import { Action, ThunkDispatch } from '@reduxjs/toolkit';
import rootReducer from './rootReducer';

export type RootState = ReturnType<typeof rootReducer>;
export type AppDispatch = ThunkDispatch<RootState, any, Action>;

import { createSlice, createAsyncThunk, PayloadAction } from '@reduxjs/toolkit';
import api from "@/shared/api/api";
import { Customer } from "@repo/shared";

const API_URL = "/customers";

// Get token from state
const getConfig = (token: string) => ({
  headers: {
    Authorization: `Bearer ${token}`,
  },
});

interface CustomerState {
  customers: Customer[];
  customer: Customer | null;
  transactions: any[]; // Define a stricter type if available, e.g., Transaction[]
  isLoading: boolean;
  isSuccess: boolean;
  isError: boolean;
  message: string | any;
}

const initialState: CustomerState = {
  customers: [],
  customer: null,
  transactions: [],
  isLoading: false,
  isSuccess: false,
  isError: false,
  message: '',
};

// Get all customers
export const getAllCustomers = createAsyncThunk(
  'customers/getAll',
  async (_, thunkAPI) => {
    try {
      const state = thunkAPI.getState() as any;
      const token = state.auth.user?.token;
      if (!token) return thunkAPI.rejectWithValue("Not authenticated");
      const response = await api.get(API_URL, getConfig(token));
      return response.data;
    } catch (error: any) {
      const message =
        (error.response && error.response.data && error.response.data.message) ||
        error.message ||
        error.toString();
      return thunkAPI.rejectWithValue(message);
    }
  }
);

// Get customer by ID
export const getCustomerById = createAsyncThunk(
  'customers/getById',
  async (id: string, thunkAPI) => {
    try {
      const state = thunkAPI.getState() as any;
      const token = state.auth.user?.token;
      if (!token) return thunkAPI.rejectWithValue("Not authenticated");
      const response = await api.get(`${API_URL}/${id}`, getConfig(token));
      return response.data;
    } catch (error: any) {
      const message =
        (error.response && error.response.data && error.response.data.message) ||
        error.message ||
        error.toString();
      return thunkAPI.rejectWithValue(message);
    }
  }
);

// Add customer
export const addCustomer = createAsyncThunk(
