    updateChequeStatus,
    setTransactions,
    setCheques,
    setDailyRecords,
    addDailyRecord,
    updateDailyRecord,
    deleteDailyRecord,
    setDailyRecordSynced
} = financeSlice.actions;
export default financeSlice.reducer;

