    async (payload, thunkAPI) => {
        try {
            const response = await httpClient.post(endpoints.auth.resetPassword, payload);
            return response;
        } catch (error: any) {
            const message =
                (error.response && error.response.data && error.response.data.message) ||
                error.message ||
                error.toString();
            return thunkAPI.rejectWithValue(message);
        }
    }
);

