import { useEffect } from 'react';

export const useResetPasswordForm = (email: string, token: string) => {
    const { dispatch, isLoading, reset } = useAuthActions();

    const form = useForm<ResetPasswordInput>({
        resolver: zodResolver(resetPasswordSchema),
        defaultValues: {
            password: '',
            confirmPassword: '',
        },
    });

    const onSubmit = (data: ResetPasswordInput) => {
        dispatch(performPasswordReset({ token, email, password: data.password }));
    };

    useEffect(() => {
        return () => {
            reset();
        };
    }, []);

    return {
        form,
        onSubmit: form.handleSubmit(onSubmit),
        isLoading,
    };
};

import { logger } from '@/shared/lib/logger';
import { useState, useEffect } from 'react';
import { useSelector } from 'react-redux';
import api from "@/shared/api/api";
import { RootState } from "@/app/store/store";

export interface ExpenseSubCategory {
    id: string;
    name: string;
    description?: string;
}

export interface ExpenseCategory {
    id: string;
    name: string;
    description?: string;
    monthly_budget: number;
    approval_required: boolean;
    is_cash_allowed: boolean;
    is_active: boolean;
    gst_eligible: boolean;
    subcategories?: ExpenseSubCategory[];
}

interface AuthState {
    user: any;
    isLoading: boolean;
    isSuccess: boolean;
    isError: boolean;
    message: string;
}

export const useExpenseCategories = () => {
    const { user } = useSelector((state: RootState & { auth: AuthState }) => state.auth);
    const [categories, setCategories] = useState<ExpenseCategory[]>([]);
    const [loading, setLoading] = useState<boolean>(true);
    const [error, setError] = useState<string | null>(null);

    const fetchCategories = async () => {
        try {
            setLoading(true);
            const token = localStorage.getItem('token');
            const response = await api.get('/expense-categories', {
                headers: { Authorization: `Bearer ${token}` }
            });
            setCategories(response.data?.categories || response.data || []);
            setError(null);
        } catch (err: any) {
            logger.error('Error fetching expense categories:', err);
            setError(err.message);
            setCategories([]);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        if (user) {
            fetchCategories();
        }
    }, [user]);

    const upsertCategory = async (category: Partial<ExpenseCategory>) => {
        try {
            const token = localStorage.getItem('token');
            if (category.id) {
                await api.put(`/expense-categories/${category.id}`, category, {
                    headers: { Authorization: `Bearer ${token}` }
                });
            } else {
                await api.post('/expense-categories', category, {
                    headers: { Authorization: `Bearer ${token}` }
                });
            }
            await fetchCategories();
        } catch (err: any) {
            logger.error('Error upserting category:', err);
            throw err;
        }
    };

    const deleteCategory = async (id: string) => {
        try {
            const token = localStorage.getItem('token');
            await api.delete(`/expense-categories/${id}`, {
                headers: { Authorization: `Bearer ${token}` }
            });
            await fetchCategories();
        } catch (err: any) {
            logger.error('Error deleting category:', err);
            throw err;
        }
    };

    return { categories, loading, error, upsertCategory, deleteCategory, refetch: fetchCategories };
};

import { logger } from '@/shared/lib/logger';
import { useState, useEffect } from 'react';
import { useSelector } from 'react-redux';
import api from "@/shared/api/api";
import { RootState } from "@/app/store/store";

export interface ExpenseReportStats {
    total_expense: number;
    report_period: string;
    by_category: { category: string; amount: number; percentage: number; type?: string }[];
    by_branch: { branch: string; amount: number; percentage: number; risk: 'HIGH' | 'LOW' | 'MEDIUM' }[];
    by_payment_mode: { mode: string; amount: number; percentage: number }[];
    audit_flags: string[];
    recommendations: string[];
}

interface AuthState {
    user: any;
    isLoading: boolean;
    isSuccess: boolean;
    isError: boolean;
    message: string;
}

export const useExpenseReports = () => {
    const { user } = useSelector((state: RootState & { auth: AuthState }) => state.auth);
    const [report, setReport] = useState<ExpenseReportStats | null>(null);
    const [loading, setLoading] = useState<boolean>(true);
    const [error, setError] = useState<string | null>(null);

    const fetchReport = async (startDate?: string, endDate?: string) => {
        try {
            setLoading(true);
            const token = localStorage.getItem('token');
            let url = '/expense-reports';
            if (startDate || endDate) {
                const params = new URLSearchParams();
                if (startDate) params.append('startDate', startDate);
                if (endDate) params.append('endDate', endDate);
                url += `?${params.toString()}`;
            }
            const response = await api.get(url, {
                headers: { Authorization: `Bearer ${token}` }
            });
            setReport(response.data);
            setError(null);
        } catch (err: any) {
            logger.error('Error fetching expense reports:', err);
            setError(err.message);
            // Return empty report structure
            setReport({
                report_period: new Date().toLocaleString('default', { month: 'long', year: 'numeric' }),
                total_expense: 0,
                by_category: [],
                by_branch: [],
                by_payment_mode: [],
                audit_flags: [],
                recommendations: ['Add expenses to generate insights'],
            });
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        if (user) {
            fetchReport();
        }
    }, [user]);

    return { report, loading, error, refetch: fetchReport };
};

