import api from '@/shared/api/api';

export interface GoogleBusinessProfileData {
    businessName: string;
    address: string;
    phone: string;
    email: string;
    website: string;
    category: string;
    description: string;
    verified: boolean;
    insights: {
        views: number;
        calls: number;
        directions: number;
        websiteClicks: number;
    };
    completeness: number;
    isConnected: boolean;
    reviews: GoogleReview[];
    posts: GooglePost[];
    photos?: GooglePhoto[];
    hours?: Record<string, { open: string; close: string; closed: boolean }>;
}

export interface GoogleReview {
    _id?: string;
    reviewer: string;
    rating: number;
    comment: string;
    date: string;
    reply?: string;
}

export interface GooglePost {
    content: string;
    type: 'UPDATE' | 'OFFER' | 'EVENT';
    imageUrl?: string;
    date: string;
    views: number;
    clicks: number;
}

export interface GooglePhoto {
    url: string;
    type: string;
}

export const googleBusinessService = {
    async getProfile(): Promise<GoogleBusinessProfileData> {
        const res = await api.get('/api/google-business/profile');
        return res.data;
    },

    async updateProfile(data: Partial<GoogleBusinessProfileData> & { hours?: any }): Promise<void> {
        await api.put('/api/google-business/profile', data);
    },

    async syncProfile(): Promise<GoogleBusinessProfileData | null> {
        const res = await api.post('/api/google-business/sync');
        return res.data;
    },

    async replyToReview(reviewId: string, reply: string): Promise<void> {
        await api.post(`/api/google-business/reviews/${reviewId}/reply`, { reply });
    },

    async createPost(data: { content: string; type: string; imageUrl?: string }): Promise<GooglePost> {
        const res = await api.post('/api/google-business/posts', data);
        return res.data;
    }
};

import { useState } from 'react';
import { useDispatch } from 'react-redux';
import { AppDispatch } from "@/app/store/store";
import { addItem as addProduct, updateItem as editProduct } from "@/entities/inventory/model/inventorySlice";
import { Product } from "@repo/shared";
import { ProductFormRow } from './useInventoryForm';
import { Sector, BranchId } from "@repo/shared";

interface UseInventoryActionsProps {
    products: Product[];
    currentSector: Sector;
    currentBranch: string;
    imagePreview: string | null;
    resetForm: () => void;
    displayedProductsLength: number;
}

export const useInventoryActions = ({
    products,
    currentSector,
    currentBranch,
    imagePreview,
    resetForm,
    displayedProductsLength
}: UseInventoryActionsProps) => {
    const dispatch = useDispatch<AppDispatch>();
    const [selectedProductIds, setSelectedProductIds] = useState<Set<string>>(new Set());
    const [isPrintMode, setIsPrintMode] = useState(false);
    const [isPrintModalOpen, setIsPrintModalOpen] = useState(false);

    const handleSave = (bulkFormData: ProductFormRow[]) => {
        const validRows = bulkFormData.filter(row => row.name && row.cost);

        validRows.forEach(row => {
            const cost = parseFloat(row.cost) || 0;
            const price = parseFloat(row.price) || (cost * 1.25);
            const stock = parseFloat(row.stock) || 0;

            const productData = {
                name: row.name,
                sku: row.sku,
                price: price,
                cost: cost,
                stock: stock,
                category: row.category || 'General',
                unit: row.unit || 'Piece',
                productType: row.productType || 'Standard',
                brand: row.brand || 'Generic',
                sector: currentSector,
                branchId: (row.branch || currentBranch) as BranchId,
                image: imagePreview || row.image || undefined,
                subCategory: row.subCategory,
                size: row.size,
                color: row.color,
                material: row.material,
                location: row.location,
                discount: row.discount ? parseFloat(row.discount) : 0,
                expiryDate: row.expiryDate,
                warrantyPeriod: row.warrantyPeriod,
                gstPercentage: parseFloat(row.gstPercentage || '0'),
                barcode: !row.id ? (row.sku || Math.random().toString().slice(2, 14)) : undefined
            };

            if (row.id) {
                dispatch(editProduct({
                    id: row.id,
                    itemData: {
                        ...productData,
                        barcode: products.find(p => p.id === row.id)?.barcode
                    }
                }));
            } else {
                dispatch(addProduct({
                    ...productData,
                    id: Math.random().toString(36).substr(2, 9),
                }));
            }
        });
        resetForm();
    };

    const toggleProductSelection = (id: string) => {
        const newSet = new Set(selectedProductIds);
        if (newSet.has(id)) newSet.delete(id);
        else newSet.add(id);
        setSelectedProductIds(newSet);
    };

    const handlePrintLabels = () => {
        if (selectedProductIds.size === 0) {
            alert("Please select at least one product to print labels.");
            return;
        }
        setIsPrintModalOpen(true);
    };

    const selectAll = (displayedProducts: Product[]) => {
        if (selectedProductIds.size === displayedProducts.length) {
            setSelectedProductIds(new Set());
        } else {
            setSelectedProductIds(new Set(displayedProducts.map(p => p.id)));
        }
    };

    const clearSelection = () => {
        setSelectedProductIds(new Set());
    };

    return {
        selectedProductIds,
        isPrintMode, setIsPrintMode,
        isPrintModalOpen, setIsPrintModalOpen,
        handleSave,
        toggleProductSelection,
        handlePrintLabels,
        selectAll,
        clearSelection
    };
};

import React, { useState } from 'react';
import { Product } from "@repo/shared";

export interface ProductFormRow {
    id?: string;
    name: string;
    sku: string;
    price: string;
    cost: string;
    stock: string;
    category: string;
    productType: string;
    branch: string;
    brand: string;
    unit: string;
    subCategory: string;
    size: string;
    color: string;
    material: string;
    location: string;
    discount: string;
    image?: string;
    expiryDate?: string;
    warrantyPeriod?: string;
    gstPercentage: string;
}

export const defaultRow: ProductFormRow = {
    name: '', sku: '', price: '', cost: '', stock: '', category: '', productType: '', branch: 'Alpha', brand: '', unit: 'Piece',
    subCategory: '', size: '', color: '', material: '', location: '', discount: '', expiryDate: '', warrantyPeriod: '',
    gstPercentage: '18'
};

export const useInventoryForm = (currentBranch: string) => {
    const [isFormOpen, setIsFormOpen] = useState(false);
    const [editingId, setEditingId] = useState<string | null>(null);
    const [bulkFormData, setBulkFormData] = useState<ProductFormRow[]>([defaultRow]);
    const [imagePreview, setImagePreview] = useState<string | null>(null);

    const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) {
            const reader = new FileReader();
            reader.onloadend = () => {
                setImagePreview(reader.result as string);
            };
            reader.readAsDataURL(file);
        }
    };

    const handleEdit = (product: Product) => {
        const p = product as any;
        setBulkFormData([{
            id: p.id,
            name: p.name,
            sku: p.sku,
            price: p.price.toString(),
            cost: p.cost.toString(),
            stock: p.stock.toString(),
            category: p.category,
            subCategory: p.subCategory || '',
            size: p.size || '',
            color: p.color || '',
            material: p.material || '',
            location: p.location || '',
            discount: p.discount?.toString() || '',
            productType: p.productType || '',
            branch: p.branchId || '',
            brand: p.brand || '',
            unit: p.unit || 'Piece',
            image: p.image,
            expiryDate: p.expiryDate || '',
            gstPercentage: p.gstPercentage?.toString() || '18',
            warrantyPeriod: p.warrantyPeriod || ''
        }]);
        setImagePreview(product.image || null);
        setIsFormOpen(true);
        window.scrollTo({ top: 0, behavior: 'smooth' });
    };

    const resetForm = () => {
        setEditingId(null);
        setBulkFormData([{
            ...defaultRow,
            branch: currentBranch === 'All' ? '' : currentBranch,
        }]);
        setImagePreview(null);
        setIsFormOpen(false);
    };

    const handleRowChange = (index: number, field: keyof ProductFormRow, value: string) => {
        const updated = [...bulkFormData];
        updated[index] = { ...updated[index], [field]: value };

        if (!updated[index].id && field === 'brand' && value) {
            const prefix = value.substring(0, 3).toUpperCase();
            const timestamp = new Date().toISOString().replace(/[-:T.]/g, '').slice(0, 14);
            updated[index].sku = `${prefix}-${timestamp}-${index}`;
        }

        setBulkFormData(updated);

        const isLastRow = index === updated.length - 1;
        if (isLastRow) {
            const row = updated[index];
            const isComplete = row.name && row.brand && row.category && row.productType && row.stock && row.cost && row.price;
            if (isComplete) {
                setBulkFormData(prev => [...prev, { ...defaultRow, branch: currentBranch === 'All' ? '' : currentBranch }]);
            }
        }
    };

    const addRow = () => {
        setBulkFormData([...bulkFormData, { ...defaultRow, branch: currentBranch === 'All' ? '' : currentBranch }]);
    };

    const copyRow = (index: number) => {
        const rowToCopy = { ...bulkFormData[index] };
        if (!rowToCopy.id && rowToCopy.brand) {
            const prefix = rowToCopy.brand.substring(0, 3).toUpperCase();
            const timestamp = new Date().toISOString().replace(/[-:T.]/g, '').slice(0, 14);
            rowToCopy.sku = `${prefix}-${timestamp}-${bulkFormData.length}`;
        } else {
            rowToCopy.sku = '';
        }
        delete rowToCopy.id;
        setBulkFormData([...bulkFormData, rowToCopy]);
    };

    const removeRow = (index: number) => {
        if (bulkFormData.length === 1) return;
        const updated = [...bulkFormData];
        updated.splice(index, 1);
        setBulkFormData(updated);
    };

    return {
        isFormOpen, setIsFormOpen,
        editingId, setEditingId,
        bulkFormData, setBulkFormData,
        imagePreview, setImagePreview,
        handleImageUpload,
        handleEdit,
        resetForm,
        handleRowChange,
        addRow,
        copyRow,
        removeRow
    };
};

