export interface POSLogic {
    user: any;
    currentSector: string;
    currentBranch: string;
    sessions: any[];
    activeSessionIndex: number;
    activeSession: any;
    cart: any[];
    activeCustomer: any;
    customers: any[];
    heldBills: any[];
