import React, { useState } from 'react';

interface Column {
    key: string;
    label: string;
    sortable?: boolean;
    render?: (value: any, row: any) => React.ReactNode;
}

interface DataTableProps {
    columns: Column[];
    data: any[];
    onRowClick?: ((row: any) => void) | null;
    emptyMessage?: string;
    isLoading?: boolean;
}

const DataTable: React.FC<DataTableProps> = ({
    columns,
    data,
    onRowClick = null,
    emptyMessage = 'No data available',
    isLoading = false
}) => {
    const [sortColumn, setSortColumn] = useState<string | null>(null);
    const [sortDirection, setSortDirection] = useState<'asc' | 'desc'>('asc');

    const handleSort = (columnKey: string) => {
        if (sortColumn === columnKey) {
            setSortDirection(sortDirection === 'asc' ? 'desc' : 'asc');
        } else {
            setSortColumn(columnKey);
            setSortDirection('asc');
        }
    };

    const sortedData = [...data].sort((a, b) => {
        if (!sortColumn) return 0;

        const aValue = a[sortColumn];
        const bValue = b[sortColumn];

        if (aValue < bValue) return sortDirection === 'asc' ? -1 : 1;
        if (aValue > bValue) return sortDirection === 'asc' ? 1 : -1;
        return 0;
    });

    if (isLoading) {
        return (
            <div className="bg-white dark:bg-[rgb(var(--color-card))] rounded-xl shadow-sm dark:shadow-lg overflow-hidden border dark:border-[rgb(var(--color-border))]">
                <div className="flex justify-center items-center py-12">
                    <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-indigo-600 dark:border-[rgb(var(--color-primary))]"></div>
                </div>
            </div>
        );
    }

    if (data.length === 0) {
        return (
            <div className="bg-white dark:bg-[rgb(var(--color-card))] rounded-xl shadow-sm dark:shadow-lg overflow-hidden border dark:border-[rgb(var(--color-border))]">
                <div className="text-center py-12">
                    <svg className="w-16 h-16 text-gray-400 dark:text-[rgb(var(--color-text-muted))] mx-auto mb-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M20 13V6a2 2 0 00-2-2H6a2 2 0 00-2 2v7m16 0v5a2 2 0 01-2 2H6a2 2 0 01-2-2v-5m16 0h-2.586a1 1 0 00-.707.293l-2.414 2.414a1 1 0 01-.707.293h-3.172a1 1 0 01-.707-.293l-2.414-2.414A1 1 0 006.586 13H4" />
                    </svg>
                    <p className="text-gray-500 dark:text-[rgb(var(--color-text-secondary))] text-lg">{emptyMessage}</p>
                </div>
            </div>
        );
    }

    return (
        <div className="bg-white dark:bg-[rgb(var(--color-card))] rounded-xl shadow-sm dark:shadow-lg overflow-hidden border dark:border-[rgb(var(--color-border))]">
            <div className="overflow-x-auto">
                <table className="w-full">
                    <thead className="bg-gray-50 dark:bg-[rgb(var(--color-table-header))] border-b border-gray-200 dark:border-[rgb(var(--color-border))]">
                        <tr>
                            {columns.map((column) => (
                                <th
                                    key={column.key}
                                    onClick={() => column.sortable && handleSort(column.key)}
                                    className={`px-6 py-3 text-left text-xs font-medium text-gray-500 dark:text-[rgb(var(--color-text-secondary))] uppercase ${column.sortable ? 'cursor-pointer hover:bg-gray-100 dark:hover:bg-[rgb(var(--color-input))]' : ''
                                        }`}
                                >
                                    <div className="flex items-center space-x-1">
                                        <span>{column.label}</span>
                                        {column.sortable && sortColumn === column.key && (
                                            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                                <path
                                                    strokeLinecap="round"
                                                    strokeLinejoin="round"
                                                    strokeWidth={2}
                                                    d={sortDirection === 'asc' ? "M5 15l7-7 7 7" : "M19 9l-7 7-7-7"}
                                                />
                                            </svg>
                                        )}
                                    </div>
                                </th>
                            ))}
                        </tr>
                    </thead>
                    <tbody className="bg-white dark:bg-[rgb(var(--color-table-row))] divide-y divide-gray-200 dark:divide-[rgb(var(--color-border))]">
                        {sortedData.map((row, rowIndex) => (
                            <tr
                                key={rowIndex}
                                onClick={() => onRowClick && onRowClick(row)}
                                className={`${onRowClick ? 'cursor-pointer hover:bg-gray-50 dark:hover:bg-[rgb(var(--color-input))]' : ''} text-gray-900 dark:text-[rgb(var(--color-text))]`}
                            >
                                {columns.map((column) => (
                                    <td key={column.key} className="px-6 py-4 whitespace-nowrap">
                                        {column.render ? column.render(row[column.key], row) : row[column.key]}
                                    </td>
                                ))}
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
        </div>
    );
};

export default DataTable;

import { logger } from '@/shared/lib/logger';
import React, { useState, useEffect } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import api from "@/shared/api/api";
import Modal from '../../components/shared/Overlay/Modal';
import { RootState, AppDispatch } from "@/app/store/store";
import { toast } from 'react-toastify';

interface BusinessSetupModalProps {
    isOpen: boolean;
    onClose: () => void;
}

interface Sector {
    id: string;
    name: string;
}

interface BusinessType {
    id: string;
    name: string;
}

interface BusinessSetupData {
    category: string;
    businessType: string;
    businessName: string;
    phone: string;
}

interface ApiResponse<T> {
    success: boolean;
    data: T;
    message?: string;
}

interface FormData {
    category: string;
    businessType: string;
    businessName: string;
    phone: string;
}

const BusinessSetupModal: React.FC<BusinessSetupModalProps> = ({ isOpen, onClose }) => {
    const dispatch = useDispatch<AppDispatch>();
    const { user } = useSelector((state: RootState) => state.auth);
    const [isLoading, setIsLoading] = useState<boolean>(false);

    const [formData, setFormData] = useState<FormData>({
        category: '', // ID
        businessType: '', // ID
        businessName: '',
        phone: '',
    });

    const [sectors, setSectors] = useState<Sector[]>([]);
    const [businessTypes, setBusinessTypes] = useState<BusinessType[]>([]);

    useEffect(() => {
        const fetchAllData = async () => {
            if (isOpen) {
                setIsLoading(true);
                try {
                    // 1. Fetch Setup Status first
                    const setupResponse = await api.get<ApiResponse<BusinessSetupData>>('/business/setup');
                    if (setupResponse.data && setupResponse.data.success) {
                        const setup = setupResponse.data.data;
                        setFormData({
                            category: setup.category || '',
                            businessType: setup.businessType || '',
                            businessName: setup.businessName || user?.shopName || '',
                            phone: setup.phone || user?.phone || '',
                        });

                        // 2. Fetch Master Data (Sectors and Types) after setup check
                        const [sectorsRes, typesRes] = await Promise.all([
                            api.get<ApiResponse<Sector[]>>('/business/sectors'),
                            api.get<ApiResponse<BusinessType[]>>('/business/types')
                        ]);

                        if (sectorsRes.data?.success) setSectors(sectorsRes.data.data);
                        if (typesRes.data?.success) setBusinessTypes(typesRes.data.data);
                    }
                } catch (error) {
                    logger.error("Failed to fetch setup or master data", error);
                    // Fallback to basic user data
                    if (user) {
                        setFormData(prev => ({
                            ...prev,
                            businessName: user.shopName || '',
                            phone: user.phone || ''
                        }));
                    }
                } finally {
                    setIsLoading(false);
                }
            }
        };

        fetchAllData();
    }, [isOpen, user]);

    const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
        const { name, value } = e.target;
        setFormData(prev => ({ ...prev, [name]: value }));
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!formData.category) {
            toast.error('Please select a business category');
            return;
        }
        if (!formData.businessType) {
            toast.error('Please select a business type');
            return;
        }

        setIsLoading(true);
        try {
            const response = await api.post<ApiResponse<any>>('/business/setup', formData);
            if (response.data && response.data.success) {
                toast.success('Business setup completed!');
                onClose();
            } else {
                toast.error('Failed to complete business setup');
            }
        } catch (error) {
            toast.error('Failed to complete business setup');
            logger.error(error);
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <Modal
            isOpen={isOpen}
            onClose={onClose}
            title="Complete Your Business Profile"
            showCloseButton={false} // Force user to complete
            size="md"
        >
            <div className="space-y-4">
                <p className="text-secondary text-sm">
                    To give you the best experience, please tell us a bit more about your business.
                </p>

                <form onSubmit={handleSubmit} className="space-y-4">
                    <div>
                        <label htmlFor="businessName" className="block text-sm font-medium text-secondary mb-1">
                            Business Name
                        </label>
                        <input
                            type="text"
                            id="businessName"
                            name="businessName"
                            value={formData.businessName}
                            onChange={handleChange}
                            className="w-full px-3 py-2 border border-default rounded-lg focus:ring-2 focus:ring-primary-500 focus:border-transparent"
                            placeholder="Enter your business name"
                            required
                        />
                    </div>

                    <div>
                        <label htmlFor="businessType" className="block text-sm font-medium text-secondary mb-1">
                            Business Type
                        </label>
                        <select
                            id="businessType"
                            name="businessType"
                            value={formData.businessType}
                            onChange={handleChange}
                            className="w-full px-3 py-2 border border-default rounded-lg focus:ring-2 focus:ring-primary-500 focus:border-transparent"
                            required
                        >
                            <option value="">Select a type</option>
                            {businessTypes.map((type) => (
                                <option key={type.id} value={type.id}>
                                    {type.name}
                                </option>
                            ))}
                        </select>
                    </div>

                    <div>
                        <label htmlFor="category" className="block text-sm font-medium text-secondary mb-1">
                            Business Category (Sector)
                        </label>
                        <select
                            id="category"
                            name="category"
                            value={formData.category}
                            onChange={handleChange}
                            className="w-full px-3 py-2 border border-default rounded-lg focus:ring-2 focus:ring-primary-500 focus:border-transparent"
                            required
                        >
                            <option value="">Select a category</option>
                            {sectors.map((sector) => (
                                <option key={sector.id} value={sector.id}>
                                    {sector.name}
                                </option>
                            ))}
                        </select>
                    </div>

                    <div>
                        <label htmlFor="phone" className="block text-sm font-medium text-secondary mb-1">
                            Phone Number
                        </label>
                        <input
                            type="tel"
                            id="phone"
                            name="phone"
                            value={formData.phone}
                            onChange={handleChange}
                            className="w-full px-3 py-2 border border-default rounded-lg focus:ring-2 focus:ring-primary-500 focus:border-transparent"
                            placeholder="Enter phone number"
                        />
                    </div>

                    <div className="pt-4 flex justify-end">
                        <button
                            type="submit"
                            disabled={isLoading}
                            className="px-6 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 font-medium transition disabled:opacity-50"
                        >
                            {isLoading ? 'Saving...' : 'Save & Continue'}
                        </button>
                    </div>
                </form>
            </div>
        </Modal>
    );
};

