import { toast } from 'react-toastify';

interface Template {
    id: number;
    name: string;
    content: string;
}

interface CustomerGroup {
    id: number;
    name: string;
    count: number;
    selected: boolean;
}

interface Campaign {
    id: number;
    name: string;
    sent: number;
    delivered: number;
    read: number;
    date: string;
    status: 'completed' | 'scheduled';
}

interface FormData {
    message: string;
    scheduleDate: string;
    scheduleTime: string;
    attachments: any[];
}

const WhatsAppMarketing: React.FC = () => {
    const [showBroadcastForm, setShowBroadcastForm] = useState<boolean>(false);
