                                </div>
                            </div>
                        </div>

                        {/* Quick Tips Tooltip */}
                        <div className="bg-gradient-to-br from-indigo-900 to-emerald-900 rounded-[2.5rem] p-8 text-white shadow-2xl relative overflow-hidden group">
