    // Mock Data for UI Visualization
    const [stats, setStats] = useState({
        matched: 124,
        mismatch: 5,
        missingGSTR: 12,
        missingSystem: 3
    });

    const [activeTab, setActiveTab] = useState<'MATCHED' | 'MISMATCH' | 'MISSING'>('MISMATCH');

    const handleSimulateReconcile = () => {
        setIsReconciling(true);
        setTimeout(() => {
