                                <p className="font-mono text-xs font-bold text-slate-700 dark:text-slate-300">INV-2024-00{i}</p>
                            </div>
                            <div>
                                <p className="text-[10px] font-black text-slate-400 uppercase tracking-wider mb-0.5">Amount Diff</p>
