                                    i === 1 ? 'bg-rose-100 text-rose-700' : i === 2 ? 'bg-emerald-100 text-emerald-700' : 'bg-amber-100 text-amber-700'
                                }`}>
                                    {i === 1 ? 'Tax Mismatch' : i === 2 ? 'Fully Matched' : 'Partial Match'}
