                                    Recommended: Review staff login logs for the 14:00 - 15:00 window.
                                </p>
                                <button className="w-full py-3 bg-primary text-white rounded-xl font-black text-[11px] uppercase tracking-widest shadow-xl shadow-primary/20 hover:scale-[1.02] transition-all active:scale-95">
                                    Lockdown Account 004
                                </button>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </Layout >
    );
};

export default CashBankIntelligence;

