import React, { useState, useEffect } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { useNavigate } from 'react-router-dom';
import Layout from "@/shared/ui/Layout";
import PageHeader from "@/shared/ui/Layout/PageHeader";
import CashBankInput from './components/CashBankInput';
import CashBankFormSection from './components/CashBankFormSection';
import CashBankHero from './components/CashBankHero';
import {
    getTransactions,
    getCashBankPosition,
    getAccounts,
    createCashTransaction,
    reset
} from "@/entities/finance/model/cashbankSlice";
import { RootState, AppDispatch } from "@/app/store/store";
import { Transaction } from './types';
import { toast } from 'react-toastify';
import {
    Plus,
    Minus,
    FileText,
    Calendar,
    IndianRupee,
    Navigation,
    ArrowUpRight,
    ArrowDownLeft,
    Wallet,
    History,
    X,
    Activity,
    Zap
} from 'lucide-react';

const CashInHand: React.FC = () => {
    const navigate = useNavigate();
    const dispatch = useDispatch<AppDispatch>();

    const [showAddTransaction, setShowAddTransaction] = useState(false);
    const [filterType, setFilterType] = useState<'all' | 'in' | 'out'>('all');
    const [dateRange, setDateRange] = useState({ from: '', to: '' });

    const { transactions, position, accounts, isLoading, isSuccess, isError, message } = useSelector((state: RootState) => state.cashbank);

    const [formData, setFormData] = useState<Partial<Transaction>>({
        date: new Date().toISOString().split('T')[0],
        description: '',
        amount: 0,
        type: 'in',
        toAccount: '',
        fromAccount: '',
        reference: ''
    });

    useEffect(() => {
        dispatch(getTransactions('cash'));
        dispatch(getCashBankPosition());
        dispatch(getAccounts());
    }, [dispatch]);

    useEffect(() => {
        if (isSuccess && showAddTransaction) {
            toast.success('Capital re-indexed successfully!');
            setShowAddTransaction(false);
            setFormData({
                date: new Date().toISOString().split('T')[0],
                description: '',
                amount: 0,
                type: 'in',
                toAccount: '',
                fromAccount: '',
                reference: ''
            });
            dispatch(getTransactions('cash'));
            dispatch(getCashBankPosition());
            dispatch(reset());
        }
        if (isError && message) {
            toast.error(message);
            dispatch(reset());
        }
    }, [isSuccess, isError, message, dispatch, showAddTransaction]);

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        dispatch(createCashTransaction(formData));
    };

    const filteredTransactions = transactions.filter(t => {
        const matchesType = filterType === 'all' || t.type === filterType;
        const txnDate = t.date.split('T')[0];
        const matchesDate = (!dateRange.from || txnDate >= dateRange.from) && (!dateRange.to || txnDate <= dateRange.to);
        return matchesType && matchesDate;
    });

    const categories = [
        { group: 'Operational Inflow', items: ['Sales', 'Customer Payment', 'Service Fee'] },
        { group: 'Operational Outflow', items: ['Office Rent', 'Electricity', 'Water Bill', 'Internet', 'Stationery', 'Tea/Snacks', 'Other Expense'] },
        { group: 'Institutional Units', items: accounts.map(a => ({ value: a._id, label: `Vault: ${a.bankName}` })) }
    ];

    return (
        <Layout>
            <PageHeader
                title="Vault Surveillance"
                description="High-fidelity monitoring of physical capital and direct fiscal clearing"
                breadcrumbs={[{ label: 'Treasury', link: '/cashbank/position' }, { label: 'Vault' }]}
                actions={
                    <div className="flex gap-2">
                        <button
                            onClick={() => { setFormData({ ...formData, type: 'in', toAccount: 'cash', fromAccount: '' }); setShowAddTransaction(true); }}
                            className="px-6 py-2.5 bg-emerald-600 text-white rounded-xl text-[10px] font-black uppercase tracking-widest shadow-xl shadow-emerald-100 dark:shadow-none hover:bg-emerald-700 transition-all flex items-center gap-2"
                        >
                            <Plus className="w-4 h-4" /> Capital Inflow
                        </button>
                        <button
                            onClick={() => { setFormData({ ...formData, type: 'out', fromAccount: 'cash', toAccount: '' }); setShowAddTransaction(true); }}
                            className="px-6 py-2.5 bg-rose-600 text-white rounded-xl text-[10px] font-black uppercase tracking-widest shadow-xl shadow-rose-100 dark:shadow-none hover:bg-rose-700 transition-all flex items-center gap-2"
                        >
                            <Minus className="w-4 h-4" /> Capital Outflow
                        </button>
                    </div>
                }
            />

            <CashBankHero
                title="Live Vault Liquidity"
                value={`₹${(position?.cashInHand || 0).toLocaleString('en-IN')}`}
                icon={Wallet}
                stats={
                    <>
                        <div className="px-4 py-2 bg-white/10 rounded-2xl backdrop-blur-md border border-white/20 text-[10px] font-black uppercase tracking-widest flex items-center gap-2">
                            <span className={`w-2 h-2 rounded-full ${(position?.cashInHand || 0) > 0 ? 'bg-emerald-400 animate-pulse' : 'bg-rose-400'}`}></span>
                            Operational Status: {(position?.cashInHand || 0) > 0 ? 'Healthy' : 'Depleted'}
                        </div>
                        <button onClick={() => navigate('/cashbank/ledger/cash')} className="text-[10px] font-black uppercase tracking-widest text-indigo-200 hover:text-white transition-all underline underline-offset-8">Audit Ledger</button>
                    </>
                }
                extraActions={
                    <div className="grid grid-cols-2 gap-4">
                        <div className="bg-white/5 border border-white/10 p-6 rounded-[2rem] backdrop-blur-sm">
                            <p className="text-[10px] font-black text-indigo-300 uppercase tracking-widest mb-1 text-center">Aggregate Inflow</p>
                            <p className="text-xl font-black text-emerald-400 text-center">₹{transactions.filter(t => t.type === 'in' || (t.type === 'transfer' && t.toAccount === 'cash')).reduce((sum, t) => sum + t.amount, 0).toLocaleString('en-IN')}</p>
                        </div>
                        <div className="bg-white/5 border border-white/10 p-6 rounded-[2rem] backdrop-blur-sm">
                            <p className="text-[10px] font-black text-indigo-300 uppercase tracking-widest mb-1 text-center">Aggregate Outflow</p>
                            <p className="text-xl font-black text-rose-400 text-center">₹{transactions.filter(t => t.type === 'out' || (t.type === 'transfer' && t.fromAccount === 'cash')).reduce((sum, t) => sum + t.amount, 0).toLocaleString('en-IN')}</p>
                        </div>
                    </div>
                }
            />

            {/* Terminal Controls */}
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-8">
                <div className="flex items-center gap-1.5 p-1.5 bg-slate-100 dark:bg-slate-800 rounded-2xl w-fit">
                    {(['all', 'in', 'out'] as const).map(type => (
                        <button
                            key={type}
                            onClick={() => setFilterType(type)}
                            className={`px-6 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${filterType === type
                                ? 'bg-white dark:bg-slate-700 text-indigo-600 shadow-md scale-105'
                                : 'text-slate-400 hover:text-slate-600 dark:hover:text-slate-300'}`}
                        >
                            {type === 'all' ? 'All Channels' : type === 'in' ? 'Inflows' : 'Outflows'}
                        </button>
                    ))}
                </div>
                <div className="flex items-center gap-3 bg-white dark:bg-slate-900 px-4 py-2 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm">
                    <Calendar className="w-4 h-4 text-slate-400" />
                    <input
                        type="date"
                        value={dateRange.from}
                        onChange={(e) => setDateRange({ ...dateRange, from: e.target.value })}
                        className="bg-transparent text-xs font-bold text-slate-600 dark:text-slate-400 focus:outline-none"
                    />
                    <div className="w-1 h-1 bg-slate-300 rounded-full"></div>
                    <input
                        type="date"
                        value={dateRange.to}
                        onChange={(e) => setDateRange({ ...dateRange, to: e.target.value })}
                        className="bg-transparent text-xs font-bold text-slate-600 dark:text-slate-400 focus:outline-none"
                    />
                </div>
            </div>

            {/* Execution Terminal */}
            {showAddTransaction && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-fade-in">
                    <form onSubmit={handleSubmit} className="bg-white dark:bg-slate-900 w-full max-w-3xl rounded-[3rem] shadow-2xl border border-slate-200 dark:border-slate-800 overflow-hidden animate-slide-up">
                        <div className="p-8 bg-slate-50 dark:bg-slate-800/50 border-b border-slate-200 dark:border-slate-700 flex items-center justify-between">
                            <div>
                                <h2 className="text-xl font-black text-slate-800 dark:text-white uppercase tracking-tight">Vault Transfer Terminal</h2>
                                <p className="text-xs font-medium text-slate-400">Recording manual {formData.type === 'in' ? 'Inflow' : 'Outflow'} protocol</p>
                            </div>
                            <button type="button" onClick={() => setShowAddTransaction(false)} className="p-2 hover:bg-slate-200 dark:hover:bg-slate-700 rounded-xl transition-all">
                                <X className="w-5 h-5 text-slate-500" />
                            </button>
                        </div>

                        <div className="p-10 space-y-8">
                            <CashBankFormSection title="Clearing Matrix">
                                <CashBankInput label="Execution Date" icon={Calendar}>
                                    <input
                                        type="date"
                                        value={formData.date}
                                        onChange={(e) => setFormData({ ...formData, date: e.target.value })}
                                        className="w-full pl-11 pr-4 py-3.5 bg-slate-50 dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 rounded-2xl outline-none focus:ring-4 focus:ring-indigo-500/10 focus:border-indigo-500 transition-all font-bold text-sm"
                                        required
                                    />
                                </CashBankInput>
                                <CashBankInput label="Liquidity Volume (₹)" icon={IndianRupee}>
                                    <input
                                        type="number"
                                        value={formData.amount}
                                        onChange={(e) => setFormData({ ...formData, amount: parseFloat(e.target.value) || 0 })}
                                        className="w-full pl-11 pr-4 py-3.5 bg-slate-50 dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 rounded-2xl outline-none focus:ring-4 focus:ring-indigo-500/10 focus:border-indigo-500 transition-all font-bold text-sm"
                                        placeholder="0.00"
                                        required
                                    />
                                </CashBankInput>
                            </CashBankFormSection>

                            <CashBankFormSection title="Routing Information">
                                <CashBankInput label="Category / Origin Unit" icon={Navigation}>
                                    <select
                                        value={formData.type === 'in' ? formData.fromAccount : formData.toAccount}
                                        onChange={(e) => {
                                            if (formData.type === 'in') {
                                                setFormData({ ...formData, fromAccount: e.target.value });
                                            } else {
                                                setFormData({ ...formData, toAccount: e.target.value });
                                            }
                                        }}
                                        className="w-full pl-11 pr-4 py-3.5 bg-slate-50 dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 rounded-2xl outline-none focus:ring-4 focus:ring-indigo-500/10 focus:border-indigo-500 transition-all font-bold text-sm bg-no-repeat"
                                        required
                                    >
                                        <option value="">Select Routing Channel</option>
                                        {categories.map(group => (
                                            <optgroup key={group.group} label={group.group.toUpperCase()}>
                                                {group.items.map(item => {
                                                    const val = typeof item === 'string' ? item : item.value;
                                                    const lab = typeof item === 'string' ? item : item.label;
                                                    return (
                                                        <option key={val} value={val}>
                                                            {lab}
                                                        </option>
                                                    );
                                                })}
                                            </optgroup>
                                        ))}
                                    </select>
                                </CashBankInput>
                                <CashBankInput label="Registry Reference" icon={FileText}>
                                    <input
                                        type="text"
                                        value={formData.reference}
                                        onChange={(e) => setFormData({ ...formData, reference: e.target.value })}
                                        className="w-full pl-11 pr-4 py-3.5 bg-slate-50 dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 rounded-2xl outline-none focus:ring-4 focus:ring-indigo-500/10 focus:border-indigo-500 transition-all font-bold text-sm"
                                        placeholder="Voucher or Clearing ID"
                                    />
                                </CashBankInput>
                            </CashBankFormSection>

                            <div className="md:col-span-2">
                                <CashBankInput label="Transactional Narrative" icon={History}>
                                    <textarea
                                        value={formData.description}
                                        onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                                        rows={2}
                                        className="w-full pl-11 pr-4 py-3.5 bg-slate-50 dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 rounded-2xl outline-none focus:ring-4 focus:ring-indigo-500/10 focus:border-indigo-500 transition-all font-bold text-sm leading-relaxed"
                                        placeholder="Detailed purpose of manual clearing"
                                        required
                                    />
                                </CashBankInput>
                            </div>

                            {/* Impact Advisory */}
                            {(formData.amount || 0) > 0 && (formData.fromAccount || formData.toAccount) && (
                                <div className="bg-indigo-50 dark:bg-indigo-900/20 border border-indigo-100 dark:border-indigo-800 p-6 rounded-[2rem] flex items-center justify-between">
                                    <div className="flex items-center gap-4">
                                        <div className="p-3 bg-white dark:bg-slate-800 rounded-2xl shadow-sm">
                                            <Zap className="w-5 h-5 text-indigo-600" />
                                        </div>
                                        <div>
                                            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Anticipated Impact</p>
                                            <p className="text-xs font-bold text-indigo-900 dark:text-indigo-300">
                                                {formData.type === 'in' ? 'Depositing into Vault' : 'Withdrawing from Vault'}
                                            </p>
                                        </div>
                                    </div>
                                    <div className="text-right">
                                        <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">New Vault Index</p>
                                        <p className="text-xl font-black text-indigo-600">₹{(formData.type === 'in' ? (position?.cashInHand || 0) + (formData.amount || 0) : (position?.cashInHand || 0) - (formData.amount || 0)).toLocaleString('en-IN')}</p>
                                    </div>
                                </div>
                            )}
                        </div>

                        <div className="p-8 bg-slate-50 dark:bg-slate-800/50 border-t border-slate-200 dark:border-slate-700 flex justify-end gap-3">
                            <button type="button" onClick={() => setShowAddTransaction(false)} className="px-8 py-3.5 border border-slate-200 dark:border-slate-700 text-slate-500 rounded-2xl text-[10px] font-black uppercase tracking-widest hover:bg-white transition-all">Abort</button>
                            <button type="submit" disabled={isLoading} className={`px-10 py-3.5 rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-xl transition-all disabled:opacity-50 text-white ${formData.type === 'in' ? 'bg-emerald-600 shadow-emerald-100 dark:shadow-none hover:bg-emerald-700' : 'bg-rose-600 shadow-rose-100 dark:shadow-none hover:bg-rose-700'}`}>
                                {isLoading ? 'Committing...' : `Commit ${formData.type === 'in' ? 'Inflow' : 'Outflow'}`}
                            </button>
                        </div>
                    </form>
                </div>
            )}

            {/* Transaction Ledger Grid */}
            <div className="grid grid-cols-1 gap-4 pb-20">
                {filteredTransactions.map(t => {
                    const isIn = t.type === 'in' || (t.type === 'transfer' && t.toAccount === 'cash');
                    return (
                        <div key={t._id} className="bg-white dark:bg-slate-900 p-6 rounded-[2rem] border border-slate-200 dark:border-slate-800 shadow-sm flex items-center justify-between hover:shadow-lg hover:border-indigo-100 dark:hover:border-indigo-900 transition-all group">
                            <div className="flex items-center gap-6">
                                <div className={`w-14 h-14 rounded-2xl flex items-center justify-center transition-transform group-hover:scale-110 ${isIn ? 'bg-emerald-50 text-emerald-600 dark:bg-emerald-900/20' : 'bg-rose-50 text-rose-600 dark:bg-rose-900/20'}`}>
                                    {isIn ? <ArrowDownLeft className="w-6 h-6" /> : <ArrowUpRight className="w-6 h-6" />}
                                </div>
                                <div>
                                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2 mb-1">
                                        {new Date(t.date).toLocaleDateString('en-IN', { day: '2-digit', month: 'short', year: 'numeric' })} • {t.reference || 'NO-REF'}
                                    </p>
                                    <h4 className="text-sm font-black text-slate-800 dark:text-white uppercase tracking-tight">{t.description}</h4>
                                    <p className="text-[10px] font-bold text-slate-400 mt-1 italic">Channel: {t.type === 'transfer' ? 'Internal Transfer' : 'Direct Manual'}</p>
                                </div>
                            </div>
                            <div className="text-right">
                                <p className={`text-xl font-black ${isIn ? 'text-emerald-600' : 'text-rose-600'}`}>
                                    {isIn ? '+' : '-'} ₹{t.amount.toLocaleString('en-IN')}
                                </p>
                                <button className="p-1 px-3 bg-slate-50 dark:bg-slate-800 rounded-lg text-[9px] font-black text-slate-400 uppercase tracking-widest mt-2 hover:bg-indigo-50 dark:hover:bg-indigo-900/30 hover:text-indigo-600 transition-all">Audit Detalle</button>
                            </div>
                        </div>
                    );
                })}

                {filteredTransactions.length === 0 && (
                    <div className="py-20 bg-slate-50 dark:bg-slate-800/20 border-2 border-dashed border-slate-200 dark:border-slate-800 rounded-[3rem] text-center flex flex-col items-center">
                        <div className="w-20 h-20 bg-white dark:bg-slate-800 rounded-[2rem] shadow-xl flex items-center justify-center text-slate-200 mb-6 font-black text-4xl">
                            ?
                        </div>
                        <h4 className="text-lg font-black text-slate-800 dark:text-white uppercase tracking-tight">No Temporal Ledger Data</h4>
                        <p className="text-xs font-medium text-slate-400 mt-2">Initialize a capital pulse through the inflow/outflow controls above.</p>
                    </div>
                )}
            </div>
        </Layout>
    );
};

export default CashInHand;

import { logger } from '@/shared/lib/logger';
import React, { useState, useMemo, useEffect } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import { RootState, AppDispatch } from "@/app/store/store";
import { fetchCheques, registerCheque, updateChequeStatusBackend, fetchEffectiveBalance } from "@/entities/finance/model/financeSlice";
import { getAccounts, validatePayments, createTransfer } from "@/entities/finance/model/cashbankSlice";
import { fetchPurchaseOrders } from "@/entities/purchase/model/purchaseSlice";
import Layout from "@/shared/ui/Layout";
import {
    FileCheck,
    Clock,
    XCircle,
    Receipt,
    Building2,
    Plus,
    Search,
    Calendar,
    IndianRupee,
    User,
    FileText,
    X,
    CheckCircle2,
    ArrowDownLeft,
    ArrowUpRight,
    Activity,
    ShieldCheck,
    Zap,
    Download,
    TrendingUp,
    Filter,
    ArrowRight,
    Layers,
    AlertTriangle
} from 'lucide-react';
import { formatCurrency } from "@/shared/lib/utils/helpers";
import TransferModal from './TransferModal';
import DayEndModal from './DayEndModal';
import ClearingParameters from './ClearingParameters';

const Cheques: React.FC = () => {
    const dispatch = useDispatch<AppDispatch>();
    const { cheques, effectiveBalance, bankBalance: reduxBankBalance, pdcAlerts, loading } = useSelector((state: RootState) => state.finance);
    const { currentSector } = useSelector((state: RootState) => state.auth);
    const { accounts } = useSelector((state: RootState) => state.cashbank);
    const { orders: purchases } = useSelector((state: RootState) => state.purchase);

    const [showAddCheque, setShowAddCheque] = useState(false);
    const [showTransferModal, setShowTransferModal] = useState(false);
    const [showDayEndModal, setShowDayEndModal] = useState(false);
    const [showClearingParams, setShowClearingParams] = useState(false);
    const [showBulkPaymentModal, setShowBulkPaymentModal] = useState(false);
    const [selectedInvoices, setSelectedInvoices] = useState<any[]>([]);
    const [bulkPayAccountId, setBulkPayAccountId] = useState('');
    const [searchTerm, setSearchTerm] = useState('');
    const [statusFilter, setStatusFilter] = useState<'all' | 'PENDING' | 'CLEARED' | 'BOUNCED'>('all');
    const [selectedCheque, setSelectedCheque] = useState<any | null>(null);
    const [showDetails, setShowDetails] = useState(false);
    const [isValidating, setIsValidating] = useState(false);
    const [validationResults, setValidationResults] = useState<any | null>(null);

    const [formData, setFormData] = useState({
        number: '',
        payee: '',
        amount: '',
        date: new Date().toISOString().split('T')[0],
        bankName: '',
        type: 'RECEIVED' as 'RECEIVED' | 'ISSUED',
        accountId: '',
        notes: ''
    });

    useEffect(() => {
        dispatch(getAccounts());
        dispatch(fetchPurchaseOrders());
        dispatch(fetchCheques(currentSector));
    }, [dispatch, currentSector]);

    useEffect(() => {
        if (bulkPayAccountId) {
            dispatch(fetchEffectiveBalance({ accountId: bulkPayAccountId }));
        }
    }, [dispatch, bulkPayAccountId]);


    const sectorCheques = useMemo(() =>
        (cheques || []).filter((c: any) => c.sector === currentSector)
        , [cheques, currentSector]);

    const filteredCheques = useMemo(() =>
        sectorCheques.filter((c: any) => {
            const matchesStatus = statusFilter === 'all' || c.status === statusFilter;
            const matchesSearch = c.number.toLowerCase().includes(searchTerm.toLowerCase()) ||
                c.payee.toLowerCase().includes(searchTerm.toLowerCase());
            return matchesStatus && matchesSearch;
        })
        , [sectorCheques, statusFilter, searchTerm]);

    const statusCounts = {
        all: sectorCheques.length,
        PENDING: sectorCheques.filter((c: any) => c.status === 'PENDING').length,
        CLEARED: sectorCheques.filter((c: any) => c.status === 'CLEARED').length,
        BOUNCED: sectorCheques.filter((c: any) => c.status === 'BOUNCED').length
    };

    const statusValues = {
        PENDING: sectorCheques.filter((c: any) => c.status === 'PENDING').reduce((sum: number, c: any) => sum + c.amount, 0),
        CLEARED: sectorCheques.filter((c: any) => c.status === 'CLEARED').reduce((sum: number, c: any) => sum + c.amount, 0),
        BOUNCED: sectorCheques.filter((c: any) => c.status === 'BOUNCED').reduce((sum: number, c: any) => sum + c.amount, 0)
    };

    const handleRegister = async (e: React.FormEvent) => {
        try {
            e.preventDefault();
            await dispatch(registerCheque({
                ...formData,
                amount: parseFloat(formData.amount),
                status: 'PENDING',
                sector: currentSector as any
            })).unwrap();
            setShowAddCheque(false);
            setFormData({ number: '', payee: '', amount: '', date: new Date().toISOString().split('T')[0], bankName: '', type: 'RECEIVED', accountId: '', notes: '' });
        } catch (err: any) {
            if (err.code === 'INSUFFICIENT_FUNDS') {
                const shortage = err.shortage;
                const confirmForce = window.confirm(
                    `⚠️ Insufficient Funds Detected!\n\nShortage: ₹${shortage}\n\nDo you want to FORCE PAY this cheque? This will be logged as an exception.`
                );
                if (confirmForce) {
                    await dispatch(registerCheque({
                        ...formData,
                        amount: parseFloat(formData.amount),
                        status: 'PENDING',
                        sector: currentSector as any,
                        forcePay: true,
                        notes: `${formData.notes} [FORCE PAY: Shortage ₹${shortage}]`
                    } as any)).unwrap();
                    setShowAddCheque(false);
                    setFormData({ number: '', payee: '', amount: '', date: new Date().toISOString().split('T')[0], bankName: '', type: 'RECEIVED', accountId: '', notes: '' });
                }
            } else {
                logger.error('Failed to register cheque:', err);
                // Ideally show a toast here, but console for now as per minimal changes
                alert(`Error: ${err.message || 'Failed to register'}`);
            }
        }
    };

    const handleUpdateStatus = (id: string, status: 'CLEARED' | 'BOUNCED') => {
        dispatch(updateChequeStatusBackend({ id, status }));
        setShowDetails(false);
    };

    const handleOpenBulkPay = () => {
        setSelectedInvoices(purchases
            .filter((p: any) => (p.status === 'COMPLETED' || p.status === 'APPROVED') && ((p.totalAmount || p.total) > (p.paidAmount || 0)))
            .map((p: any) => ({
                id: p._id,
                invoiceNo: p.purchaseNumber || p.invoiceNo,
                supplier: p.vendor,
                amount: p.totalAmount || p.total,
                due: (p.totalAmount || p.total) - (p.paidAmount || 0),
                payAmount: 0,
                selected: false,
                status: 'pending'
            })));
        setShowBulkPaymentModal(true);
    };

    const handleValidateBulk = async () => {
        const toPay = selectedInvoices.filter(i => i.selected && i.payAmount > 0);
        if (toPay.length === 0) return;
        if (!bulkPayAccountId) return;

        setIsValidating(true);
        try {
            const result = await dispatch(validatePayments({
                accountId: bulkPayAccountId,
                payments: toPay.map(i => ({
                    amount: i.payAmount,
                    referenceId: i.id,
                    payee: i.supplier
                }))
            })).unwrap();
            setValidationResults(result);

            const updated = [...selectedInvoices];
            result.results.forEach((res: any) => {
                const idx = updated.findIndex(u => u.id === res.referenceId);
                if (idx !== -1) {
                    updated[idx].status = res.status;
                }
            });
            setSelectedInvoices(updated);
        } catch (err) {
            logger.error('Validation failed:', err);
        } finally {
            setIsValidating(false);
        }
    };

    return (
        <Layout>
            <div className="space-y-6 animate-fade-in text-neutral-900 dark:text-neutral-100 pb-16">

                {/* Header */}
                <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                    <div>
                        <h2 className="text-3xl font-black flex items-center gap-2 tracking-tight uppercase">
                            <Receipt className="w-8 h-8 text-primary" />
                            Instrument Clearing Console
                        </h2>
                        <p className="text-sm text-neutral-500 mt-1 font-medium flex items-center gap-2">
                            Authority Node: <span className="px-2 py-0.5 bg-primary/10 text-primary rounded-md font-bold italic">{currentSector}</span>
                        </p>
                    </div>
                    <div className="flex gap-3">
                        <button
                            onClick={() => setShowClearingParams(true)}
                            className="px-5 py-2.5 bg-neutral-900 text-white dark:bg-neutral-100 dark:text-neutral-900 rounded-xl text-[10px] font-black flex items-center gap-2 hover:bg-neutral-800 dark:hover:bg-neutral-200 transition active:scale-95 uppercase tracking-[0.2em]"
                        >
                            <Zap className="w-4 h-4" /> Parameters
                        </button>
                        <button
                            onClick={() => setShowDayEndModal(true)}
                            className="px-5 py-2.5 bg-neutral-900 text-white dark:bg-neutral-100 dark:text-neutral-900 rounded-xl text-[10px] font-black flex items-center gap-2 hover:bg-neutral-800 dark:hover:bg-neutral-200 transition active:scale-95 uppercase tracking-[0.2em]"
                        >
                            <Calendar className="w-4 h-4" /> Day End
                        </button>
                        <button
                            onClick={() => setShowTransferModal(true)}
                            className="px-5 py-2.5 bg-neutral-900 text-white dark:bg-neutral-100 dark:text-neutral-900 rounded-xl text-[10px] font-black flex items-center gap-2 hover:bg-neutral-800 dark:hover:bg-neutral-200 transition active:scale-95 uppercase tracking-[0.2em]"
                        >
                            <ArrowRight className="w-4 h-4" /> Fund Transfer
                        </button>
                        <button
                            onClick={handleOpenBulkPay}
                            className="px-5 py-2.5 bg-brand-100 text-brand-600 dark:bg-brand-900/30 dark:text-brand-400 rounded-xl text-[10px] font-black flex items-center gap-2 hover:bg-brand-200 transition active:scale-95 uppercase tracking-[0.2em]"
                        >
                            <Layers className="w-4 h-4" /> Bulk Payment Stream
                        </button>
                        <button className="px-5 py-2.5 bg-white dark:bg-neutral-800 border border-neutral-200 dark:border-neutral-700 rounded-xl text-[10px] font-black flex items-center gap-2 hover:bg-neutral-50 shadow-sm transition active:scale-95 uppercase tracking-[0.2em]">
                            <Download className="w-4 h-4 text-primary" /> Export Ledger
                        </button>
                        <button
                            onClick={() => setShowAddCheque(true)}
                            className="px-5 py-2.5 bg-primary text-white rounded-xl text-[10px] font-black shadow-lg shadow-primary/20 flex items-center gap-2 hover:bg-primary/90 transition hover:scale-105 active:scale-95 uppercase tracking-[0.2em]"
                        >
                            <Plus className="w-4 h-4 fill-current" /> Register Instrument
                        </button>
                    </div>
                </div>

                {/* KPI Pulse Row */}
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
                    <div className="bg-white dark:bg-neutral-800 p-6 rounded-[2rem] border border-neutral-200 dark:border-neutral-700 shadow-sm relative overflow-hidden group">
                        <p className="text-[10px] font-black text-neutral-400 uppercase tracking-[0.2em] mb-1">Clearing Rate</p>
                        <h3 className="text-3xl font-black text-primary italic tracking-tighter">
                            {statusCounts.all > 0 ? ((statusCounts.CLEARED / statusCounts.all) * 100).toFixed(0) : 0}%
                        </h3>
                        <div className="mt-3 h-1 bg-neutral-100 dark:bg-neutral-900 rounded-full overflow-hidden">
                            <div
                                className="h-full bg-primary transition-all duration-1000"
                                style={{ width: `${statusCounts.all > 0 ? (statusCounts.CLEARED / statusCounts.all) * 100 : 0}%` }}
                            />
                        </div>
                    </div>

                    <div className="bg-white dark:bg-neutral-800 p-6 rounded-[2rem] border border-neutral-200 dark:border-neutral-700 shadow-sm relative overflow-hidden group">
                        <p className="text-[10px] font-black text-neutral-400 uppercase tracking-[0.2em] mb-1">Pending Capital</p>
                        <h3 className="text-3xl font-black text-warning italic tracking-tighter">
                            ₹{formatCurrency(statusValues.PENDING)}
                        </h3>
                        <div className="flex items-center gap-1.5 mt-2">
                            <Clock className="w-4 h-4 text-warning" />
                            <span className="text-[10px] font-black text-warning uppercase">{statusCounts.PENDING} Active Wrappers</span>
                        </div>
                    </div>

                    <div className="bg-white dark:bg-neutral-800 p-6 rounded-[2rem] border border-neutral-200 dark:border-neutral-700 shadow-sm relative overflow-hidden group">
                        <p className="text-[10px] font-black text-neutral-400 uppercase tracking-[0.2em] mb-1">Successfully Cleared</p>
                        <h3 className="text-3xl font-black text-success italic tracking-tighter">
                            ₹{formatCurrency(statusValues.CLEARED)}
                        </h3>
                        <div className="flex items-center gap-1.5 mt-2">
                            <FileCheck className="w-4 h-4 text-success" />
                            <span className="text-[10px] font-black text-success uppercase">Commited to Vault</span>
                        </div>
                    </div>

                    <div className="bg-neutral-950 text-white p-6 rounded-[2rem] shadow-2xl relative overflow-hidden group">
                        <Zap className="absolute -top-4 -right-4 w-20 h-20 text-primary opacity-20 group-hover:scale-125 transition duration-1000" />
                        <div className="relative z-10">
                            <div className="inline-flex items-center gap-2 px-2 py-0.5 bg-primary/20 border border-primary/30 rounded-full text-primary-light text-[9px] font-black uppercase tracking-[0.2em] mb-2">
                                <ShieldCheck className="w-3 h-3 fill-current" /> Effective Balance
                            </div>
                            <h3 className="text-3xl font-black text-white italic tracking-tighter">
                                ₹{formatCurrency(effectiveBalance || 0)}
                            </h3>
                            <p className="text-[10px] font-bold text-neutral-400 mt-2 uppercase tracking-widest italic">
                                Available after {pdcAlerts?.count || 0} PDCs
                            </p>
                            <ArrowRight className="absolute bottom-0 right-0 w-4 h-4 text-primary group-hover:translate-x-1 transition cursor-pointer" />
                        </div>
                    </div>
                </div>

                {/* PDC Alert Banner */}
                {pdcAlerts && pdcAlerts.count > 1 && (
                    <div className="bg-error/10 border border-error/20 p-4 rounded-2xl flex items-center gap-4 animate-pulse">
                        <AlertTriangle className="text-error w-6 h-6" />
                        <div>
                            <p className="text-xs font-black text-error uppercase tracking-widest">Multiple PDC Alert</p>
                            <p className="text-[10px] font-bold text-error/80 uppercase italic">
                                {pdcAlerts.count} cheques totaling ₹{formatCurrency(pdcAlerts.total)} are due for clearing. Ensure sufficient liquidity.
                            </p>
                        </div>
                    </div>
                )}

                {/* Search & Filters */}
                <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 bg-white dark:bg-neutral-800 p-2 rounded-2xl border border-neutral-200 dark:border-neutral-700">
                    <div className="flex p-1 bg-neutral-100 dark:bg-neutral-900 rounded-xl w-full md:w-auto">
                        {[
                            { id: 'all', label: 'All Node' },
                            { id: 'PENDING', label: 'Pending' },
                            { id: 'CLEARED', label: 'Cleared' },
                            { id: 'BOUNCED', label: 'Bounced' }
                        ].map(f => (
                            <button
                                key={f.id}
                                onClick={() => setStatusFilter(f.id as any)}
                                className={`flex-1 md:flex-none flex items-center justify-center gap-2 px-6 py-2 rounded-lg text-[9px] font-black uppercase tracking-widest transition-all ${statusFilter === f.id
                                    ? 'bg-white dark:bg-neutral-800 text-primary shadow-sm'
                                    : 'text-neutral-500 hover:text-neutral-900 dark:hover:text-white'
                                    }`}
                            >
                                {f.label}
                            </button>
                        ))}
                    </div>

                    <div className="flex items-center gap-4 w-full md:w-auto px-2">
                        <div className="relative flex-1 md:w-64">
                            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-neutral-400" />
                            <input
                                type="text"
                                placeholder="Search Instruments..."
                                value={searchTerm}
                                onChange={e => setSearchTerm(e.target.value)}
                                className="w-full pl-9 pr-4 py-2 bg-neutral-50 dark:bg-neutral-900 border border-neutral-200 dark:border-neutral-700 rounded-xl text-xs outline-none focus:ring-2 focus:ring-primary/20 transition font-black tracking-tight italic"
                            />
                        </div>
                        <button className="p-2.5 bg-neutral-50 dark:bg-neutral-900 border border-neutral-200 dark:border-neutral-700 rounded-xl text-neutral-500 hover:text-primary transition shadow-sm">
                            <Filter className="w-4 h-4" />
                        </button>
                    </div>
                </div>

                {/* Instrument Grid */}
                {filteredCheques.length === 0 ? (
                    <div className="py-32 bg-white dark:bg-neutral-800 rounded-[3rem] border-2 border-dashed border-neutral-200 dark:border-neutral-700 text-center flex flex-col items-center">
                        <Layers className="w-16 h-16 text-neutral-100 dark:text-neutral-900 mb-6" />
                        <h4 className="text-xl font-black italic text-neutral-400 uppercase tracking-widest">No Instruments located in node</h4>
                        <p className="text-xs font-bold text-neutral-300 mt-2 uppercase tracking-widest italic">Clear filters or register a new transaction pulse</p>
                    </div>
                ) : (
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                        {filteredCheques.map((c: any) => (
                            <div
                                key={c.id}
                                onClick={() => { setSelectedCheque(c); setShowDetails(true); }}
                                className="bg-white dark:bg-neutral-800 rounded-[2.5rem] border border-neutral-200 dark:border-neutral-700 p-8 hover:shadow-2xl hover:border-primary/30 transition-all group cursor-pointer relative overflow-hidden"
                            >
                                <div className="absolute top-0 right-0 w-24 h-24 bg-neutral-50 dark:bg-neutral-900/50 rounded-full -mr-12 -mt-12 group-hover:scale-150 transition-transform duration-700" />

                                <div className="relative z-10">
                                    <div className="flex items-start justify-between mb-8">
                                        <div className={`p-4 rounded-2xl ${c.type === 'RECEIVED' ? 'bg-success/10 text-success' : 'bg-primary/10 text-primary'}`}>
                                            {c.type === 'RECEIVED' ? <ArrowDownLeft className="w-6 h-6" /> : <ArrowUpRight className="w-6 h-6" />}
                                        </div>
                                        <span className={`px-4 py-1 rounded-full text-[9px] font-black uppercase tracking-[0.2em] border ${c.status === 'PENDING' ? 'bg-warning/10 text-warning border-warning/20' :
                                            c.status === 'CLEARED' ? 'bg-success/10 text-success border-success/20' :
                                                'bg-error/10 text-error border-error/20'
                                            }`}>
                                            {c.status}
                                        </span>
                                    </div>

                                    <div className="space-y-4 mb-8">
                                        <div>
                                            <p className="text-[10px] font-black text-neutral-400 uppercase tracking-widest mb-1">Party / Payee</p>
                                            <h4 className="text-xl font-black italic tracking-tighter truncate">{c.payee}</h4>
                                        </div>

                                        <div className="grid grid-cols-2 gap-4">
                                            <div>
                                                <p className="text-[9px] font-black text-neutral-400 uppercase tracking-widest mb-1">Instrument #</p>
                                                <p className="text-xs font-black font-mono tracking-tighter italic">{c.number}</p>
                                            </div>
                                            <div>
                                                <p className="text-[9px] font-black text-neutral-400 uppercase tracking-widest mb-1">Entity Bank</p>
                                                <p className="text-xs font-black italic tracking-tighter truncate uppercase">{c.bankName}</p>
                                            </div>
                                        </div>
                                    </div>

                                    <div className="pt-6 border-t border-neutral-100 dark:border-neutral-700 flex items-end justify-between">
                                        <div>
                                            <p className="text-[9px] font-black text-neutral-400 uppercase tracking-widest mb-1">Commitment Value</p>
                                            <p className={`text-2xl font-black italic tracking-tighter ${c.type === 'RECEIVED' ? 'text-success' : 'text-primary'}`}>
                                                ₹{formatCurrency(c.amount)}
                                            </p>
                                        </div>
                                        <div className="text-[9px] font-black text-neutral-300 uppercase italic">
                                            {new Date(c.date).toLocaleDateString(undefined, { day: '2-digit', month: 'short' })}
                                        </div>
                                    </div>
                                </div>
                            </div>
                        ))}
                    </div>
                )}
            </div>

            {/* --- MODALS --- */}
            {showAddCheque && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-6 bg-neutral-950/80 backdrop-blur-md animate-in fade-in duration-300">
                    <div className="bg-white dark:bg-neutral-800 w-full max-w-2xl rounded-[3rem] shadow-2xl border border-neutral-200 dark:border-neutral-700 overflow-hidden relative">
                        <Activity className="absolute -top-10 -right-10 w-48 h-48 text-primary opacity-5" />

                        <div className="p-10">
                            <div className="flex items-center justify-between mb-10">
                                <div>
                                    <h3 className="text-2xl font-black italic tracking-tighter uppercase mb-1">Register Instrument</h3>
                                    <p className="text-xs font-bold text-neutral-400 uppercase tracking-widest italic">Securing asset node in {currentSector} zone</p>
                                </div>
                                <button onClick={() => setShowAddCheque(false)} className="p-3 bg-neutral-100 dark:bg-neutral-900 rounded-full text-neutral-400 hover:text-error transition">
                                    <X size={20} />
                                </button>
                            </div>

                            <form onSubmit={handleRegister} className="space-y-6">
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                    <div className="space-y-2">
                                        <label className="text-[10px] font-black text-neutral-400 uppercase tracking-[0.2em] pl-1">Instrument ID</label>
                                        <input
                                            type="text"
                                            required
                                            value={formData.number}
                                            onChange={e => setFormData({ ...formData, number: e.target.value })}
                                            className="w-full px-5 py-4 bg-neutral-50 dark:bg-neutral-900 border border-neutral-100 dark:border-neutral-700 rounded-2xl text-sm font-black italic outline-none focus:ring-4 focus:ring-primary/10 transition-all font-mono"
                                            placeholder="CHQ-XXXXXX"
                                        />
                                    </div>
                                    <div className="space-y-2">
                                        <label className="text-[10px] font-black text-neutral-400 uppercase tracking-[0.2em] pl-1">Entry Date</label>
                                        <input
                                            type="date"
                                            required
                                            value={formData.date}
                                            onChange={e => setFormData({ ...formData, date: e.target.value })}
                                            className="w-full px-5 py-4 bg-neutral-50 dark:bg-neutral-900 border border-neutral-100 dark:border-neutral-700 rounded-2xl text-sm font-black italic outline-none focus:ring-4 focus:ring-primary/10 transition-all"
                                        />
                                    </div>
                                    <div className="space-y-2">
                                        <label className="text-[10px] font-black text-neutral-400 uppercase tracking-[0.2em] pl-1">Counter-Party Label</label>
                                        <input
                                            type="text"
                                            required
                                            value={formData.payee}
                                            onChange={e => setFormData({ ...formData, payee: e.target.value })}
                                            className="w-full px-5 py-4 bg-neutral-50 dark:bg-neutral-900 border border-neutral-100 dark:border-neutral-700 rounded-2xl text-sm font-black italic outline-none focus:ring-4 focus:ring-primary/10 transition-all"
                                            placeholder="Entity Name..."
                                        />
                                    </div>
                                    <div className="space-y-2">
                                        <label className="text-[10px] font-black text-neutral-400 uppercase tracking-[0.2em] pl-1">Magnitude (₹)</label>
                                        <input
                                            type="number"
                                            required
                                            value={formData.amount}
                                            onChange={e => setFormData({ ...formData, amount: e.target.value })}
                                            className="w-full px-5 py-4 bg-neutral-50 dark:bg-neutral-900 border border-neutral-100 dark:border-neutral-700 rounded-2xl text-sm font-black italic outline-none focus:ring-4 focus:ring-primary/10 transition-all font-mono"
                                            placeholder="0.00"
                                        />
                                    </div>
                                    <div className="space-y-2">
                                        <label className="text-[10px] font-black text-neutral-400 uppercase tracking-[0.2em] pl-1">Target Account</label>
                                        <select
                                            required
                                            value={formData.accountId}
                                            onChange={e => setFormData({ ...formData, accountId: e.target.value })}
                                            className="w-full px-5 py-4 bg-neutral-50 dark:bg-neutral-900 border border-neutral-100 dark:border-neutral-700 rounded-2xl text-sm font-black italic outline-none focus:ring-4 focus:ring-primary/10 transition-all font-mono appearance-none"
                                        >
                                            <option value="">Select Account...</option>
                                            {accounts.map(acc => (
                                                <option key={acc._id} value={acc._id}>{acc.bankName} - {acc.accountNumber}</option>
                                            ))}
                                        </select>
                                    </div>
                                    <div className="space-y-2">
                                        <label className="text-[10px] font-black text-neutral-400 uppercase tracking-[0.2em] pl-1">Pulse Direction</label>
                                        <div className="flex bg-neutral-50 dark:bg-neutral-900 p-1 rounded-2xl border border-neutral-100 dark:border-neutral-700">
                                            <button
                                                type="button"
                                                onClick={() => setFormData({ ...formData, type: 'RECEIVED' })}
                                                className={`flex-1 py-3 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all ${formData.type === 'RECEIVED' ? 'bg-success text-white shadow-lg shadow-success/20' : 'text-neutral-400'}`}
                                            >
                                                Received
                                            </button>
                                            <button
                                                type="button"
                                                onClick={() => setFormData({ ...formData, type: 'ISSUED' })}
                                                className={`flex-1 py-3 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all ${formData.type === 'ISSUED' ? 'bg-primary text-white shadow-lg shadow-primary/20' : 'text-neutral-400'}`}
                                            >
                                                Issued
                                            </button>
                                        </div>
                                    </div>
                                </div>

                                <button type="submit" className="w-full py-5 mt-6 bg-neutral-950 text-white rounded-3xl text-[10px] font-black uppercase tracking-[0.3em] shadow-2xl hover:bg-neutral-900 transition-all flex items-center justify-center gap-4 border border-neutral-700">
                                    <ShieldCheck className="w-5 h-5 text-primary" />
                                    Authorize Instrument Deployment
                                </button>
                            </form>
                        </div>
                    </div>
                </div>
            )}

            {showDetails && selectedCheque && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-6 bg-neutral-950/80 backdrop-blur-md animate-in fade-in duration-300">
                    <div className="bg-white dark:bg-neutral-800 w-full max-w-lg rounded-[3.5rem] shadow-2xl border border-neutral-200 dark:border-neutral-700 overflow-hidden">
                        <div className="p-10 border-b border-neutral-50 dark:border-neutral-700 flex items-center justify-between bg-neutral-50/50 dark:bg-neutral-900/10">
                            <div>
                                <h3 className="text-2xl font-black italic tracking-tighter uppercase mb-1">{selectedCheque.number}</h3>
                                <p className="text-[10px] font-black text-neutral-400 uppercase tracking-[0.2em] italic">Authority Node Audit</p>
                            </div>
                            <button onClick={() => setShowDetails(false)} className="p-3 bg-white dark:bg-neutral-900 border border-neutral-100 dark:border-neutral-700 rounded-2xl text-neutral-400 hover:text-error transition shadow-sm">
                                <X size={20} />
                            </button>
                        </div>

                        <div className="p-10 text-center">
                            <div className="inline-flex items-center gap-2 px-4 py-1.5 bg-primary/10 border border-primary/20 rounded-full text-primary text-[9px] font-black uppercase tracking-[0.2em] mb-6 italic">
                                <Zap className="w-3.5 h-3.5 fill-current" /> Instrument Value Extraction
                            </div>
                            <h2 className={`text-6xl font-black italic tracking-tighter mb-4 ${selectedCheque.type === 'RECEIVED' ? 'text-success' : 'text-primary'}`}>
                                ₹{formatCurrency(selectedCheque.amount)}
                            </h2>
                            <p className="text-sm font-bold text-neutral-400 uppercase tracking-widest italic mb-10">Commitment to {selectedCheque.payee}</p>

                            <div className="grid grid-cols-2 gap-4 mb-12">
                                <div className="p-6 bg-neutral-50 dark:bg-neutral-900 rounded-[2rem] border border-neutral-100 dark:border-neutral-800 text-left">
                                    <p className="text-[9px] font-black text-neutral-400 uppercase tracking-widest mb-1">Status Protocol</p>
                                    <p className="text-xs font-black italic text-neutral-900 dark:text-white uppercase">{selectedCheque.status}</p>
                                </div>
                                <div className="p-6 bg-neutral-50 dark:bg-neutral-900 rounded-[2rem] border border-neutral-100 dark:border-neutral-800 text-left">
                                    <p className="text-[9px] font-black text-neutral-400 uppercase tracking-widest mb-1">Entity Direction</p>
                                    <p className={`text-xs font-black italic uppercase ${selectedCheque.type === 'RECEIVED' ? 'text-success' : 'text-primary'}`}>{selectedCheque.type}</p>
                                </div>
                            </div>

                            {selectedCheque.status === 'PENDING' && (
                                <div className="flex gap-4">
                                    <button
                                        onClick={() => handleUpdateStatus(selectedCheque.id, 'CLEARED')}
                                        className="flex-1 py-5 bg-success text-white rounded-[2rem] text-[10px] font-black uppercase tracking-[0.2em] shadow-xl shadow-success/20 hover:scale-105 transition-all flex items-center justify-center gap-2"
                                    >
                                        <CheckCircle2 className="w-5 h-5 fill-current" /> Commit to Vault
                                    </button>
                                    <button
                                        onClick={() => handleUpdateStatus(selectedCheque.id, 'BOUNCED')}
                                        className="flex-1 py-5 bg-error text-white rounded-[2rem] text-[10px] font-black uppercase tracking-[0.2em] shadow-xl shadow-error/20 hover:scale-105 transition-all flex items-center justify-center gap-2"
                                    >
                                        <XCircle className="w-5 h-5 fill-current" /> Log Rejection
                                    </button>
                                </div>
                            )}
                        </div>
                    </div>
                </div>
            )}

            {showBulkPaymentModal && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-6 bg-neutral-950/80 backdrop-blur-md animate-in fade-in duration-300">
                    <div className="bg-white dark:bg-neutral-800 w-full max-w-4xl rounded-[3.5rem] shadow-2xl border border-neutral-200 dark:border-neutral-700 overflow-hidden flex flex-col max-h-[90vh]">
                        <div className="p-10 border-b border-neutral-50 dark:border-neutral-700 flex items-center justify-between">
                            <div>
                                <h3 className="text-2xl font-black italic tracking-tighter uppercase mb-1">Bulk Payment Stream</h3>
                                <p className="text-[10px] font-black text-neutral-400 uppercase tracking-[0.2em] italic">Dynamic Balance Validation Protocol</p>
                            </div>
                            <button onClick={() => setShowBulkPaymentModal(false)} className="p-3 bg-neutral-50 dark:bg-neutral-900 border border-neutral-100 dark:border-neutral-700 rounded-2xl text-neutral-400 hover:text-error transition">
                                <X size={20} />
                            </button>
                        </div>

                        <div className="p-10 overflow-y-auto flex-1 space-y-8">
                            <div className="space-y-4">
                                <label className="text-[10px] font-black text-neutral-400 uppercase tracking-[0.2em] pl-1 text-center block">Deployment Account</label>
                                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                                    {accounts.map(acc => (
                                        <button
                                            key={acc._id}
                                            onClick={() => setBulkPayAccountId(acc._id)}
                                            className={`p-6 rounded-[2rem] border-2 transition-all text-left ${bulkPayAccountId === acc._id ? 'border-primary bg-primary/5 ring-8 ring-primary/5' : 'border-neutral-100 dark:border-neutral-800 bg-neutral-50 dark:bg-neutral-900 hover:border-neutral-200'}`}
                                        >
                                            <p className="text-[9px] font-black text-neutral-400 uppercase tracking-widest mb-1">{acc.bankName}</p>
                                            <p className="text-sm font-black italic text-neutral-900 dark:text-white mb-2">{acc.accountNumber}</p>
                                            <p className="text-xs font-black text-primary italic">₹{formatCurrency(acc.currentBalance)}</p>
                                        </button>
                                    ))}
                                </div>
                            </div>

                            <div className="bg-neutral-50 dark:bg-neutral-900/50 rounded-[2.5rem] border border-neutral-100 dark:border-neutral-800 overflow-hidden">
                                <table className="w-full text-left border-collapse">
                                    <thead>
                                        <tr className="bg-neutral-100/50 dark:bg-neutral-800/50">
                                            <th className="px-6 py-4 text-[9px] font-black text-neutral-400 uppercase tracking-widest">Select</th>
                                            <th className="px-6 py-4 text-[9px] font-black text-neutral-400 uppercase tracking-widest">Supplier/Ref</th>
                                            <th className="px-6 py-4 text-[9px] font-black text-neutral-400 uppercase tracking-widest">Pending</th>
                                            <th className="px-6 py-4 text-[9px] font-black text-neutral-400 uppercase tracking-widest">Pay Amount</th>
                                            <th className="px-6 py-4 text-[9px] font-black text-neutral-400 uppercase tracking-widest text-right">Balance Feedback</th>
                                        </tr>
                                    </thead>
                                    <tbody className="divide-y divide-neutral-100 dark:divide-neutral-800">
                                        {selectedInvoices.map((inv, idx) => (
                                            <tr key={inv.id} className={`group hover:bg-neutral-100/20 transition-colors ${inv.selected ? 'bg-primary/5' : ''}`}>
                                                <td className="px-6 py-4">
                                                    <input
                                                        type="checkbox"
                                                        checked={inv.selected}
                                                        onChange={(e) => {
                                                            const updated = [...selectedInvoices];
                                                            updated[idx].selected = e.target.checked;
                                                            setSelectedInvoices(updated);
                                                        }}
                                                        className="w-5 h-5 rounded-lg border-2 border-neutral-200 text-primary focus:ring-primary/20 transition-all cursor-pointer"
                                                    />
                                                </td>
                                                <td className="px-6 py-4">
                                                    <p className="text-[10px] font-black italic uppercase text-neutral-800 dark:text-neutral-200">{inv.supplier}</p>
                                                    <p className="text-[9px] font-bold text-neutral-400 uppercase">{inv.invoiceNo}</p>
                                                </td>
                                                <td className="px-6 py-4">
                                                    <p className="text-[10px] font-black italic text-neutral-500">₹{formatCurrency(inv.due)}</p>
                                                </td>
                                                <td className="px-6 py-4">
                                                    <input
                                                        type="number"
                                                        value={inv.payAmount || ''}
                                                        onChange={(e) => {
                                                            const updated = [...selectedInvoices];
                                                            updated[idx].payAmount = parseFloat(e.target.value) || 0;
                                                            setSelectedInvoices(updated);
                                                        }}
                                                        disabled={!inv.selected}
                                                        placeholder="0.00"
                                                        className="w-32 px-4 py-2 bg-white dark:bg-neutral-900 border border-neutral-100 dark:border-neutral-700 rounded-xl text-xs font-black italic outline-none focus:ring-4 focus:ring-primary/10 disabled:opacity-30 transition-all font-mono"
                                                    />
                                                </td>
                                                <td className="px-6 py-4 text-right">
                                                    {inv.status === 'insufficient_funds' ? (
                                                        <span className="inline-flex items-center gap-1.5 px-3 py-1 bg-error/10 text-error text-[8px] font-black uppercase tracking-widest rounded-full animate-pulse">
                                                            <AlertTriangle size={10} /> Shortage Detected
                                                        </span>
                                                    ) : inv.status === 'approved' ? (
                                                        <span className="inline-flex items-center gap-1.5 px-3 py-1 bg-success/10 text-success text-[8px] font-black uppercase tracking-widest rounded-full">
                                                            <CheckCircle2 size={10} /> Funds Verified
                                                        </span>
                                                    ) : (
                                                        <span className="text-[8px] font-black text-neutral-300 uppercase italic tracking-widest">Awaiting Verification</span>
                                                    )}
                                                </td>
                                            </tr>
                                        ))}
                                    </tbody>
                                </table>
                            </div>
                        </div>

                        <div className="p-10 bg-neutral-50 dark:bg-neutral-900/50 border-t border-neutral-100 dark:border-neutral-700 flex items-center justify-between">
                            <div className="text-left">
                                <p className="text-[9px] font-black text-neutral-400 uppercase tracking-[0.2em] mb-1">Total Payload Magnitude</p>
                                <p className="text-2xl font-black italic text-neutral-900 dark:text-white">
                                    ₹{formatCurrency(selectedInvoices.filter(i => i.selected).reduce((acc, i) => acc + (i.payAmount || 0), 0))}
                                </p>
                            </div>
                            <div className="flex gap-4">
                                <button
                                    onClick={handleValidateBulk}
                                    disabled={isValidating || !bulkPayAccountId || selectedInvoices.filter(i => i.selected).length === 0}
                                    className="px-8 py-4 bg-white dark:bg-neutral-800 border-2 border-primary text-primary rounded-2xl text-[9px] font-black uppercase tracking-[0.2em] hover:bg-primary hover:text-white transition-all disabled:opacity-50 flex items-center gap-2"
                                >
                                    {isValidating ? 'Processing Logic...' : 'Run Balance Check'}
                                </button>
                                <button
                                    disabled={!validationResults || !validationResults.approved}
                                    className="px-10 py-5 bg-primary text-white rounded-[2rem] text-[10px] font-black uppercase tracking-[0.2em] shadow-xl shadow-primary/20 hover:scale-105 transition-all disabled:opacity-30 flex items-center gap-3"
                                >
                                    {validationResults?.approved ? 'Execute Batch Payment' : 'Validation Required'}
                                </button>
                            </div>
                        </div>
                    </div>
                </div>
            )}

            {showTransferModal && (
                <TransferModal
                    accounts={accounts}
                    onClose={() => setShowTransferModal(false)}
                    onSuccess={() => {
                        setShowTransferModal(false);
                        dispatch(getAccounts());
                    }}
                />
            )}

            {showDayEndModal && (
                <DayEndModal onClose={() => setShowDayEndModal(false)} />
            )}

            {showClearingParams && (
                <ClearingParameters onClose={() => setShowClearingParams(false)} />
            )}
        </Layout>
    );
};

export default Cheques;

import { logger } from '@/shared/lib/logger';
import React, { useState, useEffect } from 'react';
import { X, Save, RefreshCw, Zap, ShieldCheck } from 'lucide-react';
import api from "@/shared/api/api"; // Direct API import since no slice action exists yet
import { useSelector } from 'react-redux';
import { RootState } from "@/app/store/store";

interface ClearingParametersProps {
    onClose: () => void;
}

const ClearingParameters: React.FC<ClearingParametersProps> = ({ onClose }) => {
    const { currentSector } = useSelector((state: RootState) => state.auth);
    const [parameters, setParameters] = useState<any[]>([]);
    const [loading, setLoading] = useState(false);
    const [initializing, setInitializing] = useState(false);

    const fetchParameters = async () => {
        try {
            setLoading(true);
            const res = await api.get(`/api/finance/clearing?sector=${currentSector}`);
            setParameters(res.data);
        } catch (err) {
            logger.error(err);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchParameters();
    }, [currentSector]);

    const handleInitialize = async () => {
        try {
            setInitializing(true);
            await api.post('/finance/clearing/init', { sector: currentSector });
            await fetchParameters();
        } catch (err) {
            logger.error(err);
            alert('Failed to initialize unit');
        } finally {
            setInitializing(false);
        }
    };

    const handleUpdate = async (id: string, updates: any) => {
        try {
            await api.put(`/api/finance/clearing/${id}`, updates);
            await fetchParameters(); // Refresh to ensure sync
        } catch (err) {
            logger.error(err);
            alert('Failed to update parameter');
        }
    };

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-6 bg-neutral-950/80 backdrop-blur-md animate-in fade-in duration-300">
            <div className="bg-white dark:bg-neutral-800 w-full max-w-2xl rounded-[3rem] shadow-2xl border border-neutral-200 dark:border-neutral-700 overflow-hidden relative">
                <div className="p-10">
                    <div className="flex items-center justify-between mb-10">
                        <div>
                            <h3 className="text-2xl font-black italic tracking-tighter uppercase mb-1">Unit Parameters</h3>
                            <p className="text-xs font-bold text-neutral-400 uppercase tracking-widest italic">Clearing Configuration for {currentSector}</p>
                        </div>
                        <button onClick={onClose} className="p-3 bg-neutral-100 dark:bg-neutral-900 rounded-full text-neutral-400 hover:text-error transition">
                            <X size={20} />
                        </button>
                    </div>

                    {loading ? (
                        <div className="text-center py-20">Loading Configuration...</div>
                    ) : parameters.length === 0 ? (
                        <div className="text-center py-16 space-y-6">
                            <div className="inline-flex items-center justify-center w-20 h-20 rounded-full bg-primary/10 text-primary mb-4">
                                <Zap className="w-10 h-10" />
                            </div>
                            <h4 className="text-xl font-black italic uppercase">Unit Not Initialized</h4>
                            <p className="text-sm text-neutral-500 max-w-md mx-auto">
                                This unit ({currentSector}) does not have clearing parameters defined. Initialize to set defaults.
                            </p>
                            <button
                                onClick={handleInitialize}
                                disabled={initializing}
                                className="px-8 py-4 bg-primary text-white rounded-2xl text-xs font-black uppercase tracking-widest hover:bg-primary/90 transition shadow-lg shadow-primary/20 flex items-center gap-2 mx-auto disabled:opacity-50"
                            >
                                <RefreshCw className={`w-4 h-4 ${initializing ? 'animate-spin' : ''}`} />
                                {initializing ? 'Initializing...' : 'Initialize Unit Protocols'}
                            </button>
                        </div>
                    ) : (
                        <div className="space-y-6">
                            {parameters.map((param) => (
                                <div key={param._id} className="p-6 bg-neutral-50 dark:bg-neutral-900 rounded-[2rem] border border-neutral-100 dark:border-neutral-700 flex items-center justify-between group hover:border-primary/20 transition-all">
                                    <div>
                                        <p className="text-[10px] font-black text-neutral-400 uppercase tracking-widest mb-1">Clearing Type</p>
                                        <h4 className="text-lg font-black italic uppercase tracking-tight">{param.type}</h4>
                                    </div>

                                    <div className="flex items-center gap-8">
                                        <div>
                                            <p className="text-[9px] font-black text-neutral-400 uppercase tracking-widest mb-1">Clearing Days</p>
                                            <div className="flex items-center gap-2">
                                                <input
                                                    type="number"
                                                    value={param.clearingDays}
                                                    onChange={(e) => handleUpdate(param._id, { clearingDays: parseInt(e.target.value) })}
                                                    className="w-16 px-3 py-1 bg-white dark:bg-neutral-800 border border-neutral-200 dark:border-neutral-700 rounded-lg text-sm font-black text-center focus:ring-2 focus:ring-primary/20 outline-none"
                                                />
                                                <span className="text-xs font-bold text-neutral-500 uppercase">Days</span>
                                            </div>
                                        </div>

                                        <div className="flex items-center gap-2">
                                            <button
                                                onClick={() => handleUpdate(param._id, { holidaysIncluded: !param.holidaysIncluded })}
                                                className={`w-12 h-6 rounded-full transition-colors relative ${param.holidaysIncluded ? 'bg-success' : 'bg-neutral-300 dark:bg-neutral-700'}`}
                                            >
                                                <span className={`absolute top-1 left-1 w-4 h-4 rounded-full bg-white transition-transform ${param.holidaysIncluded ? 'translate-x-6' : ''}`} />
                                            </button>
                                            <span className="text-[9px] font-black text-neutral-400 uppercase tracking-widest">Incl. Holidays</span>
                                        </div>
                                    </div>
                                </div>
                            ))}

                            <div className="flex justify-end pt-4">
                                <div className="inline-flex items-center gap-2 px-4 py-2 bg-success/10 text-success rounded-xl text-[10px] font-black uppercase tracking-widest">
                                    <ShieldCheck className="w-4 h-4" /> System Synchronized
                                </div>
                            </div>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

export default ClearingParameters;

import { logger } from '@/shared/lib/logger';
import React, { useState, useEffect } from 'react';
import { X, Calendar, IndianRupee, CheckCircle2, AlertTriangle, Loader2 } from 'lucide-react';
import api from "@/shared/api/api";
import { formatCurrency } from "@/shared/lib/utils/helpers";

interface DayEndModalProps {
    onClose: () => void;
}

interface DayEndSummary {
    openingCash: number;
    cashSales: number;
    cashExpenses: number;
    expectedCash: number;
    pendingCheques: any[];
    supplierAlerts: any[];
}

const DayEndModal: React.FC<DayEndModalProps> = ({ onClose }) => {
    const [loading, setLoading] = useState(true);
    const [saving, setSaving] = useState(false);
    const [summary, setSummary] = useState<DayEndSummary | null>(null);
    const [physicalCash, setPhysicalCash] = useState('');
    const [variance, setVariance] = useState(0);
    const [notes, setNotes] = useState('');

    useEffect(() => {
        fetchSummary();
    }, []);

    useEffect(() => {
        if (summary && physicalCash) {
            setVariance(parseFloat(physicalCash) - summary.expectedCash);
        }
    }, [physicalCash, summary]);

    const fetchSummary = async () => {
        try {
            const response = await api.get('/cashbank/day-end/summary');
            setSummary(response.data);
        } catch (error) {
            logger.error('Failed to fetch day end summary:', error);
        } finally {
            setLoading(false);
        }
    };

    const handleSave = async () => {
        if (!summary) return;
        setSaving(true);
        try {
            await api.post('/cashbank/day-end/save', {
                date: new Date().toISOString(),
                openingCash: summary.openingCash,
                cashSales: summary.cashSales,
                cashExpenses: summary.cashExpenses,
                expectedCash: summary.expectedCash,
                physicalCash: parseFloat(physicalCash) || 0,
                variance,
                notes
            });
            onClose();
        } catch (error) {
            logger.error('Failed to save day end:', error);
        } finally {
            setSaving(false);
        }
    };

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-6 bg-neutral-950/80 backdrop-blur-md animate-in fade-in duration-300">
            <div className="bg-white dark:bg-neutral-800 w-full max-w-2xl rounded-[3rem] shadow-2xl border border-neutral-200 dark:border-neutral-700 overflow-hidden relative">
                <div className="p-10">
                    <div className="flex items-center justify-between mb-10">
                        <div>
                            <h3 className="text-2xl font-black italic tracking-tighter uppercase mb-1">Day End Reconciliation</h3>
                            <p className="text-xs font-bold text-neutral-400 uppercase tracking-widest italic flex items-center gap-2">
                                <Calendar className="w-4 h-4" /> {new Date().toLocaleDateString('en-IN', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}
                            </p>
                        </div>
                        <button onClick={onClose} className="p-3 bg-neutral-100 dark:bg-neutral-900 rounded-full text-neutral-400 hover:text-error transition">
                            <X size={20} />
                        </button>
                    </div>

                    {loading ? (
                        <div className="flex items-center justify-center py-20">
                            <Loader2 className="w-8 h-8 animate-spin text-primary" />
                        </div>
                    ) : summary ? (
                        <div className="space-y-8">
                            {/* Cash Flow Summary */}
                            <div className="grid grid-cols-2 gap-4">
                                <div className="p-6 bg-success/10 rounded-[2rem] border border-success/20">
                                    <p className="text-[9px] font-black text-success uppercase tracking-widest mb-1">Cash Sales (In)</p>
                                    <p className="text-2xl font-black italic text-success">₹{formatCurrency(summary.cashSales)}</p>
                                </div>
                                <div className="p-6 bg-error/10 rounded-[2rem] border border-error/20">
                                    <p className="text-[9px] font-black text-error uppercase tracking-widest mb-1">Cash Expenses (Out)</p>
                                    <p className="text-2xl font-black italic text-error">₹{formatCurrency(summary.cashExpenses)}</p>
                                </div>
                            </div>

                            {/* Expected vs Physical */}
                            <div className="p-6 bg-neutral-50 dark:bg-neutral-900 rounded-[2rem] border border-neutral-100 dark:border-neutral-800">
                                <div className="flex items-center justify-between mb-6">
                                    <div>
                                        <p className="text-[9px] font-black text-neutral-400 uppercase tracking-widest mb-1">Expected Cash in Drawer</p>
                                        <p className="text-3xl font-black italic text-primary">₹{formatCurrency(summary.expectedCash)}</p>
                                    </div>
                                    <IndianRupee className="w-12 h-12 text-neutral-200 dark:text-neutral-700" />
                                </div>

                                <div className="space-y-2">
                                    <label className="text-[10px] font-black text-neutral-400 uppercase tracking-[0.2em] pl-1">Actual Physical Cash Count</label>
                                    <input
                                        type="number"
                                        value={physicalCash}
                                        onChange={e => setPhysicalCash(e.target.value)}
                                        className="w-full px-5 py-4 bg-white dark:bg-neutral-800 border border-neutral-200 dark:border-neutral-700 rounded-2xl text-xl font-black italic outline-none focus:ring-4 focus:ring-primary/10 transition-all font-mono"
                                        placeholder="Enter counted cash..."
                                    />
                                </div>

                                {physicalCash && (
                                    <div className={`mt-4 p-4 rounded-xl flex items-center gap-3 ${variance >= 0 ? 'bg-success/10 text-success' : 'bg-error/10 text-error'}`}>
                                        {variance >= 0 ? <CheckCircle2 className="w-5 h-5" /> : <AlertTriangle className="w-5 h-5" />}
                                        <span className="text-sm font-black uppercase tracking-widest">
                                            Variance: ₹{formatCurrency(Math.abs(variance))} {variance >= 0 ? 'Surplus' : 'Shortage'}
                                        </span>
                                    </div>
                                )}
                            </div>

                            {/* Pending Cheques */}
                            {summary.pendingCheques.length > 0 && (
                                <div className="p-6 bg-warning/10 rounded-[2rem] border border-warning/20">
                                    <p className="text-[9px] font-black text-warning uppercase tracking-widest mb-3">Cheques Pending Clearance Today</p>
                                    <div className="space-y-2">
                                        {summary.pendingCheques.map((chq: any, idx: number) => (
                                            <div key={idx} className="flex items-center justify-between text-xs font-bold text-warning">
                                                <span>{chq.payee || chq.number}</span>
                                                <span>₹{formatCurrency(chq.amount)}</span>
                                            </div>
                                        ))}
                                    </div>
                                </div>
                            )}

                            {/* Notes */}
                            <div className="space-y-2">
                                <label className="text-[10px] font-black text-neutral-400 uppercase tracking-[0.2em] pl-1">Reconciliation Notes</label>
                                <textarea
                                    value={notes}
                                    onChange={e => setNotes(e.target.value)}
                                    rows={2}
                                    className="w-full px-5 py-4 bg-neutral-50 dark:bg-neutral-900 border border-neutral-100 dark:border-neutral-700 rounded-2xl text-sm font-bold outline-none focus:ring-4 focus:ring-primary/10 transition-all resize-none"
                                    placeholder="Any discrepancies or notes..."
                                />
                            </div>

                            {/* Submit */}
                            <button
                                onClick={handleSave}
                                disabled={saving || !physicalCash}
                                className="w-full py-5 bg-neutral-950 text-white rounded-3xl text-[10px] font-black uppercase tracking-[0.3em] shadow-2xl hover:bg-neutral-900 transition-all flex items-center justify-center gap-4 border border-neutral-700 disabled:opacity-50"
                            >
                                <CheckCircle2 className="w-5 h-5 text-primary" />
                                {saving ? 'Saving...' : 'Close Day & Save Reconciliation'}
                            </button>
                        </div>
                    ) : (
                        <div className="text-center py-20 text-neutral-400">
                            Failed to load summary. Please try again.
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

export default DayEndModal;

