                                                {isBorrowed ? <Car className="w-6 h-6" /> : <Gift className="w-6 h-6" />}
                                            </div>
                                            <div>
                                                <h3 className="text-lg font-bold tracking-tight">{loan.lenderName}</h3>
                                                <p className="text-[10px] font-black uppercase tracking-widest text-neutral-500">{loan.loanType}</p>
                                            </div>
                                        </div>
                                        <div className="text-right">
                                            <p className="text-lg font-black tracking-tight tabular-nums">
                                                ₹{loan.balanceRemaining.toLocaleString('en-IN')}
                                                <span className="text-[10px] text-neutral-500 font-bold ml-1">/₹{loan.loanAmount.toLocaleString('en-IN')}</span>
                                            </p>
                                        </div>
                                    </div>

                                    {/* Progress Bar */}
                                    <div className="space-y-2 mb-6">
                                        <div className="flex justify-between text-[10px] font-black uppercase tracking-widest text-neutral-500">
                                            <span>Today</span>
                                            <span>30 Jun 2026</span>
                                        </div>
                                        <div className="h-4 bg-neutral-800 rounded-full overflow-hidden relative">
                                            <div
                                                className={`h-full rounded-full transition-all duration-1000 flex items-center justify-end pr-2 text-[8px] font-black ${isBorrowed ? 'bg-fuchsia-500/30' : 'bg-rose-500/50 text-white'}`}
                                                style={{ width: `${progress}%` }}
                                            >
                                                {progress}%
                                            </div>
                                        </div>
                                    </div>

                                    {/* Footer Nudge */}
                                    <p className="text-xs font-bold text-neutral-400">
                                        {isBorrowed ? `Pay ₹${dailyPaydown}/day` : `Receive ₹${dailyPaydown}/day`} in the next 365 days.
                                    </p>
                                </div>
                            );
                        })}
                    </div>

                    {/* Floating FAB for Loans */}
                    <div className="fixed bottom-24 right-8 z-50">
                        <button
                            onClick={() => setShowAddLoan(true)}
                            className="w-14 h-14 bg-emerald-500/20 hover:bg-emerald-500/30 text-emerald-500 rounded-2xl flex items-center justify-center backdrop-blur-xl border border-emerald-500/30 shadow-2xl transition-all active:scale-95"
                        >
                            <Plus className="w-6 h-6" />
                        </button>
                    </div>

                    {/* App-Style Navigation Footer */}
                    <div className="fixed bottom-10 left-1/2 -translate-x-1/2 flex items-center gap-10 px-10 py-6 bg-neutral-900/80 backdrop-blur-2xl border border-white/10 rounded-[2.5rem] shadow-2xl z-50">
                        <button className="flex flex-col items-center gap-1.5 opacity-40 hover:opacity-100 transition-opacity">
                            <Home className="w-5 h-5" />
                            <span className="text-[8px] font-black uppercase tracking-widest">Overview</span>
                        </button>
                        <button className="flex flex-col items-center gap-1.5 opacity-100 text-emerald-500">
                            <TrendingUp className="w-5 h-5" />
                            <span className="text-[8px] font-black uppercase tracking-widest">Loans</span>
                        </button>
                        <button className="flex flex-col items-center gap-1.5 opacity-40 hover:opacity-100 transition-opacity">
                            <Target className="w-5 h-5" />
                            <span className="text-[8px] font-black uppercase tracking-widest">Goals</span>
                        </button>
                    </div>
                </div>
            </div>
        </Layout>
    );
};

export default LoanAccounts;

import React, { useState, useMemo } from 'react';
import { useSelector } from 'react-redux';
import { RootState } from "@/app/store/store";
import Layout from "@/shared/ui/Layout";
import {
    CircleDollarSign,
    Search,
    AlertCircle,
    CheckCircle2,
    ShieldAlert,
    History,
    FileWarning,
    Receipt,
    Zap,
    Download,
    Eye,
    ChevronRight,
    UserCircle2,
    Building2,
    MoreVertical,
    TrendingDown,
    Plus,
    Clock,
    Info,
} from 'lucide-react';

// --- Types ---

type PettyStatus = 'HEALTHY' | 'LOW_BALANCE' | 'LIMIT_EXCEEDED' | 'AUDIT_REQUIRED';
type RiskLevel = 'CRITICAL' | 'HIGH' | 'MEDIUM' | 'LOW';

interface PettyCashFund {
    id: string;
    name: string;
    branch: string;
    custodian: string;
    opening_balance: number;
    current_balance: number;
    daily_limit: number;
    status: PettyStatus;
    burn_rate_daily: number;
    replenishment_source: string;
}

interface PettyTransaction {
    id: string;
    date: string;
    amount: number;
    type: 'IN' | 'OUT';
    category: string;
    description: string;
    custodian: string;
    receipt: boolean;
    violation?: string;
}

interface PettyAlert {
    fund_id: string;
    issue: string;
    risk_level: RiskLevel;
}

const PettyCash: React.FC = () => {
    const { user } = useSelector((state: RootState) => state.auth);
    const tenant_id = user?.tenantId || 'TEN001';

    const [searchTerm, setSearchTerm] = useState('');
    const [viewMode, setViewMode] = useState<'FUNDS' | 'LEDGER' | 'AUDIT'>('FUNDS');

    // --- Intelligence Engine ---

    const funds: PettyCashFund[] = useMemo(() => [
        {
            id: 'F-001',
            name: 'Chennai Retail - Main Petty',
            branch: 'CHENNAI_OMR',
            custodian: 'Madhan K.',
            opening_balance: 10000,
            current_balance: 1800,
            daily_limit: 2000,
            status: 'LOW_BALANCE',
            burn_rate_daily: 450,
            replenishment_source: 'HDFC Current'
        },
        {
            id: 'F-002',
            name: 'Madurai Godown Operational',
            branch: 'MADURAI_NORTH',
            custodian: 'Manikandan V.',
            opening_balance: 5000,
            current_balance: 4200,
            daily_limit: 1000,
            status: 'HEALTHY',
            burn_rate_daily: 120,
            replenishment_source: 'Main Cash'
        },
        {
            id: 'F-003',
            name: 'HQ Administrative Fund',
            branch: 'CORPORATE',
            custodian: 'Sarah J.',
            opening_balance: 25000,
            current_balance: 12500,
            daily_limit: 5000,
            status: 'AUDIT_REQUIRED',
            burn_rate_daily: 1200,
            replenishment_source: 'ICICI Current'
        }
    ], []);

    const recentTransactions: PettyTransaction[] = useMemo(() => [
        { id: 'T-998', date: '2026-01-11 16:45', amount: 450, type: 'OUT', category: 'Travel', description: 'Auto fare to TNVAT office', custodian: 'Madhan K.', receipt: true },
        { id: 'T-999', date: '2026-01-11 15:20', amount: 1500, type: 'OUT', category: 'Repairs', description: 'AC Filter cleaning', custodian: 'Madhan K.', receipt: false, violation: 'MISSING_RECEIPT' },
        { id: 'T-1000', date: '2026-01-11 14:10', amount: 120, type: 'OUT', category: 'Tea/Snacks', description: 'Tea for guests', custodian: 'Madhan K.', receipt: true },
        { id: 'T-1001', date: '2026-01-11 11:30', amount: 200, type: 'OUT', category: 'Stationery', description: 'A4 Paper bundle', custodian: 'Sarah J.', receipt: true },
        { id: 'T-1002', date: '2026-01-11 10:05', amount: 500, type: 'OUT', category: 'Repairs', description: 'Door handle fix', custodian: 'Sarah J.', receipt: false, violation: 'MISSING_RECEIPT' },
        { id: 'T-1003', date: '2026-01-10 17:30', amount: 2100, type: 'OUT', category: 'Fuel', description: 'Generator diesel', custodian: 'Madhan K.', receipt: true, violation: 'DAILY_LIMIT_EXCEEDED' },
    ], []);

    const alerts: PettyAlert[] = useMemo(() => [
        { fund_id: 'F-001', issue: '3 expenses without receipts in last 2 days', risk_level: 'HIGH' },
        { fund_id: 'F-003', issue: 'Abnormal withdrawal frequency detected', risk_level: 'MEDIUM' },
        { fund_id: 'F-001', issue: 'Daily limit exceeded by ₹100 yesterday', risk_level: 'LOW' }
    ], []);

    // Filter Logic
    const filteredFunds = useMemo(() => {
        return funds.filter(f => f.name.toLowerCase().includes(searchTerm.toLowerCase()) || f.branch.toLowerCase().includes(searchTerm.toLowerCase()));
    }, [funds, searchTerm]);

    const metrics = useMemo(() => {
        const totalOut = recentTransactions.filter(t => t.type === 'OUT').reduce((acc, t) => acc + t.amount, 0);
        const violations = recentTransactions.filter(t => t.violation).length;
        return {
            totalOperationalSpend: totalOut,
            activeFunds: funds.length,
            violationRate: Math.round((violations / recentTransactions.length) * 100),
            savingsAgentAdvice: 'Consolidate stationery buys to monthly for 15% discount.'
