                                                </div>
                                            </div>
                                        </div>

                                        {fund.status === 'LOW_BALANCE' && (
                                            <div className="mt-4 p-3 bg-primary/5 border border-primary/10 rounded-xl flex items-center justify-between animate-pulse">
                                                <div className="flex items-center gap-3">
