                                        <div className="flex justify-between mt-1">
                                            <span className="text-[10px] text-slate-500">{paidPct.toFixed(1)}% paid</span>
                                            <span className="text-[10px] text-slate-500">₹{fmt(loan.pending)} pending · EMI ₹{fmt(loan.emi)}/mo</span>
