import { logger } from '@/shared/lib/logger';
import React, { useState, useRef, useEffect } from 'react';
import { Search, Save, AlertCircle, CheckCircle, Package, ArrowRight, Printer } from 'lucide-react';
import axios from 'axios';
import { toast } from 'react-toastify';
import { useConfig } from "@/contexts/ConfigContext";

interface Item {
    _id: string;
    name: string;
    sku: string;
    sellingPrice: number;
    stockQty: number;
    category: string;
}

const BatchPriceUpdate: React.FC = () => {
    const { tenantId } = useConfig();
    const apiUrl = (import.meta as any).env.VITE_BACKEND_URL;
    const [sku, setSku] = useState('');
    const [item, setItem] = useState<Item | null>(null);
    const [newPrice, setNewPrice] = useState<string>('');
    const [loading, setLoading] = useState(false);
    const [updating, setUpdating] = useState(false);

    const skuInputRef = useRef<HTMLInputElement>(null);
    const priceInputRef = useRef<HTMLInputElement>(null);

    // Auto-focus SKU input on mount
    useEffect(() => {
        skuInputRef.current?.focus();
    }, []);

    const handleScan = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!sku.trim()) return;

        setLoading(true);
        setItem(null);
        setNewPrice('');

        try {
            // We search by SKU. The getAllItems endpoint supports search.
            // But ideally we want exact match. 
            // The existing API /api/inventory?search=sku might return multiple.
            // Let's assume we can use the search query.
            const token = localStorage.getItem('token');
            const res = await axios.get(`${apiUrl}/inventory?search=${encodeURIComponent(sku)}&limit=1`, {
                headers: { Authorization: `Bearer ${token}`, 'x-tenant-id': tenantId }
            });

            if (res.data.items && res.data.items.length > 0) {
                // Check for exact SKU match if possible, or take the first one
                const found = res.data.items.find((i: Item) => i.sku.toLowerCase() === sku.toLowerCase()) || res.data.items[0];
                setItem(found);

                // Focus price input
                setTimeout(() => priceInputRef.current?.focus(), 100);
            } else {
                toast.error('Item not found');
                setItem(null);
            }
        } catch (err) {
            logger.error('Scan Error:', err);
            toast.error('Error fetching item');
        } finally {
            setLoading(false);
        }
    };

    const handleUpdate = async () => {
        if (!item || !newPrice) return;

        setUpdating(true);
        try {
            const token = localStorage.getItem('token');
            const res = await axios.post(`${apiUrl}/inventory/batch-price-update`, {
                sku: item.sku,
                newPrice: parseFloat(newPrice)
            }, {
                headers: { Authorization: `Bearer ${token}`, 'x-tenant-id': tenantId }
            });

            toast.success(res.data.message);

            // Reset for next scan
            setSku('');
            setItem(null);
            setNewPrice('');
            skuInputRef.current?.focus();

        } catch (err: any) {
            logger.error('Update Error:', err);
            toast.error(err.response?.data?.message || 'Error updating price');
        } finally {
            setUpdating(false);
        }
    };

    return (
        <div className="p-6 max-w-4xl mx-auto">
            <div className="mb-8">
                <h1 className="text-2xl font-bold text-gray-800 dark:text-white flex items-center gap-2">
                    <Printer className="w-8 h-8 text-emerald-500" />
                    Batch Price Update
                </h1>
                <p className="text-gray-500 dark:text-gray-400 mt-1">
                    Scan a barcode, update the price, and automatically queue labels for reprinting.
                </p>
            </div>

            <div className="grid grid-cols-1 gap-6">
                {/* Scan Section */}
                <div className="bg-white dark:bg-gray-800 p-6 rounded-xl shadow-sm border border-gray-200 dark:border-gray-700">
                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                        Scan Barcode / Enter SKU
                    </label>
                    <form onSubmit={handleScan} className="flex gap-4">
                        <div className="relative flex-1">
                            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-5 h-5" />
                            <input
                                ref={skuInputRef}
                                type="text"
                                value={sku}
                                onChange={(e) => setSku(e.target.value)}
                                placeholder="Scan or type SKU..."
                                className="w-full pl-10 pr-4 py-3 bg-gray-50 dark:bg-gray-900 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-emerald-500 outline-none transition-all"
                            />
                        </div>
                        <button
                            type="submit"
                            disabled={loading}
                            className="bg-emerald-600 hover:bg-emerald-700 text-white px-6 py-3 rounded-lg font-medium transition-colors disabled:opacity-50 flex items-center gap-2"
                        >
                            {loading ? 'Scanning...' : (
                                <>
                                    Find Item <ArrowRight className="w-4 h-4" />
                                </>
                            )}
                        </button>
                    </form>
                </div>

                {/* Item Details & Update Section */}
                {item && (
                    <div className="bg-white dark:bg-gray-800 p-6 rounded-xl shadow-lg border-2 border-emerald-500/20 animation-fade-in">
                        <div className="flex items-start justify-between mb-6">
                            <div>
                                <h3 className="text-xl font-bold text-gray-900 dark:text-white">{item.name}</h3>
                                <p className="text-sm text-gray-500 dark:text-gray-400 mt-1">
                                    SKU: <span className="font-mono bg-gray-100 dark:bg-gray-700 px-2 py-0.5 rounded">{item.sku}</span>
                                </p>
                            </div>
                            <div className="text-right">
                                <div className="text-sm text-gray-500 dark:text-gray-400">Current Stock</div>
                                <div className="text-2xl font-bold text-gray-800 dark:text-white flex items-center justify-end gap-2">
                                    <Package className="w-5 h-5 text-emerald-500" />
                                    {item.stockQty}
                                </div>
                            </div>
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-8 items-end bg-gray-50 dark:bg-gray-900/50 p-6 rounded-xl">
                            <div>
                                <label className="block text-sm font-medium text-gray-500 dark:text-gray-400 mb-1">
                                    Current Selling Price
                                </label>
                                <div className="text-2xl font-bold text-gray-400 line-through">
                                    ₹{item.sellingPrice}
                                </div>
                            </div>

                            <div>
                                <label className="block text-sm font-bold text-emerald-600 dark:text-emerald-400 mb-2">
                                    New Selling Price (₹)
                                </label>
                                <input
                                    ref={priceInputRef}
                                    type="number"
                                    value={newPrice}
                                    onChange={(e) => setNewPrice(e.target.value)}
                                    onKeyDown={(e) => e.key === 'Enter' && handleUpdate()}
                                    placeholder="0.00"
                                    className="w-full text-2xl font-bold text-gray-900 dark:text-white bg-white dark:bg-gray-800 border-2 border-emerald-500 rounded-lg px-4 py-3 focus:outline-none focus:ring-4 focus:ring-emerald-500/20"
                                />
                            </div>
                        </div>

                        <div className="mt-8 flex justify-end gap-4">
                            <button
                                onClick={() => {
                                    setItem(null);
                                    setSku('');
                                    setNewPrice('');
                                    skuInputRef.current?.focus();
                                }}
                                className="px-6 py-3 text-gray-600 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg font-medium transition-colors"
                            >
                                Cancel
                            </button>
                            <button
                                onClick={handleUpdate}
                                disabled={updating || !newPrice}
                                className="bg-emerald-600 hover:bg-emerald-700 text-white px-8 py-3 rounded-lg font-bold shadow-lg shadow-emerald-600/30 flex items-center gap-2 transform active:scale-95 transition-all disabled:opacity-50 disabled:cursor-not-allowed"
                            >
                                {updating ? 'Updating...' : (
                                    <>
                                        <Save className="w-5 h-5" />
                                        Update Price & Queue Reprint
                                    </>
                                )}
                            </button>
                        </div>

                        <div className="mt-4 flex items-center gap-2 text-sm text-amber-600 dark:text-amber-500 bg-amber-50 dark:bg-amber-900/20 p-3 rounded-lg">
                            <AlertCircle className="w-4 h-4 flex-shrink-0" />
                            This will update the global price for this item and add all {item.stockQty} units to the label reprint queue.
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
};

export default BatchPriceUpdate;

import { logger } from '@/shared/lib/logger';
import React, { useState, useEffect, useCallback } from 'react';
import {
    Layers,
    Search,
    Download,
    FolderPlus,
    RefreshCw,
    AlertTriangle,
    Loader2,
    ChevronLeft,
    ChevronRight,
    ArrowUpDown,
    ArrowUp,
    ArrowDown,
    Filter,
    CheckCircle2,
    ShieldCheck,
    Package,
    TrendingUp,
    BarChart3,
    Edit,
    Trash2
} from 'lucide-react';
import { useSelector } from 'react-redux';
import { RootState } from "@/app/store/store";
import api from "@/shared/api/api";

interface Category {
    id: string;
    name: string;
    description?: string;
    color: string;
    itemCount: number;
    stockValue: number;
    isActive: boolean;
    riskFlag: 'HEALTHY' | 'OVERSTOCKED' | 'LOW_TURNOVER';
    gstCompliance: 'OK' | 'MIXED';
    pricingHealth: 'GOOD' | 'LOW_MARGIN' | 'PROMO_NEEDED';
    gstRate: number;
    defaultUnit?: string;
}

interface Stats {
    totalCategories: number;
    totalItems: number;
    totalStockValue: number;
    avgItemsPerCategory: number;
}

interface ApiResponse<T> {
    success: boolean;
    data: T;
    stats?: Stats;
    meta?: {
        page: number;
        limit: number;
        total: number;
        totalPages: number;
    };
    message?: string;
}

interface CategoriesResponse extends ApiResponse<Category[]> { }

const CategoryManager: React.FC = () => {
    // Data State
    const [categories, setCategories] = useState<Category[]>([]);
    const [stats, setStats] = useState<Stats | null>(null);
    const [isLoading, setIsLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);

    // Filter/Sort Configuration
    const [search, setSearch] = useState('');
    const [debouncedSearch, setDebouncedSearch] = useState('');
    const [page, setPage] = useState(1);
    const [totalPages, setTotalPages] = useState(1);
    const [sortBy, setSortBy] = useState<keyof Category>('stockValue');
    const [order, setOrder] = useState<'asc' | 'desc'>('desc');
    const [selectedItems, setSelectedItems] = useState<string[]>([]);

    // Sector Context
    const { tenants } = useSelector((state: RootState) => state.tenant);
    const { user } = useSelector((state: RootState) => state.auth);
    const currentTenant = tenants.find(t => t.id === user?.tenantId);
    const sector = currentTenant?.sector || 'General';

    // Debounce Search Logic
    useEffect(() => {
        const timer = setTimeout(() => {
            setDebouncedSearch(search);
            setPage(1);
        }, 300);
        return () => clearTimeout(timer);
    }, [search]);

    // Data Fetching
    const fetchData = useCallback(async () => {
        setIsLoading(true);
        setError(null);
        try {
            const response = await api.get<CategoriesResponse>('/inventory/categories', {
                params: {
                    page,
                    limit: 25,
                    search: debouncedSearch,
                    sortBy,
                    order,
                    sector
                }
            });

            const catData = response.data;

            if (catData.success) {
                setCategories(catData.data);
                if (catData.meta) {
                    setTotalPages(catData.meta.totalPages);
                }
                if (catData.stats) {
                    setStats(catData.stats);
                }
            } else {
                throw new Error(catData.message || 'Failed to fetch categories');
            }

        } catch (err: any) {
            logger.error(err);
            const message = err.response?.data?.message || err.message || 'Network Error';
            setError(message);
        } finally {
            setIsLoading(false);
        }
    }, [page, debouncedSearch, sortBy, order, sector]);

    useEffect(() => {
        fetchData();
    }, [fetchData]);

    // Handlers
    const handleSort = (field: keyof Category) => {
        if (sortBy === field) {
            setOrder(prev => prev === 'asc' ? 'desc' : 'asc');
        } else {
            setSortBy(field);
            setOrder('desc');
        }
    };

    const toggleSelectAll = () => {
        if (selectedItems.length === categories.length) {
            setSelectedItems([]);
        } else {
            setSelectedItems(categories.map(c => c.id));
        }
    };

    const toggleSelectItem = (id: string) => {
        setSelectedItems(prev => prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]);
    };

    const refreshData = () => {
        setPage(1);
        fetchData();
    };

    // Render Helpers
    const getSortIcon = (field: keyof Category) => {
        if (sortBy !== field) return <ArrowUpDown className="w-3 h-3 text-slate-400 opacity-0 group-hover:opacity-50" />;
        return order === 'asc'
            ? <ArrowUp className="w-3 h-3 text-indigo-600" />
            : <ArrowDown className="w-3 h-3 text-indigo-600" />;
    };

    if (error) {
        return (
            <div className="flex flex-col items-center justify-center p-12 bg-slate-50 border border-slate-200 rounded-2xl h-[500px]">
                <div className="w-12 h-12 bg-rose-50 text-rose-600 rounded-xl flex items-center justify-center mb-4">
                    <AlertTriangle className="w-6 h-6" />
                </div>
                <h3 className="text-lg font-bold text-slate-900 mb-2">Connection Failed</h3>
                <p className="text-slate-500 mb-6 text-center max-w-md">
                    Unable to retrieve category data. Please ensure the backend server is running and accessible.
                </p>
                <div className="flex gap-3">
                    <button
                        onClick={fetchData}
                        className="px-4 py-2 bg-indigo-600 hover:bg-indigo-700 text-white rounded-lg font-bold text-sm flex items-center gap-2 transition-colors"
                    >
                        <RefreshCw className="w-4 h-4" /> Retry Connection
                    </button>
                </div>
            </div>
        );
    }

    return (
        <div className="space-y-6 animate-in fade-in duration-500">
            {/* Header Section */}
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                <div>
                    <h1 className="text-2xl font-bold text-slate-900 flex items-center gap-2">
                        <Layers className="w-6 h-6 text-indigo-600" />
                        Category Management
                    </h1>
                    <p className="text-slate-500 text-sm mt-1">
                        Enterprise taxonomy control and inventory grouping.
                    </p>
                </div>
                <div className="flex gap-2">
                    <button className="px-4 py-2 bg-white border border-slate-200 text-slate-600 hover:bg-slate-50 rounded-lg text-sm font-bold flex items-center gap-2 transition-colors shadow-sm">
                        <Download className="w-4 h-4" /> Export
                    </button>
                    <button className="px-4 py-2 bg-indigo-600 text-white hover:bg-indigo-700 rounded-lg text-sm font-bold flex items-center gap-2 shadow-md shadow-indigo-600/20 transition-all active:scale-95">
                        <FolderPlus className="w-4 h-4" /> New Category
                    </button>
                </div>
            </div>

            {/* KPI Stats */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
                {[
                    { label: 'Total Categories', value: stats?.totalCategories.toLocaleString() || '-', icon: Layers, color: 'text-indigo-600', bg: 'bg-indigo-50' },
                    { label: 'Total Items SKUs', value: stats?.totalItems.toLocaleString() || '-', icon: Package, color: 'text-emerald-600', bg: 'bg-emerald-50' },
                    { label: 'Stock Valuation', value: stats ? `₹${(stats.totalStockValue / 1000000).toFixed(2)}M` : '-', icon: TrendingUp, color: 'text-amber-600', bg: 'bg-amber-50' },
                    { label: 'Avg Items / Cat', value: stats?.avgItemsPerCategory.toLocaleString() || '-', icon: BarChart3, color: 'text-blue-600', bg: 'bg-blue-50' }
                ].map((stat, idx) => (
                    <div key={idx} className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-4">
                        <div className={`p-3 rounded-xl ${stat.bg}`}>
                            <stat.icon className={`w-6 h-6 ${stat.color}`} />
                        </div>
                        <div>
                            <p className="text-xs font-bold uppercase tracking-wider text-slate-500 mb-0.5">{stat.label}</p>
                            <h3 className="text-2xl font-bold text-slate-900">{stat.value}</h3>
                        </div>
                    </div>
                ))}
            </div>

            {/* Main Content Card */}
            <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden">
                {/* Controls Toolbar */}
                <div className="p-4 border-b border-slate-200 flex flex-col md:flex-row gap-4 items-center justify-between bg-slate-50/50">
                    <div className="relative w-full md:w-80">
                        <input
                            type="text"
                            placeholder="Search categories..."
                            className="w-full pl-10 pr-4 py-2 bg-white border border-slate-200 rounded-lg text-sm font-medium focus:ring-2 focus:ring-indigo-500 outline-none shadow-sm transition-all"
                            value={search}
                            onChange={(e) => setSearch(e.target.value)}
                        />
                        <Search className="w-4 h-4 text-slate-400 absolute left-3 top-2.5" />
                        {isLoading && search && (
                            <Loader2 className="w-3 h-3 text-indigo-600 absolute right-3 top-3 animate-spin" />
                        )}
                    </div>
                    <div className="flex items-center gap-3">
                        <button className="p-2 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg transition-colors" onClick={refreshData} title="Refresh Data">
                            <RefreshCw className={`w-4 h-4 ${isLoading ? 'animate-spin' : ''}`} />
                        </button>
                        <div className="h-6 w-px bg-slate-200 mx-1" />
                        <button className="flex items-center gap-2 px-3 py-1.5 bg-white border border-slate-200 rounded-lg text-xs font-bold text-slate-600 hover:bg-slate-50 shadow-sm">
                            <Filter className="w-3.5 h-3.5" /> Filters
                        </button>
                    </div>
                </div>

                {/* Data Table */}
                <div className="overflow-x-auto">
                    <table className="w-full text-left text-sm">
                        <thead className="bg-slate-50 text-slate-500 font-bold uppercase text-xs tracking-wider border-b border-slate-200">
                            <tr>
                                <th className="px-6 py-4 w-12 text-center">
                                    <input
                                        type="checkbox"
                                        className="rounded border-slate-300 text-indigo-600 focus:ring-indigo-500"
                                        checked={categories.length > 0 && selectedItems.length === categories.length}
                                        onChange={toggleSelectAll}
                                        disabled={isLoading}
                                    />
                                </th>
                                {[
                                    { id: 'name', label: 'Category Name', align: 'left' },
                                    { id: 'itemCount', label: 'Total Items', align: 'center' },
                                    { id: 'stockValue', label: 'Stock Value', align: 'right' },
                                    { id: 'defaultUnit', label: 'Unit', align: 'center' },
                                    { id: 'gstRate', label: 'GST %', align: 'center' },
                                    { id: 'riskFlag', label: 'Risk Status', align: 'center' },
                                    { id: 'pricingHealth', label: 'Pricing Health', align: 'left' },
                                ].map((col) => (
                                    <th
                                        key={col.id}
                                        className={`px-6 py-4 cursor-pointer group hover:bg-slate-100 transition-colors text-${col.align}`}
                                        onClick={() => handleSort(col.id as keyof Category)}
                                    >
                                        <div className={`flex items-center gap-1 ${col.align === 'right' ? 'justify-end' : col.align === 'center' ? 'justify-center' : 'justify-start'}`}>
                                            {col.label}
                                            {getSortIcon(col.id as keyof Category)}
                                        </div>
                                    </th>
                                ))}
                                <th className="px-6 py-4 text-right">Actions</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-100">
                            {isLoading ? (
                                [...Array(5)].map((_, i) => (
                                    <tr key={i} className="animate-pulse">
                                        <td className="px-6 py-4"><div className="h-4 w-4 bg-slate-200 rounded" /></td>
                                        <td className="px-6 py-4"><div className="h-4 w-32 bg-slate-200 rounded" /></td>
                                        <td className="px-6 py-4"><div className="h-4 w-12 bg-slate-200 rounded mx-auto" /></td>
                                        <td className="px-6 py-4"><div className="h-4 w-20 bg-slate-200 rounded ml-auto" /></td>
                                        <td className="px-6 py-4"><div className="h-4 w-8 bg-slate-200 rounded mx-auto" /></td>
                                        <td className="px-6 py-4"><div className="h-6 w-24 bg-slate-200 rounded-full mx-auto" /></td>
                                        <td className="px-6 py-4"><div className="h-4 w-24 bg-slate-200 rounded" /></td>
                                        <td className="px-6 py-4"><div className="h-8 w-16 bg-slate-200 rounded ml-auto" /></td>
                                    </tr>
                                ))
                            ) : categories.length === 0 ? (
                                <tr>
                                    <td colSpan={8} className="px-6 py-24 text-center text-slate-500">
                                        <div className="w-16 h-16 bg-slate-50 rounded-full flex items-center justify-center mx-auto mb-4">
                                            <Search className="w-8 h-8 text-slate-300" />
                                        </div>
                                        <h4 className="text-lg font-bold text-slate-700 mb-1">No results found</h4>
                                        <p className="text-sm">Try adjusting your filters or search terms.</p>
                                    </td>
                                </tr>
                            ) : (
                                categories.map((cat) => (
                                    <tr key={cat.id} className="hover:bg-slate-50 transition-colors">
                                        <td className="px-6 py-4 text-center">
                                            <input
                                                type="checkbox"
                                                className="rounded border-slate-300 text-indigo-600 focus:ring-indigo-500"
                                                checked={selectedItems.includes(cat.id)}
                                                onChange={() => toggleSelectItem(cat.id)}
                                            />
                                        </td>
                                        <td className="px-6 py-4">
                                            <div className="flex items-center gap-3">
                                                <div className="w-8 h-8 rounded-lg flex items-center justify-center text-white text-xs font-bold shadow-sm" style={{ backgroundColor: cat.color }}>
                                                    {cat.name.charAt(0)}
                                                </div>
                                                <div>
                                                    <p className="font-bold text-slate-900">{cat.name}</p>
                                                    <p className="text-xs text-slate-500 truncate max-w-[200px]">{cat.description || 'No description provided'}</p>
                                                </div>
                                            </div>
                                        </td>
                                        <td className="px-6 py-4 text-center">
                                            <span className={`font-bold ${cat.itemCount > 0 ? 'text-indigo-600' : 'text-slate-400'}`}>
                                                {cat.itemCount.toLocaleString()}
                                            </span>
                                        </td>
                                        <td className="px-6 py-4 text-right font-mono text-slate-600 font-bold">
                                            ₹{cat.stockValue.toLocaleString(undefined, { minimumFractionDigits: 0, maximumFractionDigits: 0 })}
                                        </td>
                                        <td className="px-6 py-4 text-center">
                                            <span className="px-2 py-1 bg-slate-100 text-slate-600 rounded text-xs font-bold border border-slate-200">
                                                {cat.defaultUnit || '-'}
                                            </span>
                                        </td>
                                        <td className="px-6 py-4 text-center">
                                            <span className="px-2 py-1 bg-slate-100 text-slate-600 rounded text-xs font-bold border border-slate-200">
                                                {cat.gstRate}%
                                            </span>
                                        </td>
                                        <td className="px-6 py-4 text-center">
                                            <span className={`px-2 py-1 rounded text-[10px] font-bold uppercase border ${cat.riskFlag === 'HEALTHY' ? 'bg-emerald-50 text-emerald-700 border-emerald-100' :
                                                cat.riskFlag === 'OVERSTOCKED' ? 'bg-amber-50 text-amber-700 border-amber-100' :
                                                    'bg-rose-50 text-rose-700 border-rose-100'
                                                }`}>
                                                {cat.riskFlag.replace('_', ' ')}
                                            </span>
                                        </td>
                                        <td className="px-6 py-4">
                                            <div className="flex items-center gap-1.5">
                                                <div className={`w-2 h-2 rounded-full ${cat.pricingHealth === 'GOOD' ? 'bg-emerald-500' :
                                                    cat.pricingHealth === 'LOW_MARGIN' ? 'bg-amber-500' : 'bg-rose-500'
                                                    }`} />
                                                <span className="text-xs font-medium text-slate-600">
                                                    {cat.pricingHealth.replace('_', ' ')}
                                                </span>
                                            </div>
                                            <div className="flex items-center gap-1 mt-1">
                                                <ShieldCheck className={`w-3 h-3 ${cat.gstCompliance === 'OK' ? 'text-emerald-500' : 'text-amber-500'}`} />
                                                <span className="text-[10px] font-bold text-slate-400">TAX SYNC: {cat.gstCompliance}</span>
                                            </div>
                                        </td>
                                        <td className="px-6 py-4 text-right">
                                            <div className="flex items-center justify-end gap-2 text-slate-400">
                                                <button className="p-2 hover:bg-white hover:text-indigo-600 rounded-lg hover:shadow-sm border border-transparent hover:border-slate-200 transition-all">
                                                    <Edit className="w-4 h-4" />
                                                </button>
                                                <button className="p-2 hover:bg-rose-50 hover:text-rose-600 rounded-lg border border-transparent hover:border-rose-100 transition-all">
                                                    <Trash2 className="w-4 h-4" />
                                                </button>
                                            </div>
                                        </td>
                                    </tr>
                                ))
                            )}
                        </tbody>
                    </table>
                </div>

                {/* Pagination Toolbar */}
                <div className="px-6 py-4 bg-slate-50 border-t border-slate-200 flex items-center justify-between">
                    <p className="text-sm text-slate-500">
                        Page <span className="font-bold text-slate-900">{page}</span> of <span className="font-bold text-slate-900">{totalPages}</span>
                    </p>
                    <div className="flex items-center gap-2">
                        <button
                            onClick={() => setPage(p => Math.max(1, p - 1))}
                            disabled={page === 1 || isLoading}
                            className="px-4 py-2 bg-white border border-slate-200 rounded-lg text-sm font-bold text-slate-600 hover:bg-slate-50 disabled:opacity-50 disabled:cursor-not-allowed shadow-sm transition-colors flex items-center gap-1"
                        >
                            <ChevronLeft className="w-4 h-4" /> Previous
                        </button>
                        <button
                            onClick={() => setPage(p => Math.min(totalPages, p + 1))}
                            disabled={page === totalPages || isLoading}
                            className="px-4 py-2 bg-white border border-slate-200 rounded-lg text-sm font-bold text-slate-600 hover:bg-slate-50 disabled:opacity-50 disabled:cursor-not-allowed shadow-sm transition-colors flex items-center gap-1"
                        >
                            Next <ChevronRight className="w-4 h-4" />
                        </button>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default CategoryManager;

import { logger } from '@/shared/lib/logger';
import React, { useState, useMemo, useEffect } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import { RootState, AppDispatch } from "@/app/store/store";
import {
    getAgingReport,
    applyAgingAction,
    getAllItems,
    deleteItem as deleteSingleItem,
    deleteItemsBatch,
    addItem,
    updateItem,
    bulkUpdateCategory,
    bulkAdjustStock,
    duplicateItem,
    toggleItemStatus,
    getStockHistory,
    getInventoryStats
} from "@/entities/inventory/model/inventorySlice";
import ProductModal from "./ProductModal";
import { BulkCategoryModal, BulkAdjustmentModal } from "./BulkActionModals";
import { StockHistoryDrawer } from "./StockHistoryPanel";
import StockTransferModal from "./StockTransferModal";
import { Product } from "@repo/shared";
import Layout from "@/shared/ui/Layout";
import PageHeader from "@/shared/ui/Layout/PageHeader";
import {
    Box,
    Search,
    Plus,
    Tag,
    Warehouse,
    TrendingUp,
    AlertTriangle,
    ArrowRightLeft,
    Edit3,
    Barcode,
    Image as ImageIcon,
    Download,
    ChevronLeft,
    ChevronRight,
    Zap,
    MoreVertical,
    CheckSquare,
    Square,
    X,
    AlertOctagon,
    Percent,
    Eye,
    EyeOff,
    History,
    MoreHorizontal,
    Copy,
    Trash2,
} from 'lucide-react';

const MetricCard = ({ title, value, subtext, icon: Icon, color, trend }: any) => (
    <div className="bg-white dark:bg-neutral-800 p-6 rounded-xl border border-neutral-200 dark:border-neutral-700 shadow-sm relative overflow-hidden group hover:border-primary/50 transition-all">
        <div className={`absolute top-0 right-0 w-24 h-24 bg-${color}-500/10 rounded-full blur-2xl -mr-12 -mt-12 group-hover:bg-${color}-500/20 transition-all`}></div>
        <div className="flex justify-between items-start relative z-10">
            <div>
                <p className="text-neutral-500 dark:text-neutral-400 text-[10px] font-black uppercase tracking-widest">{title}</p>
                <h3 className="text-2xl font-black text-neutral-900 dark:text-white mt-1 italic tracking-tight">{value}</h3>
                {subtext && (
                    <p className={`text-[10px] font-bold mt-2 flex items-center gap-1 ${trend === 'up' ? 'text-emerald-500' : trend === 'down' ? 'text-rose-500' : 'text-neutral-400'}`}>
                        {subtext}
                    </p>
                )}
            </div>
            <div className={`p-3 rounded-xl bg-neutral-100 dark:bg-neutral-700/50 text-neutral-600 dark:text-neutral-400 group-hover:text-primary transition-colors`}>
                <Icon className="w-5 h-5" />
            </div>
        </div>
    </div>
);

const InventoryManager: React.FC = () => {
    const dispatch = useDispatch<AppDispatch>();
    const { items, isLoading, agingReport, pagination, stockHistory, inventoryStats } = useSelector((state: RootState) => state.inventory);
    const { user } = useSelector((state: RootState) => state.auth);
    const tenant_id = user?.tenantId || 'TEN001';

    const [showAgingModal, setShowAgingModal] = useState(false);
    const [isProductModalOpen, setIsProductModalOpen] = useState(false);
    const [editingProduct, setEditingProduct] = useState<Product | null>(null);
    const [selectedCategory, setSelectedCategory] = useState('ALL');
    const [selectedItems, setSelectedItems] = useState<Set<string>>(new Set());
    const [isTransferModalOpen, setIsTransferModalOpen] = useState(false);

    const [searchTerm, setSearchTerm] = useState('');
    const [debouncedSearch, setDebouncedSearch] = useState('');
    const [page, setPage] = useState(1);

    // Bulk Action States
    const [showMoreActions, setShowMoreActions] = useState(false);
    const [showCategoryMoveModal, setShowCategoryMoveModal] = useState(false);
    const [showAdjustmentModal, setShowAdjustmentModal] = useState(false);
    const [showImportModal, setShowImportModal] = useState(false);

    // Row Action States
    const [rowActionDropdown, setRowActionDropdown] = useState<string | null>(null);
    const [showStockHistory, setShowStockHistory] = useState(false);
    const [historyItem, setHistoryItem] = useState<{ id: string; name: string } | null>(null);

    useEffect(() => {
        const timer = setTimeout(() => {
            setDebouncedSearch(searchTerm);
            setPage(1);
        }, 500);
        return () => clearTimeout(timer);
    }, [searchTerm]);

    useEffect(() => {
        dispatch(getAllItems({ page, limit: 20, search: debouncedSearch, category: selectedCategory }));
        dispatch(getInventoryStats());
    }, [dispatch, page, debouncedSearch, selectedCategory]);

    const handleOpenAgingReport = () => {
        dispatch(getAgingReport());
        setShowAgingModal(true);
    };

    const handleAgingAction = async (itemId: string, action: 'CLEARANCE' | 'REDUCE_MARGIN', currentPrice: number) => {
        let value = 0;
        if (action === 'REDUCE_MARGIN') {
            const p = window.prompt("Enter new selling price:", (currentPrice * 0.8).toFixed(2));
            if (!p) return;
            value = parseFloat(p);
            if (isNaN(value) || value <= 0) {
                alert("Invalid price");
                return;
            }
        }
        await dispatch(applyAgingAction({ itemId, action, value }) as any);
        dispatch(getAgingReport());
    };


    const categoryList = useMemo(() => {
        const cats = new Set(items.map((i: any) => i.category).filter(Boolean));
        return ['ALL', ...Array.from(cats)];
    }, [items]);

    const toggleSelect = (id: string) => {
        const newSet = new Set(selectedItems);
        if (newSet.has(id)) newSet.delete(id);
        else newSet.add(id);
        setSelectedItems(newSet);
    };

    const toggleSelectAll = () => {
        if (selectedItems.size === items.length && items.length > 0) {
            setSelectedItems(new Set());
        } else {
            setSelectedItems(new Set(items.map((i: any) => i._id)));
        }
    };

    const handleBulkDelete = async () => {
        if (selectedItems.size === 0) return;
        if (window.confirm(`Are you sure you want to delete ${selectedItems.size} items?`)) {
            await dispatch(deleteItemsBatch(Array.from(selectedItems)));
            setSelectedItems(new Set());
        }
    };

    const handleDeleteSingle = async (id: string, name: string) => {
        if (window.confirm(`Delete item "${name}"?`)) {
            await dispatch(deleteSingleItem(id));
        }
    };

    const handleAddProduct = () => {
        setEditingProduct(null);
        setIsProductModalOpen(true);
    };

    const handleEditProduct = (product: Product) => {
        setEditingProduct(product);
        setIsProductModalOpen(true);
    };

    const handleSaveProduct = async (productData: Partial<Product>) => {
        try {
            if (editingProduct) {
                await dispatch(updateItem({ id: editingProduct._id as string, itemData: productData })).unwrap();
            } else {
                await dispatch(addItem(productData)).unwrap();
            }
            setIsProductModalOpen(false);
            dispatch(getAllItems());
        } catch (error: any) {
            alert(error || "Failed to save product");
        }
    };

    const handleImportSKUsOpen = () => {
        setShowImportModal(true);
    };

    const onBulkCategoryConfirm = async (category: string) => {
        await dispatch(bulkUpdateCategory({ ids: Array.from(selectedItems), category }));
        setSelectedItems(new Set());
        dispatch(getAllItems({ page, limit: 20, search: debouncedSearch, category: selectedCategory }));
    };

    const onBulkAdjustmentConfirm = async (adjustment: number, type: 'ADD' | 'SUBTRACT' | 'SET') => {
        await dispatch(bulkAdjustStock({ ids: Array.from(selectedItems), adjustment, type }));
        setSelectedItems(new Set());
        dispatch(getAllItems({ page, limit: 20, search: debouncedSearch, category: selectedCategory }));
    };

    const handleDuplicateItem = async (id: string) => {
        await dispatch(duplicateItem(id));
        setRowActionDropdown(null);
    };

    const handleToggleStatus = async (id: string) => {
        await dispatch(toggleItemStatus(id));
        setRowActionDropdown(null);
    };

    const handleViewHistory = async (id: string, name: string) => {
        setHistoryItem({ id, name });
        await dispatch(getStockHistory(id));
        setShowStockHistory(true);
        setRowActionDropdown(null);
    };

    const inventoryMetrics = useMemo(() => {
        if (inventoryStats) {
            return {
                totalItems: inventoryStats.totalItems,
                lowStock: inventoryStats.lowStockCount,
                totalValuation: inventoryStats.totalValuation
            };
        }
        // Fallback to page-level if stats not yet loaded
        const totalItems = items.length;
        const lowStock = items.filter((i: any) => i.stockQty <= i.lowStockLimit).length;
        const totalValuation = items.reduce((acc, i) => acc + (i.stockQty * (i.costPrice || 0)), 0);
        return { totalItems, lowStock, totalValuation };
    }, [items, inventoryStats]);

    return (
        <Layout>
            <div className="space-y-6 animate-fade-in text-main pb-16">
                <PageHeader
                    title="Inventory Core Manager"
                    description={`Central stock authority and metadata control for ${tenant_id}`}
                    actions={
                        <div className="flex gap-2">
                            <button className="px-4 py-2 bg-white dark:bg-neutral-800 border border-neutral-200 dark:border-neutral-700 rounded-xl text-xs font-black flex items-center gap-2 hover:border-primary/50 transition-all uppercase tracking-widest text-main shadow-sm">
                                <Download className="w-4 h-4" /> Export
                            </button>
                            <button onClick={handleOpenAgingReport} className="px-4 py-2 bg-rose-50 dark:bg-rose-900/10 text-rose-600 border border-rose-200 dark:border-rose-900/20 rounded-xl text-xs font-black flex items-center gap-2 hover:bg-rose-600 hover:text-white transition-all uppercase tracking-widest shadow-sm">
                                <AlertOctagon className="w-4 h-4" /> Stock Aging
                            </button>
                            <button
                                onClick={() => setIsTransferModalOpen(true)}
                                className="px-4 py-2 bg-indigo-50 dark:bg-indigo-900/10 text-indigo-600 border border-indigo-200 dark:border-indigo-900/20 rounded-xl text-xs font-black flex items-center gap-2 hover:bg-indigo-600 hover:text-white transition-all uppercase tracking-widest shadow-sm"
                            >
                                <ArrowRightLeft className="w-4 h-4" /> Transfer
                            </button>
                            <button
                                onClick={handleAddProduct}
                                className="px-5 py-2 bg-primary text-white rounded-xl text-xs font-black shadow-lg shadow-primary/25 flex items-center gap-2 hover:bg-primary/90 transition-all uppercase tracking-widest"
                            >
                                <Plus className="w-5 h-5" /> Register SKU
                            </button>
                        </div>
                    }
                />

                {/* Metrics Row */}
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                    <MetricCard
                        title="Total SKU Count"
                        value={inventoryMetrics.totalItems}
                        subtext="Across all nodes"
                        icon={Box}
                        color="primary"
                        trend="flat"
                    />
                    <MetricCard
                        title="Low Stock Alerts"
                        value={inventoryMetrics.lowStock}
                        subtext="Immediate restock needed"
                        icon={AlertTriangle}
                        color="rose"
                        trend="down"
                    />
                    <MetricCard
                        title="Estimated Valuation"
                        value={`₹${(inventoryMetrics.totalValuation / 100000).toFixed(2)}L`}
                        subtext="Total Asset Value"
                        icon={TrendingUp}
                        color="emerald"
                        trend="up"
                    />
                    <div className="bg-neutral-900 text-white p-6 rounded-xl shadow-xl relative overflow-hidden group border border-white/5">
                        <Zap className="absolute top-0 right-0 p-4 opacity-10 group-hover:scale-125 transition duration-700 stroke-[3]" />
                        <p className="text-[10px] font-black text-primary uppercase tracking-[0.2em] mb-2 italic">Agent Pulse</p>
                        <p className="text-sm font-bold leading-relaxed text-neutral-200">
                            {inventoryMetrics.lowStock > 0 ? (
                                <>Inventory needs attention. <span className="text-primary underline decoration-2 underline-offset-4 font-black">{items.find((i: any) => i.stockQty <= i.lowStockLimit)?.sku || 'Some SKUs'}</span> is low.</>
                            ) : (
                                <>Inventory healthy. <span className="text-emerald-400 font-black italic">Perfectly balanced.</span></>
                            )}
                        </p>
                    </div>
                </div>

                {/* Controls Bar */}
                <div className="flex flex-col xl:flex-row justify-between items-start xl:items-center gap-6 bg-white dark:bg-neutral-800 p-6 rounded-2xl border border-neutral-200 dark:border-neutral-700 shadow-sm">
                    <div className="flex flex-col md:flex-row gap-4 w-full xl:w-auto items-stretch md:items-center">
                        <div className="relative flex-1 xl:w-[450px]">
                            <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-neutral-400" />
                            <input
                                type="text"
                                placeholder="Search by SKU, Name or Barcode..."
                                className="w-full pl-12 pr-4 py-3 bg-neutral-50 dark:bg-neutral-900/50 border border-neutral-200 dark:border-neutral-700 rounded-xl text-sm outline-none focus:ring-2 focus:ring-primary/20 focus:border-primary transition-all font-bold text-main placeholder:text-neutral-400"
                                value={searchTerm}
                                onChange={(e) => setSearchTerm(e.target.value)}
                            />
                        </div>
                        <select
                            className="px-6 py-3 bg-neutral-50 dark:bg-neutral-900/50 border border-neutral-200 dark:border-neutral-700 rounded-xl text-[10px] font-black uppercase tracking-[0.15em] outline-none hover:border-primary transition-all text-main cursor-pointer"
                            value={selectedCategory}
                            onChange={(e) => setSelectedCategory(e.target.value)}
                        >
                            {categoryList.map(cat => (
                                <option key={cat} value={cat}>{cat.replace(/_/g, ' ')}</option>
                            ))}
                        </select>
                    </div>

                    <div className="flex gap-3 w-full md:w-auto justify-end">
                        {selectedItems.size > 0 && (
                            <button
                                onClick={handleBulkDelete}
                                className="px-6 py-3 bg-rose-600 text-white rounded-xl text-xs font-black uppercase tracking-[0.15em] shadow-xl shadow-rose-600/20 flex items-center gap-2 hover:bg-rose-700 transition-all active:scale-95"
                            >
                                Trash ({selectedItems.size})
                            </button>
                        )}
                        <div className="relative">
                            <button
                                onClick={() => setShowMoreActions(!showMoreActions)}
                                className="px-6 py-3 border border-neutral-200 dark:border-neutral-700 bg-white dark:bg-neutral-800 hover:bg-neutral-50 dark:hover:bg-neutral-700 text-main rounded-xl text-xs font-black uppercase tracking-[0.15em] transition-all shadow-sm flex items-center gap-2"
                            >
                                More Actions <MoreVertical className="w-4 h-4" />
                            </button>

                            {showMoreActions && (
                                <div className="absolute right-0 mt-2 w-64 bg-white dark:bg-neutral-800 border border-neutral-200 dark:border-neutral-700 rounded-2xl shadow-2xl z-[50] py-2 animate-in fade-in slide-in-from-top-2 duration-200">
                                    <div className="px-4 py-2 border-b border-neutral-100 dark:border-neutral-700 mb-1">
                                        <p className="text-[10px] font-black text-neutral-400 uppercase tracking-widest">Bulk Operations</p>
                                    </div>
                                    <button
                                        disabled={selectedItems.size === 0}
                                        onClick={() => { setShowMoreActions(false); /* handlePrintLabels(); */ }}
                                        className="w-full text-left px-4 py-3 text-[10px] font-black uppercase tracking-widest text-neutral-600 dark:text-neutral-300 hover:bg-primary/5 hover:text-primary transition-all flex items-center gap-3 disabled:opacity-50 disabled:cursor-not-allowed"
                                    >
                                        <Barcode className="w-4 h-4" /> Print Labels ({selectedItems.size})
                                    </button>
                                    <button
                                        disabled={selectedItems.size === 0}
                                        onClick={() => { setShowMoreActions(false); setShowCategoryMoveModal(true); }}
                                        className="w-full text-left px-4 py-3 text-[10px] font-black uppercase tracking-widest text-neutral-600 dark:text-neutral-300 hover:bg-primary/5 hover:text-primary transition-all flex items-center gap-3 disabled:opacity-50 disabled:cursor-not-allowed"
                                    >
                                        <Tag className="w-4 h-4" /> Change Category
                                    </button>
                                    <button
                                        disabled={selectedItems.size === 0}
                                        onClick={() => { setShowMoreActions(false); setShowAdjustmentModal(true); }}
                                        className="w-full text-left px-4 py-3 text-[10px] font-black uppercase tracking-widest text-neutral-600 dark:text-neutral-300 hover:bg-primary/5 hover:text-primary transition-all flex items-center gap-3 disabled:opacity-50 disabled:cursor-not-allowed"
                                    >
                                        <CheckSquare className="w-4 h-4" /> Stock Adjustment
                                    </button>
                                    <div className="h-px bg-neutral-100 dark:bg-neutral-700 mx-2 my-1"></div>
                                    <button
                                        onClick={() => { setShowMoreActions(false); setShowImportModal(true); }}
                                        className="w-full text-left px-4 py-3 text-[10px] font-black uppercase tracking-widest text-neutral-600 dark:text-neutral-300 hover:bg-emerald-500/5 hover:text-emerald-500 transition-all flex items-center gap-3"
                                    >
                                        <Download className="w-4 h-4" /> Import Excel/CSV
                                    </button>
                                </div>
                            )}
                        </div>
                    </div>
                </div>

                {/* Product Ledger */}
                <div className="bg-white dark:bg-neutral-800 rounded-2xl border border-neutral-200 dark:border-neutral-700 overflow-hidden shadow-sm">
                    <div className="overflow-x-auto">
                        <table className="w-full text-left text-sm tabular-nums border-collapse">
                            <thead className="bg-neutral-50/50 dark:bg-neutral-700/50 border-b border-neutral-200 dark:border-neutral-700 text-neutral-500 font-black uppercase tracking-[0.25em] text-[10px]">
                                <tr>
                                    <th className="px-6 py-5 w-10">
                                        <button onClick={toggleSelectAll} className="text-neutral-400 hover:text-primary transition-all">
                                            {selectedItems.size === items.length && items.length > 0 ?
                                                <CheckSquare className="w-5 h-5 text-primary" /> :
                                                <Square className="w-5 h-5" />
                                            }
                                        </button>
                                    </th>
                                    <th className="px-6 py-5">Product Master</th>
                                    <th className="px-6 py-5">Classification</th>
                                    <th className="px-6 py-5">Stock Node</th>
                                    <th className="px-6 py-5 text-right">Pricing</th>
                                    <th className="px-6 py-5">Status</th>
                                    <th className="px-6 py-5 w-10"></th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-neutral-200 dark:divide-neutral-700">
                                {isLoading ? (
                                    <tr>
                                        <td colSpan={7} className="p-20 text-center">
                                            <div className="animate-spin rounded-full h-12 w-12 border-4 border-primary border-t-transparent mx-auto"></div>
                                            <p className="mt-4 text-xs font-black uppercase tracking-widest text-neutral-400">Indexing Stock...</p>
                                        </td>
                                    </tr>
                                ) : items.length === 0 ? (
                                    <tr>
                                        <td colSpan={7} className="p-24 text-center text-neutral-400 font-black uppercase tracking-[0.3em] text-xs italic opacity-50">
                                            No SKUs found in this node
                                        </td>
                                    </tr>
                                ) : (
                                    items.map((item: any) => {
                                        const isLowStock = item.stockQty <= item.lowStockLimit;
                                        const isSelected = selectedItems.has(item._id);
                                        return (
                                            <tr key={item._id} className={`hover:bg-neutral-50 dark:hover:bg-neutral-700/50 transition-all group ${isSelected ? 'bg-primary/5 dark:bg-primary/10' : ''}`}>
                                                <td className="px-6 py-5">
                                                    <button onClick={() => toggleSelect(item._id)} className="text-neutral-400 hover:text-primary transition-all">
                                                        {isSelected ?
                                                            <CheckSquare className="w-5 h-5 text-primary" /> :
                                                            <Square className="w-5 h-5" />
                                                        }
                                                    </button>
                                                </td>
                                                <td className="px-6 py-5">
                                                    <div className="flex items-start gap-4">
                                                        <div className="w-10 h-10 rounded-xl bg-neutral-100 dark:bg-neutral-900/50 border border-neutral-200 dark:border-neutral-700 flex items-center justify-center shrink-0 overflow-hidden">
                                                            {item.image ? <img src={item.image} alt="" className="w-full h-full object-cover" /> : <ImageIcon className="w-5 h-5 text-neutral-400" />}
                                                        </div>
                                                        <div className="min-w-0">
                                                            <div
                                                                className="font-bold text-neutral-900 dark:text-neutral-100 uppercase tracking-tight truncate max-w-[200px] group-hover:text-primary transition-colors cursor-pointer"
                                                                onClick={() => handleEditProduct(item)}
                                                            >
                                                                {item.name}
                                                            </div>
                                                            <div className="flex items-center gap-2 mt-1">
                                                                <span className="text-[10px] text-neutral-500 font-bold">SKU: {item.sku || 'N/A'}</span>
                                                                {item.barcode && <div className="flex items-center gap-1"><Barcode className="w-3 h-3 text-neutral-400" /><span className="text-[10px] text-neutral-500 font-bold">{item.barcode}</span></div>}
                                                            </div>
                                                        </div>
                                                    </div>
                                                </td>
                                                <td className="px-6 py-5">
                                                    <div className="flex flex-col gap-1">
                                                        <span className="px-2 py-0.5 bg-neutral-100 dark:bg-neutral-700 text-neutral-600 dark:text-neutral-400 rounded text-[9px] font-black uppercase tracking-widest w-fit border border-neutral-200 dark:border-neutral-600">{item.category}</span>
                                                        <span className="text-[10px] text-primary font-bold italic">{item.brand || 'No Brand'}</span>
                                                    </div>
                                                </td>
                                                <td className="px-6 py-5">
                                                    <div className="flex flex-col">
                                                        <div className={`text-sm font-black italic ${isLowStock ? 'text-rose-500' : 'text-neutral-900 dark:text-neutral-100'}`}>
                                                            {item.stockQty} {item.unit}
                                                        </div>
                                                        <div className="flex items-center gap-1.5 mt-1">
                                                            <Warehouse className="w-3 h-3 text-neutral-400" />
                                                            <span className="text-[10px] text-neutral-400 font-bold uppercase">{item.location || 'General Floor'}</span>
                                                        </div>
                                                    </div>
                                                </td>
                                                <td className="px-6 py-5 text-right">
                                                    <div className="font-bold text-neutral-400 text-[10px] uppercase tracking-wider line-through decoration-rose-500/30">₹{item.costPrice?.toLocaleString()}</div>
                                                    <div className="font-black text-primary text-xl italic tracking-tight mt-0.5">₹{item.sellingPrice?.toLocaleString()}</div>
                                                </td>
                                                <td className="px-6 py-5">
                                                    <span className={`px-3 py-1.5 rounded-xl text-[9px] font-black uppercase tracking-[0.15em] border ${isLowStock ? 'bg-rose-50 text-rose-600 border-rose-200 dark:bg-rose-900/20 dark:border-rose-900/30' : 'bg-emerald-50 text-emerald-600 border-emerald-200 dark:bg-emerald-900/20 dark:border-emerald-900/30'}`}>
                                                        {isLowStock ? 'Critical Low' : 'In Stock'}
                                                    </span>
                                                </td>
                                                <td className="px-6 py-5 text-right relative">
                                                    <div className="flex items-center justify-end gap-2">
                                                        <button
                                                            onClick={() => setRowActionDropdown(rowActionDropdown === item._id ? null : item._id)}
                                                            className={`p-2.5 rounded-xl transition-all shadow-sm ${rowActionDropdown === item._id ? 'bg-primary text-white' : 'bg-neutral-50 dark:bg-neutral-800 text-neutral-400 hover:text-primary'}`}
                                                            title="More Actions"
                                                        >
                                                            <MoreVertical className="w-5 h-5" />
                                                        </button>

                                                        {rowActionDropdown === item._id && (
                                                            <div className="absolute right-6 top-16 w-56 bg-white dark:bg-neutral-800 border border-neutral-200 dark:border-neutral-700 rounded-2xl shadow-2xl z-[50] py-2 animate-in fade-in slide-in-from-top-2 duration-200 text-left">
                                                                <button
                                                                    onClick={() => { handleEditProduct(item); setRowActionDropdown(null); }}
                                                                    className="w-full text-left px-4 py-3 text-[10px] font-black uppercase tracking-widest text-neutral-600 dark:text-neutral-300 hover:bg-primary/5 hover:text-primary transition-all flex items-center gap-3"
                                                                >
                                                                    <Edit3 className="w-4 h-4" /> Edit Specifications
                                                                </button>
                                                                <button
                                                                    onClick={() => handleViewHistory(item._id, item.name)}
                                                                    className="w-full text-left px-4 py-3 text-[10px] font-black uppercase tracking-widest text-neutral-600 dark:text-neutral-300 hover:bg-primary/5 hover:text-primary transition-all flex items-center gap-3"
                                                                >
                                                                    <History className="w-4 h-4" /> Stock History
                                                                </button>
                                                                <button
                                                                    onClick={() => handleDuplicateItem(item._id)}
                                                                    className="w-full text-left px-4 py-3 text-[10px] font-black uppercase tracking-widest text-neutral-600 dark:text-neutral-300 hover:bg-primary/5 hover:text-primary transition-all flex items-center gap-3"
                                                                >
                                                                    <Copy className="w-4 h-4" /> Duplicate SKU
                                                                </button>
                                                                <div className="h-px bg-neutral-100 dark:bg-neutral-700 mx-2 my-1"></div>
                                                                <button
                                                                    onClick={() => handleToggleStatus(item._id)}
                                                                    className={`w-full text-left px-4 py-3 text-[10px] font-black uppercase tracking-widest transition-all flex items-center gap-3 ${item.isActive ? 'text-rose-600 hover:bg-rose-50' : 'text-emerald-600 hover:bg-emerald-50'}`}
                                                                >
                                                                    {item.isActive ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
                                                                    {item.isActive ? 'Deactivate Record' : 'Activate Record'}
