import { logger } from '@/shared/lib/logger';
import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { toast } from 'react-toastify';
import { Printer, Trash2, RefreshCw, AlertTriangle } from 'lucide-react';
import { useConfig } from '@/app/providers/ConfigContext';
import { LabelPrintModal } from "./LabelPrintModal";

interface QueueItem {
    itemId: string;
    itemName: string;
    sku: string;
    oldPrice?: number;
    newPrice: number; // This will map to price/sellingPrice
    quantity: number; // This will map to stock
    reason?: string;
}

const ReprintQueue: React.FC = () => {
    const { tenantId } = useConfig();
    const apiUrl = (import.meta as any).env.VITE_BACKEND_URL;
    const [queue, setQueue] = useState<QueueItem[]>([]);
    const [loading, setLoading] = useState(true);
    const [isPrintModalOpen, setIsPrintModalOpen] = useState(false);

    const fetchQueue = async () => {
        setLoading(true);
        try {
            const token = localStorage.getItem('token');
            const res = await axios.get(`${apiUrl}/inventory/reprint-queue`, {
                headers: { Authorization: `Bearer ${token}`, 'x-tenant-id': tenantId }
            });
            setQueue(res.data);
        } catch (err) {
            logger.error('Fetch Queue Error:', err);
            toast.error('Error fetching reprint queue');
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchQueue();
    }, [apiUrl, tenantId]);

    const handleClearQueue = async () => {
        if (!confirm('Are you sure you want to clear the reprint queue?')) return;

        try {
            const token = localStorage.getItem('token');
            await axios.delete(`${apiUrl}/inventory/reprint-queue`, {
                headers: { Authorization: `Bearer ${token}`, 'x-tenant-id': tenantId }
            });
            toast.success('Queue cleared');
            setQueue([]);
        } catch (err) {
            logger.error('Clear Queue Error:', err);
            toast.error('Error clearing queue');
        }
    };

    // Prepare products for LabelPrintModal
    // Mapping QueueItem to the structure expected by LabelPrintModal (roughly matching Product type but with required fields)
    const productsToPrint = queue.map(item => ({
        id: item.itemId,
        name: item.itemName,
        sku: item.sku,
        price: item.newPrice, // LabelPrintModal uses p.mrp || p.price
        stock: item.quantity, // LabelPrintModal uses p.stock
        // Add other fields if needed to satisfy TS or logic
        category: '',
        costPrice: 0,
        sellingPrice: item.newPrice,
        stockQty: item.quantity,
        tenantId: '',
        unit: 'pcs'
    })) as any[]; // Cast to any to avoid strict type checks against the complex Product interface for now

    return (
        <div className="p-6 max-w-6xl mx-auto">
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-8">
                <div>
                    <h1 className="text-2xl font-bold text-gray-800 dark:text-white flex items-center gap-2">
                        <Printer className="w-8 h-8 text-emerald-500" />
                        Label Reprint Queue
                    </h1>
                    <p className="text-gray-500 dark:text-gray-400 mt-1">
                        Items queued for updated labels (e.g., after price hikes).
                    </p>
                </div>
                <div className="flex items-center gap-3">
                    <button
                        onClick={fetchQueue}
                        className="p-2 text-gray-500 hover:text-emerald-600 transition-colors"
                        title="Refresh"
                    >
                        <RefreshCw className={`w-5 h-5 ${loading ? 'animate-spin' : ''}`} />
                    </button>
                    {queue.length > 0 && (
                        <>
                            <button
                                onClick={handleClearQueue}
                                className="px-4 py-2 text-red-600 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg flex items-center gap-2 transition-colors border border-transparent hover:border-red-200"
                            >
                                <Trash2 className="w-4 h-4" />
                                Clear Queue
                            </button>
                            <button
                                onClick={() => setIsPrintModalOpen(true)}
                                className="bg-emerald-600 hover:bg-emerald-700 text-white px-6 py-2 rounded-lg font-bold shadow-lg shadow-emerald-600/30 flex items-center gap-2 transform active:scale-95 transition-all"
                            >
                                <Printer className="w-5 h-5" />
                                Print {queue.length} Items
                            </button>
                        </>
                    )}
                </div>
            </div>

            {loading ? (
                <div className="flex justify-center py-20">
                    <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-emerald-500"></div>
                </div>
            ) : queue.length === 0 ? (
                <div className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-200 dark:border-gray-700 p-12 text-center">
                    <Printer className="w-16 h-16 text-gray-300 dark:text-gray-600 mx-auto mb-4" />
                    <h3 className="text-lg font-medium text-gray-900 dark:text-white">Queue is Empty</h3>
                    <p className="text-gray-500 dark:text-gray-400 mt-1">No items are currently queued for reprinting.</p>
                </div>
            ) : (
                <div className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-200 dark:border-gray-700 overflow-hidden">
                    <table className="w-full text-left">
                        <thead className="bg-gray-50 dark:bg-gray-900 border-b border-gray-200 dark:border-gray-700">
                            <tr>
                                <th className="px-6 py-4 text-xs font-semibold text-gray-500 uppercase tracking-wider">Item Details</th>
                                <th className="px-6 py-4 text-xs font-semibold text-gray-500 uppercase tracking-wider">SKU</th>
                                <th className="px-6 py-4 text-xs font-semibold text-gray-500 uppercase tracking-wider text-right">Qty</th>
                                <th className="px-6 py-4 text-xs font-semibold text-gray-500 uppercase tracking-wider text-right">Old Price</th>
                                <th className="px-6 py-4 text-xs font-semibold text-gray-500 uppercase tracking-wider text-right">New Price</th>
                                <th className="px-6 py-4 text-xs font-semibold text-gray-500 uppercase tracking-wider">Reason</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-gray-200 dark:divide-gray-700">
                            {queue.map((item, index) => (
                                <tr key={index} className="hover:bg-gray-50 dark:hover:bg-gray-700/50 transition-colors">
                                    <td className="px-6 py-4">
                                        <div className="font-medium text-gray-900 dark:text-white">{item.itemName}</div>
                                    </td>
                                    <td className="px-6 py-4 text-sm font-mono text-gray-500 dark:text-gray-400">
                                        {item.sku}
                                    </td>
                                    <td className="px-6 py-4 text-right font-medium text-gray-900 dark:text-white">
                                        {item.quantity}
                                    </td>
                                    <td className="px-6 py-4 text-right text-gray-500 line-through">
                                        {item.oldPrice ? `₹${item.oldPrice}` : '-'}
                                    </td>
                                    <td className="px-6 py-4 text-right font-bold text-emerald-600 dark:text-emerald-400">
                                        ₹{item.newPrice}
                                    </td>
                                    <td className="px-6 py-4 text-sm text-gray-500">
                                        {item.reason || '-'}
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            )}

            {/* Label Print Modal */}
            <LabelPrintModal
                isOpen={isPrintModalOpen}
                onClose={() => setIsPrintModalOpen(false)}
                products={productsToPrint}
                onPrintComplete={() => {
                    // Optional: Can prompt user to clear queue, or auto clear
                    // For now, let user manually clear or I can show a toast
                    toast.info("If printing was successful, please clear the queue to avoid duplicates.");
                }}
            />
        </div>
    );
};

export default ReprintQueue;

import React, { useState } from 'react';
import { X, ArrowRightLeft, Warehouse, Layers, Save, AlertCircle } from 'lucide-react';

interface StockTransferModalProps {
    isOpen: boolean;
    onClose: () => void;
    onTransfer: (transferData: any) => Promise<void>;
    isLoading?: boolean;
    items?: any[];
}

const StockTransferModal: React.FC<StockTransferModalProps> = ({ isOpen, onClose, onTransfer, isLoading, items = [] }) => {
    const [formData, setFormData] = useState({
        itemId: '',
        sourceNode: 'Main Warehouse',
        destinationNode: '',
        quantity: 0,
        remarks: ''
    });

    if (!isOpen) return null;

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!formData.itemId || !formData.destinationNode || formData.quantity <= 0) {
            alert("Please fill all required fields");
            return;
        }
        await onTransfer(formData);
    };

    const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
        const { name, value } = e.target;
        setFormData(prev => ({
            ...prev,
            [name]: name === 'quantity' ? parseFloat(value) || 0 : value
        }));
    };

    const selectedItem = items.find(i => i._id === formData.itemId);

    return (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-neutral-950/80 backdrop-blur-md animate-in fade-in duration-300">
            <div className="bg-white dark:bg-neutral-800 w-full max-w-xl rounded-3xl border border-neutral-200 dark:border-neutral-700 shadow-2xl overflow-hidden flex flex-col max-h-[90vh]">
                {/* Header */}
                <div className="px-8 py-6 border-b border-neutral-200 dark:border-neutral-700 flex justify-between items-center bg-neutral-50/50 dark:bg-neutral-700/50">
                    <div className="flex items-center gap-3">
                        <div className="p-2 bg-indigo-600/10 text-indigo-600 rounded-xl">
                            <ArrowRightLeft className="w-6 h-6" />
                        </div>
                        <div>
                            <h3 className="text-xl font-black italic text-neutral-900 dark:text-neutral-100">
                                Stock Transfer Protocol
                            </h3>
                            <p className="text-[10px] font-black text-neutral-400 uppercase tracking-widest mt-0.5">
                                Inter-Node Movement Authorization
                            </p>
                        </div>
                    </div>
                    <button onClick={onClose} className="p-2 hover:bg-neutral-100 dark:hover:bg-neutral-700 text-neutral-400 hover:text-rose-600 rounded-full transition-all">
                        <X className="w-5 h-5" />
                    </button>
                </div>

                {/* Form Body */}
                <form onSubmit={handleSubmit} className="p-8 space-y-6 overflow-y-auto">
                    <div className="space-y-4">
                        {/* SKU Selection */}
                        <div>
                            <label className="text-[10px] font-black text-neutral-400 uppercase tracking-widest mb-1.5 block px-1">Select SKU to Transfer</label>
                            <select
                                name="itemId"
                                value={formData.itemId}
                                onChange={handleChange}
                                required
                                className="w-full px-4 py-3 bg-neutral-50 dark:bg-neutral-900/50 border border-neutral-200 dark:border-neutral-700 rounded-xl text-xs font-bold text-main outline-none focus:ring-2 focus:ring-primary/20 focus:border-primary transition-all cursor-pointer"
                            >
                                <option value="">-- Choose Item --</option>
                                {items.map(item => (
                                    <option key={item._id} value={item._id}>{item.name} ({item.sku}) - Qty: {item.stockQty}</option>
                                ))}
                            </select>
                        </div>

                        {/* Node Selection */}
                        <div className="grid grid-cols-2 gap-4 items-center">
                            <div>
                                <label className="text-[10px] font-black text-neutral-400 uppercase tracking-widest mb-1.5 block px-1">Source Node</label>
                                <div className="px-4 py-3 bg-neutral-100 dark:bg-neutral-800 border border-neutral-200 dark:border-neutral-700 rounded-xl text-xs font-black text-neutral-500 flex items-center gap-2">
                                    <Warehouse className="w-4 h-4" /> {formData.sourceNode}
                                </div>
                            </div>
                            <div>
                                <label className="text-[10px] font-black text-neutral-400 uppercase tracking-widest mb-1.5 block px-1">Destination Node</label>
                                <select
                                    name="destinationNode"
                                    value={formData.destinationNode}
                                    onChange={handleChange}
                                    required
                                    className="w-full px-4 py-3 bg-neutral-50 dark:bg-neutral-900/50 border border-neutral-200 dark:border-neutral-700 rounded-xl text-xs font-bold text-main outline-none focus:ring-2 focus:ring-primary/20 focus:border-primary transition-all cursor-pointer"
                                >
                                    <option value="">-- Choose Node --</option>
                                    <option value="Branch A">Coimbatore Branch</option>
                                    <option value="Branch B">Chennai Warehouse</option>
                                    <option value="Showroom">Main Showroom</option>
                                </select>
                            </div>
                        </div>

                        {/* Quantity and Validation */}
                        <div>
                            <label className="text-[10px] font-black text-neutral-400 uppercase tracking-widest mb-1.5 block px-1">Transfer Quantity</label>
                            <div className="relative">
                                <input
                                    type="number"
                                    name="quantity"
                                    value={formData.quantity}
                                    onChange={handleChange}
                                    required
                                    max={selectedItem?.stockQty || 0}
                                    className="w-full px-4 py-3 bg-neutral-50 dark:bg-neutral-900/50 border border-neutral-200 dark:border-neutral-700 rounded-xl text-sm font-bold text-main outline-none focus:ring-2 focus:ring-primary/20 focus:border-primary transition-all"
                                    placeholder="0"
                                />
                                {selectedItem && (
                                    <div className="absolute right-4 top-1/2 -translate-y-1/2 text-[10px] font-black text-neutral-400">
                                        / {selectedItem.stockQty} AVAILABLE
                                    </div>
                                )}
                            </div>
                            {selectedItem && formData.quantity > selectedItem.stockQty && (
                                <p className="mt-2 text-[10px] font-bold text-rose-500 flex items-center gap-1">
                                    <AlertCircle className="w-3 h-3" /> Insufficient stock for transfer
                                </p>
                            )}
                        </div>

                        {/* Remarks */}
                        <div>
                            <label className="text-[10px] font-black text-neutral-400 uppercase tracking-widest mb-1.5 block px-1">Authorization Remarks</label>
                            <textarea
                                name="remarks"
                                value={formData.remarks}
                                onChange={handleChange}
                                rows={3}
                                className="w-full px-4 py-3 bg-neutral-50 dark:bg-neutral-900/50 border border-neutral-200 dark:border-neutral-700 rounded-xl text-sm font-bold text-main outline-none focus:ring-2 focus:ring-primary/20 focus:border-primary transition-all resize-none"
                                placeholder="Purpose of movement..."
                            />
                        </div>
                    </div>
                </form>

                {/* Footer */}
                <div className="px-8 py-6 border-t border-neutral-200 dark:border-neutral-700 bg-neutral-50/50 dark:bg-neutral-700/50 flex justify-end gap-3">
                    <button
                        onClick={onClose}
                        className="px-6 py-3 bg-white dark:bg-neutral-800 border border-neutral-200 dark:border-neutral-700 text-neutral-500 rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-neutral-50 dark:hover:bg-neutral-700 transition-all"
                    >
                        Discard
                    </button>
                    <button
                        onClick={handleSubmit}
                        disabled={isLoading || !formData.itemId || !formData.destinationNode || formData.quantity <= 0 || (selectedItem && formData.quantity > selectedItem.stockQty)}
                        className="px-8 py-3 bg-indigo-600 text-white rounded-xl text-[10px] font-black uppercase tracking-widest shadow-xl shadow-indigo-600/20 hover:scale-105 active:scale-95 transition-all flex items-center gap-2 disabled:opacity-50 disabled:scale-100"
                    >
                        {isLoading ? (
                            <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                        ) : (
                            <Save className="w-4 h-4" />
                        )}
                        Execute Transfer
                    </button>
                </div>
            </div>
        </div>
    );
};

