                    </div>
                    <div>
                        <div className="font-black uppercase tracking-widest text-xs text-neutral-400">Inventory Sync</div>
                        <div className="text-sm font-bold text-emerald-600">Modules are automatically interconnected</div>
                    </div>
                </div>
                <div className="text-right">
                    <div className="text-2xl font-black text-brand-600">{selectedModules.length}</div>
                    <div className="text-[10px] font-black uppercase tracking-widest text-neutral-400">Modules Selected</div>
                </div>
            </div>
        </div>
    );

    // Open plan customizer
    const openPlanCustomizer = (plan: Plan) => {
        setCustomizingPlan(plan);
        setCustomModules([...selectedModules]);
        setAdditionalUsers(0);
        setAdditionalBranches(0);
        setShowPlanCustomizer(true);
    };

    // Calculate custom pricing
    const customPricing = useMemo(() => {
        if (!customizingPlan) return null;
        const addons = customModules.filter(m => !customizingPlan.modules.includes(m));
        return calculateCustomPricing(customizingPlan, addons, additionalUsers, additionalBranches);
    }, [customizingPlan, customModules, additionalUsers, additionalBranches]);

    // Skip plan and configure later
    const handleSkipPlan = () => {
        setSkippedPlanSelection(true);
        setSelectedPlan(PLANS[0]); // Default to Starter (free)
        nextStep();
    };

    // Complete setup and navigate
    const handleCompleteSetup = async () => {
        // Collect all final modules (base + custom)
        const finalModules = [...new Set([
            ...(selectedPlan?.modules || recommendation?.recommendedPlan.modules || []),
            ...selectedModules,
            ...customModules
        ])];

        // Register the tenant and admin in mock DB
        const response = await registrationUtil.registerTenant({
            businessName,
            businessType,
            sector,
            city,
            state,
            modules: finalModules,
            adminName,
            adminEmail,
            adminMobile,
            adminPassword,
            preferredLogin,
            employeeCount,
            branchCount
        });

        const { admin } = response as any; // Cast to any if type is incomplete


        // Auto-login the user
        dispatch(setUser(admin));
        setSession(admin); // Persist session correctly

        // Mark session as active for demo purposes
        localStorage.setItem('isAuthenticated', 'true');
        localStorage.setItem('erp_current_tenant', admin.tenantId); // Hint for the app shell

        // Navigate to dashboard with success message
        navigate('/', { replace: true });
    };

    // Render plan customizer modal
    const renderPlanCustomizer = () => {
        if (!showPlanCustomizer || !customizingPlan) return null;

        return (
            <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
                <div className="bg-white dark:bg-neutral-900 rounded-2xl max-w-2xl w-full max-h-[90vh] overflow-auto shadow-2xl">
                    <div className="p-6 border-b border-neutral-200 dark:border-neutral-800">
                        <div className="flex items-center justify-between">
                            <h3 className="text-xl font-bold flex items-center gap-2">
                                <Settings className="w-5 h-5" /> Customize {customizingPlan.name} Plan
                            </h3>
                            <button onClick={() => setShowPlanCustomizer(false)} className="p-2 hover:bg-neutral-100 dark:hover:bg-neutral-800 rounded-lg">
                                <X className="w-5 h-5" />
                            </button>
                        </div>
                    </div>

                    <div className="p-6 space-y-6">
                        {/* Base Plan */}
                        <div className="bg-neutral-50 dark:bg-neutral-800/50 rounded-xl p-4">
                            <div className="flex items-center justify-between">
                                <div>
                                    <div className="font-bold">{customizingPlan.name} Plan</div>
                                    <div className="text-sm text-neutral-500">{customizingPlan.description}</div>
                                </div>
                                <div className="text-xl font-black">{customizingPlan.price}</div>
                            </div>
                        </div>

                        {/* Additional Users */}
                        <div>
                            <label className="block text-sm font-bold mb-2">Additional Users</label>
                            <div className="flex items-center gap-4">
                                <button
                                    onClick={() => setAdditionalUsers(Math.max(0, additionalUsers - 1))}
                                    className="p-2 rounded-lg bg-neutral-100 dark:bg-neutral-800 hover:bg-neutral-200"
                                >
                                    <Minus className="w-5 h-5" />
                                </button>
                                <span className="text-2xl font-bold w-16 text-center">{additionalUsers}</span>
                                <button
                                    onClick={() => setAdditionalUsers(additionalUsers + 1)}
                                    className="p-2 rounded-lg bg-neutral-100 dark:bg-neutral-800 hover:bg-neutral-200"
                                >
                                    <Plus className="w-5 h-5" />
                                </button>
                                <span className="text-sm text-neutral-500">₹99/user/month</span>
                            </div>
                        </div>

                        {/* Additional Branches */}
                        <div>
                            <label className="block text-sm font-bold mb-2">Additional Branches</label>
                            <div className="flex items-center gap-4">
                                <button
                                    onClick={() => setAdditionalBranches(Math.max(0, additionalBranches - 1))}
                                    className="p-2 rounded-lg bg-neutral-100 dark:bg-neutral-800 hover:bg-neutral-200"
                                >
                                    <Minus className="w-5 h-5" />
                                </button>
                                <span className="text-2xl font-bold w-16 text-center">{additionalBranches}</span>
                                <button
                                    onClick={() => setAdditionalBranches(additionalBranches + 1)}
                                    className="p-2 rounded-lg bg-neutral-100 dark:bg-neutral-800 hover:bg-neutral-200"
                                >
                                    <Plus className="w-5 h-5" />
                                </button>
                                <span className="text-sm text-neutral-500">₹199/branch/month</span>
                            </div>
                        </div>

                        {/* Add-on Modules */}
                        <div>
                            <label className="block text-sm font-bold mb-3">Add-on Modules</label>
                            <div className="grid grid-cols-2 gap-2">
                                {MODULES.filter(m => !customizingPlan.modules.includes(m.id)).map(module => {
                                    const isSelected = customModules.includes(module.id);
                                    return (
                                        <button
                                            key={module.id}
                                            onClick={() => setCustomModules(prev =>
                                                prev.includes(module.id)
                                                    ? prev.filter(m => m !== module.id)
                                                    : [...prev, module.id]
                                            )}
                                            className={`p-3 rounded-lg border-2 text-left transition-all ${isSelected
                                                ? 'border-brand-600 bg-brand-50 dark:bg-brand-900/20'
                                                : 'border-neutral-200 dark:border-neutral-700'
                                                }`}
                                        >
                                            <div className="flex items-center gap-2">
                                                <span>{module.icon}</span>
                                                <span className="font-medium text-sm">{module.name}</span>
                                                <span className="ml-auto text-xs text-neutral-500">+₹299</span>
                                            </div>
                                        </button>
                                    );
                                })}
                            </div>
                        </div>

                        {/* Pricing Summary */}
                        {customPricing && (
                            <div className="bg-brand-50 dark:bg-brand-900/20 rounded-xl p-4 border border-brand-200">
                                <div className="flex items-center gap-2 mb-3">
                                    <Calculator className="w-5 h-5 text-brand-600" />
                                    <span className="font-bold">Pricing Summary</span>
                                </div>
                                <div className="space-y-2 text-sm">
                                    {customPricing.breakdown.map((item, idx) => (
                                        <div key={idx} className="flex justify-between">
                                            <span className="text-neutral-600">{item.item}</span>
                                            <span className="font-medium">₹{item.cost.toLocaleString()}</span>
                                        </div>
                                    ))}
                                    <div className="border-t border-brand-200 pt-2 mt-2 flex justify-between font-bold text-lg">
                                        <span>Total / Month</span>
                                        <span className="text-brand-600">₹{customPricing.total.toLocaleString()}</span>
                                    </div>
                                </div>
                            </div>
                        )}
                    </div>

                    <div className="p-6 border-t border-neutral-200 dark:border-neutral-800 flex gap-3">
                        <button
                            onClick={() => setShowPlanCustomizer(false)}
                            className="btn btn-secondary flex-1"
                        >
                            Cancel
                        </button>
                        <button
                            onClick={() => {
                                setSelectedPlan(customizingPlan);
                                setSelectedModules([...new Set([...selectedModules, ...customModules])]);
                                setShowPlanCustomizer(false);
                                nextStep();
                            }}
                            className="btn btn-primary flex-1"
                        >
                            Apply & Continue
                        </button>
                    </div>
                </div>
            </div>
        );
    };

    // Step 5: Plan Recommendation
    const renderPlanRecommendation = () => {
        if (!recommendation) return null;

        return (
            <div className="space-y-12 step-bounce">
                <div className="text-center">
                    <h2 className="text-3xl font-black mb-2">Your Path to <span className="onboarding-gradient-text">Success</span></h2>
                    <p className="text-neutral-500 dark:text-neutral-400 font-medium">Data-driven recommendation optimized for your profile</p>
                </div>

                {/* Recommended Plan */}
                <div className="max-w-xl mx-auto">
                    <div className="relative p-1 rounded-[2.5rem] onboarding-gradient-bg shadow-2xl shadow-brand-600/30 group">
                        <div className="absolute top-0 left-1/2 -translate-x-1/2 -translate-y-1/2 bg-amber-500 text-white text-[10px] font-black uppercase tracking-[0.2em] px-6 py-2 rounded-full shadow-xl shadow-amber-500/40 z-20">
                            Our Best Pick for You
                        </div>

                        <div className="bg-white/95 dark:bg-neutral-900/95 backdrop-blur-xl p-10 rounded-[2.4rem] space-y-8 relative overflow-hidden">
                            {/* Abstract background elements */}
                            <div className="absolute -top-24 -right-24 w-48 h-48 onboarding-gradient-bg rounded-full blur-[80px] opacity-10" />

                            <div className="text-center space-y-4">
                                <div className="w-20 h-20 rounded-3xl onboarding-gradient-bg flex items-center justify-center mx-auto shadow-xl shadow-brand-600/20 rotate-3">
                                    <recommendation.recommendedPlan.icon className="w-10 h-10 text-white" />
                                </div>
                                <div>
                                    <h3 className="text-3xl font-black uppercase tracking-tight">{recommendation.recommendedPlan.name}</h3>
                                    <div className="flex items-baseline justify-center gap-1 mt-1">
                                        <span className="text-5xl font-black text-neutral-900 dark:text-white">{recommendation.recommendedPlan.price}</span>
                                        <span className="text-neutral-400 font-bold uppercase tracking-widest text-xs">{recommendation.recommendedPlan.period}</span>
                                    </div>
                                </div>
                            </div>

                            <div className="grid grid-cols-1 gap-4">
                                {recommendation.reasons.map((reason, idx) => (
                                    <div key={idx} className="flex items-start gap-3 bg-neutral-50 dark:bg-neutral-800/50 p-4 rounded-2xl border border-neutral-100 dark:border-neutral-800 shadow-sm">
                                        <div className="w-6 h-6 rounded-full bg-emerald-500 flex items-center justify-center text-white shrink-0 mt-0.5">
                                            <Check className="w-4 h-4 stroke-[3]" />
                                        </div>
                                        <span className="text-sm font-semibold text-neutral-700 dark:text-neutral-300">{reason}</span>
                                    </div>
                                ))}
                            </div>

                            <div className="glass-card p-6 rounded-3xl border-brand-100 dark:border-brand-900/30 flex items-center justify-between">
                                <div className="space-y-1">
                                    <div className="text-[10px] font-black uppercase tracking-widest text-neutral-400">Estimated Monthly</div>
                                    <div className="text-3xl font-black text-brand-600">₹{(recommendation.monthlyEstimate ?? 0).toLocaleString()}</div>
                                </div>
                                {recommendation.savings && (
                                    <div className="text-right">
                                        <div className="px-3 py-1 bg-emerald-100 dark:bg-emerald-900/30 text-emerald-600 text-[10px] font-black rounded-full uppercase tracking-tighter mb-1">
                                            Save 15% Yearly
                                        </div>
                                        <div className="text-[10px] text-neutral-400 italic">Pre-applied</div>
                                    </div>
                                )}
                            </div>

                            <div className="flex flex-col gap-4 pt-2">
                                <button
                                    onClick={() => {
                                        setSelectedPlan(recommendation.recommendedPlan);
                                        nextStep();
                                    }}
                                    className="onboarding-gradient-bg text-white font-black text-xl py-5 rounded-2xl shadow-2xl shadow-brand-600/30 hover:scale-[1.02] active:scale-[0.98] transition-all"
                                >
                                    Activate {recommendation.recommendedPlan.name}
                                </button>
                                <button
                                    onClick={() => openPlanCustomizer(recommendation.recommendedPlan)}
                                    className="btn btn-secondary py-4 rounded-2xl border-neutral-200 dark:border-neutral-800 font-bold flex items-center justify-center gap-2 hover:bg-neutral-50 dark:hover:bg-neutral-900/50"
                                >
                                    <Settings className="w-5 h-5" /> Customize Plan Add-ons
                                </button>
                            </div>
                        </div>
                    </div>
                </div>


                {/* All Plans Selector */}
                <div className="space-y-6">
                    <div className="flex items-center gap-4">
                        <div className="h-px flex-1 bg-neutral-200 dark:bg-neutral-800" />
                        <span className="text-[10px] font-black uppercase tracking-[0.3em] text-neutral-400">Other Available Options</span>
                        <div className="h-px flex-1 bg-neutral-200 dark:bg-neutral-800" />
                    </div>

                    <div className="grid md:grid-cols-4 gap-4">
                        {PLANS.map(plan => {
                            const isRecommended = plan.id === recommendation.recommendedPlan.id;
                            return (
                                <div
                                    key={plan.id}
                                    className={`p-6 rounded-3xl border-2 transition-all duration-500 overflow-hidden relative group ${isRecommended
                                        ? 'border-brand-600 bg-brand-50/50 dark:bg-brand-900/20 ring-4 ring-brand-600/10 shadow-xl'
                                        : 'border-neutral-100 dark:border-neutral-800 bg-white/30 dark:bg-black/10 hover:border-brand-300'
                                        }`}
                                >
                                    <div className="flex items-center gap-3 mb-4">
                                        <div className={`w-10 h-10 rounded-xl flex items-center justify-center ${isRecommended ? 'bg-brand-600 text-white' : 'bg-neutral-100 dark:bg-neutral-800 text-neutral-400 group-hover:bg-brand-100 group-hover:text-brand-600'}`}>
                                            <plan.icon className="w-6 h-6" />
                                        </div>
                                        <span className="font-black uppercase tracking-tight text-sm">{plan.name}</span>
                                    </div>
                                    <div className="text-2xl font-black mb-1">{plan.price}</div>
                                    <div className="text-[10px] text-neutral-500 dark:text-neutral-400 font-bold uppercase tracking-widest mb-6">{plan.period}</div>

                                    <button
                                        onClick={() => {
                                            setSelectedPlan(plan);
                                            nextStep();
                                        }}
                                        className={`w-full py-3 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${isRecommended
                                            ? 'onboarding-gradient-bg text-white shadow-lg shadow-brand-600/20'
                                            : 'bg-neutral-100 dark:bg-neutral-800 text-neutral-600 dark:text-neutral-400 hover:bg-brand-600 hover:text-white'
                                            }`}
                                    >
                                        Choose Plan
                                    </button>
                                </div>
                            );
                        })}
                    </div>
                </div>

                <div className="text-center pt-8">
                    <button
                        onClick={handleSkipPlan}
                        className="group flex flex-col items-center gap-2 mx-auto"
                    >
                        <span className="text-sm font-bold text-neutral-500 group-hover:text-brand-600 transition-colors">Not ready to decide?</span>
                        <div className="flex items-center gap-2 px-6 py-2 rounded-full border border-neutral-200 dark:border-neutral-800 text-[10px] font-black uppercase tracking-widest text-neutral-400 group-hover:border-brand-300">
                            <Clock className="w-3 h-3" /> Start for Free & Choose Later
                        </div>
                    </button>
                </div>
            </div>
        );
    };

    // Step 6: Confirmation
    const renderConfirmation = () => {
        const plan = selectedPlan || recommendation?.recommendedPlan;
        if (!plan) return null;

        return (
            <div className="space-y-12 max-w-5xl mx-auto step-bounce">
                <div className="text-center space-y-4">
                    <div className="w-24 h-24 bg-emerald-500/10 rounded-full flex items-center justify-center mx-auto ring-8 ring-emerald-500/5 pulse">
                        <CheckCircle className="w-12 h-12 text-emerald-500" />
                    </div>
                    <div>
                        <h2 className="text-4xl font-black">Ready to <span className="onboarding-gradient-text">Blast Off!</span></h2>
                        <p className="text-neutral-500 dark:text-neutral-400 font-medium">Your enterprise-grade foundation is prepared</p>
                    </div>
                </div>

                <div className="grid md:grid-cols-5 gap-8 items-start">
                    {/* Summary Cards */}
                    <div className="md:col-span-3 space-y-6">
                        <div className="glass-card p-8 rounded-[2rem] border-neutral-100 dark:border-neutral-800">
                            <h3 className="text-sm font-black uppercase tracking-[0.2em] text-neutral-400 mb-8 flex items-center gap-2">
                                <Building2 className="w-4 h-4 text-brand-600" /> Organization Profile
                            </h3>

                            <div className="grid grid-cols-2 gap-y-8 gap-x-12">
                                <div className="space-y-1">
                                    <div className="text-[10px] font-black uppercase tracking-widest text-neutral-400">Business Name</div>
                                    <div className="font-bold text-lg">{businessName}</div>
                                </div>
                                <div className="space-y-1">
                                    <div className="text-[10px] font-black uppercase tracking-widest text-neutral-400">Sector</div>
                                    <div className="font-bold text-lg">{SECTORS.find(s => s.id === sector)?.name}</div>
                                </div>
                                <div className="space-y-1">
                                    <div className="text-[10px] font-black uppercase tracking-widest text-neutral-400">Location</div>
                                    <div className="font-bold text-lg">{city}, {state}</div>
                                </div>
                                <div className="space-y-1">
                                    <div className="text-[10px] font-black uppercase tracking-widest text-neutral-400">Team Scale</div>
                                    <div className="font-bold text-lg">{employeeCount} Employees / {branchCount} Branches</div>
                                </div>
                            </div>

                            <div className="mt-12 pt-8 border-t border-neutral-100 dark:border-neutral-800">
                                <h3 className="text-xs font-black uppercase tracking-widest text-neutral-400 mb-6">Activated Modules</h3>
                                <div className="flex flex-wrap gap-2">
                                    {selectedModules.map(moduleId => {
                                        const m = MODULES.find(mod => mod.id === moduleId);
                                        return m ? (
                                            <div key={moduleId} className="px-4 py-2 bg-neutral-50 dark:bg-neutral-800 rounded-xl text-xs font-bold border border-neutral-100 dark:border-neutral-800 flex items-center gap-2">
                                                <span className="text-lg">{m.icon}</span> {m.name}
                                            </div>
                                        ) : null;
                                    })}
                                </div>
                            </div>
                        </div>

                        <div className="glass-card p-6 rounded-[2rem] border-brand-100 dark:border-brand-900/30 flex items-center justify-between">
                            <div className="flex items-center gap-4">
                                <div className="w-12 h-12 rounded-2xl bg-brand-100 dark:bg-brand-900/30 flex items-center justify-center text-brand-600">
                                    <Shield className="w-6 h-6" />
                                </div>
                                <div>
                                    <div className="text-xs font-black uppercase tracking-widest text-neutral-400">Security Ready</div>
                                    <div className="text-sm font-bold">Encrypted Data & Tenant Isolation Activated</div>
                                </div>
                            </div>
                            <div className="text-right">
                                <div className="text-[10px] font-black text-emerald-600 uppercase tracking-widest">Master Admin</div>
                                <div className="text-sm font-bold">{adminName}</div>
                            </div>
                        </div>
                    </div>

                    {/* Final CTA Card */}
                    <div className="md:col-span-2 space-y-6">
                        <div className="p-8 rounded-[2.5rem] bg-neutral-900 dark:bg-neutral-800 text-white space-y-8 relative overflow-hidden shadow-2xl">
                            <div className="absolute top-0 right-0 w-32 h-32 onboarding-gradient-bg opacity-20 blur-[60px]" />

                            <div className="space-y-2">
                                <div className="text-[10px] font-black uppercase tracking-[0.2em] text-neutral-400">Selected Plan</div>
                                <h3 className="text-4xl font-black">{plan.name}</h3>
                                <div className="flex items-baseline gap-2">
                                    <span className="text-3xl font-black onboarding-gradient-text">{plan.price}</span>
                                    <span className="text-xs text-neutral-500 font-bold uppercase tracking-widest">{plan.period}</span>
                                </div>
                            </div>

                            <div className="space-y-4">
                                {plan.features.slice(0, 4).map((f: string, i: number) => (
                                    <div key={i} className="flex items-center gap-3">
                                        <div className="w-5 h-5 rounded-full bg-brand-600/20 flex items-center justify-center">
                                            <Check className="w-3 h-3 text-brand-400" />
                                        </div>
                                        <span className="text-sm text-neutral-300 font-medium">{f}</span>
                                    </div>
                                ))}
                            </div>

                            <div className="pt-4">
                                <button
                                    onClick={handleCompleteSetup}
                                    className="w-full onboarding-gradient-bg py-5 rounded-2xl font-black text-xl shadow-xl shadow-brand-600/20 hover:scale-[1.02] active:scale-[0.98] transition-all flex items-center justify-center gap-3"
                                >
                                    Complete Setup <ArrowRight className="w-6 h-6" />
                                </button>
                                <p className="text-[10px] text-center text-neutral-500 mt-6 font-bold uppercase tracking-widest">
                                    By clicking complete, you agree to our Terms of Service
                                </p>
                            </div>
                        </div>

                        <div className="glass-card p-6 rounded-[2rem] border-neutral-100 dark:border-neutral-800 text-center">
                            <p className="text-xs text-neutral-500 leading-relaxed">
                                Need help? Our experts are ready to assist you in setting up your workspace once you enter the dashboard.
                            </p>
                        </div>
                    </div>
                </div>
            </div>
        );
    };

    // Render current step content
    const renderStepContent = () => {
        switch (currentStep) {
            case 1: return renderWelcome();
            case 2: return renderBusinessInfo();
            case 3: return renderTeamSetup();
            case 4: return renderFeatureSelection();
            case 5: return renderPlanRecommendation();
            case 6: return renderConfirmation();
            default: return null;
        }
    };

    // Check if can proceed to next step
    const canProceed = () => {
        switch (currentStep) {
            case 1: return true;
            case 2: {
                // Business info + admin contact validation
                const hasBusinessInfo = businessName && businessType && sector;
                const hasAdminName = adminName.trim().length > 0;
                const hasValidContact = preferredLogin === 'mobile'
                    ? adminMobile.length === 10
                    : (adminEmail.includes('@') && adminPassword.length >= 8);
                return hasBusinessInfo && hasAdminName && hasValidContact;
            }
            case 3: return employeeCount > 0 && branchCount > 0;
            case 4: return selectedModules.length > 0;
            case 5: return true;
            default: return true;
        }
    };

    return (
        <div className="min-h-screen gradient-mesh py-12 px-4 selection:bg-brand-100 selection:text-brand-900">
            <div className="max-w-5xl mx-auto">
                {/* Progress Stepper */}
                {renderStepper()}

                {/* Main Content Card */}
                <div className="glass-card rounded-[2.5rem] shadow-2xl shadow-brand-900/10 overflow-hidden border-none step-bounce">
                    <div className="p-8 md:p-12">
                        {/* Plan Customizer Modal */}
                        {renderPlanCustomizer()}

                        {/* Step Content */}
                        <div className="min-h-[500px]">
                            {renderStepContent()}
                        </div>

                        {/* Navigation */}
                        {currentStep > 1 && currentStep < 6 && (
                            <div className="flex justify-between items-center mt-12 pt-8 border-t border-neutral-200/50 dark:border-neutral-800/50">
                                <button
                                    onClick={prevStep}
                                    className="btn btn-secondary px-8 py-3 rounded-xl border-neutral-200 dark:border-neutral-800 hover:bg-neutral-50 dark:hover:bg-neutral-900/50"
                                >
                                    <ChevronLeft className="w-5 h-5 mr-2" /> Back
                                </button>

                                {currentStep < 5 && (
                                    <button
                                        onClick={nextStep}
                                        disabled={!canProceed()}
                                        className="onboarding-gradient-bg text-white font-bold px-12 py-3 rounded-xl shadow-lg shadow-brand-600/20 disabled:opacity-50 disabled:shadow-none hover:scale-[1.02] active:scale-[0.98] transition-all flex items-center gap-2"
                                    >
                                        Continue <ChevronRight className="w-5 h-5" />
                                    </button>
                                )}
                            </div>
                        )}
                    </div>
                </div>

                {/* Trust Footer */}
                <div className="mt-8 flex justify-center items-center gap-8 text-neutral-400 dark:text-neutral-500 font-medium text-sm">
                    <div className="flex items-center gap-2">
                        <Shield className="w-4 h-4" /> SSL Encrypted
                    </div>
                    <div className="flex items-center gap-2">
                        <CheckCircle className="w-4 h-4" /> Trusted by 5,000+ Businesses
                    </div>
                </div>
            </div>
        </div>
    );
};

export default TenantOnboarding;

import { logger } from '@/shared/lib/logger';

import React, { useState, useMemo, useRef } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import { RootState, AppDispatch } from "@/app/store/store";
import { addToCart } from "@/entities/sales/model/posSlice";
import { activateEcommerce } from '../../redux/thunks/tenantThunks';
import {
    Search, Filter, Sparkles, Send, Image as ImageIcon,
    Check, ShoppingCart
} from 'lucide-react';
import { Product } from "@repo/shared";
import { getProductRecommendations, searchProductsByImage } from "@/features/ai-intelligence/lib/GeminiService";
import { Tenant } from "@/entities/session/model/core";

// Components
import OnlineStoreSetup from './OnlineStoreSetup';
import ProductCard from './ProductCard';


const OnlineStore: React.FC = () => {
    const dispatch = useDispatch<AppDispatch>();
    const { user } = useSelector((state: RootState) => state.auth);
    const { tenants } = useSelector((state: RootState) => state.tenant);
    const { items: products } = useSelector((state: RootState) => state.inventory);
    const { currentSector, currentBranch } = useSelector((state: RootState) => state.auth);

    const activeTenant = tenants.find((t: Tenant) => t.id === user?.tenantId);
    const ecomConfig = activeTenant?.ecommerceConfig;
    const isEnabled = ecomConfig?.isEnabled || false;
    const currentPlan = ecomConfig?.plan || 'STARTER';

    const [isLoading, setIsLoading] = useState(false);

    // --- Actions ---
    const handleActivate = async () => {
        if (!user?.tenantId) return;
        setIsLoading(true);
        await dispatch(activateEcommerce(user.tenantId));
        setIsLoading(false);
    };

    // --- Storefront State ---
    const [searchTerm, setSearchTerm] = useState('');
    const [showAi, setShowAi] = useState(false);
    const [aiQuery, setAiQuery] = useState('');
    const [aiThinking, setAiThinking] = useState(false);
    const [aiResult, setAiResult] = useState<{ text: string, ids: string[] } | null>(null);
    const [visualSearchImage, setVisualSearchImage] = useState<string | null>(null);
    const [isVisualSearching, setIsVisualSearching] = useState(false);
    const fileInputRef = useRef<HTMLInputElement>(null);
    const [priceRange, setPriceRange] = useState<{ min: string, max: string }>({ min: '', max: '' });
    const [selectedCategories, setSelectedCategories] = useState<string[]>([]);
    const [sortBy, setSortBy] = useState<string>('featured');
    const [inStockOnly, setInStockOnly] = useState(false);

    // --- Data Preparation ---
    const baseProducts = useMemo(() => {
        return products.filter((p: Product) =>
            p.sector === currentSector && (currentBranch === 'All' || p.branchId === currentBranch)
        );
    }, [products, currentSector, currentBranch]);

    const availableCategories = useMemo(() => {
        return Array.from(new Set(baseProducts.map((p: Product) => p.category))) as string[];
    }, [baseProducts]);

    const handleAiSearch = async () => {
        if (!aiQuery.trim()) return;
        setAiThinking(true);
        setAiResult(null);
        try {
            const res = await getProductRecommendations(aiQuery, baseProducts);
            setAiResult({ text: res.recommendationText, ids: res.recommendedIds });
        } catch (e) {
            logger.error(e);
            setAiResult({ text: "I'm having trouble connecting to the brain right now. Please try again.", ids: [] });
        } finally {
            setAiThinking(false);
        }
    };

    const handleVisualSearch = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;
        const url = URL.createObjectURL(file);
        setVisualSearchImage(url);
        setIsVisualSearching(true);
        setAiResult(null);
        try {
            const ids = await searchProductsByImage(file, baseProducts);
            setAiResult({
                text: `I found ${ids.length} products that look similar to your image.`,
                ids: ids
            });
        } catch (err) {
            logger.error(err);
            setAiResult({ text: "Could not analyze image.", ids: [] });
        } finally {
            setIsVisualSearching(false);
        }
    };

    const toggleCategory = (cat: string) => {
        setSelectedCategories(prev =>
            prev.includes(cat) ? prev.filter(c => c !== cat) : [...prev, cat]
        );
    };

    const filteredProducts = useMemo(() => {
        return baseProducts.filter((p: Product) => {
            if (aiResult && aiResult.ids.length > 0) {
                if (!aiResult.ids.includes(p.id)) return false;
            }
            if (searchTerm && !p.name.toLowerCase().includes(searchTerm.toLowerCase()) && !p.category.toLowerCase().includes(searchTerm.toLowerCase())) {
                return false;
            }
            if (selectedCategories.length > 0 && !selectedCategories.includes(p.category)) {
                return false;
            }
            const min = parseFloat(priceRange.min);
            const max = parseFloat(priceRange.max);
            if (!isNaN(min) && p.sellingPrice < min) return false;
            if (!isNaN(max) && p.sellingPrice > max) return false;
            if (inStockOnly && p.stockQty <= 0) return false;
            return true;
        }).sort((a: Product, b: Product) => {
            switch (sortBy) {
                case 'price-asc': return a.sellingPrice - b.sellingPrice;
                case 'price-desc': return b.sellingPrice - a.sellingPrice;
                case 'name': return a.name.localeCompare(b.name);
                default: return 0;
            }
        });
    }, [baseProducts, aiResult, searchTerm, selectedCategories, priceRange, inStockOnly, sortBy]);

    // --- Render ---

    if (!isEnabled) {
        return <OnlineStoreSetup isLoading={isLoading} onActivate={handleActivate} currentPlan={currentPlan} />;
    }

    return (
        <div className="flex flex-col h-full bg-slate-50 dark:bg-slate-950 animate-fade-in relative rounded-3xl overflow-hidden border border-slate-200 dark:border-slate-800">
            {/* --- Top Navigation Bar --- */}
            <div className="sticky top-0 z-30 bg-white/80 dark:bg-slate-900/80 backdrop-blur-md border-b border-slate-200 dark:border-slate-800 px-6 py-4 flex items-center gap-4">
                <div className="flex-1 max-w-2xl relative flex items-center">
                    <input
                        type="text"
                        placeholder="Search for products..."
                        value={searchTerm}
                        onChange={e => setSearchTerm(e.target.value)}
                        className="w-full pl-10 pr-12 py-3 bg-slate-100 dark:bg-slate-800 border-none rounded-2xl text-slate-900 dark:text-white outline-none focus:ring-2 focus:ring-indigo-500 shadow-inner"
                    />
                    <Search className="w-5 h-5 text-slate-400 absolute left-3" />
                    <button
                        onClick={() => fileInputRef.current?.click()}
                        className="absolute right-2 p-1.5 hover:bg-slate-200 dark:hover:bg-slate-700 rounded-lg text-slate-500 transition-colors"
                        title="Search by Image"
                    >
                        <ImageIcon className="w-5 h-5" />
                    </button>
                    <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleVisualSearch} />
                </div>

                <div className="flex items-center gap-2 ml-auto">
                    <button
                        onClick={() => setShowAi(!showAi)}
                        className={`hidden md:flex items-center gap-2 px-6 py-3 rounded-2xl font-black text-xs uppercase tracking-widest transition-all border ${showAi ? 'bg-indigo-600 text-white border-indigo-600' : 'bg-white dark:bg-slate-800 text-indigo-600 dark:text-indigo-400 border-indigo-200 dark:border-indigo-900'}`}
                    >
                        <Sparkles className="w-4 h-4" />
                        <span>AI Assistant</span>
                    </button>
                </div>
            </div>

            <div className="flex flex-1 overflow-hidden relative">
                {/* --- Sidebar Filters (Desktop) --- */}
                <aside className={`w-72 bg-white dark:bg-slate-900 border-r border-slate-200 dark:border-slate-800 overflow-y-auto hidden md:block p-8`}>
                    <div className="flex items-center gap-2 mb-8 text-slate-900 dark:text-white font-black text-lg">
                        <Filter className="w-5 h-5" /> Filters
                    </div>

                    <div className="space-y-8">
                        <div>
                            <h4 className="text-xs font-black text-slate-400 uppercase tracking-widest mb-4">Categories</h4>
                            <div className="space-y-3">
                                {availableCategories.map(cat => (
                                    <label key={cat} className="flex items-center gap-3 cursor-pointer group">
                                        <div className={`w-5 h-5 rounded border flex items-center justify-center transition-colors ${selectedCategories.includes(cat) ? 'bg-indigo-600 border-indigo-600' : 'border-slate-300 dark:border-slate-600 bg-white dark:bg-slate-800'}`}>
                                            {selectedCategories.includes(cat) && <Check className="w-3.5 h-3.5 text-white" />}
                                        </div>
                                        <input type="checkbox" className="hidden" onChange={() => toggleCategory(cat)} checked={selectedCategories.includes(cat)} />
                                        <span className={`text-sm ${selectedCategories.includes(cat) ? 'text-slate-900 dark:text-white font-bold' : 'text-slate-600 dark:text-slate-400'}`}>{cat}</span>
                                    </label>
                                ))}
                            </div>
                        </div>
                    </div>
                </aside>

                {/* --- Main Content Area --- */}
                <main className="flex-1 overflow-y-auto p-6 md:p-10">
                    {(showAi || aiResult || visualSearchImage) && (
                        <div className="mb-8 bg-white dark:bg-slate-900 rounded-[2rem] border border-indigo-100 dark:border-indigo-900 shadow-xl overflow-hidden animate-in slide-in-from-top-2">
                            <div className="p-6">
                                {showAi && !visualSearchImage && !aiResult && !aiThinking && (
                                    <div className="relative">
                                        <textarea
                                            value={aiQuery}
                                            onChange={e => setAiQuery(e.target.value)}
                                            placeholder="Describe what you are looking for..."
                                            className="w-full bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-700 rounded-2xl p-6 pr-14 text-sm focus:ring-2 focus:ring-indigo-500 outline-none resize-none h-24 text-slate-900 dark:text-white placeholder:text-slate-400 font-medium"
                                            onKeyDown={e => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleAiSearch(); } }}
                                        />
                                        <button onClick={handleAiSearch} disabled={!aiQuery.trim()} className="absolute right-4 bottom-4 p-3 bg-indigo-600 text-white rounded-xl hover:bg-indigo-500 disabled:opacity-50 transition-all shadow-lg shadow-indigo-500/20">
                                            <Send className="w-4 h-4" />
                                        </button>
                                    </div>
                                )}
                                {aiResult && <div className="p-4 bg-slate-50 dark:bg-slate-800 rounded-2xl text-sm font-medium leading-relaxed">{aiResult.text}</div>}
                            </div>
                        </div>
                    )}

                    {/* Product Grid */}
                    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-8">
                        {filteredProducts.map((product: Product) => (
                            <ProductCard
                                key={product.id}
                                product={product}
                                onAddToCart={(p) => dispatch(addToCart({ ...p, qty: 1, price: p.sellingPrice }))}
                            />
                        ))}
                        {filteredProducts.length === 0 && (
                            <div className="col-span-full py-20 text-center">
                                <ShoppingCart className="w-16 h-16 text-slate-300 mx-auto mb-4 opacity-20" />
                                <p className="text-slate-500 font-medium text-lg">No products found matching your search.</p>
                            </div>
                        )}
                    </div>
                </main>
            </div>
        </div>
    );
};

export default OnlineStore;

import { useState, useEffect } from "react";
import { useDispatch, useSelector } from "react-redux";
import { useNavigate } from "react-router-dom";
import { toast } from "react-toastify";
import { addCustomer, reset, getAllCustomers } from "@/entities/contact/model/customerSlice";
import { Layout, PageHeader } from "@/shared/ui";
import { Info } from 'lucide-react';
import CustomerForm from "./components/CustomerForm";
import { RootState, AppDispatch } from "@/app/store/store";
import "react-toastify/dist/ReactToastify.css";

const AddCustomer = () => {
    const navigate = useNavigate();
    const dispatch = useDispatch<AppDispatch>();

    const { isLoading, isSuccess, customers } = useSelector(
        (state: RootState) => state.customers
    );

    const [shouldNavigate, setShouldNavigate] = useState(false);
    const [duplicateField, setDuplicateField] = useState<string | null>(null);

    useEffect(() => {
        dispatch(getAllCustomers());
    }, [dispatch]);

    useEffect(() => {
        if (shouldNavigate && isSuccess) {
            navigate("/customers");
            dispatch(reset());
        }
    }, [shouldNavigate, isSuccess, navigate, dispatch]);

    const onSubmit = async (formData: any) => {
        setDuplicateField(null);
        const result: any = await dispatch(addCustomer(formData));
        if (result.type === 'customers/add/fulfilled') {
            toast.success("Customer indexed successfully!");
            setShouldNavigate(true);
        } else if (result.type === 'customers/add/rejected') {
            const errorMsg = result.payload || "Terminal sync failure";
            toast.error(errorMsg);

            if (errorMsg.toLowerCase().includes('phone')) {
                setDuplicateField('phone');
            } else if (errorMsg.toLowerCase().includes('email')) {
                setDuplicateField('email');
            }
        }
    };

    return (
        <Layout>
            <PageHeader
                title="Consumer Onboarding"
                description="Register high-value partners into the global marketplace terminal"
                breadcrumbs={[{ label: 'Portfolio', link: '/customers' }, { label: 'New Onboarding' }]}
                actions={
                    <button
                        onClick={() => navigate('/customers')}
                        className="px-6 py-2 border border-slate-200 dark:border-slate-800 text-slate-600 dark:text-slate-400 rounded-xl text-sm font-bold hover:bg-slate-50 transition-all font-medium"
                    >
                        Abort Sync
                    </button>
                }
            />

            <div className="max-w-5xl mx-auto space-y-6">
                <div className="bg-indigo-50 dark:bg-indigo-900/10 border border-indigo-100 dark:border-indigo-800/30 p-4 rounded-2xl flex items-start gap-4">
                    <div className="p-2 bg-indigo-100 dark:bg-indigo-900/30 rounded-xl">
                        <Info className="w-5 h-5 text-indigo-600" />
                    </div>
                    <div>
                        <p className="text-xs font-black text-indigo-900 dark:text-indigo-300 uppercase tracking-widest leading-none mt-1">Onboarding Protocol</p>
                        <p className="text-[11px] text-indigo-600 dark:text-indigo-400 font-medium mt-2 leading-relaxed italic">All consumer records are multi-indexed by phone number and email to prevent marketplace duplication. Ensure accuracy of contact nodes for logistics integrity.</p>
                    </div>
                </div>

                <CustomerForm
                    customers={customers}
                    onSubmit={onSubmit}
                    isLoading={isLoading}
                    duplicateField={duplicateField}
                    submitLabel="Commit Partnership"
                    onCancel={() => navigate('/customers')}
                />
            </div>
        </Layout>
    );
};

export default AddCustomer;

import React, { useState, useMemo } from 'react';
import { useSelector } from 'react-redux';
import { RootState } from "@/app/store/store";
import {
    Search,
    Users,
    FolderPlus,
    Edit,
    Trash2,
    Tag,
    Percent,
    UserPlus,
    ChevronDown,
    ChevronUp,
    Crown,
    ShoppingBag,
    Building,
    Star
} from 'lucide-react';

interface CustomerGroup {
    id: string;
    name: string;
    description: string;
    color: string;
    discountPercent: number;
    creditLimit: number;
    paymentTerms: number; // days
    memberCount: number;
    icon: string;
}

const DEFAULT_GROUPS: CustomerGroup[] = [
    { id: 'retail', name: 'Retail', description: 'Walk-in retail customers', color: '#3b82f6', discountPercent: 0, creditLimit: 5000, paymentTerms: 0, memberCount: 0, icon: 'shopping' },
    { id: 'wholesale', name: 'Wholesale', description: 'Bulk purchase customers', color: '#8b5cf6', discountPercent: 10, creditLimit: 50000, paymentTerms: 30, memberCount: 0, icon: 'building' },
    { id: 'vip', name: 'VIP', description: 'Premium loyalty customers', color: '#f59e0b', discountPercent: 15, creditLimit: 100000, paymentTerms: 45, memberCount: 0, icon: 'crown' },
    { id: 'corporate', name: 'Corporate', description: 'Business accounts', color: '#10b981', discountPercent: 12, creditLimit: 200000, paymentTerms: 60, memberCount: 0, icon: 'building' }
];

const CustomerGroups: React.FC = () => {
    const { customers } = useSelector((state: RootState) => state.customers);

    const [groups, setGroups] = useState<CustomerGroup[]>(DEFAULT_GROUPS);
    const [searchTerm, setSearchTerm] = useState('');
    const [expandedGroup, setExpandedGroup] = useState<string | null>(null);
    const [showAddModal, setShowAddModal] = useState(false);
    const [editingGroup, setEditingGroup] = useState<CustomerGroup | null>(null);

    // Calculate member counts
    const groupsWithCounts = useMemo(() => {
        return groups.map(group => ({
            ...group,
            memberCount: customers.filter(c => (c as any).groupId === group.id).length
        }));
    }, [groups, customers]);

    const filteredGroups = groupsWithCounts.filter(g =>
        g.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
        g.description.toLowerCase().includes(searchTerm.toLowerCase())
    );

    const getGroupIcon = (iconName: string) => {
        switch (iconName) {
            case 'crown': return <Crown className="w-5 h-5" />;
            case 'building': return <Building className="w-5 h-5" />;
            case 'shopping': return <ShoppingBag className="w-5 h-5" />;
            default: return <Users className="w-5 h-5" />;
        }
    };

    const totalCustomers = customers.length;
    const assignedCustomers = groupsWithCounts.reduce((acc, g) => acc + g.memberCount, 0);

    return (
        <div className="space-y-6 animate-fade-in">
            {/* Header */}
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                <div>
                    <h2 className="text-2xl font-bold text-neutral-900 dark:text-white flex items-center gap-2">
                        <Tag className="w-6 h-6 text-primary" />
                        Customer Groups
                    </h2>
                    <p className="text-neutral-500 text-sm mt-1">Organize customers into groups with custom pricing and terms</p>
                </div>
                <button
                    onClick={() => setShowAddModal(true)}
                    className="px-4 py-2 bg-primary text-white rounded-lg text-sm font-bold hover:bg-primary/90 flex items-center gap-2"
                >
                    <FolderPlus className="w-4 h-4" /> Create Group
                </button>
            </div>

            {/* Summary Cards */}
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                <div className="bg-white dark:bg-neutral-800 p-4 rounded-xl border border-neutral-200 dark:border-neutral-700">
                    <p className="text-xs font-medium text-neutral-500 uppercase">Total Groups</p>
                    <p className="text-2xl font-bold text-neutral-900 dark:text-white mt-1">{groups.length}</p>
                </div>
                <div className="bg-white dark:bg-neutral-800 p-4 rounded-xl border border-neutral-200 dark:border-neutral-700">
                    <p className="text-xs font-medium text-neutral-500 uppercase">Total Customers</p>
                    <p className="text-2xl font-bold text-primary mt-1">{totalCustomers}</p>
                </div>
                <div className="bg-white dark:bg-neutral-800 p-4 rounded-xl border border-neutral-200 dark:border-neutral-700">
                    <p className="text-xs font-medium text-neutral-500 uppercase">Assigned</p>
                    <p className="text-2xl font-bold text-success mt-1">{assignedCustomers}</p>
                </div>
                <div className="bg-white dark:bg-neutral-800 p-4 rounded-xl border border-neutral-200 dark:border-neutral-700">
                    <p className="text-xs font-medium text-neutral-500 uppercase">Unassigned</p>
                    <p className="text-2xl font-bold text-warning mt-1">{totalCustomers - assignedCustomers}</p>
                </div>
            </div>

            {/* Search */}
            <div className="bg-white dark:bg-neutral-800 p-4 rounded-xl border border-neutral-200 dark:border-neutral-700">
                <div className="relative max-w-md">
                    <input
                        type="text"
                        placeholder="Search groups..."
                        className="w-full pl-9 pr-4 py-2 bg-neutral-100 dark:bg-neutral-700 border border-neutral-200 dark:border-neutral-600 rounded-lg text-neutral-900 dark:text-white text-sm"
                        value={searchTerm}
                        onChange={e => setSearchTerm(e.target.value)}
                    />
                    <Search className="w-4 h-4 absolute left-3 top-2.5 text-neutral-400" />
                </div>
            </div>

            {/* Groups List */}
            <div className="space-y-4">
                {filteredGroups.length === 0 ? (
                    <div className="bg-white dark:bg-neutral-800 p-12 rounded-xl border border-neutral-200 dark:border-neutral-700 text-center">
                        <Tag className="w-12 h-12 mx-auto mb-4 text-neutral-300" />
                        <p className="text-neutral-500">No customer groups found</p>
                    </div>
                ) : (
                    filteredGroups.map(group => (
                        <div key={group.id} className="bg-white dark:bg-neutral-800 rounded-xl border border-neutral-200 dark:border-neutral-700 overflow-hidden">
                            {/* Group Header */}
                            <div
                                className="p-4 flex justify-between items-center cursor-pointer hover:bg-neutral-50 dark:hover:bg-neutral-700/50"
                                onClick={() => setExpandedGroup(expandedGroup === group.id ? null : group.id)}
                            >
                                <div className="flex items-center gap-4">
                                    <div
                                        className="w-12 h-12 rounded-xl flex items-center justify-center text-white"
                                        style={{ backgroundColor: group.color }}
                                    >
                                        {getGroupIcon(group.icon)}
                                    </div>
                                    <div>
                                        <h3 className="font-bold text-neutral-900 dark:text-white">{group.name}</h3>
                                        <p className="text-sm text-neutral-500">{group.description}</p>
                                    </div>
                                </div>
                                <div className="flex items-center gap-6">
                                    <div className="text-center hidden md:block">
                                        <p className="text-xs text-neutral-500">Members</p>
                                        <p className="font-bold text-primary">{group.memberCount}</p>
                                    </div>
                                    <div className="text-center hidden md:block">
                                        <p className="text-xs text-neutral-500">Discount</p>
                                        <p className="font-bold text-success">{group.discountPercent}%</p>
                                    </div>
                                    <div className="text-center hidden md:block">
                                        <p className="text-xs text-neutral-500">Credit Limit</p>
                                        <p className="font-bold text-neutral-700 dark:text-neutral-300">₹{group.creditLimit.toLocaleString()}</p>
                                    </div>
                                    {expandedGroup === group.id ? (
                                        <ChevronUp className="w-5 h-5 text-neutral-400" />
                                    ) : (
                                        <ChevronDown className="w-5 h-5 text-neutral-400" />
                                    )}
                                </div>
                            </div>

                            {/* Expanded Details */}
                            {expandedGroup === group.id && (
                                <div className="border-t border-neutral-100 dark:border-neutral-700 p-4 bg-neutral-50 dark:bg-neutral-900">
                                    <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-4">
                                        <div className="bg-white dark:bg-neutral-800 p-3 rounded-lg">
                                            <p className="text-xs text-neutral-500 flex items-center gap-1">
                                                <Users className="w-3 h-3" /> Members
                                            </p>
                                            <p className="text-lg font-bold text-primary">{group.memberCount}</p>
                                        </div>
                                        <div className="bg-white dark:bg-neutral-800 p-3 rounded-lg">
                                            <p className="text-xs text-neutral-500 flex items-center gap-1">
                                                <Percent className="w-3 h-3" /> Default Discount
                                            </p>
                                            <p className="text-lg font-bold text-success">{group.discountPercent}%</p>
                                        </div>
                                        <div className="bg-white dark:bg-neutral-800 p-3 rounded-lg">
                                            <p className="text-xs text-neutral-500">Credit Limit</p>
                                            <p className="text-lg font-bold text-neutral-700 dark:text-neutral-300">₹{group.creditLimit.toLocaleString()}</p>
                                        </div>
                                        <div className="bg-white dark:bg-neutral-800 p-3 rounded-lg">
                                            <p className="text-xs text-neutral-500">Payment Terms</p>
                                            <p className="text-lg font-bold text-neutral-700 dark:text-neutral-300">{group.paymentTerms} days</p>
                                        </div>
                                    </div>

                                    <div className="flex gap-2">
                                        <button
                                            onClick={() => setEditingGroup(group)}
                                            className="px-4 py-2 bg-white dark:bg-neutral-800 border border-neutral-200 dark:border-neutral-700 rounded-lg text-sm font-medium hover:bg-neutral-100 dark:hover:bg-neutral-700 flex items-center gap-2"
                                        >
                                            <Edit className="w-4 h-4" /> Edit Group
                                        </button>
                                        <button className="px-4 py-2 bg-primary/10 text-primary rounded-lg text-sm font-bold hover:bg-primary/20 flex items-center gap-2">
                                            <UserPlus className="w-4 h-4" /> Add Members
                                        </button>
                                        <button className="px-4 py-2 bg-error/10 text-error rounded-lg text-sm font-bold hover:bg-error/20 flex items-center gap-2 ml-auto">
                                            <Trash2 className="w-4 h-4" /> Delete
                                        </button>
                                    </div>
                                </div>
                            )}
                        </div>
                    ))
                )}
            </div>

            {/* Quick Tips */}
            <div className="bg-gradient-to-r from-primary/10 to-primary/5 p-4 rounded-xl border border-primary/20">
                <h4 className="font-bold text-neutral-900 dark:text-white flex items-center gap-2">
                    <Star className="w-4 h-4 text-primary" /> Tips for Customer Groups
                </h4>
                <ul className="text-sm text-neutral-600 dark:text-neutral-400 mt-2 space-y-1">
                    <li>• Set different discount rates for wholesale vs retail customers</li>
                    <li>• Define credit limits based on customer reliability</li>
                    <li>• Use payment terms to manage cash flow expectations</li>
                    <li>• Create VIP groups for your best customers with special privileges</li>
                </ul>
            </div>
        </div>
    );
};

