    Book,
    User,
    Calendar,
    TrendingUp,
    TrendingDown,
    Download,
    Filter,
    ChevronDown,
    ChevronUp,
    Receipt,
    CreditCard,
    RotateCcw
} from 'lucide-react';

interface LedgerEntry {
    id: string;
    date: string;
    type: 'SALE' | 'PAYMENT' | 'RETURN' | 'CREDIT_NOTE';
    reference: string;
    description: string;
    debit: number;
    credit: number;
    balance: number;
}

interface CustomerLedger {
    customerId: string;
    customerName: string;
    phone?: string;
    openingBalance: number;
    closingBalance: number;
    totalDebit: number;
    totalCredit: number;
    entries: LedgerEntry[];
}

const CustomerLedgerPage: React.FC = () => {
    const { customers } = useSelector((state: RootState) => state.customers);
    const { invoices: salesHistory } = useSelector((state: RootState) => state.pos);
    const { currentSector } = useSelector((state: RootState) => state.auth);

    const [selectedCustomerId, setSelectedCustomerId] = useState<string | null>(null);
    const [searchTerm, setSearchTerm] = useState('');
    const [dateFrom, setDateFrom] = useState('');
    const [dateTo, setDateTo] = useState('');
    const [expandedCustomers, setExpandedCustomers] = useState<Set<string>>(new Set());

    // Build ledger for each customer
    const customerLedgers: CustomerLedger[] = useMemo(() => {
        return customers.map(customer => {
            const entries: LedgerEntry[] = [];
            let runningBalance = 0;
            let totalDebit = 0;
            let totalCredit = 0;

            // Get sales for this customer
            const customerSales = salesHistory
                .filter(s => {
                    const cid = typeof s.customer === 'string' ? s.customer : s.customer?._id || s.customer?.id;
                    return cid === customer.id && s.sector === currentSector;
                })
                .sort((a, b) => new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime());

            customerSales.forEach(sale => {
                const saleId = sale._id || sale.id;
                // Sale entry (debit - customer owes us)
                runningBalance += sale.totalAmount;
                totalDebit += sale.totalAmount;
                entries.push({
                    id: `sale-${saleId}`,
                    date: sale.createdAt,
                    type: 'SALE',
                    reference: `INV-${saleId.substring(0, 8)}`,
                    description: `Invoice for ${sale.items.length} items`,
                    debit: sale.totalAmount,
                    credit: 0,
                    balance: runningBalance
                });

                // Payment entry (credit - customer paid)
                const paidAmount = sale.paidAmount ?? sale.totalAmount;
                if (paidAmount > 0) {
                    runningBalance -= paidAmount;
                    totalCredit += paidAmount;
                    entries.push({
                        id: `pay-${saleId}`,
                        date: sale.createdAt,
                        type: 'PAYMENT',
                        reference: `REC-${saleId.substring(0, 6)}`,
                        description: `Payment received`,
                        debit: 0,
                        credit: paidAmount,
                        balance: runningBalance
                    });
                }
            });

            return {
                customerId: customer.id,
                customerName: customer.name,
                phone: customer.phone,
                openingBalance: 0,
                closingBalance: runningBalance,
                totalDebit,
                totalCredit,
                entries
            };
        });
    }, [customers, salesHistory, currentSector]);

    // Filter customers
    const filteredLedgers = useMemo(() => {
        return customerLedgers.filter(ledger => {
            if (searchTerm) {
                const search = searchTerm.toLowerCase();
                if (!ledger.customerName.toLowerCase().includes(search) &&
                    !ledger.phone?.includes(searchTerm)) {
                    return false;
                }
            }
            // Only show customers with transactions
            if (ledger.entries.length === 0) return false;
            return true;
        });
    }, [customerLedgers, searchTerm]);

    // Selected customer's ledger
    const selectedLedger = selectedCustomerId
        ? customerLedgers.find(l => l.customerId === selectedCustomerId)
        : null;

    // Filter entries by date
    const filteredEntries = useMemo(() => {
        if (!selectedLedger) return [];
        return selectedLedger.entries.filter(entry => {
            if (dateFrom && new Date(entry.date) < new Date(dateFrom)) return false;
            if (dateTo) {
                const nextDay = new Date(dateTo);
                nextDay.setDate(nextDay.getDate() + 1);
                if (new Date(entry.date) >= nextDay) return false;
            }
            return true;
        });
    }, [selectedLedger, dateFrom, dateTo]);

    const toggleExpand = (customerId: string) => {
        const newExpanded = new Set(expandedCustomers);
        if (newExpanded.has(customerId)) {
            newExpanded.delete(customerId);
        } else {
            newExpanded.add(customerId);
        }
        setExpandedCustomers(newExpanded);
    };

    const getTypeIcon = (type: string) => {
        switch (type) {
            case 'SALE': return <Receipt className="w-4 h-4 text-primary" />;
            case 'PAYMENT': return <CreditCard className="w-4 h-4 text-success" />;
            case 'RETURN': return <RotateCcw className="w-4 h-4 text-warning" />;
            default: return <Receipt className="w-4 h-4 text-neutral-400" />;
        }
    };

    // Summary stats
    const totalReceivable = filteredLedgers.reduce((acc, l) => acc + Math.max(0, l.closingBalance), 0);
    const totalAdvance = filteredLedgers.reduce((acc, l) => acc + Math.abs(Math.min(0, l.closingBalance)), 0);

    return (
        <div className="space-y-6 animate-fade-in">
            {/* Header */}
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                <div>
                    <h2 className="text-2xl font-bold text-neutral-900 dark:text-white flex items-center gap-2">
                        <Book className="w-6 h-6 text-primary" />
                        Customer Ledger
                    </h2>
                    <p className="text-neutral-500 text-sm mt-1">View transaction history and balances for each customer</p>
                </div>
                <button className="px-4 py-2 bg-white dark:bg-neutral-800 border border-neutral-200 dark:border-neutral-700 rounded-lg text-sm font-medium hover:bg-neutral-50 dark:hover:bg-neutral-700 flex items-center gap-2">
                    <Download className="w-4 h-4" /> Export Ledger
                </button>
            </div>

            {/* Summary Cards */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                <div className="bg-white dark:bg-neutral-800 p-5 rounded-xl border border-neutral-200 dark:border-neutral-700">
                    <div className="flex items-center justify-between">
                        <div>
                            <p className="text-xs font-medium text-neutral-500 uppercase">Customers with Balance</p>
                            <p className="text-2xl font-bold text-neutral-900 dark:text-white mt-1">{filteredLedgers.length}</p>
                        </div>
                        <div className="p-3 bg-primary/10 rounded-xl">
                            <User className="w-6 h-6 text-primary" />
                        </div>
                    </div>
                </div>

                <div className="bg-white dark:bg-neutral-800 p-5 rounded-xl border border-neutral-200 dark:border-neutral-700">
                    <div className="flex items-center justify-between">
                        <div>
                            <p className="text-xs font-medium text-neutral-500 uppercase">Total Receivable</p>
                            <p className="text-2xl font-bold text-error mt-1">₹{totalReceivable.toLocaleString()}</p>
                        </div>
                        <div className="p-3 bg-error/10 rounded-xl">
                            <TrendingDown className="w-6 h-6 text-error" />
                        </div>
                    </div>
                </div>

                <div className="bg-white dark:bg-neutral-800 p-5 rounded-xl border border-neutral-200 dark:border-neutral-700">
                    <div className="flex items-center justify-between">
                        <div>
                            <p className="text-xs font-medium text-neutral-500 uppercase">Total Advance</p>
                            <p className="text-2xl font-bold text-success mt-1">₹{totalAdvance.toLocaleString()}</p>
                        </div>
                        <div className="p-3 bg-success/10 rounded-xl">
                            <TrendingUp className="w-6 h-6 text-success" />
                        </div>
                    </div>
                </div>
            </div>

            {/* Search */}
            <div className="bg-white dark:bg-neutral-800 p-4 rounded-xl border border-neutral-200 dark:border-neutral-700 flex flex-wrap gap-4 items-end">
                <div className="flex-1 min-w-[250px]">
                    <label className="text-xs text-neutral-500 font-bold uppercase mb-1 block">Search Customer</label>
                    <div className="relative">
                        <input
                            type="text"
                            placeholder="Name or phone..."
                            className="w-full pl-9 pr-4 py-2 bg-neutral-100 dark:bg-neutral-700 border border-neutral-200 dark:border-neutral-600 rounded-lg text-neutral-900 dark:text-white text-sm"
                            value={searchTerm}
                            onChange={e => setSearchTerm(e.target.value)}
                        />
                        <Search className="w-4 h-4 absolute left-3 top-2.5 text-neutral-400" />
                    </div>
                </div>

                {selectedLedger && (
                    <>
                        <div>
                            <label className="text-xs text-neutral-500 font-bold uppercase mb-1 block">From Date</label>
                            <input
                                type="date"
                                className="px-3 py-2 bg-neutral-100 dark:bg-neutral-700 border border-neutral-200 dark:border-neutral-600 rounded-lg text-neutral-900 dark:text-white text-sm"
                                value={dateFrom}
                                onChange={e => setDateFrom(e.target.value)}
                            />
                        </div>
                        <div>
                            <label className="text-xs text-neutral-500 font-bold uppercase mb-1 block">To Date</label>
                            <input
                                type="date"
                                className="px-3 py-2 bg-neutral-100 dark:bg-neutral-700 border border-neutral-200 dark:border-neutral-600 rounded-lg text-neutral-900 dark:text-white text-sm"
                                value={dateTo}
                                onChange={e => setDateTo(e.target.value)}
                            />
                        </div>
                    </>
                )}
            </div>

            {/* Customer List with Expandable Ledgers */}
            <div className="space-y-3">
                {filteredLedgers.length === 0 ? (
                    <div className="bg-white dark:bg-neutral-800 p-8 rounded-xl border border-neutral-200 dark:border-neutral-700 text-center text-neutral-500">
                        <Book className="w-12 h-12 mx-auto mb-2 text-neutral-300" />
                        <p>No customer ledgers found</p>
                    </div>
                ) : (
                    filteredLedgers.map(ledger => (
                        <div key={ledger.customerId} className="bg-white dark:bg-neutral-800 rounded-xl border border-neutral-200 dark:border-neutral-700 overflow-hidden">
                            {/* Customer Header */}
                            <div
                                className="p-4 flex justify-between items-center cursor-pointer hover:bg-neutral-50 dark:hover:bg-neutral-700/50"
                                onClick={() => toggleExpand(ledger.customerId)}
                            >
                                <div className="flex items-center gap-3">
                                    <div className="w-10 h-10 rounded-full bg-gradient-to-br from-primary to-primary/60 flex items-center justify-center">
                                        <span className="text-white font-bold">{ledger.customerName.charAt(0)}</span>
                                    </div>
                                    <div>
                                        <p className="font-bold text-neutral-900 dark:text-white">{ledger.customerName}</p>
                                        <p className="text-xs text-neutral-500">{ledger.phone || 'No phone'} • {ledger.entries.length} transactions</p>
                                    </div>
                                </div>
                                <div className="flex items-center gap-4">
                                    <div className="text-right">
                                        <p className="text-xs text-neutral-500">Balance</p>
                                        <p className={`font-bold ${ledger.closingBalance > 0 ? 'text-error' : ledger.closingBalance < 0 ? 'text-success' : 'text-neutral-500'}`}>
                                            {ledger.closingBalance > 0 ? '₹' : ledger.closingBalance < 0 ? '-₹' : '₹'}
                                            {Math.abs(ledger.closingBalance).toLocaleString()}
                                        </p>
                                    </div>
                                    {expandedCustomers.has(ledger.customerId) ? (
                                        <ChevronUp className="w-5 h-5 text-neutral-400" />
                                    ) : (
                                        <ChevronDown className="w-5 h-5 text-neutral-400" />
                                    )}
                                </div>
                            </div>

                            {/* Expanded Ledger Entries */}
                            {expandedCustomers.has(ledger.customerId) && (
                                <div className="border-t border-neutral-100 dark:border-neutral-700">
                                    <table className="w-full text-sm">
                                        <thead className="bg-neutral-50 dark:bg-neutral-900 text-neutral-500 text-xs uppercase">
                                            <tr>
                                                <th className="p-3 text-left">Date</th>
                                                <th className="p-3 text-left">Type</th>
                                                <th className="p-3 text-left">Reference</th>
                                                <th className="p-3 text-left">Description</th>
                                                <th className="p-3 text-right">Debit</th>
                                                <th className="p-3 text-right">Credit</th>
                                                <th className="p-3 text-right">Balance</th>
                                            </tr>
                                        </thead>
                                        <tbody className="divide-y divide-neutral-100 dark:divide-neutral-700">
                                            {ledger.entries.map(entry => (
                                                <tr key={entry.id} className="hover:bg-neutral-50 dark:hover:bg-neutral-800">
                                                    <td className="p-3 text-neutral-600 dark:text-neutral-400">
                                                        {new Date(entry.date).toLocaleDateString()}
                                                    </td>
                                                    <td className="p-3">
                                                        <div className="flex items-center gap-2">
                                                            {getTypeIcon(entry.type)}
                                                            <span className="text-neutral-700 dark:text-neutral-300">{entry.type}</span>
                                                        </div>
                                                    </td>
                                                    <td className="p-3 font-mono text-xs text-primary">{entry.reference}</td>
                                                    <td className="p-3 text-neutral-500">{entry.description}</td>
                                                    <td className="p-3 text-right font-medium text-error">
                                                        {entry.debit > 0 ? `₹${entry.debit.toLocaleString()}` : '-'}
                                                    </td>
                                                    <td className="p-3 text-right font-medium text-success">
                                                        {entry.credit > 0 ? `₹${entry.credit.toLocaleString()}` : '-'}
                                                    </td>
                                                    <td className="p-3 text-right font-bold text-neutral-900 dark:text-white">
                                                        ₹{entry.balance.toLocaleString()}
                                                    </td>
                                                </tr>
                                            ))}
                                        </tbody>
                                        <tfoot className="bg-neutral-50 dark:bg-neutral-900 font-bold">
                                            <tr>
                                                <td colSpan={4} className="p-3 text-right text-neutral-600 dark:text-neutral-400">Totals:</td>
                                                <td className="p-3 text-right text-error">₹{ledger.totalDebit.toLocaleString()}</td>
                                                <td className="p-3 text-right text-success">₹{ledger.totalCredit.toLocaleString()}</td>
                                                <td className="p-3 text-right text-neutral-900 dark:text-white">₹{ledger.closingBalance.toLocaleString()}</td>
                                            </tr>
                                        </tfoot>
                                    </table>
                                </div>
                            )}
                        </div>
                    ))
                )}
            </div>
        </div>
    );
};

export default CustomerLedgerPage;

import React, { useState, useMemo } from 'react';
import { useSelector } from 'react-redux';
import { RootState } from "@/app/store/store";
import {
    Search,
    Users,
    User,
    Phone,
    Mail,
    MapPin,
    TrendingUp,
    Download,
    Plus,
    Eye,
    Edit,
    Star,
    ShoppingBag
} from 'lucide-react';
import Customer360Modal from './Customer360Modal';

const CustomerList: React.FC = () => {
    const { customers } = useSelector((state: RootState) => state.customers);
    const { invoices: salesHistory } = useSelector((state: RootState) => state.pos);
    const { currentSector } = useSelector((state: RootState) => state.auth);

    const [searchTerm, setSearchTerm] = useState('');
    const [sortBy, setSortBy] = useState<'name' | 'purchases' | 'recent'>('name');
    const [filterActive, setFilterActive] = useState<'all' | 'active' | 'inactive'>('all');
    const [selectedCustomer, setSelectedCustomer] = useState<any>(null);
    const [isModalOpen, setIsModalOpen] = useState(false);

    // Calculate customer stats from sales history
    const customerStats = useMemo(() => {
        const stats: Record<string, { totalPurchases: number; purchaseCount: number; lastPurchase: string }> = {};

        salesHistory
            .filter((s: any) => s.sector === currentSector)
            .forEach((sale: any) => {
                const customerId = typeof sale.customer === 'string' ? sale.customer : sale.customer?._id || sale.customer?.id;
                if (customerId) {
                    if (!stats[customerId]) {
                        stats[customerId] = { totalPurchases: 0, purchaseCount: 0, lastPurchase: '' };
                    }
                    stats[customerId].totalPurchases += sale.totalAmount;
                    stats[customerId].purchaseCount++;
                    if (!stats[customerId].lastPurchase || sale.createdAt > stats[customerId].lastPurchase) {
                        stats[customerId].lastPurchase = sale.createdAt;
                    }
                }
            });

        return stats;
    }, [salesHistory, currentSector]);

    // Enrich customers with stats
    const enrichedCustomers = useMemo(() => {
        return (customers as any[]).map((customer: any) => ({
            ...customer,
            totalPurchases: customerStats[customer.id]?.totalPurchases || 0,
            purchaseCount: customerStats[customer.id]?.purchaseCount || 0,
            lastPurchase: customerStats[customer.id]?.lastPurchase || null,
            isActive: customerStats[customer.id]?.purchaseCount > 0
        }));
    }, [customers, customerStats]);

    // Filter and sort
    const filteredCustomers = useMemo(() => {
        const result = enrichedCustomers.filter((customer: any) => {
            if (searchTerm) {
                const search = searchTerm.toLowerCase();
                if (!customer.name.toLowerCase().includes(search) &&
                    !customer.phone?.includes(searchTerm) &&
                    !customer.email?.toLowerCase().includes(search)) {
                    return false;
                }
            }
            if (filterActive === 'active' && !customer.isActive) return false;
            if (filterActive === 'inactive' && customer.isActive) return false;
            return true;
        });

        result.sort((a: any, b: any) => {
            switch (sortBy) {
                case 'name': return a.name.localeCompare(b.name);
                case 'purchases': return b.totalPurchases - a.totalPurchases;
                case 'recent':
                    if (!a.lastPurchase) return 1;
                    if (!b.lastPurchase) return -1;
                    return new Date(b.lastPurchase).getTime() - new Date(a.lastPurchase).getTime();
                default: return 0;
            }
        });

        return result;
    }, [enrichedCustomers, searchTerm, sortBy, filterActive]);

    // Summary stats
    const totalCustomers = customers.length;
    const activeCustomers = enrichedCustomers.filter((c: any) => c.isActive).length;
    const totalRevenue = enrichedCustomers.reduce((acc: number, c: any) => acc + c.totalPurchases, 0);
    const avgPurchaseValue = totalRevenue / Math.max(1, enrichedCustomers.reduce((acc: number, c: any) => acc + c.purchaseCount, 0));

    return (
        <div className="space-y-6 animate-fade-in">
            {/* Header */}
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                <div>
                    <h2 className="text-2xl font-bold text-neutral-900 dark:text-white flex items-center gap-2">
                        <Users className="w-6 h-6 text-primary" />
                        Customer List
                    </h2>
                    <p className="text-neutral-500 text-sm mt-1">Manage your customer database</p>
                </div>
                <div className="flex gap-2">
                    <button className="px-4 py-2 bg-white dark:bg-neutral-800 border border-neutral-200 dark:border-neutral-700 rounded-lg text-sm font-medium hover:bg-neutral-50 dark:hover:bg-neutral-700 flex items-center gap-2">
                        <Download className="w-4 h-4" /> Export
                    </button>
                    <button className="px-4 py-2 bg-primary text-white rounded-lg text-sm font-bold hover:bg-primary/90 flex items-center gap-2">
                        <Plus className="w-4 h-4" /> Add Customer
                    </button>
                </div>
            </div>

            {/* KPI Cards */}
            <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
                <div className="bg-white dark:bg-neutral-800 p-5 rounded-xl border border-neutral-200 dark:border-neutral-700">
                    <div className="flex items-center justify-between">
                        <div>
                            <p className="text-xs font-medium text-neutral-500 uppercase tracking-wide">Total Customers</p>
                            <p className="text-2xl font-bold text-neutral-900 dark:text-white mt-1">{totalCustomers}</p>
                        </div>
                        <div className="p-3 bg-primary/10 rounded-xl">
                            <Users className="w-6 h-6 text-primary" />
                        </div>
                    </div>
                </div>

                <div className="bg-white dark:bg-neutral-800 p-5 rounded-xl border border-neutral-200 dark:border-neutral-700">
                    <div className="flex items-center justify-between">
                        <div>
                            <p className="text-xs font-medium text-neutral-500 uppercase tracking-wide">Active Customers</p>
                            <p className="text-2xl font-bold text-success mt-1">{activeCustomers}</p>
                        </div>
                        <div className="p-3 bg-success/10 rounded-xl">
                            <ShoppingBag className="w-6 h-6 text-success" />
                        </div>
                    </div>
                    <p className="text-xs text-neutral-400 mt-2">{Math.round((activeCustomers / Math.max(1, totalCustomers)) * 100)}% of total</p>
                </div>

                <div className="bg-white dark:bg-neutral-800 p-5 rounded-xl border border-neutral-200 dark:border-neutral-700">
                    <div className="flex items-center justify-between">
                        <div>
                            <p className="text-xs font-medium text-neutral-500 uppercase tracking-wide">Total Revenue</p>
                            <p className="text-2xl font-bold text-primary mt-1">₹{totalRevenue.toLocaleString()}</p>
                        </div>
                        <div className="p-3 bg-primary/10 rounded-xl">
                            <TrendingUp className="w-6 h-6 text-primary" />
                        </div>
                    </div>
                </div>

                <div className="bg-white dark:bg-neutral-800 p-5 rounded-xl border border-neutral-200 dark:border-neutral-700">
                    <div className="flex items-center justify-between">
                        <div>
                            <p className="text-xs font-medium text-neutral-500 uppercase tracking-wide">Avg Transaction</p>
                            <p className="text-2xl font-bold text-neutral-900 dark:text-white mt-1">₹{avgPurchaseValue.toFixed(0)}</p>
                        </div>
                        <div className="p-3 bg-neutral-100 dark:bg-neutral-700 rounded-xl">
                            <Star className="w-6 h-6 text-neutral-600 dark:text-neutral-400" />
                        </div>
                    </div>
                </div>
            </div>

            {/* Filters */}
            <div className="bg-white dark:bg-neutral-800 p-4 rounded-xl border border-neutral-200 dark:border-neutral-700 flex flex-wrap gap-4 items-end">
                <div className="flex-1 min-w-[250px]">
                    <label className="text-xs text-neutral-500 font-bold uppercase mb-1 block">Search</label>
                    <div className="relative">
                        <input
                            type="text"
                            placeholder="Name, phone, or email..."
                            className="w-full pl-9 pr-4 py-2 bg-neutral-100 dark:bg-neutral-700 border border-neutral-200 dark:border-neutral-600 rounded-lg text-neutral-900 dark:text-white text-sm"
                            value={searchTerm}
                            onChange={e => setSearchTerm(e.target.value)}
                        />
                        <Search className="w-4 h-4 absolute left-3 top-2.5 text-neutral-400" />
                    </div>
                </div>

                <div>
                    <label className="text-xs text-neutral-500 font-bold uppercase mb-1 block">Status</label>
                    <select
                        className="px-4 py-2 bg-neutral-100 dark:bg-neutral-700 border border-neutral-200 dark:border-neutral-600 rounded-lg text-neutral-900 dark:text-white text-sm"
                        value={filterActive}
                        onChange={e => setFilterActive(e.target.value as any)}
                    >
                        <option value="all">All Customers</option>
                        <option value="active">Active (Has Purchases)</option>
                        <option value="inactive">Inactive</option>
                    </select>
                </div>

                <div>
                    <label className="text-xs text-neutral-500 font-bold uppercase mb-1 block">Sort By</label>
                    <select
                        className="px-4 py-2 bg-neutral-100 dark:bg-neutral-700 border border-neutral-200 dark:border-neutral-600 rounded-lg text-neutral-900 dark:text-white text-sm"
                        value={sortBy}
                        onChange={e => setSortBy(e.target.value as any)}
                    >
                        <option value="name">Name (A-Z)</option>
                        <option value="purchases">Total Purchases</option>
                        <option value="recent">Most Recent</option>
                    </select>
                </div>
            </div>

            {/* Customer List */}
            <div className="bg-white dark:bg-neutral-800 rounded-xl border border-neutral-200 dark:border-neutral-700 overflow-hidden">
                <div className="hidden md:block overflow-x-auto">
                    <table className="w-full text-left text-sm">
                        <thead className="bg-neutral-50 dark:bg-neutral-900 text-neutral-500 uppercase text-xs font-medium">
                            <tr>
                                <th className="p-4">Customer</th>
                                <th className="p-4">Contact</th>
                                <th className="p-4 text-center">Purchases</th>
                                <th className="p-4 text-right">Total Spent</th>
                                <th className="p-4">Last Purchase</th>
                                <th className="p-4 text-center">Actions</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-neutral-100 dark:divide-neutral-700">
                            {filteredCustomers.length === 0 ? (
                                <tr><td colSpan={6} className="p-8 text-center text-neutral-500">
                                    <div className="flex flex-col items-center gap-2">
                                        <Users className="w-8 h-8 text-neutral-300" />
                                        <p>No customers found</p>
                                    </div>
                                </td></tr>
                            ) : (
                                filteredCustomers.map((customer: any) => (
                                    <tr key={customer.id} className="hover:bg-neutral-50 dark:hover:bg-neutral-700/50">
                                        <td className="p-4">
                                            <div className="flex items-center gap-3">
                                                <div className="w-10 h-10 rounded-full bg-gradient-to-br from-primary to-primary/60 flex items-center justify-center">
                                                    <span className="text-white font-bold">
                                                        {customer.name.charAt(0).toUpperCase()}
                                                    </span>
                                                </div>
                                                <div>
                                                    <p className="font-medium text-neutral-900 dark:text-white">{customer.name}</p>
                                                    {customer.isActive ? (
                                                        <span className="text-[10px] px-1.5 py-0.5 bg-success/10 text-success rounded-full">Active</span>
                                                    ) : (
                                                        <span className="text-[10px] px-1.5 py-0.5 bg-neutral-100 dark:bg-neutral-700 text-neutral-500 rounded-full">New</span>
                                                    )}
                                                </div>
                                            </div>
                                        </td>
                                        <td className="p-4">
                                            <div className="space-y-1">
                                                {customer.phone && (
                                                    <div className="flex items-center gap-1 text-neutral-600 dark:text-neutral-400 text-xs">
                                                        <Phone className="w-3 h-3" /> {customer.phone}
                                                    </div>
                                                )}
                                                {customer.email && (
                                                    <div className="flex items-center gap-1 text-neutral-500 text-xs">
                                                        <Mail className="w-3 h-3" /> {customer.email}
                                                    </div>
                                                )}
                                            </div>
                                        </td>
                                        <td className="p-4 text-center">
                                            <span className="font-bold text-primary">{customer.purchaseCount}</span>
                                        </td>
                                        <td className="p-4 text-right font-bold text-success">
                                            ₹{customer.totalPurchases.toLocaleString()}
                                        </td>
                                        <td className="p-4 text-neutral-500 text-sm">
                                            {customer.lastPurchase
                                                ? new Date(customer.lastPurchase).toLocaleDateString()
                                                : '-'
                                            }
                                        </td>
                                        <td className="p-4">
                                            <div className="flex justify-center gap-1">
                                                <button
                                                    onClick={() => {
                                                        setSelectedCustomer(customer);
                                                        setIsModalOpen(true);
                                                    }}
                                                    className="p-2 hover:bg-neutral-100 dark:hover:bg-neutral-700 rounded-lg"
                                                    title="View"
                                                >
                                                    <Eye className="w-4 h-4 text-primary" />
                                                </button>
                                                <button className="p-2 hover:bg-neutral-100 dark:hover:bg-neutral-700 rounded-lg" title="Edit">
                                                    <Edit className="w-4 h-4 text-neutral-400" />
                                                </button>
                                            </div>
                                        </td>
                                    </tr>
                                ))
                            )}
                        </tbody>
                    </table>
                </div>

                {/* Mobile View */}
                <div className="md:hidden divide-y divide-neutral-100 dark:divide-neutral-700">
                    {filteredCustomers.length === 0 ? (
                        <div className="p-8 text-center text-neutral-500">No customers found</div>
                    ) : (
                        filteredCustomers.map((customer: any) => (
                            <div key={customer.id} className="p-4">
                                <div className="flex justify-between items-start mb-2">
                                    <div className="flex items-center gap-3">
                                        <div className="w-10 h-10 rounded-full bg-gradient-to-br from-primary to-primary/60 flex items-center justify-center">
                                            <span className="text-white font-bold">
                                                {customer.name.charAt(0).toUpperCase()}
                                            </span>
                                        </div>
                                        <div>
                                            <p className="font-bold text-neutral-900 dark:text-white">{customer.name}</p>
                                            {customer.phone && <p className="text-xs text-neutral-500">{customer.phone}</p>}
                                        </div>
                                    </div>
                                    {customer.isActive && (
                                        <span className="text-[10px] px-2 py-0.5 bg-success/10 text-success rounded-full">Active</span>
                                    )}
                                </div>
                                <div className="flex justify-between items-center bg-neutral-50 dark:bg-neutral-700/50 p-3 rounded-lg mt-2">
                                    <div className="text-xs text-neutral-500">
                                        <span className="font-bold text-primary">{customer.purchaseCount}</span> purchases
                                    </div>
                                    <p className="font-bold text-success">₹{customer.totalPurchases.toLocaleString()}</p>
                                </div>
                            </div>
                        ))
                    )}
                </div>
            </div>

            {/* Footer */}
            <div className="text-center text-xs text-neutral-400">
                Showing {filteredCustomers.length} of {totalCustomers} customers
            </div>

            {selectedCustomer && (
                <Customer360Modal
                    isOpen={isModalOpen}
                    onClose={() => setIsModalOpen(false)}
                    customer={selectedCustomer}
                />
            )}
        </div>
    );
};

export default CustomerList;

import React, { useState, useMemo } from 'react';
import { useSelector } from 'react-redux';
import { RootState } from "@/app/store/store";
import {
    Search,
    FileText,
    User,
    Calendar,
    Download,
    Printer,
    Mail,
    Eye,
    Building,
    Phone
} from 'lucide-react';

interface StatementData {
    customerId: string;
    customerName: string;
    phone?: string;
    email?: string;
    periodFrom: string;
    periodTo: string;
    openingBalance: number;
    closingBalance: number;
    transactions: {
        date: string;
        reference: string;
        description: string;
        debit: number;
        credit: number;
        balance: number;
    }[];
}

const CustomerStatements: React.FC = () => {
    const { customers } = useSelector((state: RootState) => state.customers);
    const { invoices: salesHistory } = useSelector((state: RootState) => state.pos);
    const { currentSector } = useSelector((state: RootState) => state.auth);
    const { tenants } = useSelector((state: RootState) => state.tenant);

    const [selectedCustomerId, setSelectedCustomerId] = useState<string>('');
    const [periodFrom, setPeriodFrom] = useState(() => {
        const d = new Date();
        d.setMonth(d.getMonth() - 1);
        return d.toISOString().split('T')[0];
    });
    const [periodTo, setPeriodTo] = useState(() => new Date().toISOString().split('T')[0]);
    const [searchTerm, setSearchTerm] = useState('');
    const [showPreview, setShowPreview] = useState(false);

    // Filter customers
    const filteredCustomers = useMemo(() => {
        return customers.filter(c => {
            if (!searchTerm) return true;
            const search = searchTerm.toLowerCase();
            return c.name.toLowerCase().includes(search) || c.phone?.includes(searchTerm);
        });
    }, [customers, searchTerm]);

    // Generate statement for selected customer
    const statementData: StatementData | null = useMemo(() => {
        if (!selectedCustomerId) return null;

        const customer = customers.find(c => c.id === selectedCustomerId);
        if (!customer) return null;

        const transactions: StatementData['transactions'] = [];
        let runningBalance = 0;

        const customerSales = salesHistory
            .filter(s => {
                const cid = typeof s.customer === 'string' ? s.customer : s.customer?._id || s.customer?.id;
                return (
                    cid === selectedCustomerId &&
                    s.sector === currentSector &&
                    new Date(s.createdAt) >= new Date(periodFrom) &&
                    new Date(s.createdAt) <= new Date(periodTo)
                );
            })
            .sort((a, b) => new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime());

        customerSales.forEach(sale => {
            const saleId = sale._id || sale.id;
            // Sale
            runningBalance += sale.totalAmount;
            transactions.push({
                date: sale.createdAt,
                reference: `INV-${saleId.substring(0, 8)}`,
                description: `Invoice - ${sale.items.length} items`,
                debit: sale.totalAmount,
                credit: 0,
                balance: runningBalance
            });

            // Payment
            const paid = sale.paidAmount ?? sale.totalAmount;
            if (paid > 0) {
                runningBalance -= paid;
                transactions.push({
                    date: sale.createdAt,
                    reference: `REC-${saleId.substring(0, 6)}`,
                    description: 'Payment received',
                    debit: 0,
                    credit: paid,
                    balance: runningBalance
                });
            }
        });

        return {
            customerId: customer.id,
            customerName: customer.name,
            phone: customer.phone,
            email: (customer as any).email,
            periodFrom,
            periodTo,
            openingBalance: 0,
            closingBalance: runningBalance,
            transactions
        };
    }, [selectedCustomerId, customers, salesHistory, currentSector, periodFrom, periodTo]);

    const handlePrint = () => {
        window.print();
    };

    const businessName = tenants[0]?.name || 'Your Business';

    return (
        <div className="space-y-6 animate-fade-in">
            {/* Header */}
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 print:hidden">
                <div>
                    <h2 className="text-2xl font-bold text-neutral-900 dark:text-white flex items-center gap-2">
                        <FileText className="w-6 h-6 text-primary" />
                        Customer Statements
                    </h2>
                    <p className="text-neutral-500 text-sm mt-1">Generate and send account statements to customers</p>
                </div>
            </div>

            {/* Statement Generator */}
            <div className="bg-white dark:bg-neutral-800 p-6 rounded-xl border border-neutral-200 dark:border-neutral-700 print:hidden">
                <h3 className="text-lg font-bold text-neutral-900 dark:text-white mb-4">Generate Statement</h3>

                <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                    <div className="md:col-span-2">
                        <label className="text-xs text-neutral-500 font-bold uppercase mb-1 block">Select Customer</label>
                        <div className="relative">
                            <input
                                type="text"
                                placeholder="Search customer..."
                                className="w-full pl-9 pr-4 py-2 bg-neutral-100 dark:bg-neutral-700 border border-neutral-200 dark:border-neutral-600 rounded-lg text-neutral-900 dark:text-white text-sm mb-2"
                                value={searchTerm}
                                onChange={e => setSearchTerm(e.target.value)}
                            />
                            <Search className="w-4 h-4 absolute left-3 top-2.5 text-neutral-400" />
                        </div>
                        <select
                            className="w-full px-4 py-2 bg-neutral-100 dark:bg-neutral-700 border border-neutral-200 dark:border-neutral-600 rounded-lg text-neutral-900 dark:text-white text-sm"
                            value={selectedCustomerId}
                            onChange={e => setSelectedCustomerId(e.target.value)}
                            size={5}
                        >
                            {filteredCustomers.map(c => (
                                <option key={c.id} value={c.id}>{c.name} {c.phone ? `(${c.phone})` : ''}</option>
                            ))}
                        </select>
                    </div>

                    <div>
                        <label className="text-xs text-neutral-500 font-bold uppercase mb-1 block">Period From</label>
                        <div className="relative">
                            <input
                                type="date"
                                className="w-full pl-9 pr-4 py-2 bg-neutral-100 dark:bg-neutral-700 border border-neutral-200 dark:border-neutral-600 rounded-lg text-neutral-900 dark:text-white text-sm"
                                value={periodFrom}
                                onChange={e => setPeriodFrom(e.target.value)}
                            />
                            <Calendar className="w-4 h-4 absolute left-3 top-2.5 text-neutral-400" />
                        </div>
                    </div>

                    <div>
                        <label className="text-xs text-neutral-500 font-bold uppercase mb-1 block">Period To</label>
                        <div className="relative">
                            <input
                                type="date"
                                className="w-full pl-9 pr-4 py-2 bg-neutral-100 dark:bg-neutral-700 border border-neutral-200 dark:border-neutral-600 rounded-lg text-neutral-900 dark:text-white text-sm"
                                value={periodTo}
                                onChange={e => setPeriodTo(e.target.value)}
                            />
                            <Calendar className="w-4 h-4 absolute left-3 top-2.5 text-neutral-400" />
                        </div>
                    </div>
                </div>

                <div className="flex gap-2 mt-4">
                    <button
                        onClick={() => setShowPreview(true)}
                        disabled={!selectedCustomerId}
                        className="px-4 py-2 bg-primary text-white rounded-lg text-sm font-bold hover:bg-primary/90 disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-2"
                    >
                        <Eye className="w-4 h-4" /> Preview Statement
                    </button>
                    <button
                        onClick={handlePrint}
                        disabled={!statementData}
                        className="px-4 py-2 bg-neutral-200 dark:bg-neutral-700 text-neutral-700 dark:text-neutral-300 rounded-lg text-sm font-bold hover:bg-neutral-300 dark:hover:bg-neutral-600 disabled:opacity-50 flex items-center gap-2"
                    >
                        <Printer className="w-4 h-4" /> Print
                    </button>
                    <button
                        disabled={!statementData}
                        className="px-4 py-2 bg-neutral-200 dark:bg-neutral-700 text-neutral-700 dark:text-neutral-300 rounded-lg text-sm font-bold hover:bg-neutral-300 dark:hover:bg-neutral-600 disabled:opacity-50 flex items-center gap-2"
                    >
                        <Download className="w-4 h-4" /> Download PDF
                    </button>
                    <button
                        disabled={!statementData || !statementData.email}
                        className="px-4 py-2 bg-success text-white rounded-lg text-sm font-bold hover:bg-success/90 disabled:opacity-50 flex items-center gap-2"
                    >
                        <Mail className="w-4 h-4" /> Email to Customer
                    </button>
                </div>
            </div>

            {/* Statement Preview */}
            {statementData && (showPreview || true) && (
                <div className="bg-white dark:bg-neutral-800 p-8 rounded-xl border border-neutral-200 dark:border-neutral-700 print:border-0 print:p-0">
                    {/* Statement Header */}
                    <div className="border-b-2 border-primary pb-4 mb-6 print:border-black">
                        <div className="flex justify-between items-start">
                            <div>
                                <h1 className="text-2xl font-bold text-neutral-900 dark:text-white print:text-black">{businessName}</h1>
                                <p className="text-neutral-500 text-sm print:text-gray-600">Account Statement</p>
                            </div>
                            <div className="text-right">
                                <p className="text-sm text-neutral-600 dark:text-neutral-400 print:text-gray-600">
                                    Statement Date: {new Date().toLocaleDateString()}
                                </p>
                                <p className="text-sm text-neutral-600 dark:text-neutral-400 print:text-gray-600">
                                    Period: {new Date(statementData.periodFrom).toLocaleDateString()} - {new Date(statementData.periodTo).toLocaleDateString()}
                                </p>
                            </div>
                        </div>
                    </div>

                    {/* Customer Details */}
                    <div className="grid grid-cols-2 gap-8 mb-6">
                        <div className="bg-neutral-50 dark:bg-neutral-700/50 p-4 rounded-lg print:bg-gray-100">
                            <h3 className="text-xs font-bold text-neutral-500 uppercase mb-2">Bill To</h3>
                            <p className="font-bold text-neutral-900 dark:text-white print:text-black">{statementData.customerName}</p>
                            {statementData.phone && (
                                <p className="text-sm text-neutral-600 dark:text-neutral-400 flex items-center gap-1">
                                    <Phone className="w-3 h-3" /> {statementData.phone}
                                </p>
                            )}
                            {statementData.email && (
                                <p className="text-sm text-neutral-600 dark:text-neutral-400 flex items-center gap-1">
                                    <Mail className="w-3 h-3" /> {statementData.email}
                                </p>
                            )}
                        </div>
                        <div className="bg-neutral-50 dark:bg-neutral-700/50 p-4 rounded-lg print:bg-gray-100">
                            <h3 className="text-xs font-bold text-neutral-500 uppercase mb-2">Account Summary</h3>
                            <div className="space-y-1">
                                <div className="flex justify-between text-sm">
                                    <span className="text-neutral-600 dark:text-neutral-400">Opening Balance:</span>
                                    <span className="font-medium">₹{statementData.openingBalance.toLocaleString()}</span>
                                </div>
                                <div className="flex justify-between text-sm">
                                    <span className="text-neutral-600 dark:text-neutral-400">Total Invoices:</span>
                                    <span className="font-medium text-error">₹{statementData.transactions.filter(t => t.debit > 0).reduce((a, t) => a + t.debit, 0).toLocaleString()}</span>
                                </div>
                                <div className="flex justify-between text-sm">
                                    <span className="text-neutral-600 dark:text-neutral-400">Total Payments:</span>
                                    <span className="font-medium text-success">₹{statementData.transactions.filter(t => t.credit > 0).reduce((a, t) => a + t.credit, 0).toLocaleString()}</span>
                                </div>
                                <div className="flex justify-between text-sm font-bold border-t pt-1 mt-1">
                                    <span>Closing Balance:</span>
                                    <span className={statementData.closingBalance > 0 ? 'text-error' : 'text-success'}>
                                        ₹{statementData.closingBalance.toLocaleString()}
                                    </span>
                                </div>
                            </div>
                        </div>
                    </div>

                    {/* Transactions Table */}
                    <table className="w-full text-sm border-collapse">
                        <thead>
                            <tr className="bg-neutral-100 dark:bg-neutral-900 print:bg-gray-200">
                                <th className="p-3 text-left border border-neutral-200 dark:border-neutral-700 print:border-gray-300">Date</th>
                                <th className="p-3 text-left border border-neutral-200 dark:border-neutral-700 print:border-gray-300">Reference</th>
                                <th className="p-3 text-left border border-neutral-200 dark:border-neutral-700 print:border-gray-300">Description</th>
                                <th className="p-3 text-right border border-neutral-200 dark:border-neutral-700 print:border-gray-300">Debit</th>
                                <th className="p-3 text-right border border-neutral-200 dark:border-neutral-700 print:border-gray-300">Credit</th>
                                <th className="p-3 text-right border border-neutral-200 dark:border-neutral-700 print:border-gray-300">Balance</th>
                            </tr>
                        </thead>
                        <tbody>
                            {statementData.transactions.length === 0 ? (
                                <tr>
                                    <td colSpan={6} className="p-8 text-center text-neutral-500 border border-neutral-200 dark:border-neutral-700">
                                        No transactions in this period
                                    </td>
                                </tr>
                            ) : (
                                statementData.transactions.map((t, idx) => (
                                    <tr key={idx} className="hover:bg-neutral-50 dark:hover:bg-neutral-800 print:hover:bg-transparent">
                                        <td className="p-3 border border-neutral-200 dark:border-neutral-700 print:border-gray-300">
                                            {new Date(t.date).toLocaleDateString()}
                                        </td>
                                        <td className="p-3 border border-neutral-200 dark:border-neutral-700 print:border-gray-300 font-mono text-xs">
                                            {t.reference}
                                        </td>
                                        <td className="p-3 border border-neutral-200 dark:border-neutral-700 print:border-gray-300">
                                            {t.description}
                                        </td>
                                        <td className="p-3 border border-neutral-200 dark:border-neutral-700 print:border-gray-300 text-right text-error">
                                            {t.debit > 0 ? `₹${t.debit.toLocaleString()}` : '-'}
                                        </td>
                                        <td className="p-3 border border-neutral-200 dark:border-neutral-700 print:border-gray-300 text-right text-success">
                                            {t.credit > 0 ? `₹${t.credit.toLocaleString()}` : '-'}
                                        </td>
                                        <td className="p-3 border border-neutral-200 dark:border-neutral-700 print:border-gray-300 text-right font-bold">
                                            ₹{t.balance.toLocaleString()}
                                        </td>
                                    </tr>
                                ))
                            )}
                        </tbody>
                        <tfoot>
                            <tr className="bg-neutral-100 dark:bg-neutral-900 font-bold print:bg-gray-200">
                                <td colSpan={3} className="p-3 border border-neutral-200 dark:border-neutral-700 print:border-gray-300 text-right">
                                    Balance Due:
                                </td>
                                <td colSpan={3} className={`p-3 border border-neutral-200 dark:border-neutral-700 print:border-gray-300 text-right text-lg ${statementData.closingBalance > 0 ? 'text-error' : 'text-success'}`}>
                                    ₹{statementData.closingBalance.toLocaleString()}
                                </td>
                            </tr>
                        </tfoot>
                    </table>

                    {/* Footer */}
                    <div className="mt-8 pt-4 border-t border-neutral-200 dark:border-neutral-700 text-center text-xs text-neutral-500 print:border-gray-300">
                        <p>This is a computer-generated statement and does not require a signature.</p>
                        <p className="mt-1">For any queries, please contact us.</p>
                    </div>
                </div>
            )}

            {/* Empty State */}
            {!selectedCustomerId && (
                <div className="bg-white dark:bg-neutral-800 p-12 rounded-xl border border-neutral-200 dark:border-neutral-700 text-center">
                    <FileText className="w-16 h-16 mx-auto mb-4 text-neutral-300" />
                    <h3 className="text-lg font-bold text-neutral-700 dark:text-neutral-300">Select a Customer</h3>
                    <p className="text-neutral-500 mt-1">Choose a customer and date range to generate their account statement</p>
                </div>
            )}
        </div>
    );
};

export default CustomerStatements;

import { useState, useEffect } from "react";
import { useDispatch, useSelector } from "react-redux";
import { useNavigate, useParams } from "react-router-dom";
import { toast } from "react-toastify";
import { getCustomerById, updateCustomer, reset, getAllCustomers } from "@/entities/contact/model/customerSlice";
import { Layout, PageHeader } from "@/shared/ui";
import { Zap } from 'lucide-react';
import CustomerForm from "./components/CustomerForm";
import { RootState, AppDispatch } from "@/app/store/store";
import "react-toastify/dist/ReactToastify.css";

const EditCustomer = () => {
    const { id } = useParams<{ id: string }>();
    const navigate = useNavigate();
    const dispatch = useDispatch<AppDispatch>();

    const { customer, isLoading, isSuccess, customers } = useSelector(
        (state: RootState) => state.customers
    );

    const [shouldNavigate, setShouldNavigate] = useState(false);
    const [duplicateField, setDuplicateField] = useState<string | null>(null);

    useEffect(() => {
        if (id) {
            dispatch(getCustomerById(id));
            dispatch(getAllCustomers()); // Needed for referrer selection list
        }
        return () => {
            dispatch(reset());
        };
    }, [dispatch, id]);

    useEffect(() => {
        if (shouldNavigate && isSuccess && !isLoading) {
            navigate("/customers");
            dispatch(reset());
        }
    }, [shouldNavigate, isSuccess, isLoading, navigate, dispatch]);

    const onSubmit = async (formData: any) => {
        if (!id) return;
        setDuplicateField(null);
        const result: any = await dispatch(updateCustomer({ id, customerData: formData }));
        if (result.type === 'customers/update/fulfilled') {
            toast.success("Profile re-indexed successfully!");
            setShouldNavigate(true);
        } else if (result.type === 'customers/update/rejected') {
            const errorMsg = result.payload || "Modification failure";
            toast.error(errorMsg);

            if (errorMsg.toLowerCase().includes('phone')) {
                setDuplicateField('phone');
            } else if (errorMsg.toLowerCase().includes('email')) {
                setDuplicateField('email');
            }
        }
    };

    if (isLoading && !customer) {
        return (
            <Layout>
                <div className="flex justify-center items-center py-20">
                    <div className="flex flex-col items-center gap-4">
                        <div className="w-12 h-12 border-4 border-indigo-600/20 border-t-indigo-600 rounded-full animate-spin"></div>
                        <p className="text-sm font-bold text-slate-400">Fetching Partner Intel...</p>
                    </div>
                </div>
            </Layout>
        );
    }

    return (
        <Layout>
            <PageHeader
                title="Modify Partner Intel"
                description={`Updating system parameters for CID-${id?.slice(-6).toUpperCase()}`}
                breadcrumbs={[{ label: 'Portfolio', link: '/customers' }, { label: 'Intel Modification' }]}
                actions={
                    <button
                        onClick={() => navigate('/customers')}
                        className="px-6 py-2 border border-slate-200 dark:border-slate-800 text-slate-600 dark:text-slate-400 rounded-xl text-sm font-bold hover:bg-slate-50 transition-all font-medium"
                    >
                        Abort Modification
                    </button>
                }
            />

            <div className="max-w-5xl mx-auto space-y-6">
                <div className="bg-amber-50 dark:bg-amber-900/10 border border-amber-100 dark:border-amber-800/30 p-4 rounded-2xl flex items-start gap-4 text-amber-900 dark:text-amber-300">
                    <div className="p-2 bg-amber-100 dark:bg-amber-900/30 rounded-xl">
                        < Zap className="w-5 h-5 text-amber-600" />
                    </div>
                    <div>
                        <p className="text-xs font-black uppercase tracking-widest leading-none mt-1">Audit Warning</p>
                        <p className="text-[11px] font-medium mt-2 leading-relaxed italic opacity-80">Modifying contact nodes will trigger a marketplace re-indexing. Historical integrity will be updated to reflect these commercial parameters across all linked terminals.</p>
                    </div>
                </div>

                <CustomerForm
                    initialData={customer || undefined}
                    customers={customers}
                    onSubmit={onSubmit}
                    isLoading={isLoading}
                    duplicateField={duplicateField}
                    submitLabel="Push Updates"
                    onCancel={() => navigate('/customers')}
                />
            </div>
        </Layout>
    );
};

export default EditCustomer;

import React, { useState, useMemo } from 'react';
import { useSelector } from 'react-redux';
import { RootState } from "@/app/store/store";
import {
    Search,
    Gift,
    Star,
    TrendingUp,
    Settings,
    Users,
    Award,
    Coins,
    ArrowUpRight,
    ArrowDownRight,
    Calendar,
    Download,
    Percent
} from 'lucide-react';

interface LoyaltyTransaction {
    id: string;
    customerId: string;
    customerName: string;
    date: string;
    type: 'EARNED' | 'REDEEMED' | 'EXPIRED' | 'BONUS';
    points: number;
    invoiceRef?: string;
    description: string;
}

interface LoyaltyTier {
    name: string;
    minPoints: number;
    discountPercent: number;
    pointsMultiplier: number;
    color: string;
}

const LOYALTY_TIERS: LoyaltyTier[] = [
    { name: 'Bronze', minPoints: 0, discountPercent: 0, pointsMultiplier: 1, color: '#CD7F32' },
    { name: 'Silver', minPoints: 500, discountPercent: 2, pointsMultiplier: 1.25, color: '#C0C0C0' },
    { name: 'Gold', minPoints: 2000, discountPercent: 5, pointsMultiplier: 1.5, color: '#FFD700' },
    { name: 'Platinum', minPoints: 5000, discountPercent: 10, pointsMultiplier: 2, color: '#E5E4E2' }
];

const LoyaltyPoints: React.FC = () => {
    const { customers } = useSelector((state: RootState) => state.customers);
    const { invoices: salesHistory } = useSelector((state: RootState) => state.pos);
    const { currentSector } = useSelector((state: RootState) => state.auth);

    const [searchTerm, setSearchTerm] = useState('');
    const [activeTab, setActiveTab] = useState<'overview' | 'customers' | 'transactions' | 'settings'>('overview');

    // Calculate loyalty data
    const loyaltyData = useMemo(() => {
        const customerPoints: Record<string, { earned: number; redeemed: number; balance: number }> = {};
        const transactions: LoyaltyTransaction[] = [];

        // Calculate points from sales (1 point per ₹100 spent)
        salesHistory
            .filter(s => s.sector === currentSector)
            .forEach(sale => {
                const customerId = typeof sale.customer === 'string' ? sale.customer : sale.customer?._id || sale.customer?.id;
                const saleId = sale._id || sale.id;

                if (customerId) {
                    if (!customerPoints[customerId]) {
                        customerPoints[customerId] = { earned: 0, redeemed: 0, balance: 0 };
                    }
                    const pointsEarned = Math.floor(sale.totalAmount / 100);
                    customerPoints[customerId].earned += pointsEarned;
                    customerPoints[customerId].balance += pointsEarned;

                    const customer = customers.find(c => c.id === customerId || c._id === customerId);
                    transactions.push({
                        id: `earn-${saleId}`,
                        customerId: customerId,
                        customerName: customer?.name || 'Unknown',
                        date: sale.createdAt,
                        type: 'EARNED',
                        points: pointsEarned,
                        invoiceRef: `INV-${saleId.substring(0, 8)}`,
                        description: `Points for purchase`
                    });
                }
            });

        return { customerPoints, transactions };
    }, [salesHistory, customers, currentSector]);

    // Customer loyalty list
    const customerLoyalty = useMemo(() => {
        return customers.map(customer => {
            const points = loyaltyData.customerPoints[customer.id] || { earned: 0, redeemed: 0, balance: 0 };
            const tier = [...LOYALTY_TIERS].reverse().find(t => points.balance >= t.minPoints) || LOYALTY_TIERS[0];
            return {
                ...customer,
                ...points,
                tier
            };
        }).filter(c => c.earned > 0);
    }, [customers, loyaltyData]);

    const filteredCustomers = customerLoyalty.filter(c =>
        c.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
        c.phone?.includes(searchTerm)
    );

    // Summary stats
    const totalPointsIssued = Object.values(loyaltyData.customerPoints).reduce<number>((acc, p) => acc + (p as any).earned, 0);
    const totalPointsRedeemed = Object.values(loyaltyData.customerPoints).reduce<number>((acc, p) => acc + (p as any).redeemed, 0);
    const activeMembers = customerLoyalty.length;

    return (
        <div className="space-y-6 animate-fade-in">
            {/* Header */}
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                <div>
                    <h2 className="text-2xl font-bold text-neutral-900 dark:text-white flex items-center gap-2">
                        <Gift className="w-6 h-6 text-primary" />
                        Loyalty Points Program
                    </h2>
                    <p className="text-neutral-500 text-sm mt-1">Reward customers and build loyalty</p>
                </div>
                <div className="flex gap-2">
                    <button className="px-4 py-2 bg-white dark:bg-neutral-800 border border-neutral-200 dark:border-neutral-700 rounded-lg text-sm font-medium hover:bg-neutral-50 dark:hover:bg-neutral-700 flex items-center gap-2">
                        <Download className="w-4 h-4" /> Export
                    </button>
                    <button className="px-4 py-2 bg-primary text-white rounded-lg text-sm font-bold hover:bg-primary/90 flex items-center gap-2">
                        <Award className="w-4 h-4" /> Award Bonus Points
                    </button>
                </div>
            </div>

            {/* KPI Cards */}
            <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
                <div className="bg-white dark:bg-neutral-800 p-5 rounded-xl border border-neutral-200 dark:border-neutral-700">
                    <div className="flex items-center justify-between">
                        <div>
                            <p className="text-xs font-medium text-neutral-500 uppercase">Total Points Issued</p>
                            <p className="text-2xl font-bold text-primary mt-1">{totalPointsIssued.toLocaleString()}</p>
                        </div>
                        <div className="p-3 bg-primary/10 rounded-xl">
                            <Coins className="w-6 h-6 text-primary" />
                        </div>
                    </div>
                </div>

                <div className="bg-white dark:bg-neutral-800 p-5 rounded-xl border border-neutral-200 dark:border-neutral-700">
                    <div className="flex items-center justify-between">
                        <div>
                            <p className="text-xs font-medium text-neutral-500 uppercase">Points Redeemed</p>
                            <p className="text-2xl font-bold text-success mt-1">{totalPointsRedeemed.toLocaleString()}</p>
                        </div>
                        <div className="p-3 bg-success/10 rounded-xl">
                            <Gift className="w-6 h-6 text-success" />
                        </div>
                    </div>
                </div>

                <div className="bg-white dark:bg-neutral-800 p-5 rounded-xl border border-neutral-200 dark:border-neutral-700">
                    <div className="flex items-center justify-between">
                        <div>
                            <p className="text-xs font-medium text-neutral-500 uppercase">Outstanding Points</p>
                            <p className="text-2xl font-bold text-warning mt-1">{(totalPointsIssued - totalPointsRedeemed).toLocaleString()}</p>
                        </div>
                        <div className="p-3 bg-warning/10 rounded-xl">
                            <Star className="w-6 h-6 text-warning" />
                        </div>
                    </div>
                </div>

                <div className="bg-white dark:bg-neutral-800 p-5 rounded-xl border border-neutral-200 dark:border-neutral-700">
                    <div className="flex items-center justify-between">
                        <div>
                            <p className="text-xs font-medium text-neutral-500 uppercase">Active Members</p>
                            <p className="text-2xl font-bold text-neutral-900 dark:text-white mt-1">{activeMembers}</p>
                        </div>
                        <div className="p-3 bg-neutral-100 dark:bg-neutral-700 rounded-xl">
                            <Users className="w-6 h-6 text-neutral-600 dark:text-neutral-400" />
                        </div>
                    </div>
                </div>
            </div>

            {/* Tiers Overview */}
            <div className="bg-white dark:bg-neutral-800 p-4 rounded-xl border border-neutral-200 dark:border-neutral-700">
                <h3 className="font-bold text-neutral-900 dark:text-white mb-4">Loyalty Tiers</h3>
                <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                    {LOYALTY_TIERS.map(tier => {
                        const memberCount = customerLoyalty.filter(c => c.tier.name === tier.name).length;
                        return (
                            <div key={tier.name} className="p-4 rounded-xl border-2" style={{ borderColor: tier.color }}>
                                <div className="flex items-center gap-2 mb-2">
                                    <div className="w-8 h-8 rounded-full flex items-center justify-center" style={{ backgroundColor: tier.color }}>
                                        <Star className="w-4 h-4 text-white" />
                                    </div>
                                    <span className="font-bold" style={{ color: tier.color }}>{tier.name}</span>
                                </div>
                                <div className="text-sm space-y-1">
                                    <p className="text-neutral-500">{tier.minPoints}+ points</p>
                                    <p className="text-neutral-600 dark:text-neutral-400">{tier.discountPercent}% discount</p>
                                    <p className="text-neutral-600 dark:text-neutral-400">{tier.pointsMultiplier}x points</p>
                                    <p className="font-bold text-primary mt-2">{memberCount} members</p>
                                </div>
                            </div>
                        );
                    })}
                </div>
            </div>

            {/* Search */}
            <div className="bg-white dark:bg-neutral-800 p-4 rounded-xl border border-neutral-200 dark:border-neutral-700">
                <div className="relative max-w-md">
                    <input
                        type="text"
                        placeholder="Search member by name or phone..."
                        className="w-full pl-9 pr-4 py-2 bg-neutral-100 dark:bg-neutral-700 border border-neutral-200 dark:border-neutral-600 rounded-lg text-neutral-900 dark:text-white text-sm"
                        value={searchTerm}
                        onChange={e => setSearchTerm(e.target.value)}
                    />
                    <Search className="w-4 h-4 absolute left-3 top-2.5 text-neutral-400" />
                </div>
            </div>

            {/* Members Table */}
            <div className="bg-white dark:bg-neutral-800 rounded-xl border border-neutral-200 dark:border-neutral-700 overflow-hidden">
                <div className="hidden md:block overflow-x-auto">
                    <table className="w-full text-left text-sm">
                        <thead className="bg-neutral-50 dark:bg-neutral-900 text-neutral-500 uppercase text-xs">
                            <tr>
                                <th className="p-4">Member</th>
                                <th className="p-4">Tier</th>
                                <th className="p-4 text-right">Points Earned</th>
                                <th className="p-4 text-right">Points Redeemed</th>
                                <th className="p-4 text-right">Balance</th>
                                <th className="p-4 text-center">Action</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-neutral-100 dark:divide-neutral-700">
                            {filteredCustomers.length === 0 ? (
                                <tr><td colSpan={6} className="p-8 text-center text-neutral-500">
                                    <Gift className="w-8 h-8 mx-auto mb-2 text-neutral-300" />
                                    <p>No loyalty members found</p>
                                </td></tr>
                            ) : (
                                filteredCustomers.slice(0, 20).map(customer => (
                                    <tr key={customer.id} className="hover:bg-neutral-50 dark:hover:bg-neutral-700/50">
                                        <td className="p-4">
                                            <div className="flex items-center gap-3">
                                                <div className="w-10 h-10 rounded-full flex items-center justify-center" style={{ backgroundColor: customer.tier.color }}>
                                                    <span className="text-white font-bold">{customer.name.charAt(0)}</span>
                                                </div>
                                                <div>
                                                    <p className="font-medium text-neutral-900 dark:text-white">{customer.name}</p>
                                                    <p className="text-xs text-neutral-500">{customer.phone || 'No phone'}</p>
                                                </div>
                                            </div>
                                        </td>
                                        <td className="p-4">
                                            <span className="px-2 py-1 rounded-full text-xs font-bold text-white" style={{ backgroundColor: customer.tier.color }}>
                                                {customer.tier.name}
                                            </span>
                                        </td>
                                        <td className="p-4 text-right">
                                            <span className="flex items-center justify-end gap-1 text-success">
                                                <ArrowUpRight className="w-4 h-4" />
                                                {customer.earned.toLocaleString()}
                                            </span>
                                        </td>
                                        <td className="p-4 text-right">
                                            <span className="flex items-center justify-end gap-1 text-error">
                                                <ArrowDownRight className="w-4 h-4" />
                                                {customer.redeemed.toLocaleString()}
                                            </span>
                                        </td>
                                        <td className="p-4 text-right font-bold text-primary">{customer.balance.toLocaleString()}</td>
                                        <td className="p-4 text-center">
                                            <button className="px-3 py-1 bg-primary/10 text-primary text-xs font-bold rounded-lg hover:bg-primary/20">
                                                View History
                                            </button>
                                        </td>
                                    </tr>
                                ))
                            )}
                        </tbody>
                    </table>
                </div>

                {/* Mobile View */}
                <div className="md:hidden divide-y divide-neutral-100 dark:divide-neutral-700">
                    {filteredCustomers.length === 0 ? (
                        <div className="p-8 text-center text-neutral-500">No members found</div>
                    ) : (
                        filteredCustomers.slice(0, 20).map(customer => (
                            <div key={customer.id} className="p-4">
                                <div className="flex justify-between items-center mb-2">
                                    <div className="flex items-center gap-3">
                                        <div className="w-10 h-10 rounded-full flex items-center justify-center" style={{ backgroundColor: customer.tier.color }}>
                                            <span className="text-white font-bold">{customer.name.charAt(0)}</span>
                                        </div>
                                        <div>
                                            <p className="font-bold text-neutral-900 dark:text-white">{customer.name}</p>
                                            <span className="text-[10px] px-2 py-0.5 rounded-full text-white" style={{ backgroundColor: customer.tier.color }}>
                                                {customer.tier.name}
                                            </span>
                                        </div>
                                    </div>
                                </div>
                                <div className="flex justify-between items-center bg-neutral-50 dark:bg-neutral-700/50 p-3 rounded-lg">
                                    <div className="text-center">
                                        <p className="text-[10px] text-neutral-500">Earned</p>
                                        <p className="font-bold text-success">{customer.earned}</p>
                                    </div>
                                    <div className="text-center">
                                        <p className="text-[10px] text-neutral-500">Redeemed</p>
                                        <p className="font-bold text-error">{customer.redeemed}</p>
                                    </div>
                                    <div className="text-center">
                                        <p className="text-[10px] text-neutral-500">Balance</p>
                                        <p className="font-bold text-primary">{customer.balance}</p>
                                    </div>
                                </div>
                            </div>
                        ))
                    )}
                </div>
            </div>

            {/* Program Rules */}
            <div className="bg-gradient-to-r from-primary/10 to-warning/10 p-4 rounded-xl border border-primary/20">
                <h4 className="font-bold text-neutral-900 dark:text-white flex items-center gap-2">
                    <Settings className="w-4 h-4 text-primary" /> Program Rules
                </h4>
                <ul className="text-sm text-neutral-600 dark:text-neutral-400 mt-2 space-y-1">
                    <li>• Earn <strong>1 point for every ₹100</strong> spent</li>
                    <li>• Points can be redeemed at <strong>1 point = ₹1</strong></li>
                    <li>• Points expire after <strong>12 months</strong> of inactivity</li>
                    <li>• Higher tiers earn bonus multipliers on all purchases</li>
                </ul>
            </div>
        </div>
    );
};

export default LoyaltyPoints;

import React, { useState, useEffect, useRef } from 'react';
import { User, Phone, Mail, MapPin, Search, X, Briefcase } from 'lucide-react';
import { FormSection, InputWrapper } from './CustomerUI';
import { Customer } from "../../../../types";

interface CustomerFormProps {
    initialData?: Partial<Customer>;
    customers: Customer[];
    onSubmit: (data: any) => void;
    isLoading: boolean;
    duplicateField: string | null;
    submitLabel: string;
    onCancel: () => void;
}

const CustomerForm: React.FC<CustomerFormProps> = ({
    initialData,
    customers,
    onSubmit,
    isLoading,
    duplicateField,
    submitLabel,
    onCancel
}) => {
    const [formData, setFormData] = useState({
        name: initialData?.name || '',
        phone: initialData?.phone || '',
        email: initialData?.email || '',
        address: initialData?.address || '',
        referredBy: typeof initialData?.referrer === 'string' ? initialData.referrer : (initialData?.referrer as any)?._id || '',
    });

    const [referralSearch, setReferralSearch] = useState('');
    const [showReferralDropdown, setShowReferralDropdown] = useState(false);
    const [selectedReferrer, setSelectedReferrer] = useState<Customer | null>(null);
    const dropdownRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        if (initialData) {
            setFormData({
                name: initialData.name || '',
                phone: initialData.phone || '',
                email: initialData.email || '',
                address: initialData.address || '',
                referredBy: typeof initialData.referrer === 'string' ? initialData.referrer : (initialData.referrer as any)?._id || '',
            });

            if (initialData.referrer && typeof initialData.referrer !== 'string') {
                setSelectedReferrer(initialData.referrer as any);
                setReferralSearch((initialData.referrer as any).name);
            }
        }
    }, [initialData]);

    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
                setShowReferralDropdown(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    const onChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
        setFormData(prev => ({ ...prev, [e.target.name]: e.target.value }));
    };

    const handleSelectReferrer = (customer: Customer) => {
        setSelectedReferrer(customer);
        setFormData(prev => ({ ...prev, referredBy: customer._id }));
        setReferralSearch(customer.name);
        setShowReferralDropdown(false);
    };

    const handleClearReferrer = () => {
        setSelectedReferrer(null);
        setFormData(prev => ({ ...prev, referredBy: '' }));
        setReferralSearch('');
    };

    const filteredReferralCustomers = customers.filter(
        c => c.name.toLowerCase().includes(referralSearch.toLowerCase()) ||
            c.phone.includes(referralSearch)
    ).filter(c => c._id !== initialData?._id); // Don't allow self-referral

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        onSubmit(formData);
    };

    return (
        <form onSubmit={handleSubmit} className="space-y-6">
            <FormSection title="Partner Identity" description="Core contact parameters and decision-maker details">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6 w-full">
                    <InputWrapper label="Partner Name" icon={User} required>
                        <input
                            type="text"
                            name="name"
                            value={formData.name}
                            onChange={onChange}
                            required
                            className="w-full px-5 py-4 bg-slate-50 dark:bg-slate-800/50 border border-slate-100 dark:border-slate-800 rounded-2xl outline-none focus:ring-4 focus:ring-indigo-500/10 focus:border-indigo-500 transition-all font-bold text-sm text-[rgb(var(--color-text))]"
                            placeholder="Full Commercial Name"
                        />
                    </InputWrapper>

                    <InputWrapper
                        label="Communication Node"
                        icon={Phone}
                        required
                        error={duplicateField === 'phone' ? 'Node collision: Phone already exists' : undefined}
                    >
                        <input
                            type="tel"
                            name="phone"
                            value={formData.phone}
                            onChange={onChange}
                            required
                            pattern="[0-9]{10}"
                            className={`w-full px-5 py-4 bg-slate-50 dark:bg-slate-800/50 border rounded-2xl outline-none focus:ring-4 focus:ring-indigo-500/10 transition-all font-bold text-sm text-[rgb(var(--color-text))] ${duplicateField === 'phone' ? 'border-rose-500 focus:border-rose-500' : 'border-slate-100 dark:border-slate-800 focus:border-indigo-500'}`}
                            placeholder="10-Digit Primary Line"
                        />
                    </InputWrapper>

                    <InputWrapper
                        label="Email Registry"
                        icon={Mail}
                        error={duplicateField === 'email' ? 'Node collision: Email already exists' : undefined}
                    >
                        <input
                            type="email"
                            name="email"
                            value={formData.email}
                            onChange={onChange}
                            className={`w-full px-5 py-4 bg-slate-50 dark:bg-slate-800/50 border rounded-2xl outline-none focus:ring-4 focus:ring-indigo-500/10 transition-all font-bold text-sm text-[rgb(var(--color-text))] ${duplicateField === 'email' ? 'border-rose-500 focus:border-rose-500' : 'border-slate-100 dark:border-slate-800 focus:border-indigo-500'}`}
                            placeholder="Official Digital Correspondence"
                        />
                    </InputWrapper>

                    <InputWrapper label="Network Referral" icon={Briefcase}>
                        <div className="relative" ref={dropdownRef}>
                            {selectedReferrer ? (
                                <div className="w-full px-5 py-3.5 bg-emerald-50 dark:bg-emerald-900/10 border border-emerald-100 dark:border-emerald-800/30 rounded-2xl flex items-center justify-between group">
                                    <div>
                                        <p className="text-[10px] font-black text-emerald-600 uppercase tracking-tighter leading-none mb-1">Referrer Selected</p>
                                        <p className="text-sm font-bold text-emerald-700 dark:text-emerald-400">{selectedReferrer.name}</p>
                                    </div>
                                    <button type="button" onClick={handleClearReferrer} className="p-2 hover:bg-emerald-100 dark:hover:bg-emerald-900/30 rounded-xl transition-all">
                                        <X className="w-4 h-4 text-emerald-600" />
                                    </button>
                                </div>
                            ) : (
                                <div className="relative">
                                    <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                                    <input
                                        type="text"
                                        value={referralSearch}
                                        onChange={(e) => {
                                            setReferralSearch(e.target.value);
                                            setShowReferralDropdown(true);
                                        }}
                                        className="w-full pl-11 pr-4 py-4 bg-slate-50 dark:bg-slate-800/50 border border-slate-100 dark:border-slate-800 rounded-2xl outline-none focus:ring-4 focus:ring-indigo-500/10 focus:border-indigo-500 transition-all font-bold text-sm text-[rgb(var(--color-text))]"
                                        placeholder="Search existing partners..."
                                    />
                                    {showReferralDropdown && referralSearch.length > 0 && (
                                        <div className="absolute z-20 w-full mt-2 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-[2rem] shadow-2xl overflow-hidden max-h-60 overflow-y-auto">
                                            {filteredReferralCustomers.length > 0 ? (
                                                filteredReferralCustomers.map((c) => (
                                                    <button
                                                        key={c._id}
                                                        type="button"
                                                        onClick={() => handleSelectReferrer(c)}
                                                        className="w-full px-6 py-4 hover:bg-slate-50 dark:hover:bg-slate-800/50 flex flex-col gap-1 border-b border-slate-100 dark:border-slate-800 last:border-0 transition-all text-left"
                                                    >
                                                        <span className="text-sm font-black text-slate-800 dark:text-white uppercase tracking-tight">{c.name}</span>
                                                        <span className="text-[10px] font-bold text-slate-400">{c.phone}</span>
                                                    </button>
                                                ))
                                            ) : (
                                                <div className="p-8 text-center opacity-40">
                                                    <Search className="w-8 h-8 mx-auto mb-2" />
                                                    <p className="text-[10px] font-black uppercase tracking-widest leading-relaxed">No matching partners<br />detected in registry</p>
                                                </div>
                                            )}
                                        </div>
                                    )}
                                </div>
                            )}
                        </div>
                    </InputWrapper>
                </div>
            </FormSection>

            <FormSection title="Logistics Reachability" description="Physical warehouse and billing coordinates">
                <div className="w-full">
                    <InputWrapper label="Primary Reachability Node" icon={MapPin}>
                        <textarea
                            name="address"
                            value={formData.address}
                            onChange={onChange}
                            rows={3}
                            className="w-full px-5 py-4 bg-slate-50 dark:bg-slate-800/50 border border-slate-100 dark:border-slate-800 rounded-2xl outline-none focus:ring-4 focus:ring-indigo-500/10 focus:border-indigo-500 transition-all font-bold text-sm leading-relaxed text-[rgb(var(--color-text))]"
                            placeholder="Warehouse Access Point / Billing Logistics Center"
                        />
                    </InputWrapper>
                </div>
            </FormSection>

            <div className="flex justify-end gap-3 pt-4">
                <button
                    type="button"
                    onClick={onCancel}
                    className="px-8 py-4 border border-slate-200 dark:border-slate-800 text-slate-600 dark:text-slate-400 rounded-2xl text-[10px] font-black uppercase tracking-[0.2em] hover:bg-slate-50 transition-all"
                >
                    Abort
                </button>
                <button
                    type="submit"
                    disabled={isLoading}
                    className="px-10 py-4 bg-indigo-600 text-white rounded-2xl text-[10px] font-black uppercase tracking-[0.2em] shadow-xl shadow-indigo-100 dark:shadow-none hover:bg-indigo-700 active:scale-95 transition-all disabled:opacity-50 disabled:cursor-wait"
                >
                    {isLoading ? 'Synchronizing Pipeline...' : submitLabel}
                </button>
            </div>
        </form>
    );
};

export default CustomerForm;

import React from 'react';
import { IndianRupee, Calculator } from 'lucide-react';
import { Card } from "@repo/ui";
import { formatCurrency } from "@/shared/lib/utils/helpers";
import { convertMonthlyToDailyWage } from "@/entities/people/lib/laborUtils";

interface AddLaborerFormProps {
    newEmp: { name: string; role: string; roleId: string; dailyRate: string; mobile: string; branch: string };
    setNewEmp: React.Dispatch<React.SetStateAction<any>>;
    wageType: 'DAILY' | 'MONTHLY';
    setWageType: React.Dispatch<React.SetStateAction<'DAILY' | 'MONTHLY'>>;
    monthlyInput: string;
    onMonthlyChange: (e: React.ChangeEvent<HTMLInputElement>) => void;
    roles: any[];
    onSubmit: (e: React.FormEvent) => void;
    onCancel: () => void;
}

const AddLaborerForm: React.FC<AddLaborerFormProps> = ({
    newEmp, setNewEmp, wageType, setWageType, monthlyInput, onMonthlyChange, roles, onSubmit, onCancel
}) => {
    return (
        <Card className="p-3 bg-blue-50 dark:bg-slate-800 border-blue-100 dark:border-slate-700 shadow-md relative z-10">
            <h4 className="font-bold text-blue-800 dark:text-blue-300 mb-2 text-xs">New Laborer Details</h4>
            <form onSubmit={onSubmit} className="space-y-2">
                <input
                    type="text"
                    placeholder="Full Name"
                    value={newEmp.name}
                    onChange={e => setNewEmp({ ...newEmp, name: e.target.value })}
                    className="w-full p-2 text-xs rounded border border-blue-200 dark:border-slate-600 bg-white dark:bg-slate-900 text-slate-900 dark:text-white outline-none focus:ring-2 focus:ring-blue-300"
                    autoFocus
                />
                <input
                    type="text"
                    placeholder="Role (Display Name)"
                    value={newEmp.role}
                    onChange={e => setNewEmp({ ...newEmp, role: e.target.value })}
                    className="w-full p-2 text-xs rounded border border-blue-200 dark:border-slate-600 bg-white dark:bg-slate-900 text-slate-900 dark:text-white outline-none focus:ring-2 focus:ring-blue-300"
                />
                <select
                    value={newEmp.roleId}
                    onChange={e => setNewEmp({ ...newEmp, roleId: e.target.value })}
                    className="w-full p-2 text-xs rounded border border-blue-200 dark:border-slate-600 bg-white dark:bg-slate-900 text-slate-900 dark:text-white outline-none focus:ring-2 focus:ring-blue-300"
                >
                    <option value="">Select System Role (Default: Staff)</option>
                    {roles.map(r => <option key={r.id} value={r.id}>{r.name}</option>)}
                </select>
                <input
                    type="text"
                    placeholder="Phone Number"
                    value={newEmp.mobile}
                    onChange={e => setNewEmp({ ...newEmp, mobile: e.target.value })}
                    className="w-full p-2 text-xs rounded border border-blue-200 dark:border-slate-600 bg-white dark:bg-slate-900 text-slate-900 dark:text-white outline-none focus:ring-2 focus:ring-blue-300"
                />

                <div className="flex bg-white dark:bg-slate-900 rounded border border-blue-200 dark:border-slate-600 overflow-hidden">
                    <button
                        type="button"
                        onClick={() => setWageType('DAILY')}
                        className={`flex-1 py-1.5 text-[10px] font-bold transition-colors ${wageType === 'DAILY' ? 'bg-blue-600 text-white' : 'text-slate-500 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-800'}`}
                    >
                        Daily Rate
                    </button>
                    <div className="w-px bg-blue-200 dark:bg-slate-600"></div>
                    <button
                        type="button"
                        onClick={() => setWageType('MONTHLY')}
                        className={`flex-1 py-1.5 text-[10px] font-bold transition-colors ${wageType === 'MONTHLY' ? 'bg-blue-600 text-white' : 'text-slate-500 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-800'}`}
                    >
                        Monthly Salary
                    </button>
                </div>

                {wageType === 'DAILY' ? (
                    <div className="relative">
                        <IndianRupee size={12} className="absolute left-2 top-2.5 text-slate-400" />
                        <input
                            type="number"
                            placeholder="Daily Wage"
                            value={newEmp.dailyRate}
                            onChange={e => setNewEmp({ ...newEmp, dailyRate: e.target.value })}
                            className="w-full pl-6 p-2 text-xs rounded border border-blue-200 dark:border-slate-600 bg-white dark:bg-slate-900 text-slate-900 dark:text-white outline-none focus:ring-2 focus:ring-blue-300"
                        />
                    </div>
                ) : (
                    <div className="space-y-1">
                        <div className="relative">
                            <IndianRupee size={12} className="absolute left-2 top-2.5 text-slate-400" />
                            <input
                                type="number"
                                placeholder="Monthly Salary"
                                value={monthlyInput}
                                onChange={onMonthlyChange}
                                className="w-full pl-6 p-2 text-xs rounded border border-blue-200 dark:border-slate-600 bg-white dark:bg-slate-900 text-slate-900 dark:text-white outline-none focus:ring-2 focus:ring-blue-300"
                            />
                        </div>
                        {newEmp.dailyRate && (
                            <div className="flex items-center gap-1.5 text-[10px] text-blue-700 dark:text-blue-300 bg-blue-100/50 dark:bg-blue-900/30 p-1.5 rounded">
                                <Calculator size={10} />
                                <span>Daily: {formatCurrency(convertMonthlyToDailyWage(monthlyInput))} (Calc: /30)</span>
                            </div>
                        )}
                    </div>
                )}

                <div className="flex gap-2 mt-1">
                    <button type="submit" className="flex-1 bg-blue-600 text-white py-1 rounded text-xs font-medium hover:bg-blue-700">Save</button>
                    <button type="button" onClick={onCancel} className="flex-1 bg-white dark:bg-slate-700 text-slate-600 dark:text-slate-300 py-1 rounded text-xs font-medium hover:bg-slate-50 dark:hover:bg-slate-600">Cancel</button>
                </div>
            </form>
        </Card>
    );
};

export default AddLaborerForm;

import { logger } from '@/shared/lib/logger';
import React, { useState, useEffect } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import { RootState, AppDispatch } from "@/app/store/store";
import {
    Save,
    Plus,
    Calendar as CalendarIcon,
    CheckCircle2,
    Info,
    TrendingUp,
    TrendingDown,
    Loader2,
    PlusCircle,
    Edit2,
    Trash2,
    Pencil,
    XCircle,
    Shield,
    Users,
    Banknote,
    CreditCard,
    ChevronDown
} from 'lucide-react';
import {
    fetchSalaryComponents,
    createSalaryComponent,
    updateSalaryComponent,
    deleteSalaryComponent,
    fetchSalaryStructure,
    fetchAllSalaryStructures,
    fetchAttendanceSummary,
    processIndividualPayout,
    SalaryComponent
} from "@/entities/people/model/payrollSlice";
import { getAccounts } from "@/entities/finance/model/cashbankSlice";
import api from "@/shared/api/api";

const AllowanceManager: React.FC = () => {
    const dispatch = useDispatch<AppDispatch>();
    // Revert to local state for employees since employeeSlice does not exist
    const [employees, setEmployees] = useState<any[]>([]);

    const { components, structures, attendance, loading } = useSelector((state: RootState) => state.payroll);
    const { accounts } = useSelector((state: RootState) => state.cashbank);

    const [selectedDate, setSelectedDate] = useState({ month: new Date().getMonth(), year: new Date().getFullYear() });
    const [selectedBenefitId, setSelectedBenefitId] = useState<string>('ALL');
    const [selectedEmployeeId, setSelectedEmployeeId] = useState<string>('ALL');
    const [payoutFrequency, setPayoutFrequency] = useState<'Monthly' | 'Weekly'>('Monthly');
    const [activeTab, setActiveTab] = useState<'breakdown' | 'list'>('breakdown');

    const [showModal, setShowModal] = useState(false);
    const [editingId, setEditingId] = useState<string | null>(null);
    const [formData, setFormData] = useState<Partial<SalaryComponent>>({
        name: '',
        type: 'EARNING',
        calculationType: 'FLAT',
        defaultValue: 0,
        isTaxable: true,
        isActive: true
    });

    useEffect(() => {
        dispatch(fetchSalaryComponents());
        dispatch(fetchAllSalaryStructures());
        dispatch(fetchAttendanceSummary(selectedDate));
        dispatch(getAccounts());

        // Load employees locally
        const loadEmployees = async () => {
            try {
                const res = await api.get('/hr/employees');
                if (res.data.success) setEmployees(res.data.data);
            } catch (e) {
                logger.error("Failed to load employees");
            }
        };
        loadEmployees();
    }, [dispatch, selectedDate]);

    const handleOpenAdd = () => {
        setEditingId(null);
        setFormData({
            name: '',
            type: 'EARNING',
            calculationType: 'FLAT',
            defaultValue: 0,
            isTaxable: true,
            isActive: true
        });
        setShowModal(true);
    };

    const handleOpenEdit = (comp: SalaryComponent) => {
        setEditingId(comp._id);
        setFormData({ ...comp });
        setShowModal(true);
    };

    const handleDelete = async (id: string, name: string) => {
        if (window.confirm(`Are you sure you want to delete "${name}"? This may affect existing payroll records.`)) {
            try {
                await dispatch(deleteSalaryComponent(id)).unwrap();
            } catch (err) {
                logger.error("Delete failed:", err);
                alert("Failed to delete component. It might be in use.");
            }
        }
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        try {
            if (editingId) {
                await dispatch(updateSalaryComponent({ id: editingId, data: formData })).unwrap();
            } else {
                await dispatch(createSalaryComponent(formData)).unwrap();
            }
            setShowModal(false);
        } catch (err) {
            logger.error("Operation failed:", err);
        }
    };

    const handlePayment = async (employeeId: string, bankName: string, workedDays: number) => {
        if (!accounts || accounts.length === 0) {
            alert("No payment accounts found. Please set up a Cash account in Finance -> Cash & Bank.");
            return;
        }

        // Prioritize Cash account if available
        const cashAccount = accounts.find(a => a.accountType === 'Cash');
        const targetAccount = cashAccount || accounts[0];

        const accountId = targetAccount._id;
        const paymentMode = targetAccount.accountType === 'Cash' ? 'CASH' : 'BANK_TRANSFER';
        const isWeekly = payoutFrequency === 'Weekly';

        // Use Cash terminology if paymentMode IS Cash, or generic if bankName is provided
        const paymentLabel = paymentMode === 'CASH' ? 'Cash Payment' : `Payment via ${bankName}`;

        // Directly process payment without confirmation popup
        try {
            await dispatch(processIndividualPayout({
                employeeId,
                month: selectedDate.month,
                year: selectedDate.year,
                paymentMode,
                accountId,
                overrideWorkedDays: isWeekly ? workedDays : undefined,
                force: isWeekly // Allow multiple weekly payments
            })).unwrap();
            alert("Payment Processed Successfully!");
            // Refresh data
            dispatch(fetchAttendanceSummary(selectedDate));
        } catch (err: any) {
            alert(`Payment Failed: ${err}`);
        }
    };

    const earnings = components.filter(c => c.type === 'EARNING');
    const deductions = components.filter(c => c.type === 'DEDUCTION');
    const isTeaAllowanceSelected = earnings.find(c => c._id === selectedBenefitId)?.name === 'Tea Allowance';

    return (
        <div className="space-y-10 animate-in fade-in duration-500">
            {/* Header */}
            <div className="flex items-center justify-between">
                <div>
                    <h2 className="text-2xl font-bold text-slate-800 dark:text-white">Allowance Management</h2>
                    <p className="text-slate-500 dark:text-slate-400 text-sm">Define earnings and deductions for your staff payroll.</p>
                </div>
                <button
                    onClick={handleOpenAdd}
                    className="flex items-center gap-2 bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg font-bold shadow-sm transition-all"
                >
                    <PlusCircle className="w-5 h-5" />
                    Add New Component
                </button>
            </div>

            {/* Tabs */}
            <div className="flex border-b border-slate-200 dark:border-slate-700">
                <button
                    onClick={() => setActiveTab('breakdown')}
                    className={`px-6 py-3 text-sm font-bold transition-all border-b-2 ${activeTab === 'breakdown'
                        ? 'border-blue-600 text-blue-600'
                        : 'border-transparent text-slate-500 hover:text-slate-700'
                        }`}
                >
                    Employee Benefit Breakdown
                </button>
                <button
                    onClick={() => setActiveTab('list')}
                    className={`px-6 py-3 text-sm font-bold transition-all border-b-2 ${activeTab === 'list'
                        ? 'border-blue-600 text-blue-600'
                        : 'border-transparent text-slate-500 hover:text-slate-700'
                        }`}
                >
                    Allowance Configuration
                </button>
            </div>

            {loading && components.length === 0 ? (
                <div className="flex flex-col items-center justify-center py-20 bg-white dark:bg-slate-800 rounded-xl border border-slate-200 dark:border-slate-700 border-dashed">
                    <Loader2 className="w-10 h-10 animate-spin text-blue-500 mb-4" />
                    <p className="text-slate-500 dark:text-slate-400 font-bold">Synchronizing Components...</p>
                </div>
            ) : (
                <>
                    {activeTab === 'breakdown' && (
                        <div className="bg-white dark:bg-slate-800 rounded-2xl border border-slate-200 dark:border-slate-700 overflow-hidden shadow-sm animate-in slide-in-from-bottom-4 duration-500">
                            <div className="p-6 border-b border-slate-100 dark:border-slate-700 flex flex-col sm:flex-row sm:items-center justify-between gap-4">
                                <div>
                                    <h3 className="text-lg font-bold text-slate-800 dark:text-white">Employee Benefit Breakdown</h3>
                                    <div className="flex items-center gap-3 mt-1">
                                        <p className="text-sm text-slate-500">Overview of calculated allowances. Payments are processed via Cash.</p>
                                    </div>
                                </div>

                                <div className="flex items-center gap-3">
                                    <div className="flex items-center gap-2 bg-slate-50 dark:bg-slate-900 px-3 py-1.5 rounded-lg border border-slate-200 dark:border-slate-700 shadow-sm transition-all focus-within:ring-2 focus-within:ring-blue-500/20">
                                        <CalendarIcon className="w-4 h-4 text-blue-500" />
                                        <select
                                            className="bg-transparent text-sm font-bold text-slate-700 dark:text-slate-200 outline-none cursor-pointer"
                                            value={selectedDate.month}
                                            onChange={(e) => setSelectedDate({ ...selectedDate, month: parseInt(e.target.value) })}
                                        >
                                            {Array.from({ length: 12 }, (_, i) => (
                                                <option key={i} value={i} className="dark:bg-slate-800">{new Date(0, i).toLocaleString('default', { month: 'long' })}</option>
                                            ))}
                                        </select>
                                        <div className="h-4 w-px bg-slate-200 dark:bg-slate-700 mx-1"></div>
                                        <input
                                            type="number"
                                            className="bg-transparent text-sm font-bold text-slate-700 dark:text-slate-200 w-16 outline-none text-center"
                                            value={selectedDate.year}
                                            onChange={(e) => setSelectedDate({ ...selectedDate, year: parseInt(e.target.value) })}
                                        />
                                    </div>

                                    <div className="flex items-center gap-2 bg-slate-50 dark:bg-slate-900 px-3 py-1.5 rounded-lg border border-slate-200 dark:border-slate-700 shadow-sm transition-all focus-within:ring-2 focus-within:ring-blue-500/20">
                                        <Users className="w-4 h-4 text-blue-500" />
                                        <select
                                            className="bg-transparent text-sm font-bold text-slate-700 dark:text-slate-200 outline-none cursor-pointer"
                                            value={selectedEmployeeId}
                                            onChange={(e) => setSelectedEmployeeId(e.target.value)}
                                        >
                                            <option value="ALL">All Employees</option>
                                            {employees.map(emp => (
                                                <option key={emp._id} value={emp._id}>{emp.name}</option>
                                            ))}
                                        </select>
                                    </div>

                                    <div className="flex items-center gap-2 bg-slate-50 dark:bg-slate-900 px-3 py-1.5 rounded-lg border border-slate-200 dark:border-slate-700 shadow-sm transition-all focus-within:ring-2 focus-within:ring-emerald-500/20">
                                        <TrendingUp className="w-4 h-4 text-emerald-500" />
                                        <select
                                            className="bg-transparent text-sm font-bold text-slate-700 dark:text-slate-200 outline-none cursor-pointer"
                                            value={selectedBenefitId}
                                            onChange={(e) => setSelectedBenefitId(e.target.value)}
                                        >
                                            <option value="ALL">All Benefits</option>
                                            {earnings.map(c => (
                                                <option key={c._id} value={c._id}>{c.name}</option>
                                            ))}
                                        </select>
                                    </div>

                                    <div className="flex bg-slate-100 dark:bg-slate-700 p-1 rounded-lg">
                                        <button
                                            onClick={() => setPayoutFrequency('Monthly')}
                                            className={`px-3 py-1 text-xs font-bold rounded-md transition-all ${payoutFrequency === 'Monthly' ? 'bg-white dark:bg-slate-600 shadow text-blue-600 dark:text-blue-400' : 'text-slate-500 dark:text-slate-400 hover:text-slate-700'}`}
                                        >
                                            Monthly
                                        </button>
                                        <button
                                            onClick={() => setPayoutFrequency('Weekly')}
                                            className={`px-3 py-1 text-xs font-bold rounded-md transition-all ${payoutFrequency === 'Weekly' ? 'bg-white dark:bg-slate-600 shadow text-blue-600 dark:text-blue-400' : 'text-slate-500 dark:text-slate-400 hover:text-slate-700'}`}
                                        >
                                            Weekly
                                        </button>
                                    </div>
                                </div>
                            </div>

                            <div className="overflow-x-auto">
                                <table className="w-full text-left border-collapse min-w-[1000px]">
                                    <thead>
                                        <tr className="bg-slate-50 dark:bg-slate-900/50">
                                            <th className="px-6 py-4 text-[10px] font-bold text-slate-400 uppercase tracking-widest border-b border-slate-100 dark:border-slate-700">Employee</th>
                                            <th className="px-6 py-4 text-[10px] font-bold text-slate-400 uppercase tracking-widest border-b border-slate-100 dark:border-slate-700">Worked Days</th>
                                            {!isTeaAllowanceSelected && <th className="px-6 py-4 text-[10px] font-bold text-slate-400 uppercase tracking-widest border-b border-slate-100 dark:border-slate-700">Prorated Basic</th>}
                                            {earnings.filter(c => selectedBenefitId === 'ALL' || c._id === selectedBenefitId).map(c => (
                                                <th key={c._id} className="px-6 py-4 text-[10px] font-bold text-emerald-500 uppercase tracking-widest border-b border-slate-100 dark:border-slate-700">
                                                    {c.name} {isTeaAllowanceSelected && '(Rate)'}
                                                </th>
                                            ))}
                                            {!isTeaAllowanceSelected && <th className="px-6 py-4 text-[10px] font-bold text-blue-600 dark:text-blue-400 uppercase tracking-widest border-b border-slate-100 dark:border-slate-700 bg-blue-50/30 dark:bg-blue-900/10">Selection Total</th>}
                                            {isTeaAllowanceSelected && <th className="px-6 py-4 text-[10px] font-bold text-blue-600 dark:text-blue-400 uppercase tracking-widest border-b border-slate-100 dark:border-slate-700 bg-blue-50/30 dark:bg-blue-900/10">Total Amount</th>}
                                            {!isTeaAllowanceSelected && <th className="px-6 py-4 text-[10px] font-bold text-slate-800 dark:text-white uppercase tracking-widest border-b border-slate-100 dark:border-slate-700 bg-slate-100/50 dark:bg-slate-800/50">Total Payout</th>}
                                            <th className="px-6 py-4 text-[10px] font-bold text-slate-400 uppercase tracking-widest border-b border-slate-100 dark:border-slate-700">Actions</th>
                                        </tr>
                                    </thead>
                                    <tbody className="divide-y divide-slate-100 dark:divide-slate-700">
                                        {employees.filter(e => selectedEmployeeId === 'ALL' || e._id === selectedEmployeeId).map(emp => {
                                            const structure = structures[emp._id];
                                            const attRecord = attendance.find((a: any) => (typeof a.employeeId === 'string' ? a.employeeId : a.employeeId._id) === emp._id);

                                            const daysInMonth = new Date(selectedDate.year, selectedDate.month + 1, 0).getDate();
                                            // Determine Effective Worked Days based on Frequency
                                            // Weekly limit logic: Consider leaves only (assumes standard 7 day week - leaves)
                                            // If daily attendance is available, use that. Else default to 7.
                                            const defaultWeeklyDays = 7;
                                            const effectiveWorkedDays = payoutFrequency === 'Weekly' ? (attRecord ? attRecord.workedDays : defaultWeeklyDays) : (attRecord ? attRecord.workedDays : daysInMonth);

                                            // Display Prorated Days if Monthly, else Fixed
                                            const displayDays = effectiveWorkedDays;

                                            const baseSalary = emp.baseSalary || 0;
                                            const basic = (baseSalary / daysInMonth) * effectiveWorkedDays;

                                            // Calculate ALL earnings for the Total Payout regardless of filter
                                            let totalEarningsSum = 0;
                                            let selectedEarningsSum = 0;
                                            earnings.forEach(c => {
                                                const sComp = structure?.components.find((sc: any) =>
                                                    (typeof sc.componentId === 'string' ? sc.componentId : sc.componentId._id) === c._id
                                                );
                                                const value = sComp ? sComp.amount : (c.name === 'Tea Allowance' ? 15 : 0);
                                                let amount = 0;
                                                if (c.calculationType === 'PERCENTAGE') {
                                                    amount = (basic * value) / 100;
                                                } else {
                                                    // Special calculation for Tea Allowance: Rate * Days
                                                    if (c.name === 'Tea Allowance') {
                                                        amount = value * effectiveWorkedDays;
                                                    } else {
                                                        // Prorate flat amount for others
                                                        amount = (value / daysInMonth) * effectiveWorkedDays;
                                                    }
                                                }
                                                totalEarningsSum += amount;
                                                if (selectedBenefitId === 'ALL' || c._id === selectedBenefitId) {
                                                    selectedEarningsSum += amount;
                                                }
                                            });

                                            return (
                                                <tr key={emp._id} className="hover:bg-slate-50/50 dark:hover:bg-slate-900/10 transition-colors">
                                                    <td className="px-6 py-4">
                                                        <div className="font-bold text-slate-800 dark:text-white whitespace-nowrap">{emp.name}</div>
                                                        <div className="text-[10px] font-medium text-slate-500 uppercase flex items-center gap-2 mt-0.5">
                                                            <Shield className="w-2.5 h-2.5" /> {emp.role}
                                                        </div>
                                                    </td>
                                                    <td className="px-6 py-4">
                                                        <div className="flex items-center gap-2">
                                                            <span className={`px-2 py-0.5 rounded text-xs font-bold ${displayDays < daysInMonth ? 'bg-orange-100 text-orange-600' : 'bg-emerald-100 text-emerald-600'}`}>
                                                                {displayDays} {payoutFrequency === 'Monthly' ? `/ ${daysInMonth - displayDays}` : '(Fixed)'}
                                                            </span>
                                                            <span className="text-[10px] text-slate-400 font-medium whitespace-nowrap">P / L</span>
                                                        </div>
                                                    </td>
                                                    {!isTeaAllowanceSelected && (
                                                        <td className="px-6 py-4">
                                                            <div className="font-mono text-sm font-bold text-slate-600 dark:text-slate-400">₹{Math.round(basic).toLocaleString()}</div>
                                                            {displayDays < daysInMonth && <div className="text-[9px] font-bold text-orange-500 uppercase tracking-tighter">Prorated</div>}
                                                        </td>
                                                    )}
                                                    {earnings.filter(c => selectedBenefitId === 'ALL' || c._id === selectedBenefitId).map(c => {
                                                        const sComp = structure?.components.find((sc: any) =>
                                                            (typeof sc.componentId === 'string' ? sc.componentId : sc.componentId._id) === c._id
                                                        );

                                                        let amount = 0;
                                                        const value = sComp ? sComp.amount : (c.name === 'Tea Allowance' ? 15 : 0);

                                                        if (c.calculationType === 'PERCENTAGE') {
                                                            amount = (basic * value) / 100;
                                                        } else {
                                                            if (c.name === 'Tea Allowance') {
                                                                amount = value * effectiveWorkedDays;
                                                            } else {
                                                                // Prorate flat amount
                                                                amount = (value / daysInMonth) * effectiveWorkedDays;
                                                            }
                                                        }

                                                        return (
                                                            <td key={c._id} className="px-6 py-4 font-mono text-sm text-emerald-600 dark:text-emerald-400 whitespace-nowrap">
                                                                {amount > 0 ? `₹${Math.round(amount).toLocaleString()}` : '-'}
                                                            </td>
                                                        );
                                                    })}
                                                    <td className="px-6 py-4 font-bold text-blue-600 dark:text-blue-400 bg-blue-50/30 dark:bg-blue-900/10">
                                                        <div className="font-mono">₹{Math.round(isTeaAllowanceSelected ? selectedEarningsSum : selectedEarningsSum + basic).toLocaleString()}</div>
                                                        <div className="text-[9px] text-blue-400 font-medium uppercase mt-0.5 tracking-tighter whitespace-nowrap">
                                                            {isTeaAllowanceSelected ? 'Total Amount' : 'Selection Total'}
                                                        </div>
                                                    </td>
                                                    {!isTeaAllowanceSelected && (
                                                        <td className="px-6 py-4 font-bold text-slate-800 dark:text-white bg-slate-50/50 dark:bg-slate-900/10">
                                                            <div className="text-blue-600 dark:text-blue-400">₹{Math.round(totalEarningsSum + basic).toLocaleString()}</div>
                                                            <div className="text-[9px] text-slate-400 font-medium uppercase mt-0.5 tracking-tighter whitespace-nowrap">Gross Estimate</div>
                                                        </td>
                                                    )}
                                                    <td className="px-6 py-4">
                                                        <div className="flex items-center gap-2">
                                                            <button
                                                                onClick={() => handlePayment(emp._id, accounts[0]?.bankName || 'Cash', effectiveWorkedDays)}
                                                                className="flex items-center gap-1.5 bg-blue-600 hover:bg-blue-700 text-white px-3 py-1.5 rounded-lg text-xs font-bold transition-all shadow-sm shadow-blue-500/20"
                                                            >
                                                                <Banknote className="w-3.5 h-3.5" />
                                                                Pay
                                                            </button>
                                                        </div>
                                                    </td>
                                                </tr>
                                            );
                                        })}
                                    </tbody>
                                    <tfoot className="bg-slate-50 dark:bg-slate-900/50 border-t-2 border-slate-200 dark:border-slate-700">
                                        <tr className="font-bold">
                                            <td className="px-6 py-4 text-slate-800 dark:text-white uppercase tracking-wider">Total</td>
                                            <td className="px-6 py-4 border-b border-transparent text-slate-400 font-mono text-[10px]">
                                                {employees.filter(e => selectedEmployeeId === 'ALL' || e._id === selectedEmployeeId).reduce((sum, emp) => {
                                                    const attRecord = attendance.find((a: any) => (typeof a.employeeId === 'string' ? a.employeeId : a.employeeId._id) === emp._id);
                                                    return sum + (attRecord ? attRecord.workedDays : new Date(selectedDate.year, selectedDate.month + 1, 0).getDate());
                                                }, 0)} d
                                            </td>
                                            {!isTeaAllowanceSelected && (
                                                <td className="px-6 py-4 text-slate-800 dark:text-white font-mono">
                                                    ₹{Math.round(employees.filter(e => selectedEmployeeId === 'ALL' || e._id === selectedEmployeeId).reduce((sum, emp) => {
                                                        const attRecord = attendance.find((a: any) => (typeof a.employeeId === 'string' ? a.employeeId : a.employeeId._id) === emp._id);
                                                        const daysInMonth = new Date(selectedDate.year, selectedDate.month + 1, 0).getDate();
                                                        const workedDays = attRecord ? attRecord.workedDays : daysInMonth;
                                                        return sum + ((emp.baseSalary || 0) / daysInMonth) * workedDays;
                                                    }, 0)).toLocaleString()}
                                                </td>
                                            )}
                                            {earnings.filter(c => selectedBenefitId === 'ALL' || c._id === selectedBenefitId).map(c => {
                                                const total = employees.filter(e => selectedEmployeeId === 'ALL' || e._id === selectedEmployeeId).reduce((sum, emp) => {
                                                    const structure = structures[emp._id];
                                                    const attRecord = attendance.find((a: any) => (typeof a.employeeId === 'string' ? a.employeeId : a.employeeId._id) === emp._id);
                                                    const daysInMonth = new Date(selectedDate.year, selectedDate.month + 1, 0).getDate();
                                                    const workedDays = attRecord ? attRecord.workedDays : daysInMonth;
                                                    const basic = ((emp.baseSalary || 0) / daysInMonth) * workedDays;

                                                    const sComp = structure?.components.find((sc: any) =>
                                                        (typeof sc.componentId === 'string' ? sc.componentId : sc.componentId._id) === c._id
                                                    );
                                                    const value = sComp ? sComp.amount : (c.name === 'Tea Allowance' ? 15 : 0);
                                                    return sum + (c.calculationType === 'PERCENTAGE' ? (basic * value) / 100 : value);
                                                }, 0);

                                                return (
                                                    <td key={c._id} className="px-6 py-4 text-emerald-600 dark:text-emerald-400 font-mono">
                                                        ₹{Math.round(total).toLocaleString()}
                                                    </td>
                                                );
                                            })}
                                            <td className="px-6 py-4 text-blue-600 dark:text-blue-400 font-mono bg-blue-50/30 dark:bg-blue-900/10">
                                                ₹{Math.round(employees.filter(e => selectedEmployeeId === 'ALL' || e._id === selectedEmployeeId).reduce((sum, emp) => {
                                                    const structure = structures[emp._id];
                                                    const attRecord = attendance.find((a: any) => (typeof a.employeeId === 'string' ? a.employeeId : a.employeeId._id) === emp._id);
                                                    const daysInMonth = new Date(selectedDate.year, selectedDate.month + 1, 0).getDate();
                                                    const workedDays = attRecord ? attRecord.workedDays : daysInMonth;
                                                    const basic = ((emp.baseSalary || 0) / daysInMonth) * workedDays;

                                                    let selectedEarningsSum = 0;
                                                    earnings.forEach(c => {
                                                        if (selectedBenefitId === 'ALL' || c._id === selectedBenefitId) {
                                                            const sComp = structure?.components.find((sc: any) =>
                                                                (typeof sc.componentId === 'string' ? sc.componentId : sc.componentId._id) === c._id
                                                            );
                                                            const value = sComp ? sComp.amount : (c.name === 'Tea Allowance' ? 15 : 0);
                                                            if (c.calculationType === 'PERCENTAGE') {
                                                                selectedEarningsSum += (basic * value) / 100;
                                                            } else {
                                                                if (c.name === 'Tea Allowance') {
                                                                    selectedEarningsSum += value * workedDays;
                                                                } else {
                                                                    selectedEarningsSum += (value / daysInMonth) * workedDays;
                                                                }
                                                            }
                                                        }
                                                    });
                                                    return sum + (isTeaAllowanceSelected ? selectedEarningsSum : selectedEarningsSum + basic);
                                                }, 0)).toLocaleString()}
                                            </td>
                                            {!isTeaAllowanceSelected && (
                                                <td className="px-6 py-4 text-blue-600 dark:text-blue-400 font-mono bg-slate-100/50 dark:bg-slate-800/50">
                                                    ₹{Math.round(employees.filter(e => selectedEmployeeId === 'ALL' || e._id === selectedEmployeeId).reduce((sum, emp) => {
                                                        const structure = structures[emp._id];
                                                        const attRecord = attendance.find((a: any) => (typeof a.employeeId === 'string' ? a.employeeId : a.employeeId._id) === emp._id);
                                                        const daysInMonth = new Date(selectedDate.year, selectedDate.month + 1, 0).getDate();
                                                        const workedDays = attRecord ? attRecord.workedDays : daysInMonth;
                                                        const basic = ((emp.baseSalary || 0) / daysInMonth) * workedDays;

                                                        let earningsSum = 0;
                                                        earnings.forEach(c => {
                                                            const sComp = structure?.components.find((sc: any) =>
                                                                (typeof sc.componentId === 'string' ? sc.componentId : sc.componentId._id) === c._id
                                                            );
                                                            const value = sComp ? sComp.amount : (c.name === 'Tea Allowance' ? 15 : 0);
                                                            if (c.calculationType === 'PERCENTAGE') {
                                                                earningsSum += (basic * value) / 100;
                                                            } else {
                                                                if (c.name === 'Tea Allowance') {
                                                                    earningsSum += value * workedDays;
                                                                } else {
                                                                    earningsSum += (value / daysInMonth) * workedDays;
                                                                }
                                                            }
                                                        });
                                                        return sum + basic + earningsSum;
                                                    }, 0)).toLocaleString()}
                                                </td>
                                            )}
                                            <td className="px-6 py-4 border-b border-transparent"></td>
                                        </tr>
                                    </tfoot>
                                </table>
                            </div>
                            {attendance.length === 0 && (
