            </div>
            {supplier.itemsSupplied && supplier.itemsSupplied.length > 0 ? (
              <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                {supplier.itemsSupplied.map((item, i) => (
                  <div key={i} className="p-4 bg-slate-50 dark:bg-slate-800/30 rounded-2xl border border-slate-100 dark:border-slate-800 text-center">
                    <p className="text-xs font-bold text-slate-700 dark:text-slate-300">{item}</p>
                  </div>
                ))}
              </div>
            ) : (
              <div className="py-12 text-center border-2 border-dashed border-slate-100 dark:border-slate-800 rounded-2xl">
                <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">No procurement history detected</p>
              </div>
            )}
          </div>
        </div>

        {/* Sidebar Stats Area */}
        <div className="lg:col-span-4 space-y-6">
          {/* Financial Health - Metrics Grid */}
          {/* Credit & Terms Sidebar */}
          <div className="grid grid-cols-2 gap-4">
            {/* Credit Limit */}
            <div className="bg-[#F8FBFF] dark:bg-blue-500/10 border border-blue-100/50 dark:border-blue-500/20 p-4 rounded-2xl shadow-sm flex flex-col justify-center text-center">
              <p className="text-[11px] font-bold text-slate-400 dark:text-neutral-500 uppercase tracking-wider mb-1">Credit Limit</p>
              <p className="text-lg font-black text-blue-600 dark:text-blue-400">₹{(supplier.creditLimit || 0).toLocaleString()}</p>
            </div>

            {/* Credit Days */}
            <div className="bg-slate-50 dark:bg-neutral-800 border border-slate-100 dark:border-neutral-700 p-4 rounded-2xl shadow-sm flex flex-col justify-center text-center">
              <p className="text-[11px] font-bold text-slate-400 dark:text-neutral-500 uppercase tracking-wider mb-1">Term</p>
              <p className="text-lg font-black text-slate-700 dark:text-slate-200">{supplier.creditPeriod || 0} Days</p>
            </div>
          </div>

          {/* Operational Insights - Checklist Style */}
          <div className="bg-white dark:bg-slate-900 rounded-2xl border border-slate-200 dark:border-neutral-700 shadow-sm overflow-hidden flex flex-col">
            <div className="p-5 border-b border-slate-50 dark:border-neutral-700">
              <h3 className="font-bold text-slate-800 dark:text-neutral-100">Performance Check</h3>
            </div>

            <div className="p-5 space-y-4">
              {/* Reliability Widget */}
              <div className="p-4 bg-emerald-50 dark:bg-emerald-500/10 border border-emerald-100/50 dark:border-emerald-500/20 rounded-xl group hover:bg-emerald-100/30 dark:hover:bg-emerald-500/15 transition-all cursor-pointer">
                <div className="flex items-center justify-between mb-2">
                  <div className="flex items-center gap-2">
                    <div className="p-1.5 bg-emerald-500 rounded-lg text-white">
                      <ShieldCheck className="w-3.5 h-3.5" />
                    </div>
                    <span className="text-[11px] font-bold uppercase tracking-wider text-emerald-600">Reliability Score</span>
                  </div>
                </div>
                <div className="flex items-end justify-between">
                  <span className={`text-2xl font-black ${(supplier.performanceMetrics?.reliabilityScore || 100) >= 80 ? 'text-emerald-500' : 'text-amber-500'}`}>
                    {supplier.performanceMetrics?.reliabilityScore || 100}/100
                  </span>
                  <span className="text-[11px] font-bold text-slate-400 uppercase tracking-wider mb-1">Excellent</span>
                </div>
                {/* Mini Progress Bar */}
                <div className="mt-3 w-full h-1 bg-white/50 rounded-full overflow-hidden">
                  <div
                    className="h-full bg-emerald-500 transition-all duration-1000"
                    style={{ width: `${supplier.performanceMetrics?.reliabilityScore || 100}%` }}
                  />
                </div>
              </div>

              {/* Last Update Widget */}
              <div className="flex items-center gap-4 p-3 bg-slate-50 dark:bg-slate-800/50 rounded-xl border border-slate-100 dark:border-slate-700">
                <div className="w-10 h-10 rounded-xl bg-slate-100 dark:bg-slate-700 flex items-center justify-center text-slate-400">
                  <History className="w-5 h-5" />
                </div>
                <div>
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-0.5">Last Interaction</p>
                  <p className="text-xs font-bold text-slate-700 dark:text-slate-200">
                    {supplier.updatedAt ? new Date(supplier.updatedAt).toLocaleDateString('en-IN', { day: 'numeric', month: 'short', year: 'numeric' }) : 'Initial Seed'}
                  </p>
                </div>
              </div>

              <button
                onClick={() => navigate(`/suppliers/${supplier._id}/ledger`)}
                className="w-full py-3 mt-2 bg-indigo-50 dark:bg-indigo-500/10 text-indigo-600 dark:text-indigo-400 rounded-xl text-[10px] font-black uppercase tracking-[0.2em] border border-indigo-100 dark:border-indigo-500/20 hover:bg-indigo-100 dark:hover:bg-indigo-500/20 transition-all"
              >
                Generate Ledger
              </button>
            </div>
          </div>
        </div>
      </div>
    </Layout>
  );
};

export default SupplierDetail;

import { logger } from '@/shared/lib/logger';
import React, { useState, useMemo, useEffect } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import { RootState, AppDispatch } from "@/app/store/store";
import { getSupplierGroups, deleteSupplierGroup, SupplierGroup } from "@/entities/contact/model/supplierGroupSlice";
import {
    Search,
    Truck,
    FolderPlus,
    Edit,
    Trash2,
    Tag,
    Percent,
    UserPlus,
    ChevronDown,
    ChevronUp,
    Crown,
    Building,
    Star,
    Clock,
    CreditCard,
    MoreVertical
} from 'lucide-react';



import Layout from '@/shared/ui/Layout/Layout';
import PageHeader from '@/shared/ui/Layout/PageHeader';
import SupplierSubNav from './SupplierSubNav';
import SupplierGroupModal from "./components/SupplierGroupModal";

const SupplierGroups: React.FC = () => {
    const dispatch = useDispatch<AppDispatch>();
    const { suppliers } = useSelector((state: RootState) => state.suppliers);
    const { groups, isLoading } = useSelector((state: RootState) => state.supplierGroups);

    // const [groups, setGroups] = useState<SupplierGroup[]>(DEFAULT_GROUPS); // Replaced by Redux
    const [searchTerm, setSearchTerm] = useState('');
    const [expandedGroup, setExpandedGroup] = useState<string | null>(null);
    const [isCreateModalOpen, setIsCreateModalOpen] = useState(false);
    const [openMenuId, setOpenMenuId] = useState<string | null>(null);
    const [editingGroup, setEditingGroup] = useState<SupplierGroup | null>(null);

    const handleDeleteGroup = async (id: string) => {
        if (window.confirm('Are you sure you want to delete this group?')) {
            try {
                await dispatch(deleteSupplierGroup(id)).unwrap();
            } catch (error) {
                logger.error('Failed to delete group:', error);
            }
        }
    };

    useEffect(() => {
        dispatch(getSupplierGroups());
    }, [dispatch]);

    // Calculate member counts
    const groupsWithCounts = useMemo(() => {
        return groups.map(group => ({
            ...group,
            memberCount: (suppliers || []).filter(s => (s as any).groupId === group._id).length // Assuming supplier has groupId
        }));
    }, [groups, suppliers]);

    const filteredGroups = groupsWithCounts.filter(g =>
        g.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
        g.description.toLowerCase().includes(searchTerm.toLowerCase())
    );

    const getGroupIcon = (iconName: string) => {
        switch (iconName) {
            case 'crown': return <Crown className="w-5 h-5" />;
            case 'building': return <Building className="w-5 h-5" />;
            case 'star': return <Star className="w-5 h-5" />;
            default: return <Truck className="w-5 h-5" />;
        }
    };

    const totalSuppliers = (suppliers || []).length;
    const assignedSuppliers = groupsWithCounts.reduce((acc, g) => acc + (g.memberCount || 0), 0);

    return (
        <Layout>
            <PageHeader
                title="Supplier Groups"
                actions={
                    <button
                        onClick={() => { setEditingGroup(null); setIsCreateModalOpen(true); }}
                        className="px-6 py-2 bg-indigo-600 text-white rounded-xl text-sm font-bold shadow-lg shadow-indigo-200 dark:shadow-none hover:bg-indigo-700 active:scale-95 transition-all flex items-center gap-2"
                    >
                        <FolderPlus className="w-4 h-4" /> Create Group
                    </button>
                }
            />

            <SupplierSubNav />

            <div className="space-y-6 animate-fade-in">
                {/* Summary Cards */}
                {/* Summary Cards */}
                <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                    {/* Total Groups */}
                    <div className="bg-white dark:bg-neutral-800 border-2 border-indigo-200 dark:border-indigo-500/30 rounded-xl p-5 relative overflow-hidden shadow-sm">
                        <div className="flex items-center gap-2 mb-1">
                            <div className="p-1.5 rounded-lg bg-indigo-50 dark:bg-indigo-500/10 text-indigo-600 dark:text-indigo-400">
                                <FolderPlus className="w-4 h-4" />
                            </div>
                            <span className="text-xs font-bold text-indigo-600 dark:text-indigo-400 uppercase tracking-wide">Total Groups</span>
                        </div>
                        <span className="text-3xl font-black text-slate-900 dark:text-white">{groups.length}</span>
                    </div>

                    {/* Total Suppliers */}
                    <div className="bg-white dark:bg-neutral-800 border border-slate-100 dark:border-neutral-700 rounded-xl p-5 relative overflow-hidden shadow-sm">
                        <div className="flex items-center gap-2 mb-1">
                            <div className="p-1.5 rounded-lg bg-emerald-50 dark:bg-emerald-500/10 text-emerald-600 dark:text-emerald-400">
                                <Truck className="w-4 h-4" />
                            </div>
                            <span className="text-xs font-bold text-emerald-600 dark:text-emerald-400 uppercase tracking-wide">Total Suppliers</span>
                        </div>
                        <span className="text-3xl font-black text-slate-900 dark:text-white">{totalSuppliers}</span>
                    </div>

                    {/* Assigned */}
                    <div className="bg-white dark:bg-neutral-800 border border-slate-100 dark:border-neutral-700 rounded-xl p-5 relative overflow-hidden shadow-sm">
                        <div className="flex items-center gap-2 mb-1">
                            <div className="p-1.5 rounded-lg bg-blue-50 dark:bg-blue-500/10 text-blue-600 dark:text-blue-400">
                                <UserPlus className="w-4 h-4" />
                            </div>
                            <span className="text-xs font-bold text-blue-600 dark:text-blue-400 uppercase tracking-wide">Assigned</span>
                        </div>
                        <span className="text-3xl font-black text-slate-900 dark:text-white">{assignedSuppliers}</span>
                    </div>

                    {/* Unassigned */}
                    <div className="bg-white dark:bg-neutral-800 border border-slate-100 dark:border-neutral-700 rounded-xl p-5 relative overflow-hidden shadow-sm">
                        <div className="flex items-center gap-2 mb-1">
                            <div className="p-1.5 rounded-lg bg-amber-50 dark:bg-amber-500/10 text-amber-600 dark:text-amber-400">
                                <Tag className="w-4 h-4" />
                            </div>
                            <span className="text-xs font-bold text-amber-600 dark:text-amber-400 uppercase tracking-wide">Unassigned</span>
                        </div>
                        <span className="text-3xl font-black text-slate-900 dark:text-white">{totalSuppliers - assignedSuppliers}</span>
                    </div>
                </div>

                {/* Filter Bar */}
                <div className="flex items-center justify-between">
                    <div className="relative group">
                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 group-focus-within:text-indigo-500 transition-colors" />
                        <input
                            type="text"
                            placeholder="Search groups..."
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                            className="w-80 pl-9 pr-4 py-2.5 bg-white dark:bg-neutral-800 border border-slate-200 dark:border-neutral-700 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-400 transition-all text-sm text-slate-700 dark:text-neutral-200 placeholder:text-slate-400 shadow-sm"
                        />
                    </div>
                </div>

                {/* Groups Table */}
                <div className="bg-white dark:bg-neutral-800 rounded-2xl border border-slate-100 dark:border-neutral-700 shadow-sm overflow-hidden">
                    <div className="overflow-x-auto">
                        <table className="w-full text-left">
                            <thead>
                                <tr className="border-b border-slate-100 dark:border-neutral-700">
                                    <th className="px-6 py-4 text-[11px] font-bold text-slate-500 dark:text-neutral-400 uppercase tracking-wider whitespace-nowrap">Group Name</th>
                                    <th className="px-6 py-4 text-[11px] font-bold text-slate-500 dark:text-neutral-400 uppercase tracking-wider whitespace-nowrap">Members</th>
                                    <th className="px-6 py-4 text-[11px] font-bold text-slate-500 dark:text-neutral-400 uppercase tracking-wider whitespace-nowrap">Payment Terms</th>
                                    <th className="px-6 py-4 text-[11px] font-bold text-slate-500 dark:text-neutral-400 uppercase tracking-wider whitespace-nowrap">Credit Limit</th>
                                    <th className="px-6 py-4 text-[11px] font-bold text-slate-500 dark:text-neutral-400 uppercase tracking-wider whitespace-nowrap">Tags</th>
                                    <th className="px-6 py-4 text-[11px] font-bold text-slate-500 dark:text-neutral-400 uppercase tracking-wider text-right whitespace-nowrap">Actions</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-slate-50 dark:divide-neutral-700/50">
                                {filteredGroups.length === 0 ? (
                                    <tr>
                                        <td colSpan={6} className="px-6 py-16 text-center">
                                            <div className="flex flex-col items-center gap-3">
                                                <Tag className="w-10 h-10 text-slate-200 dark:text-neutral-700" />
                                                <p className="text-sm font-bold text-slate-400 dark:text-neutral-500">No supplier groups found</p>
                                            </div>
                                        </td>
                                    </tr>
                                ) : (
                                    filteredGroups.map((group) => (
                                        <tr
                                            key={group._id}
                                            className="group hover:bg-slate-50/50 dark:hover:bg-neutral-700/30 transition-colors"
                                            onClick={() => { setEditingGroup(group); setIsCreateModalOpen(true); }}
                                        >
                                            {/* Name */}
                                            <td className="px-6 py-4 whitespace-nowrap">
                                                <div className="flex items-center gap-3">
                                                    <div
                                                        className="w-8 h-8 rounded-lg flex items-center justify-center text-white shadow-sm"
                                                        style={{ backgroundColor: group.color }}
                                                    >
                                                        {getGroupIcon(group.icon)}
                                                    </div>
                                                    <div>
                                                        <p className="text-sm font-bold text-slate-800 dark:text-neutral-100">{group.name}</p>
                                                        <p className="text-xs text-slate-500 dark:text-neutral-400 truncate max-w-[200px]">{group.description}</p>
                                                    </div>
                                                </div>
                                            </td>

                                            {/* Members */}
                                            <td className="px-6 py-4 whitespace-nowrap">
                                                <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-bold bg-slate-100 text-slate-600 dark:bg-neutral-700 dark:text-neutral-300">
                                                    {group.memberCount} Suppliers
                                                </span>
                                            </td>

                                            {/* Terms */}
                                            <td className="px-6 py-4 whitespace-nowrap">
                                                <span className="text-sm font-medium text-slate-700 dark:text-neutral-200">
                                                    {group.paymentTerms} Days
                                                </span>
                                            </td>

                                            {/* Credit Limit */}
                                            <td className="px-6 py-4 whitespace-nowrap">
                                                <span className="text-sm font-bold text-slate-700 dark:text-neutral-200">
                                                    ₹ {group.creditLimit.toLocaleString('en-IN')}
                                                </span>
                                            </td>

                                            {/* Tags */}
                                            <td className="px-6 py-4 whitespace-nowrap">
                                                <div className="flex gap-1.5">
                                                    {group.priority && (
                                                        <span className={`text-[10px] px-2 py-0.5 rounded border font-bold uppercase ${group.priority === 'High' ? 'bg-rose-50 border-rose-100 text-rose-600' :
                                                            group.priority === 'Medium' ? 'bg-amber-50 border-amber-100 text-amber-600' :
                                                                'bg-emerald-50 border-emerald-100 text-emerald-600'
                                                            }`}>
                                                            {group.priority}
                                                        </span>
                                                    )}
                                                    {group.nature && (
                                                        <span className="text-[10px] px-2 py-0.5 rounded border bg-slate-50 border-slate-100 text-slate-600 font-bold uppercase">
                                                            {group.nature}
                                                        </span>
                                                    )}
                                                </div>
                                            </td>

                                            {/* Actions */}
                                            <td className="px-6 py-4 whitespace-nowrap text-right" onClick={(e) => e.stopPropagation()}>
                                                <div className="relative">
                                                    <button
                                                        onClick={() => setOpenMenuId(openMenuId === group._id ? null : group._id)}
                                                        className="p-1.5 text-slate-300 dark:text-neutral-600 hover:text-slate-500 dark:hover:text-neutral-400 hover:bg-slate-100 dark:hover:bg-neutral-700 rounded-lg transition-all"
                                                    >
                                                        <MoreVertical className="w-4 h-4" />
                                                    </button>
                                                    {openMenuId === group._id && (
                                                        <div className="absolute right-0 top-8 w-48 bg-white dark:bg-neutral-800 border border-slate-200 dark:border-neutral-700 rounded-xl shadow-lg z-20 py-1 animate-in fade-in zoom-in-95 duration-150">
                                                            <button
                                                                onClick={() => { setEditingGroup(group); setIsCreateModalOpen(true); setOpenMenuId(null); }}
                                                                className="w-full px-4 py-2.5 text-left text-sm text-slate-700 dark:text-neutral-300 hover:bg-slate-50 dark:hover:bg-neutral-700 flex items-center gap-2 font-medium"
                                                            >
                                                                <Edit className="w-3.5 h-3.5 text-slate-400" /> Edit Group
                                                            </button>
                                                            <button
                                                                onClick={() => { /* Add logic for adding suppliers */ setOpenMenuId(null); }}
                                                                className="w-full px-4 py-2.5 text-left text-sm text-slate-700 dark:text-neutral-300 hover:bg-slate-50 dark:hover:bg-neutral-700 flex items-center gap-2 font-medium"
                                                            >
                                                                <UserPlus className="w-3.5 h-3.5 text-slate-400" /> Add Suppliers
                                                            </button>
                                                            <div className="h-px bg-slate-100 dark:bg-neutral-700 my-1" />
                                                            <button
                                                                onClick={() => { handleDeleteGroup(group._id); setOpenMenuId(null); }}
                                                                className="w-full px-4 py-2.5 text-left text-sm text-rose-600 dark:text-rose-400 hover:bg-rose-50 dark:hover:bg-rose-500/10 flex items-center gap-2 font-medium"
                                                            >
                                                                <Trash2 className="w-3.5 h-3.5" /> Delete
                                                            </button>
                                                        </div>
                                                    )}
                                                </div>
                                            </td>
                                        </tr>
                                    ))
                                )}
                            </tbody>
                        </table>
                    </div>
                </div>

                {/* Quick Tips */}
                <div className="bg-gradient-to-r from-indigo-50 to-purple-50 dark:from-indigo-900/10 dark:to-purple-900/10 p-5 rounded-2xl border border-indigo-100 dark:border-indigo-500/20">
                    <h4 className="font-bold text-indigo-900 dark:text-indigo-100 flex items-center gap-2 mb-2">
                        <div className="p-1 bg-indigo-100 dark:bg-indigo-500/20 rounded-lg">
                            <Star className="w-4 h-4 text-indigo-600 dark:text-indigo-400" />
                        </div>
                        Tips for Supplier Groups
                    </h4>
                    <ul className="text-sm text-indigo-700 dark:text-indigo-300 space-y-2 pl-1">
                        <li className="flex items-start gap-2">
                            <span className="w-1.5 h-1.5 rounded-full bg-indigo-400 mt-1.5 flex-shrink-0" />
                            Group suppliers by reliability and importance for better management
                        </li>
                        <li className="flex items-start gap-2">
                            <span className="w-1.5 h-1.5 rounded-full bg-indigo-400 mt-1.5 flex-shrink-0" />
                            Set appropriate payment terms based on supplier relationships
                        </li>
                        <li className="flex items-start gap-2">
                            <span className="w-1.5 h-1.5 rounded-full bg-indigo-400 mt-1.5 flex-shrink-0" />
                            Define credit limits to control purchasing exposure
                        </li>
                        <li className="flex items-start gap-2">
                            <span className="w-1.5 h-1.5 rounded-full bg-indigo-400 mt-1.5 flex-shrink-0" />
                            Use discount rates to track negotiated pricing from strategic partners
                        </li>
                    </ul>
                </div>
            </div>

            <SupplierGroupModal
                isOpen={isCreateModalOpen}
                onClose={() => { setIsCreateModalOpen(false); setEditingGroup(null); }}
                initialData={editingGroup}
            />
        </Layout>
    );
};

export default SupplierGroups;

import { logger } from '@/shared/lib/logger';
import React, { useState, useEffect, useMemo } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { ArrowLeft, Printer, Filter, Calendar, Book, RefreshCw, FileText, Search } from 'lucide-react';
import { useSelector } from 'react-redux';
import { RootState } from "@/app/store/store";
import api from "@/shared/api/api";
import { toast } from 'react-toastify';
import Layout from '@/shared/ui/Layout/Layout';
import PageHeader from '@/shared/ui/Layout/PageHeader';
import SupplierSubNav from './SupplierSubNav';
import SupplierLedgerSummary from './components/SupplierLedgerSummary';
import SupplierLedgerTable from './components/SupplierLedgerTable';

// Interfaces for response data
interface Transaction {
    date: string;
    type: 'BILL' | 'PAYMENT' | 'DEBIT_NOTE';
    refNo: string;
    description: string;
    credit: number;
    debit: number;
    balance: number;
    originalRef: any;
    purchaseReturnId?: string;
}

interface LedgerData {
    supplier: {
        _id: string;
        businessName: string;
        openingBalance: number;
    };
    period: {
        start: string;
        end: string;
    };
    openingBalance: number;
    closingBalance: number;
    totals: {
        credit: number;
        debit: number;
    };
    transactions: Transaction[];
}

const SupplierLedger: React.FC = () => {
    const { id } = useParams<{ id: string }>();
    const navigate = useNavigate();
    const [loading, setLoading] = useState(false);
    const [data, setData] = useState<LedgerData | null>(null);
    const [selectedSupplierId, setSelectedSupplierId] = useState<string | null>(id || null);
    const [searchTerm, setSearchTerm] = useState('');

    const user = useSelector((state: RootState) => state.auth.user);
    const token = user?.token;
    const { suppliers } = useSelector((state: RootState) => state.suppliers);

    // Filtered suppliers for picker
    const filteredSuppliers = useMemo(() => {
        const list = (suppliers || []).filter((s: any) => s.status === 'active');
        if (!searchTerm) return list;
        const term = searchTerm.toLowerCase();
        return list.filter((s: any) =>
            s.businessName?.toLowerCase().includes(term) ||
            s.contactPersonName?.toLowerCase().includes(term) ||
            s.supplierId?.toLowerCase().includes(term)
        );
    }, [suppliers, searchTerm]);

    const [startDate, setStartDate] = useState(() => {
        const now = new Date();
        // Indian Fiscal Year: April 1 to March 31
        // If current month is Jan-Mar (0-2), start year is previous year
        const startYear = now.getMonth() < 3 ? now.getFullYear() - 1 : now.getFullYear();
        return `${startYear}-04-01`;
    });
    const [endDate, setEndDate] = useState(() => {
        return new Date().toISOString().split('T')[0];
    });

    const effectiveId = selectedSupplierId || id;

    const fetchLedger = async () => {
        if (!effectiveId || !token) return;
        setLoading(true);
        try {
            const response = await api.get(`/api/purchases/suppliers/${effectiveId}/ledger`, {
                params: { startDate, endDate },
                headers: { Authorization: `Bearer ${token}` }
            });
            if (response.data.success) {
                setData(response.data.data);
            }
        } catch (error: any) {
            logger.error(error);
            toast.error(error.response?.data?.message || 'Failed to fetch ledger');
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        if (effectiveId) fetchLedger();
    }, [effectiveId, token]);

    useEffect(() => {
        if (effectiveId) fetchLedger();
    }, [startDate, endDate]);

    const handleSelectSupplier = (supplierId: string) => {
        setSelectedSupplierId(supplierId);
        setData(null);
    };

    const handlePrint = () => { window.print(); };

    const formatCurrency = (amount: number) => {
        return new Intl.NumberFormat('en-IN', { style: 'currency', currency: 'INR', minimumFractionDigits: 0 }).format(amount);
    };

    const handleRowClick = (t: Transaction) => {
        if (t.type === 'BILL' && t.originalRef?._id) {
            navigate(`/purchase/bills/view/${t.originalRef._id}`);
        } else if (t.type === 'DEBIT_NOTE') {
            if (t.purchaseReturnId) {
                navigate(`/purchase/returns/view/${t.purchaseReturnId}`);
            } else {
                navigate(`/purchase/debit-notes`);
            }
        } else if (t.type === 'PAYMENT') {
            navigate(`/purchase/payments`);
        }
    };

    // ==========================================
    // SUPPLIER PICKER VIEW (no supplier selected)
    // ==========================================
    if (!effectiveId) {
        return (
            <Layout>
                <div className="space-y-8 animate-in fade-in duration-700 pb-10 max-w-[1600px] mx-auto">
                    <PageHeader
                        title="Supplier Ledger"
                        description="Select a supplier to view their account statement"
                    />
                    <SupplierSubNav />

                    {/* Search */}
                    <div className="relative max-w-md">
                        <Search className="w-4 h-4 absolute left-3.5 top-1/2 -translate-y-1/2 text-slate-400" />
                        <input
                            type="text"
                            placeholder="Search suppliers..."
                            value={searchTerm}
                            onChange={e => setSearchTerm(e.target.value)}
                            className="w-full pl-10 pr-4 py-2.5 bg-white dark:bg-neutral-800 border border-slate-100 dark:border-neutral-700 rounded-xl text-sm text-slate-800 dark:text-neutral-200 focus:ring-2 focus:ring-indigo-500/30 focus:border-indigo-500/50 outline-none shadow-sm placeholder:text-slate-400 dark:placeholder:text-neutral-500"
                        />
                    </div>

                    {/* Supplier Grid - Dashboard card style */}
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                        {filteredSuppliers.length === 0 ? (
                            <div className="col-span-full text-center py-20">
                                <Book className="w-12 h-12 mx-auto mb-3 text-slate-200 dark:text-neutral-700" />
                                <p className="text-sm font-bold text-slate-400 dark:text-neutral-500">No suppliers found</p>
                                <p className="text-[10px] text-slate-300 dark:text-neutral-600 mt-1 uppercase tracking-wider font-bold">Try adjusting your search term</p>
                            </div>
                        ) : (
                            filteredSuppliers.map((s: any) => (
                                <button
                                    key={s._id}
                                    onClick={() => handleSelectSupplier(s._id)}
                                    className="bg-white dark:bg-neutral-800 border border-slate-100 dark:border-neutral-700 p-5 rounded-2xl shadow-sm hover:shadow-md hover:border-indigo-200 dark:hover:border-indigo-500/30 transition-all text-left group relative overflow-hidden"
                                >
                                    <div className="absolute top-0 right-0 w-20 h-20 bg-indigo-500/5 rounded-full -mr-10 -mt-10 group-hover:scale-150 transition-all" />
                                    <div className="flex items-center gap-4 relative z-10">
                                        <div className="w-10 h-10 bg-indigo-50 dark:bg-indigo-500/10 border border-indigo-100/50 dark:border-indigo-500/20 rounded-xl flex items-center justify-center text-indigo-500 font-black text-sm shrink-0 group-hover:bg-indigo-500 group-hover:text-white group-hover:border-indigo-500 transition-all">
                                            {s.businessName?.charAt(0)?.toUpperCase() || 'S'}
                                        </div>
                                        <div className="min-w-0 flex-1">
                                            <p className="font-bold text-slate-800 dark:text-neutral-100 text-sm truncate">{s.businessName}</p>
                                            {s.contactPersonName && (
                                                <p className="text-[10px] text-slate-400 dark:text-neutral-500 truncate font-medium mt-0.5">{s.contactPersonName}</p>
                                            )}
                                        </div>
                                        <Book className="w-4 h-4 text-slate-200 dark:text-neutral-700 group-hover:text-indigo-500 transition-colors shrink-0" />
                                    </div>
                                </button>
                            ))
                        )}
                    </div>
                </div>
            </Layout>
        );
    }

    // ==========================================
    // LOADING STATE
    // ==========================================
    if (loading && !data) return (
        <Layout>
            <div className="space-y-8 animate-in fade-in duration-700 pb-10 max-w-[1600px] mx-auto">
                <SupplierSubNav />
                <div className="flex flex-col items-center justify-center py-20">
                    <RefreshCw className="w-8 h-8 text-indigo-500 animate-spin mb-4" />
                    <p className="text-sm font-bold text-slate-400 dark:text-neutral-500">Loading Ledger...</p>
                </div>
            </div>
        </Layout>
    );

    // ==========================================
    // NO DATA STATE
    // ==========================================
    if (!data) return (
        <Layout>
            <div className="space-y-8 animate-in fade-in duration-700 pb-10 max-w-[1600px] mx-auto">
                <SupplierSubNav />
                <div className="flex flex-col items-center justify-center py-20">
                    <FileText className="w-12 h-12 text-slate-200 dark:text-neutral-700 mb-3" />
                    <p className="text-sm font-bold text-slate-400 dark:text-neutral-500">No Data Found</p>
                </div>
            </div>
        </Layout>
    );

    // ==========================================
    // MAIN LEDGER VIEW
    // ==========================================
    return (
        <Layout>
            <div className="space-y-8 animate-in fade-in duration-700 pb-10 max-w-[1600px] mx-auto">

                {/* Header Section — Dashboard style */}
                <div className="flex items-center justify-between pb-2">
                    <div className="flex items-center gap-4">
                        {(id || selectedSupplierId) && (
                            <button
                                onClick={() => id ? navigate(`/suppliers/${id}`) : (setSelectedSupplierId(null), setData(null))}
                                className="w-9 h-9 flex items-center justify-center rounded-xl bg-slate-50 dark:bg-neutral-800 border border-slate-100 dark:border-neutral-700 text-slate-500 dark:text-neutral-400 hover:bg-indigo-50 hover:text-indigo-500 hover:border-indigo-200 dark:hover:bg-indigo-500/10 dark:hover:border-indigo-500/20 transition-all mr-2"
                            >
                                <ArrowLeft className="w-4 h-4" />
                            </button>
                        )}
                        <div className="flex flex-col">
                            <h1 className="text-xl font-bold text-slate-800 dark:text-neutral-100 tracking-tight">{data.supplier.businessName}</h1>
                            <div className="flex items-center gap-2 mt-1">
