import React, { useState, useEffect } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { X, Save, Shield, Tag, CreditCard, Palette, Truck, Crown, Building, Star } from 'lucide-react';
import { AppDispatch, RootState } from "@/app/store/store";
import { createSupplierGroup, updateSupplierGroup, reset, SupplierGroup } from "@/entities/contact/model/supplierGroupSlice";
import { toast } from 'react-toastify';

interface SupplierGroupModalProps {
    isOpen: boolean;
    onClose: () => void;
    initialData: SupplierGroup | null;
}

const SupplierGroupModal: React.FC<SupplierGroupModalProps> = ({ isOpen, onClose, initialData }) => {
    const dispatch = useDispatch<AppDispatch>();
    const { isLoading, isSuccess, isError, message } = useSelector((state: RootState) => state.supplierGroups);

    const [formData, setFormData] = useState<Partial<SupplierGroup>>({
        name: '',
        description: '',
        color: '#6366f1',
        icon: 'truck',
        paymentTerms: 30,
        creditLimit: 0,
        discountPercent: 0,
        priority: 'Medium',
        nature: 'Standard'
    });

    useEffect(() => {
        if (initialData) {
            setFormData(initialData);
        } else {
            setFormData({
                name: '',
                description: '',
                color: '#6366f1',
                icon: 'truck',
                paymentTerms: 30,
                creditLimit: 0,
                discountPercent: 0,
                priority: 'Medium',
                nature: 'Standard'
            });
        }
    }, [initialData, isOpen]);

    useEffect(() => {
        if (isSuccess && isOpen) {
            toast.success(`Group ${initialData ? 'updated' : 'created'} successfully`);
            onClose();
            dispatch(reset());
        }
        if (isError && message && isOpen) {
            toast.error(message);
            dispatch(reset());
        }
    }, [isSuccess, isError, message, isOpen, initialData, onClose, dispatch]);

    const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
        const { name, value, type } = e.target;
        setFormData(prev => ({
            ...prev,
            [name]: type === 'number' ? parseFloat(value) || 0 : value
        }));
    };

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (initialData?._id) {
            dispatch(updateSupplierGroup({ id: initialData._id, data: formData }));
        } else {
            dispatch(createSupplierGroup(formData));
        }
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-300">
            <div className="bg-white dark:bg-neutral-900 w-full max-w-2xl rounded-[2.5rem] shadow-2xl overflow-hidden border border-slate-100 dark:border-neutral-800 animate-in zoom-in-95 duration-300">
                <div className="px-8 py-6 border-b border-slate-50 dark:border-neutral-800 flex items-center justify-between bg-slate-50/50 dark:bg-neutral-800/50">
                    <div>
                        <h2 className="text-xl font-black text-slate-800 dark:text-white uppercase tracking-tight">
                            {initialData ? 'Refine Group Logic' : 'Initialize New Group'}
                        </h2>
                        <p className="text-[10px] font-black text-indigo-500 uppercase tracking-[0.2em] mt-1">Classification Artifact</p>
                    </div>
                    <button onClick={onClose} className="p-2 hover:bg-slate-200/50 dark:hover:bg-neutral-700 rounded-xl transition-all">
                        <X className="w-5 h-5 text-slate-400" />
                    </button>
                </div>

                <form onSubmit={handleSubmit} className="p-8 space-y-8 max-h-[70vh] overflow-y-auto custom-scrollbar">
                    {/* Basic Info */}
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <div className="space-y-2">
                            <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 px-1 flex items-center gap-2">
                                <Tag className="w-3.5 h-3.5" /> Group Designation
                            </label>
                            <input
                                type="text"
                                name="name"
                                value={formData.name}
                                onChange={handleChange}
                                required
                                className="w-full px-5 py-4 bg-slate-50 dark:bg-slate-800/50 border-2 border-transparent focus:border-indigo-500 rounded-2xl outline-none transition-all font-bold text-sm"
                                placeholder="e.g. Strategic Tech Partners"
                            />
                        </div>

                        <div className="space-y-2">
                            <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 px-1 flex items-center gap-2">
                                <Shield className="w-3.5 h-3.5" /> Priority Level
                            </label>
                            <select
                                name="priority"
                                value={formData.priority}
                                onChange={handleChange}
                                className="w-full px-5 py-4 bg-slate-50 dark:bg-slate-800/50 border-2 border-transparent focus:border-indigo-500 rounded-2xl outline-none transition-all font-bold text-sm appearance-none"
                            >
                                <option value="High">High Priority</option>
                                <option value="Medium">Standard</option>
                                <option value="Low">Low Priority</option>
                            </select>
                        </div>
                    </div>

                    {/* Aesthetics */}
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <div className="space-y-2">
                            <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 px-1 flex items-center gap-2">
                                <Palette className="w-3.5 h-3.5" /> Visual Identifier (Color)
                            </label>
                            <div className="flex gap-3">
                                <input
                                    type="color"
                                    name="color"
                                    value={formData.color}
                                    onChange={handleChange}
                                    className="w-14 h-14 p-1 bg-slate-50 dark:bg-slate-800 border-none rounded-2xl cursor-pointer"
                                />
                                <input
                                    type="text"
                                    value={formData.color}
                                    readOnly
                                    className="flex-grow px-5 py-4 bg-slate-50 dark:bg-slate-800/50 border-none rounded-2xl font-mono text-xs font-bold text-slate-400"
                                />
                            </div>
                        </div>

                        <div className="space-y-2">
                            <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 px-1 flex items-center gap-2">
                                <Crown className="w-3.5 h-3.5" /> Symbolic Glyph (Icon)
                            </label>
                            <div className="grid grid-cols-4 gap-2">
                                {['truck', 'crown', 'building', 'star'].map((icon) => (
                                    <button
                                        key={icon}
                                        type="button"
                                        onClick={() => setFormData(prev => ({ ...prev, icon }))}
                                        className={`p-3 rounded-xl border-2 transition-all flex items-center justify-center ${formData.icon === icon
                                                ? 'border-indigo-500 bg-indigo-50 dark:bg-indigo-500/10 text-indigo-600'
                                                : 'border-transparent bg-slate-50 dark:bg-slate-800 text-slate-400 hover:bg-slate-100'
                                            }`}
                                    >
                                        {icon === 'truck' && <Truck className="w-5 h-5" />}
                                        {icon === 'crown' && <Crown className="w-5 h-5" />}
                                        {icon === 'building' && <Building className="w-5 h-5" />}
                                        {icon === 'star' && <Star className="w-5 h-5" />}
                                    </button>
                                ))}
                            </div>
                        </div>
                    </div>

                    {/* Financial Logic */}
                    <div className="space-y-4">
                        <h3 className="text-[10px] font-black uppercase tracking-[0.2em] text-indigo-500 border-b border-indigo-50 dark:border-indigo-500/10 pb-2">Financial Constraints</h3>
                        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                            <div className="space-y-2">
                                <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 px-1">Payment Window (Days)</label>
                                <input
                                    type="number"
                                    name="paymentTerms"
                                    value={formData.paymentTerms}
                                    onChange={handleChange}
                                    className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-800/50 border-none rounded-xl font-bold text-sm"
                                />
                            </div>
                            <div className="space-y-2">
                                <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 px-1 flex items-center gap-1">Credit Ceiling <CreditCard className="w-3 h-3" /></label>
                                <input
                                    type="number"
                                    name="creditLimit"
                                    value={formData.creditLimit}
                                    onChange={handleChange}
                                    className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-800/50 border-none rounded-xl font-bold text-sm"
                                />
                            </div>
                            <div className="space-y-2">
                                <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 px-1">Strategic Discount %</label>
                                <input
                                    type="number"
                                    name="discountPercent"
                                    value={formData.discountPercent}
                                    onChange={handleChange}
                                    className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-800/50 border-none rounded-xl font-bold text-sm"
                                />
                            </div>
                        </div>
                    </div>

                    <div className="space-y-2">
                        <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 px-1">Contextual Description</label>
                        <textarea
                            name="description"
                            value={formData.description}
                            onChange={handleChange}
                            rows={3}
                            className="w-full px-5 py-4 bg-slate-50 dark:bg-slate-800/50 border-none rounded-2xl font-bold text-sm"
                            placeholder="Define the purpose and scope of this group..."
                        />
                    </div>
                </form>

                <div className="px-8 py-6 bg-slate-50 dark:bg-neutral-800/50 border-t border-slate-50 dark:border-neutral-800 flex justify-end gap-3">
                    <button
                        type="button"
                        onClick={onClose}
                        className="px-6 py-3 text-slate-400 font-black text-[10px] uppercase tracking-widest hover:text-slate-600 transition-all"
                    >
                        Abort
                    </button>
                    <button
                        onClick={handleSubmit}
                        disabled={isLoading}
                        className="px-8 py-3 bg-indigo-600 text-white font-black text-[10px] uppercase tracking-[0.2em] rounded-xl shadow-lg shadow-indigo-100 dark:shadow-none hover:bg-indigo-700 active:scale-95 transition-all flex items-center gap-2"
                    >
                        {isLoading ? (
                            <div className="w-3.5 h-3.5 border-2 border-white/20 border-t-white rounded-full animate-spin" />
                        ) : (
                            <Save className="w-3.5 h-3.5" />
                        )}
                        {initialData ? 'Update Matrix' : 'Initialize Group'}
                    </button>
                </div>
            </div>
        </div>
    );
};

export default SupplierGroupModal;

import React, { useState, useMemo } from 'react';
import { Book, RefreshCw, ArrowUpDown, ArrowUp, ArrowDown } from 'lucide-react';

interface Transaction {
    date: string;
    type: 'BILL' | 'PAYMENT' | 'DEBIT_NOTE';
    refNo: string;
    description: string;
    credit: number;
    debit: number;
    balance: number;
    originalRef: any;
    purchaseReturnId?: string;
}

interface LedgerData {
    period: {
        start: string;
        end: string;
    };
    openingBalance: number;
    closingBalance: number;
    totals: {
        credit: number;
        debit: number;
    };
    transactions: Transaction[];
}

interface SupplierLedgerTableProps {
    data: LedgerData;
    loading: boolean;
    onRowClick?: (t: Transaction) => void;
}

type SortKey = 'date' | 'type' | 'refNo' | 'debit' | 'credit' | 'balance';

const SupplierLedgerTable: React.FC<SupplierLedgerTableProps> = ({ data, loading, onRowClick }) => {
    const [sortConfig, setSortConfig] = useState<{ key: SortKey; direction: 'asc' | 'desc' } | null>(null);

    const formatCurrency = (amount: number) => {
        return new Intl.NumberFormat('en-IN', { style: 'currency', currency: 'INR', minimumFractionDigits: 0 }).format(amount);
    };

    const handleSort = (key: SortKey) => {
        let direction: 'asc' | 'desc' = 'asc';
        if (sortConfig && sortConfig.key === key && sortConfig.direction === 'asc') {
            direction = 'desc';
        }
        setSortConfig({ key, direction });
    };

    const sortedTransactions = useMemo(() => {
        const sortableItems = [...data.transactions];
        if (sortConfig !== null) {
            sortableItems.sort((a, b) => {
                const aValue: any = a[sortConfig.key];
                const bValue: any = b[sortConfig.key];

                // Handle specifically for description/details if mapped differently, 
                // but checking the interface, keys match directly for most.
                // date is string ISO, works with localization string compare or Date object

                if (sortConfig.key === 'debit' || sortConfig.key === 'credit' || sortConfig.key === 'balance') {
                    // Numeric sort
                    return sortConfig.direction === 'asc' ? aValue - bValue : bValue - aValue;
                }

                // String sort
                if (aValue < bValue) {
                    return sortConfig.direction === 'asc' ? -1 : 1;
                }
                if (aValue > bValue) {
                    return sortConfig.direction === 'asc' ? 1 : -1;
                }
                return 0;
            });
        }
        return sortableItems;
    }, [data.transactions, sortConfig]);

    const SortIcon = ({ column }: { column: SortKey }) => {
        if (sortConfig?.key !== column) return <ArrowUpDown className="w-3 h-3 text-slate-300 dark:text-neutral-600 opacity-50 group-hover:opacity-100" />;
        if (sortConfig.direction === 'asc') return <ArrowUp className="w-3 h-3 text-indigo-500" />;
        return <ArrowDown className="w-3 h-3 text-indigo-500" />;
    };

    const renderHeader = (label: string, key: SortKey, align: 'left' | 'right' = 'left') => (
        <th
            className={`py-3 px-5 font-bold text-slate-400 dark:text-neutral-500 uppercase text-[11px] tracking-wider text-${align} whitespace-nowrap cursor-pointer group hover:bg-slate-100 dark:hover:bg-neutral-800 transition-colors select-none`}
            onClick={() => handleSort(key)}
        >
            <div className={`flex items-center gap-1.5 ${align === 'right' ? 'justify-end' : 'justify-start'}`}>
                {label}
                <SortIcon column={key} />
            </div>
        </th>
    );

    return (
        <div className="bg-white dark:bg-neutral-800 rounded-2xl border border-slate-100 dark:border-neutral-700 shadow-sm overflow-hidden relative">
            {/* Table Header */}
            <div className="flex items-center justify-between px-6 py-4 border-b border-slate-100 dark:border-neutral-700 print:hidden">
                <div>
                    <h3 className="text-sm font-bold text-slate-800 dark:text-neutral-100 flex items-center gap-2">
                        <Book className="w-4 h-4 text-indigo-500" /> Transaction History
                    </h3>
                    <p className="text-[10px] text-slate-400 dark:text-neutral-500 font-bold uppercase tracking-widest mt-0.5">
                        {data.transactions.length} transaction{data.transactions.length !== 1 ? 's' : ''} in period
                    </p>
                </div>
                {loading && <RefreshCw className="w-4 h-4 text-indigo-500 animate-spin" />}
            </div>

            <div className="overflow-x-auto">
                <table className="w-full text-sm">
                    <thead className="bg-slate-50/80 dark:bg-neutral-900/50">
                        <tr>
                            {renderHeader('Date', 'date')}
                            {renderHeader('Type', 'type')}
                            {renderHeader('Ref No', 'refNo')}
                            {renderHeader('Debit (₹)', 'debit', 'right')}
                            {renderHeader('Credit (₹)', 'credit', 'right')}
                            {renderHeader('Balance (₹)', 'balance', 'right')}
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-50 dark:divide-neutral-700/50">
                        {/* Opening Balance Row */}
                        <tr className="bg-slate-50/30 dark:bg-neutral-800/50">
                            <td className="py-3.5 px-5 text-slate-500 font-medium text-sm whitespace-nowrap">{new Date(data.period.start).toLocaleDateString('en-IN')}</td>
                            <td className="py-3.5 px-5 whitespace-nowrap">
                                <span className="px-2 py-0.5 rounded-md bg-slate-100 dark:bg-neutral-700 text-[10px] font-black text-slate-500 dark:text-neutral-400 uppercase tracking-wider">Opening</span>
                            </td>
                            <td className="py-3.5 px-5 italic text-slate-400 dark:text-neutral-500 text-xs whitespace-nowrap">Opening Balance Forwarded</td>
                            <td className="py-3.5 px-5 text-right text-slate-200 dark:text-neutral-700 whitespace-nowrap">—</td>
                            <td className="py-3.5 px-5 text-right text-slate-200 dark:text-neutral-700 whitespace-nowrap">—</td>
                            <td className="py-3.5 px-5 text-right font-black text-slate-600 dark:text-neutral-300 whitespace-nowrap text-sm">{formatCurrency(data.openingBalance)}</td>
                        </tr>

                        {sortedTransactions.map((t, i) => (
                            <tr
                                key={i}
                                className={`hover:bg-indigo-50/30 dark:hover:bg-indigo-500/5 transition-colors group ${onRowClick ? 'cursor-pointer' : ''}`}
                                onClick={() => onRowClick && onRowClick(t)}
                            >
                                <td className="py-3.5 px-5 text-slate-600 dark:text-neutral-400 font-medium text-sm whitespace-nowrap">{new Date(t.date).toLocaleDateString('en-IN')}</td>
                                <td className="py-3.5 px-5 whitespace-nowrap">
                                    <span className={`px-2 py-1 rounded-md text-[10px] font-black uppercase tracking-widest ${t.type === 'BILL' ? 'bg-indigo-50 text-indigo-600 dark:bg-indigo-500/10 dark:text-indigo-400 border border-indigo-100/50 dark:border-indigo-500/20' :
                                        t.type === 'PAYMENT' ? 'bg-emerald-50 text-emerald-600 dark:bg-emerald-500/10 dark:text-emerald-400 border border-emerald-100/50 dark:border-emerald-500/20' :
                                            'bg-amber-50 text-amber-600 dark:bg-amber-500/10 dark:text-amber-400 border border-amber-100/50 dark:border-amber-500/20'
                                        }`}>
                                        {t.type === 'DEBIT_NOTE' ? (t.purchaseReturnId ? 'Return' : 'D.Note') : t.type}
                                    </span>
                                </td>
                                <td className="py-3.5 px-5 whitespace-nowrap">
                                    <div className="font-bold text-slate-800 dark:text-neutral-200 text-sm group-hover:text-indigo-500 transition-colors">#{t.refNo}</div>
                                    <div className="text-xs text-slate-400 dark:text-neutral-500 mt-0.5 truncate max-w-[200px]">{t.description}</div>
                                </td>
                                <td className="py-3.5 px-5 text-right font-black text-emerald-600 dark:text-emerald-400 text-sm whitespace-nowrap">
                                    {t.debit > 0 ? formatCurrency(t.debit) : '—'}
                                </td>
                                <td className="py-3.5 px-5 text-right font-black text-rose-500 dark:text-rose-400 text-sm whitespace-nowrap">
                                    {t.credit > 0 ? formatCurrency(t.credit) : '—'}
                                </td>
                                <td className="py-3.5 px-5 text-right font-black text-slate-900 dark:text-white text-sm whitespace-nowrap">
                                    {formatCurrency(t.balance)}
                                    <span className="text-[9px] ml-1 text-slate-400 dark:text-neutral-500 font-bold">
                                        {t.balance > 0 ? 'Cr' : 'Dr'}
                                    </span>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                    <tfoot>
                        <tr className="bg-slate-50/80 dark:bg-neutral-900/50">
                            <td colSpan={3} className="py-4 px-5 text-right text-[11px] font-bold text-slate-500 dark:text-neutral-400 uppercase tracking-wider">Closing Balance</td>
                            <td className="py-4 px-5 text-right font-black text-emerald-600 dark:text-emerald-400 text-sm">{formatCurrency(data.totals.debit)}</td>
                            <td className="py-4 px-5 text-right font-black text-rose-500 dark:text-rose-400 text-sm">{formatCurrency(data.totals.credit)}</td>
                            <td className="py-4 px-5 text-right font-black text-indigo-500 text-lg">{formatCurrency(data.closingBalance)}</td>
                        </tr>
                    </tfoot>
                </table>
            </div>
        </div>
    );
};

