import React, { useState, useEffect, useRef } from 'react';
import { User, Smartphone, Mail, CreditCard, Send, RotateCcw, Crown, Zap, History, Gift, MessageSquare, Smile } from 'lucide-react';
import { Customer } from "@repo/shared";
import Customer360Modal from '@/views/People/Customers/Customer360Modal';

interface POSCustomerPanelProps {
    activeCustomer: Customer;
    customers: Customer[];
    onSetCustomer: (id: string) => void;
    onLookupOrCreateCustomer: (phone: string, name?: string) => void;
}

export const POSCustomerPanel: React.FC<POSCustomerPanelProps> = ({
    activeCustomer,
    customers,
    onSetCustomer,
    onLookupOrCreateCustomer
}) => {
    const [phoneQuery, setPhoneQuery] = useState('');
    const [nameQuery, setNameQuery] = useState('');
    const [phoneSuggestions, setPhoneSuggestions] = useState<Customer[]>([]);
    const [selectedPhoneIndex, setSelectedPhoneIndex] = useState(-1);
    const phoneInputRef = useRef<HTMLInputElement>(null);
    const nameInputRef = useRef<HTMLInputElement>(null);
    const [is360ModalOpen, setIs360ModalOpen] = useState(false);

    // Filter Suggestions and Auto-select
    useEffect(() => {
        if (phoneQuery) {
            const matches = customers.filter(c => c.phone.includes(phoneQuery) || c.name.toLowerCase().includes(phoneQuery.toLowerCase())).slice(0, 5);
            setPhoneSuggestions(matches);

            // Auto-select if exact phone match and length is 10 (standard mobile)
            if (phoneQuery.length === 10) {
                const exactMatch = customers.find(c => c.phone === phoneQuery);
                if (exactMatch) {
                    onSetCustomer(exactMatch.id);
                    setPhoneQuery('');
                    setNameQuery('');
                    setPhoneSuggestions([]);
                    // Optional: Blur input or move to next step?
                    phoneInputRef.current?.blur();
                }
            }
        } else {
            setPhoneSuggestions([]);
        }
    }, [phoneQuery, customers, onSetCustomer]);

    // Keyboard Navigation
    const handlePhoneKeyDown = (e: React.KeyboardEvent) => {
        if (e.key === 'ArrowDown') {
            e.preventDefault();
            setSelectedPhoneIndex(prev => Math.min(prev + 1, phoneSuggestions.length - 1));
        } else if (e.key === 'ArrowUp') {
            e.preventDefault();
            setSelectedPhoneIndex(prev => Math.max(prev - 1, -1));
        } else if (e.key === 'Enter') {
            e.preventDefault();
            if (selectedPhoneIndex >= 0 && phoneSuggestions[selectedPhoneIndex]) {
                const cust = phoneSuggestions[selectedPhoneIndex];
                onSetCustomer(cust.id);
                setPhoneQuery('');
                setNameQuery('');
                setPhoneSuggestions([]);
            } else if (phoneQuery.length >= 10) {
                // If no suggestion selected, move to name or submit
                if (nameInputRef.current) {
                    nameInputRef.current.focus();
                } else {
                    onLookupOrCreateCustomer(phoneQuery, nameQuery || undefined);
                    setPhoneQuery('');
                    setNameQuery('');
                    setPhoneSuggestions([]);
                }
            }
        }
    };

    const handleNameKeyDown = (e: React.KeyboardEvent) => {
        if (e.key === 'Enter') {
            e.preventDefault();
            if (phoneQuery.length >= 10) {
                onLookupOrCreateCustomer(phoneQuery, nameQuery || undefined);
                setPhoneQuery('');
                setNameQuery('');
                setPhoneSuggestions([]);
                phoneInputRef.current?.focus();
            }
        } else if (e.key === 'Escape') {
            phoneInputRef.current?.focus();
        }
    };

    // Listen for global shortcut
    useEffect(() => {
        const handleFocus = () => {
            phoneInputRef.current?.focus();
            phoneInputRef.current?.select();
        };
        const handleKeyDown = (e: KeyboardEvent) => {
            if (e.key === 'Escape') {
                setPhoneQuery('');
                setPhoneSuggestions([]);
            }
        };

        window.addEventListener('pos-focus-customer', handleFocus);
        window.addEventListener('keydown', handleKeyDown);

        return () => {
            window.removeEventListener('pos-focus-customer', handleFocus);
            window.removeEventListener('keydown', handleKeyDown);
        };
    }, []);

    return (
        <div className="bg-white dark:bg-neutral-800 p-2 border-b border-neutral-200 dark:border-neutral-700 shadow-sm shrink-0 transition-colors">


            <div className="relative mb-2 flex flex-col gap-2">
                <div className="flex gap-2">
                    <div className="relative flex-1">
                        <input
                            ref={phoneInputRef}
                            type="text"
                            placeholder="Identify Customer (Mobile No.)"
                            className={`w-full pl-8 pr-2 py-1.5 text-xs bg-neutral-50 dark:bg-neutral-900 border ${activeCustomer.id !== 'c1' ? 'border-success text-success dark:text-success/90 ring-2 ring-success/10' : 'border-primary/30 dark:border-primary/60 animate-pulse-subtle'} rounded focus:outline-none focus:ring-2 focus:ring-primary transition-all`}
                            value={phoneQuery}
                            onChange={e => setPhoneQuery(e.target.value)}
                            onKeyDown={handlePhoneKeyDown}
                        />
                        <Smartphone className={`absolute left-2 top-1.5 w-3.5 h-3.5 ${activeCustomer.id !== 'c1' ? 'text-success' : 'text-primary/70'}`} />
                    </div>
                </div>

                {phoneQuery.length >= 10 && phoneSuggestions.length === 0 && (
                    <div className="flex gap-2 animate-in fade-in slide-in-from-top-1 duration-200">
                        <div className="relative flex-1">
                            <input
                                ref={nameInputRef}
                                type="text"
                                placeholder="Customer Name (Optional)"
                                className="w-full pl-8 pr-2 py-1.5 text-xs bg-primary/5 dark:bg-neutral-900 border border-primary/20 dark:border-primary/40 rounded focus:outline-none focus:ring-2 focus:ring-primary transition-all"
                                value={nameQuery}
                                onChange={e => setNameQuery(e.target.value)}
                                onKeyDown={handleNameKeyDown}
                            />
                            <User className="absolute left-2 top-1.5 w-3.5 h-3.5 text-primary/70" />
                        </div>
                        <button
                            onClick={() => {
                                onLookupOrCreateCustomer(phoneQuery, nameQuery || undefined);
                                setPhoneQuery('');
                                setNameQuery('');
                                setPhoneSuggestions([]);
                            }}
                            className="bg-primary text-white px-3 py-1 text-[10px] font-bold rounded hover:bg-primary/90 transition-colors"
                        >
                            CREATE
                        </button>
                    </div>
                )}

                {/* Customer Suggestions */}
                {phoneSuggestions.length > 0 && (
                    <div className="absolute top-full left-0 right-0 mt-2 bg-white dark:bg-neutral-800 border border-neutral-200 dark:border-neutral-700 rounded-lg shadow-xl z-20 max-h-60 overflow-y-auto">
                        {phoneSuggestions.map((cust, idx) => (
                            <button
                                key={cust.id}
                                onClick={() => {
                                    onSetCustomer(cust.id);
                                    setPhoneQuery('');
                                    setNameQuery('');
                                    setPhoneSuggestions([]);
                                }}
                                className={`w-full text-left px-3 py-2.5 text-sm border-b border-neutral-100 dark:border-neutral-700/50 block ${idx === selectedPhoneIndex ? 'bg-primary text-white' : 'text-neutral-700 dark:text-neutral-300 hover:bg-neutral-100 dark:hover:bg-neutral-700'}`}
                            >
                                <span className="font-bold">{cust.name}</span>
                                <div className="flex items-center gap-2 mt-0.5">
                                    <span className={`text-xs ${idx === selectedPhoneIndex ? 'text-white/70' : 'text-neutral-500'}`}>{cust.phone}</span>
                                    <span className={`text-[10px] px-1 rounded font-bold ${idx === selectedPhoneIndex ? 'bg-white/20 text-white' : 'bg-neutral-100 dark:bg-neutral-700 text-neutral-600 dark:text-neutral-400'}`}>
                                        {cust.tier || 'General'}
                                    </span>
                                    <span className={`text-xs ${idx === selectedPhoneIndex ? 'text-white/70' : 'text-neutral-500'}`}>&bull; {cust.points} pts</span>
                                </div>
                            </button>
                        ))}
                    </div>
                )}
            </div>



            <div className="flex flex-col gap-2 bg-white dark:bg-slate-900 rounded-3xl p-4 border border-slate-200 dark:border-slate-800 shadow-sm relative overflow-hidden group">
                <div className="absolute top-0 right-0 w-24 h-24 bg-indigo-600/5 rounded-full -mr-12 -mt-12 group-hover:scale-150 transition-transform duration-700" />
                <div className="flex justify-between items-center relative z-10">
                    <div className="flex items-center gap-2">
                        <div className={`w-8 h-8 rounded-xl flex items-center justify-center font-black text-[10px] ${activeCustomer.id !== 'c1' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-600/20' : 'bg-slate-100 dark:bg-slate-800 text-slate-400'}`}>
                            {activeCustomer.name.charAt(0)}
                        </div>
                        <div>
                            <span
                                onClick={() => setIs360ModalOpen(true)}
                                className={`text-xs font-black truncate max-w-[120px] italic block leading-none cursor-pointer hover:underline ${activeCustomer.id !== 'c1' ? 'text-slate-900 dark:text-white' : 'text-slate-500'}`}
                            >
                                {activeCustomer.id !== 'c1' ? activeCustomer.name : 'Unidentified Customer'}
                            </span>
                            {activeCustomer.id !== 'c1' && (
                                <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest mt-0.5">{activeCustomer.phone}</p>
                            )}
                        </div>
                    </div>
                    {activeCustomer.id !== 'c1' && (
                        <button onClick={() => onSetCustomer('c1')} className="p-1.5 bg-rose-50 dark:bg-rose-900/20 text-rose-500 hover:bg-rose-500 hover:text-white rounded-lg transition-all">
                            <RotateCcw className="w-3.5 h-3.5" />
                        </button>
                    )}
                </div>

                {/* Loyalty Tier & Points */}
                {activeCustomer.id !== 'c1' && (
                    <div className="flex items-center justify-between mt-2 pt-3 border-t border-slate-100 dark:border-slate-800 relative z-10">
                        <div className="flex items-center gap-2">
                            <div className="flex flex-col">
                                <span className="text-[8px] font-black text-slate-400 uppercase tracking-widest">Customer Tier</span>
                                <div className="flex items-center gap-1.5">
                                    <Crown className="w-3 h-3 text-amber-500" />
                                    <span className="text-[10px] font-black text-slate-700 dark:text-slate-300 uppercase tracking-widest">
                                        {activeCustomer.tier || 'BRONZE'}
                                    </span>
                                </div>
                            </div>
                        </div>
                        <div className="text-right">
                            <span className="text-[8px] font-black text-indigo-600 dark:text-indigo-400 uppercase tracking-widest block">Wallet Points</span>
                            <p className="text-sm font-black text-slate-900 dark:text-white tracking-tight">{activeCustomer.points.toLocaleString()} <span className="text-[10px] text-slate-400 uppercase ml-0.5">Pts</span></p>
                        </div>
                    </div>
                )}

                {/* Points Earned Preview */}
                {activeCustomer.id !== 'c1' && (
                    <div className="mt-2 p-2 bg-indigo-50 dark:bg-indigo-900/20 rounded-xl border border-indigo-100 dark:border-indigo-900/30 flex items-center justify-between relative z-10">
                        <div className="flex items-center gap-2">
                            <Zap className="w-3.5 h-3.5 text-indigo-600 dark:text-indigo-400 animate-pulse" />
                            <span className="text-[9px] font-black text-indigo-700 dark:text-indigo-300 uppercase tracking-widest">Points for this order</span>
                        </div>
                        <p className="text-xs font-black text-indigo-600 dark:text-indigo-400">+ 184</p>
                    </div>
                )}

                {/* Engagement Quick Actions */}
                {activeCustomer.id !== 'c1' && (
                    <div className="flex items-center gap-4 pt-3 mt-1 border-t border-slate-100 dark:border-slate-800 relative z-10">
                        {/* Email Actions */}
                        <div className="flex items-center gap-1.5">
                            <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest mr-1">Reach:</span>
                            <button
                                onClick={() => alert("Invoice emailed!")}
                                className="p-2 bg-slate-50 dark:bg-slate-800 hover:bg-indigo-600 hover:text-white rounded-xl transition-all shadow-sm border border-slate-200 dark:border-slate-700"
                                title="Email Invoice"
                            >
                                <Mail className="w-3.5 h-3.5" />
                            </button>
                            <button
                                onClick={() => alert("Invoice sent via WhatsApp!")}
                                className="p-2 bg-emerald-50 dark:bg-emerald-900/10 hover:bg-emerald-600 hover:text-white rounded-xl text-emerald-600 transition-all shadow-sm border border-emerald-100 dark:border-emerald-900/30"
                                title="WhatsApp Invoice"
                            >
                                <Send className="w-3.5 h-3.5" />
                            </button>
                        </div>

                        {/* Loyalty Actions */}
                        <div className="flex items-center gap-1.5 ml-auto">
                            <button
                                onClick={() => alert("Opening Loyalty Ledger...")}
                                className="p-2 bg-amber-50 dark:bg-amber-900/10 hover:bg-amber-500 hover:text-white rounded-xl text-amber-600 transition-all shadow-sm border border-amber-100 dark:border-amber-900/30"
                                title="Loyalty History"
                            >
                                <History className="w-3.5 h-3.5" />
                            </button>
                            <button
                                onClick={() => alert("Redeeming points...")}
                                className="flex items-center gap-2 px-3 py-2 bg-indigo-600 text-white rounded-xl text-[9px] font-black uppercase tracking-widest hover:scale-105 active:scale-95 transition-all shadow-lg shadow-indigo-600/20"
                                title="Redeem Points"
                            >
                                <Gift className="w-3.5 h-3.5" /> Redeem
                            </button>
                        </div>

                        {/* CX Feedback Trigger */}
                        <div className="flex items-center gap-1.5 ml-2 border-l border-slate-100 dark:border-slate-800 pl-4">
                            <button
                                onClick={() => alert("Feedback request sent to customer!")}
                                className="p-2 bg-emerald-50 dark:bg-emerald-900/10 hover:bg-emerald-600 hover:text-white rounded-xl text-emerald-600 transition-all shadow-sm border border-emerald-100 dark:border-emerald-900/30"
                                title="Trigger Feedback Request"
                            >
                                <MessageSquare className="w-3.5 h-3.5" />
                            </button>
                            <div className="flex flex-col items-center">
                                <Smile className="w-3.5 h-3.5 text-emerald-500" />
                                <span className="text-[7px] font-black text-slate-400">92% CSAT</span>
                            </div>
                        </div>
                    </div>
                )}
            </div>

            {is360ModalOpen && activeCustomer.id !== 'c1' && (
                <Customer360Modal
                    isOpen={is360ModalOpen}
                    onClose={() => setIs360ModalOpen(false)}
                    customer={activeCustomer}
                />
            )}
        </div>
    );
};

import React from 'react';
import { CreditCard, AlertOctagon, Banknote, Smartphone, Check, Loader2, PackageCheck } from 'lucide-react';
import { TaxMode, PaymentMethod } from "@repo/shared";
import { Customer } from "@repo/shared";
import { LoyaltyConfig } from '@/entities/session/model/loyalty';

interface POSFooterProps {
    cartSubtotal: number;
    taxAmount: number;
    cartTotal: number;
    redemptionAmount: number;
    finalTotal: number;
    taxMode: TaxMode;
    paymentMethod: PaymentMethod;
    isProcessing: boolean;
    isBranchAll: boolean;
    hasMultipleBranches: boolean;
    isEmpty: boolean;
    isPreOrder: boolean;
    isRefund?: boolean;
    activeCustomer: Customer;
    loyaltyConfig?: LoyaltyConfig;
    onSetTaxMode: (mode: TaxMode) => void;
    onSetPaymentMethod: (method: PaymentMethod) => void;
    onSetRedeemedPoints: (points: number) => void;
    onSetIsPreOrder: (val: boolean) => void;
    onCheckout: () => void;
}

export const POSFooter: React.FC<POSFooterProps> = ({
    cartSubtotal,
    taxAmount,
    cartTotal,
    redemptionAmount,
    finalTotal,
    taxMode,
    paymentMethod,
    isProcessing,
    isBranchAll,
    hasMultipleBranches,
    isEmpty,
    isPreOrder,
    isRefund,
    activeCustomer,
    loyaltyConfig,
    onSetTaxMode,
    onSetPaymentMethod,
    onSetRedeemedPoints,
    onSetIsPreOrder,
    onCheckout
}) => {
    return (
        <div className="bg-white dark:bg-neutral-800 rounded-xl border border-neutral-200 dark:border-neutral-700 p-3 sm:p-4 shadow-lg flex-1 flex flex-col min-h-0 transition-colors">
            <h3 className="text-secondary font-bold uppercase text-[10px] tracking-wider mb-3 flex items-center gap-2">
                <CreditCard className="w-3.5 h-4 text-secondary/70" /> Settlement
            </h3>

            {/* Redemption Section */}
            {activeCustomer.id !== 'c1' && loyaltyConfig && (
                <div className="mb-4 p-2.5 bg-secondary/5 dark:bg-secondary/10 border border-secondary/20 rounded-lg">
                    <div className="flex justify-between items-center mb-1.5">
                        <span className="text-[10px] font-bold text-secondary uppercase">Loyalty Redemption</span>
                        <span className="text-[10px] text-neutral-500 dark:text-neutral-400">Bal: <span className="font-bold text-secondary">{activeCustomer.points} pts</span></span>
                    </div>

                    <div className="flex items-center gap-2">
                        <div className="flex-1 relative">
                            <input
                                type="number"
                                placeholder="Points to redeem"
                                className="w-full pl-2 pr-8 py-1.5 text-xs bg-white dark:bg-neutral-900 border border-secondary/30 dark:border-neutral-700 rounded focus:outline-none focus:ring-1 focus:ring-secondary font-mono"
                                min="0"
                                max={activeCustomer.points}
                                onChange={(e) => {
                                    const val = parseInt(e.target.value) || 0;
                                    const maxPercentage = loyaltyConfig.maxRedeemPercentage || 100;
                                    const maxPerBill = (cartTotal * maxPercentage) / 100;
                                    if (val > activeCustomer.points) return;
                                    if (val * (loyaltyConfig.pointValue || 1) > maxPerBill) {
                                        alert(`Maximum redemption for this bill is ₹${maxPerBill.toFixed(2)} (${maxPercentage}%).`);
                                        return;
                                    }
                                    onSetRedeemedPoints(val);
                                }}
                            />
                            <span className="absolute right-2 top-1.5 text-[10px] font-bold text-slate-400">PTS</span>
                        </div>
                        <button
                            onClick={() => {
                                const min = loyaltyConfig.minRedeemPoints || 0;
                                if (activeCustomer.points < min) {
                                    alert(`Minimum ${min} points required to redeem.`);
                                    return;
                                }
                                onSetRedeemedPoints(activeCustomer.points);
                            }}
                            className="px-2 py-1.5 text-[10px] font-bold bg-secondary text-white rounded hover:bg-secondary/90 transition-colors"
                        >
                            MAX
                        </button>
                    </div>
                    {redemptionAmount > 0 && (
                        <div className="mt-1.5 flex justify-between items-center text-[10px]">
                            <span className="text-success font-bold">Redemption Value:</span>
                            <span className="text-success font-bold">-₹{(redemptionAmount || 0).toFixed(2)}</span>
                        </div>
                    )}
                </div>
            )}

            {/* Toggles */}
            <div className="space-y-3 mb-4">
                <div className="grid grid-cols-2 gap-3">
                    <div>
                        <span className="text-[9px] font-bold text-neutral-400 mb-1 block uppercase">Tax Mode</span>
                        <div className="flex bg-neutral-100 dark:bg-neutral-900 rounded-lg p-1 border border-neutral-200 dark:border-neutral-700">
                            {(['EXCLUSIVE', 'INCLUSIVE'] as TaxMode[]).map(mode => (
                                <button
                                    key={mode}
                                    onClick={() => onSetTaxMode(mode)}
                                    className={`flex-1 text-[10px] py-1.5 rounded-md font-bold transition-all ${taxMode === mode ? 'bg-secondary text-white shadow' : 'text-neutral-500 dark:text-neutral-400 hover:text-neutral-800 dark:hover:text-neutral-200'}`}
                                >
                                    {mode === 'EXCLUSIVE' ? '+ Tax' : 'Incl.'}
                                </button>
                            ))}
                        </div>
                    </div>
                    <div>
                        <span className="text-[9px] font-bold text-neutral-400 mb-1 block uppercase">Payment</span>
                        <div className="flex bg-neutral-100 dark:bg-neutral-900 rounded-lg p-1 border border-neutral-200 dark:border-neutral-700">
                            {(['CASH', 'CARD', 'UPI'] as PaymentMethod[]).map(method => (
                                <button
                                    key={method}
                                    onClick={() => onSetPaymentMethod(method)}
                                    className={`flex-1 py-1.5 rounded-md flex flex-col items-center justify-center gap-0.5 transition-all ${paymentMethod === method ? 'bg-success text-white shadow font-bold' : 'text-neutral-500 dark:text-neutral-400 hover:text-neutral-800 dark:hover:text-neutral-200'}`}
                                    title={method}
                                >
                                    {method === 'CASH' && <Banknote className="w-4 h-4" />}
                                    {method === 'CARD' && <Smartphone className="w-4 h-4" />}
                                    {method === 'UPI' && <Smartphone className="w-4 h-4" />}
                                    <span className="text-[9px] uppercase leading-none">{method}</span>
                                </button>
                            ))}
                        </div>
                    </div>
                </div>

            </div>


            <div className="mt-auto space-y-1.5">
                <div className="flex justify-between items-center text-xs border-t border-neutral-200 dark:border-neutral-700 pt-2">
                    <span className="text-neutral-500 dark:text-neutral-400 font-medium">Subtotal</span>
                    <span className="text-neutral-800 dark:text-neutral-200 font-mono">₹{(cartSubtotal || 0).toFixed(2)}</span>
                </div>
                <div className="flex justify-between items-center text-xs">
                    <span className="text-neutral-500 dark:text-neutral-400 font-medium">Tax {taxMode === 'INCLUSIVE' ? '(Incl.)' : ''}</span>
                    <span className="text-secondary font-mono">₹{(taxAmount || 0).toFixed(2)}</span>
                </div>
                <div className="flex justify-between items-end pt-1">
                    <span className="text-neutral-700 dark:text-neutral-300 font-bold text-sm">
                        {isRefund ? 'Refund Amount' : 'Total Payable'}
                    </span>
                    <span className={`font-bold text-2xl font-mono tracking-tight ${isRefund ? 'text-error' : 'text-success'}`}>
                        ₹{Math.abs(finalTotal || 0).toFixed(2)}
                    </span>
                </div>

                <button
                    onClick={onCheckout}
                    disabled={isEmpty || isProcessing}
                    className="relative w-full py-3 bg-primary hover:bg-primary/90 disabled:bg-neutral-200 dark:disabled:bg-neutral-800 disabled:border disabled:border-neutral-300 dark:disabled:border-neutral-700 disabled:text-neutral-400 dark:disabled:text-neutral-600 disabled:cursor-not-allowed text-white font-bold rounded-xl flex items-center justify-center gap-2 transition-all shadow-lg shadow-primary/20 mt-2 text-base group"
                    title="Shortcut: Ctrl + Space"
                >
                    {isProcessing ? (
                        <>
                            <Loader2 className="w-6 h-6 animate-spin" />
                            Processing...
                        </>
                    ) : (
                        <>
                            <Check className="w-6 h-6" />
                            Finalize Bill
                            <span className="absolute right-3 top-1/2 -translate-y-1/2 text-[10px] opacity-0 group-hover:opacity-60 transition-opacity bg-black/20 px-2 py-1 rounded">Ctrl+Space</span>
                        </>
                    )}
                </button>
            </div>
        </div>
    );
};

import React from 'react';
import { Maximize2, Minimize2, Wifi, WifiOff, Plus, X } from 'lucide-react';
import { Session } from "@repo/shared";
import { useNetworkStatus } from '@/shared/lib/hooks/useNetworkStatus';

interface POSHeaderProps {
    sessions: Session[];
    activeSessionIndex: number;
    onSwitchSession: (index: number) => void;
    onAddSession: () => void;
    onRemoveSession: (index: number) => void;
    isFullScreen: boolean;
    onToggleFullScreen: () => void;
    activeCounterId?: string;
    onSwitchCounter: (counterId: string) => void;
    branches: any[];
    currentBranch: string;
}

export const POSHeader: React.FC<POSHeaderProps> = ({
    sessions,
    activeSessionIndex,
    onSwitchSession,
    onAddSession,
    onRemoveSession,
    isFullScreen,
    onToggleFullScreen,
    activeCounterId,
    onSwitchCounter,
    branches,
    currentBranch
}) => {
    const isOnline = useNetworkStatus();

    const currentBranchData = branches?.find(b => b.id === currentBranch);
    const availableCounters = currentBranchData?.counters || [];

    return (
        <div className="flex gap-4 mb-2 shrink-0 items-end">
            {/* Session Tabs */}
            <div className="hidden md:flex gap-2 flex-1">
                {sessions.map((session, index) => {
                    const totalQty = session.cart.reduce((acc, item) => acc + item.qty, 0);
                    return (
                        <div key={session.id} className="relative group flex items-end">
                            <button
                                onClick={() => onSwitchSession(index)}
                                title={`Switch to ${session.label} (Alt+${index + 1})`}
                                className={`flex flex-col items-center justify-center p-2 rounded-t-lg font-bold transition-all border-b-2 gap-1 pr-8 ${activeSessionIndex === index
                                    ? 'bg-primary text-white border-primary shadow-sm'
                                    : 'bg-white dark:bg-neutral-800 text-neutral-500 dark:text-neutral-400 border-transparent hover:bg-neutral-50 dark:hover:bg-neutral-700'
                                    }`}
                            >
                                <div className="flex items-center gap-2">
                                    <span className="text-sm">{session.label}</span>
                                    {totalQty > 0 && (
                                        <span className={`text-[10px] px-2 py-0.5 rounded-full font-mono ${activeSessionIndex === index
                                            ? 'bg-white/20 text-white'
                                            : 'bg-neutral-200 dark:bg-neutral-700 text-neutral-600 dark:text-neutral-300'
                                            }`}>
                                            {totalQty}
                                        </span>
                                    )}
                                </div>
                                <kbd className={`text-[9px] opacity-40 font-mono tracking-tighter ${activeSessionIndex === index ? 'text-white' : ''}`}>Alt+{index + 1}</kbd>
                            </button>
                            {sessions.length > 1 && (
                                <button
                                    onClick={(e) => {
                                        e.stopPropagation();
                                        onRemoveSession(index);
                                    }}
                                    className={`absolute top-1 right-1 p-0.5 rounded-md transition-colors ${activeSessionIndex === index
                                        ? 'text-primary hover:bg-white/10 hover:text-white'
                                        : 'text-neutral-400 hover:bg-neutral-100 dark:hover:bg-neutral-700 hover:text-error'
                                        }`}
                                    title="Close Tab"
                                >
                                    <X className="w-3 h-3" />
                                </button>
                            )}
                        </div>
                    )
                })}
                {sessions.length < 4 && (
                    <button
                        onClick={onAddSession}
                        className="p-3 bg-white dark:bg-neutral-800 text-neutral-400 hover:text-primary dark:hover:text-primary hover:bg-neutral-50 dark:hover:bg-neutral-700 rounded-t-lg transition-all border-b-2 border-transparent self-end"
                        title="Add New Billing Tab"
                    >
                        <Plus className="w-4 h-4" />
                    </button>
                )}
            </div>

            {/* Counter Selector */}
            {availableCounters.length > 0 && (
                <div className="hidden lg:flex flex-col gap-1">
                    <label className="text-[10px] font-bold text-neutral-400 uppercase ml-1">Terminal</label>
                    <select
                        value={activeCounterId}
                        onChange={(e) => onSwitchCounter(e.target.value)}
                        className="bg-white dark:bg-neutral-800 border-b-2 border-primary px-3 py-2 rounded-t-lg text-sm font-bold text-neutral-700 dark:text-white outline-none focus:ring-2 ring-primary/20"
                    >
                        {availableCounters.map((c: any) => (
                            <option key={c.id} value={c.id}>
                                {c.id} - {c.name}
                            </option>
                        ))}
                    </select>
                </div>
            )}

            {/* Network Status & Full Screen */}
            <div className="flex gap-2">
                <div className={`flex items-center gap-2 px-3 py-1 rounded-lg border text-xs font-bold transition-all ${isOnline
                    ? 'bg-success/10 text-success border-success/20'
                    : 'bg-warning/10 text-warning border-warning/20'
                    }`}>
                    {isOnline ? <Wifi className="w-3.5 h-3.5" /> : <WifiOff className="w-3.5 h-3.5" />}
                    {isOnline ? 'Online' : 'Offline'}
                </div>

                <button
                    onClick={onToggleFullScreen}
                    className="hidden sm:block p-2.5 bg-white dark:bg-neutral-800 text-neutral-500 dark:text-neutral-400 hover:text-primary dark:hover:text-primary hover:bg-primary/5 dark:hover:bg-neutral-700 rounded-lg shadow-sm border-b-2 border-transparent transition-all"
                    title={isFullScreen ? "Exit Full Screen" : "Enter Full Screen"}
                >
                    {isFullScreen ? <Minimize2 className="w-5 h-5" /> : <Maximize2 className="w-5 h-5" />}
                </button>
            </div>
        </div>
    );
};

import React from 'react';
import { HeldBill } from "@/entities/sales/model/posSlice";
import { Clock, User, Trash2, ArrowRightCircle, ShoppingCart } from 'lucide-react';

interface POSHeldBillsModalProps {
    isOpen: boolean;
    onClose: () => void;
    heldBills: HeldBill[];
    onResume: (id: string) => void;
    onDiscard: (id: string) => void;
}

export const POSHeldBillsModal: React.FC<POSHeldBillsModalProps> = ({
    isOpen,
    onClose,
    heldBills,
    onResume,
    onDiscard
}) => {
    if (!isOpen) return null;

    // Sort by newest first
    const sortedBills = [...heldBills].sort((a: HeldBill, b: HeldBill) =>
        new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime()
    );

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm animate-in fade-in duration-200">
            <div className="bg-white dark:bg-neutral-800 rounded-2xl shadow-2xl w-full max-w-2xl max-h-[80vh] flex flex-col overflow-hidden">

                <div className="p-4 border-b border-neutral-100 dark:border-neutral-700 flex justify-between items-center bg-neutral-50 dark:bg-neutral-900/50">
                    <h2 className="text-lg font-bold text-neutral-800 dark:text-neutral-100 flex items-center gap-2">
                        <Clock className="w-5 h-5 text-primary" />
                        Held Bills Queue
                        <span className="bg-primary/10 dark:bg-primary/30 text-primary dark:text-primary-light text-xs px-2 py-0.5 rounded-full">
                            {heldBills.length}
                        </span>
                    </h2>
                    <button
                        onClick={onClose}
                        className="text-sm font-medium text-neutral-500 hover:text-neutral-700 dark:hover:text-neutral-300"
                    >
                        Close
                    </button>
                </div>

                <div className="flex-1 overflow-y-auto p-4 space-y-3">
                    {sortedBills.length === 0 ? (
                        <div className="flex flex-col items-center justify-center h-48 text-neutral-400">
                            <Clock className="w-12 h-12 mb-2 opacity-20" />
                            <p>No held bills found.</p>
                        </div>
                    ) : (
                        sortedBills.map((bill) => (
                            <div
                                key={bill.id}
                                className="bg-white dark:bg-neutral-800 border border-neutral-200 dark:border-neutral-700 rounded-xl p-4 shadow-sm hover:shadow-md transition-shadow flex justify-between items-center group"
                            >
                                <div className="flex-1 min-w-0">
                                    <div className="flex items-center gap-2 mb-1">
                                        <span className="font-bold text-neutral-800 dark:text-neutral-100 truncate">
                                            {bill.session.customerId || 'Walk-in Customer'}
                                        </span>
                                        <span className="text-xs text-neutral-400 font-mono">
                                            {new Date(bill.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                                        </span>
                                    </div>
                                    <div className="flex items-center gap-3 text-sm text-neutral-500">
                                        <span className="flex items-center gap-1">
                                            <ShoppingCart className="w-3.5 h-3.5" />
                                            {bill.session.cart.reduce((sum: number, item: any) => sum + item.qty, 0)} Items
                                        </span>
                                        <span className="w-1 h-1 bg-neutral-300 rounded-full"></span>
                                        <span className="font-bold text-success">
                                            ₹{(bill.session.cart.reduce((sum: number, item: any) => sum + (item.price * item.qty), 0)).toFixed(2)}
                                        </span>
                                    </div>
                                    {bill.note && (
                                        <p className="text-xs text-primary mt-1 italic line-clamp-1">
                                            Note: "{bill.note}"
                                        </p>
                                    )}
                                </div>

                                <div className="flex items-center gap-2">
                                    <button
                                        onClick={() => onDiscard(bill.id)}
                                        className="p-2 text-neutral-400 hover:text-error hover:bg-error/10 dark:hover:bg-error/20 rounded-lg transition-colors"
                                        title="Discard Bill"
                                    >
                                        <Trash2 className="w-4 h-4" />
                                    </button>
                                    <button
                                        onClick={() => {
                                            onResume(bill.id);
                                            onClose();
                                        }}
                                        className="px-4 py-2 bg-primary/10 hover:bg-primary/20 dark:bg-primary/20 dark:hover:bg-primary/40 text-primary dark:text-primary-light rounded-lg font-bold text-sm flex items-center gap-2 transition-colors"
                                    >
                                        Resume
                                        <ArrowRightCircle className="w-4 h-4" />
                                    </button>
                                </div>
                            </div>
                        ))
                    )}
                </div>
            </div>
        </div>
    );
};

