export default BillItemsTable;

import React from 'react';
import { useNavigate } from 'react-router-dom';
import { FileText, Eye, CreditCard, Trash2, CheckCircle, Clock, AlertCircle } from 'lucide-react';
import { Bill } from "@/entities/finance/model/billSlice";

interface Props {
    bills: Bill[];
    isLoading: boolean;
    onMarkAsPaid: (bill: Bill) => void;
    onDelete: (id: string) => void;
}

const formatCurrency = (amount: number) =>
    new Intl.NumberFormat('en-IN', { style: 'currency', currency: 'INR', maximumFractionDigits: 0 }).format(amount);

const getStatusBadge = (status: string) => {
    const s = status?.toLowerCase();
    switch (s) {
        case 'paid':
            return (
                <span className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-[10px] font-bold bg-emerald-50 text-emerald-700 border border-emerald-200 uppercase tracking-wider">
                    <CheckCircle className="w-3.5 h-3.5" />
                    Paid
                </span>
            );
        case 'matched':
        case 'approved':
            return (
                <span className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-[10px] font-bold bg-blue-50 text-blue-700 border border-blue-200 uppercase tracking-wider">
                    <CheckCircle className="w-3.5 h-3.5" />
                    {status}
                </span>
            );
        case 'partial':
        case 'received':
            return (
                <span className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-[10px] font-bold bg-amber-50 text-amber-700 border border-amber-200 uppercase tracking-wider">
                    <Clock className="w-3.5 h-3.5" />
                    {status}
                </span>
            );
        case 'disputed':
        case 'rejected':
            return (
                <span className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-[10px] font-bold bg-red-50 text-red-700 border border-red-200 uppercase tracking-wider">
                    <AlertCircle className="w-3.5 h-3.5" />
                    {status}
                </span>
            );
        case 'hold':
            return (
                <span className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-[10px] font-bold bg-slate-100 text-slate-700 border border-slate-300 uppercase tracking-wider">
                    <Clock className="w-3.5 h-3.5" />
                    Hold
                </span>
            );
        case 'unpaid':
            // Should theoretically not happen with correct data, but kept for safety fallback
            return (
                <span className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-[10px] font-bold bg-red-50 text-red-700 border border-red-200 uppercase tracking-wider">
                    <AlertCircle className="w-3.5 h-3.5" />
                    Unpaid
                </span>
            );
        default:
            return (
                <span className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-[10px] font-bold bg-slate-50 text-slate-700 border border-slate-200 uppercase tracking-wider">
                    {status || 'Unknown'}
                </span>
            );
    }
};

const BillsTable: React.FC<Props> = ({ bills, isLoading, onMarkAsPaid, onDelete }) => {
    const navigate = useNavigate();

    return (
        <div className="bg-white dark:bg-[rgb(var(--color-card))] border dark:border-[rgb(var(--color-border))] rounded-2xl overflow-hidden shadow-sm">
            {isLoading ? (
                <div className="flex flex-col items-center justify-center py-20">
                    <div className="animate-spin rounded-full h-10 w-10 border-b-2 border-brand-600 mb-4"></div>
                    <p className="text-muted font-medium">Loading bills...</p>
                </div>
            ) : bills.length === 0 ? (
                <div className="flex flex-col items-center justify-center py-20 text-neutral-500">
                    <FileText className="w-12 h-12 mb-4 opacity-20" />
                    <p className="font-medium">No bills found</p>
                </div>
            ) : (
                <div className="overflow-x-auto">
                    <table className="w-full text-left text-sm">
                        <thead className="bg-slate-50 dark:bg-neutral-900/50 border-b dark:border-neutral-700">
                            <tr>
                                <th className="px-6 py-4 font-semibold text-secondary uppercase tracking-wider">Bill Details</th>
                                <th className="px-6 py-4 font-semibold text-secondary uppercase tracking-wider">Reference (PO/GRN)</th>
                                <th className="px-6 py-4 font-semibold text-secondary uppercase tracking-wider">Supplier</th>
                                <th className="px-6 py-4 font-semibold text-slate-500 uppercase tracking-wider text-right">Amount</th>
                                <th className="px-6 py-4 font-semibold text-slate-500 uppercase tracking-wider text-center">Status</th>
                                <th className="px-6 py-4 font-semibold text-secondary uppercase tracking-wider">Due Date</th>
                                <th className="px-6 py-4 font-semibold text-slate-500 uppercase tracking-wider text-right">Actions</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-100 dark:divide-neutral-800">
                            {bills.map((bill: any) => (
                                <tr key={bill._id} className="group hover:bg-slate-50/50 dark:hover:bg-neutral-800/50 transition-colors">
                                    <td className="px-6 py-4">
                                        <div className="flex flex-col">
                                            <span className="font-semibold text-indigo-600 dark:text-indigo-400">{bill.bill_number}</span>
                                            <span className="text-[10px] text-neutral-500">{new Date(bill.date || bill.bill_date).toLocaleDateString()}</span>
                                        </div>
                                    </td>
                                    <td className="px-6 py-4">
                                        <div className="flex flex-col gap-1">
                                            {bill.po_number && (
                                                <span className="inline-flex items-center gap-1 text-[10px] font-bold text-neutral-500 bg-neutral-100 dark:bg-neutral-800 px-2 py-0.5 rounded">
                                                    PO: {bill.po_number}
                                                </span>
                                            )}
                                            {bill.grn_number && (
                                                <span className="inline-flex items-center gap-1 text-[10px] font-bold text-primary bg-primary/5 px-2 py-0.5 rounded">
                                                    GRN: {bill.grn_number}
                                                </span>
                                            )}
                                            {!bill.po_number && !bill.grn_number && <span className="text-neutral-400 text-xs">Direct Bill</span>}
                                        </div>
                                    </td>
                                    <td className="px-6 py-4">
                                        <span className="font-medium text-slate-900 dark:text-white truncate max-w-[150px] inline-block">
                                            {bill.vendor_name || 'N/A'}
                                        </span>
                                    </td>
                                    <td className="px-6 py-4 text-right font-semibold text-slate-900 dark:text-white">
                                        {formatCurrency(bill.amount || bill.total_amount)}
                                    </td>
                                    <td className="px-6 py-4 text-center">
                                        {getStatusBadge(bill.status)}
                                    </td>
                                    <td className="px-6 py-4 text-secondary">
                                        {bill.dueDate || bill.due_date ? new Date(bill.dueDate || bill.due_date).toLocaleDateString() : '—'}
                                    </td>
                                    <td className="px-6 py-4">
                                        <div className="flex items-center justify-end gap-1 opacity-100 lg:opacity-0 group-hover:opacity-100 transition-opacity">
                                            <button
                                                onClick={() => navigate(`/purchase/bills/view/${bill._id || bill.id}`)}
                                                className="p-2 text-primary hover:bg-primary/10 rounded-lg transition-colors"
                                                title="View Details"
                                            >
                                                <Eye className="w-4 h-4" />
                                            </button>
                                            {(bill.status === 'Received' || bill.status === 'Approved' || bill.status === 'Matched' || bill.status === 'Partially Paid') && (
                                                <button
                                                    onClick={() => onMarkAsPaid(bill)}
                                                    className="p-2 text-emerald-600 hover:bg-emerald-50 dark:hover:bg-emerald-900/20 rounded-lg transition-colors"
                                                    title="Record Payment"
                                                >
                                                    <CreditCard className="w-4 h-4" />
                                                </button>
                                            )}
                                            <button
                                                onClick={() => onDelete(bill._id || bill.id)}
                                                className="p-2 text-red-600 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg transition-colors"
                                                title="Delete"
                                            >
                                                <Trash2 className="w-4 h-4" />
                                            </button>
                                        </div>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            )}
        </div>
    );
};

export default BillsTable;

import React from 'react';
import { Package, Search, CheckCircle, XCircle, Clock, AlertTriangle } from 'lucide-react';
import { GRNItem, InspectionStatus } from "@repo/shared";

interface GRNItemsTableProps {
    items?: GRNItem[];
    poNumber?: string;
    onItemChange: (index: number, field: keyof GRNItem, value: any) => void;
}

const GRNItemsTable: React.FC<GRNItemsTableProps> = ({
    items,
    poNumber,
    onItemChange
}) => {
    const getStatusIcon = (status: InspectionStatus) => {
        switch (status) {
            case 'Accepted': return <CheckCircle className="w-4 h-4 text-success" />;
            case 'Rejected': return <XCircle className="w-4 h-4 text-error" />;
            case 'Hold': return <Clock className="w-4 h-4 text-warning" />;
            case 'Partial': return <AlertTriangle className="w-4 h-4 text-warning" />;
        }
    };

    return (
        <div className="bg-white dark:bg-neutral-800 rounded-2xl border border-neutral-200 dark:border-neutral-700 shadow-sm overflow-hidden">
            <div className="p-6 border-b border-neutral-100 dark:border-neutral-700 flex justify-between items-center">
                <h3 className="text-lg font-bold flex items-center gap-2">
                    <Package className="w-5 h-5 text-primary" /> Item Inspection
                </h3>
                <div className="text-xs font-medium text-neutral-500 p-2 bg-neutral-50 dark:bg-neutral-900 rounded-lg">
                    {items?.length || 0} Items linked to {poNumber || 'PO'}
                </div>
            </div>

            <div className="overflow-x-auto">
                <table className="w-full text-left text-sm">
                    <thead className="bg-neutral-50 dark:bg-neutral-900 text-neutral-500 uppercase text-[10px] font-bold tracking-wider">
                        <tr>
                            <th className="px-6 py-4">Product Details</th>
                            <th className="px-4 py-4 text-center">Ordered</th>
                            <th className="px-4 py-4 text-center">Received</th>
                            <th className="px-4 py-4 text-center">Accepted</th>
                            <th className="px-4 py-4 text-center">Status</th>
                            <th className="px-6 py-4">Batch / Serial</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-neutral-100 dark:divide-neutral-700">
                        {!items || items.length === 0 ? (
                            <tr>
                                <td colSpan={6} className="px-6 py-12 text-center text-neutral-400">
                                    <div className="flex flex-col items-center gap-2">
                                        <Search className="w-8 h-8 opacity-20" />
                                        <p>Select a Purchase Order to load items</p>
                                    </div>
                                </td>
                            </tr>
                        ) : (
                            items.map((item, idx) => (
                                <tr key={item.id} className="hover:bg-neutral-50/50 dark:hover:bg-neutral-700/30 transition-colors">
                                    <td className="px-6 py-4">
                                        <p className="font-bold text-neutral-900 dark:text-white mb-0.5">{item.productName}</p>
                                        <p className="text-xs text-neutral-500 font-mono">{item.sku}</p>
                                    </td>
                                    <td className="px-4 py-4 text-center font-bold text-neutral-400">
                                        {item.orderedQty}
                                    </td>
                                    <td className="px-4 py-4">
                                        <input
                                            type="number"
                                            className="w-20 mx-auto px-2 py-1.5 bg-neutral-100 dark:bg-neutral-900 border border-neutral-200 dark:border-neutral-700 rounded-lg text-center font-bold focus:ring-1 focus:ring-primary outline-none"
                                            value={item.receivedQty}
                                            onChange={e => onItemChange(idx, 'receivedQty', parseInt(e.target.value) || 0)}
                                        />
                                    </td>
                                    <td className="px-4 py-4">
                                        <div className="flex flex-col gap-1 items-center">
                                            <input
                                                type="number"
                                                className={`w-20 mx-auto px-2 py-1.5 border rounded-lg text-center font-bold focus:ring-1 outline-none transition-all ${
                                                    item.acceptedQty !== item.receivedQty 
                                                    ? 'bg-rose-50 border-rose-200 text-rose-600 focus:ring-rose-500' 
                                                    : 'bg-success/5 border-success/20 text-success focus:ring-success'
                                                }`}
                                                value={item.acceptedQty}
                                                onChange={e => onItemChange(idx, 'acceptedQty', parseInt(e.target.value) || 0)}
                                            />
                                            {item.acceptedQty !== item.receivedQty && (
                                                <span className="text-[8px] font-black text-rose-500 uppercase tracking-tighter animate-pulse">Discrepancy!</span>
                                            )}
                                        </div>
                                    </td>
                                    <td className="px-4 py-4 text-center">
                                        <div className="flex flex-col items-center gap-1.5 p-2 rounded-xl bg-neutral-50 dark:bg-neutral-900 border border-neutral-100 dark:border-neutral-700/50">
                                            <div className="flex items-center gap-2">
                                                {getStatusIcon(item.inspectionStatus)}
                                                <span className={`text-[10px] font-black uppercase tracking-widest ${
                                                    item.inspectionStatus === 'Accepted' ? 'text-emerald-600' :
                                                    item.inspectionStatus === 'Rejected' ? 'text-rose-600' :
                                                    'text-amber-600'
                                                }`}>
                                                    {item.inspectionStatus}
                                                </span>
                                            </div>
                                            <div className="w-full h-1 bg-neutral-200 dark:bg-neutral-800 rounded-full overflow-hidden">
                                                <div className={`h-full rounded-full ${
                                                    item.inspectionStatus === 'Accepted' ? 'bg-emerald-500 w-full' :
                                                    item.inspectionStatus === 'Rejected' ? 'bg-rose-500 w-full' :
                                                    'bg-amber-500 w-1/2'
                                                }`} />
                                            </div>
                                        </div>
                                    </td>
                                    <td className="px-6 py-4">
                                        <div className="space-y-2">
                                            <input
                                                type="text"
                                                placeholder="Batch #"
                                                className="w-full px-3 py-1.5 bg-neutral-100 dark:bg-neutral-900 border border-neutral-200 dark:border-neutral-700 rounded-lg text-xs outline-none"
                                                value={item.batchNumber || ''}
                                                onChange={e => onItemChange(idx, 'batchNumber', e.target.value)}
                                            />
                                            <input
                                                type="text"
                                                placeholder="Expiry Date"
                                                className="w-full px-3 py-1.5 bg-neutral-100 dark:bg-neutral-900 border border-neutral-200 dark:border-neutral-700 rounded-lg text-xs outline-none"
                                                onFocus={(e) => e.target.type = 'date'}
                                                onBlur={(e) => e.target.type = 'text'}
                                                value={item.expiryDate || ''}
                                                onChange={e => onItemChange(idx, 'expiryDate', e.target.value)}
                                            />
                                        </div>
                                    </td>
                                </tr>
                            ))
                        )}
                    </tbody>
                </table>
            </div>
        </div>
    );
};

export default GRNItemsTable;

import React from 'react';
import { Search } from 'lucide-react';

interface PayablesFiltersProps {
    viewMode: 'bill-wise' | 'vendor-wise';
    onViewModeChange: (mode: 'bill-wise' | 'vendor-wise') => void;
    searchTerm: string;
    onSearchTermChange: (term: string) => void;
    statusFilter: 'All' | 'Overdue' | 'Due Soon' | 'Future';
    onStatusFilterChange: (status: 'All' | 'Overdue' | 'Due Soon' | 'Future') => void;
    vendorFilter: string;
    onVendorFilterChange: (vendorId: string) => void;
    suppliers: any[];
}

const PayablesFilters: React.FC<PayablesFiltersProps> = ({
    viewMode,
    onViewModeChange,
    searchTerm,
    onSearchTermChange,
    statusFilter,
    onStatusFilterChange,
    vendorFilter,
    onVendorFilterChange,
    suppliers
}) => {
    return (
        <div className="flex flex-wrap gap-3 items-center justify-between">
            <div className="flex gap-2 bg-slate-100 dark:bg-slate-800/50 p-1 rounded-xl">
                <button
                    onClick={() => onViewModeChange('bill-wise')}
                    className={`px-4 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all ${viewMode === 'bill-wise' ? 'bg-white dark:bg-slate-900 text-emerald-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}
                >
                    Bill-wise
                </button>
                <button
                    onClick={() => onViewModeChange('vendor-wise')}
                    className={`px-4 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all ${viewMode === 'vendor-wise' ? 'bg-white dark:bg-slate-900 text-emerald-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}
                >
                    Vendor-wise
                </button>
            </div>

            <div className="flex gap-2 flex-grow max-w-4xl">
                <div className="relative flex-grow">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                    <input
                        type="text"
                        placeholder="Search Vendor / Bill #..."
                        value={searchTerm}
                        onChange={(e) => onSearchTermChange(e.target.value)}
                        className="w-full pl-10 pr-4 py-2.5 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl text-xs font-medium focus:ring-2 focus:ring-emerald-500/20 outline-none transition-all"
                    />
                </div>

                <select
                    value={statusFilter}
                    onChange={(e) => onStatusFilterChange(e.target.value as any)}
                    className="px-4 py-2.5 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl text-xs font-medium focus:ring-2 focus:ring-emerald-500/20 outline-none"
                >
                    <option value="All">All Statuses</option>
                    <option value="Overdue">Overdue</option>
                    <option value="Due Soon">Due Soon</option>
                    <option value="Future">Future Dues</option>
                </select>

                <select
                    value={vendorFilter}
                    onChange={(e) => onVendorFilterChange(e.target.value)}
                    className="px-4 py-2.5 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl text-xs font-medium focus:ring-2 focus:ring-emerald-500/20 outline-none max-w-[200px]"
                >
                    <option value="">All Vendors</option>
                    {suppliers.map(s => <option key={s._id} value={s._id}>{s.businessName}</option>)}
                </select>
            </div>
        </div>
    );
};

export default PayablesFilters;

import { logger } from '@/shared/lib/logger';
import React, { useEffect, useState } from 'react';
import { X, CheckCircle, Search, Filter } from 'lucide-react';
import { useDispatch } from 'react-redux';
import { AppDispatch } from "@/app/store/store";
import { getAllBills } from "@/entities/finance/model/billSlice";
import { Bill } from "@/entities/finance/model/billSlice";

interface BillSelectionModalProps {
    isOpen: boolean;
    onClose: () => void;
    supplierId: string;
    onConfirm: (selectedBills: Bill[], allocations: { [billId: string]: number }, discounts: { [billId: string]: number }) => void;
    initialAllocations?: { [billId: string]: number };
    initialDiscounts?: { [billId: string]: number };
}

const BillSelectionModal: React.FC<BillSelectionModalProps> = ({
    isOpen,
    onClose,
    supplierId,
    onConfirm,
    initialAllocations = {},
    initialDiscounts = {}
}) => {
    const dispatch = useDispatch<AppDispatch>();
    const [loading, setLoading] = useState(false);
    const [bills, setBills] = useState<Bill[]>([]);

    // Selection state
    const [selectedBillIds, setSelectedBillIds] = useState<Set<string>>(new Set(Object.keys(initialAllocations)));
    const [allocations, setAllocations] = useState<{ [billId: string]: number }>(initialAllocations);
    const [discounts, setDiscounts] = useState<{ [billId: string]: number }>(initialDiscounts);

    useEffect(() => {
        if (isOpen && supplierId) {
            fetchBills();
        }
    }, [isOpen, supplierId]);

    const fetchBills = async () => {
        setLoading(true);
        try {
            // Fetch unpaid and partial bills
            const result = await dispatch(getAllBills({
                supplier: supplierId,
                paymentStatus: 'unpaid,partial'
            })).unwrap();

            // Also fetch paid bills if they have allocations (in case of editing), but usually settlement is for unpaid.
            // For now, just show unpaid/partial.
            setBills(result);
        } catch (error) {
            logger.error("Failed to fetch bills", error);
        } finally {
            setLoading(false);
        }
    };

    const toggleBill = (bill: Bill) => {
        const newSelected = new Set(selectedBillIds);
        const billId = bill._id || '';

        if (newSelected.has(billId)) {
            newSelected.delete(billId);
            // Optional: clear allocation? Better to keep it if they re-select.
        } else {
            newSelected.add(billId);
            // Default allocation to full due amount if not set
            if (!allocations[billId]) {
                const due = (bill.amount || 0) - (bill.paidAmount || 0) - (bill.discountReceived || 0);
                setAllocations(prev => ({ ...prev, [billId]: due }));
            }
        }
        setSelectedBillIds(newSelected);
    };

    const handleAllocationChange = (billId: string, value: number) => {
        setAllocations(prev => ({ ...prev, [billId]: value }));
    };

    const handleDiscountChange = (billId: string, value: number) => {
        setDiscounts(prev => ({ ...prev, [billId]: value }));
    };

    const handleConfirm = () => {
        const selectedBills = bills.filter(b => selectedBillIds.has(b._id || ''));
        // Filter allocations/discounts to only selected bills
        const finalAllocations: { [id: string]: number } = {};
        const finalDiscounts: { [id: string]: number } = {};

        selectedBills.forEach(b => {
            const bid = b._id || '';
            finalAllocations[bid] = allocations[bid] || 0;
            finalDiscounts[bid] = discounts[bid] || 0;
        });

        onConfirm(selectedBills, finalAllocations, finalDiscounts);
        onClose();
    };

    if (!isOpen) return null;

    const totalSelectedDue = bills
        .filter(b => selectedBillIds.has(b._id || ''))
        .reduce((sum, b) => sum + ((b.amount || 0) - (b.paidAmount || 0) - (b.discountReceived || 0)), 0);

    const totalAllocated = Object.entries(allocations)
        .filter(([id]) => selectedBillIds.has(id))
        .reduce((sum, [_, val]) => sum + val, 0);

    return (
        <div className="fixed inset-0 bg-black/40 backdrop-blur-sm z-50 flex items-center justify-center p-4">
            <div className="bg-white dark:bg-slate-800 rounded-2xl w-full max-w-4xl shadow-2xl border dark:border-slate-700 flex flex-col max-h-[90vh]">
                <div className="p-6 border-b border-slate-200 dark:border-slate-700 flex justify-between items-center bg-slate-50 dark:bg-slate-800/50 rounded-t-2xl">
                    <div>
                        <h2 className="text-xl font-bold mb-1 text-slate-800 dark:text-white">Select Bills for Settlement</h2>
                        <p className="text-sm text-slate-500">Select unpaid invoices to settle</p>
                    </div>
                    <button onClick={onClose} className="p-2 hover:bg-slate-200 dark:hover:bg-slate-700 rounded-full transition-colors">
                        <X className="w-5 h-5 text-slate-500" />
                    </button>
                </div>

                <div className="flex-1 overflow-y-auto p-6">
                    {loading ? (
                        <div className="flex items-center justify-center h-40">
                            <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-indigo-600"></div>
                        </div>
                    ) : bills.length === 0 ? (
                        <div className="text-center py-12 text-slate-400">
                            <CheckCircle size={48} className="mx-auto mb-3 opacity-20" />
                            <p>No unpaid bills found for this supplier.</p>
                        </div>
                    ) : (
                        <table className="w-full text-left text-sm border-separate border-spacing-0">
                            <thead className="bg-slate-50 dark:bg-slate-700/50 text-slate-500 sticky top-0 z-10">
                                <tr>
                                    <th className="px-4 py-3 rounded-l-lg border-b border-slate-200 dark:border-slate-700 w-12">
                                        <input
                                            type="checkbox"
                                            className="rounded border-slate-300"
                                            checked={bills.length > 0 && selectedBillIds.size === bills.length}
                                            onChange={() => {
                                                if (selectedBillIds.size === bills.length) {
                                                    setSelectedBillIds(new Set());
                                                } else {
                                                    const allIds = new Set(bills.map(b => b._id || ''));
                                                    setSelectedBillIds(allIds);
                                                    // Auto allocate all
                                                    const newAlloc: any = {};
                                                    bills.forEach(b => {
                                                        const due = (b.amount || 0) - (b.paidAmount || 0) - (b.discountReceived || 0);
                                                        newAlloc[b._id || ''] = due;
                                                    });
                                                    setAllocations(newAlloc);
                                                }
                                            }}
                                        />
                                    </th>
                                    <th className="px-4 py-3 border-b border-slate-200 dark:border-slate-700">Bill Details</th>
                                    <th className="px-4 py-3 border-b border-slate-200 dark:border-slate-700 text-right">Bill Amount</th>
                                    <th className="px-4 py-3 border-b border-slate-200 dark:border-slate-700 text-right">Balance Due</th>
                                    <th className="px-4 py-3 border-b border-slate-200 dark:border-slate-700 w-40">Payment Amt</th>
                                    <th className="px-4 py-3 rounded-r-lg border-b border-slate-200 dark:border-slate-700 w-32">Discount</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-slate-100 dark:divide-slate-700">
                                {bills.map(bill => {
                                    const billId = bill._id || '';
                                    const isSelected = selectedBillIds.has(billId);
                                    const due = (bill.amount || 0) - (bill.paidAmount || 0) - (bill.discountReceived || 0);

                                    return (
                                        <tr key={billId} className={`hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors ${isSelected ? 'bg-indigo-50/30 dark:bg-indigo-900/10' : ''}`}>
                                            <td className="px-4 py-3">
                                                <input
                                                    type="checkbox"
                                                    checked={isSelected}
                                                    onChange={() => toggleBill(bill)}
                                                    className="rounded border-slate-300 text-indigo-600 focus:ring-indigo-500"
                                                />
                                            </td>
                                            <td className="px-4 py-3">
                                                <div className="font-medium text-slate-800 dark:text-slate-200">{bill.billNo}</div>
                                                <div className="text-xs text-slate-500">{new Date(bill.date).toLocaleDateString()}</div>
                                            </td>
                                            <td className="px-4 py-3 text-right text-slate-600">₹{bill.amount?.toLocaleString()}</td>
                                            <td className="px-4 py-3 text-right font-medium text-slate-800 dark:text-slate-200">₹{due.toLocaleString()}</td>
                                            <td className="px-4 py-3">
                                                <input
                                                    type="number"
                                                    disabled={!isSelected}
                                                    value={allocations[billId] || ''}
                                                    onChange={(e) => handleAllocationChange(billId, parseFloat(e.target.value))}
                                                    className="w-full px-3 py-1.5 border border-slate-300 dark:border-slate-600 rounded-lg text-right focus:border-indigo-500 outline-none disabled:opacity-50 disabled:bg-slate-100 dark:disabled:bg-slate-900 transition-all font-medium"
                                                    placeholder="0.00"
                                                />
                                            </td>
                                            <td className="px-4 py-3">
                                                <input
                                                    type="number"
                                                    disabled={!isSelected}
                                                    value={discounts[billId] || ''}
                                                    onChange={(e) => handleDiscountChange(billId, parseFloat(e.target.value))}
                                                    className="w-full px-3 py-1.5 border border-slate-300 dark:border-slate-600 rounded-lg text-right text-sm focus:border-indigo-500 outline-none disabled:opacity-50 disabled:bg-slate-100 dark:disabled:bg-slate-900 transition-all"
                                                    placeholder="0"
                                                />
                                            </td>
                                        </tr>
                                    );
                                })}
                            </tbody>
                        </table>
                    )}
                </div>

                <div className="p-6 border-t border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-800/50 rounded-b-2xl flex justify-between items-center">
                    <div className="text-sm">
                        <span className="text-slate-500">Selected Due: </span>
                        <strong className="text-slate-800 dark:text-white text-lg ml-1">₹{totalSelectedDue.toLocaleString()}</strong>
                    </div>

                    <div className="flex items-center gap-4">
                        <div className="text-right mr-4">
                            <div className="text-sm text-slate-500">Total To Pay</div>
                            <div className="text-xl font-bold text-indigo-600 dark:text-indigo-400">₹{totalAllocated.toLocaleString()}</div>
                        </div>

                        <button
                            onClick={onClose}
                            className="px-5 py-2.5 text-slate-600 font-medium hover:bg-white dark:hover:bg-slate-700 rounded-xl transition-all border border-transparent hover:border-slate-200 dark:hover:border-slate-600"
                        >
                            Cancel
                        </button>
                        <button
                            onClick={handleConfirm}
                            disabled={selectedBillIds.size === 0}
                            className="px-8 py-2.5 bg-indigo-600 text-white font-bold rounded-xl shadow-lg shadow-indigo-200 dark:shadow-none hover:bg-indigo-700 active:scale-95 transition-all disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-2"
                        >
                            <CheckCircle size={18} />
                            Confim Selection
                        </button>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default BillSelectionModal;

import { logger } from '@/shared/lib/logger';

import React, { useState } from 'react';
import { X, CheckCircle, FileText } from 'lucide-react';
import { PurchaseOrder } from "@repo/shared";
import { useDispatch } from 'react-redux';
// We assume we can import these. If not, we might need to verify paths.
// Based on Bills.tsx imports:
import { createBill } from "@/entities/finance/model/billSlice";
import { AppDispatch } from "@/app/store/store";
import { toast } from 'react-toastify';

interface CreateBillModalProps {
    isOpen: boolean;
    onClose: () => void;
    order: PurchaseOrder;
    onBillCreated: () => void;
}

const CreateBillModal: React.FC<CreateBillModalProps> = ({ isOpen, onClose, order, onBillCreated }) => {
    const dispatch = useDispatch<AppDispatch>();
    const [loading, setLoading] = useState(false);

    // Initial State pre-filled from Order
    const [formData, setFormData] = useState({
        date: new Date().toISOString().split('T')[0],
        supplier: order.vendor_id || '', // Provided order has vendor_id
        amount: order.total_amount,
        dueDate: '',
        status: 'unpaid',
        description: `Bill for PO #${order.po_number}`,
        paymentMethod: 'cash',
        paidAmount: 0,
        bankAccount: ''
    });

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        try {
            setLoading(true);
            await dispatch(createBill(formData)).unwrap(); // Assuming unwrap is available if using createAsyncThunk
            toast.success('Bill created successfully');
            onBillCreated();
            onClose();
        } catch (error: any) {
            logger.error("Failed to create bill:", error);
            toast.error(error.message || 'Failed to create bill');
        } finally {
            setLoading(false);
        }
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 bg-black/40 backdrop-blur-sm z-50 flex items-center justify-center p-4">
            <div className="bg-white dark:bg-neutral-800 rounded-2xl w-full max-w-lg shadow-2xl border dark:border-neutral-700 flex flex-col">
                <div className="p-6 border-b border-neutral-200 dark:border-neutral-700 flex justify-between items-center">
                    <div>
                        <h2 className="text-xl font-bold mb-1">Create Bill</h2>
                        <p className="text-sm text-neutral-500">For PO #{order.po_number}</p>
                    </div>
                    <button onClick={onClose} className="p-2 hover:bg-neutral-100 dark:hover:bg-neutral-700 rounded-full">
                        <X className="w-5 h-5" />
                    </button>
                </div>

                <form onSubmit={handleSubmit} className="p-6 space-y-4">
                    <div className="grid grid-cols-2 gap-4">
                        <div>
                            <label className="block text-sm font-medium text-neutral-700 dark:text-neutral-300 mb-1">Bill Date</label>
                            <input
                                type="date"
                                required
                                className="w-full px-4 py-2 bg-neutral-100 dark:bg-neutral-900 border border-neutral-200 dark:border-neutral-700 rounded-xl text-sm"
                                value={formData.date}
                                onChange={e => setFormData({ ...formData, date: e.target.value })}
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-neutral-700 dark:text-neutral-300 mb-1">Due Date</label>
                            <input
                                type="date"
                                className="w-full px-4 py-2 bg-neutral-100 dark:bg-neutral-900 border border-neutral-200 dark:border-neutral-700 rounded-xl text-sm"
                                value={formData.dueDate}
                                onChange={e => setFormData({ ...formData, dueDate: e.target.value })}
                            />
                        </div>
                    </div>

                    <div>
                        <label className="block text-sm font-medium text-neutral-700 dark:text-neutral-300 mb-1">Amount</label>
                        <div className="relative">
                            <span className="absolute left-4 top-2 text-neutral-500">₹</span>
                            <input
                                type="number"
                                required
                                disabled // Usually bill matches PO, but maybe editable? Let's keep editable but prefilled
                                className="w-full pl-8 pr-4 py-2 bg-neutral-100 dark:bg-neutral-900 border border-neutral-200 dark:border-neutral-700 rounded-xl text-sm"
                                value={formData.amount}
                                onChange={e => setFormData({ ...formData, amount: parseFloat(e.target.value) || 0 })}
                            />
                        </div>
                    </div>

                    <div>
                        <label className="block text-sm font-medium text-neutral-700 dark:text-neutral-300 mb-1">Description</label>
                        <textarea
                            className="w-full px-4 py-2 bg-neutral-100 dark:bg-neutral-900 border border-neutral-200 dark:border-neutral-700 rounded-xl text-sm"
                            rows={3}
                            value={formData.description}
                            onChange={e => setFormData({ ...formData, description: e.target.value })}
                        />
                    </div>

                    <div className="pt-4 flex justify-end gap-3">
                        <button
                            type="button"
                            onClick={onClose}
                            className="px-6 py-2.5 border border-neutral-200 dark:border-neutral-700 rounded-xl font-medium hover:bg-neutral-50 dark:hover:bg-neutral-700 transition-colors"
                        >
                            Cancel
                        </button>
                        <button
                            type="submit"
                            disabled={loading}
                            className="px-6 py-2.5 bg-purple-600 text-white rounded-xl font-bold shadow-lg shadow-purple-600/25 hover:bg-purple-700 transition-all flex items-center gap-2"
                        >
                            {loading ? 'Creating...' : <><FileText className="w-4 h-4" /> Create Bill</>}
                        </button>
                    </div>
                </form>
            </div>
        </div>
    );
};

export default CreateBillModal;

import React, { useState } from 'react';
import { XCircle, Plus, Trash2, Percent } from 'lucide-react';
import { debitNoteService, DebitNote } from "@/entities/finance/api/debitNoteService";
import { toast } from 'react-toastify';
import { useDispatch } from 'react-redux';
import { AppDispatch } from "@/app/store/store";

interface CreateDebitNoteModalProps {
    isOpen: boolean;
    onClose: () => void;
    onSuccess: () => void;
    vendors: any[];
    bills: any[];
    grns: any[];
    REASON_LABELS: Record<string, string>;
}

const CreateDebitNoteModal: React.FC<CreateDebitNoteModalProps> = ({
    isOpen, onClose, onSuccess, vendors, bills, grns, REASON_LABELS
}) => {
    const [newNote, setNewNote] = useState<Partial<DebitNote>>({
        reason: 'OTHER',
        items: [{ name: '', qty: 1, amount: 0, taxRate: 0, taxAmount: 0 }],
        subTotal: 0,
        taxAmount: 0,
        totalAmount: 0,
        notes: '',
        status: 'DRAFT'
    });

    if (!isOpen) return null;

    const handleCreateNote = async (e: React.FormEvent) => {
        e.preventDefault();

        if (!newNote.vendorId) {
            toast.error('Please select a vendor');
            return;
        }

        const selectedVendor = vendors.find((v: any) => v._id === newNote.vendorId);
        const finalNote = {
            ...newNote,
            vendorName: selectedVendor?.name || '',
            totalAmount: newNote.items?.reduce((sum, item) => sum + item.amount, 0) || 0
        };

        try {
            await debitNoteService.createDebitNote(finalNote);
            toast.success('Debit note created successfully');
            onSuccess();
            setNewNote({
                reason: 'OTHER',
                items: [{ name: '', qty: 1, amount: 0 }],
                notes: ''
            });
        } catch (error: any) {
            toast.error(error.response?.data?.message || 'Failed to create debit note');
        }
    };

    const calculateTotals = (items: any[]) => {
        const subTotal = items.reduce((sum, item) => sum + (item.qty * item.amount), 0);
        const taxAmount = items.reduce((sum, item) => sum + (item.taxAmount || 0), 0);
        const totalAmount = subTotal + taxAmount;
        return { subTotal, taxAmount, totalAmount };
    };

    const addItem = () => {
        const updatedItems = [...(newNote.items || []), { name: '', qty: 1, amount: 0, taxRate: 0, taxAmount: 0 }];
        const totals = calculateTotals(updatedItems);
        setNewNote({
            ...newNote,
            items: updatedItems,
            ...totals
        });
    };

    const removeItem = (index: number) => {
        const items = [...(newNote.items || [])];
        items.splice(index, 1);
        const totals = calculateTotals(items);
        setNewNote({ ...newNote, items, ...totals });
    };

    const updateItem = (index: number, field: string, value: any) => {
        const items = [...(newNote.items || [])];
        const item = { ...items[index], [field]: value };

        if (field === 'qty' || field === 'amount' || field === 'taxRate') {
            const qty = field === 'qty' ? value : item.qty;
            const amount = field === 'amount' ? value : item.amount;
            const taxRate = field === 'taxRate' ? value : (item.taxRate || 0);
            item.taxAmount = (qty * amount * taxRate) / 100;
        }

        items[index] = item;
        const totals = calculateTotals(items);
        setNewNote({ ...newNote, items, ...totals });
    };

    return (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
            <div className="bg-white dark:bg-neutral-800 rounded-2xl w-full max-w-2xl max-h-[90vh] overflow-hidden flex flex-col shadow-2xl animate-fade-in">
                <div className="p-6 border-b border-neutral-100 dark:border-neutral-700 flex justify-between items-center">
                    <div>
                        <h2 className="text-xl font-black text-neutral-900 dark:text-white uppercase tracking-tight">Create Debit Note</h2>
                        <p className="text-xs text-neutral-500 font-medium">Issue a claim or return to a supplier</p>
                    </div>
                    <button
                        onClick={onClose}
                        className="p-2 hover:bg-neutral-100 dark:hover:bg-neutral-700 rounded-xl transition-colors"
                    >
                        <XCircle className="w-6 h-6 text-neutral-400" />
                    </button>
                </div>

                <form onSubmit={handleCreateNote} className="flex-1 overflow-y-auto p-6 space-y-6">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <div>
                            <label className="text-xs font-black text-neutral-400 uppercase tracking-widest mb-2 block">Vendor / Supplier</label>
                            <select
                                className="w-full px-4 py-2 bg-neutral-50 dark:bg-neutral-700 border border-neutral-200 dark:border-neutral-600 rounded-xl text-neutral-900 dark:text-white font-medium focus:ring-2 focus:ring-error/20"
                                value={newNote.vendorId}
                                onChange={(e) => setNewNote({ ...newNote, vendorId: e.target.value })}
                                required
                            >
                                <option value="">Select Vendor</option>
                                {vendors.map((v: any) => (
                                    <option key={v._id} value={v._id}>{v.name}</option>
                                ))}
                            </select>
                        </div>

                        <div>
                            <label className="text-xs font-black text-neutral-400 uppercase tracking-widest mb-2 block">Reason</label>
                            <select
                                className="w-full px-4 py-2 bg-neutral-50 dark:bg-neutral-700 border border-neutral-200 dark:border-neutral-600 rounded-xl text-neutral-900 dark:text-white font-medium focus:ring-2 focus:ring-error/20"
                                value={newNote.reason}
                                onChange={(e) => setNewNote({ ...newNote, reason: e.target.value as any })}
                                required
                            >
                                {Object.entries(REASON_LABELS).map(([val, label]) => (
                                    <option key={val} value={val}>{label}</option>
                                ))}
                            </select>
                        </div>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <div>
                            <label className="text-xs font-black text-neutral-400 uppercase tracking-widest mb-2 block">Link to Bill</label>
                            <select
                                className="w-full px-4 py-2 bg-neutral-50 dark:bg-neutral-700 border border-neutral-200 dark:border-neutral-600 rounded-xl text-neutral-900 dark:text-white font-medium focus:ring-2 focus:ring-error/20"
                                value={newNote.originalBillId}
                                onChange={(e) => {
                                    const bill = bills.find(b => b._id === e.target.value);
                                    setNewNote({
                                        ...newNote,
                                        originalBillId: e.target.value,
                                        originalBillNumber: bill?.bill_number || ''
                                    });
                                }}
                            >
                                <option value="">Direct / No Bill Link</option>
                                {bills.filter(b => b.vendor_id === newNote.vendorId || !newNote.vendorId).map((b: any) => (
                                    <option key={b._id} value={b._id}>{b.bill_number} (₹{(b.amount || b.total_amount).toLocaleString()})</option>
                                ))}
                            </select>
                        </div>

                        <div>
                            <label className="text-xs font-black text-neutral-400 uppercase tracking-widest mb-2 block">Link to GRN</label>
                            <select
                                className="w-full px-4 py-2 bg-neutral-50 dark:bg-neutral-700 border border-neutral-200 dark:border-neutral-600 rounded-xl text-neutral-900 dark:text-white font-medium focus:ring-2 focus:ring-error/20"
                                value={newNote.originalGrnId}
                                onChange={(e) => {
                                    const grn = grns.find(g => g.id === e.target.value);
                                    setNewNote({
                                        ...newNote,
                                        originalGrnId: e.target.value,
                                        originalGrnNumber: grn?.grnNumber || grn?.id || ''
                                    });
                                }}
                            >
                                <option value="">No GRN Link</option>
                                {grns.filter(g => g.vendorName === vendors.find(v => v._id === newNote.vendorId)?.name || !newNote.vendorId).map((g: any) => (
