import { logger } from '@/shared/lib/logger';
import { useState, useEffect, useMemo, useCallback } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { toast } from 'react-toastify';
import api from "@/shared/api/api";
import { getAllBills, createBill, updateBill, deleteBill, reset, Bill } from "@/entities/finance/model/billSlice";
import { getAllSuppliers } from "@/entities/contact/model/supplierSlice";
import { RootState, AppDispatch } from "@/app/store/store";

export const useBills = () => {
    const dispatch = useDispatch<AppDispatch>();
    const { bills, isLoading, isError, message } = useSelector((state: RootState) => state.bill);
    const { suppliers } = useSelector((state: RootState) => state.suppliers);

    const [searchTerm, setSearchTerm] = useState('');
    const [statusFilter, setStatusFilter] = useState('all');
    const [showForm, setShowForm] = useState(false);
    const [editingBill, setEditingBill] = useState<Bill | null>(null);
    const [deleteConfirm, setDeleteConfirm] = useState<string | null>(null);
    const [bankAccounts, setBankAccounts] = useState<any[]>([]);
    const [paymentModal, setPaymentModal] = useState<{ isOpen: boolean; bill: Bill | null }>({
        isOpen: false,
        bill: null
    });

    useEffect(() => {
        dispatch(getAllBills({}));
        dispatch(getAllSuppliers());
        fetchBankAccounts();
        return () => {
            dispatch(reset());
        };
    }, [dispatch]);

    const fetchBankAccounts = async () => {
        try {
            const userDataString = localStorage.getItem('user');
            if (!userDataString) return;
            const userData = JSON.parse(userDataString);
            const token = userData?.token;
            const response = await api.get(
                `/api/cashbank/accounts`,
                { headers: { Authorization: `Bearer ${token}` } }
            );
            setBankAccounts(response.data);
        } catch (error) {
            logger.error('Error fetching bank accounts:', error);
        }
    };

    const handleMarkAsPaid = useCallback((bill: Bill) => {
        setPaymentModal({
            isOpen: true,
            bill
        });
    }, []);

    const handlePaymentSubmit = useCallback(async (paymentData: any) => {
        if (!paymentModal.bill) return;
        try {
            const userDataString = localStorage.getItem('user');
            if (!userDataString) return;
            const userData = JSON.parse(userDataString);
            const token = userData?.token;
            await api.put(
                `/api/bills/${paymentModal.bill._id}/payment`,
                paymentData,
                { headers: { Authorization: `Bearer ${token}` } }
            );

            toast.success('Payment recorded successfully');
            setPaymentModal({ isOpen: false, bill: null });
            dispatch(getAllBills({}));
        } catch (error: any) {
            toast.error(error.response?.data?.message || 'Payment failed');
        }
    }, [paymentModal.bill, dispatch]);

    const handleSaveBill = useCallback(async (billData: any) => {
        try {
            if (editingBill) {
                await dispatch(updateBill({ id: editingBill?._id || editingBill?.id || '', billData }));
            } else {
                await dispatch(createBill(billData));
            }
            setShowForm(false);
            setEditingBill(null);
            dispatch(getAllBills({}));
        } catch (error) {
            logger.error('Error saving bill:', error);
        }
    }, [editingBill, dispatch]);

    const handleEdit = useCallback((bill: Bill) => {
        setEditingBill(bill);
        setShowForm(true);
    }, []);

    const handleDelete = useCallback(async (id: string) => {
        try {
            await dispatch(deleteBill(id));
            setDeleteConfirm(null);
        } catch (error) {
            logger.error('Error deleting bill:', error);
        }
    }, [dispatch]);

    const filteredBills = useMemo(() => {
        return bills.filter((bill: Bill) => {
            const matchesSearch = (bill.bill_number || '').toLowerCase().includes(searchTerm.toLowerCase()) ||
                (bill.vendor_name || '').toLowerCase().includes(searchTerm.toLowerCase()) ||
                bill.amount?.toString().includes(searchTerm);
            const matchesStatus = statusFilter === 'all' || bill.status === statusFilter;
            return matchesSearch && matchesStatus;
        });
    }, [bills, searchTerm, statusFilter]);

    const totals = useMemo(() => {
        const totalBillsAmount = bills.reduce((sum: number, bill: Bill) => sum + (bill.amount || 0), 0);
        const totalPaidAmount = bills.filter((bill: Bill) => bill.status === 'Paid').reduce((sum: number, bill: Bill) => sum + (bill.amount || 0), 0);
        const totalOutstanding = bills.filter((bill: Bill) => bill.status !== 'Paid' && bill.status !== 'Rejected').reduce((sum: number, bill: Bill) => sum + (bill.amount || 0), 0);

        return {
            totalBillsAmount,
            totalPaidAmount,
            totalOutstanding
        };
    }, [bills]);

    return {
        bills,
        filteredBills,
        isLoading,
        searchTerm,
        setSearchTerm,
        statusFilter,
        setStatusFilter,
        showForm,
        setShowForm,
        editingBill,
        setEditingBill,
        deleteConfirm,
        setDeleteConfirm,
        paymentModal,
        setPaymentModal,
        handleMarkAsPaid,
        handlePaymentSubmit,
        handleSaveBill,
        handleEdit,
        handleDelete,
        totals
    };
};

import { useState, useMemo } from 'react';
import { useSelector } from 'react-redux';
import { RootState } from "@/app/store/store";
import { useBranchResolver } from "@/hooks/useBranchResolver";

export interface GoodsReceivedNote {
    id: string;
    grnNumber?: string;
    poId: string;
    poNumber: string;
    vendorName: string;
    receivedDate: string;
    expectedItems: number;
    receivedItems: number;
    status: 'COMPLETE' | 'PARTIAL' | 'PENDING';
    branchId: string;
    inspector?: string;
    notes?: string;
}

export const useGRNData = () => {
    const { orders, grns } = useSelector((state: RootState) => state.purchase);
    const { currentSector, currentBranch, user } = useSelector((state: RootState) => state.auth);

    const [searchTerm, setSearchTerm] = useState('');
    const [statusFilter, setStatusFilter] = useState<string>('ALL');
    const [dateFrom, setDateFrom] = useState('');
    const [dateTo, setDateTo] = useState('');

    // Use real GRNs from Redux, fall back to PO-derived ones if empty (for demo/initial state)
    const grnRecords = useMemo(() => {
        if (grns && grns.length > 0) {
            return grns.map(grn => {
                const totalItems = grn.items.reduce((sum, item) => sum + item.orderedQty, 0);
                const receivedItems = grn.items.reduce((sum, item) => sum + item.receivedQty, 0);

                // Map GRNStatus to local status
                let status: 'COMPLETE' | 'PARTIAL' | 'PENDING' = 'PENDING';
                if (grn.status === 'Accepted') status = 'COMPLETE';
                else if (grn.status === 'Partial') status = 'PARTIAL';
                else if (grn.status === 'Rejected') status = 'PENDING';

                return {
                    id: grn.id,
                    grnNumber: grn.grnNumber,
                    poId: grn.poId,
                    poNumber: grn.poNumber,
                    vendorName: grn.vendorName,
                    receivedDate: grn.receivedDate,
                    expectedItems: totalItems,
                    receivedItems: receivedItems,
                    status: status,
                    branchId: grn.branch_id || currentBranch || 'Main',
                    inspector: grn.created_by,
                    notes: grn.notes
                } as GoodsReceivedNote;
            });
        }

        return orders
            .filter(o => o.status === 'Approved' || o.status === 'Partial Receipt' || o.status === 'Fully Received')
            .map(order => {
                const totalItems = order.items.reduce((sum, item) => sum + item.quantity, 0);
                const receivedItems = order.items.reduce((sum, item) => sum + (item.received_quantity || 0), 0);

                let status: 'COMPLETE' | 'PARTIAL' | 'PENDING' = 'PARTIAL';
                if (receivedItems === 0) status = 'PENDING';
                else if (receivedItems >= totalItems) status = 'COMPLETE';

                return {
                    id: `GRN-${order.id.substring(0, 6)}`,
                    grnNumber: `GRN-${order.id.substring(0, 6)}`,
                    poId: order.id,
                    poNumber: order.po_number,
                    vendorName: order.vendor_name,
                    receivedDate: order.po_date,
                    expectedItems: totalItems,
                    receivedItems: receivedItems,
                    status,
                    branchId: order.branch_id || currentBranch || 'Main',
                    inspector: user?.name || 'System'
                } as GoodsReceivedNote;
            });
    }, [orders, grns, currentSector, currentBranch, user]);

    // Apply filters
    const filteredRecords = useMemo(() => {
        return grnRecords.filter((grn) => {
            if (searchTerm) {
                const search = searchTerm.toLowerCase();
                if (!grn.vendorName.toLowerCase().includes(search) &&
                    !grn.id.toLowerCase().includes(search) &&
                    !grn.poNumber.toLowerCase().includes(search)) {
                    return false;
                }
            }
            if (statusFilter !== 'ALL' && grn.status !== statusFilter) return false;
            if (dateFrom && new Date(grn.receivedDate) < new Date(dateFrom)) return false;
            if (dateTo) {
                const nextDay = new Date(dateTo);
                nextDay.setDate(nextDay.getDate() + 1);
                if (new Date(grn.receivedDate) >= nextDay) return false;
            }
            return true;
        });
    }, [grnRecords, searchTerm, statusFilter, dateFrom, dateTo]);

    // Summary stats
    const stats = useMemo(() => {
        const completeCount = filteredRecords.filter((g) => g.status === 'COMPLETE').length;
        const partialCount = filteredRecords.filter((g) => g.status === 'PARTIAL').length;
        const pendingCount = filteredRecords.filter((g) => g.status === 'PENDING').length;
        const totalExpected = filteredRecords.reduce((acc, g) => acc + g.expectedItems, 0);
        const totalReceived = filteredRecords.reduce((acc, g) => acc + g.receivedItems, 0);

        return {
            completeCount,
            partialCount,
            pendingCount,
            totalExpected,
            totalReceived,
            totalCount: filteredRecords.length
        };
    }, [filteredRecords]);

    const clearFilters = () => {
        setDateFrom('');
        setDateTo('');
        setSearchTerm('');
        setStatusFilter('ALL');
    };

    return {
        grnRecords,
        filteredRecords,
        filters: {
            searchTerm, setSearchTerm,
            statusFilter, setStatusFilter,
            dateFrom, setDateFrom,
            dateTo, setDateTo,
            clearFilters
        },
        stats
    };
};

import { useState, useEffect, useMemo } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { useDispatch, useSelector } from 'react-redux';
import { RootState } from "@/app/store/store";
import { addGRN } from "@/entities/purchase/model/purchaseSlice";
import { GRN, GRNItem, GRNStatus, PurchaseOrder } from "@repo/shared";

export const useGRNForm = () => {
    const { poId } = useParams<{ poId: string }>();
    const navigate = useNavigate();
    const dispatch = useDispatch();

    const { orders } = useSelector((state: RootState) => state.purchase);
    const { user, currentBranch } = useSelector((state: RootState) => state.auth);

    const [selectedPO, setSelectedPO] = useState<PurchaseOrder | null>(null);
    const [grnData, setGrnData] = useState<Partial<GRN>>({
        grnNumber: `GRN-${Math.floor(100000 + Math.random() * 900000)}`,
        receivedDate: new Date().toISOString().split('T')[0],
        status: 'Draft',
        items: [],
        notes: '',
        attachments: []
    });

    const availablePOs = useMemo(() => {
        return orders.filter((o: PurchaseOrder) => o.status === 'Approved' || o.status === 'Partial Receipt');
    }, [orders]);

    const initializeGRNFromPO = (order: PurchaseOrder) => {
        const items: GRNItem[] = order.items.map((item: any) => ({
            id: `ITEM-${Math.random().toString(36).substr(2, 9)}`,
            poItemId: item.product_id || '',
            productId: item.product_id || '',
            productName: item.product_name,
            sku: item.sku,
            orderedQty: item.quantity,
            receivedQty: item.quantity - (item.received_quantity || 0),
            acceptedQty: item.quantity - (item.received_quantity || 0),
            rejectedQty: 0,
            inspectionStatus: 'Accepted',
            discrepancyNotes: ''
        }));

        setGrnData((prev: Partial<GRN>) => ({
            ...prev,
            poId: order.id,
            poNumber: order.po_number,
            vendorId: order.vendor_id || '',
            vendorName: order.vendor_name,
            items: items
        }));
    };

    // Fetch PO details if poId is provided
    useEffect(() => {
        if (poId) {
            const order = orders.find((o: PurchaseOrder) => o.id === poId);
            if (order) {
                setSelectedPO(order);
                initializeGRNFromPO(order);
            }
        }
    }, [poId, orders]);

    const handlePOSelect = (poId: string) => {
        const order = orders.find((o: PurchaseOrder) => o.id === poId);
        if (order) {
            setSelectedPO(order);
            initializeGRNFromPO(order);
        }
    };

    const handleItemChange = (index: number, field: keyof GRNItem, value: any) => {
        const newItems = [...(grnData.items || [])];
        const item = { ...newItems[index], [field]: value };

        // Auto-calculate accepted/rejected if receivedQty changes
        if (field === 'receivedQty') {
            item.acceptedQty = value;
            item.rejectedQty = 0;
            item.inspectionStatus = 'Accepted';
        }

        // Auto-calculate rejected if accepted changes
        if (field === 'acceptedQty') {
            item.rejectedQty = Math.max(0, item.receivedQty - value);
            item.inspectionStatus = item.rejectedQty > 0 ? 'Partial' : 'Accepted';
        }

        newItems[index] = item;
        setGrnData((prev: Partial<GRN>) => ({ ...prev, items: newItems }));
    };

    const saveGRN = (status: GRNStatus) => {
        const finalGRN: GRN = {
            ...grnData as GRN,
            status,
            created_at: new Date().toISOString(),
            created_by: user?.name,
            branch_id: currentBranch || 'Main'
        };

        dispatch(addGRN(finalGRN));
        navigate('/purchase/grn');
    };

    const setGrnField = (field: keyof GRN, value: any) => {
        setGrnData(prev => ({ ...prev, [field]: value }));
    };

    return {
        poId,
        grnData,
        selectedPO,
        availablePOs,
        handlePOSelect,
        handleItemChange,
        saveGRN,
        setGrnField,
        navigate
    };
};

import { useState, useMemo, useEffect } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import { RootState, AppDispatch } from "@/app/store/store";
import { getAllBills } from "@/entities/finance/model/billSlice";
import { getAllSuppliers } from "@/entities/contact/model/supplierSlice";
import * as XLSX from 'xlsx';
import { jsPDF } from 'jspdf';
import 'jspdf-autotable';
import { toast } from 'react-toastify';
import { useNavigate } from 'react-router-dom';

export interface AgedBill {
    id: string;
    vendorId: string;
    vendorName: string;
    billNumber: string;
    billDate: string;
    dueDate: string;
    amount: number;
    amountPaid: number;
    outstandingAmount: number;
    daysOverdue: number;
    status: string;
    isUrgent: boolean;
    hasDiscount: boolean;
    isDisputed: boolean;
}

export const useOutstandingPayables = () => {
    const navigate = useNavigate();
    const dispatch = useDispatch<AppDispatch>();
    const { bills, isLoading } = useSelector((state: RootState) => state.bill);
    const { suppliers } = useSelector((state: RootState) => state.suppliers);

    // Filter & Sort State
    const [searchTerm, setSearchTerm] = useState('');
    const [statusFilter, setStatusFilter] = useState<'All' | 'Overdue' | 'Due Soon' | 'Future'>('All');
    const [vendorFilter, setVendorFilter] = useState('');
    const [sortBy, setSortBy] = useState<'dueDate' | 'amount' | 'daysOverdue' | 'vendorName'>('dueDate');
    const [sortOrder, setSortOrder] = useState<'asc' | 'desc'>('asc');
    const [viewMode, setViewMode] = useState<'bill-wise' | 'vendor-wise'>('bill-wise');

    useEffect(() => {
        dispatch(getAllBills({}));
        dispatch(getAllSuppliers());
    }, [dispatch]);

    // Process bills into aged format
    const processedBills = useMemo(() => {
        const today = new Date();
        return bills.map(bill => {
            const dueDate = new Date(bill.due_date);
            const diffTime = today.getTime() - dueDate.getTime();
            const daysOverdue = Math.floor(diffTime / (1000 * 60 * 60 * 24));

            const amountPaid = bill.status === 'Paid' ? bill.total_amount : (bill.status === 'Partially Paid' ? bill.total_amount * 0.4 : 0);
            const outstandingAmount = bill.total_amount - amountPaid;

            return {
                id: bill._id || bill.id,
                vendorId: bill.vendor_id,
                vendorName: bill.vendor_name,
                billNumber: bill.bill_number,
                billDate: bill.bill_date,
                dueDate: bill.due_date,
                amount: bill.total_amount,
                amountPaid,
                outstandingAmount,
                daysOverdue: daysOverdue > 0 ? daysOverdue : 0,
                status: bill.status,
                isUrgent: daysOverdue > 5 && outstandingAmount > 0,
                hasDiscount: bill.payment_terms?.toLowerCase().includes('discount'),
                isDisputed: bill.status === 'Disputed'
            };
        }).filter(b => b.outstandingAmount > 0);
    }, [bills]);

    // Filtering logic
    const filteredBills = useMemo(() => {
        return processedBills.filter(bill => {
            const matchesSearch = bill.vendorName.toLowerCase().includes(searchTerm.toLowerCase()) ||
                bill.billNumber.toLowerCase().includes(searchTerm.toLowerCase());

            const matchesVendor = !vendorFilter || bill.vendorId === vendorFilter;

            const matchesStatus = statusFilter === 'All' ||
                (statusFilter === 'Overdue' && bill.daysOverdue > 0) ||
                (statusFilter === 'Due Soon' && bill.daysOverdue <= 0 && Math.abs(bill.daysOverdue) <= 7) ||
                (statusFilter === 'Future' && bill.daysOverdue <= 0 && Math.abs(bill.daysOverdue) > 7);

            return matchesSearch && matchesVendor && matchesStatus;
        }).sort((a, b) => {
            let comparison = 0;
            switch (sortBy) {
                case 'dueDate': comparison = new Date(a.dueDate).getTime() - new Date(b.dueDate).getTime(); break;
                case 'amount': comparison = a.outstandingAmount - b.outstandingAmount; break;
                case 'daysOverdue': comparison = a.daysOverdue - b.daysOverdue; break;
                case 'vendorName': comparison = a.vendorName.localeCompare(b.vendorName); break;
            }
            return sortOrder === 'asc' ? comparison : -comparison;
        });
    }, [processedBills, searchTerm, statusFilter, vendorFilter, sortBy, sortOrder]);

    // Vendor-wise summary
    const vendorSummary = useMemo(() => {
        const summary: Record<string, { vendorId: string, vendorName: string, total: number, overdue: number, count: number }> = {};
        processedBills.forEach(bill => {
            if (!summary[bill.vendorId]) {
                summary[bill.vendorId] = { vendorId: bill.vendorId, vendorName: bill.vendorName, total: 0, overdue: 0, count: 0 };
            }
            summary[bill.vendorId].total += bill.outstandingAmount;
            if (bill.daysOverdue > 0) summary[bill.vendorId].overdue += bill.outstandingAmount;
            summary[bill.vendorId].count += 1;
        });
        return Object.values(summary).sort((a, b) => b.total - a.total);
    }, [processedBills]);

    // Aging Buckets
    const agingAnalysis = useMemo(() => {
        const buckets = {
            current: 0,
            '1-30': 0,
            '31-60': 0,
            '61-90': 0,
            '90+': 0
        };
        processedBills.forEach(bill => {
            if (bill.daysOverdue <= 0) buckets.current += bill.outstandingAmount;
            else if (bill.daysOverdue <= 30) buckets['1-30'] += bill.outstandingAmount;
            else if (bill.daysOverdue <= 60) buckets['31-60'] += bill.outstandingAmount;
            else if (bill.daysOverdue <= 90) buckets['61-90'] += bill.outstandingAmount;
            else buckets['90+'] += bill.outstandingAmount;
        });
        return buckets;
    }, [processedBills]);

    const totalPayable = useMemo(() => processedBills.reduce((acc, b) => acc + b.outstandingAmount, 0), [processedBills]);
    const totalOverdue = useMemo(() => processedBills.filter(b => b.daysOverdue > 0).reduce((acc, b) => acc + b.outstandingAmount, 0), [processedBills]);

    // Export Functions
    const exportToExcel = () => {
        const data = filteredBills.map(b => ({
            'Vendor Name': b.vendorName,
            'Bill Number': b.billNumber,
            'Bill Date': b.billDate,
            'Due Date': b.dueDate,
            'Total Amount': b.amount,
            'Amount Paid': b.amountPaid,
            'Outstanding': b.outstandingAmount,
            'Days Overdue': b.daysOverdue,
            'Status': b.status
        }));
        const ws = XLSX.utils.json_to_sheet(data);
        const wb = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(wb, ws, 'Outstanding Payables');
        XLSX.writeFile(wb, `Outstanding_Payables_${new Date().toISOString().split('T')[0]}.xlsx`);
        toast.info("Excel report generated successfully");
    };

    const printReport = () => {
        const doc = new jsPDF() as any;
        doc.setFontSize(18);
        doc.text('Outstanding Payables Report', 14, 22);
        doc.setFontSize(11);
        doc.text(`Generated on: ${new Date().toLocaleString()}`, 14, 30);
        doc.text(`Total Payable: ${totalPayable.toFixed(2)} | Total Overdue: ${totalOverdue.toFixed(2)}`, 14, 38);

        const tableData = filteredBills.map(b => [
            b.vendorName,
            b.billNumber,
            b.dueDate,
            b.outstandingAmount.toFixed(2),
            b.daysOverdue
        ]);

        doc.autoTable({
            startY: 45,
            head: [['Vendor', 'Bill #', 'Due Date', 'Outstanding', 'Overdue Days']],
            body: tableData,
            theme: 'striped',
            headStyles: { fillStyle: [16, 185, 129] }
        });

        doc.save(`Payables_Report_${new Date().getTime()}.pdf`);
        toast.info("PDF report generated successfully");
    };

    const handleQuickPayment = (vendorId: string) => {
        navigate(`/purchase/payments/${vendorId}`);
    };

    return {
        isLoading,
        searchTerm,
        setSearchTerm,
        statusFilter,
        setStatusFilter,
        vendorFilter,
        setVendorFilter,
        sortBy,
        setSortBy,
        sortOrder,
        setSortOrder,
        viewMode,
        setViewMode,
        processedBills,
        filteredBills,
        vendorSummary,
        agingAnalysis,
        totalPayable,
        totalOverdue,
        suppliers,
        exportToExcel,
        printReport,
        handleQuickPayment
    };
};

