                        className="px-4 py-2 bg-neutral-100 dark:bg-neutral-800 text-primary font-bold text-xs rounded-lg hover:bg-neutral-200 transition-colors uppercase"
                        disabled={isLoading}
                    >
                        {isLoading ? 'Processing...' : 'Auto-Extract (OCR)'}
                    </button>
                    {id && bill.status !== 'Paid' && (
                        <div className="flex items-center gap-2 mr-2 pr-4 border-r border-neutral-200 dark:border-neutral-800">
                            <button
                                onClick={() => handleUpdateStatus('Hold')}
                                className="p-2 text-amber-600 hover:bg-amber-50 rounded-lg transition-colors border border-amber-200"
                                title="Put on Hold"
                            >
                                <Clock className="w-4 h-4" />
                            </button>
                            <button
                                onClick={() => handleUpdateStatus('Disputed')}
                                className="p-2 text-red-600 hover:bg-red-50 rounded-lg transition-colors border border-red-200"
                                title="Dispute Bill"
                            >
                                <AlertCircle className="w-4 h-4" />
                            </button>
                            <button
                                onClick={() => handleUpdateStatus('Rejected')}
                                className="p-2 text-neutral-600 hover:bg-neutral-50 rounded-lg transition-colors border border-neutral-200"
                                title="Reject"
                            >
                                <Ban className="w-4 h-4" />
                            </button>
                        </div>
                    )}
                    <button
                        onClick={handleSave}
                        disabled={isLoading}
                        className="px-6 py-2.5 bg-brand-600 hover:bg-brand-700 text-white rounded-xl font-bold shadow-lg shadow-brand-600/20 flex items-center gap-2 transition-all disabled:opacity-50"
                    >
                        <Save className="w-4 h-4" /> {isLoading ? 'Saving...' : id ? 'Update Bill' : 'Finalize Bill'}
                    </button>
                    <button onClick={handleBack} className="px-4 py-2.5 text-neutral-600 dark:text-neutral-400 font-semibold text-sm hover:bg-neutral-100 dark:hover:bg-neutral-800 rounded-xl transition-colors">
                        Cancel
                    </button>
                </div>
            </div>

            <div className="flex-1 overflow-y-auto p-8 custom-scrollbar">
                <div className="max-w-6xl mx-auto space-y-8">
                    {/* Main Bill Details */}
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
                        <div className="space-y-6 md:col-span-2">
                            <BillBasicInfo
                                bill={bill}
                                vendors={vendors}
                                onVendorChange={handleVendorChange}
                                onBillChange={updateBillField}
                            />

                            {/* Vendor Invoice Details */}
                            <div className="bg-white dark:bg-neutral-900 p-6 rounded-2xl border border-neutral-200 dark:border-neutral-800 shadow-sm">
                                <h3 className="text-sm font-bold text-neutral-400 uppercase tracking-widest flex items-center gap-2 mb-4">
                                    <FileText className="w-4 h-4" /> Vendor Documents
                                </h3>
                                <div className="grid grid-cols-2 gap-4">
                                    <div>
                                        <label className="text-xs font-bold text-neutral-500 uppercase">Vendor Invoice No.</label>
                                        <input
                                            type="text"
                                            value={bill.vendorInvoiceNo || ''}
                                            onChange={(e) => updateBillField('vendorInvoiceNo', e.target.value)}
                                            placeholder="e.g. INV-2024-001"
                                            className="w-full px-4 py-2 mt-1 bg-neutral-50 dark:bg-neutral-950 border border-neutral-200 dark:border-neutral-800 rounded-lg text-sm font-bold"
                                        />
                                    </div>
                                    <div>
                                        <label className="text-xs font-bold text-neutral-500 uppercase">Invoice Date</label>
                                        <input
                                            type="date"
                                            value={bill.bill_date || ''}
                                            onChange={(e) => updateBillField('bill_date', e.target.value)}
                                            className="w-full px-4 py-2 mt-1 bg-neutral-50 dark:bg-neutral-950 border border-neutral-200 dark:border-neutral-800 rounded-lg text-sm font-bold"
                                        />
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>

                    {/* Linkage Panel */}
                    <div className="space-y-6">
                        <div className="bg-brand-50/30 dark:bg-brand-900/10 p-6 rounded-2xl border border-brand-100 dark:border-brand-900/30 shadow-sm space-y-6">
                            <h3 className="text-sm font-bold text-brand-700 dark:text-brand-400 uppercase tracking-widest flex items-center gap-2">
                                <CheckCircle className="w-4 h-4" /> Three-Way Matching
                            </h3>
                            <div>
                                <label className="block text-xs font-bold text-brand-600/60 mb-2 uppercase">Linked Goods Receipt (GRN)</label>
                                <select
                                    value={bill.grn_id || ''}
                                    onChange={(e) => handleGRNChange(e.target.value)}
                                    disabled={!bill.vendor_id}
                                    className="w-full px-4 py-3 bg-white dark:bg-neutral-950 border border-brand-200 dark:border-brand-900/50 rounded-xl text-sm focus:ring-2 focus:ring-brand-500/20 disabled:opacity-50"
                                >
                                    <option value="">Select GRN</option>
                                    {grns.map(g => <option key={g.id} value={g.id}>{g.grnNumber} ({new Date(g.receivedDate).toLocaleDateString()})</option>)}
                                </select>
                                {bill.po_number && (
                                    <div className="mt-3 flex items-center gap-2 px-3 py-2 bg-brand-500/5 rounded-lg border border-brand-500/10">
                                        <CheckCircle className="w-3.5 h-3.5 text-brand-600" />
                                        <span className="text-[10px] font-bold text-brand-700">Matched to {bill.po_number}</span>
                                    </div>
                                )}
                            </div>
                            <div className="pt-4 border-t border-brand-100 dark:border-brand-900/20">
                                <div className="flex items-center justify-between text-xs font-medium text-brand-700 mb-2">
                                    <span>Matching Status</span>
                                    <span className="px-2 py-0.5 bg-emerald-100 text-emerald-700 rounded-full font-bold">Auto-Linked</span>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>

                {/* Items Table */}
                <BillItemsTable
                    items={bill.items || []}
                    onUpdateItem={updateItem}
                />

                {/* Bottom Grid */}
                <div className="grid grid-cols-1 md:grid-cols-2 gap-8 pb-12">
                    {/* Attachments & Notes */}
                    <div className="space-y-6">
                        <div className="bg-white dark:bg-neutral-900 p-6 rounded-2xl border border-neutral-200 dark:border-neutral-800 shadow-sm space-y-4">
                            <h3 className="text-sm font-bold text-neutral-400 uppercase tracking-widest flex items-center gap-2">
                                <Paperclip className="w-4 h-4" /> Documents & OCR
                            </h3>
                            <div
                                className="border-2 border-dashed border-neutral-200 dark:border-neutral-800 rounded-xl p-8 text-center hover:border-brand-500/50 hover:bg-brand-500/5 transition-all cursor-pointer group"
                            >
                                <input
                                    type="file"
                                    id="bill-upload"
                                    className="hidden"
                                    onChange={handleFileUpload}
                                    accept=".pdf,image/*"
                                />
                                <div onClick={() => document.getElementById('bill-upload')?.click()}>
                                    <div className="w-12 h-12 bg-neutral-100 dark:bg-neutral-800 rounded-full flex items-center justify-center mx-auto mb-3 group-hover:scale-110 transition-transform">
                                        <Plus className="w-6 h-6 text-neutral-400 group-hover:text-brand-500" />
                                    </div>
                                    <p className="text-sm font-bold text-neutral-600 dark:text-neutral-400">Click to upload Bill PDF/Image</p>
                                    <p className="text-xs text-neutral-500 mt-1">Supports OCR amount extraction (Experimental)</p>
                                </div>
                            </div>
                            <div className="flex flex-wrap gap-2">
                                {attachments.map((at, i) => (
                                    <div key={i} className="flex items-center gap-2 px-3 py-1.5 bg-neutral-100 dark:bg-neutral-800 rounded-lg text-xs border border-neutral-200 dark:border-neutral-700">
                                        <FileText className="w-3.5 h-3.5" /> {at} <X className="w-3 h-3 cursor-pointer" onClick={() => removeAttachment(i)} />
                                    </div>
                                ))}
                            </div>
                        </div>
                        <div className="bg-white dark:bg-neutral-900 p-6 rounded-2xl border border-neutral-200 dark:border-neutral-800 shadow-sm space-y-4">
                            <h3 className="text-sm font-bold text-neutral-400 uppercase tracking-widest flex items-center gap-2">
                                <FileText className="w-4 h-4" /> Bill Notes
                            </h3>
                            <textarea
                                value={bill.notes || ''}
                                onChange={(e) => updateBillField('notes', e.target.value)}
                                rows={4}
                                className="w-full px-4 py-3 bg-neutral-50 dark:bg-neutral-950 border border-neutral-200 dark:border-neutral-800 rounded-xl text-sm focus:ring-2 focus:ring-brand-500/20"
                                placeholder="Any internal notes or dispute details..."
                            />
                        </div>
                    </div>

                    {/* Totals & Tax Summary */}
                    <BillFinancialSummary
                        totals={totals}
                        status={bill.status}
                        paymentTerms={bill.payment_terms}
                    />
                </div>
            </div>
        </div>
    );
};


export default BillForm;

import React from 'react';
import { Plus } from 'lucide-react';
import Layout from "@/shared/ui/Layout/Layout";
import PageHeader from "@/shared/ui/Layout/PageHeader";
import BillForm from "./BillForm";
import BillsStats from '../Components/BillsStats';
import BillsFilters from '../Components/BillsFilters';
import BillsTable from '../Components/BillsTable';
import DeleteBillModal from '../Components/DeleteBillModal';
import PaymentModal from "@/shared/ui/Modals/PaymentModal";
import { useBills } from '../hooks/useBills';

const Bills: React.FC = () => {
    const {
        filteredBills,
        isLoading,
        searchTerm,
        setSearchTerm,
        statusFilter,
        setStatusFilter,
        showForm,
        setShowForm,
        editingBill,
        setEditingBill,
        deleteConfirm,
        setDeleteConfirm,
        paymentModal,
        setPaymentModal,
        handleMarkAsPaid,
        handlePaymentSubmit,
        handleSaveBill,
        handleEdit,
        handleDelete,
        totals
    } = useBills();

    return (
        <Layout>
            <div className="space-y-6 animate-fade-in pb-10">
                <PageHeader
                    title="Supplier Bills"
                    description="Record and track bills from your vendors and suppliers"
                    actions={
                        <button
                            onClick={() => { setEditingBill(null); setShowForm(true); }}
                            className="btn btn-primary bg-brand-600 hover:bg-brand-700 shadow-brand-600/20"
                        >
                            <Plus className="w-4 h-4" />
                            New Bill
                        </button>
                    }
                />

                {showForm ? (
                    <BillForm
                        onBack={() => setShowForm(false)}
                        onSave={handleSaveBill}
                        initialData={editingBill as any}
                    />
                ) : (
                    <>
                        <BillsStats
                            billsCount={filteredBills.length}
                            totalAmount={totals.totalBillsAmount}
                            paidAmount={totals.totalPaidAmount}
                            outstandingAmount={totals.totalOutstanding}
                        />

                        <BillsFilters
                            searchTerm={searchTerm}
                            onSearchChange={setSearchTerm}
                            statusFilter={statusFilter}
                            onStatusFilterChange={setStatusFilter}
                        />

                        <BillsTable
                            bills={filteredBills}
                            isLoading={isLoading}
                            onMarkAsPaid={handleMarkAsPaid}
                            onDelete={(id) => setDeleteConfirm(id)}
                        />
                    </>
                )}

                {/* Delete Confirm */}
                <DeleteBillModal
                    isOpen={!!deleteConfirm}
                    onClose={() => setDeleteConfirm(null)}
                    onConfirm={() => deleteConfirm && handleDelete(deleteConfirm)}
                />

                {/* Payment Modal */}
                {paymentModal.isOpen && paymentModal.bill && (
                    <PaymentModal
                        isOpen={paymentModal.isOpen}
                        onClose={() => setPaymentModal({ isOpen: false, bill: null })}
                        onSubmit={handlePaymentSubmit}
                        documentType="Bill"
                        totalAmount={paymentModal.bill.amount}
                        paidAmount={paymentModal.bill.paidAmount || 0}
                    />
                )}
            </div>
        </Layout>
    );
};

export default Bills;

import React, { useState, useMemo, useEffect } from 'react';
import { useSelector } from 'react-redux';
import { RootState } from "@/app/store/store";
import { useBranchResolver } from "@/hooks/useBranchResolver";
import Layout from "@/shared/ui/Layout/Layout";
import PageHeader from "@/shared/ui/Layout/PageHeader";
import {
    Search,
    FileText,
    Download,
    Plus,
    Eye,
    Truck,
    RotateCcw,
    CheckCircle,
    Clock,
    Loader2,
} from 'lucide-react';
import { getAllBills } from "@/entities/finance/model/billSlice";
import { fetchPurchaseOrders } from "@/entities/purchase/model/purchaseSlice";
import { AppDispatch } from "@/app/store/store";
import { useDispatch } from 'react-redux';
import { debitNoteService, DebitNote } from "@/entities/finance/api/debitNoteService";
import { toast } from 'react-toastify';
import CreateDebitNoteModal from '../Modals/CreateDebitNoteModal';
import DebitNoteStats from '../Components/DebitNoteStats';


const REASON_LABELS: Record<string, string> = {
    SHORT_DELIVERY: 'Short Delivery',
    QUALITY_ISSUE: 'Quality Issue',
    RETURN_SHIPPING: 'Return Shipping Cost',
    SERVICE_CHARGE: 'Service Charge',
    PRICE_DIFFERENCE: 'Price Difference',
    OTHER: 'Other'
};

const STATUS_CONFIG: Record<string, { label: string; icon: any; color: string; bg: string }> = {
    DRAFT: { label: 'Drafted', icon: FileText, color: 'text-neutral-600', bg: 'bg-neutral-100' },
    SENT: { label: 'Sent', icon: Clock, color: 'text-primary', bg: 'bg-primary/10' },
    ACKNOWLEDGED: { label: 'Acknowledged', icon: CheckCircle, color: 'text-info', bg: 'bg-info/10' },
    SETTLED: { label: 'Settled', icon: CheckCircle, color: 'text-success', bg: 'bg-success/10' }
};

const DebitNotes: React.FC = () => {
    const dispatch = useDispatch<AppDispatch>();
    const { orders, grns } = useSelector((state: RootState) => state.purchase);
    const { bills } = useSelector((state: RootState) => state.bill);
    const { suppliers: vendors } = useSelector((state: RootState) => state.suppliers);
    const { currentBranch } = useSelector((state: RootState) => state.auth);
    const { currentBranchId, getBranchName } = useBranchResolver();

    const [searchTerm, setSearchTerm] = useState('');
    const [statusFilter, setStatusFilter] = useState<string>('ALL');
    const [reasonFilter, setReasonFilter] = useState<string>('ALL');
    const [dateFrom, setDateFrom] = useState('');
    const [dateTo, setDateTo] = useState('');
    const [showCreateModal, setShowCreateModal] = useState(false);
    const [debitNotes, setDebitNotes] = useState<DebitNote[]>([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        dispatch(getAllBills({}));
        dispatch(fetchPurchaseOrders());
    }, [dispatch]);

    useEffect(() => {
        fetchDebitNotes();
    }, []);

    const fetchDebitNotes = async () => {
        try {
            const data = await debitNoteService.getDebitNotes();
            setDebitNotes(data);
        } catch (error: any) {
            toast.error('Failed to fetch debit notes');
        } finally {
            setLoading(false);
        }
    };

    // Apply filters
    const filteredNotes = useMemo(() => {
        return debitNotes.filter(note => {
            if (searchTerm) {
                const search = searchTerm.toLowerCase();
                if (!note.vendorName.toLowerCase().includes(search) &&
                    !note.noteId.toLowerCase().includes(search)) {
                    return false;
                }
            }
            if (statusFilter !== 'ALL' && note.status !== statusFilter) return false;
            if (reasonFilter !== 'ALL' && note.reason !== reasonFilter) return false;
            if (dateFrom && new Date(note.date) < new Date(dateFrom)) return false;
            if (dateTo) {
                const nextDay = new Date(dateTo);
                nextDay.setDate(nextDay.getDate() + 1);
                if (new Date(note.date) >= nextDay) return false;
            }
            return true;
        });
    }, [debitNotes, searchTerm, statusFilter, reasonFilter, dateFrom, dateTo]);

    // Summary
    const totalAmount = filteredNotes.reduce((acc, n) => acc + n.totalAmount, 0);
    const approvedAmount = filteredNotes.filter(n => n.status === 'SETTLED').reduce((acc, n) => acc + n.totalAmount, 0);
    const pendingCount = filteredNotes.filter(n => n.status === 'SENT').length;

    const getStatusBadge = (status: string) => {
        const config = STATUS_CONFIG[status] || STATUS_CONFIG.DRAFT;
        const Icon = config.icon;
        return (
            <span className={`px-2 py-1 ${config.bg} ${config.color} text-xs font-bold rounded-full flex items-center gap-1`}>
                <Icon className="w-3 h-3" /> {config.label}
            </span>
        );
    };

    const getReasonBadge = (reason: string) => {
        const colors: Record<string, string> = {
            SHORT_DELIVERY: 'bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400',
            QUALITY_ISSUE: 'bg-orange-100 text-orange-700 dark:bg-orange-900/30 dark:text-orange-400',
            RETURN_SHIPPING: 'bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400',
            SERVICE_CHARGE: 'bg-purple-100 text-purple-700 dark:bg-purple-900/30 dark:text-purple-400',
            PRICE_DIFFERENCE: 'bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400',
            OTHER: 'bg-neutral-100 text-neutral-600 dark:bg-neutral-700 dark:text-neutral-400'
        };
        return <span className={`px-2 py-0.5 text-[10px] font-bold rounded ${colors[reason] || colors.OTHER}`}>
            {REASON_LABELS[reason] || reason}
        </span>;
    };

    return (
        <Layout>
            <div className="space-y-6 animate-fade-in">
                <PageHeader
                    title="Debit Notes"
                    description={`Track returns and claims against suppliers • ${getBranchName(currentBranchId)}`}
                    actions={
                        <>
                            <button className="px-4 py-2 bg-white dark:bg-neutral-800 border border-neutral-200 dark:border-neutral-700 rounded-lg text-sm font-medium hover:bg-neutral-50 dark:hover:bg-neutral-700 flex items-center gap-2">
                                <Download className="w-4 h-4" /> Export
                            </button>
                            <button
                                onClick={() => setShowCreateModal(true)}
                                className="px-4 py-2 bg-error text-white rounded-lg text-sm font-bold hover:bg-error/90 flex items-center gap-2"
                            >
                                <Plus className="w-4 h-4" /> Create Debit Note
                            </button>
                        </>
                    }
                />

                <DebitNoteStats
                    totalCount={filteredNotes.length}
                    totalAmount={totalAmount}
                    approvedAmount={approvedAmount}
                    pendingCount={pendingCount}
                />

                {/* Filters */}
                <div className="bg-white dark:bg-neutral-800 p-4 rounded-xl border border-neutral-200 dark:border-neutral-700 flex flex-wrap gap-4 items-end">
                    <div className="flex-1 min-w-[200px]">
                        <label className="text-xs text-secondary font-bold uppercase mb-1 block">Search</label>
                        <div className="relative">
                            <input
                                type="text"
                                placeholder="DN # or Vendor..."
                                className="w-full pl-9 pr-4 py-2 bg-neutral-100 dark:bg-neutral-700 border border-neutral-200 dark:border-neutral-600 rounded-lg text-neutral-900 dark:text-white text-sm"
                                value={searchTerm}
                                onChange={e => setSearchTerm(e.target.value)}
                            />
                            <Search className="w-4 h-4 absolute left-3 top-2.5 text-neutral-400" />
                        </div>
                    </div>

                    <div>
                        <label className="text-xs text-secondary font-bold uppercase mb-1 block">From</label>
                        <input
                            type="date"
                            className="px-3 py-2 bg-neutral-100 dark:bg-neutral-700 border border-neutral-200 dark:border-neutral-600 rounded-lg text-neutral-900 dark:text-white text-sm"
                            value={dateFrom}
                            onChange={e => setDateFrom(e.target.value)}
                        />
                    </div>

                    <div>
                        <label className="text-xs text-secondary font-bold uppercase mb-1 block">To</label>
                        <input
                            type="date"
                            className="px-3 py-2 bg-neutral-100 dark:bg-neutral-700 border border-neutral-200 dark:border-neutral-600 rounded-lg text-neutral-900 dark:text-white text-sm"
                            value={dateTo}
                            onChange={e => setDateTo(e.target.value)}
                        />
                    </div>

                    <div>
                        <label className="text-xs text-secondary font-bold uppercase mb-1 block">Status</label>
                        <select
                            className="px-3 py-2 bg-neutral-100 dark:bg-neutral-700 border border-neutral-200 dark:border-neutral-600 rounded-lg text-neutral-900 dark:text-white text-sm"
                            value={statusFilter}
                            onChange={e => setStatusFilter(e.target.value)}
                        >
                            <option value="ALL">All Status</option>
                            <option value="DRAFT">Draft</option>
                            <option value="SENT">Sent</option>
                            <option value="ACKNOWLEDGED">Acknowledged</option>
                            <option value="SETTLED">Settled</option>
                        </select>
                    </div>

                    <div>
                        <label className="text-xs text-secondary font-bold uppercase mb-1 block">Reason</label>
                        <select
                            className="px-3 py-2 bg-neutral-100 dark:bg-neutral-700 border border-neutral-200 dark:border-neutral-600 rounded-lg text-neutral-900 dark:text-white text-sm"
                            value={reasonFilter}
                            onChange={e => setReasonFilter(e.target.value)}
                        >
                            <option value="ALL">All Reasons</option>
                            <option value="RETURN">Goods Return</option>
                            <option value="PRICE_DIFF">Price Difference</option>
                            <option value="QUALITY">Quality Issue</option>
                            <option value="SHORTAGE">Short Shipment</option>
                            <option value="OTHER">Other</option>
                        </select>
                    </div>

                    <button
                        onClick={() => { setSearchTerm(''); setStatusFilter('ALL'); setReasonFilter('ALL'); setDateFrom(''); setDateTo(''); }}
                        className="px-4 py-2 bg-neutral-200 dark:bg-neutral-700 hover:bg-neutral-300 dark:hover:bg-neutral-600 text-neutral-700 dark:text-neutral-300 rounded-lg text-sm font-bold"
                    >
                        Clear
                    </button>
                </div>

                {/* Debit Notes Table */}
                <div className="bg-white dark:bg-neutral-800 rounded-xl border border-neutral-200 dark:border-neutral-700 overflow-hidden">
                    <div className="hidden md:block overflow-x-auto">
                        <table className="w-full text-left text-sm">
                            <thead className="bg-neutral-50 dark:bg-neutral-900 text-secondary uppercase text-xs font-medium">
                                <tr>
                                    <th className="p-4">DN #</th>
                                    <th className="p-4">Date</th>
                                    <th className="p-4">Vendor</th>
                                    <th className="p-4">PO Ref</th>
                                    <th className="p-4">Reason</th>
                                    <th className="p-4 text-right">Amount</th>
                                    <th className="p-4 text-center">Status</th>
                                    <th className="p-4 text-center">Action</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-neutral-100 dark:divide-neutral-700">
                                {loading ? (
                                    <tr><td colSpan={8} className="p-8 text-center text-neutral-500">
                                        <div className="flex flex-col items-center gap-2">
                                            <Loader2 className="w-8 h-8 text-neutral-300 animate-spin" />
                                            <p>Loading debit notes...</p>
                                        </div>
                                    </td></tr>
                                ) : filteredNotes.length === 0 ? (
                                    <tr><td colSpan={8} className="p-8 text-center text-neutral-500">
                                        <div className="flex flex-col items-center gap-2">
                                            <RotateCcw className="w-8 h-8 text-neutral-300" />
                                            <p>No debit notes found</p>
                                        </div>
                                    </td></tr>
                                ) : (
                                    filteredNotes.map(note => (
                                        <tr key={note._id || note.noteId} className="hover:bg-neutral-50 dark:hover:bg-neutral-700/50">
                                            <td className="p-4 font-mono text-xs text-error font-medium">{note.noteId}</td>
                                            <td className="p-4 text-neutral-600 dark:text-neutral-400">
                                                {new Date(note.date).toLocaleDateString()}
                                            </td>
                                            <td className="p-4">
                                                <div className="flex items-center gap-2">
                                                    <div className="w-8 h-8 rounded-lg bg-primary/10 flex items-center justify-center">
                                                        <Truck className="w-4 h-4 text-primary" />
                                                    </div>
                                                    <span className="font-medium text-neutral-900 dark:text-white">{note.vendorName}</span>
                                                </div>
                                            </td>
                                            <td className="p-4 font-mono text-xs text-neutral-500">{note.originalBillNumber || note.originalGrnNumber || '-'}</td>
                                            <td className="p-4">{getReasonBadge(note.reason)}</td>
                                            <td className="p-4 text-right font-bold text-error">₹{note.totalAmount.toLocaleString()}</td>
                                            <td className="p-4 text-center">{getStatusBadge(note.status)}</td>
                                            <td className="p-4 text-center">
                                                <button className="p-2 hover:bg-neutral-100 dark:hover:bg-neutral-700 rounded-lg" title="View">
                                                    <Eye className="w-4 h-4 text-primary" />
                                                </button>
                                            </td>
                                        </tr>
                                    ))
                                )}
                            </tbody>
                        </table>
                    </div>

                    {/* Mobile View */}
                    <div className="md:hidden divide-y divide-neutral-100 dark:divide-neutral-700">
                        {filteredNotes.length === 0 ? (
                            <div className="p-8 text-center text-neutral-500">No debit notes</div>
                        ) : (
                            filteredNotes.map(note => (
                                <div key={note._id || note.noteId} className="p-4">
                                    <div className="flex justify-between items-start mb-2">
                                        <div>
                                            <p className="font-mono text-xs text-error font-medium">{note.noteId}</p>
                                            <p className="font-bold text-neutral-900 dark:text-white">{note.vendorName}</p>
                                        </div>
                                        {getStatusBadge(note.status)}
                                    </div>
                                    <div className="flex justify-between items-center bg-neutral-50 dark:bg-neutral-700/50 p-3 rounded-lg mt-2">
                                        <div className="flex items-center gap-2">
                                            {getReasonBadge(note.reason)}
                                        </div>
                                        <p className="font-bold text-error">₹{note.totalAmount.toLocaleString()}</p>
                                    </div>
                                </div>
                            ))
                        )}
                    </div>
                </div>

                {/* Create Modal */}
                <CreateDebitNoteModal
                    isOpen={showCreateModal}
                    onClose={() => setShowCreateModal(false)}
                    onSuccess={() => {
                        setShowCreateModal(false);
                        fetchDebitNotes();
                    }}
                    vendors={vendors}
                    bills={bills}
                    grns={grns}
                    REASON_LABELS={REASON_LABELS}
                />
            </div>
        </Layout>
    );
};

