import React, { useState, useEffect } from 'react';
import { usePurchaseOrders } from "@/hooks/usePurchaseOrders";
import { PurchaseOrder, PurchaseOrderItem } from "@repo/shared";
import PurchaseOrderList from './PurchaseOrderList';
import PurchaseOrderForm from './PurchaseOrderForm';
import PurchaseOrderDetails from './PurchaseOrderDetails';
import { useDispatch, useSelector } from 'react-redux';
import { useUiStore } from "@/shared/lib/store/uiStore";
import { RootState } from "@/app/store/store";
import Layout from "@/shared/ui/Layout/Layout";
import PageHeader from "@/shared/ui/Layout/PageHeader";
import { StatsCard } from "@repo/ui";
import { useBranchResolver } from "@/hooks/useBranchResolver";
import { ClipboardList, Clock, CheckCircle, Lock, Plus } from 'lucide-react';

const PurchaseOrdersModule: React.FC = () => {
    const {
        orders,
        currentOrder,
        isLoading: loading,
        loadOrders: fetchOrders,
        loadOrderDetails: fetchOrderDetails,
        createOrder: saveOrder,
        updateOrderStatus: updateStatus
    } = usePurchaseOrders();

    // Stats for the module
    const stats = {
        total: orders.length,
        pending: orders.filter((o: any) => o.status === 'Pending').length,
        approved: orders.filter((o: any) => o.status === 'Approved').length,
        converted: orders.filter((o: any) => o.status === 'Converted').length,
    };
    const [view, setView] = useState<'LIST' | 'FORM' | 'DETAILS'>('LIST');
    const [selectedOrder, setSelectedOrder] = useState<PurchaseOrder | null>(null);
    const [selectedItems, setSelectedItems] = useState<PurchaseOrderItem[]>([]);

    const dispatch = useDispatch();
    const { activeTab, setActiveTab } = useUiStore();

    // Sync view with activeTab
    useEffect(() => {
        if (activeTab === 'PURCHASE_ORDER_FORM') {
            setView('FORM');
            setSelectedOrder(null);
            setSelectedItems([]);
        } else if (activeTab === 'PURCHASE_ORDER_LIST' || activeTab === 'PURCHASE_ORDER') {
            setView('LIST');
        }
    }, [activeTab]);

    useEffect(() => {
        fetchOrders();
    }, [fetchOrders]);

    const handleCreate = () => {
        setSelectedOrder(null);
        setSelectedItems([]);
        setView('FORM');
    };

    const handleView = async (id: string) => {
        const fullDetails = await fetchOrderDetails(id);
        if (fullDetails) {
            setSelectedOrder(fullDetails);
            setSelectedItems(fullDetails.items || []);
            setView('DETAILS');
        }
    };

    const handleSave = async (order: Partial<PurchaseOrder>, items: PurchaseOrderItem[]) => {
        await saveOrder(order, items);
        setView('LIST');
    };

    const handleApprove = async () => {
        if (selectedOrder) {
            if (confirm('Are you sure you want to approve this order?')) {
                await updateStatus(selectedOrder.id, 'Approved');
                const updated = { ...selectedOrder, status: 'Approved' } as PurchaseOrder;
                setSelectedOrder(updated);
            }
        }
    };

    const handleConvert = (order: PurchaseOrder, items: PurchaseOrderItem[]) => {
        if (confirm('This will navigate to Purchase Entry to finalize the purchase. Continue?')) {
            const conversionData = {
                po_id: order.id,
                vendor_id: typeof order.vendor_id === 'object' ? (order.vendor_id as any)._id || (order.vendor_id as any).id : order.vendor_id,
                items: items.map(i => ({
                    productId: i.product_id,
                    quantity: i.quantity,
                    rate: i.rate,
                    tax: i.tax_percent,
                    discount: i.discount_amount
                }))
            };
            localStorage.setItem('pending_po_conversion', JSON.stringify(conversionData));
            setActiveTab('PURCHASE_ENTRY');
        }
    };

    const renderContent = () => {
        if (loading && orders.length === 0) {
            return (
                <div className="flex flex-col items-center justify-center py-20">
                    <div className="animate-spin rounded-full h-10 w-10 border-b-2 border-brand-600 mb-4"></div>
                    <p className="text-neutral-500 font-medium">Loading orders...</p>
                </div>
            );
        }

        switch (view) {
            case 'LIST':
                return (
                    <div className="space-y-6">
                        <PageHeader
                            title="Purchase Orders"
                            description="Create and track procurement orders with suppliers"
                            actions={
                                <button
                                    onClick={handleCreate}
                                    className="btn btn-primary"
                                >
                                    <Plus className="w-4 h-4" />
                                    New Order
                                </button>
                            }
                        />

                        {/* Stats Bar */}
                        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
                            <StatsCard
                                title="Total Orders"
                                value={stats.total}
                                icon={<ClipboardList className="w-full h-full" />}
                                iconBgColor="bg-blue-100"
                                iconColor="text-blue-600"
                            />
                            <StatsCard
                                title="Pending Approval"
                                value={stats.pending}
                                icon={<Clock className="w-full h-full" />}
                                iconBgColor="bg-amber-100"
                                iconColor="text-amber-600"
                                trend="Awaiting review"
                                trendUp={false}
                            />
                            <StatsCard
                                title="Approved"
                                value={stats.approved}
                                icon={<CheckCircle className="w-full h-full" />}
                                iconBgColor="bg-emerald-100"
                                iconColor="text-emerald-600"
                                trend="Ready for conversion"
                                trendUp={true}
                            />
                            <StatsCard
                                title="Converted"
                                value={stats.converted}
                                icon={<Lock className="w-full h-full" />}
                                iconBgColor="bg-neutral-100"
                                iconColor="text-neutral-600"
                                trend="Fulfilled"
                                trendUp={true}
                            />
                        </div>

                        <PurchaseOrderList orders={orders} onCreate={handleCreate} onView={handleView} />
                    </div>
                );
            case 'FORM':
                return (
                    <PurchaseOrderForm
                        onBack={() => setView('LIST')}
                        onSave={handleSave}
                        initialData={selectedOrder}
                    />
                );
            case 'DETAILS':
                return selectedOrder && (
                    <PurchaseOrderDetails
                        order={selectedOrder}
                        items={selectedItems}
                        onBack={() => setView('LIST')}
                        onApprove={() => updateStatus(selectedOrder.id, 'Approved')}
                        onConvert={handleConvert}
                        onUpdateStatus={updateStatus} // Pass the generic handler
                    />
                );
            default:
                return null;
        }
    };

    return (
        <Layout>
            <div className="h-full animate-fade-in pb-10">
                {renderContent()}
            </div>
        </Layout>
    );
};

export default PurchaseOrdersModule;

import React, { useState, useMemo } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import { useNavigate } from 'react-router-dom';
import { toast } from 'react-toastify';
import { RootState, AppDispatch } from "@/app/store/store";
import { getAllPurchases } from "@/entities/purchase/model/purchaseSlice";
import { useUiStore } from "@/shared/lib/store/uiStore";
import { PurchaseOrder, PurchaseOrderStatus } from "@repo/shared";
import { useBranchResolver } from "@/hooks/useBranchResolver";
import {
    Search,
    Calendar,
    Package,
    TrendingUp,
    FileText,
    Filter,
    Download,
    Plus,
    Eye,
    CheckCircle,
    Clock,
    XCircle,
    Truck,
    RefreshCw,
    User,
    ChevronLeft,
    ChevronRight,
    FileSpreadsheet,
    ArrowUpDown,
    ArrowUp,
    CheckSquare,
    ArrowDown
} from 'lucide-react';
import Layout from "@/shared/ui/Layout/Layout";
import PageHeader from "@/shared/ui/Layout/PageHeader";
import { StatsCard } from "@repo/ui";
import jsPDF from 'jspdf';
import autoTable from 'jspdf-autotable';

const PurchaseRegister: React.FC = () => {
    const navigate = useNavigate();
    const dispatch = useDispatch<AppDispatch>();
    const { orders, isProcessing } = useSelector((state: RootState) => state.purchase);
    const { getBranchName } = useBranchResolver();
    const { setActiveTab } = useUiStore();

    // Filter State
    const [searchTerm, setSearchTerm] = useState('');
    const [statusFilter, setStatusFilter] = useState<string>('ALL');
    const [dateFrom, setDateFrom] = useState('');
    const [dateTo, setDateTo] = useState('');
    const [vendorFilter, setVendorFilter] = useState('ALL');
    const [amountMin, setAmountMin] = useState('');
    const [amountMax, setAmountMax] = useState('');

    // View Mode State
    const [viewMode, setViewMode] = useState<'ALL' | 'BILLED' | 'UNBILLED' | 'DRAFT'>('ALL');

    const [isRefreshing, setIsRefreshing] = useState(false);

    // Sort State
    const [sortColumn, setSortColumn] = useState<string>('date');
    const [sortDirection, setSortDirection] = useState<'asc' | 'desc'>('desc');

    // Pagination State
    const [currentPage, setCurrentPage] = useState(1);
    const [itemsPerPage, setItemsPerPage] = useState(10);

    // Load Data
    React.useEffect(() => {
        dispatch(getAllPurchases());
    }, [dispatch]);

    const handleRefresh = async () => {
        setIsRefreshing(true);
        await dispatch(getAllPurchases());
        setTimeout(() => setIsRefreshing(false), 500);
    };

    const handleSort = (column: string) => {
        if (sortColumn === column) {
            setSortDirection(sortDirection === 'asc' ? 'desc' : 'asc');
        } else {
            setSortColumn(column);
            setSortDirection('asc'); // Default new column to asc, or maybe desc for date? let's stick to standard toggle
        }
    };

    // Derived Data for Filters 
    // Handle the fact that vendorId is populated in the backend
    const uniqueVendors = useMemo(() => {
        const vendorNames = orders.map(o => {
            if (o.vendorId && typeof o.vendorId === 'object') {
                return o.vendorId.businessName || o.vendorId.name;
            }
            return o.vendor_name;
        });
        return Array.from(new Set(vendorNames)).filter((v): v is string => !!v).sort();
    }, [orders]);

    // Filtering Logic
    const filteredOrders = useMemo(() => {
        return orders.filter(order => {
            let vName = '';
            if (order.vendorId && typeof order.vendorId === 'object') {
                vName = order.vendorId.businessName || order.vendorId.name || '';
            } else {
                vName = order.vendor_name || '';
            }

            const pNumber = order.purchaseNumber || order.po_number || '';
            const pDate = order.date || order.po_date;
            const tAmount = order.totalAmount || order.total_amount || 0;

            // Search
            if (searchTerm) {
                const search = searchTerm.toLowerCase();
                if (!vName.toLowerCase().includes(search) &&
                    !pNumber.toLowerCase().includes(search)) {
                    return false;
                }
            }

            // Status
            if (statusFilter !== 'ALL' && order.status !== statusFilter) return false;

            // Vendor
            if (vendorFilter !== 'ALL' && vName !== vendorFilter) return false;

            // Date Range
            if (dateFrom && new Date(pDate) < new Date(dateFrom)) return false;
            if (dateTo) {
                const nextDay = new Date(dateTo);
                nextDay.setDate(nextDay.getDate() + 1);
                if (new Date(pDate) >= nextDay) return false;
            }

            // Amount Range
            if (amountMin && tAmount < parseFloat(amountMin)) return false;
            if (amountMax && tAmount > parseFloat(amountMax)) return false;

            return true;
        }).sort((a, b) => {
            let valA: any = '';
            let valB: any = '';

            switch (sortColumn) {
                case 'number':
                    valA = a.purchaseNumber || a.po_number || '';
                    valB = b.purchaseNumber || b.po_number || '';
                    break;
                case 'date':
                    valA = new Date((a as any).createdAt || a.created_at || a.date || a.po_date || 0).getTime();
                    valB = new Date((b as any).createdAt || b.created_at || b.date || b.po_date || 0).getTime();
                    break;
                case 'vendor':
                    if (a.vendorId && typeof a.vendorId === 'object') {
                        valA = (a.vendorId.businessName || a.vendorId.name || '').toLowerCase();
                    } else {
                        valA = (a.vendor_name || '').toLowerCase();
                    }
                    if (b.vendorId && typeof b.vendorId === 'object') {
                        valB = (b.vendorId.businessName || b.vendorId.name || '').toLowerCase();
                    } else {
                        valB = (b.vendor_name || '').toLowerCase();
                    }
                    break;
                case 'items':
                    valA = a.items.length;
                    valB = b.items.length;
                    break;
                case 'amount':
                    valA = a.totalAmount || a.total_amount || 0;
                    valB = b.totalAmount || b.total_amount || 0;
                    break;
                case 'status':
                    valA = a.status || '';
                    valB = b.status || '';
                    break;
                default:
                    return 0;
            }

            if (sortDirection === 'asc') {
                return valA > valB ? 1 : -1;
            } else {
                return valA < valB ? 1 : -1;
            }
        });
    }, [orders, searchTerm, statusFilter, dateFrom, dateTo, vendorFilter, amountMin, amountMax, sortColumn, sortDirection]);

    // Apply View Mode
    const displayOrders = useMemo(() => {
        switch (viewMode) {
            case 'BILLED':
                return filteredOrders.filter(o =>
                    o.status === 'COMPLETED' ||
                    o.status === 'Billed' ||
                    o.status === 'Paid' ||
                    o.status === 'Converted'
                );
            case 'UNBILLED':
                return filteredOrders.filter(o =>
                    o.status === 'Pending' ||
                    o.status === 'Pending Approval' ||
                    o.status === 'Approved' ||
                    o.status === 'Partial Receipt' || // Corrected from Partially Received
                    o.status === 'Fully Received' ||
                    o.status === 'RECEIVED'
                );
            case 'DRAFT':
                return filteredOrders.filter(o => o.status === 'Draft');
            case 'ALL':
            default:
                return filteredOrders;
        }
    }, [filteredOrders, viewMode]);

    // Pagination Logic
    const totalPages = Math.ceil(displayOrders.length / itemsPerPage);
    const paginatedOrders = useMemo(() => {
        const start = (currentPage - 1) * itemsPerPage;
        return displayOrders.slice(start, start + itemsPerPage);
    }, [displayOrders, currentPage, itemsPerPage]);

    // Stats (Calculated on Base Filtered Orders, NOT affected by 'Billed Only' toggle)
    const totalPurchasesValue = filteredOrders.reduce((acc, o) => acc + (o.totalAmount || o.total_amount || 0), 0);
    const totalBilledValue = filteredOrders
        .filter(o => o.status === 'COMPLETED')
        .reduce((acc, o) => acc + (o.totalAmount || o.total_amount || 0), 0);

    const pendingCount = filteredOrders.filter(o => o.status === 'Pending' || o.status === 'Pending Approval' || o.status === 'Draft').length;
    const approvedCount = filteredOrders.filter(o => o.status === 'Approved' || o.status === 'Fully Received').length;

    const getStatusBadge = (status: string) => {
        const s = status.toUpperCase();
        switch (s) {
            case 'APPROVED':
            case 'COMPLETED':
                return <span className="px-2 py-1 bg-success/10 text-success text-xs font-bold rounded-full flex items-center gap-1"><CheckCircle className="w-3 h-3" /> {status === 'COMPLETED' ? 'Completed' : 'Approved'}</span>;
            case 'PENDING':
            case 'PENDING APPROVAL':
            case 'DRAFT':
                return <span className="px-2 py-1 bg-warning/10 text-warning text-xs font-bold rounded-full flex items-center gap-1"><Clock className="w-3 h-3" /> {s === 'DRAFT' ? 'Draft' : 'Pending'}</span>;
            case 'REJECTED':
            case 'CANCELLED':
                return <span className="px-2 py-1 bg-error/10 text-error text-xs font-bold rounded-full flex items-center gap-1"><XCircle className="w-3 h-3" /> {status}</span>;
            case 'PAID':
                return <span className="px-2 py-1 bg-emerald-100 text-emerald-800 text-xs font-bold rounded-full flex items-center gap-1"><CheckCircle className="w-3 h-3" /> Paid</span>;
            case 'BILLED':
                return <span className="px-2 py-1 bg-purple-100 text-purple-800 text-xs font-bold rounded-full flex items-center gap-1"><FileText className="w-3 h-3" /> Billed</span>;
            default:
                return <span className="px-2 py-1 bg-neutral-100 text-neutral-600 text-xs font-bold rounded-full">{status}</span>;
        }
    };

    const handleView = (order: PurchaseOrder) => {
        if (!order) return;
        navigate(`/purchase/orders/${order._id || order.id}`);
    };

    const handleExportPDF = () => {
        const doc = new jsPDF();
        doc.text("Purchase Register", 14, 15);

        const tableData = displayOrders.map(o => {
            const vName = (o.vendorId && typeof o.vendorId === 'object') ? (o.vendorId.businessName || o.vendorId.name) : (o.vendor_name || 'N/A');
            return [
                new Date(o.date || o.po_date).toLocaleDateString(),
                o.purchaseNumber || o.po_number || 'N/A',
                vName || 'N/A',
                o.status,
                o.items.length.toString(),
                `Rs. ${(o.totalAmount || o.total_amount || 0).toLocaleString()}`
            ];
        });

        autoTable(doc, {
            head: [['Date', 'Number #', 'Vendor', 'Status', 'Items', 'Amount']],
            body: tableData,
            startY: 20,
        });

        doc.save('purchase_register.pdf');
    };

    const handleExportCSV = () => {
        const headers = ["Date,Number #,Vendor,Status,Items,Amount,Created By"];
        const rows = displayOrders.map(o => {
            const vName = (o.vendorId && typeof o.vendorId === 'object') ? (o.vendorId.businessName || o.vendorId.name) : (o.vendor_name || 'N/A');
            const created = (o.createdBy && typeof o.createdBy === 'object') ? o.createdBy.name : (o.created_by || '-');
            return `${new Date(o.date || o.po_date).toLocaleDateString()},${o.purchaseNumber || o.po_number},"${vName}",${o.status},${o.items.length},${o.totalAmount || o.total_amount || 0},${created}`;
        });

        const csvContent = "data:text/csv;charset=utf-8," + [headers, ...rows].join("\n");
        const encodedUri = encodeURI(csvContent);
        const link = document.createElement("a");
        link.setAttribute("href", encodedUri);
        link.setAttribute("download", "purchase_register.csv");
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
    };


    return (
        <Layout>
            <div className="space-y-6 animate-fade-in pb-10 h-full flex flex-col">
                <PageHeader
                    title="Purchase Register"
                    description="Comprehensive record and audit trail of all purchases"
                    actions={
                        <div className="flex gap-2">
                            <button onClick={handleRefresh} disabled={isRefreshing || isProcessing} className="px-3 py-2 bg-white dark:bg-neutral-800 border border-neutral-200 dark:border-neutral-700 rounded-lg hover:bg-neutral-50 dark:hover:bg-neutral-700">
                                <RefreshCw className={`w-4 h-4 ${(isRefreshing || isProcessing) ? 'animate-spin' : ''}`} />
                            </button>
                            <button onClick={handleExportCSV} className="px-3 py-2 bg-white dark:bg-neutral-800 border border-neutral-200 dark:border-neutral-700 rounded-lg text-sm font-medium hover:bg-neutral-50 dark:hover:bg-neutral-700 flex items-center gap-2">
                                <FileSpreadsheet className="w-4 h-4 text-green-600" /> Excel
                            </button>
                            <button onClick={handleExportPDF} className="px-3 py-2 bg-white dark:bg-neutral-800 border border-neutral-200 dark:border-neutral-700 rounded-lg text-sm font-medium hover:bg-neutral-50 dark:hover:bg-neutral-700 flex items-center gap-2">
                                <FileText className="w-4 h-4 text-red-600" /> PDF
                            </button>
                            <select
                                value={viewMode}
                                onChange={(e) => setViewMode(e.target.value as any)}
                                className="px-3 py-2 bg-white dark:bg-neutral-800 border border-neutral-200 dark:border-neutral-700 rounded-lg text-sm font-medium hover:bg-neutral-50 dark:hover:bg-neutral-700 outline-none focus:ring-2 focus:ring-primary/20"
                            >
                                <option value="ALL">All Orders</option>
                                <option value="BILLED">Billed / Completed</option>
                                <option value="UNBILLED">Unbilled / Pending</option>
                                <option value="DRAFT">Drafts</option>
                            </select>
                            <button
                                onClick={() => setActiveTab('PURCHASE_ENTRY')}
                                className="px-4 py-2 bg-primary text-white rounded-lg text-sm font-bold hover:bg-primary/90 flex items-center gap-2"
                            >
                                <Plus className="w-4 h-4" /> New Purchase
                            </button>
                        </div>
                    }
                />

                {/* KPI Cards */}
                <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
                    <StatsCard
                        title="Total Value"
                        value={`₹${totalPurchasesValue.toLocaleString()}`}
                        icon={<TrendingUp />}
                        iconBgColor="bg-primary/10"
                        iconColor="text-primary"
                    />
                    <StatsCard
                        title="Total Billed"
                        value={`₹${totalBilledValue.toLocaleString()}`}
                        icon={<CheckSquare />}
                        iconBgColor="bg-emerald-100 dark:bg-emerald-900/30"
                        iconColor="text-emerald-600 dark:text-emerald-400"
                    />
                    <StatsCard
                        title="Transactions"
                        value={filteredOrders.length}
                        icon={<FileText />}
                        iconBgColor="bg-neutral-100 dark:bg-neutral-700"
                        iconColor="text-neutral-600 dark:text-neutral-300"
                    />
                    <StatsCard
                        title="Pending"
                        value={pendingCount}
                        icon={<Clock />}
                        iconBgColor="bg-warning/10"
                        iconColor="text-warning"
                    />

                </div>

                {/* Advanced Filters */}
                <div className="bg-card rounded-xl border border-default p-4 flex flex-col gap-4">
                    <div className="flex flex-wrap gap-4 items-end">
                        <div className="flex-1 min-w-[200px]">
                            <label className="text-xs font-bold text-muted uppercase mb-1 block">Search</label>
                            <div className="relative">
                                <Search className="w-4 h-4 absolute left-3 top-2.5 text-muted" />
                                <input type="text" placeholder="Search PO #..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full pl-9 pr-4 py-2 bg-input border border-default rounded-lg text-sm text-main placeholder-muted focus:ring-2 focus:ring-primary focus:border-transparent outline-none" />
                            </div>
                        </div>
                        <div className="w-48">
                            <label className="text-xs font-bold text-muted uppercase mb-1 block">Vendor</label>
                            <select value={vendorFilter} onChange={e => setVendorFilter(e.target.value)} className="w-full px-3 py-2 bg-input border border-default rounded-lg text-sm text-main focus:ring-2 focus:ring-primary focus:border-transparent outline-none">
                                <option value="ALL">All Vendors</option>
                                {uniqueVendors.map(v => <option key={v} value={v}>{v}</option>)}
                            </select>
                        </div>
                        <div className="w-40">
                            <label className="text-xs font-bold text-muted uppercase mb-1 block">Status</label>
                            <select value={statusFilter} onChange={e => setStatusFilter(e.target.value)} className="w-full px-3 py-2 bg-input border border-default rounded-lg text-sm text-main focus:ring-2 focus:ring-primary focus:border-transparent outline-none">
                                <option value="ALL">All Status</option>
                                <option value="COMPLETED">Completed</option>
                                <option value="Approved">Approved</option>
                                <option value="Pending">Pending</option>
                                <option value="DRAFT">Draft</option>
                                <option value="CANCELLED">Cancelled</option>
                            </select>
                        </div>
                        <div className="w-36">
                            <label className="text-xs font-bold text-muted uppercase mb-1 block">From</label>
                            <input type="date" value={dateFrom} onChange={e => setDateFrom(e.target.value)} className="w-full px-3 py-2 bg-input border border-default rounded-lg text-sm text-main focus:ring-2 focus:ring-primary focus:border-transparent outline-none" />
                        </div>
                        <div className="w-36">
                            <label className="text-xs font-bold text-muted uppercase mb-1 block">To</label>
                            <input type="date" value={dateTo} onChange={e => setDateTo(e.target.value)} className="w-full px-3 py-2 bg-input border border-default rounded-lg text-sm text-main focus:ring-2 focus:ring-primary focus:border-transparent outline-none" />
                        </div>
                    </div>
                </div>

                {/* Table */}
                <div className="bg-card rounded-xl border border-default flex-1 flex flex-col overflow-hidden">
                    <div className="flex-1 overflow-auto custom-scrollbar">
                        <table className="w-full text-left text-sm">
                            <thead className="bg-surface text-muted uppercase text-xs font-medium sticky top-0 z-10">
                                <tr>
                                    <th className="p-4 cursor-pointer hover:bg-neutral-100 dark:hover:bg-neutral-800 transition-colors" onClick={() => handleSort('number')}>
                                        <div className="flex items-center gap-2">
                                            Number #
                                            {sortColumn === 'number' && (sortDirection === 'asc' ? <ArrowUp className="w-3 h-3 text-primary" /> : <ArrowDown className="w-3 h-3 text-primary" />)}
                                            {sortColumn !== 'number' && <ArrowUpDown className="w-3 h-3 text-neutral-300" />}
                                        </div>
                                    </th>
                                    <th className="p-4 cursor-pointer hover:bg-neutral-100 dark:hover:bg-neutral-800 transition-colors" onClick={() => handleSort('date')}>
                                        <div className="flex items-center gap-2">
                                            Date
                                            {sortColumn === 'date' && (sortDirection === 'asc' ? <ArrowUp className="w-3 h-3 text-primary" /> : <ArrowDown className="w-3 h-3 text-primary" />)}
                                            {sortColumn !== 'date' && <ArrowUpDown className="w-3 h-3 text-neutral-300" />}
                                        </div>
                                    </th>
                                    <th className="p-4 cursor-pointer hover:bg-neutral-100 dark:hover:bg-neutral-800 transition-colors" onClick={() => handleSort('vendor')}>
                                        <div className="flex items-center gap-2">
                                            Vendor
                                            {sortColumn === 'vendor' && (sortDirection === 'asc' ? <ArrowUp className="w-3 h-3 text-primary" /> : <ArrowDown className="w-3 h-3 text-primary" />)}
                                            {sortColumn !== 'vendor' && <ArrowUpDown className="w-3 h-3 text-neutral-300" />}
                                        </div>
                                    </th>
                                    <th className="p-4 cursor-pointer hover:bg-neutral-100 dark:hover:bg-neutral-800 transition-colors text-center" onClick={() => handleSort('items')}>
                                        <div className="flex items-center justify-center gap-2">
                                            Items
                                            {sortColumn === 'items' && (sortDirection === 'asc' ? <ArrowUp className="w-3 h-3 text-primary" /> : <ArrowDown className="w-3 h-3 text-primary" />)}
                                            {sortColumn !== 'items' && <ArrowUpDown className="w-3 h-3 text-neutral-300" />}
                                        </div>
                                    </th>
                                    <th className="p-4 cursor-pointer hover:bg-neutral-100 dark:hover:bg-neutral-800 transition-colors text-right" onClick={() => handleSort('amount')}>
                                        <div className="flex items-center justify-end gap-2">
                                            Amount
                                            {sortColumn === 'amount' && (sortDirection === 'asc' ? <ArrowUp className="w-3 h-3 text-primary" /> : <ArrowDown className="w-3 h-3 text-primary" />)}
                                            {sortColumn !== 'amount' && <ArrowUpDown className="w-3 h-3 text-neutral-300" />}
                                        </div>
                                    </th>
                                    <th className="p-4 cursor-pointer hover:bg-neutral-100 dark:hover:bg-neutral-800 transition-colors text-center" onClick={() => handleSort('status')}>
                                        <div className="flex items-center justify-center gap-2">
                                            Status
                                            {sortColumn === 'status' && (sortDirection === 'asc' ? <ArrowUp className="w-3 h-3 text-primary" /> : <ArrowDown className="w-3 h-3 text-primary" />)}
                                            {sortColumn !== 'status' && <ArrowUpDown className="w-3 h-3 text-neutral-300" />}
                                        </div>
                                    </th>
                                    <th className="p-4 text-center">Action</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-default">
                                {paginatedOrders.length === 0 ? (
                                    <tr><td colSpan={7} className="p-8 text-center text-muted">No records found</td></tr>
                                ) : (
                                    paginatedOrders.map(order => {
                                        let vName = '';
                                        if (order.vendorId && typeof order.vendorId === 'object') {
                                            vName = order.vendorId.businessName || order.vendorId.name || '';
                                        } else {
                                            vName = order.vendor_name || 'N/A';
                                        }

                                        return (
                                            <tr key={order._id || order.id} className="hover:bg-surface transition-colors">
                                                <td className="p-4 font-mono text-xs text-primary font-bold">
                                                    #{order.purchaseNumber || order.po_number || 'N/A'}
                                                </td>
                                                <td className="p-4 text-secondary">
                                                    <div className="flex flex-col">
                                                        <span className="font-medium text-main">
                                                            {new Date(order.date || order.po_date).toLocaleDateString()}
                                                        </span>
                                                        <span className="text-xs text-muted">
                                                            {new Date((order as any).createdAt || (order as any).created_at || order.date).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                                                        </span>
                                                    </div>
                                                </td>
                                                <td className="p-4 font-medium text-main">
                                                    {vName}
                                                </td>
                                                <td className="p-4 text-center text-secondary">{order.items.length}</td>
                                                <td className="p-4 text-right font-bold text-main">
                                                    ₹{(order.totalAmount || order.total_amount || 0).toLocaleString()}
                                                </td>
                                                <td className="p-4 text-center">{getStatusBadge(order.status)}</td>
                                                <td className="p-4 text-center">
                                                    <button onClick={() => handleView(order)} className="p-2 hover:bg-surface rounded-lg text-primary transition-colors">
                                                        <Eye className="w-4 h-4" />
                                                    </button>
                                                </td>
                                            </tr>
                                        );
                                    })
                                )}
                            </tbody>
                        </table>
                    </div>

                    {/* Pagination */}
                    <div className="p-4 border-t border-default flex items-center justify-between bg-surface">
                        <div className="text-xs text-muted">
                            Showing {((currentPage - 1) * itemsPerPage) + 1} to {Math.min(currentPage * itemsPerPage, displayOrders.length)} of {displayOrders.length} entries
                        </div>

                        <div className="flex items-center gap-2">
                            <button
                                onClick={() => setCurrentPage(p => Math.max(1, p - 1))}
                                disabled={currentPage === 1}
                                className="p-2 border border-default rounded-lg hover:bg-card disabled:opacity-50 text-main"
                            >
                                <ChevronLeft className="w-4 h-4" />
                            </button>
                            <span className="text-sm font-medium px-2 text-main">Page {currentPage} of {totalPages || 1}</span>
                            <button
                                onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))}
                                disabled={currentPage === totalPages}
                                className="p-2 border border-default rounded-lg hover:bg-card disabled:opacity-50 text-main"
                            >
                                <ChevronRight className="w-4 h-4" />
                            </button>
                        </div>
                    </div>
                </div>
            </div>
        </Layout>
    );
};

export default PurchaseRegister;

import { logger } from '@/shared/lib/logger';
import React, { useState, useEffect } from 'react';
import Layout from "@/shared/ui/Layout/Layout";
import FormInput from "@/shared/ui/Form/Input";
import SupplierSelectionModal from "@/shared/ui/Modals/SupplierSelectionModal";
import api from "@/shared/api/api";
import { toast } from 'react-toastify';
import { useNavigate } from 'react-router-dom';
import PageHeader from "@/shared/ui/Layout/PageHeader";
import {
    RotateCcw, Save, Printer, FileText, User, Phone, X,
    Trash2, Package, Calculator, CreditCard, Banknote,
    Building2, RefreshCw, FileEdit, AlertTriangle, Plus
} from 'lucide-react';
import { Supplier } from "@repo/shared";

interface ReturnItem {
    name: string;
    quantity: number;
    rate: number;
    tax: number;
    amount: number;
    reason: string;
}

interface PurchaseReturnFormData {
    debitNoteNo: string;
    debitNoteDate: string;
    originalPurchase: any;
    supplier: Supplier | null;
    items: ReturnItem[];
    refundMethod: 'credit' | 'cash' | 'bank_transfer' | 'adjust_next_bill' | string;
    discount: number;
    notes: string;
    bankAccount: string;
}

const PurchaseReturn: React.FC = () => {
    const [formData, setFormData] = useState<PurchaseReturnFormData>({
        debitNoteNo: 'DN-' + Date.now(),
        debitNoteDate: new Date().toISOString().split('T')[0],
        originalPurchase: null,
        supplier: null,
        items: [{ name: '', quantity: 1, rate: 0, tax: 18, amount: 0, reason: '' }],
        refundMethod: 'credit',
        discount: 0,
        notes: '',
        bankAccount: ''
    });
    const [showSupplierModal, setShowSupplierModal] = useState(false);
    const [bankAccounts, setBankAccounts] = useState<any[]>([]);
    const [loading, setLoading] = useState(false);
    const navigate = useNavigate();

    const refundMethods = [
        { value: 'credit', label: 'Credit Note', icon: CreditCard, color: 'indigo' },
        { value: 'cash', label: 'Cash Refund', icon: Banknote, color: 'emerald' },
        { value: 'bank_transfer', label: 'Bank Transfer', icon: Building2, color: 'blue' },
        { value: 'adjust_next_bill', label: 'Adjust Next Bill', icon: RefreshCw, color: 'purple' }
    ];

    const returnReasons = ['Damaged Product', 'Wrong Item', 'Quality Issue', 'Expired Product', 'Other'];

    useEffect(() => {
        const fetchBanks = async () => {
            try {
                const userDataString = localStorage.getItem('user');
                if (!userDataString) return;
                const userData = JSON.parse(userDataString);
                const token = userData?.token;
                const response = await api.get(
                    '/api/cashbank/accounts',
                    { headers: { Authorization: `Bearer ${token}` } }
                );
                setBankAccounts(response.data.filter((acc: any) => acc.status === 'active'));
            } catch (error) {
                logger.error('Error fetching banks:', error);
            }
        };
        fetchBanks();
    }, []);

    const addItem = () => setFormData({ ...formData, items: [...formData.items, { name: '', quantity: 1, rate: 0, tax: 18, amount: 0, reason: '' }] });

    const removeItem = (index: number) => {
        if (formData.items.length > 1) {
            const newItems = formData.items.filter((_, i) => i !== index);
            setFormData({ ...formData, items: newItems });
        }
    };

    const updateItem = (index: number, field: keyof ReturnItem, value: any) => {
        const newItems = [...formData.items];
        (newItems[index] as any)[field] = value;
        if (field === 'quantity' || field === 'rate') {
            newItems[index].amount = newItems[index].quantity * newItems[index].rate;
        }
        setFormData({ ...formData, items: newItems });
    };

    const calculateSubtotal = () => formData.items.reduce((sum, item) => sum + item.amount, 0);
    const calculateTax = () => formData.items.reduce((sum, item) => sum + (item.amount * item.tax / 100), 0);
    const calculateTotal = () => calculateSubtotal() + calculateTax() - formData.discount;

    const handleSubmit = async () => {
        if (!formData.supplier) return toast.warning('Please select a supplier');
        if (formData.items.some(item => !item.name || item.quantity <= 0)) return toast.warning('Please fill all item details');
        if (formData.refundMethod === 'bank_transfer' && !formData.bankAccount) return toast.warning('Please select a bank account');

        try {
            setLoading(true);
            const userDataString = localStorage.getItem('user');
            if (!userDataString) return;
            const userData = JSON.parse(userDataString);
            const token = userData?.token;

            await api.post(
                '/api/purchase-returns',
                {
                    supplierId: formData.supplier._id,
                    items: formData.items,
                    refundMethod: formData.refundMethod,
                    bankAccount: formData.bankAccount,
                    discount: formData.discount,
                    notes: formData.notes,
                    returnDate: formData.debitNoteDate
                },
                { headers: { Authorization: `Bearer ${token}` } }
            );

            toast.success('Purchase return processed successfully');
            navigate('/purchase/returns');
        } catch (error: any) {
            toast.error(error.response?.data?.message || 'Failed to process return');
        } finally {
            setLoading(false);
        }
    };

    const getMethodColorClasses = (color: string, isSelected: boolean) => {
        const colors: Record<string, string> = {
            indigo: isSelected ? 'border-indigo-500 bg-indigo-50 dark:bg-indigo-900/20 ring-2 ring-indigo-500/20' : 'border-slate-200 dark:border-neutral-700 hover:border-indigo-300 hover:bg-indigo-50/50',
            emerald: isSelected ? 'border-emerald-500 bg-emerald-50 dark:bg-emerald-900/20 ring-2 ring-emerald-500/20' : 'border-slate-200 dark:border-neutral-700 hover:border-emerald-300 hover:bg-emerald-50/50',
            blue: isSelected ? 'border-blue-500 bg-blue-50 dark:bg-blue-900/20 ring-2 ring-blue-500/20' : 'border-slate-200 dark:border-neutral-700 hover:border-blue-300 hover:bg-blue-50/50',
            purple: isSelected ? 'border-purple-500 bg-purple-50 dark:bg-purple-900/20 ring-2 ring-purple-500/20' : 'border-slate-200 dark:border-neutral-700 hover:border-purple-300 hover:bg-purple-50/50'
        };
        return colors[color] || colors.indigo;
    };

    return (
        <Layout>
            <div className="space-y-6 animate-fade-in pb-10">
                <PageHeader
                    title="Purchase Return / Debit Note"
                    description="Record returns and issue debit notes to suppliers"
                    actions={
                        <div className="flex gap-3">
                            <button className="btn btn-secondary bg-white dark:bg-neutral-800">
                                <Printer className="w-4 h-4" />
                                Print
                            </button>
                            <button
                                onClick={handleSubmit}
                                disabled={loading}
                                className="btn btn-primary bg-rose-600 hover:bg-rose-700"
                            >
                                <Save className="w-4 h-4" />
                                {loading ? 'Saving...' : 'Save Debit Note'}
                            </button>
                        </div>
                    }
                />

                <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                    <div className="lg:col-span-2 space-y-6">
                        <div className="bg-white dark:bg-neutral-800 border border-neutral-200 dark:border-neutral-700 rounded-2xl p-6 shadow-sm">
                            <div className="flex items-center gap-3 mb-6">
                                <div className="w-8 h-8 bg-slate-100 dark:bg-neutral-900 rounded-lg flex items-center justify-center">
                                    <FileText className="w-4 h-4 text-slate-600 dark:text-neutral-400" />
                                </div>
                                <h2 className="text-base font-semibold text-slate-900 dark:text-white">Debit Note Details</h2>
                            </div>
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                <FormInput
                                    label="Reference Number"
                                    name="debitNoteNo"
                                    placeholder="e.g. RET-001"
                                    value={formData.debitNoteNo}
                                    onChange={(e: React.ChangeEvent<HTMLInputElement>) => setFormData({ ...formData, debitNoteNo: e.target.value })}
                                    required
                                />
                                <FormInput
                                    label="Return Date"
                                    name="debitNoteDate"
                                    type="date"
                                    value={formData.debitNoteDate}
                                    onChange={(e: React.ChangeEvent<HTMLInputElement>) => setFormData({ ...formData, debitNoteDate: e.target.value })}
                                    required
                                />
                            </div>
                        </div>

                        <div className="bg-white dark:bg-neutral-800 border border-neutral-200 dark:border-neutral-700 rounded-2xl p-6 shadow-sm">
                            <div className="flex items-center gap-3 mb-6">
                                <div className="w-8 h-8 bg-slate-100 dark:bg-neutral-900 rounded-lg flex items-center justify-center">
                                    <User className="w-4 h-4 text-slate-600 dark:text-neutral-400" />
                                </div>
                                <h2 className="text-base font-semibold text-slate-900 dark:text-white">Supplier</h2>
                            </div>
                            {formData.supplier ? (
                                <div className="p-4 bg-rose-50 dark:bg-rose-900/10 border border-rose-200 dark:border-rose-800 rounded-xl">
                                    <div className="flex items-center justify-between">
                                        <div className="flex items-center gap-4">
                                            <div className="w-12 h-12 bg-white dark:bg-neutral-800 rounded-xl flex items-center justify-center shadow-sm">
                                                <span className="text-lg font-bold text-rose-700 dark:text-rose-500">
                                                    {formData.supplier.businessName?.charAt(0) || 'S'}
                                                </span>
                                            </div>
                                            <div>
                                                <p className="font-semibold text-slate-900 dark:text-white">{formData.supplier.businessName}</p>
                                                <p className="text-sm text-slate-600 dark:text-neutral-400">{formData.supplier.contactPersonName}</p>
                                                {formData.supplier.contactNo && (
                                                    <div className="flex items-center gap-1.5 mt-1 text-sm text-slate-500">
                                                        <Phone className="w-3.5 h-3.5" />
                                                        {formData.supplier.contactNo}
                                                    </div>
                                                )}
                                            </div>
                                        </div>
                                        <button
                                            onClick={() => setFormData({ ...formData, supplier: null })}
                                            className="p-2 text-red-600 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg transition-colors"
                                        >
                                            <X className="w-5 h-5" />
                                        </button>
                                    </div>
                                </div>
                            ) : (
                                <button
                                    onClick={() => setShowSupplierModal(true)}
                                    className="w-full px-4 py-8 border-2 border-dashed border-slate-200 dark:border-neutral-700 rounded-2xl text-slate-500 hover:border-rose-400 hover:text-rose-600 hover:bg-rose-50/50 dark:hover:bg-rose-900/10 transition-all flex flex-col items-center justify-center gap-3"
                                >
                                    <div className="w-12 h-12 bg-slate-50 dark:bg-neutral-800 rounded-full flex items-center justify-center">
                                        <Plus className="w-6 h-6 text-rose-500" />
                                    </div>
                                    <span className="font-medium">Click to select supplier</span>
                                </button>
                            )}
                        </div>

                        <div className="bg-white dark:bg-neutral-800 border border-neutral-200 dark:border-neutral-700 rounded-2xl p-6 shadow-sm overflow-hidden">
                            <div className="flex items-center justify-between mb-6">
                                <div className="flex items-center gap-3">
                                    <div className="w-8 h-8 bg-slate-100 dark:bg-neutral-900 rounded-lg flex items-center justify-center">
                                        <AlertTriangle className="w-4 h-4 text-slate-600 dark:text-neutral-400" />
                                    </div>
                                    <h2 className="text-base font-semibold text-slate-900 dark:text-white">Return Items</h2>
                                </div>
                                <button
                                    onClick={addItem}
                                    className="btn border border-emerald-200 text-emerald-600 hover:bg-emerald-50 py-2"
                                >
                                    <Plus className="w-4 h-4" />
                                    Add Item
                                </button>
                            </div>
                            <div className="overflow-x-auto -mx-6">
                                <table className="w-full text-left text-sm whitespace-nowrap">
                                    <thead className="bg-slate-50 dark:bg-neutral-900 border-y border-neutral-200 dark:border-neutral-700">
                                        <tr>
                                            <th className="px-6 py-3 font-semibold text-slate-500">Item</th>
                                            <th className="px-6 py-3 font-semibold text-slate-500 w-20 text-right">Qty</th>
                                            <th className="px-6 py-3 font-semibold text-slate-500 w-32 text-right">Rate</th>
                                            <th className="px-6 py-3 font-semibold text-slate-500 w-24 text-right">Tax %</th>
                                            <th className="px-6 py-3 font-semibold text-slate-500 w-32 text-right">Total</th>
                                            <th className="px-6 py-3 font-semibold text-slate-500 w-48">Reason</th>
                                            <th className="px-6 py-3 w-10"></th>
                                        </tr>
                                    </thead>
                                    <tbody className="divide-y divide-slate-100 dark:divide-neutral-800">
                                        {formData.items.map((item, index) => (
                                            <tr key={index} className="group hover:bg-slate-50/50 dark:hover:bg-neutral-800/50 transition-colors">
                                                <td className="px-6 py-3">
                                                    <input
                                                        type="text"
                                                        value={item.name}
                                                        onChange={(e) => updateItem(index, 'name', e.target.value)}
                                                        className="w-full bg-transparent outline-none font-medium border-b border-transparent focus:border-rose-500"
                                                        placeholder="Item name"
                                                    />
                                                </td>
                                                <td className="px-6 py-3">
                                                    <input
                                                        type="number"
                                                        value={item.quantity}
                                                        onChange={(e) => updateItem(index, 'quantity', parseFloat(e.target.value) || 0)}
                                                        className="w-full bg-transparent outline-none text-right font-medium"
                                                    />
                                                </td>
                                                <td className="px-6 py-3">
                                                    <input
                                                        type="number"
                                                        value={item.rate}
                                                        onChange={(e) => updateItem(index, 'rate', parseFloat(e.target.value) || 0)}
                                                        className="w-full bg-transparent outline-none text-right font-medium"
                                                    />
                                                </td>
                                                <td className="px-6 py-3">
                                                    <select
                                                        value={item.tax}
                                                        onChange={(e) => updateItem(index, 'tax', parseFloat(e.target.value))}
                                                        className="w-full bg-transparent outline-none text-right font-medium"
                                                    >
                                                        <option value="0">0%</option>
                                                        <option value="5">5%</option>
                                                        <option value="12">12%</option>
                                                        <option value="18">18%</option>
                                                        <option value="28">28%</option>
                                                    </select>
                                                </td>
                                                <td className="px-6 py-3 text-right font-bold text-slate-900 dark:text-white">
                                                    ₹{item.amount.toFixed(2)}
                                                </td>
                                                <td className="px-6 py-3">
                                                    <select
                                                        value={item.reason}
                                                        onChange={(e) => updateItem(index, 'reason', e.target.value)}
                                                        className="w-full bg-transparent outline-none font-medium text-slate-600 dark:text-neutral-400"
                                                    >
                                                        <option value="">Select reason</option>
                                                        {returnReasons.map(reason => (
                                                            <option key={reason} value={reason}>{reason}</option>
                                                        ))}
                                                    </select>
                                                </td>
                                                <td className="px-6 py-3 text-center">
                                                    <button
                                                        onClick={() => removeItem(index)}
                                                        className="p-1.5 text-slate-300 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg transition-colors opacity-0 group-hover:opacity-100"
                                                        disabled={formData.items.length === 1}
                                                    >
                                                        <Trash2 className="w-4 h-4" />
                                                    </button>
                                                </td>
                                            </tr>
                                        ))}
                                    </tbody>
                                </table>
                            </div>
                        </div>

                        <div className="bg-white dark:bg-neutral-800 border border-neutral-200 dark:border-neutral-700 rounded-2xl p-6 shadow-sm">
                            <div className="flex items-center gap-3 mb-6">
                                <div className="w-8 h-8 bg-slate-100 dark:bg-neutral-900 rounded-lg flex items-center justify-center">
                                    <CreditCard className="w-4 h-4 text-slate-600 dark:text-neutral-400" />
                                </div>
                                <h2 className="text-base font-semibold text-slate-900 dark:text-white">Refund Details</h2>
                            </div>
                            <div className="space-y-6">
                                <div>
                                    <label className="block text-xs font-bold text-slate-400 uppercase tracking-widest mb-4">Refund Method</label>
                                    <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                                        {refundMethods.map((method) => {
                                            const isSelected = formData.refundMethod === method.value;
                                            const IconComponent = method.icon;
                                            return (
                                                <button
                                                    key={method.value}
                                                    onClick={() => setFormData({ ...formData, refundMethod: method.value, bankAccount: '' })}
                                                    className={`group p-4 border-2 rounded-2xl transition-all text-center ${getMethodColorClasses(method.color, isSelected)}`}
                                                >
                                                    <div className={`w-12 h-12 mx-auto mb-3 rounded-xl flex items-center justify-center transition-colors ${isSelected ? `bg-${method.color}-100 dark:bg-${method.color}-900/30` : 'bg-slate-50 dark:bg-neutral-700'}`}>
                                                        <IconComponent className={`w-6 h-6 transition-colors ${isSelected ? `text-${method.color}-600 dark:text-${method.color}-400` : 'text-slate-400'}`} />
                                                    </div>
                                                    <div className={`text-xs font-bold uppercase tracking-wider transition-colors ${isSelected ? 'text-slate-900 dark:text-white' : 'text-slate-500'}`}>
                                                        {method.label}
                                                    </div>
                                                </button>
                                            );
                                        })}
                                    </div>
                                </div>

                                {formData.refundMethod === 'bank_transfer' && (
                                    <div className="animate-in slide-in-from-top-2">
                                        <label className="block text-sm font-medium text-slate-700 dark:text-neutral-300 mb-2">Select Bank Account</label>
                                        <select
                                            value={formData.bankAccount}
                                            onChange={(e) => setFormData({ ...formData, bankAccount: e.target.value })}
                                            className="w-full px-4 py-3 bg-slate-50 dark:bg-neutral-900 border border-slate-200 dark:border-neutral-700 rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-rose-500/20"
                                        >
                                            <option value="">Choose Bank Account</option>
                                            {bankAccounts.map(acc => (
                                                <option key={acc._id} value={acc._id}>
                                                    {acc.bankName} - ****{acc.accountNumber?.slice(-4)} (₹{acc.currentBalance?.toLocaleString()})
                                                </option>
                                            ))}
                                        </select>
                                    </div>
                                )}

                                <div>
                                    <label className="block text-sm font-medium text-slate-700 dark:text-neutral-300 mb-2">Notes</label>
                                    <textarea
                                        value={formData.notes}
                                        onChange={(e) => setFormData({ ...formData, notes: e.target.value })}
                                        rows={3}
                                        className="w-full px-4 py-3 bg-slate-50 dark:bg-neutral-900 border border-slate-200 dark:border-neutral-700 rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-rose-500/20 resize-none transition-all"
                                        placeholder="Add notes about this return..."
                                    />
                                </div>
                            </div>
                        </div>
                    </div>

                    <div className="lg:col-span-1">
                        <div className="bg-white dark:bg-neutral-800 border border-neutral-200 dark:border-neutral-700 rounded-2xl overflow-hidden shadow-lg sticky top-6">
                            <div className="bg-gradient-to-r from-rose-500 to-red-600 p-6">
                                <div className="flex items-center gap-4">
                                    <div className="w-12 h-12 bg-white/20 backdrop-blur-md rounded-xl flex items-center justify-center text-white">
                                        <Calculator className="w-6 h-6" />
                                    </div>
                                    <div>
                                        <h2 className="text-lg font-bold text-white">Return Balance</h2>
                                        <p className="text-rose-100/80 text-xs font-medium uppercase tracking-wider">Debit Note Value</p>
                                    </div>
                                </div>
                            </div>

                            <div className="p-6">
                                <div className="space-y-4 mb-8">
                                    <div className="flex justify-between items-center py-2">
                                        <span className="text-sm text-slate-500">Subtotal</span>
                                        <span className="text-sm font-medium text-slate-900 dark:text-white">₹{calculateSubtotal().toFixed(2)}</span>
                                    </div>
                                    <div className="flex justify-between items-center py-2">
                                        <span className="text-sm text-slate-500">Total Tax</span>
                                        <span className="text-sm font-medium text-slate-900 dark:text-white">₹{calculateTax().toFixed(2)}</span>
                                    </div>
                                    <div className="pt-2">
                                        <label className="block text-xs font-bold text-slate-400 uppercase tracking-widest mb-2">Discount Adjustment</label>
                                        <div className="relative">
                                            <span className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 text-sm font-bold">₹</span>
                                            <input
                                                type="number"
                                                value={formData.discount}
                                                onChange={(e) => setFormData({ ...formData, discount: parseFloat(e.target.value) || 0 })}
                                                className="w-full pl-8 pr-4 py-2.5 bg-slate-50 dark:bg-neutral-900 border border-slate-200 dark:border-neutral-700 rounded-xl text-sm focus:outline-none focus:border-rose-500"
                                            />
                                        </div>
                                    </div>
                                </div>

                                <div className="border-t border-neutral-100 dark:border-neutral-800 pt-6 mb-8 text-center">
                                    <p className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-2">Total Refund / Credit</p>
                                    <p className="text-4xl font-black text-emerald-600">₹{calculateTotal().toLocaleString()}</p>
                                </div>

                                <div className="space-y-3">
                                    <button
                                        onClick={handleSubmit}
                                        disabled={loading}
                                        className="w-full py-4 bg-gradient-to-r from-rose-600 to-red-600 text-white font-bold rounded-2xl hover:from-rose-700 hover:to-red-700 transition-all shadow-xl shadow-rose-500/20 flex items-center justify-center gap-3 disabled:opacity-50"
                                    >
                                        <Save className="w-5 h-5" />
                                        {loading ? 'Processing...' : 'Issue Debit Note'}
                                    </button>
                                    <button className="w-full py-3.5 border border-slate-200 dark:border-neutral-700 text-slate-700 dark:text-neutral-300 font-semibold rounded-2xl hover:bg-slate-50 dark:hover:bg-neutral-800 transition-colors flex items-center justify-center gap-2">
                                        <Printer className="w-4 h-4" />
                                        Print Document
                                    </button>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>

            <SupplierSelectionModal
                isOpen={showSupplierModal}
                onClose={() => setShowSupplierModal(false)}
                onSelect={(supplier: any) => setFormData({ ...formData, supplier })}
            />
        </Layout>
    );
};

export default PurchaseReturn;

import { logger } from '@/shared/lib/logger';

import React, { useState, useEffect, useMemo } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { ArrowLeft, Save, Trash2, Plus, Search, FileText, Paperclip, X, AlertCircle, CheckCircle, Clock, RotateCcw, Truck, Ban } from 'lucide-react';
import { PurchaseReturn, PurchaseReturnItem, ReturnReason, PurchaseReturnStatus, GRN, PurchaseOrder } from "@/entities/purchase/model/purchase";
import api from "@/shared/api/api";
import { toast } from 'react-toastify';

interface Props {
    onBack?: () => void;
    onSave?: (returns: Partial<PurchaseReturn>) => Promise<void>;
    initialData?: PurchaseReturn | null;
}

const PurchaseReturnForm: React.FC<Props> = ({ onBack, onSave = async () => { }, initialData }) => {
    const { id, grnId } = useParams<{ id?: string, grnId?: string }>();
    const navigate = useNavigate();

    const handleBack = () => {
        if (onBack) onBack();
        else navigate('/purchase/returns');
    };

    const [returnData, setReturnData] = useState<Partial<PurchaseReturn>>({
        return_date: new Date().toISOString().split('T')[0],
        status: 'Initiated',
        reason: 'Quality Issues',
        total_amount: 0,
        tax_amount: 0,
        attachments: [],
        items: [] as any
    });

    const [vendors, setVendors] = useState<any[]>([]);
    const [grns, setGrns] = useState<GRN[]>([]);
    const [isLoading, setIsLoading] = useState(false);

    // Fetch Return if ID exists
    useEffect(() => {
        if (id) {
            const fetchReturn = async () => {
                try {
                    const { data } = await api.get(`/api/purchase-returns/${id}`);
                    setReturnData(data);
                } catch (err) {
                    logger.error("Failed to fetch return", err);
                    toast.error("Failed to load return details");
                }
            };
            fetchReturn();
        }
    }, [id]);

    // Fetch Vendors
    useEffect(() => {
        const fetchVendors = async () => {
            try {
                const { data } = await api.get('/suppliers');
                setVendors(data || []);
            } catch (err) {
                logger.error("Failed to fetch suppliers", err);
            }
        };
        fetchVendors();
    }, []);

    // Fetch GRNs when vendor is selected
    useEffect(() => {
        if (!returnData.vendor_id) return;
        const fetchGRNs = async () => {
            try {
                const { data } = await api.get(`/api/grns?vendorId=${returnData.vendor_id}`);
                setGrns(data || []);

                if (grnId && !returnData.grn_id) {
                    const targetGrn = (data || []).find((g: any) => g.id === grnId || g._id === grnId);
                    if (targetGrn) {
                        handleGRNChange(grnId, data);
                    }
                }
            } catch (err) {
                logger.error("Failed to fetch GRNs", err);
            }
        };
        fetchGRNs();
    }, [returnData.vendor_id, grnId]);

    const handleVendorChange = (vendorId: string) => {
        const vendor = vendors.find(v => v.id === vendorId || v._id === vendorId);
        setReturnData(prev => ({
            ...prev,
            vendor_id: vendorId,
            vendor_name: vendor?.businessName || vendor?.name || '',
            grn_id: undefined,
            grn_number: undefined,
            items: []
        }));
    };

    const handleGRNChange = (selectedGrnId: string, availableGrns = grns) => {
        const grn = availableGrns.find(g => g.id === selectedGrnId || (g as any)._id === selectedGrnId);
        if (grn) {
            const returnItems: PurchaseReturnItem[] = grn.items.map(item => ({
                id: Math.random().toString(36).substr(2, 9),
                itemId: item.productId, // Ensure backend receives this for stock adjustment
                product_id: item.productId,
                product_name: item.productName,
                sku: item.sku,
                grn_quantity: item.acceptedQty,
                return_quantity: 0, // Default to 0, user specifies what to return
                rate: 0, // In real app, fetch from PO/GRN
                tax_percent: 18,
                line_total: 0
            }));

            setReturnData(prev => ({
                ...prev,
                grn_id: selectedGrnId,
                grn_number: grn.grnNumber,
                po_id: grn.poId,
                po_number: grn.poNumber,
                items: returnItems as any
            }));
        }
    };

    const updateItem = (index: number, field: keyof PurchaseReturnItem, value: any) => {
        const newItems = [...(returnData.items || [])] as PurchaseReturnItem[];
        const item = { ...newItems[index], [field]: value };

        // Validation: Return qty cannot exceed GRN qty
        if (field === 'return_quantity') {
            if (value > item.grn_quantity) {
                toast.warning(`Cannot return more than received (${item.grn_quantity})`);
                item.return_quantity = item.grn_quantity;
            }
        }

        item.line_total = item.return_quantity * item.rate;
        newItems[index] = item;
        setReturnData(prev => ({ ...prev, items: newItems as any }));
    };

    const totals = useMemo(() => {
        const subtotal = (returnData.items || []).reduce((sum, item) => sum + (item.line_total || 0), 0);
        const tax = (subtotal * 18) / 100;
        return { subtotal, tax, total: subtotal + tax };
    }, [returnData.items]);

    const handleSave = async () => {
        if (!returnData.vendor_id || !returnData.grn_id) {
            toast.warning("Vendor and GRN are required");
            return;
        }
        if ((returnData.items || []).every(i => i.return_quantity === 0)) {
            toast.warning("Please specify items to return");
            return;
        }

        setIsLoading(true);
        try {
            const payload = {
                ...returnData,
                total_amount: totals.total,
                tax_amount: totals.tax
            };
            logger.info("Saving Return:", payload);
            toast.success("Purchase Return initiated successfully");

            // Trigger Inventory Impact Notification
            toast.info("Stock levels will be adjusted upon processing.");

            navigate('/purchase/returns');
        } catch (err) {
            toast.error("Failed to save return");
        } finally {
            setIsLoading(false);
        }
    };

    const handleUpdateStatus = (newStatus: PurchaseReturnStatus) => {
        setReturnData(prev => ({ ...prev, status: newStatus }));
        toast.info(`Return status updated to ${newStatus}`);
    };

    return (
        <div className="flex flex-col h-full bg-white dark:bg-neutral-900 rounded-xl border border-neutral-200 dark:border-neutral-800 shadow-xl overflow-hidden animate-in fade-in zoom-in duration-300">
            {/* Header */}
            <div className="px-6 py-4 border-b border-neutral-200 dark:border-neutral-800 flex items-center justify-between bg-neutral-50/50 dark:bg-neutral-900/50">
                <div className="flex items-center gap-4">
                    <button onClick={handleBack} className="p-2 hover:bg-neutral-200 dark:hover:bg-neutral-800 rounded-full transition-colors">
                        <ArrowLeft className="w-5 h-5 text-neutral-600 dark:text-neutral-400" />
                    </button>
                    <div>
                        <h2 className="text-xl font-bold text-neutral-900 dark:text-white flex items-center gap-2">
                            <RotateCcw className="w-5 h-5 text-neutral-500" /> Purchase Return (Debit Note)
                        </h2>
                        <p className="text-xs text-neutral-500 font-medium tracking-tight">Return items to vendor against GRN</p>
                    </div>
                </div>
                <div className="flex items-center gap-3">
                    <button
                        onClick={handleSave}
                        disabled={isLoading}
                        className="px-6 py-2.5 bg-brand-600 hover:bg-brand-700 text-white rounded-xl font-bold shadow-lg shadow-brand-600/20 flex items-center gap-2 transition-all disabled:opacity-50"
                    >
                        <Save className="w-4 h-4" /> {isLoading ? 'Saving...' : id ? 'Update Return' : 'Finalize Return'}
                    </button>
                    <button onClick={handleBack} className="px-4 py-2.5 text-neutral-600 dark:text-neutral-400 font-semibold text-sm hover:bg-neutral-100 dark:hover:bg-neutral-800 rounded-xl transition-colors">
                        Cancel
                    </button>
                </div>
            </div>

            <div className="flex-1 overflow-y-auto p-8 custom-scrollbar">
                <div className="max-w-6xl mx-auto space-y-8">
                    {/* Return Header Details */}
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
                        <div className="md:col-span-2 space-y-6">
                            <div className="bg-white dark:bg-neutral-900 p-6 rounded-2xl border border-neutral-200 dark:border-neutral-800 shadow-sm grid grid-cols-1 md:grid-cols-2 gap-6">
                                <div>
                                    <label className="block text-xs font-bold text-neutral-500 mb-2 uppercase tracking-wider">Vendor / Supplier</label>
                                    <select
                                        value={returnData.vendor_id || ''}
                                        onChange={(e) => handleVendorChange(e.target.value)}
                                        className="w-full px-4 py-3 bg-neutral-50 dark:bg-neutral-950 border border-neutral-200 dark:border-neutral-800 rounded-xl text-sm focus:ring-2 focus:ring-brand-500/20"
                                    >
                                        <option value="">Select Vendor</option>
                                        {vendors.map(v => <option key={v._id || v.id} value={v._id || v.id}>{v.businessName || v.name}</option>)}
                                    </select>
                                </div>
                                <div>
                                    <label className="block text-xs font-bold text-neutral-500 mb-2 uppercase tracking-wider">Linked GRN</label>
                                    <select
                                        value={returnData.grn_id || ''}
                                        onChange={(e) => handleGRNChange(e.target.value)}
                                        disabled={!returnData.vendor_id}
                                        className="w-full px-4 py-3 bg-neutral-50 dark:bg-neutral-950 border border-neutral-200 dark:border-neutral-800 rounded-xl text-sm focus:ring-2 focus:ring-brand-500/20 disabled:opacity-50"
                                    >
                                        <option value="">Select GRN</option>
                                        {grns.map(g => <option key={g.id} value={g.id}>{g.grnNumber} ({new Date(g.receivedDate).toLocaleDateString()})</option>)}
                                    </select>
                                </div>
                                <div>
                                    <label className="block text-xs font-bold text-neutral-500 mb-2 uppercase tracking-wider">Return Reason</label>
                                    <select
                                        value={returnData.reason}
                                        onChange={(e) => setReturnData({ ...returnData, reason: e.target.value as ReturnReason })}
                                        className="w-full px-4 py-3 bg-neutral-50 dark:bg-neutral-950 border border-neutral-200 dark:border-neutral-800 rounded-xl text-sm focus:ring-2 focus:ring-brand-500/20"
                                    >
                                        <option value="Defective">Defective / Damaged</option>
                                        <option value="Wrong Item">Wrong Item Received</option>
                                        <option value="Excess Quantity">Excess Quantity</option>
                                        <option value="Quality Issues">Quality Issues</option>
                                        <option value="Others">Others</option>
                                    </select>
                                </div>
                                <div>
                                    <label className="block text-xs font-bold text-neutral-500 mb-2 uppercase tracking-wider">Return Date</label>
                                    <input
                                        type="date"
                                        value={returnData.return_date}
                                        onChange={(e) => setReturnData({ ...returnData, return_date: e.target.value })}
                                        className="w-full px-4 py-3 bg-neutral-50 dark:bg-neutral-950 border border-neutral-200 dark:border-neutral-800 rounded-xl text-sm focus:ring-2 focus:ring-brand-500/20"
                                    />
                                </div>
                            </div>
                        </div>

                        {/* Status / Tracking Panel */}
                        <div className="bg-brand-50/30 dark:bg-brand-900/10 p-6 rounded-2xl border border-brand-100 dark:border-brand-900/30 space-y-4">
                            <h3 className="text-xs font-bold text-brand-700 uppercase tracking-widest flex items-center gap-2">
                                <Truck className="w-4 h-4" /> Return Lifecycle
                            </h3>
                            <div className="space-y-3">
                                <div className="flex items-center justify-between text-sm">
                                    <span className="text-neutral-500">Current Status</span>
                                    <span className="px-2 py-0.5 bg-brand-100 text-brand-700 rounded-full font-bold text-[10px]">{returnData.status}</span>
                                </div>
                                {id && (
                                    <div className="grid grid-cols-2 gap-2 pt-2">
                                        <button onClick={() => handleUpdateStatus('In-Transit')} className="text-[10px] py-1.5 bg-white border border-brand-200 rounded font-bold hover:bg-brand-50">Mark In-Transit</button>
                                        <button onClick={() => handleUpdateStatus('Received by Vendor')} className="text-[10px] py-1.5 bg-white border border-brand-200 rounded font-bold hover:bg-brand-50">Mark Received</button>
                                    </div>
                                )}
                            </div>
                            <div className="pt-4 border-t border-brand-100/50">
                                <label className="block text-[10px] font-bold text-brand-600 mb-1 uppercase">Tracking Number</label>
                                <input
                                    type="text"
                                    value={returnData.tracking_number || ''}
                                    onChange={(e) => setReturnData({ ...returnData, tracking_number: e.target.value })}
                                    placeholder="Carrier tracking code..."
                                    className="w-full px-3 py-2 bg-white dark:bg-neutral-950 border border-brand-200 dark:border-brand-900/50 rounded-lg text-xs"
                                />
                            </div>
                        </div>
                    </div>

