                        vendor_name: 'Tech supplies Corp',
                        vendor_id: 'v1',
                        grn_number: 'GRN-9982',
                        grn_id: 'g1',
                        status: 'Initiated',
                        reason: 'Defective',
                        total_amount: 15400,
                        tax_amount: 2772,
                        items: [],
                        attachments: [],
                        created_at: '2024-03-20T10:00:00Z'
                    },
                    {
                        id: '2',
                        return_number: 'PR-2024-002',
                        return_date: '2024-03-18',
                        vendor_name: 'Office Mart',
