        const pendingAmount = returns.filter(r => r.status !== 'Credited').reduce((sum, r) => sum + r.total_amount, 0);
        const creditedAmount = returns.filter(r => r.status === 'Credited').reduce((sum, r) => sum + r.total_amount, 0);

        return {
            total: returns.length,
            totalAmount,
            pendingAmount,
            creditedAmount
