                                            <span className={`px-2 py-0.5 rounded-full text-[10px] font-bold border ${r.reason === 'Defective' ? 'bg-red-50 text-red-600 border-red-100' : 'bg-neutral-50 text-neutral-600 border-neutral-100'}`}>
