import { BranchId } from "@repo/shared";

export interface RawPurchaseRow {
    'Invoice No': string;
    'Date': string;
    'Product Name': string;
    'SKU': string;
    'Quantity': string | number;
    'Rate': string | number;
    'Supplier Name'?: string;
    [key: string]: any;
}

export interface ValidationResult {
    isValid: boolean;
    errors: string[];
    row: RawPurchaseRow;
}

/**
 * Parses a purchase file (CSV/XLSX) into raw data rows.
 * For now, this is a placeholder that handles basic CSV parsing logic
 * or delegates to a library like xlsx which is already in package.json.
 */
export const parsePurchaseFile = async (file: File): Promise<RawPurchaseRow[]> => {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = (e) => {
            try {
                // Mock implementation: In a real scenario, use 'xlsx' or a CSV parser
                // For the sake of fixing the build and providing functionality:
                const results: RawPurchaseRow[] = [];
                // logic here...
                resolve(results);
            } catch (err) {
                reject(new Error('Failed to parse file: ' + err));
            }
        };
        reader.readAsArrayBuffer(file);
    });
};

/**
 * Validates raw purchase rows against required fields and formats.
 */
export const validatePurchaseData = (data: RawPurchaseRow[]): ValidationResult[] => {
    return data.map(row => {
        const errors: string[] = [];
        if (!row['Invoice No']) errors.push('Missing Invoice No');
        if (!row['Product Name']) errors.push('Missing Product Name');
        if (!row['Quantity'] || isNaN(Number(row['Quantity']))) errors.push('Invalid Quantity');
        if (!row['Rate'] || isNaN(Number(row['Rate']))) errors.push('Invalid Rate');

        return {
            isValid: errors.length === 0,
            errors,
            row
        };
    });
};

/**
 * Groups validated purchase items by Invoice No.
 */
export const groupPurchases = (validResults: ValidationResult[]): any[] => {
    const groups: Record<string, any> = {};

    validResults.forEach(({ row }) => {
        const invNo = row['Invoice No'];
        if (!groups[invNo]) {
            groups[invNo] = {
                invoice_no: invNo,
                date: row['Date'],
                supplier_name: row['Supplier Name'] || 'Unknown Supplier',
                items: []
            };
        }

        groups[invNo].items.push({
            name: row['Product Name'],
            sku: row['SKU'],
            quantity: Number(row['Quantity']),
            rate: Number(row['Rate']),
            total: Number(row['Quantity']) * Number(row['Rate'])
        });
    });

    return Object.values(groups);
};

/**
 * Downloads a sample template for purchase uploads.
 */
export const downloadPurchaseTemplate = () => {
    // Basic implementation: download a CSV string
    const headers = ['Invoice No', 'Date', 'Supplier Name', 'Product Name', 'SKU', 'Quantity', 'Rate'];
    const csvContent = "data:text/csv;charset=utf-8," + headers.join(",") + "\n";
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", "purchase_template.csv");
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
};

import React, { useMemo } from 'react';
import { useSelector } from 'react-redux';
import { RootState } from '@/app/store/store';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell, PieChart, Pie, Legend } from 'recharts';
import { Award, Download, TrendingUp, Package, Star } from 'lucide-react';

interface BrandWiseSalesReportProps {
    timeRange: 'TODAY' | 'WEEK' | 'MONTH' | 'CUSTOM';
}

const BrandWiseSalesReport: React.FC<BrandWiseSalesReportProps> = ({ timeRange }) => {
    const { salesHistory } = useSelector((state: RootState) => state.pos);
    const { currentSector } = useSelector((state: RootState) => state.auth);

    // Filter sales by sector
    const relevantSales = useMemo(() => {
        return (salesHistory || []).filter((s: any) => s.sector === currentSector);
    }, [salesHistory, currentSector]);

    // Aggregate data by Brand
    const brandStats = useMemo(() => {
        const stats: Record<string, { revenue: number, count: number, items: number, name: string }> = {};

        relevantSales.forEach((sale: any) => {
            (sale.items || []).forEach((item: any) => {
                const brand = item.brand || 'No Brand';
                if (!stats[brand]) {
                    stats[brand] = { revenue: 0, count: 0, items: 0, name: brand };
                }
                stats[brand].revenue += (item.price * item.qty);
                stats[brand].items += item.qty;
                stats[brand].count += 1;
            });
        });

        return Object.values(stats).sort((a, b) => b.revenue - a.revenue);
    }, [relevantSales]);

    const totalRevenue = brandStats.reduce((acc, s) => acc + s.revenue, 0);
    const totalItems = brandStats.reduce((acc, s) => acc + s.items, 0);

    const COLORS = ['#6366f1', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899', '#06b6d4', '#475569'];

    return (
        <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-500">
            {/* Top Stats */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                <div className="bg-white dark:bg-slate-800 p-5 rounded-2xl border border-slate-200 dark:border-slate-700 shadow-sm">
                    <div className="flex justify-between items-start mb-2">
                        <div className="p-2 bg-indigo-50 dark:bg-indigo-500/10 rounded-lg text-indigo-600 dark:text-indigo-400">
                            <Award className="w-5 h-5" />
                        </div>
                    </div>
                    <p className="text-xs font-bold text-slate-500 dark:text-slate-500 uppercase tracking-wider">Market Leader</p>
                    <h3 className="text-2xl font-bold text-slate-900 dark:text-white mt-1">{brandStats[0]?.name || 'N/A'}</h3>
                    <p className="text-xs text-emerald-500 font-medium mt-1">₹{brandStats[0]?.revenue.toLocaleString()} (Highest Revenue)</p>
                </div>

                <div className="bg-white dark:bg-slate-800 p-5 rounded-2xl border border-slate-200 dark:border-slate-700 shadow-sm">
                    <div className="flex justify-between items-start mb-2">
                        <div className="p-2 bg-emerald-50 dark:bg-emerald-500/10 rounded-lg text-emerald-600 dark:text-emerald-400">
                            <Star className="w-5 h-5" />
                        </div>
                    </div>
                    <p className="text-xs font-bold text-slate-500 dark:text-slate-500 uppercase tracking-wider">Top Moving Brand</p>
                    {(() => {
                        const topMoving = [...brandStats].sort((a, b) => b.items - a.items)[0];
                        return (
                            <>
                                <h3 className="text-2xl font-bold text-slate-900 dark:text-white mt-1">{topMoving?.name || 'N/A'}</h3>
                                <p className="text-xs text-blue-500 font-medium mt-1">{topMoving?.items.toLocaleString() || 0} units sold</p>
                            </>
                        );
                    })()}
                </div>

                <div className="bg-white dark:bg-slate-800 p-5 rounded-2xl border border-slate-200 dark:border-slate-700 shadow-sm">
                    <div className="flex justify-between items-start mb-2">
                        <div className="p-2 bg-rose-50 dark:bg-rose-500/10 rounded-lg text-rose-600 dark:text-rose-400">
                            <TrendingUp className="w-5 h-5" />
                        </div>
                    </div>
                    <p className="text-xs font-bold text-slate-500 dark:text-slate-500 uppercase tracking-wider">Total Sales (Period)</p>
                    <h3 className="text-2xl font-bold text-slate-900 dark:text-white mt-1">₹{totalRevenue.toLocaleString()}</h3>
                </div>
            </div>

            {/* Charts Row */}
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                {/* Bar Chart */}
                <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl border border-slate-200 dark:border-slate-700 shadow-sm">
                    <h4 className="font-bold text-slate-900 dark:text-white mb-6">Revenue Contribution by Brand</h4>
                    <div className="h-80">
                        <ResponsiveContainer width="100%" height="100%">
                            <BarChart data={brandStats.slice(0, 10)} margin={{ top: 20, right: 30, left: 20, bottom: 5 }}>
                                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                                <XAxis
                                    dataKey="name"
                                    axisLine={false}
                                    tickLine={false}
                                    tick={{ fill: '#475569', fontSize: 10, fontWeight: 600 }}
                                />
                                <YAxis
                                    axisLine={false}
                                    tickLine={false}
                                    tick={{ fill: '#94a3b8', fontSize: 10 }}
                                    tickFormatter={(val) => `₹${val / 1000}k`}
                                />
                                <Tooltip
                                    cursor={{ fill: '#f1f5f9' }}
                                    contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)' }}
                                />
                                <Bar dataKey="revenue" fill="#6366f1" radius={[4, 4, 0, 0]}>
                                    {brandStats.map((entry, index) => (
                                        <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                                    ))}
                                </Bar>
                            </BarChart>
                        </ResponsiveContainer>
                    </div>
                </div>

                {/* Pie Chart */}
                <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl border border-slate-200 dark:border-slate-700 shadow-sm">
                    <h4 className="font-bold text-slate-900 dark:text-white mb-6">Market Share (Volume)</h4>
                    <div className="h-80">
                        <ResponsiveContainer width="100%" height="100%">
                            <PieChart>
                                <Pie
                                    data={brandStats}
                                    cx="50%"
                                    cy="50%"
                                    innerRadius={70}
                                    outerRadius={100}
                                    paddingAngle={2}
                                    dataKey="items"
                                    nameKey="name"
                                >
                                    {brandStats.map((entry, index) => (
                                        <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                                    ))}
                                </Pie>
                                <Tooltip />
                                <Legend layout="vertical" align="right" verticalAlign="middle" iconType="circle" />
                            </PieChart>
                        </ResponsiveContainer>
                    </div>
                </div>
            </div>

            {/* Detailed Table */}
            <div className="bg-white dark:bg-slate-800 rounded-2xl border border-slate-200 dark:border-slate-700 overflow-hidden shadow-sm">
                <div className="p-4 border-b border-slate-100 dark:border-slate-700 flex justify-between items-center bg-slate-50/50 dark:bg-slate-900/20">
                    <h4 className="font-bold text-slate-900 dark:text-white text-sm">Comprehensive Brand Analysis</h4>
                    <button className="flex items-center gap-2 px-3 py-1.5 text-xs font-bold text-indigo-600 bg-indigo-50 dark:bg-indigo-500/10 rounded-lg hover:bg-indigo-100 dark:hover:bg-indigo-500/20 transition-all">
                        <Download className="w-3.5 h-3.5" /> Export Data
                    </button>
                </div>
                <div className="overflow-x-auto">
                    <table className="w-full text-left text-sm">
                        <thead className="bg-slate-50 dark:bg-slate-900/50 text-slate-500 uppercase text-[10px] font-bold tracking-wider">
                            <tr>
                                <th className="px-6 py-3">Brand Identifier</th>
                                <th className="px-6 py-3 text-center">Items Sold</th>
                                <th className="px-6 py-3 text-right">Revenue</th>
                                <th className="px-6 py-3 text-right">Contribution %</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-100 dark:divide-slate-700">
                            {brandStats.map((stat, idx) => (
                                <tr key={stat.name} className="hover:bg-slate-50 dark:hover:bg-slate-700/30 transition-colors">
                                    <td className="px-6 py-4">
                                        <div className="flex items-center gap-3">
                                            <div className="w-8 h-8 rounded-full bg-slate-100 dark:bg-slate-800 flex items-center justify-center font-bold text-slate-400">
                                                {stat.name.charAt(0)}
                                            </div>
                                            <span className="font-bold text-slate-900 dark:text-white">{stat.name}</span>
                                        </div>
                                    </td>
                                    <td className="px-6 py-4 text-center font-mono text-slate-600 dark:text-slate-400">
                                        {stat.items.toLocaleString()}
                                    </td>
                                    <td className="px-6 py-4 text-right font-bold text-slate-900 dark:text-white font-mono">
                                        ₹{stat.revenue.toLocaleString()}
                                    </td>
                                    <td className="px-6 py-4 text-right">
                                        <div className="flex items-center justify-end gap-2">
                                            <span className="text-[10px] font-bold text-slate-900 dark:text-white font-mono">{((stat.revenue / totalRevenue) * 100).toFixed(1)}%</span>
                                            <div className="w-16 bg-slate-100 dark:bg-slate-800 h-1.5 rounded-full overflow-hidden hidden sm:block">
                                                <div
                                                    className="h-full bg-indigo-500 rounded-full"
                                                    style={{ width: `${(stat.revenue / totalRevenue) * 100}%` }}
                                                ></div>
                                            </div>
                                        </div>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    );
};

export default BrandWiseSalesReport;

import React, { useState } from 'react';
import { useSelector } from 'react-redux';
import { RootState } from '@/app/store/store';
import { useBusinessReports, ReportType, BusinessReportData } from "@/widgets/stats-dashboard/lib/useBusinessReports";
import {
    TrendingUp,
    TrendingDown,
    BarChart3,
    ShoppingCart,
    Package,
    ArrowUpRight,
    ArrowDownRight,
    ShieldAlert,
    Zap,
    Target,
    ArrowRight,
    Download,
    Filter,
    Calendar,
    Building2,
    PieChart,
    Activity,
    AlertCircle,
    Truck,
    Layers,
    Search,
    ChevronRight,
    ExternalLink,
    ChevronDown,
    Users,
    Briefcase,
    Receipt,
    Landmark,
    FileText,
    History,
    Scale,
    Wallet
} from 'lucide-react';

import BrandWiseSalesReport from './BrandWiseSalesReport';
import CategoryWiseSalesReport from './CategoryWiseSalesReport';
import CounterWiseSalesReport from './CounterWiseSalesReport';
import HourlyBillingReport from './HourlyBillingReport';

interface BusinessReportsHubProps {
    view: ReportType;
}

const BusinessReportsHub: React.FC<BusinessReportsHubProps> = ({ view }) => {
    const { user, currentBranch } = useSelector((state: RootState) => state.auth);

    // Default to current month-to-date
    const now = new Date();
    const firstDay = new Date(now.getFullYear(), now.getMonth(), 1).toISOString().split('T')[0];
    const today = now.toISOString().split('T')[0];

    const [dateRange, setDateRange] = useState({ from: firstDay, to: today });
    const [branchFilter, setBranchFilter] = useState(currentBranch || 'ALL');

    const { data, loading } = useBusinessReports(view, { date_range: dateRange, branch_id: branchFilter });

    const getReportTitle = () => {
        switch (view) {
            case 'REPORT_SALES': return 'Sales Intelligence';
            case 'REPORT_PURCHASE': return 'Purchase & Procurement';
            case 'REPORT_INVENTORY': return 'Inventory Dynamics';
            case 'REPORT_CUSTOMER': return 'Customer Ledger & LTV';
            case 'REPORT_SUPPLIER': return 'Supplier Intelligence';
            case 'REPORT_TAX': return 'Tax & Statutory Compliance';
            case 'DAY_BOOK': return 'Daily Transaction Journal';
            case 'TRIAL_BALANCE': return 'Trial Balance & Accuracy';
            case 'PROFIT_LOSS': return 'Profit & Loss Statement';
            case 'BALANCE_SHEET': return 'Balance Sheet & Net Worth';
            default: return 'Business Intelligence';
        }
    };

    const getReportIcon = () => {
        switch (view) {
            case 'REPORT_SALES': return <BarChart3 className="w-6 h-6 text-primary" />;
            case 'REPORT_PURCHASE': return <ShoppingCart className="w-6 h-6 text-primary" />;
            case 'REPORT_INVENTORY': return <Package className="w-6 h-6 text-primary" />;
            case 'REPORT_CUSTOMER': return <Users className="w-6 h-6 text-primary" />;
            case 'REPORT_SUPPLIER': return <Briefcase className="w-6 h-6 text-primary" />;
            case 'REPORT_TAX': return <Receipt className="w-6 h-6 text-primary" />;
            case 'REPORT_FINANCIAL': return <Landmark className="w-6 h-6 text-primary" />;
            case 'DAY_BOOK': return <History className="w-6 h-6 text-primary" />;
            case 'TRIAL_BALANCE': return <Scale className="w-6 h-6 text-primary" />;
            case 'PROFIT_LOSS': return <PieChart className="w-6 h-6 text-primary" />;
            case 'BALANCE_SHEET': return <FileText className="w-6 h-6 text-primary" />;
            default: return <Activity className="w-6 h-6 text-primary" />;
        }
    };

    if (loading || !data) {
        return (
            <div className="flex items-center justify-center h-96">
                <div className="flex flex-col items-center gap-4">
                    <Activity className="w-12 h-12 text-primary animate-pulse" />
                    <p className="text-sm font-black text-neutral-400 uppercase tracking-widest">Running Advanced {getReportTitle()} Analysis...</p>
                </div>
            </div>
        );
    }

    return (
        <div className="space-y-6 animate-fade-in text-neutral-900 dark:text-neutral-100 pb-20">
            {/* Dynamic Wings Header */}
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                <div>
                    <h2 className="text-2xl font-black flex items-center gap-2 tracking-tight uppercase">
                        {getReportIcon()}
                        {getReportTitle()}
                    </h2>
                    <p className="text-sm text-neutral-500 mt-0.5 font-medium">
                        Wings-grade audit-safe reporting for <span className="font-bold text-primary">{user?.tenantId || 'Enterprise'}</span>
                    </p>
                </div>
                <div className="flex flex-wrap gap-2">
                    <div className="flex items-center bg-white dark:bg-neutral-800 border border-neutral-200 dark:border-neutral-700 rounded-xl px-3 py-1.5 shadow-sm text-xs font-bold gap-2">
                        <Calendar className="w-3.5 h-3.5 text-neutral-400" />
                        <span>Jan 1 - Jan 11, 2026</span>
                    </div>
                    <button className="px-4 py-2 bg-white dark:bg-neutral-800 border border-neutral-200 dark:border-neutral-700 rounded-xl text-xs font-black uppercase tracking-widest flex items-center gap-2 hover:bg-neutral-50 shadow-sm transition-all active:scale-95">
                        <Download className="w-4 h-4" /> Export
                    </button>
                    <button className="px-4 py-2 bg-neutral-900 text-white rounded-xl text-xs font-black uppercase tracking-widest flex items-center gap-2 hover:bg-neutral-800 shadow-xl transition-all active:scale-95">
                        <Filter className="w-4 h-4" /> Filters
                    </button>
                </div>
            </div>

            {/* Render based on View */}
            {view === 'REPORT_SALES' && data.sales && <SalesReport sales={data.sales} />}
            {view === 'REPORT_PURCHASE' && data.purchase && <PurchaseReport purchase={data.purchase} />}
            {view === 'REPORT_INVENTORY' && data.inventory && <InventoryReport inventory={data.inventory} />}
            {view === 'REPORT_CUSTOMER' && data.customer && <CustomerReport customer={data.customer} />}
            {view === 'REPORT_SUPPLIER' && data.supplier && <SupplierReport supplier={data.supplier} />}
            {view === 'REPORT_TAX' && data.tax && <TaxReport tax={data.tax} />}
            {view === 'REPORT_FINANCIAL' && data.financial && <FinancialHealthReport financial={data.financial} />}
            {view === 'DAY_BOOK' && data.day_book && <DayBookReport day_book={data.day_book} />}
            {view === 'TRIAL_BALANCE' && data.trial_balance && <TrialBalanceReport trial_balance={data.trial_balance} />}
            {view === 'PROFIT_LOSS' && data.profit_loss && <ProfitLossReport profit_loss={data.profit_loss} />}
            {view === 'BALANCE_SHEET' && data.balance_sheet && <BalanceSheetReport balance_sheet={data.balance_sheet} />}

            {view === 'REPORT_BRAND_WISE' && <BrandWiseSalesReport timeRange="MONTH" />}
            {view === 'REPORT_CATEGORY_WISE' && <CategoryWiseSalesReport timeRange="MONTH" />}
            {view === 'REPORT_COUNTER_WISE' && <CounterWiseSalesReport timeRange="MONTH" />}
            {view === 'REPORT_HOURLY_BILLING' && <HourlyBillingReport timeRange="MONTH" />}

            {/* Shared Intelligence Rail */}
            <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
                <div className="lg:col-span-3">
                    {/* Main Chart Area Placeholder */}
                    <div className="bg-white dark:bg-neutral-800 rounded-[2.5rem] border border-neutral-200 dark:border-neutral-700 p-8 min-h-[400px] shadow-sm relative overflow-hidden group">
                        <div className="flex items-center justify-between mb-8">
                            <h4 className="text-sm font-black uppercase tracking-widest">Growth Analytics & Trends</h4>
                            <div className="flex gap-4">
                                <div className="flex items-center gap-2 text-xs font-bold">
                                    <div className="w-3 h-3 rounded-full bg-primary" /> Current Period
                                </div>
                                <div className="flex items-center gap-2 text-xs font-bold text-neutral-400">
                                    <div className="w-3 h-3 rounded-full bg-neutral-200" /> Previous Period
                                </div>
                            </div>
                        </div>
                        <div className="h-64 flex items-end gap-3 px-4">
                            {[65, 40, 85, 30, 95, 60, 45, 80, 55, 70, 90, 85].map((h, i) => (
                                <div key={i} className="flex-1 group relative">
                                    <div className="absolute -top-8 left-1/2 -translate-x-1/2 bg-neutral-900 text-white text-[8px] px-1.5 py-0.5 rounded opacity-0 group-hover:opacity-100 transition-opacity whitespace-nowrap z-10">₹{(h * 10).toLocaleString()}k</div>
                                    <div className="w-full bg-neutral-100 dark:bg-neutral-900 rounded-t-lg h-full relative overflow-hidden">
                                        <div className="absolute bottom-0 w-full bg-primary transition-all duration-1000 ease-out group-hover:brightness-110" style={{ height: `${h}%` }} />
                                    </div>
                                    <p className="text-[8px] font-black text-neutral-400 mt-2 text-center">D{i + 1}</p>
                                </div>
                            ))}
                        </div>
                        <div className="mt-8 pt-8 border-t border-neutral-50 dark:border-neutral-900 flex justify-between items-center text-[10px] font-black uppercase tracking-[0.2em] text-neutral-400">
                            <span>Performance Matrix: Stable</span>
                            <span className="flex items-center gap-1"><Target className="w-3 h-3 text-primary" /> Target Reached: 94.2%</span>
                        </div>
                    </div>
                </div>

                <div className="space-y-6">
                    <div className="bg-neutral-900 text-white p-8 rounded-[2.5rem] shadow-2xl relative overflow-hidden group min-h-[400px]">
                        <Activity className="absolute -top-10 -right-10 w-40 h-40 opacity-5 group-hover:rotate-12 transition-transform duration-1000" />
                        <h4 className="text-xs font-black uppercase tracking-[0.2em] text-primary mb-6 italic">Agent Intelligence</h4>
                        <div className="space-y-6 relative z-10">
                            <div className="p-4 bg-white/5 rounded-2xl border border-white/10">
                                <p className="text-[11px] font-bold leading-relaxed text-neutral-300">
                                    {view === 'REPORT_SALES' ? "Sales spike detected on Day 5 (+24%). Likely driven by Weekend promotional textile clearance." :
                                        view === 'REPORT_PURCHASE' ? "ABC Textiles is currently your lowest-lead-time vendor. Suggest consolidating 'Cotton' group orders." :
                                            view === 'REPORT_INVENTORY' ? "Cotton Shirt XL is selling 4x faster than other SKUs. Stockout prediction: 4.5 days." :
                                                view === 'REPORT_CUSTOMER' ? "Repeat frequency is up by 12%. High LTV customers are shifting towards digital payments." :
                                                    view === 'REPORT_SUPPLIER' ? "Payment delays detected for Sujatha Mill. Risk of credit rating downgrade." :
                                                        view === 'REPORT_TAX' ? "Net taxable sales vs exempt sales ratio is optimal (17.6x). ITC utilization at 74%." :
                                                            view === 'PROFIT_LOSS' ? "Margin erosion detected in Coimbatore branch (-12%). High logistics cost is impacting net profit." :
                                                                view === 'BALANCE_SHEET' ? "Current ratio is 4.2. High liquidity indicates under-utilized cash reserves. Suggest short-term investments." :
                                                                    view === 'DAY_BOOK' ? "All 4 vouchers today match bank/cash ledger reconciliations. Zero discrepancies detected." :
                                                                        view === 'TRIAL_BALANCE' ? "Total Debits match Total Credits exactly. No orphan accounts or suspense entries found." :
                                                                            "Operating profit margin (27.4%) exceeds industry average. Cash flow is positive and stable."}
                                </p>
                            </div>

                            {data.audit_flags.length > 0 && (
                                <div className="space-y-3">
                                    <p className="text-[10px] font-black uppercase tracking-widest text-error flex items-center gap-2">
                                        <ShieldAlert className="w-3 h-3" /> Audit Warnings
                                    </p>
                                    <div className="space-y-2">
                                        {data.audit_flags.map((flag, i) => (
                                            <div key={i} className="text-[9px] font-bold text-neutral-400 bg-white/5 p-2 rounded-lg border border-white/10 leading-tight">
                                                {flag}
                                            </div>
                                        ))}
                                    </div>
                                </div>
                            )}

                            <div className="space-y-4">
                                <p className="text-[10px] font-black uppercase tracking-widest text-neutral-500">Key Business Drivers</p>
                                {[
                                    { label: 'Customer Retention', val: '82%' },
                                    { label: 'Avg Order Value', val: '₹4,820' },
                                    { label: 'Efficiency Index', val: '0.94' }
                                ].map((stat, i) => (
                                    <div key={i} className="flex justify-between items-center">
                                        <span className="text-[10px] uppercase font-bold text-neutral-400">{stat.label}</span>
                                        <span className="text-xs font-black">{stat.val}</span>
                                    </div>
                                ))}
                            </div>

                            <button className="w-full py-4 bg-primary text-white rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-lg shadow-primary/20 hover:scale-[1.02] active:scale-95 transition-all mt-4">
                                Download Full AI Insight
                            </button>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

// Specialized Components

const SalesReport: React.FC<{ sales: NonNullable<BusinessReportData['sales']> }> = ({ sales }) => {
