                        Business Intelligence
                    </h1>
                    <p className="text-slate-500 dark:text-slate-400 mt-2 font-medium">Complete structured catalog of financial & operational analytics.</p>
                </div>

                {activeTab !== 'custom' && (
                    <div className="flex items-center gap-3">
                        <div className="relative group flex-1 lg:w-72">
                            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 group-focus-within:text-indigo-500 transition-colors" />
                            <input
                                type="text"
                                placeholder="Search reports..."
                                value={searchQuery}
                                onChange={(e) => setSearchQuery(e.target.value)}
                                className="w-full bg-white dark:bg-slate-800 border-none ring-1 ring-slate-200 dark:ring-slate-700 focus:ring-2 focus:ring-indigo-500 rounded-xl py-2.5 pl-10 pr-4 text-sm transition-all shadow-sm"
                            />
                        </div>
                    </div>
                )}
            </div>

            {/* Tab Navigation */}
            <div className="flex flex-wrap gap-2 border-b border-slate-200 dark:border-slate-800 pb-px">
                {TABS.map((tab) => (
                    <button
                        key={tab.id}
                        onClick={() => setActiveTabLocal(tab.id)}
                        className={`group relative flex items-center gap-2 px-6 py-4 text-sm font-black uppercase tracking-widest transition-all ${activeTab === tab.id
                            ? 'text-indigo-600'
                            : 'text-slate-500 hover:text-slate-700 dark:hover:text-slate-300'
                            }`}
                    >
                        {tab.title}
                        {activeTab === tab.id && (
                            <div className="absolute bottom-0 left-0 right-0 h-0.5 bg-indigo-600 animate-in fade-in slide-in-from-bottom-1" />
                        )}
                        <span className={`ml-1 px-1.5 py-0.5 rounded-md text-[10px] font-bold transition-colors ${activeTab === tab.id
                            ? 'bg-indigo-50 text-indigo-600'
                            : 'bg-slate-100 dark:bg-slate-800'
                            }`}>
                            {tab.count}
                        </span>
                    </button>
                ))}
            </div>

            {/* Catalog Content (Tab Panel) */}
            <div className="min-h-[400px]">
                {activeTab === 'custom' ? (
                    <div className="animate-in fade-in zoom-in-95 duration-700">
                        <div className="relative overflow-hidden rounded-[3rem] bg-slate-900 border border-slate-800 p-8 lg:p-16 text-white shadow-2xl">
                            <div className="absolute top-0 right-0 w-[500px] h-[500px] bg-indigo-600/20 blur-[120px] rounded-full -mr-64 -mt-64" />
                            <div className="absolute bottom-0 left-0 w-80 h-80 bg-blue-600/10 blur-[100px] rounded-full -ml-40 -mb-40" />

                            <div className="relative z-10 flex flex-col lg:flex-row items-center justify-between gap-12">
                                <div className="max-w-2xl text-center lg:text-left">
                                    <div className="flex items-center justify-center lg:justify-start gap-3 mb-6">
                                        <div className="p-2 bg-indigo-500/20 rounded-lg border border-indigo-500/30">
                                            <Cpu className="w-5 h-5 text-indigo-400" />
                                        </div>
                                        <span className="text-xs font-black uppercase tracking-[0.3em] text-indigo-400">Development Lab</span>
                                    </div>

                                    <h2 className="text-4xl lg:text-5xl font-black mb-6 tracking-tight leading-[1.1]">
                                        Need <span className="text-transparent bg-clip-text bg-gradient-to-r from-indigo-400 to-blue-400">Custom Reports?</span>
                                    </h2>

                                    <p className="text-slate-400 text-lg lg:text-xl font-medium leading-relaxed max-w-xl">
                                        Our engineers can build specialized reports tailored to your unique business requirements.
                                        From custom GST calculations to complex supply chain analytics.
                                    </p>

                                    <div className="mt-10 flex flex-wrap justify-center lg:justify-start gap-4">
                                        <div className="flex items-center gap-2 px-5 py-2.5 bg-slate-800/40 rounded-2xl border border-slate-700/50 text-xs font-bold text-slate-300 backdrop-blur-sm">
                                            <Sparkles className="w-3 h-3 text-indigo-400" />
                                            Tailored KPIs
                                        </div>
                                        <div className="flex items-center gap-2 px-5 py-2.5 bg-slate-800/40 rounded-2xl border border-slate-700/50 text-xs font-bold text-slate-300 backdrop-blur-sm">
                                            <Download className="w-3 h-3 text-indigo-400" />
                                            Automated Exports
                                        </div>
                                        <div className="flex items-center gap-2 px-5 py-2.5 bg-slate-800/40 rounded-2xl border border-slate-700/50 text-xs font-bold text-slate-300 backdrop-blur-sm">
                                            <Lock className="w-3 h-3 text-indigo-400" />
                                            Role-Based Access
                                        </div>
                                    </div>
                                </div>

                                <div className="flex-shrink-0">
                                    <button className="px-12 py-6 bg-white text-slate-900 rounded-[2.5rem] font-black uppercase tracking-widest text-sm hover:scale-105 active:scale-95 transition-all shadow-2xl shadow-indigo-500/10 flex items-center gap-4 group">
                                        Request Report
                                        <ArrowRight className="w-5 h-5 group-hover:translate-x-2 transition-transform" />
                                    </button>
                                </div>
                            </div>
                        </div>

                        {/* Enterprise Trust Badges */}
                        <div className="mt-12 grid grid-cols-2 md:grid-cols-4 gap-4 opacity-40 grayscale group-hover:grayscale-0 transition-all">
                            {['Data Integrity', 'GDPR Compliant', 'Real-time Sync', 'Audit Ready'].map(badge => (
                                <div key={badge} className="flex items-center justify-center gap-2 p-4 border border-dashed border-slate-200 dark:border-slate-800 rounded-2xl">
                                    <div className="w-1.5 h-1.5 rounded-full bg-slate-400" />
                                    <span className="text-[10px] font-black uppercase tracking-widest">{badge}</span>
                                </div>
                            ))}
                        </div>
                    </div>
                ) : filteredReports.length > 0 ? (
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6 animate-in fade-in duration-500">
                        {filteredReports.map((report: any) => (
                            <ReportCard key={report.id} report={report} categoryId={activeTab} />
                        ))}
                    </div>
                ) : (
                    <div className="flex flex-col items-center justify-center py-20 text-slate-400 bg-slate-50/50 dark:bg-slate-800/30 rounded-[2rem] border-2 border-dashed border-slate-200 dark:border-slate-800">
                        <Search className="w-12 h-12 mb-4 opacity-10" />
                        <p className="font-bold text-sm uppercase tracking-widest opacity-40">No reports matching your search</p>
                    </div>
                )}
            </div>
        </div>
    );
};

export default ReportsModule;

import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useDispatch, useSelector } from 'react-redux';
import { toast } from 'react-toastify';
import Layout from "@/shared/ui/Layout/Layout";
import PageHeader from "@/shared/ui/Layout/PageHeader";
import FormInput from "@/shared/ui/Form/Input";
import CustomerSelectionModal from "@/shared/ui/Modals/CustomerSelectionModal";
import ItemSelectionModal from "@/shared/ui/Modals/ItemSelectionModal";
import SalesOrderSelectionModal from "@/shared/ui/Modals/SalesOrderSelectionModal";
import { createDeliveryChallan, reset } from "@/app/store/slices/deliveryChallanSlice";

import { RootState } from '@/app/store/store';

interface ChallanItem {
    item: string;
    name: string;
    sku: string;
    quantity: number;
    deliveredQty: number;
    unit: string;
    description: string;
    availableStock: number;
    sellingPrice: number;
}

interface ChallanFormData {
    challanNo: string;
    challanDate: string;
    deliveryDate: string;
    customer: any;
    salesOrder: any;
    items: ChallanItem[];
    vehicleNo: string;
    driverName: string;
    transportMode: string;
    notes: string;
}

const DeliveryChallan = () => {
    const navigate = useNavigate();
    const dispatch = useDispatch<any>();
    const { isLoading, isSuccess, isError, message, challan } = useSelector((state: RootState) => state.deliveryChallan);

    const [showCustomerModal, setShowCustomerModal] = useState(false);
    const [showItemModal, setShowItemModal] = useState(false);
    const [showSalesOrderModal, setShowSalesOrderModal] = useState(false);
    const [formData, setFormData] = useState<ChallanFormData>({
        challanNo: 'DC-' + Date.now(),
        challanDate: new Date().toISOString().split('T')[0],
        deliveryDate: '',
        customer: null,
        salesOrder: null,
        items: [],
        vehicleNo: '',
        driverName: '',
        transportMode: 'road',
        notes: ''
    });

    useEffect(() => {
        if (isError) {
            toast.error(message);
            dispatch(reset());
        }

        if (isSuccess && challan) {
            toast.success('Delivery Challan created successfully!');

            // Reset Redux state BEFORE navigation
            dispatch(reset());

            // Reset form state
            setFormData({
                challanNo: 'DC-' + Date.now(),
                challanDate: new Date().toISOString().split('T')[0],
                deliveryDate: '',
                customer: null,
                salesOrder: null,
                items: [],
                vehicleNo: '',
                driverName: '',
                transportMode: 'road',
                notes: ''
            });

            // Navigate to detail page
            navigate(`/sales/delivery-challan/${challan._id}`);
        }
    }, [isError, isSuccess, message, challan, navigate, dispatch]);

    const handleSalesOrderSelect = (order: any) => {
        // Auto-populate customer and items from sales order
        const orderItems = order.items.map((item: any) => ({
            item: item.item._id || item.item,
            name: item.item.name || 'Unknown',
            sku: item.item.sku || '',
            quantity: item.quantity,
            deliveredQty: item.quantity - (item.deliveredQty || 0), // Remaining quantity
            unit: item.item.unit || 'pcs',
            description: '',
            availableStock: item.item.stock || 0,
            sellingPrice: item.rate
        }));

        setFormData({
            ...formData,
            customer: order.customer,
            salesOrder: order._id,
            items: orderItems,
            deliveryDate: order.expectedDeliveryDate ? new Date(order.expectedDeliveryDate).toISOString().split('T')[0] : ''
        });

        toast.success(`Loaded ${orderItems.length} items from Sales Order ${order.orderNumber}`);
    };

    const handleItemSelect = (item: any) => {
        const newItem = {
            item: item._id,
            name: item.name,
            sku: item.sku,
            quantity: item.quantity,
            deliveredQty: item.quantity,
            unit: item.unit || 'pcs',
            description: '',
            availableStock: item.stockQty - (item.reservedStock || 0),
            sellingPrice: item.sellingPrice
        };

        setFormData({
            ...formData,
            items: [...formData.items, newItem]
        });
    };

    const updateItem = (index: number, field: string, value: any) => {
        const newItems = [...formData.items];
        (newItems[index] as any)[field] = value;

        // Validate deliveredQty doesn't exceed available stock
        if (field === 'deliveredQty') {
            const maxQty = newItems[index].availableStock;
            if (value > maxQty) {
                toast.warning(`Cannot deliver more than available stock (${maxQty})`);
                (newItems[index] as any)[field] = maxQty;
            }
        }

        setFormData({ ...formData, items: newItems });
    };

    const removeItem = (index: number) => {
        const newItems = formData.items.filter((_, i) => i !== index);
        setFormData({ ...formData, items: newItems });
    };

    const handleSave = () => {
        // Validation
        if (!formData.customer) {
            toast.error('Please select a customer');
            return;
        }

        if (formData.items.length === 0) {
            toast.error('Please add at least one item');
            return;
        }

        // Check all items have deliveredQty > 0
        const invalidItems = formData.items.filter(item => !item.deliveredQty || item.deliveredQty <= 0);
        if (invalidItems.length > 0) {
            toast.error('All items must have a delivered quantity greater than 0');
            return;
        }

        // Prepare data for API
        const challanData = {
            customerId: formData.customer._id,
            challanDate: formData.challanDate,
            deliveryDate: formData.deliveryDate || undefined,
            salesOrderId: formData.salesOrder || undefined,
            items: formData.items.map(item => ({
                item: item.item,
                quantity: item.quantity,
                deliveredQty: item.deliveredQty,
                unit: item.unit,
                description: item.description
            })),
            vehicleNo: formData.vehicleNo,
            driverName: formData.driverName,
            transportMode: formData.transportMode,
            notes: formData.notes
        };

        dispatch(createDeliveryChallan(challanData) as any);
    };

    const totalItems = formData.items.length;
    const totalQuantity = formData.items.reduce((sum: number, item: any) => sum + (item.deliveredQty || 0), 0);

    return (
        <Layout>
            <div className="flex flex-col h-[calc(100vh-theme(spacing.16))] bg-app">
                {/* ERP Header Action Bar */}
                <div className="bg-card border-b border-default px-6 py-3 flex items-center justify-between shadow-sm shrink-0">
                    <div>
                        <h1 className="text-xl font-bold text-main">Delivery Challan</h1>
                        <p className="text-xs text-secondary">Create and manage delivery documents</p>
                    </div>
                    <div className="flex items-center gap-3">
                        <button
                            onClick={() => navigate('/sales/delivery-challan-list')}
                            className="px-4 py-1.5 text-sm font-bold text-secondary bg-card border border-default rounded-lg hover:bg-surface transition-all btn-interactive"
                        >
                            Cancel
                        </button>
                        <button
                            onClick={handleSave}
                            disabled={isLoading}
                            className="px-6 py-1.5 text-sm font-bold text-white bg-primary border border-transparent rounded-lg shadow-lg shadow-primary/25 hover:bg-primary-hover focus:ring-2 focus:ring-offset-2 focus:ring-primary disabled:opacity-50 flex items-center gap-2 transition-all btn-interactive"
                        >
                            {isLoading && (
                                <svg className="animate-spin h-4 w-4 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                                    <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                                    <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                                </svg>
                            )}
                            {isLoading ? 'Saving...' : 'Save Challan'}
                        </button>
                    </div>
                </div>

                {/* Main Content Scrollable Area */}
                <div className="flex-1 overflow-auto p-6">
                    <div className="max-w-7xl mx-auto space-y-6">
                        {/* Top Section: Basic Info & Customer - ERP Grid Style */}
                        <div className="bg-card border border-default rounded-xl shadow-sm overflow-hidden">
                            <div className="bg-surface px-4 py-2 border-b border-default flex justify-between items-center">
                                <h2 className="text-sm font-bold text-main uppercase tracking-wide">Document Details</h2>
                                <div className="text-xs text-secondary font-medium">
                                    {formData.salesOrder && <span className="bg-primary-soft text-primary px-2 py-0.5 rounded border border-primary/20">Linked to SO</span>}
                                </div>
                            </div>
                            <div className="p-4 grid grid-cols-1 md:grid-cols-4 gap-6">
                                {/* Column 1: Challan Info */}
                                <div className="space-y-4">
                                    <div>
                                        <label className="block text-xs font-bold text-secondary mb-1 uppercase tracking-wider">Challan No.</label>
                                        <input
                                            type="text"
                                            value={formData.challanNo}
                                            disabled
                                            className="w-full px-3 py-1.5 bg-input border border-default rounded-lg text-sm font-bold text-main focus:outline-none opacity-80"
                                        />
                                    </div>
                                    <div>
                                        <label className="block text-xs font-bold text-secondary mb-1 uppercase tracking-wider">Challan Date <span className="text-rose-500">*</span></label>
                                        <input
                                            value={formData.challanDate}
                                            onChange={(e: React.ChangeEvent<HTMLInputElement>) => setFormData({ ...formData, challanDate: e.target.value })}
                                            className="w-full px-3 py-1.5 bg-input border border-default rounded-lg text-sm font-medium text-main focus:ring-2 focus:ring-primary focus:border-transparent transition-all"
                                        />
                                    </div>
                                </div>

                                {/* Column 2: Logistics Date */}
                                <div>
                                    <label className="block text-xs font-bold text-secondary mb-1 uppercase tracking-wider">Delivery Expected</label>
                                    <input
                                        type="date"
                                        value={formData.deliveryDate}
                                        onChange={(e) => setFormData({ ...formData, deliveryDate: e.target.value })}
                                        className="w-full px-3 py-1.5 bg-input border border-default rounded-lg text-sm font-medium text-main focus:ring-2 focus:ring-primary focus:border-transparent transition-all"
                                    />
                                </div>

                                {/* Column 3 & 4: Customer Panel */}
                                <div className="md:col-span-2 border border-default rounded-xl bg-surface/30 p-4 relative group transition-all hover:bg-surface/50">
                                    <label className="block text-xs font-bold text-primary mb-3 uppercase tracking-wider">Customer</label>
                                    {formData.customer ? (
                                        <div className="flex justify-between items-start">
                                            <div>
                                                <p className="font-bold text-main text-base">{formData.customer.name}</p>
                                                <p className="text-xs text-secondary mt-1 font-medium">{formData.customer.address?.line1}, {formData.customer.address?.city}</p>
                                                <div className="flex gap-3 mt-3 text-xs text-secondary font-medium">
                                                    <span>Ph: {formData.customer.phone}</span>
                                                    {formData.customer.email && <span>• {formData.customer.email}</span>}
                                                </div>
                                            </div>
                                            <button
                                                onClick={() => setFormData({ ...formData, customer: null, salesOrder: null, items: [] })}
                                                className="text-rose-600 hover:text-rose-700 text-xs font-bold border border-rose-200 bg-card px-3 py-1.5 rounded-lg hover:bg-rose-50 transition-all btn-interactive"
                                            >
                                                Change
                                            </button>
                                        </div>
                                    ) : (
                                        <div className="h-full flex flex-col items-center justify-center gap-3 py-2">
                                            <p className="text-sm text-secondary font-medium">No customer selected</p>
                                            <div className="flex gap-3">
                                                <button
                                                    onClick={() => setShowCustomerModal(true)}
                                                    className="px-4 py-2 bg-card border border-primary text-primary text-xs font-bold rounded-lg hover:bg-primary-soft shadow-sm transition-all btn-interactive"
                                                >
                                                    Find Customer
                                                </button>
                                                <span className="text-muted text-xs flex items-center font-bold">OR</span>
                                                <button
                                                    onClick={() => setShowSalesOrderModal(true)}
                                                    className="px-4 py-2 bg-primary border border-transparent text-white text-xs font-bold rounded-lg hover:bg-primary-hover shadow-lg shadow-primary/20 transition-all btn-interactive"
                                                >
                                                    Select from Sales Order
                                                </button>
                                            </div>
                                        </div>
                                    )}
                                </div>
                            </div>
                        </div>

                        {/* Items Section - Dense Table */}
                        <div className="bg-card border border-default rounded-xl shadow-sm overflow-hidden flex flex-col min-h-[300px]">
                            <div className="px-4 py-2 border-b border-default bg-surface flex justify-between items-center">
                                <h2 className="text-sm font-bold text-main uppercase tracking-wide">Items & Quantities</h2>
                                <button
                                    onClick={() => setShowItemModal(true)}
                                    className="px-4 py-1.5 bg-emerald-600 text-white text-xs font-bold rounded-lg hover:bg-emerald-700 flex items-center gap-2 shadow-lg shadow-emerald-600/20 transition-all btn-interactive"
                                >
                                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" />
                                    </svg>
                                    Add Item
                                </button>
                            </div>

                            <div className="flex-1 overflow-x-auto">
                                <table className="w-full text-left border-collapse">
                                    <thead>
                                        <tr className="bg-surface border-b border-default">
                                            <th className="px-4 py-3 text-xs font-bold text-secondary uppercase border-r border-default w-12 text-center tracking-wider">#</th>
                                            <th className="px-4 py-3 text-xs font-bold text-secondary uppercase border-r border-default tracking-wider">Item Details</th>
                                            <th className="px-4 py-3 text-xs font-bold text-secondary uppercase border-r border-default w-24 text-right tracking-wider">Stock</th>
                                            <th className="px-4 py-3 text-xs font-bold text-secondary uppercase border-r border-default w-32 text-right tracking-wider">Delivery Qty</th>
                                            <th className="px-4 py-3 text-xs font-bold text-secondary uppercase border-r border-default w-20 tracking-wider">Unit</th>
                                            <th className="px-4 py-3 text-xs font-bold text-secondary uppercase border-r border-default tracking-wider">Description</th>
                                            <th className="px-4 py-3 text-xs font-bold text-secondary uppercase w-16 text-center tracking-wider">Action</th>
                                        </tr>
                                    </thead>
                                    <tbody className="divide-y divide-default">
                                        {formData.items.length === 0 ? (
                                            <tr>
                                                <td colSpan={7} className="px-4 py-16 text-center text-muted font-medium italic">
                                                    Start adding items to create the challan
                                                </td>
                                            </tr>
                                        ) : (
                                            formData.items.map((item, index) => (
                                                <tr key={index} className="hover:bg-surface transition-colors group">
                                                    <td className="px-4 py-3 text-xs text-secondary font-bold text-center border-r border-default bg-surface/30">
                                                        {index + 1}
                                                    </td>
                                                    <td className="px-4 py-3 border-r border-default font-medium">
                                                        <p className="text-sm font-bold text-main">{item.name}</p>
                                                        {item.sku && <p className="text-[10px] text-muted font-bold mt-0.5 tracking-tight">SKU: {item.sku}</p>}
                                                    </td>
                                                    <td className="px-4 py-3 border-r border-default text-right">
                                                        <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full uppercase tracking-tighter ${item.availableStock > 0 ? 'bg-emerald-50 text-emerald-700 dark:bg-emerald-900/20' : 'bg-rose-50 text-rose-700 dark:bg-rose-900/20'
                                                            }`}>
                                                            {item.availableStock} in stock
                                                        </span>
                                                    </td>
                                                    <td className="px-4 text-right border-r border-default p-2">
                                                        <input
                                                            type="number"
                                                            min="0"
                                                            max={item.availableStock}
                                                            value={item.deliveredQty}
                                                            onChange={(e) => updateItem(index, 'deliveredQty', parseFloat(e.target.value) || 0)}
                                                            className={`w-full text-right px-3 py-1.5 text-sm font-bold border rounded-lg focus:ring-2 focus:ring-primary focus:outline-none transition-all ${!item.deliveredQty || item.deliveredQty <= 0 ? 'border-rose-300 bg-rose-50 dark:bg-rose-900/10' : 'border-default bg-input'}`}
                                                        />
                                                    </td>
                                                    <td className="px-4 py-3 text-xs text-secondary font-bold border-r border-default">
                                                        {item.unit}
                                                    </td>
                                                    <td className="px-4 p-2 border-r border-default">
                                                        <input
                                                            type="text"
                                                            value={item.description}
                                                            onChange={(e) => updateItem(index, 'description', e.target.value)}
                                                            placeholder="Add remarks..."
                                                            className="w-full px-3 py-1.5 text-xs font-medium border border-transparent hover:border-default focus:border-primary rounded-lg focus:outline-none transition-all bg-transparent focus:bg-input text-main"
                                                        />
                                                    </td>
                                                    <td className="px-4 py-3 text-center">
                                                        <button
                                                            onClick={() => removeItem(index)}
                                                            className="text-muted hover:text-rose-600 transition-all p-1.5 hover:bg-rose-50 dark:hover:bg-rose-900/20 rounded-lg"
                                                            title="Remove Item"
                                                        >
                                                            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
                                                            </svg>
                                                        </button>
                                                    </td>
                                                </tr>
                                            ))
                                        )}
                                    </tbody>
                                    {formData.items.length > 0 && (
                                        <tfoot className="bg-surface border-t border-default">
                                            <tr>
                                                <td colSpan={3} className="px-4 py-3 text-xs font-bold text-right text-secondary uppercase border-r border-default tracking-wider">Totals:</td>
                                                <td className="px-4 py-3 text-sm text-right text-primary font-bold border-r border-default">{totalQuantity}</td>
                                                <td className="px-4 py-3 text-xs font-bold text-secondary border-r border-default" colSpan={3}>
                                                    {totalItems} Item(s)
                                                </td>
                                            </tr>
                                        </tfoot>
                                    )}
                                </table>
                            </div>
                        </div>

                        {/* Bottom Section: Transport & Logistics */}
                        <div className="bg-card border border-default rounded-xl shadow-sm overflow-hidden">
                            <div className="bg-surface px-4 py-2 border-b border-default">
                                <h2 className="text-sm font-bold text-main uppercase tracking-wide">Transport & Notes</h2>
                            </div>
                            <div className="p-4 grid grid-cols-1 md:grid-cols-2 gap-6">
                                <div className="grid grid-cols-2 gap-4">
                                    <div className="col-span-1">
                                        <label className="block text-xs font-bold text-secondary mb-1 uppercase tracking-wider">Transport Mode</label>
                                        <select
                                            value={formData.transportMode}
                                            onChange={(e) => setFormData({ ...formData, transportMode: e.target.value })}
                                            className="w-full px-3 py-1.5 bg-input border border-default rounded-lg text-sm font-medium text-main focus:ring-2 focus:ring-primary focus:border-transparent transition-all"
                                        >
                                            <option value="road">Road</option>
                                            <option value="rail">Rail</option>
                                            <option value="air">Air</option>
                                            <option value="ship">Ship</option>
                                            <option value="courier">Courier</option>
                                        </select>
                                    </div>
                                    <div className="col-span-1">
                                        <label className="block text-xs font-bold text-secondary mb-1 uppercase tracking-wider">Vehicle No.</label>
                                        <input
                                            type="text"
                                            value={formData.vehicleNo}
                                            onChange={(e) => setFormData({ ...formData, vehicleNo: e.target.value })}
                                            placeholder="MH-01-AB-1234"
                                            className="w-full px-3 py-1.5 bg-input border border-default rounded-lg text-sm font-medium text-main focus:ring-2 focus:ring-primary focus:border-transparent transition-all"
                                        />
                                    </div>
                                    <div className="col-span-2">
                                        <label className="block text-xs font-bold text-secondary mb-1 uppercase tracking-wider">Driver Name / Carrier</label>
                                        <input
                                            type="text"
                                            value={formData.driverName}
                                            onChange={(e) => setFormData({ ...formData, driverName: e.target.value })}
                                            className="w-full px-3 py-1.5 bg-input border border-default rounded-lg text-sm font-medium text-main focus:ring-2 focus:ring-primary focus:border-transparent transition-all"
                                        />
                                    </div>
                                </div>
                                <div className="col-span-1">
                                    <label className="block text-xs font-bold text-secondary mb-1 uppercase tracking-wider">Additional Notes</label>
                                    <textarea
                                        value={formData.notes}
                                        onChange={(e) => setFormData({ ...formData, notes: e.target.value })}
                                        rows={4}
                                        className="w-full px-3 py-2 bg-input border border-default rounded-lg text-sm font-medium text-main focus:ring-2 focus:ring-primary focus:border-transparent transition-all resize-none"
                                        placeholder="Enter any special instructions or remarks..."
                                    />
                                </div>
                            </div>
                        </div>
                    </div>
                </div>

                <CustomerSelectionModal
                    isOpen={showCustomerModal}
                    onClose={() => setShowCustomerModal(false)}
                    onSelect={(customer: any) => {
                        setFormData({ ...formData, customer });
                        setShowCustomerModal(false);
                    }}
                />

                <ItemSelectionModal
                    isOpen={showItemModal}
                    onClose={() => setShowItemModal(false)}
                    onSelect={handleItemSelect}
                />

                <SalesOrderSelectionModal
                    isOpen={showSalesOrderModal}
                    onClose={() => setShowSalesOrderModal(false)}
                    onSelect={handleSalesOrderSelect}
                />
            </div>
        </Layout>
    );
};

export default DeliveryChallan;

import { useEffect, useState } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { useDispatch, useSelector } from 'react-redux';
import { toast } from 'react-toastify';
import Layout from "@/shared/ui/Layout/Layout";
import { getDeliveryChallanById, convertToInvoice, reset } from "@/app/store/slices/deliveryChallanSlice";
import { ArrowLeft, Printer, Truck, ArrowRightCircle, Phone, Mail } from 'lucide-react';
import { RootState } from "@/app/store/store";

const DeliveryChallanDetail = () => {
    const { id } = useParams();
    const navigate = useNavigate();
    const dispatch = useDispatch();
    const { challan, isLoading, isError, message } = useSelector((state: RootState) => state.deliveryChallan);
    const [convertConfirm, setConvertConfirm] = useState(false);

    useEffect(() => {
        if (id) {
            dispatch(getDeliveryChallanById(id) as any);
        }
    }, [dispatch, id]);

    useEffect(() => {
        if (isError) {
            toast.error(message);
        }
        return () => {
            dispatch(reset());
        };
    }, [isError, message, dispatch]);

    const handlePrint = () => {
        window.print();
    };

    const handleConvert = async () => {
        if (!id) return;
        const result = await dispatch(convertToInvoice(id) as any);
        setConvertConfirm(false);

        if (result.type.includes('fulfilled')) {
            toast.success('Converted to Invoice successfully!');
            const payload = result.payload as any;
            if (payload?.invoice?._id) {
                navigate(`/sales/invoice/${payload.invoice._id}`);
            }
        }
    };

    if (isLoading || !challan) {
        return (
            <Layout>
                <div className="flex flex-col items-center justify-center py-20">
                    <div className="animate-spin rounded-full h-10 w-10 border-b-2 border-primary mb-4"></div>
                    <p className="text-secondary font-medium">Loading challan...</p>
                </div>
            </Layout>
        );
    }

    const totalQuantity = (challan?.items || []).reduce((sum: number, item: any) => sum + (item.deliveredQty || 0), 0);

    return (
        <Layout>
            <div className="max-w-5xl mx-auto animate-fade-in pb-10">
                {/* Header - Hidden on print */}
                <div className="mb-8 print:hidden">
                    <button
                        onClick={() => navigate('/sales/delivery-challan-list')}
                        className="flex items-center text-secondary hover:text-primary mb-4 transition-colors font-medium gap-2"
                    >
                        <ArrowLeft className="w-4 h-4" />
                        Back to Challan List
                    </button>
                    <div className="flex justify-between items-start">
                        <div>
                            <h1 className="text-2xl font-bold text-main tracking-tight flex items-center gap-2">
                                <Truck className="w-6 h-6 text-primary" />
                                Delivery Challan
                            </h1>
                            <p className="text-sm text-secondary mt-1">View and print delivery challan</p>
                        </div>
                        <div className="flex gap-2">
                            {challan.status !== 'Converted' && (
                                <button
                                    className="flex items-center gap-2 px-4 py-2 bg-emerald-600 text-white rounded-lg hover:bg-emerald-700 transition-colors shadow-sm font-medium"
                                    onClick={() => setConvertConfirm(true)}
                                >
                                    <ArrowRightCircle className="w-4 h-4" />
                                    Convert to Invoice
                                </button>
                            )}
                            <button
                                className="flex items-center gap-2 px-4 py-2 bg-primary text-white rounded-lg hover:bg-primary-hover transition-colors shadow-sm font-medium"
                                onClick={handlePrint}
                            >
                                <Printer className="w-4 h-4" />
                                Print
                            </button>
                        </div>
                    </div>
                </div>

                {/* Challan Container */}
                <div className="bg-card border border-default rounded-2xl shadow-sm overflow-hidden print:shadow-none print:border-0 print:rounded-none">
                    {/* Header Section */}
                    <div className="px-8 py-6 border-b-2 border-default print:border-gray-300">
                        <div className="flex justify-between items-start gap-4">
                            <div className="flex-1">
                                <h2 className="text-3xl font-bold text-primary mb-1 tracking-tight">DELIVERY CHALLAN</h2>
                                <div className="text-base font-mono font-bold text-main">
                                    Challan #: {challan.challanNumber}
                                </div>
                            </div>
                            <div className="text-right flex-shrink-0">
                                <div className="text-xs font-bold text-secondary uppercase mb-1 tracking-wider">Challan Date</div>
                                <div className="font-bold text-base text-main">
                                    {new Date(challan.challanDate).toLocaleDateString('en-IN', {
                                        day: '2-digit',
                                        month: 'short',
                                        year: 'numeric',
                                    })}
                                </div>
                                {challan.deliveryDate && (
                                    <>
                                        <div className="text-xs font-bold text-secondary uppercase mb-1 mt-2 tracking-wider">Delivery Date</div>
                                        <div className="font-bold text-base text-main">
                                            {new Date(challan.deliveryDate).toLocaleDateString('en-IN', {
                                                day: '2-digit',
                                                month: 'short',
                                                year: 'numeric',
                                            })}
                                        </div>
                                    </>
                                )}
                            </div>
                        </div>
                    </div>

                    {/* Customer and Status Section */}
                    <div className="grid grid-cols-2 gap-6 px-8 py-6">
                        <div>
                            <h3 className="text-xs font-bold text-secondary uppercase mb-3 pb-2 border-b border-default tracking-wider">
                                Delivered To
                            </h3>
                            <div className="space-y-2">
                                <div className="font-bold text-lg text-main">{challan.customer.name}</div>
                                <div className="text-sm text-secondary flex items-center gap-2">
                                    <Phone className="w-4 h-4 text-muted" />
                                    {challan.customer.phone}
                                </div>
                                {challan.customer.email && (
                                    <div className="text-sm text-secondary flex items-center gap-2">
                                        <Mail className="w-4 h-4 text-muted" />
                                        {challan.customer.email}
                                    </div>
                                )}
                            </div>
                        </div>

                        <div className="text-right">
                            <h3 className="text-xs font-bold text-secondary uppercase mb-3 pb-2 border-b border-default tracking-wider">
                                Status
                            </h3>
                            <div className="space-y-2">
                                <div>
                                    <span className={`px-4 py-2 inline-flex text-sm font-bold rounded-full ${challan.status === 'Converted' ? 'bg-emerald-50 text-emerald-700 dark:bg-emerald-900/20 dark:text-emerald-400' :
                                        challan.status === 'Delivered' ? 'bg-primary-soft text-primary' :
                                            'bg-surface text-secondary'
                                        }`}>
                                        {challan.status}
                                    </span>
                                </div>
                                {challan.convertedToInvoice && (
                                    <div className="text-sm text-secondary mt-2">
                                        Converted to Invoice: {challan.convertedToInvoice.invoiceNo}
                                    </div>
                                )}
                            </div>
                        </div>
                    </div>

                    {/* Items Table */}
                    <div className="px-8 py-6 border-t border-default">
                        <h3 className="text-xs font-bold text-secondary uppercase mb-4">Items Delivered</h3>
                        <div className="overflow-x-auto">
                            <table className="w-full text-sm">
                                <thead>
                                    <tr className="border-b-2 border-default">
                                        <th className="text-left py-2 px-2 font-bold text-main">#</th>
                                        <th className="text-left py-2 px-2 font-bold text-main">Item Name</th>
                                        <th className="text-center py-2 px-2 font-bold text-main">Quantity</th>
                                        <th className="text-center py-2 px-2 font-bold text-main">Unit</th>
                                        <th className="text-left py-2 px-2 font-bold text-main">Description</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {(challan?.items || []).map((item: any, index: number) => (
                                        <tr key={index} className="border-b border-default">
                                            <td className="py-2 px-2 text-main">{index + 1}</td>
                                            <td className="py-2 px-2 text-main font-medium">
                                                {item.item?.name || 'N/A'}
                                                {item.item?.sku && <div className="text-xs text-secondary">{item.item.sku}</div>}
                                            </td>
                                            <td className="py-2 px-2 text-center text-main font-semibold">{item.deliveredQty}</td>
                                            <td className="py-2 px-2 text-center text-main">{item.unit}</td>
                                            <td className="py-2 px-2 text-main">{item.description || '-'}</td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                    </div>

                    {/* Transport Details */}
                    {(challan.vehicleNo || challan.driverName || challan.transportMode) && (
                        <div className="px-8 py-6 border-t border-default">
                            <h3 className="text-xs font-bold text-secondary uppercase mb-4">Transport Details</h3>
                            <div className="grid grid-cols-3 gap-4 text-sm">
                                {challan.transportMode && (
                                    <div>
                                        <div className="text-secondary mb-1">Transport Mode</div>
                                        <div className="font-medium text-main capitalize">{challan.transportMode}</div>
                                    </div>
                                )}
                                {challan.vehicleNo && (
                                    <div>
                                        <div className="text-secondary mb-1">Vehicle Number</div>
                                        <div className="font-medium text-main">{challan.vehicleNo}</div>
                                    </div>
                                )}
                                {challan.driverName && (
                                    <div>
                                        <div className="text-secondary mb-1">Driver Name</div>
                                        <div className="font-medium text-main">{challan.driverName}</div>
                                    </div>
                                )}
                            </div>
                        </div>
                    )}

                    {/* Summary */}
                    <div className="px-8 py-6 border-t border-default bg-surface">
                        <div className="flex justify-center">
                            <div className="w-full md:w-96">
                                <div className="space-y-4 bg-card p-6 rounded-lg shadow-sm border border-default">
                                    <div className="flex justify-between py-2 text-base">
                                        <span className="text-main">Total Items:</span>
                                        <span className="font-bold text-main">{(challan?.items || []).length}</span>
                                    </div>
                                    <div className="flex justify-between py-2 text-base border-t border-default">
                                        <span className="text-main">Total Quantity:</span>
                                        <span className="font-bold text-main">{totalQuantity}</span>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>

                    {/* Notes */}
                    {challan.notes && (
                        <div className="px-8 py-6 border-t border-default">
                            <h3 className="text-xs font-bold text-secondary uppercase mb-3 pb-2 border-b border-default">
                                Notes
                            </h3>
                            <p className="text-sm text-secondary leading-relaxed">{challan.notes}</p>
                        </div>
                    )}

                    {/* Footer */}
                    <div className="px-8 py-6 border-t border-default text-center">
                        <p className="text-sm text-main font-medium">Thank you for your business!</p>
                        <p className="text-xs text-secondary mt-2">This is a computer-generated delivery challan.</p>
                        {challan.createdAt && (
                            <p className="text-xs text-secondary mt-2">
                                Created on {new Date(challan.createdAt).toLocaleString('en-IN')}
                            </p>
                        )}
                    </div>
                </div>
            </div>

            {/* Convert Confirmation Modal */}
            {convertConfirm && (
                <div className="fixed inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center z-50">
                    <div className="bg-card rounded-2xl p-6 max-w-md w-full mx-4 shadow-2xl border border-default">
                        <h3 className="text-lg font-bold text-main mb-4">Convert to Invoice</h3>
                        <p className="text-secondary mb-6">
                            Are you sure you want to convert this challan to an invoice? This action cannot be undone.
                        </p>
                        <div className="flex gap-3">
                            <button
                                onClick={() => setConvertConfirm(false)}
                                className="flex-1 px-4 py-2 border border-default rounded-lg hover:bg-surface font-medium text-main"
                            >
                                Cancel
                            </button>
                            <button
                                onClick={handleConvert}
                                className="flex-1 px-4 py-2 bg-emerald-600 text-white rounded-lg hover:bg-emerald-700 font-medium"
                            >
                                Convert
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* Print Styles */}
            <style>{`
                @media print {
                    * {
                        -webkit-print-color-adjust: exact !important;
                        color-adjust: exact !important;
                        print-color-adjust: exact !important;
                    }
                    
                    body {
                        background: white !important;
                        margin: 0 !important;
                        padding: 0 !important;
                    }
                    
                    nav, aside, .print\\:hidden, button:not(.print\\:block) {
                        display: none !important;
                    }
                    
                    .max-w-5xl {
                        max-width: 100% !important;
                    }
                }
            `}</style>
        </Layout>
    );
};

export default DeliveryChallanDetail;

import { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useDispatch, useSelector } from 'react-redux';
import { toast } from 'react-toastify';
import Layout from "@/shared/ui/Layout/Layout";
import { getAllDeliveryChallans, deleteDeliveryChallan, convertToInvoice, reset } from "@/app/store/slices/deliveryChallanSlice";
import { RootState } from "@/app/store/store";
import {
    Truck,
    Plus,
    Search,
    Eye,
    Trash2,
    FileText,
    CheckCircle,
    Clock,
    ArrowRightCircle,
    Package
} from 'lucide-react';

const DeliveryChallanList = () => {
    const navigate = useNavigate();
    const dispatch = useDispatch();
    const { challans, isLoading, isError, message } = useSelector((state: RootState) => state.deliveryChallan);

    const [searchTerm, setSearchTerm] = useState('');
    const [statusFilter, setStatusFilter] = useState('all');
    const [deleteConfirm, setDeleteConfirm] = useState<string | null>(null);
    const [convertConfirm, setConvertConfirm] = useState<string | null>(null);

    useEffect(() => {
        dispatch(getAllDeliveryChallans() as any);
    }, [dispatch]);

    useEffect(() => {
        if (isError) {
            toast.error(message);
        }
        return () => {
            dispatch(reset());
        };
    }, [isError, message, dispatch]);

    const handleDelete = async (id: string) => {
        await dispatch(deleteDeliveryChallan(id) as any);
        setDeleteConfirm(null);
        toast.success('Delivery Challan deleted successfully');
        dispatch(getAllDeliveryChallans() as any);
    };

    const handleConvert = async (id: string) => {
        const result = await dispatch(convertToInvoice(id) as any);
        setConvertConfirm(null);

        if (result.type.includes('fulfilled')) {
            toast.success('Converted to Invoice successfully!');
            const payload = result.payload as any;
            if (payload?.invoice?._id) {
                navigate(`/sales/invoice/${payload.invoice._id}`);
            }
        }
    };

    // KPI calculations
    const challanArray = Array.isArray(challans) ? challans : [];
    const totalChallans = challanArray.length;
    const deliveredCount = challanArray.filter(c => c.status === 'Delivered').length;
    const convertedCount = challanArray.filter(c => c.status === 'Converted').length;
    const draftCount = challanArray.filter(c => c.status === 'Draft').length;

    const filteredChallans = challanArray.filter(challan => {
        const matchesSearch = challan.challanNumber.toLowerCase().includes(searchTerm.toLowerCase()) ||
            (challan.customer?.name || '').toLowerCase().includes(searchTerm.toLowerCase());
        const matchesStatus = statusFilter === 'all' || challan.status === statusFilter;
        return matchesSearch && matchesStatus;
    });

    const getStatusBadge = (status: string) => {
        const badges: Record<string, { bg: string, text: string, icon: any }> = {
            Draft: { bg: 'bg-slate-100', text: 'text-slate-700', icon: Clock },
            Delivered: { bg: 'bg-blue-50', text: 'text-blue-700', icon: Truck },
            Converted: { bg: 'bg-emerald-50', text: 'text-emerald-700', icon: CheckCircle }
        };
        const badge = badges[status] || badges.Draft;
        const Icon = badge.icon;
        return (
            <span className={`inline-flex items-center gap-1 px-2.5 py-1 rounded-full text-xs font-bold ${badge.bg} ${badge.text}`}>
                <Icon className="w-3 h-3" />
                {status}
            </span>
        );
    };

    return (
        <Layout>
            <div className="space-y-6 animate-fade-in pb-10">
                {/* Header Section */}
                <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                    <div>
                        <h1 className="text-2xl font-bold text-slate-800 tracking-tight flex items-center gap-2">
                            <Truck className="w-6 h-6 text-blue-600" />
                            Delivery Challans
                        </h1>
                        <p className="text-sm text-slate-500 mt-1">View and manage delivery challans</p>
                    </div>
                    <button
                        onClick={() => {
                            dispatch(reset());
                            navigate('/sales/delivery-challan');
                        }}
                        className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 shadow-sm transition-all font-medium"
                    >
                        <Plus className="w-4 h-4" /> Create Challan
                    </button>
                </div>

                {/* KPI Grid */}
                <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                    <div className="bg-white p-5 rounded-xl shadow-sm border border-slate-100 hover:shadow-md transition-shadow">
                        <div className="flex justify-between items-start">
                            <div>
                                <p className="text-xs font-bold text-slate-400 uppercase tracking-wider">Total Challans</p>
                                <h3 className="text-2xl font-bold text-slate-800 mt-1">{totalChallans}</h3>
                            </div>
                            <div className="p-2 bg-blue-50 rounded-lg text-blue-600">
                                <Package className="w-5 h-5" />
                            </div>
                        </div>
                    </div>

                    <div className="bg-white p-5 rounded-xl shadow-sm border border-slate-100 hover:shadow-md transition-shadow">
                        <div className="flex justify-between items-start">
                            <div>
                                <p className="text-xs font-bold text-slate-400 uppercase tracking-wider">Delivered</p>
                                <h3 className="text-2xl font-bold text-blue-600 mt-1">{deliveredCount}</h3>
                            </div>
                            <div className="p-2 bg-blue-50 rounded-lg text-blue-600">
                                <Truck className="w-5 h-5" />
                            </div>
                        </div>
                    </div>

                    <div className="bg-white p-5 rounded-xl shadow-sm border border-slate-100 hover:shadow-md transition-shadow">
                        <div className="flex justify-between items-start">
                            <div>
                                <p className="text-xs font-bold text-slate-400 uppercase tracking-wider">Converted</p>
                                <h3 className="text-2xl font-bold text-emerald-600 mt-1">{convertedCount}</h3>
                            </div>
                            <div className="p-2 bg-emerald-50 rounded-lg text-emerald-600">
                                <CheckCircle className="w-5 h-5" />
                            </div>
                        </div>
                    </div>

                    <div className="bg-white p-5 rounded-xl shadow-sm border border-slate-100 hover:shadow-md transition-shadow">
                        <div className="flex justify-between items-start">
                            <div>
                                <p className="text-xs font-bold text-slate-400 uppercase tracking-wider">Drafts</p>
                                <h3 className="text-2xl font-bold text-slate-600 mt-1">{draftCount}</h3>
                            </div>
                            <div className="p-2 bg-slate-100 rounded-lg text-slate-600">
                                <Clock className="w-5 h-5" />
                            </div>
                        </div>
                    </div>
                </div>

                {/* Filter Island + Table */}
                <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
                    {/* Filter Bar */}
                    <div className="p-5 border-b border-slate-100 bg-slate-50/50">
                        <div className="flex flex-col md:flex-row gap-4 items-center justify-between">
                            <div className="relative w-full md:max-w-md group">
                                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                                    <Search className="h-5 w-5 text-slate-400 group-focus-within:text-indigo-500 transition-colors" />
                                </div>
                                <input
                                    type="text"
                                    placeholder="Search challan # or customer..."
                                    value={searchTerm}
                                    onChange={(e) => setSearchTerm(e.target.value)}
                                    className="block w-full pl-10 pr-3 py-2 border border-slate-300 rounded-lg bg-white placeholder-slate-400 focus:outline-none focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500 sm:text-sm transition-all shadow-sm"
                                />
                            </div>

                            <select
                                value={statusFilter}
                                onChange={(e) => setStatusFilter(e.target.value)}
                                className="px-3 py-2 border border-slate-300 rounded-lg text-sm bg-white focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 shadow-sm"
                            >
                                <option value="all">All Status</option>
                                <option value="Draft">Draft</option>
                                <option value="Delivered">Delivered</option>
                                <option value="Converted">Converted</option>
                            </select>
                        </div>
                    </div>

                    {/* Table */}
                    {isLoading ? (
                        <div className="flex flex-col items-center justify-center py-20">
                            <div className="animate-spin rounded-full h-10 w-10 border-b-2 border-indigo-600 mb-4"></div>
                            <p className="text-slate-500 font-medium">Loading challans...</p>
                        </div>
                    ) : filteredChallans.length === 0 ? (
                        <div className="flex flex-col items-center justify-center py-20">
                            <div className="bg-slate-100 p-3 rounded-full mb-3">
                                <FileText className="w-6 h-6 text-slate-400" />
                            </div>
                            <p className="text-slate-600 font-medium">No delivery challans found</p>
                            <p className="text-sm text-slate-400 mt-1">Try adjusting your search or filters</p>
                        </div>
                    ) : (
                        <div className="overflow-x-auto">
                            <table className="w-full text-left">
                                <thead className="bg-slate-50 border-b border-slate-200">
                                    <tr className="text-xs font-bold text-slate-500 uppercase tracking-wider">
                                        <th className="px-6 py-3">Challan No</th>
                                        <th className="px-6 py-3">Date</th>
                                        <th className="px-6 py-3">Customer</th>
                                        <th className="px-6 py-3 text-center">Items</th>
                                        <th className="px-6 py-3">Status</th>
                                        <th className="px-6 py-3 text-right">Actions</th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-slate-100 bg-white">
                                    {filteredChallans.map((challan) => (
                                        <tr key={challan._id} className="hover:bg-slate-50 transition-colors group">
                                            <td className="px-6 py-4 whitespace-nowrap">
                                                <button
                                                    onClick={() => navigate(`/sales/delivery-challan/${challan._id}`)}
                                                    className="font-bold text-indigo-600 hover:text-indigo-800"
                                                >
                                                    {challan.challanNumber}
                                                </button>
                                            </td>
                                            <td className="px-6 py-4 whitespace-nowrap text-sm text-slate-600">
                                                {new Date(challan.challanDate).toLocaleDateString('en-IN', { day: 'numeric', month: 'short', year: 'numeric' })}
                                            </td>
                                            <td className="px-6 py-4">
                                                <div className="text-sm font-medium text-slate-800">{challan.customer?.name || 'N/A'}</div>
                                                {challan.customer?.phone && (
                                                    <div className="text-xs text-slate-500">{challan.customer.phone}</div>
                                                )}
                                            </td>
                                            <td className="px-6 py-4 text-center">
                                                <span className="inline-flex items-center px-2 py-0.5 rounded text-xs font-medium bg-slate-100 text-slate-700">
                                                    {(challan.items || []).length} items
                                                </span>
                                            </td>
                                            <td className="px-6 py-4 whitespace-nowrap">
                                                {getStatusBadge(challan.status)}
                                            </td>
                                            <td className="px-6 py-4 whitespace-nowrap text-right">
                                                <div className="flex justify-end gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                                                    <button
                                                        onClick={() => navigate(`/sales/delivery-challan/${challan._id}`)}
                                                        className="p-1.5 text-indigo-600 hover:bg-indigo-50 rounded-lg"
                                                        title="View"
                                                    >
                                                        <Eye className="w-4 h-4" />
                                                    </button>
                                                    {challan.status !== 'Converted' && (
                                                        <>
                                                            <button
                                                                onClick={() => setConvertConfirm(challan._id)}
                                                                className="p-1.5 text-emerald-600 hover:bg-emerald-50 rounded-lg"
                                                                title="Convert to Invoice"
                                                            >
                                                                <ArrowRightCircle className="w-4 h-4" />
                                                            </button>
                                                            <button
                                                                onClick={() => setDeleteConfirm(challan._id)}
                                                                className="p-1.5 text-red-600 hover:bg-red-50 rounded-lg"
                                                                title="Delete"
                                                            >
                                                                <Trash2 className="w-4 h-4" />
                                                            </button>
                                                        </>
                                                    )}
                                                </div>
                                            </td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                    )}
                </div>

                {/* Delete Confirmation Modal */}
                {deleteConfirm && (
                    <div className="fixed inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center z-50">
                        <div className="bg-white rounded-2xl p-6 max-w-md w-full mx-4 shadow-2xl">
                            <h3 className="text-lg font-bold text-slate-800 mb-4">Confirm Delete</h3>
                            <p className="text-slate-600 mb-6">
                                Are you sure you want to delete this delivery challan? Stock will be restored.
                            </p>
                            <div className="flex gap-3">
                                <button
                                    onClick={() => setDeleteConfirm(null)}
                                    className="flex-1 px-4 py-2 border border-slate-300 rounded-lg hover:bg-slate-50 font-medium"
                                >
                                    Cancel
                                </button>
                                <button
                                    onClick={() => handleDelete(deleteConfirm)}
                                    className="flex-1 px-4 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700 font-medium"
                                >
                                    Delete
                                </button>
                            </div>
                        </div>
                    </div>
                )}

                {/* Convert Confirmation Modal */}
                {convertConfirm && (
                    <div className="fixed inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center z-50">
                        <div className="bg-white rounded-2xl p-6 max-w-md w-full mx-4 shadow-2xl">
                            <h3 className="text-lg font-bold text-slate-800 mb-4">Convert to Invoice</h3>
                            <p className="text-slate-600 mb-6">
                                Are you sure you want to convert this challan to an invoice? This action cannot be undone.
                            </p>
                            <div className="flex gap-3">
                                <button
                                    onClick={() => setConvertConfirm(null)}
                                    className="flex-1 px-4 py-2 border border-slate-300 rounded-lg hover:bg-slate-50 font-medium"
                                >
                                    Cancel
                                </button>
                                <button
                                    onClick={() => handleConvert(convertConfirm)}
                                    className="flex-1 px-4 py-2 bg-emerald-600 text-white rounded-lg hover:bg-emerald-700 font-medium"
                                >
                                    Convert
                                </button>
                            </div>
                        </div>
                    </div>
                )}
            </div>
        </Layout>
    );
};

export default DeliveryChallanList;

import { useState, useEffect } from "react";
import { useDispatch, useSelector } from "react-redux";
import { useNavigate } from "react-router-dom";
import { getAllItems } from "@/entities/inventory/model/inventorySlice";
import { getAllCustomers } from "@/entities/contact/model/customerSlice";
import Layout from "@/shared/ui/Layout/Layout";
import api from "@/shared/api/api";
import { toast } from "react-toastify";
import EstimateTemplate from "@/features/pos-checkout/ui/EstimateTemplate";
import { RootState } from "@/app/store/store";
import {
  Calculator,
  FileText,
  User,
  Search,
  X,
  Phone,
  AlertCircle,
  CheckCircle
} from 'lucide-react';
import { Customer } from '@repo/shared';
import { Product } from '@repo/shared';

interface CartItem {
  itemId: string;
  name: string;
  quantity: number;
  price: number;
  total: number;
}

const Estimate = () => {
  const navigate = useNavigate();
  const dispatch = useDispatch();
  const inventoryState = useSelector((state: RootState) => state.inventory);
  const items = inventoryState?.items || [];
  const customerState = useSelector((state: RootState) => state.customers);
  const customers = customerState?.customers || [];

  // State
  const [customer, setCustomer] = useState<Customer | null>(null);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [discount, setDiscount] = useState(0);
  const [searchTerm, setSearchTerm] = useState("");
  const [customerSearchTerm, setCustomerSearchTerm] = useState("");
  const [showCustomerSelect, setShowCustomerSelect] = useState(false);
  const [notes, setNotes] = useState("");
  const [isLoading, setIsLoading] = useState(false);

  useEffect(() => {
    dispatch(getAllItems() as any);
    dispatch(getAllCustomers() as any);
  }, [dispatch]);

  const filteredItems = items.filter(
    (item: Product) =>
      item.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      (item.sku && item.sku.toLowerCase().includes(searchTerm.toLowerCase()))
  );

  const filteredCustomers = customers.filter(
    (c: Customer) =>
      c.name.toLowerCase().includes(customerSearchTerm.toLowerCase()) ||
      c.phone.includes(customerSearchTerm)
  );

  // Cart management (READ-ONLY for inventory)
  const addToCart = (item: Product) => {
    const existingItem = cart.find((cartItem) => cartItem.itemId === item._id);

    if (existingItem) {
      setCart(
        cart.map((cartItem) =>
          cartItem.itemId === item._id
            ? {
              ...cartItem,
              quantity: cartItem.quantity + 1,
              total: (cartItem.quantity + 1) * cartItem.price,
            }
            : cartItem
        )
      );
    } else {
      setCart([
        ...cart,
        {
          itemId: item._id || '',
          name: item.name,
          quantity: 1,
          price: item.sellingPrice || 0,
          total: item.sellingPrice || 0,
        },
      ]);
    }
  };

  const updateQuantity = (itemId: string, newQuantity: number) => {
    if (newQuantity <= 0) {
      removeFromCart(itemId);
      return;
    }

    setCart(
      cart.map((cartItem) =>
        cartItem.itemId === itemId
          ? {
            ...cartItem,
            quantity: newQuantity,
            total: newQuantity * cartItem.price,
          }
          : cartItem
      )
    );
  };

  const removeFromCart = (itemId: string) => {
    setCart(cart.filter((cartItem) => cartItem.itemId !== itemId));
  };

  const calculateSubtotal = () => {
    return cart.reduce((sum, item) => sum + item.total, 0);
  };

  const calculateTotal = () => {
    return calculateSubtotal() - discount;
  };

  const selectCustomer = (c: Customer) => {
    setCustomer(c);
    setShowCustomerSelect(false);
    setCustomerSearchTerm("");
  };

  const handleSaveEstimate = async () => {
    if (!customer) {
      toast.warning(
        "Please select a registered customer to save the estimate."
      );
      setShowCustomerSelect(true);
      return;
    }

    if (cart.length === 0) {
      toast.error("Cart is empty!");
      return;
    }

    setIsLoading(true);

    try {
      // Get token from Redux state (same pattern as other slices)
      const userStr = localStorage.getItem("user");
      if (!userStr) {
        toast.error("Please login again");
        return;
      }
      const user = JSON.parse(userStr);

      if (!user || !user.token) {
        toast.error("Please login again");
        return;
      }

      const estimateData = {
        customerId: customer._id || customer.id,
        items: cart,
        subtotal: calculateSubtotal(),
        discount,
        totalAmount: calculateTotal(),
        notes,
      };

      const response = await api.post(
        `/api/estimates`,
        estimateData,
        {
          headers: { Authorization: `Bearer ${user.token}` },
        }
      );

      toast.success("Estimate created successfully!");

      // Navigate to estimate detail page
      navigate(`/sales/estimate/${response.data.estimate._id}`);
    } catch (error: any) {
      toast.error(error.response?.data?.message || "Failed to create estimate");
    } finally {
      setIsLoading(false);
    }
  };

  const handleClear = () => {
    if (cart.length > 0 && confirm("Clear cart?")) {
      setCart([]);
      setDiscount(0);
    }
  };

  const subtotal = calculateSubtotal();
  const total = calculateTotal();

  const getPreviewData = () => ({
    estimateNo: "PREVIEW",
    createdAt: new Date().toISOString(),
    customer: customer,
    items: cart,
    subtotal: subtotal,
    discount: discount,
    totalAmount: total,
    notes: notes,
    status: "Draft",
  });

  // 2. Handle Print Preview
  const handlePrintPreview = () => {
    if (cart.length === 0) {
      toast.error("Add items to cart before printing");
      return;
    }
    window.print();
  };

  return (
    <Layout>
      <div className="max-w-7xl mx-auto animate-fade-in pb-10">
        <div className="print:hidden">
          {/* Header */}
          <div className="mb-6 flex justify-between items-center">
            <div>
              <h1 className="text-2xl font-bold text-slate-800 tracking-tight flex items-center gap-2">
                <Calculator className="w-6 h-6 text-indigo-600" />
                Create Estimate / Proforma
              </h1>
              <p className="text-sm text-slate-500 mt-1">
                Price approximation for customers
              </p>
            </div>
            <button
              onClick={() => navigate("/sales/estimates")}
              className="flex items-center gap-2 px-4 py-2 bg-slate-600 text-white rounded-lg hover:bg-slate-700 font-medium shadow-sm transition-all"
            >
              <FileText className="w-4 h-4" />
              View Estimates
            </button>
          </div>

          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            {/* Left Side - Products */}
            <div className="lg:col-span-2 space-y-4">
              {/* Customer Selection */}
              <div className="bg-white border border-slate-200 rounded-2xl shadow-sm overflow-hidden">
                <div className="bg-slate-50 px-6 py-3 border-b border-slate-100">
                  <h2 className="text-xs font-bold text-slate-500 uppercase tracking-wider flex items-center gap-2">
                    <User className="w-4 h-4" /> Customer
                  </h2>
                </div>
                <div className="p-6">

                  {customer ? (
                    <div className="p-4 bg-indigo-50 border border-indigo-200 rounded-xl">
                      <div className="flex items-center justify-between">
                        <div className="flex items-center gap-3">
                          <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-indigo-500 to-violet-600 flex items-center justify-center text-white font-bold shadow-lg">
                            {customer.name?.charAt(0).toUpperCase() || '?'}
                          </div>
                          <div>
                            <div className="font-bold text-slate-800">
                              {customer.name}
                            </div>
                            <div className="text-sm text-slate-600 flex items-center gap-1">
                              <Phone className="w-3 h-3" /> {customer.phone}
                            </div>
                          </div>
                        </div>
                        <button
                          onClick={() => setCustomer(null)}
                          className="text-red-600 hover:text-red-700 p-1.5 hover:bg-red-50 rounded-lg"
                        >
                          <X className="w-5 h-5" />
                        </button>
                      </div>
                    </div>
                  ) : (
                    <button
                      onClick={() => setShowCustomerSelect(true)}
                      className="w-full px-4 py-4 border-2 border-dashed border-slate-300 rounded-xl text-slate-500 hover:border-indigo-500 hover:text-indigo-600 transition-colors flex items-center justify-center gap-2"
                    >
                      <User className="w-5 h-5" /> Walk-in Customer (Click to select)
                    </button>
                  )}
                  {/* Credit Balance Display */}
                  {customer && customer.dues < 0 && (
                    <div className="mt-4 p-3 bg-emerald-50 border border-emerald-200 rounded-xl flex items-center justify-between">
                      <span className="text-sm font-medium text-emerald-700 flex items-center gap-2">
                        <CheckCircle className="w-4 h-4" /> Available Credit
                      </span>
                      <span className="text-lg font-bold text-emerald-600">
                        ₹{Math.abs(customer.dues).toFixed(2)}
                      </span>
                    </div>
                  )}

                  {/* Pending Dues Display */}
                  {customer && customer?.dues > 0 && (
                    <div className="mt-4 p-3 bg-red-50 border border-red-200 rounded-xl flex items-center justify-between">
                      <span className="text-sm font-medium text-red-700 flex items-center gap-2">
                        <AlertCircle className="w-4 h-4" /> Pending Dues
                      </span>
                      <span className="text-lg font-bold text-red-600">
                        ₹{customer.dues.toFixed(2)}
                      </span>
                    </div>
                  )}
                </div>
              </div>

              {/* Product Search */}
              <div className="bg-white border border-slate-200 rounded-2xl shadow-sm overflow-hidden">
                <div className="bg-slate-50 px-6 py-3 border-b border-slate-100">
                  <h2 className="text-xs font-bold text-slate-500 uppercase tracking-wider">Products</h2>
                </div>
                <div className="p-6">
                  <div className="relative mb-4">
                    <input
                      type="text"
                      placeholder="Search products by name or SKU..."
                      value={searchTerm}
                      onChange={(e) => setSearchTerm(e.target.value)}
                      className="w-full pl-10 pr-4 py-2 border border-slate-300 bg-white placeholder-slate-400 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 text-sm transition-all"
                    />
                    <Search className="absolute left-3 top-2.5 w-5 h-5 text-slate-400" />
                  </div>

                  {/* Products Grid */}
                  <div className="grid grid-cols-2 md:grid-cols-3 gap-3 max-h-96 overflow-y-auto">
                    {filteredItems.map((item: Product) => (
                      <button
                        key={item._id}
                        onClick={() => addToCart(item)}
                        className="p-4 border-2 border-slate-200 rounded-xl text-left transition hover:border-indigo-500 hover:shadow-md bg-white"
                      >
                        <div className="font-bold text-slate-800 mb-1 truncate text-sm">
                          {item.name}
                        </div>
                        <div className="text-lg font-bold text-indigo-600">
                          ₹{item.sellingPrice}
                        </div>
                        <div className="text-xs text-slate-500 mt-1">
                          Stock: {item.stockQty} {item.unit}
                        </div>
                        {item.sku && (
                          <div className="text-xs text-slate-400 mt-1">
                            SKU: {item.sku}
                          </div>
                        )}
                      </button>
                    ))}
                  </div>
                </div>
              </div>
            </div>

            {/* Right Side - Cart & Total */}
            <div className="lg:col-span-1">
              <div className="bg-white border border-indigo-100 rounded-2xl shadow-sm overflow-hidden sticky top-4">
                <div className="bg-indigo-50/50 px-6 py-3 border-b border-indigo-100">
                  <h2 className="text-xs font-bold text-indigo-800 uppercase tracking-wider">Estimate Cart</h2>
                </div>
                <div className="p-6">

                  {/* Cart Items */}
                  <div className="space-y-3 mb-4 max-h-64 overflow-y-auto">
                    {cart.length === 0 ? (
                      <p className="text-muted dark:text-[rgb(var(--color-text-secondary))] text-center py-8">
                        Cart is empty
                      </p>
                    ) : (
                      cart.map((item) => (
                        <div
                          key={item.itemId}
                          className="flex items-center justify-between p-3 bg-gray-50 dark:bg-[rgb(var(--color-input))] rounded-lg"
                        >
                          <div className="flex-1">
                            <div className="font-medium text-maindark:text-[rgb(var(--color-text))] text-sm">
                              {item.name}
                            </div>
                            <div className="text-xs text-muted dark:text-[rgb(var(--color-text-secondary))]">
                              ₹{item.price} each
                            </div>
                          </div>
                          <div className="flex items-center space-x-2">
                            <button
                              onClick={() =>
                                updateQuantity(item.itemId, item.quantity - 1)
                              }
                              className="w-7 h-7 bg-gray-200 dark:bg-gray-700 rounded hover:bg-gray-300 dark:hover:bg-gray-600"
                            >
                              -
                            </button>
                            <span className="w-8 text-center font-medium text-maindark:text-[rgb(var(--color-text))]">
                              {item.quantity}
                            </span>
                            <button
                              onClick={() =>
                                updateQuantity(item.itemId, item.quantity + 1)
                              }
                              className="w-7 h-7 bg-gray-200 dark:bg-gray-700 rounded hover:bg-gray-300 dark:hover:bg-gray-600"
                            >
                              +
                            </button>
                            <button
                              onClick={() => removeFromCart(item.itemId)}
                              className="ml-2 text-red-600 dark:text-red-400 hover:text-red-800"
                            >
                              <svg
                                className="w-5 h-5"
                                fill="none"
                                stroke="currentColor"
                                viewBox="0 0 24 24"
                              >
                                <path
                                  strokeLinecap="round"
                                  strokeLinejoin="round"
                                  strokeWidth={2}
                                  d="M6 18L18 6M6 6l12 12"
                                />
                              </svg>
                            </button>
                          </div>
                          <div className="ml-3 font-bold text-maindark:text-[rgb(var(--color-text))] w-20 text-right">
                            ₹{item.total.toFixed(2)}
                          </div>
                        </div>
                      ))
                    )}
                  </div>

                  {/* Discount */}
                  <div className="mb-4">
                    <label className="block text-sm font-medium text-gray-700 dark:text-[rgb(var(--color-text-secondary))] mb-2">
                      Discount (₹)
                    </label>
                    <input
                      type="number"
                      value={discount}
                      onChange={(e: React.ChangeEvent<HTMLInputElement>) =>
                        setDiscount(parseFloat(e.target.value) || 0)
                      }
                      min={0}
                      step="0.01"
                      className="w-full px-4 py-2 border border-gray-300 dark:border-[rgb(var(--color-border))] bg-white dark:bg-[rgb(var(--color-input))] text-maindark:text-[rgb(var(--color-text))] rounded-lg focus:ring-2 focus:ring-primary dark:focus:ring-[rgb(var(--color-primary))] focus:border-transparent"
                      placeholder="0.00"
                    />
                  </div>

                  {/* Notes */}
                  <div className="mb-4">
                    <label className="block text-sm font-medium text-gray-700 dark:text-[rgb(var(--color-text-secondary))] mb-2">
                      Notes
                    </label>
                    <textarea
                      value={notes}
                      onChange={(e) => setNotes(e.target.value)}
                      rows={2}
                      className="w-full px-4 py-2 border border-gray-300 dark:border-[rgb(var(--color-border))] bg-white dark:bg-[rgb(var(--color-input))] text-maindark:text-[rgb(var(--color-text))] rounded-lg focus:ring-2 focus:ring-primary dark:focus:ring-[rgb(var(--color-primary))] focus:border-transparent"
                      placeholder="Additional notes..."
                    />
                  </div>

                  {/* Totals */}
                  <div className="border-t border-default dark:border-[rgb(var(--color-border))] pt-4 mb-4 space-y-2">
                    <div className="flex justify-between text-sm">
                      <span className="text-gray-600 dark:text-[rgb(var(--color-text-secondary))]">
                        Subtotal:
                      </span>
                      <span className="font-medium text-maindark:text-[rgb(var(--color-text))]">
                        ₹{subtotal.toFixed(2)}
                      </span>
                    </div>
                    <div className="flex justify-between text-sm">
                      <span className="text-gray-600 dark:text-[rgb(var(--color-text-secondary))]">
                        Discount:
                      </span>
                      <span className="font-medium text-red-600 dark:text-red-400">
                        -₹{discount.toFixed(2)}
                      </span>
                    </div>
                    <div className="flex justify-between text-lg font-bold border-t border-default dark:border-[rgb(var(--color-border))] pt-2">
                      <span className="text-maindark:text-[rgb(var(--color-text))]">
                        Estimated Total:
                      </span>
                      <span className="text-indigo-600 dark:text-[rgb(var(--color-primary))]">
                        ₹{total.toFixed(2)}
                      </span>
                    </div>
                  </div>

                  {/* Action Buttons */}
                  <div className="space-y-2">
                    <button
                      onClick={handlePrintPreview}
                      disabled={cart.length === 0}
                      className="w-full py-3 bg-gray-800 text-white rounded-lg hover:bg-gray-900 font-medium disabled:opacity-50 flex justify-center items-center gap-2"
                    >
                      <svg
                        className="w-5 h-5"
                        fill="none"
                        stroke="currentColor"
                        viewBox="0 0 24 24"
                      >
                        <path
                          strokeLinecap="round"
                          strokeLinejoin="round"
                          strokeWidth={2}
                          d="M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z"
                        />
                      </svg>
                      Print Preview
                    </button>
                    <button
                      onClick={handleSaveEstimate}
                      disabled={isLoading || cart.length === 0 || !customer}
                      className="w-full py-3 bg-indigo-600 dark:bg-[rgb(var(--color-primary))] text-white rounded-lg hover:bg-indigo-700 dark:hover:bg-[rgb(var(--color-primary-hover))] font-medium disabled:opacity-50 disabled:cursor-not-allowed"
                    >
                      {isLoading ? "Saving..." : "Save Estimate"}
                    </button>
                    <button
                      onClick={handleClear}
                      disabled={cart.length === 0}
                      className="w-full py-3 bg-gray-600 text-white rounded-lg hover:bg-gray-700 font-medium disabled:opacity-50 disabled:cursor-not-allowed"
                    >
                      Clear Cart
                    </button>
                  </div>
                </div>
              </div>
            </div>

            {/* Customer Selection Modal */}
            {showCustomerSelect && (
              <div className="fixed inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center z-50 p-4">
                <div className="bg-white dark:bg-[rgb(var(--color-card))] rounded-xl shadow-2xl border dark:border-[rgb(var(--color-border))] max-w-2xl w-full max-h-[90vh] flex flex-col">
                  {/* Header */}
                  <div className="flex items-center justify-between p-6 border-b border-default dark:border-[rgb(var(--color-border))]">
                    <h3 className="text-xl font-bold text-maindark:text-[rgb(var(--color-text))]">
                      Select Customer
                    </h3>
                    <button
                      onClick={() => setShowCustomerSelect(false)}
                      className="text-muted dark:text-[rgb(var(--color-text-muted))] hover:text-gray-600 dark:hover:text-[rgb(var(--color-text))]"
                    >
                      <svg
                        className="w-6 h-6"
                        fill="none"
                        stroke="currentColor"
                        viewBox="0 0 24 24"
                      >
                        <path
                          strokeLinecap="round"
                          strokeLinejoin="round"
                          strokeWidth={2}
                          d="M6 18L18 6M6 6l12 12"
                        />
                      </svg>
                    </button>
                  </div>

                  {/* Body */}
                  <div className="flex-1 overflow-y-auto p-6">
                    <input
                      type="text"
                      placeholder="Search by name or phone..."
                      value={customerSearchTerm}
                      onChange={(e) => setCustomerSearchTerm(e.target.value)}
                      className="w-full px-4 py-2 border border-gray-300 dark:border-[rgb(var(--color-border))] bg-white dark:bg-[rgb(var(--color-input))] text-maindark:text-[rgb(var(--color-text))] rounded-lg mb-4 focus:ring-2 focus:ring-primary dark:focus:ring-[rgb(var(--color-primary))]"
                    />

                    <div className="space-y-2">
                      {filteredCustomers.map((c: Customer) => (
                        <button
                          key={c._id}
                          onClick={() => selectCustomer(c)}
                          className="w-full p-4 border border-default dark:border-[rgb(var(--color-border))] rounded-lg hover:border-indigo-500 hover:bg-indigo-50 dark:hover:bg-indigo-900/20 text-left transition"
                        >
                          <div className="font-medium text-maindark:text-[rgb(var(--color-text))]">
                            {c.name}
                          </div>
                          <div className="text-sm text-gray-600 dark:text-[rgb(var(--color-text-secondary))]">
                            {c.phone}
                          </div>
                        </button>
                      ))}
                    </div>
                  </div>
                </div>
              </div>
            )}
          </div>
        </div>
        <div className="hidden print:block absolute top-0 left-0 w-full bg-white z-50">
          <EstimateTemplate estimate={getPreviewData()} />
        </div>
        <style>{`
                @media print {
                    body * { visibility: hidden; }
                    .print\\:block, .print\\:block * { visibility: visible; }
                    .print\\:block { position: absolute; left: 0; top: 0; width: 100%; }
                    .print\\:hidden { display: none !important; }
                }
            `}</style>
      </div>
    </Layout>
  );
};

export default Estimate;

import { useEffect, useState } from "react";
import { useNavigate, useParams } from "react-router-dom";
import Layout from "@/shared/ui/Layout/Layout";
import api from "@/shared/api/api";
import { toast } from "react-toastify";
import EstimateTemplate from "@/features/pos-checkout/ui/EstimateTemplate";
import { ArrowLeft, Printer, FileText } from 'lucide-react';

const EstimateDetail = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const [estimate, setEstimate] = useState<any>(null);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    fetchEstimate();
  }, [id]);

  const fetchEstimate = async () => {
    try {
      const user = JSON.parse(localStorage.getItem("user") || '{}');
      const response = await api.get(
        `/api/estimates/${id}`,
        {
          headers: { Authorization: `Bearer ${user.token}` },
        }
      );
      setEstimate(response.data);
    } catch (error: any) {
      toast.error(error.response?.data?.message || "Failed to fetch estimate");
      navigate("/sales/estimates");
    } finally {
      setIsLoading(false);
    }
  };

  const handlePrint = () => {
    window.print();
  };

  if (isLoading || !estimate) {
    return (
      <Layout>
        <div className="flex flex-col items-center justify-center py-20">
          <div className="animate-spin rounded-full h-10 w-10 border-b-2 border-indigo-600 mb-4"></div>
          <p className="text-slate-500 font-medium">Loading estimate...</p>
        </div>
      </Layout>
    );
  }

  return (
    <Layout>
      <div className="max-w-4xl mx-auto animate-fade-in pb-10">
        {/* Header - Hidden on print */}
        <div className="mb-8 print:hidden">
          <button
            onClick={() => navigate("/sales/estimates")}
            className="flex items-center text-slate-600 hover:text-indigo-600 mb-4 transition-colors font-medium gap-2"
          >
            <ArrowLeft className="w-4 h-4" />
            Back to Estimates
          </button>
          <div className="flex justify-between items-start">
            <div>
              <h1 className="text-2xl font-bold text-slate-800 tracking-tight flex items-center gap-2">
                <FileText className="w-6 h-6 text-indigo-600" />
                Estimate Details
              </h1>
              <p className="text-sm text-slate-500 mt-1">
                View and print estimate
              </p>
            </div>
            <button
              onClick={handlePrint}
              className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition-colors shadow-sm font-medium"
            >
              <Printer className="w-4 h-4" />
              Print
            </button>
          </div>
        </div>

        {/* Estimate Card */}
        <div className="bg-white border border-slate-200 rounded-2xl shadow-sm overflow-hidden print:shadow-none print:border-0 print:rounded-none">
          <EstimateTemplate estimate={estimate} />
        </div>
      </div>

      {/* Print Styles */}
      <style>{`
        @media print {
          body * {
            visibility: hidden;
          }
          .print\\:shadow-none,
          .print\\:shadow-none * {
            visibility: visible;
          }
          .print\\:shadow-none {
            position: absolute;
            left: 0;
            top: 0;
            width: 100%;
          }
          .print\\:hidden {
            display: none !important;
          }
        }
      `}</style>
    </Layout>
  );
};

export default EstimateDetail;

import { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import Layout from "@/shared/ui/Layout/Layout";
import api from "@/shared/api/api";
import { toast } from 'react-toastify';
import {
    FileText,
    Plus,
    Search,
    Eye,
    Trash2,
    Calculator,
    CheckCircle,
    Clock,
    XCircle
} from 'lucide-react';
import { Estimate } from '@repo/shared';

const EstimateList = () => {
    const navigate = useNavigate();
    const [estimates, setEstimates] = useState<Estimate[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [searchTerm, setSearchTerm] = useState('');
    const [statusFilter, setStatusFilter] = useState('all');

    useEffect(() => {
        fetchEstimates();
    }, []);

    const fetchEstimates = async () => {
        try {
            const userStr = localStorage.getItem('user');
            if (userStr) {
                const user = JSON.parse(userStr);
                const response = await api.get(
                    `/api/estimates`,
                    {
                        headers: { Authorization: `Bearer ${user.token}` }
                    }
                );
                setEstimates(response.data);
            }
        } catch (error: any) {
            toast.error(error.response?.data?.message || 'Failed to fetch estimates');
        } finally {
            setIsLoading(false);
        }
    };

    const handleDelete = async (id: string) => {
        if (!confirm('Delete this estimate?')) return;

        try {
            const userStr = localStorage.getItem('user');
            if (userStr) {
                const user = JSON.parse(userStr);
                await api.delete(
                    `/api/estimates/${id}`,
                    {
                        headers: { Authorization: `Bearer ${user.token}` }
                    }
                );
                toast.success('Estimate deleted');
                fetchEstimates();
            }
        } catch (error: any) {
            toast.error(error.response?.data?.message || 'Failed to delete estimate');
        }
    };

    // KPI calculations
    const totalEstimates = estimates.length;
    const totalValue = estimates.reduce((sum, est) => sum + (est.totalAmount || 0), 0);
    const acceptedCount = estimates.filter(e => e.status === 'accepted').length;
    const draftCount = estimates.filter(e => e.status === 'draft').length;

    const getStatusBadge = (status: string) => {
        const badges: Record<string, { bg: string, text: string, icon: any }> = {
            draft: { bg: 'bg-slate-100', text: 'text-slate-700', icon: Clock },
            sent: { bg: 'bg-blue-50', text: 'text-blue-700', icon: FileText },
            accepted: { bg: 'bg-emerald-50', text: 'text-emerald-700', icon: CheckCircle },
            rejected: { bg: 'bg-red-50', text: 'text-red-700', icon: XCircle }
        };
        const badge = badges[status] || badges.draft;
        const Icon = badge.icon;
        return (
            <span className={`inline-flex items-center gap-1 px-2.5 py-1 rounded-full text-xs font-bold ${badge.bg} ${badge.text}`}>
                <Icon className="w-3 h-3" />
                {status?.charAt(0).toUpperCase() + status?.slice(1)}
            </span>
        );
    };

    const filteredEstimates = estimates.filter((est) => {
        const customerName = typeof est.customer === 'object' && est.customer ? est.customer.name : '';
        const matchesSearch = est.estimateNo.toLowerCase().includes(searchTerm.toLowerCase()) ||
            customerName?.toLowerCase().includes(searchTerm.toLowerCase());
        const matchesStatus = statusFilter === 'all' || est.status === statusFilter;
        return matchesSearch && matchesStatus;
    });

    if (isLoading) {
        return (
            <Layout>
                <div className="flex flex-col items-center justify-center py-20">
                    <div className="animate-spin rounded-full h-10 w-10 border-b-2 border-indigo-600 mb-4"></div>
                    <p className="text-slate-500 font-medium">Loading estimates...</p>
                </div>
            </Layout>
        );
    }

    return (
        <Layout>
            <div className="space-y-6 animate-fade-in pb-10">
                {/* Header Section */}
                <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                    <div>
                        <h1 className="text-2xl font-bold text-slate-800 tracking-tight flex items-center gap-2">
                            <Calculator className="w-6 h-6 text-indigo-600" />
                            Estimates
                        </h1>
                        <p className="text-sm text-slate-500 mt-1">View and manage all estimates</p>
                    </div>
                    <button
                        onClick={() => navigate('/sales/estimate')}
                        className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 shadow-sm transition-all font-medium"
                    >
                        <Plus className="w-4 h-4" /> Create Estimate
                    </button>
                </div>

                {/* KPI Grid */}
                <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                    <div className="bg-white p-5 rounded-xl shadow-sm border border-slate-100 hover:shadow-md transition-shadow">
                        <div className="flex justify-between items-start">
                            <div>
                                <p className="text-xs font-bold text-slate-400 uppercase tracking-wider">Total Estimates</p>
                                <h3 className="text-2xl font-bold text-slate-800 mt-1">{totalEstimates}</h3>
                            </div>
                            <div className="p-2 bg-indigo-50 rounded-lg text-indigo-600">
                                <FileText className="w-5 h-5" />
                            </div>
                        </div>
                    </div>

                    <div className="bg-white p-5 rounded-xl shadow-sm border border-slate-100 hover:shadow-md transition-shadow">
                        <div className="flex justify-between items-start">
                            <div>
                                <p className="text-xs font-bold text-slate-400 uppercase tracking-wider">Total Value</p>
                                <h3 className="text-2xl font-bold text-slate-800 mt-1">₹{totalValue.toLocaleString()}</h3>
                            </div>
                            <div className="p-2 bg-emerald-50 rounded-lg text-emerald-600">
                                <Calculator className="w-5 h-5" />
                            </div>
                        </div>
                    </div>

                    <div className="bg-white p-5 rounded-xl shadow-sm border border-slate-100 hover:shadow-md transition-shadow">
                        <div className="flex justify-between items-start">
                            <div>
                                <p className="text-xs font-bold text-slate-400 uppercase tracking-wider">Accepted</p>
                                <h3 className="text-2xl font-bold text-emerald-600 mt-1">{acceptedCount}</h3>
                            </div>
                            <div className="p-2 bg-emerald-50 rounded-lg text-emerald-600">
                                <CheckCircle className="w-5 h-5" />
                            </div>
                        </div>
                    </div>

                    <div className="bg-white p-5 rounded-xl shadow-sm border border-slate-100 hover:shadow-md transition-shadow">
                        <div className="flex justify-between items-start">
                            <div>
                                <p className="text-xs font-bold text-slate-400 uppercase tracking-wider">Drafts</p>
                                <h3 className="text-2xl font-bold text-slate-600 mt-1">{draftCount}</h3>
                            </div>
                            <div className="p-2 bg-slate-100 rounded-lg text-slate-600">
                                <Clock className="w-5 h-5" />
                            </div>
                        </div>
                    </div>
                </div>

                {/* Filter Island + Table */}
                <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
                    {/* Filter Bar */}
                    <div className="p-5 border-b border-slate-100 bg-slate-50/50">
                        <div className="flex flex-col md:flex-row gap-4 items-center justify-between">
                            {/* Search */}
                            <div className="relative w-full md:max-w-md group">
                                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                                    <Search className="h-5 w-5 text-slate-400 group-focus-within:text-indigo-500 transition-colors" />
                                </div>
                                <input
                                    type="text"
                                    placeholder="Search estimate # or customer..."
                                    value={searchTerm}
                                    onChange={(e) => setSearchTerm(e.target.value)}
                                    className="block w-full pl-10 pr-3 py-2 border border-slate-300 rounded-lg leading-5 bg-white placeholder-slate-400 focus:outline-none focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500 sm:text-sm transition-all shadow-sm"
                                />
                            </div>

                            {/* Status Filter */}
                            <select
                                value={statusFilter}
                                onChange={(e) => setStatusFilter(e.target.value)}
                                className="px-3 py-2 border border-slate-300 rounded-lg text-sm bg-white focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 shadow-sm"
                            >
                                <option value="all">All Status</option>
                                <option value="draft">Draft</option>
                                <option value="sent">Sent</option>
                                <option value="accepted">Accepted</option>
                                <option value="rejected">Rejected</option>
                            </select>
                        </div>
                    </div>

                    {/* Table */}
                    <div className="overflow-x-auto">
                        <table className="w-full text-left">
                            <thead className="bg-slate-50 border-b border-slate-200">
                                <tr className="text-xs font-bold text-slate-500 uppercase tracking-wider">
                                    <th className="px-6 py-3">Estimate #</th>
                                    <th className="px-6 py-3">Customer</th>
                                    <th className="px-6 py-3">Date</th>
                                    <th className="px-6 py-3 text-right">Amount</th>
                                    <th className="px-6 py-3">Status</th>
                                    <th className="px-6 py-3 text-right">Actions</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-slate-100 bg-white">
                                {filteredEstimates.length === 0 ? (
                                    <tr>
                                        <td colSpan={6} className="px-6 py-12 text-center">
                                            <div className="flex flex-col items-center">
                                                <div className="bg-slate-100 p-3 rounded-full mb-3">
                                                    <FileText className="w-6 h-6 text-slate-400" />
                                                </div>
                                                <p className="text-slate-600 font-medium">No estimates found</p>
                                                <p className="text-sm text-slate-400 mt-1">Try adjusting your search or filters</p>
                                            </div>
                                        </td>
                                    </tr>
                                ) : (
                                    filteredEstimates.map((estimate) => (
                                        <tr key={estimate._id} className="hover:bg-slate-50 transition-colors group">
                                            <td className="px-6 py-4 whitespace-nowrap">
                                                <button
                                                    onClick={() => navigate(`/sales/estimate/${estimate._id}`)}
                                                    className="font-bold text-indigo-600 hover:text-indigo-800"
                                                >
                                                    {estimate.estimateNo}
                                                </button>
                                            </td>
                                            <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-slate-800">
                                                {(typeof estimate.customer === 'object' && estimate.customer?.name) || 'Walk-in Customer'}
                                            </td>
                                            <td className="px-6 py-4 whitespace-nowrap text-sm text-slate-500">
                                                {new Date(estimate.createdAt).toLocaleDateString('en-IN', { day: 'numeric', month: 'short', year: 'numeric' })}
                                            </td>
                                            <td className="px-6 py-4 whitespace-nowrap text-sm font-bold text-slate-800 text-right">
                                                ₹{estimate.totalAmount?.toFixed(2) || '0.00'}
                                            </td>
                                            <td className="px-6 py-4 whitespace-nowrap">
                                                {getStatusBadge(estimate.status)}
                                            </td>
                                            <td className="px-6 py-4 whitespace-nowrap text-right">
                                                <div className="flex justify-end gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                                                    <button
                                                        onClick={() => navigate(`/sales/estimate/${estimate._id}`)}
                                                        className="p-1.5 text-indigo-600 hover:bg-indigo-50 rounded-lg"
                                                        title="View"
                                                    >
                                                        <Eye className="w-4 h-4" />
                                                    </button>
                                                    <button
                                                        onClick={() => handleDelete(estimate._id || '')}
                                                        className="p-1.5 text-red-600 hover:bg-red-50 rounded-lg"
                                                        title="Delete"
                                                    >
                                                        <Trash2 className="w-4 h-4" />
                                                    </button>
                                                </div>
                                            </td>
                                        </tr>
                                    ))
                                )}
                            </tbody>
                        </table>
                    </div>
                </div>
            </div>
        </Layout>
    );
};

export default EstimateList;

import { logger } from '@/shared/lib/logger';
import { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import api from "@/shared/api/api";
import { toast } from "react-toastify";
import Layout from "@/shared/ui/Layout/Layout";
import PageHeader from "@/shared/ui/Layout/PageHeader";
import FormInput from "@/shared/ui/Form/Input";
import CustomerSelectionModal from "@/shared/ui/Modals/CustomerSelectionModal";



const PaymentIn = () => {
  const navigate = useNavigate();

  // Get token from user object in localStorage
  const user = JSON.parse(localStorage.getItem("user") || '{}');
  const token = user?.token;

  const [showCustomerModal, setShowCustomerModal] = useState(false);
  const [loading, setLoading] = useState(false);
  const [bankAccounts, setBankAccounts] = useState<any[]>([]);

  const [formData, setFormData] = useState<any>({
    receiptNo: "RCP-" + Date.now(),
    receiptDate: new Date().toISOString().split("T")[0],
    customer: null,
    paymentMethods: [
      {
        method: "cash",
        amount: 0,
        reference: "",
        bankAccount: "",
        cardType: "",
        chequeNumber: "",
        chequeDate: "",
        chequeBank: "",
      },
    ],
    depositAccount: "cash",
    notes: "",
  });

  const [customerInfo, setCustomerInfo] = useState<any>({
    outstandingDue: 0,
    availableCredit: 0,
    outstandingInvoices: [],
  });

  const [invoiceAllocations, setInvoiceAllocations] = useState<any>({});
  const [creditApplied, setCreditApplied] = useState(0);

  const paymentMethodOptions = [
    { value: "cash", label: "Cash", icon: "💵" },
    { value: "upi", label: "UPI", icon: "📱" },
    { value: "card", label: "Card", icon: "💳" },
    { value: "cheque", label: "Cheque", icon: "🏦" },
    { value: "bank_transfer", label: "Bank Transfer", icon: "🏧" },
  ];

  // Fetch bank accounts on mount
  useEffect(() => {
    fetchBankAccounts();
  }, []);

  // Fetch customer info when customer is selected
  useEffect(() => {
    if (formData.customer) {
      fetchCustomerInfo(formData.customer._id);
    } else {
      setCustomerInfo({
        outstandingDue: 0,
        availableCredit: 0,
        outstandingInvoices: [],
      });
      setInvoiceAllocations({});
      setCreditApplied(0);
    }
  }, [formData.customer]);

  // Auto-adjust deposit account when payment methods change
  useEffect(() => {
    const hasNonCashMethod = formData.paymentMethods.some(
      (pm: any) => pm.method !== "cash"
    );

    // If user switches to UPI or Bank Transfer and deposit account is still "cash",
    // and there are bank accounts available, suggest the first one
    if (
      hasNonCashMethod &&
      formData.depositAccount === "cash" &&
      bankAccounts.length > 0
    ) {
      setFormData({
        ...formData,
        depositAccount: bankAccounts[0]._id,
      });
    }
  }, [formData.paymentMethods]);

  const fetchBankAccounts = async () => {
    try {
      const response = await api.get(`/cashbank/accounts`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      setBankAccounts(response.data);
    } catch (error: any) {
      logger.error("Error fetching bank accounts:", error);
    }
  };

  const fetchCustomerInfo = async (customerId: string) => {
    try {
      const response = await api.get(
        `/payment-in/customer/${customerId}/info`,
        {
          headers: { Authorization: `Bearer ${token}` },
        }
      );
      setCustomerInfo(response.data);
    } catch (error: any) {
      logger.error("Error fetching customer info:", error);
      toast.error("Failed to fetch customer information");
    }
  };

  const handleCustomerSelect = (customer: any) => {
    setFormData({ ...formData, customer });
    setShowCustomerModal(false);
  };

  const addPaymentMethod = () => {
    setFormData({
      ...formData,
      paymentMethods: [
        ...formData.paymentMethods,
        {
          method: "cash",
          amount: 0,
          reference: "",
          bankAccount: "",
          cardType: "",
          chequeNumber: "",
          chequeDate: "",
          chequeBank: "",
        },
      ],
    });
  };

  const removePaymentMethod = (index: number) => {
    const newMethods = formData.paymentMethods.filter((_: any, i: number) => i !== index);
    setFormData({ ...formData, paymentMethods: newMethods });
  };

  const updatePaymentMethod = (index: number, field: string, value: any) => {
    const newMethods = [...formData.paymentMethods];
    newMethods[index][field] = value;
    setFormData({ ...formData, paymentMethods: newMethods });
  };

  const handleInvoiceAllocation = (invoiceId: string, amount: string) => {
    setInvoiceAllocations({
      ...invoiceAllocations,
      [invoiceId]: parseFloat(amount) || 0,
    });
  };

  // Calculate totals
  const totalPayment = formData.paymentMethods.reduce(
    (sum: number, pm: any) => sum + (parseFloat(pm.amount) || 0),
    0
  );
  const totalAllocated = Object.values(invoiceAllocations).reduce(
    (sum: number, amt: any) => sum + amt,
    0
  );
  const effectivePayment = totalPayment + creditApplied;
  const remainingAmount = effectivePayment - totalAllocated;

  const handleSave = async () => {
    // Validation
    if (!formData.customer) {
      toast.error("Please select a customer");
      return;
    }

    if (totalPayment <= 0) {
      toast.error("Total payment must be greater than zero");
      return;
    }

    if (!formData.depositAccount) {
      toast.error("Please select a deposit account");
      return;
    }

    if (creditApplied > customerInfo.availableCredit) {
      toast.error(
        `Credit applied (₹${creditApplied}) exceeds available credit (₹${customerInfo.availableCredit})`
      );
      return;
    }

    if (totalAllocated > effectivePayment) {
      toast.error("Total allocated amount exceeds total payment");
      return;
    }

    // Validate each invoice allocation
    for (const invoice of customerInfo.outstandingInvoices) {
      const allocated = invoiceAllocations[invoice._id] || 0;
      if (allocated > invoice.balance) {
        toast.error(
          `Allocated amount for ${invoice.invoiceNo} exceeds invoice balance`
        );
        return;
      }
    }

    // Prepare payload
    const allocatedInvoices = Object.entries(invoiceAllocations)
      .filter(([_, amount]) => (amount as number) > 0)
      .map(([invoiceId, amount]) => ({
        invoice: invoiceId,
        allocatedAmount: parseFloat(amount as string),
      }));

    // Ensure all payment method amounts are numbers and remove empty fields
    const cleanedPaymentMethods = formData.paymentMethods
      .filter((pm: any) => parseFloat(pm.amount) > 0)
      .map((pm: any) => {
        const cleaned: any = {
          method: pm.method,
          amount: parseFloat(pm.amount),
        };

        // Only add optional fields if they have values
        if (pm.reference && pm.reference.trim())
          cleaned.reference = pm.reference.trim();
        if (pm.bankAccount && pm.bankAccount.trim())
          cleaned.bankAccount = pm.bankAccount.trim();
        if (pm.cardType && pm.cardType.trim())
          cleaned.cardType = pm.cardType.trim();
        if (pm.chequeNumber && pm.chequeNumber.trim())
          cleaned.chequeNumber = pm.chequeNumber.trim();
        if (pm.chequeDate && pm.chequeDate.trim())
          cleaned.chequeDate = pm.chequeDate.trim();
        if (pm.chequeBank && pm.chequeBank.trim())
          cleaned.chequeBank = pm.chequeBank.trim();

        return cleaned;
      });

    const payload = {
      customerId: formData.customer._id,
      paymentDate: formData.receiptDate,
      paymentMethods: cleanedPaymentMethods,
      allocatedInvoices,
      creditApplied: creditApplied || 0,
      depositAccount: formData.depositAccount,
      notes: formData.notes,
    };

    try {
      setLoading(true);
      const response = await api.post(`/payment-in`, payload, {
        headers: { Authorization: `Bearer ${token}` },
      });

      toast.success("Payment recorded successfully!");

      // Reset form
      setFormData({
        receiptNo: "RCP-" + Date.now(),
        receiptDate: new Date().toISOString().split("T")[0],
        customer: null,
        paymentMethods: [
          {
            method: "cash",
            amount: 0,
            reference: "",
            bankAccount: "",
            cardType: "",
            chequeNumber: "",
            chequeDate: "",
            chequeBank: "",
          },
        ],
        depositAccount: "cash",
        notes: "",
      });
      setInvoiceAllocations({});
      setCreditApplied(0);
    } catch (error: any) {
      logger.error("Error saving payment:", error);
      logger.error("Error response:", error.response?.data);
      const errorMessage =
        error.response?.data?.message ||
        error.response?.data?.error ||
        "Failed to save payment";
      toast.error(errorMessage);
    } finally {
      setLoading(false);
    }
  };

  const handlePrint = async () => {
    // Validate form first
    const totalPayment = formData.paymentMethods.reduce(
      (sum: number, pm: any) => sum + parseFloat(pm.amount || 0),
      0
    );
    const totalAllocated = Object.values(invoiceAllocations).reduce(
      (sum: number, amount: any) => sum + parseFloat(amount || 0),
      0
    );
    const effectivePayment = totalPayment + parseFloat(creditApplied as any || 0);

    if (!formData.customer) {
      toast.error("Please select a customer");
      return;
    }

    if (totalPayment <= 0) {
      toast.error("Total payment must be greater than zero");
      return;
    }

    if (!formData.depositAccount) {
      toast.error("Please select a deposit account");
      return;
    }

    // Save payment first
    try {
      setLoading(true);

      // Prepare payload (same as handleSave)
      const allocatedInvoices = Object.entries(invoiceAllocations)
        .filter(([_, amount]: [string, any]) => amount > 0)
        .map(([invoiceId, amount]: [string, any]) => ({
          invoice: invoiceId,
          allocatedAmount: parseFloat(amount),
        }));

      const cleanedPaymentMethods = formData.paymentMethods
        .filter((pm: any) => parseFloat(pm.amount) > 0)
        .map((pm: any) => {
          const cleaned: any = {
            method: pm.method,
            amount: parseFloat(pm.amount),
          };

          if (pm.reference && pm.reference.trim())
            cleaned.reference = pm.reference.trim();
          if (pm.bankAccount && pm.bankAccount.trim())
            cleaned.bankAccount = pm.bankAccount.trim();
          if (pm.cardType && pm.cardType.trim())
            cleaned.cardType = pm.cardType.trim();
          if (pm.chequeNumber && pm.chequeNumber.trim())
            cleaned.chequeNumber = pm.chequeNumber.trim();
          if (pm.chequeDate && pm.chequeDate.trim())
            cleaned.chequeDate = pm.chequeDate.trim();
          if (pm.chequeBank && pm.chequeBank.trim())
            cleaned.chequeBank = pm.chequeBank.trim();

          return cleaned;
        });

      const payload = {
        customerId: formData.customer._id,
        paymentDate: formData.receiptDate,
        paymentMethods: cleanedPaymentMethods,
        allocatedInvoices,
        creditApplied: creditApplied || 0,
        depositAccount: formData.depositAccount,
        notes: formData.notes,
      };

      const response = await api.post(`/payment-in`, payload, {
        headers: { Authorization: `Bearer ${token}` },
      });

      toast.success("Payment saved! Opening print preview...");

      // Navigate to receipt detail page and trigger print
      const paymentId = response.data.payment._id;
      navigate(`/sales/payment-in/${paymentId}`);

      // Trigger print after a short delay to allow page to load
      setTimeout(() => {
        window.print();
      }, 1000);
    } catch (error: any) {
      logger.error("Error saving payment for print:", error);
      logger.error("Error response:", error.response?.data);
      const errorMessage =
        error.response?.data?.message ||
        error.response?.data?.error ||
        "Failed to save payment";
      toast.error(errorMessage);
    } finally {
      setLoading(false);
    }
  };

  return (
    <Layout>
      <div className="flex flex-col h-[calc(100vh-theme(spacing.16))] bg-slate-50 animate-fade-in">
        {/* Sticky Action Bar */}
        <div className="bg-white border-b border-slate-200 px-6 py-4 flex items-center justify-between shadow-sm shrink-0 z-10">
          <div>
            <h1 className="text-2xl font-bold text-slate-800 tracking-tight">Payment In</h1>
            <p className="text-sm text-slate-500 mt-0.5">Record customer payments and receipts</p>
          </div>
          <div className="flex items-center gap-3">
            <button
              onClick={() => navigate("/sales/payment-in-list")}
              className="px-4 py-2 text-sm font-medium text-slate-700 bg-white border border-slate-300 rounded-lg hover:bg-slate-50 transition-colors shadow-sm"
            >
              Cancel
            </button>
            <button
              onClick={handleSave}
              disabled={loading}
              className="px-4 py-2 text-sm font-medium text-white bg-indigo-600 border border-transparent rounded-lg shadow-sm hover:bg-indigo-700 focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500 disabled:opacity-50 transition-all flex items-center gap-2"
            >
              {loading ? (
                <svg className="animate-spin h-4 w-4 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                  <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                  <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                </svg>
              ) : (
                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
                </svg>
              )}
              {loading ? "Saving..." : "Save Payment"}
            </button>
            <button
              onClick={handlePrint}
              disabled={loading}
              className="px-4 py-2 text-sm font-medium text-slate-700 bg-white border border-slate-300 rounded-lg hover:bg-slate-50 transition-colors shadow-sm flex items-center gap-2"
            >
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z" />
              </svg>
              Print
            </button>
          </div>
        </div>

        {/* Scrollable Content */}
        <div className="flex-1 overflow-auto p-6">
          <div className="max-w-7xl mx-auto grid grid-cols-1 lg:grid-cols-3 gap-8 pb-10">
            {/* Left Column (Details & Customer) */}
            <div className="lg:col-span-2 space-y-6">

              {/* Payment Details Card */}
              <div className="bg-white border border-slate-200 rounded-xl shadow-sm overflow-hidden">
                <div className="bg-slate-50/50 px-6 py-3 border-b border-slate-100">
                  <h2 className="text-xs font-bold text-slate-500 uppercase tracking-wider">Payment Information</h2>
                </div>
                <div className="p-6 grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div>
                    <label className="block text-xs font-bold text-slate-500 mb-1.5 uppercase">Receipt Number</label>
                    <input
                      type="text"
                      value={formData.receiptNo}
                      disabled
                      className="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-lg text-sm font-medium text-slate-500"
                    />
                  </div>
                  <div>
                    <label className="block text-xs font-bold text-slate-500 mb-1.5 uppercase">Receipt Date <span className="text-red-500">*</span></label>
                    <input
                      type="date"
                      value={formData.receiptDate}
                      onChange={(e) => setFormData({ ...formData, receiptDate: e.target.value })}
                      className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 shadow-sm"
                    />
                  </div>
                </div>
              </div>

              {/* Customer Selection Card */}
              <div className="bg-white border border-slate-200 rounded-xl shadow-sm overflow-hidden">
                <div className="bg-slate-50/50 px-6 py-3 border-b border-slate-100 flex justify-between items-center">
                  <h2 className="text-xs font-bold text-slate-500 uppercase tracking-wider">Customer Details</h2>
                </div>
                <div className="p-6">
                  {formData.customer ? (
                    <div className="bg-indigo-50/30 border border-indigo-100 rounded-xl p-4 relative group">
                      <div className="flex justify-between items-start">
                        <div>
                          <p className="font-bold text-slate-800 text-lg">{formData.customer.name}</p>
                          <p className="text-sm text-slate-600 mt-1 flex items-center gap-1">
                            <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 5a2 2 0 012-2h3.28a1 1 0 01.948.684l1.498 4.493a1 1 0 01-.502 1.21l-2.257 1.13a11.042 11.042 0 005.516 5.516l1.13-2.257a1 1 0 011.21-.502l4.493 1.498a1 1 0 01.684.949V19a2 2 0 01-2 2h-1C9.716 21 3 14.284 3 6V5z" /></svg>
                            {formData.customer.phone}
                          </p>
                          <div className="flex gap-4 mt-4">
                            <div className="bg-white px-3 py-1.5 rounded-lg border border-slate-200 shadow-sm">
                              <p className="text-[10px] uppercase font-bold text-slate-400">Outstanding</p>
                              <p className="text-sm font-bold text-rose-600">₹{customerInfo.outstandingDue.toFixed(2)}</p>
                            </div>
                            {customerInfo.availableCredit > 0 && (
                              <div className="bg-white px-3 py-1.5 rounded-lg border border-emerald-200 shadow-sm">
                                <p className="text-[10px] uppercase font-bold text-emerald-600">Available Credit</p>
                                <p className="text-sm font-bold text-emerald-700">₹{customerInfo.availableCredit.toFixed(2)}</p>
                              </div>
                            )}
                          </div>
                        </div>
                        <button
                          onClick={() => setFormData({ ...formData, customer: null })}
                          className="text-red-600 hover:text-red-700 text-xs font-medium border border-red-200 bg-white px-3 py-1.5 rounded-lg hover:bg-red-50 transition-colors shadow-sm"
                        >
                          Change
                        </button>
                      </div>
                    </div>
                  ) : (
                    <button
                      onClick={() => setShowCustomerModal(true)}
                      className="w-full py-8 border-2 border-dashed border-slate-300 rounded-xl hover:border-indigo-500 hover:bg-slate-50 transition-all flex flex-col items-center justify-center gap-2 group"
                    >
                      <div className="p-3 bg-white rounded-full shadow-sm group-hover:shadow-md transition-shadow">
                        <svg className="w-6 h-6 text-slate-400 group-hover:text-indigo-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z" /></svg>
                      </div>
                      <span className="font-bold text-slate-600 group-hover:text-indigo-600">Select Customer</span>
                      <span className="text-xs text-slate-400">Search by name, phone or email</span>
                    </button>
                  )}
                </div>
              </div>

              {/* Outstanding Invoices (Allocation) */}
              {formData.customer && customerInfo.outstandingInvoices.length > 0 && (
                <div className="bg-white border border-slate-200 rounded-xl shadow-sm overflow-hidden flex flex-col">
                  <div className="bg-slate-50/50 px-6 py-3 border-b border-slate-100">
                    <h2 className="text-xs font-bold text-slate-500 uppercase tracking-wider">Outstanding Invoices</h2>
                  </div>
                  <div className="overflow-x-auto">
                    <table className="w-full text-left border-collapse">
                      <thead>
                        <tr className="bg-slate-50 border-b border-slate-200 text-xs font-bold text-slate-500 uppercase tracking-wider">
                          <th className="px-6 py-3">Invoice No</th>
                          <th className="px-6 py-3">Date</th>
                          <th className="px-6 py-3 text-right">Total</th>
                          <th className="px-6 py-3 text-right">Balance</th>
                          <th className="px-6 py-3 text-right w-40">Payment</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-100">
                        {customerInfo.outstandingInvoices.map((invoice: any) => (
                          <tr key={invoice._id} className="hover:bg-slate-50 transition-colors">
                            <td className="px-6 py-3 font-medium text-indigo-600 text-sm">
                              {invoice.invoiceNo}
                            </td>
                            <td className="px-6 py-3 text-xs text-slate-500">
                              {new Date(invoice.date).toLocaleDateString()}
                            </td>
                            <td className="px-6 py-3 text-sm font-medium text-right text-slate-700">
                              ₹{invoice.total.toFixed(2)}
                            </td>
                            <td className="px-6 py-3 text-sm font-bold text-right text-rose-600">
                              ₹{invoice.balance.toFixed(2)}
                            </td>
                            <td className="px-6 py-2 text-right">
                              <input
                                type="number"
                                value={invoiceAllocations[invoice._id] || 0}
                                onChange={(e) => handleInvoiceAllocation(invoice._id, e.target.value)}
                                className="w-full px-2 py-1.5 text-right text-sm border border-slate-200 rounded-md focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 transition-all font-medium"
                                placeholder="0.00"
                                max={invoice.balance}
                              />
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                </div>
              )}
            </div>

            {/* Right Column (Payment Methods & Summary) */}
            <div className="space-y-6">
              {/* Payment Methods */}
              <div className="bg-white border border-slate-200 rounded-xl shadow-sm overflow-hidden">
                <div className="bg-slate-50/50 px-6 py-3 border-b border-slate-100 flex justify-between items-center">
                  <h2 className="text-xs font-bold text-slate-500 uppercase tracking-wider">Payment Methods</h2>
                  <button
                    onClick={addPaymentMethod}
                    className="text-xs bg-white border border-indigo-200 text-indigo-600 hover:bg-indigo-50 px-2 py-1 rounded shadow-sm transition-colors font-bold uppercase tracking-wider"
                  >
                    + Add
                  </button>
                </div>
                <div className="p-4 space-y-4">
                  {formData.paymentMethods.map((pm: any, index: number) => (
                    <div key={index} className="p-4 border border-slate-200 rounded-xl bg-slate-50/30 relative">
                      {formData.paymentMethods.length > 1 && (
                        <button
                          onClick={() => removePaymentMethod(index)}
                          className="absolute top-2 right-2 text-slate-400 hover:text-red-600"
                        >
                          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                        </button>
                      )}

                      <div className="space-y-3">
                        {/* Method Select */}
                        <div>
                          <label className="block text-[10px] uppercase font-bold text-slate-400 mb-1">Method</label>
                          <select
                            value={pm.method}
                            onChange={(e) => updatePaymentMethod(index, "method", e.target.value)}
                            className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm bg-white focus:ring-2 focus:ring-indigo-500"
                          >
                            {paymentMethodOptions.map((opt) => (
                              <option key={opt.value} value={opt.value}>
                                {opt.icon} {opt.label}
                              </option>
                            ))}
                          </select>
                        </div>

                        {/* Amount Input */}
                        <div>
                          <label className="block text-[10px] uppercase font-bold text-slate-400 mb-1">Amount</label>
                          <div className="relative">
                            <span className="absolute left-3 top-2 text-slate-500 font-bold">₹</span>
                            <input
                              type="number"
                              value={pm.amount}
                              onChange={(e) => updatePaymentMethod(index, "amount", parseFloat(e.target.value) || 0)}
                              className="w-full pl-8 pr-3 py-2 border border-slate-300 rounded-lg text-sm font-bold text-slate-800 focus:ring-2 focus:ring-indigo-500"
                              placeholder="0.00"
                            />
                          </div>
                        </div>

                        {/* Dynamic Fields based on Method */}
                        {pm.method === "upi" && (
                          <div>
                            <label className="block text-[10px] uppercase font-bold text-slate-400 mb-1">Transaction Ref</label>
                            <input
                              type="text"
                              value={pm.reference}
                              onChange={(e) => updatePaymentMethod(index, "reference", e.target.value)}
                              className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm"
                              placeholder="UPI ID / Ref No"
                            />
                          </div>
                        )}

                        {(pm.method === "bank_transfer" || pm.method === "cheque") && (
                          <div className="space-y-3 pt-2 border-t border-slate-200 mt-2">
                            <div>
                              <label className="block text-[10px] uppercase font-bold text-slate-400 mb-1">Deposit To Bank</label>
                              <select
                                value={pm.bankAccount}
                                onChange={(e) => updatePaymentMethod(index, "bankAccount", e.target.value)}
                                className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm"
                              >
                                <option value="">Select Bank Account</option>
                                {bankAccounts.map((acc) => (
                                  <option key={acc._id} value={acc._id}>{acc.bankName} - {acc.accountNumber.slice(-4)}</option>
                                ))}
                              </select>
                            </div>
                            {pm.method === "cheque" && (
                              <div className="grid grid-cols-2 gap-3">
                                <input
                                  type="text"
                                  value={pm.chequeNumber}
                                  onChange={(e) => updatePaymentMethod(index, "chequeNumber", e.target.value)}
                                  className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm"
                                  placeholder="Cheque No"
                                />
                                <input
                                  type="date"
                                  value={pm.chequeDate}
                                  onChange={(e) => updatePaymentMethod(index, "chequeDate", e.target.value)}
                                  className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm"
                                />
                              </div>
                            )}
                          </div>
                        )}
                      </div>
                    </div>
                  ))}
                </div>
              </div>

              {/* Deposit To (Global) */}
              <div className="bg-white border border-slate-200 rounded-xl shadow-sm p-5">
                <h2 className="text-xs font-bold text-slate-500 uppercase tracking-wider mb-3">Deposit Verification</h2>
                {(() => {
                  const hasNonCashMethod = formData.paymentMethods.some((pm: any) => pm.method !== "cash");
                  if (hasNonCashMethod) {
                    return (
                      <select
                        value={formData.depositAccount}
                        onChange={(e) => setFormData({ ...formData, depositAccount: e.target.value })}
                        className="w-full px-4 py-2 border border-slate-300 rounded-lg text-sm font-medium"
                      >
                        <option value="">Select Bank Account</option>
                        {bankAccounts.map((acc: any) => (
                          <option key={acc._id} value={acc._id}>🏦 {acc.bankName} - {acc.accountNumber.slice(-4)}</option>
                        ))}]
                      </select>
                    );
                  }
                  return (
                    <select
                      value={formData.depositAccount}
                      onChange={(e) => setFormData({ ...formData, depositAccount: e.target.value })}
                      className="w-full px-4 py-2 border border-slate-300 rounded-lg text-sm font-medium"
                    >
                      <option value="cash">💵 Cash in Hand</option>
                      {bankAccounts.map((acc: any) => (
                        <option key={acc._id} value={acc._id}>🏦 {acc.bankName} - {acc.accountNumber.slice(-4)}</option>
                      ))}
                    </select>
                  );
                })()}
              </div>

              {/* Summary Card */}
              <div className="bg-white border border-indigo-100 rounded-xl shadow-sm overflow-hidden flex flex-col">
                <div className="bg-indigo-50/50 px-6 py-3 border-b border-indigo-100">
                  <h2 className="text-xs font-bold text-indigo-800 uppercase tracking-wider">Payment Summary</h2>
                </div>
                <div className="p-6 space-y-4">
                  <div className="flex justify-between text-sm">
                    <span className="text-slate-500 font-medium">Total Received</span>
                    <span className="font-bold text-slate-800">₹{totalPayment.toFixed(2)}</span>
                  </div>
                  <div className="flex justify-between text-sm border-b border-slate-100 pb-3">
                    <span className="text-slate-500 font-medium">Used from Credit</span>
                    <div className="flex items-center gap-2">
                      <span className="text-xs text-slate-400">(Available: ₹{customerInfo.availableCredit})</span>
                      <input
                        type="number"
                        value={creditApplied}
                        onChange={(e) => setCreditApplied(parseFloat(e.target.value) || 0)}
                        className="w-20 text-right px-2 py-1 text-xs border border-slate-300 rounded focus:ring-1 focus:ring-indigo-500"
                        max={Math.min(customerInfo.availableCredit, totalAllocated as number)}
                      />
                    </div>
                  </div>

                  <div className="flex justify-between text-sm">
                    <span className="text-slate-500 font-medium">Allocated to Invoices</span>
                    <span className="font-bold text-indigo-600">₹{totalAllocated.toFixed(2)}</span>
                  </div>

                  <div className="pt-2">
                    <div className="flex justify-between items-center bg-slate-50 p-3 rounded-lg border border-slate-100">
                      <span className="text-sm font-bold text-slate-600">Unallocated / Excess</span>
                      <span className={`text-lg font-bold ${remainingAmount < 0 ? 'text-red-500' : 'text-emerald-600'}`}>
                        {remainingAmount < 0 ? '-' : '+'}₹{Math.abs(remainingAmount).toFixed(2)}
                      </span>
                    </div>
                    {remainingAmount > 0 && (
                      <p className="text-[10px] text-center text-slate-400 mt-2">
                        Positive amount will be added to customer credit
                      </p>
                    )}
                    {remainingAmount < 0 && (
                      <p className="text-[10px] text-center text-red-400 mt-2 font-bold">
                        Allocation exceeds payment amount!
                      </p>
                    )}
                  </div>
                </div>
              </div>

              {/* Notes */}
              <div className="bg-white border border-slate-200 rounded-xl shadow-sm p-5">
                <h2 className="text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">Notes</h2>
                <textarea
                  value={formData.notes}
                  onChange={(e) => setFormData({ ...formData, notes: e.target.value })}
                  className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm resize-none focus:ring-2 focus:ring-indigo-500"
                  rows={3}
                  placeholder="Add remarks..."
                />
              </div>

            </div>
          </div>
        </div>

        <CustomerSelectionModal
          isOpen={showCustomerModal}
          onClose={() => setShowCustomerModal(false)}
          onSelect={handleCustomerSelect}
        />
      </div>
    </Layout>
  );
};

export default PaymentIn;

import React, { useState, useMemo } from 'react';
import { useSelector } from 'react-redux';
import {
    Receipt, Search, Plus, Trash2, Printer, Mail, MessageCircle,
    Calendar, User, CreditCard, Banknote, Smartphone, Building2,
    CheckCircle, AlertCircle, ChevronDown, Save, RefreshCw, Wallet
} from 'lucide-react';
import { RootState } from "@/app/store/store";

// Types
interface Customer {
    id: string;
    name: string;
    phone: string;
    email?: string;
    outstandingBalance: number;
    advanceBalance: number;
}

interface Invoice {
    id: string;
    invoiceNo: string;
    date: string;
    totalAmount: number;
    balanceDue: number;
    allocatedAmount: number;
}

interface PaymentMethod {
    id: string;
    method: 'CASH' | 'UPI' | 'CARD' | 'BANK' | 'CHEQUE' | 'WALLET';
    amount: number;
    reference: string;
    depositTo: string;
}

// Demo data - replaced by Redux state
// Customers fetched from Redux posSlice

const generateDemoInvoices = (customerId: string): Invoice[] => {
    if (!customerId || customerId === 'WALKIN') return [];
    return [
        { id: 'INV001', invoiceNo: 'INV/2026/0001', date: '2026-01-05', totalAmount: 25000, balanceDue: 25000, allocatedAmount: 0 },
        { id: 'INV002', invoiceNo: 'INV/2026/0002', date: '2026-01-08', totalAmount: 15000, balanceDue: 10000, allocatedAmount: 0 },
        { id: 'INV003', invoiceNo: 'INV/2026/0003', date: '2026-01-10', totalAmount: 18000, balanceDue: 10000, allocatedAmount: 0 },
    ];
};

const methodConfig = {
    CASH: { label: 'Cash', icon: Banknote, color: 'text-green-600' },
    UPI: { label: 'UPI', icon: Smartphone, color: 'text-purple-600' },
    CARD: { label: 'Card', icon: CreditCard, color: 'text-blue-600' },
    BANK: { label: 'Bank Transfer', icon: Building2, color: 'text-indigo-600' },
    CHEQUE: { label: 'Cheque', icon: Receipt, color: 'text-amber-600' },
    WALLET: { label: 'Wallet', icon: Wallet, color: 'text-pink-600' },
};

const depositOptions = ['Cash Counter', 'HDFC Bank - 1234', 'ICICI Bank - 5678', 'Petty Cash'];

const PaymentInCreator: React.FC = () => {
    // Generate receipt number
    const generateReceiptNo = () => `RCP-${new Date().getFullYear()}-${String(Math.floor(Math.random() * 10000)).padStart(5, '0')}`;

    const { user } = useSelector((state: RootState) => state.auth);
    const { customers: posCustomers } = useSelector((state: RootState) => state.pos);

    // Filter customers by tenant
    const availableCustomers: Customer[] = useMemo(() => {
        return posCustomers.map((c: any) => ({
            id: c.id,
            name: c.name,
            phone: c.phone || '',
            email: c.email,
            outstandingBalance: c.outstandingBalance || c.outstanding_balance || 0,
            advanceBalance: c.advanceBalance || 0
        }));
    }, [posCustomers]);

    // State
    const [receiptNo] = useState(generateReceiptNo);
    const [receiptDate, setReceiptDate] = useState(new Date().toISOString().split('T')[0]);

    const [customer, setCustomer] = useState<Customer | null>(null);
    const [customerSearch, setCustomerSearch] = useState('');
    const [showCustomerDropdown, setShowCustomerDropdown] = useState(false);

    const [paymentMethods, setPaymentMethods] = useState<PaymentMethod[]>([
        { id: 'PM1', method: 'CASH', amount: 0, reference: '', depositTo: 'Cash Counter' }
    ]);

    const [invoices, setInvoices] = useState<Invoice[]>([]);
    const [isCustomerLocked, setIsCustomerLocked] = useState(false);

    // Filtered customers
    const filteredCustomers = useMemo(() => {
        if (!customerSearch) return availableCustomers;
        const q = customerSearch.toLowerCase();
        return availableCustomers.filter(c =>
            c.name.toLowerCase().includes(q) || c.phone.includes(q)
        );
    }, [customerSearch, availableCustomers]);

    // Select customer
    const selectCustomer = (c: Customer) => {
        setCustomer(c);
        setInvoices(generateDemoInvoices(c.id));
        setShowCustomerDropdown(false);
        setCustomerSearch('');
    };

    // Payment methods
    const addPaymentMethod = () => {
        setPaymentMethods([...paymentMethods, {
            id: `PM${Date.now()}`,
            method: 'CASH',
            amount: 0,
            reference: '',
            depositTo: 'Cash Counter'
        }]);
        setIsCustomerLocked(true);
    };

    const updatePaymentMethod = (id: string, field: keyof PaymentMethod, value: string | number) => {
        setPaymentMethods(methods => methods.map(m =>
            m.id === id ? { ...m, [field]: value } : m
        ));
        if (field === 'amount' && (typeof value === 'number' ? value : parseFloat(value as string)) > 0) {
            setIsCustomerLocked(true);
        }
    };

    const removePaymentMethod = (id: string) => {
        if (paymentMethods.length > 1) {
            setPaymentMethods(methods => methods.filter(m => m.id !== id));
        }
    };

    // Invoice allocation
    const updateAllocation = (invoiceId: string, amount: number) => {
        setInvoices(invs => invs.map(inv =>
            inv.id === invoiceId
                ? { ...inv, allocatedAmount: Math.min(amount, inv.balanceDue) }
                : inv
        ));
    };

    const autoAllocate = () => {
        let remaining = totalPayment;
        setInvoices(invs => invs.map(inv => {
            if (remaining <= 0) return { ...inv, allocatedAmount: 0 };
            const allocate = Math.min(remaining, inv.balanceDue);
            remaining -= allocate;
            return { ...inv, allocatedAmount: allocate };
        }));
    };

    // Calculations
    const totalPayment = useMemo(() =>
        paymentMethods.reduce((sum, m) => sum + (m.amount || 0), 0)
        , [paymentMethods]);

    const totalAllocated = useMemo(() =>
        invoices.reduce((sum, inv) => sum + inv.allocatedAmount, 0)
        , [invoices]);

    const advanceCreated = Math.max(0, totalPayment - totalAllocated);
    const remainingUnallocated = Math.max(0, totalPayment - totalAllocated);

    // Format currency
    const formatCurrency = (amount: number) =>
        new Intl.NumberFormat('en-IN', { style: 'currency', currency: 'INR', maximumFractionDigits: 0 }).format(amount);

    // Clear all
    const handleClear = () => {
        setCustomer(null);
        setInvoices([]);
        setPaymentMethods([{ id: 'PM1', method: 'CASH', amount: 0, reference: '', depositTo: 'Cash Counter' }]);
        setIsCustomerLocked(false);
    };

    return (
        <div className="h-full flex flex-col bg-white dark:bg-neutral-900">
            {/* Header */}
            <div className="px-4 py-3 border-b border-neutral-200 dark:border-neutral-800">
                <div className="flex flex-wrap items-center justify-between gap-4">
                    <div className="flex items-center gap-4">
                        <div className="flex items-center gap-2">
                            <Receipt className="w-5 h-5 text-green-600" />
                            <span className="font-bold text-lg">{receiptNo}</span>
                        </div>
                        <span className="px-2 py-1 rounded-full text-xs font-bold bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400">
                            New Receipt
                        </span>
                    </div>
                    <div className="flex items-center gap-4 text-sm">
                        <div className="flex items-center gap-2">
                            <Calendar className="w-4 h-4 text-neutral-400" />
                            <input
                                type="date"
                                value={receiptDate}
                                onChange={e => setReceiptDate(e.target.value)}
                                className="input text-sm w-36"
                            />
                        </div>
                        <div className="text-neutral-500">
                            <span className="font-medium">By:</span> {user?.name || 'Admin'}
                        </div>
                    </div>
                </div>
            </div>

            <div className="flex-1 overflow-auto p-4">
                <div className="grid lg:grid-cols-2 gap-4">
                    {/* Left Column */}
                    <div className="space-y-4">
                        {/* Customer Section */}
                        <div className="bg-neutral-50 dark:bg-neutral-800/50 rounded-xl p-4">
                            <div className="flex items-center justify-between mb-3">
                                <h3 className="font-bold text-sm flex items-center gap-2">
                                    <User className="w-4 h-4" /> Customer
                                </h3>
                                {customer && !isCustomerLocked && (
                                    <button onClick={() => setCustomer(null)} className="text-xs text-red-500 hover:underline">
                                        Change
                                    </button>
                                )}
                            </div>

                            {customer ? (
                                <div className="space-y-3">
                                    <div className="flex items-center justify-between">
                                        <div>
                                            <p className="font-bold text-lg">{customer.name}</p>
                                            <p className="text-sm text-neutral-500">{customer.phone}</p>
                                        </div>
                                        {isCustomerLocked && (
                                            <span className="text-xs text-amber-600 bg-amber-100 dark:bg-amber-900/30 px-2 py-1 rounded">
                                                Locked
                                            </span>
                                        )}
                                    </div>
                                    <div className="grid grid-cols-2 gap-3">
                                        <div className="p-3 bg-red-50 dark:bg-red-900/20 rounded-lg">
                                            <p className="text-xs text-red-600 dark:text-red-400 font-medium">Outstanding</p>
                                            <p className="text-lg font-bold text-red-700 dark:text-red-400">
                                                {formatCurrency(customer.outstandingBalance)}
                                            </p>
                                        </div>
                                        <div className="p-3 bg-green-50 dark:bg-green-900/20 rounded-lg">
                                            <p className="text-xs text-green-600 dark:text-green-400 font-medium">Advance</p>
                                            <p className="text-lg font-bold text-green-700 dark:text-green-400">
                                                {formatCurrency(customer.advanceBalance)}
                                            </p>
                                        </div>
                                    </div>
                                </div>
                            ) : (
                                <div className="relative">
                                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-neutral-400" />
                                    <input
                                        type="text"
                                        placeholder="Search customer by name or phone..."
                                        value={customerSearch}
                                        onChange={e => { setCustomerSearch(e.target.value); setShowCustomerDropdown(true); }}
                                        onFocus={() => setShowCustomerDropdown(true)}
                                        className="input pl-10"
                                    />
                                    {showCustomerDropdown && filteredCustomers.length > 0 && (
                                        <div className="absolute top-full left-0 right-0 bg-white dark:bg-neutral-800 border border-neutral-200 dark:border-neutral-700 rounded-lg shadow-xl mt-1 max-h-48 overflow-auto z-20">
                                            {filteredCustomers.map(c => (
                                                <button
                                                    key={c.id}
                                                    onClick={() => selectCustomer(c)}
                                                    className="w-full text-left px-4 py-3 hover:bg-neutral-100 dark:hover:bg-neutral-700 border-b border-neutral-100 dark:border-neutral-700 last:border-0"
                                                >
                                                    <div className="flex justify-between">
                                                        <span className="font-medium">{c.name}</span>
                                                        <span className="text-xs text-red-500">Due: {formatCurrency(c.outstandingBalance)}</span>
                                                    </div>
                                                    <span className="text-xs text-neutral-500">{c.phone}</span>
                                                </button>
                                            ))}
                                        </div>
                                    )}
                                </div>
                            )}
                        </div>

                        {/* Payment Methods */}
                        <div className="bg-neutral-50 dark:bg-neutral-800/50 rounded-xl p-4">
                            <div className="flex items-center justify-between mb-3">
                                <h3 className="font-bold text-sm flex items-center gap-2">
                                    <CreditCard className="w-4 h-4" /> Payment Methods
                                </h3>
                                <button onClick={addPaymentMethod} className="btn btn-sm btn-secondary">
                                    <Plus className="w-4 h-4" /> Add
                                </button>
                            </div>

                            <div className="space-y-3">
                                {paymentMethods.map((pm, idx) => {
                                    const config = methodConfig[pm.method];
                                    const Icon = config.icon;
                                    return (
                                        <div key={pm.id} className="grid grid-cols-12 gap-2 items-center p-3 bg-white dark:bg-neutral-800 rounded-lg border border-neutral-200 dark:border-neutral-700">
                                            <div className="col-span-3">
                                                <select
                                                    value={pm.method}
                                                    onChange={e => updatePaymentMethod(pm.id, 'method', e.target.value)}
                                                    className="select text-sm"
                                                >
                                                    {Object.entries(methodConfig).map(([key, val]) => (
                                                        <option key={key} value={key}>{val.label}</option>
                                                    ))}
                                                </select>
                                            </div>
                                            <div className="col-span-3">
                                                <input
                                                    type="number"
                                                    placeholder="Amount"
                                                    value={pm.amount || ''}
                                                    onChange={e => updatePaymentMethod(pm.id, 'amount', parseFloat(e.target.value) || 0)}
                                                    className="input text-right"
                                                />
                                            </div>
                                            <div className="col-span-3">
                                                <input
                                                    type="text"
                                                    placeholder="Reference"
                                                    value={pm.reference}
                                                    onChange={e => updatePaymentMethod(pm.id, 'reference', e.target.value)}
                                                    className="input text-sm"
                                                />
                                            </div>
                                            <div className="col-span-2">
                                                <select
                                                    value={pm.depositTo}
                                                    onChange={e => updatePaymentMethod(pm.id, 'depositTo', e.target.value)}
                                                    className="select text-sm"
                                                >
                                                    {depositOptions.map(opt => (
                                                        <option key={opt} value={opt}>{opt}</option>
                                                    ))}
                                                </select>
                                            </div>
                                            <div className="col-span-1 text-center">
                                                {paymentMethods.length > 1 && (
                                                    <button onClick={() => removePaymentMethod(pm.id)} className="text-red-500 hover:text-red-700">
                                                        <Trash2 className="w-4 h-4" />
                                                    </button>
                                                )}
                                            </div>
                                        </div>
                                    );
                                })}
                            </div>

                            <div className="mt-4 p-3 bg-green-50 dark:bg-green-900/20 rounded-lg flex justify-between items-center">
                                <span className="font-bold text-green-700 dark:text-green-400">Total Payment</span>
                                <span className="text-xl font-bold text-green-700 dark:text-green-400">
                                    {formatCurrency(totalPayment)}
                                </span>
                            </div>
                        </div>
                    </div>

                    {/* Right Column - Invoice Allocation */}
                    <div className="space-y-4">
                        <div className="bg-neutral-50 dark:bg-neutral-800/50 rounded-xl p-4 h-full">
                            <div className="flex items-center justify-between mb-3">
                                <h3 className="font-bold text-sm flex items-center gap-2">
                                    <Receipt className="w-4 h-4" /> Invoice Allocation
                                </h3>
                                {customer && invoices.length > 0 && (
                                    <button onClick={autoAllocate} className="btn btn-sm btn-secondary">
                                        Auto-Allocate
                                    </button>
                                )}
                            </div>

                            {!customer ? (
                                <div className="text-center py-12 text-neutral-400">
                                    <User className="w-12 h-12 mx-auto mb-3 opacity-50" />
                                    <p>Select a customer to see open invoices</p>
                                </div>
                            ) : invoices.length === 0 ? (
                                <div className="text-center py-12 text-neutral-400">
                                    <CheckCircle className="w-12 h-12 mx-auto mb-3 opacity-50 text-green-500" />
                                    <p>No outstanding invoices</p>
                                </div>
                            ) : (
                                <div className="space-y-2">
                                    {invoices.map(inv => (
                                        <div key={inv.id} className="p-3 bg-white dark:bg-neutral-800 rounded-lg border border-neutral-200 dark:border-neutral-700">
                                            <div className="flex items-center justify-between mb-2">
                                                <div>
                                                    <span className="font-medium text-brand-600">{inv.invoiceNo}</span>
                                                    <span className="text-xs text-neutral-500 ml-2">{inv.date}</span>
                                                </div>
                                                <span className="text-sm font-medium">{formatCurrency(inv.totalAmount)}</span>
                                            </div>
                                            <div className="flex items-center gap-3">
                                                <div className="flex-1">
                                                    <div className="flex justify-between text-xs text-neutral-500 mb-1">
                                                        <span>Balance Due</span>
                                                        <span className="text-red-600 font-medium">{formatCurrency(inv.balanceDue)}</span>
                                                    </div>
                                                </div>
                                                <div className="w-32">
                                                    <input
                                                        type="number"
                                                        placeholder="Allocate"
                                                        value={inv.allocatedAmount || ''}
                                                        onChange={e => updateAllocation(inv.id, parseFloat(e.target.value) || 0)}
                                                        max={inv.balanceDue}
                                                        className="input text-right text-sm"
                                                    />
                                                </div>
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            )}

                            {/* Summary */}
                            {customer && (
                                <div className="mt-4 p-4 bg-white dark:bg-neutral-800 rounded-lg border border-neutral-200 dark:border-neutral-700 space-y-2">
                                    <div className="flex justify-between text-sm">
                                        <span className="text-neutral-500">Total Payment</span>
                                        <span className="font-medium">{formatCurrency(totalPayment)}</span>
                                    </div>
                                    <div className="flex justify-between text-sm">
                                        <span className="text-neutral-500">Allocated to Invoices</span>
                                        <span className="font-medium text-green-600">{formatCurrency(totalAllocated)}</span>
                                    </div>
                                    {advanceCreated > 0 && (
                                        <div className="flex justify-between text-sm">
                                            <span className="text-blue-600">Advance Created</span>
                                            <span className="font-medium text-blue-600">{formatCurrency(advanceCreated)}</span>
                                        </div>
                                    )}
                                    <div className="border-t border-neutral-200 dark:border-neutral-700 pt-2">
                                        <div className="flex justify-between font-bold">
                                            <span>Remaining</span>
                                            <span className={remainingUnallocated > 0 ? 'text-amber-600' : 'text-green-600'}>
                                                {formatCurrency(remainingUnallocated)}
                                            </span>
                                        </div>
                                    </div>
                                </div>
                            )}
                        </div>
                    </div>
                </div>
            </div>

            {/* Actions */}
            <div className="px-4 py-3 border-t border-neutral-200 dark:border-neutral-800 flex flex-wrap gap-3 justify-between">
                <div className="flex gap-2">
                    <button onClick={handleClear} className="btn btn-ghost text-red-500">
                        <RefreshCw className="w-4 h-4" /> Clear
                    </button>
                </div>
                <div className="flex gap-2">
                    <button className="btn btn-secondary">
                        <Printer className="w-4 h-4" /> Print Receipt
                    </button>
                    <button className="btn btn-secondary">
                        <MessageCircle className="w-4 h-4" /> WhatsApp
                    </button>
                    <button className="btn btn-secondary">
                        <Mail className="w-4 h-4" /> Email
                    </button>
                    <button className="btn btn-primary" disabled={totalPayment === 0}>
                        <Save className="w-4 h-4" /> Save Payment
                    </button>
                </div>
            </div>
        </div>
    );
};

export default PaymentInCreator;

import { logger } from '@/shared/lib/logger';
import React, { useState, useMemo } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { useNavigate } from 'react-router-dom';
import {
    Search, Plus, Filter, Download, Printer, Eye,
    MoreHorizontal, Calendar, IndianRupee, History,
    CreditCard, X
} from 'lucide-react';
import { RootState } from "@/app/store/store";
import { getTable } from "@/shared/api/dataSource";
import Layout from "@/shared/ui/Layout/Layout";
import PageHeader from "@/shared/ui/Layout/PageHeader";
import MetricCard from "@/shared/ui/Feedback/MetricCard";

// Demo Data Interface
interface PaymentRecord {
    id: string;
    receiptNo: string;
    date: string;
    customerName: string;
    customerPhone: string;
    amount: number;
    modes: string[];
    reference: string;
    excessAmount?: number;
    allocatedCount?: number;
}

const PaymentInList: React.FC = () => {
    const dispatch = useDispatch();
    const navigate = useNavigate();
    const [searchQuery, setSearchQuery] = useState('');
    const [payments, setPayments] = useState<PaymentRecord[]>([]);
    const [loading, setLoading] = useState(true);

    // Fetch payments on mount
    React.useEffect(() => {
        const fetchPayments = async () => {
            try {
                setLoading(true);
                const data = await getTable<any>('payments', {});
                if (data) {
                    setPayments(data.map((p: any) => ({
                        id: p.id || p._id,
                        receiptNo: p.receiptNumber || `RCP-${p.id?.slice(-5) || '00000'}`,
                        date: p.paymentDate || p.date,
                        customerName: p.customer?.name || p.customer_name || 'Customer',
                        customerPhone: p.customer?.phone || p.customer_phone || '',
                        amount: p.totalAmount || p.amount || 0,
                        modes: p.paymentMethods?.map((pm: any) => pm.method) || [p.mode || 'Cash'],
                        reference: p.reference || '-',
                        excessAmount: p.excessAmount || 0,
                        allocatedCount: p.allocatedInvoices?.length || 0
                    })));
                }
            } catch (error) {
                logger.error('Error fetching payments:', error);
            } finally {
                setLoading(false);
            }
        };
        fetchPayments();
    }, []);

    // Filter payments
    const filteredPayments = useMemo(() => {
        if (!searchQuery) return payments;
        const q = searchQuery.toLowerCase();
        return payments.filter(p =>
            p.receiptNo.toLowerCase().includes(q) ||
            p.customerName.toLowerCase().includes(q) ||
            p.customerPhone.includes(q)
        );
    }, [searchQuery, payments]);

    // Dashboard Metrics
    const metrics = useMemo(() => {
        const totalValue = payments.reduce((sum, p) => sum + p.amount, 0);
        const creditCount = payments.filter(p => (p.excessAmount || 0) > 0).length;
        return {
            totalValue,
            count: payments.length,
            creditCount
        };
    }, [payments]);

    // Format currency
    const formatCurrency = (amount: number) =>
        new Intl.NumberFormat('en-IN', { style: 'currency', currency: 'INR', maximumFractionDigits: 0 }).format(amount);

    return (
        <Layout>
            <div className="space-y-6 animate-fade-in pb-10">
                <PageHeader
                    title="Payment In"
                    description="Track and manage customer payment records"
                    actions={
                        <div className="flex gap-3">
                            <button
                                onClick={() => window.print()}
                                className="btn btn-secondary bg-white"
                                title="Print List"
                            >
                                <Printer className="w-4 h-4" />
                            </button>
                            <button
                                onClick={() => navigate('/sales/payment-in')}
                                className="btn btn-primary"
                            >
                                <Plus className="w-4 h-4" />
                                Record Payment
                            </button>
                        </div>
                    }
                />

                {/* Dashboard Metrics */}
                <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                    <MetricCard
                        title="Total Collections"
                        value={formatCurrency(metrics.totalValue)}
                        icon={IndianRupee}
                        color="emerald"
                    />
                    <MetricCard
                        title="Transactions"
                        value={metrics.count}
                        icon={History}
                        color="blue"
                    />
                    <MetricCard
                        title="With Credit/Excess"
                        value={metrics.creditCount}
                        icon={CreditCard}
                        color="amber"
                    />
                </div>

                <div className="bg-white dark:bg-neutral-900 rounded-xl shadow-sm border border-neutral-200 dark:border-neutral-800 overflow-hidden flex flex-col">
                    {/* Controls */}
                    <div className="p-4 bg-neutral-50/50 dark:bg-neutral-800/50 border-b border-neutral-200 dark:border-neutral-800 flex flex-col md:flex-row gap-4 items-center justify-between">
                        <div className="relative flex-1 max-w-md group w-full">
                            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-neutral-400 group-focus-within:text-brand-500 transition-colors" />
                            <input
                                type="text"
                                placeholder="Search receipt #, customer name..."
                                value={searchQuery}
                                onChange={(e) => setSearchQuery(e.target.value)}
                                className="input pl-10 w-full"
                            />
                        </div>
                        <div className="flex gap-2 w-full md:w-auto">
                            {searchQuery && (
                                <button
                                    onClick={() => setSearchQuery('')}
                                    className="btn btn-ghost text-neutral-500"
                                >
                                    <X className="w-4 h-4 mr-2" /> Clear
                                </button>
                            )}
                            <button className="btn btn-secondary">
                                <Filter className="w-4 h-4" /> Filter
                            </button>
                            <button className="btn btn-secondary">
                                <Download className="w-4 h-4" /> Export
                            </button>
                        </div>
                    </div>

                    {/* Data Display */}
                    <div className="flex-1 overflow-auto">
                        {loading ? (
                            <div className="flex flex-col items-center justify-center py-20">
                                <div className="animate-spin rounded-full h-10 w-10 border-b-2 border-brand-600 mb-4"></div>
                                <p className="text-neutral-500 font-medium font-outfit">Loading payments...</p>
                            </div>
                        ) : filteredPayments.length === 0 ? (
                            <div className="flex flex-col items-center justify-center py-20 text-center px-4 font-outfit">
                                <div className="w-16 h-16 bg-neutral-100 dark:bg-neutral-800 rounded-full flex items-center justify-center mb-4">
                                    <Search className="w-8 h-8 opacity-50" />
                                </div>
                                <p className="text-lg font-bold text-neutral-800 dark:text-neutral-200">No records found</p>
                                <p className="text-sm text-neutral-500 mt-1 max-w-xs">
                                    Try adjusting your search or record a new payment.
                                </p>
                                <button
                                    onClick={() => navigate('/sales/payment-in')}
                                    className="btn btn-primary mt-6"
                                >
                                    Record Payment
                                </button>
                            </div>
                        ) : (
                            <>
                                {/* Desktop Table View */}
                                <div className="hidden md:block">
                                    <table className="w-full text-left font-outfit">
                                        <thead className="bg-neutral-50 dark:bg-neutral-800 border-b border-neutral-200 dark:border-neutral-700">
                                            <tr>
                                                <th className="px-6 py-3 text-xs font-bold text-neutral-500 uppercase tracking-wider">Receipt No</th>
                                                <th className="px-6 py-3 text-xs font-bold text-neutral-500 uppercase tracking-wider">Date</th>
                                                <th className="px-6 py-3 text-xs font-bold text-neutral-500 uppercase tracking-wider">Customer</th>
                                                <th className="px-6 py-3 text-xs font-bold text-neutral-500 uppercase tracking-wider">Allocation</th>
                                                <th className="px-6 py-3 text-xs font-bold text-neutral-500 uppercase tracking-wider">Mode</th>
                                                <th className="px-6 py-3 text-xs font-bold text-neutral-500 uppercase tracking-wider text-right">Amount</th>
                                                <th className="px-6 py-3 text-xs font-bold text-neutral-500 uppercase tracking-wider text-right">Actions</th>
                                            </tr>
                                        </thead>
                                        <tbody className="divide-y divide-neutral-100 dark:divide-neutral-800 bg-white dark:bg-neutral-900">
                                            {filteredPayments.map((payment) => (
                                                <tr
                                                    key={payment.id}
                                                    className="hover:bg-neutral-50 dark:hover:bg-neutral-800/50 transition-colors cursor-pointer group"
                                                    onClick={() => navigate(`/sales/payment-in/${payment.id}`)}
                                                >
                                                    <td className="px-6 py-4 whitespace-nowrap text-sm font-bold text-brand-600 dark:text-brand-400">
                                                        {payment.receiptNo}
                                                    </td>
                                                    <td className="px-6 py-4 whitespace-nowrap text-sm text-neutral-600 dark:text-neutral-400">
                                                        <div className="flex items-center gap-2">
                                                            <Calendar className="w-3 h-3" />
                                                            {new Date(payment.date).toLocaleDateString(undefined, { year: 'numeric', month: 'short', day: 'numeric' })}
                                                        </div>
                                                    </td>
                                                    <td className="px-6 py-4">
                                                        <div className="flex items-center">
                                                            <div className="h-8 w-8 rounded-full bg-brand-100 dark:bg-brand-900/30 flex items-center justify-center text-brand-600 dark:text-brand-400 font-bold text-xs mr-3">
                                                                {payment.customerName.charAt(0)}
                                                            </div>
                                                            <div>
                                                                <div className="text-sm font-bold text-neutral-900 dark:text-neutral-100 font-outfit">{payment.customerName}</div>
                                                                <div className="text-xs text-neutral-500">{payment.customerPhone}</div>
                                                            </div>
                                                        </div>
                                                    </td>
                                                    <td className="px-6 py-4">
                                                        <div className="flex items-center gap-2">
                                                            {payment.allocatedCount && payment.allocatedCount > 0 ? (
                                                                <span className="inline-flex items-center px-2 py-0.5 rounded text-xs font-medium bg-blue-50 text-blue-700 border border-blue-100">
                                                                    {payment.allocatedCount} Inv
                                                                </span>
                                                            ) : (
                                                                <span className="inline-flex items-center px-2 py-0.5 rounded text-xs font-medium bg-amber-50 text-amber-700 border border-amber-200">
                                                                    Advance
                                                                </span>
                                                            )}
                                                            {(payment.excessAmount || 0) > 0 && (
                                                                <span className="inline-flex items-center px-2 py-0.5 rounded text-xs font-medium bg-green-50 text-green-700 border border-green-200">
                                                                    +Credit
                                                                </span>
                                                            )}
                                                        </div>
                                                    </td>
                                                    <td className="px-6 py-4">
                                                        <div className="flex flex-wrap gap-1">
                                                            {payment.modes.map((mode, idx) => (
                                                                <span key={idx} className="px-2 py-0.5 bg-neutral-100 dark:bg-neutral-800 text-neutral-600 dark:text-neutral-300 border border-neutral-200 dark:border-neutral-700 text-[10px] uppercase font-bold rounded">
                                                                    {mode}
                                                                </span>
                                                            ))}
                                                        </div>
                                                    </td>
                                                    <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-bold text-neutral-900 dark:text-neutral-100">
                                                        {formatCurrency(payment.amount)}
                                                    </td>
                                                    <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-medium">
                                                        <div className="flex items-center justify-end gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                                                            <button
                                                                className="p-1.5 hover:bg-neutral-100 dark:hover:bg-neutral-800 rounded text-neutral-500 hover:text-brand-600 transition-colors"
                                                                title="View"
                                                            >
                                                                <Eye className="w-4 h-4" />
                                                            </button>
                                                            <button
                                                                className="p-1.5 hover:bg-neutral-100 dark:hover:bg-neutral-800 rounded text-neutral-500 hover:text-brand-600 transition-colors"
                                                                title="Print"
                                                                onClick={(e) => {
                                                                    e.stopPropagation();
                                                                    window.print();
                                                                }}
                                                            >
                                                                <Printer className="w-4 h-4" />
                                                            </button>
                                                            <button className="p-1.5 hover:bg-neutral-100 dark:hover:bg-neutral-800 rounded text-neutral-500 hover:text-neutral-900 transition-colors" title="More">
                                                                <MoreHorizontal className="w-4 h-4" />
                                                            </button>
                                                        </div>
                                                    </td>
                                                </tr>
                                            ))}
                                        </tbody>
                                    </table>
                                </div>

                                {/* Mobile Card View */}
                                <div className="md:hidden divide-y divide-neutral-100 dark:divide-neutral-800">
                                    {filteredPayments.map((payment) => (
                                        <div
                                            key={payment.id}
                                            onClick={() => navigate(`/sales/payment-in/${payment.id}`)}
                                            className="p-4 active:bg-neutral-50 dark:active:bg-neutral-800 transition-colors"
                                        >
                                            <div className="flex justify-between items-start mb-2">
                                                <div>
                                                    <div className="font-bold text-brand-600 dark:text-brand-400">{payment.receiptNo}</div>
                                                    <div className="text-sm font-bold text-neutral-900 dark:text-neutral-100">{payment.customerName}</div>
                                                </div>
                                                <div className="font-bold text-neutral-900 dark:text-neutral-100">{formatCurrency(payment.amount)}</div>
                                            </div>
                                            <div className="flex justify-between items-center mt-3">
                                                <div className="text-xs text-neutral-500">
                                                    {new Date(payment.date).toLocaleDateString()}
                                                </div>
                                                <div className="flex gap-1">
                                                    {payment.modes.map((mode, idx) => (
                                                        <span key={idx} className="px-2 py-0.5 bg-neutral-100 dark:bg-neutral-800 text-neutral-600 dark:text-neutral-300 border border-neutral-200 dark:border-neutral-700 text-[10px] uppercase font-bold rounded">
                                                            {mode}
                                                        </span>
                                                    ))}
                                                </div>
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            </>
                        )}
                    </div>
                </div>
            </div>
        </Layout>
    );
};

export default PaymentInList;

import { logger } from '@/shared/lib/logger';
import { useEffect, useState } from "react";
import { useNavigate, useParams } from "react-router-dom";
import api from "@/shared/api/api";
import { toast } from "react-toastify";
import Layout from "@/shared/ui/Layout/Layout";
import {
  ArrowLeft,
  Printer,
  Receipt,
  User,
  Phone,
  Mail,
  CreditCard,
  Banknote,
  Smartphone,
  FileText,
  CheckCircle,
  AlertCircle,
  Clock
} from 'lucide-react';



const PaymentReceiptDetail = () => {
  const { id } = useParams();
  const navigate = useNavigate();

  const user = JSON.parse(localStorage.getItem("user") || '{}');
  const token = user?.token;

  const [payment, setPayment] = useState<any>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchPaymentDetail();
  }, [id]);

  const fetchPaymentDetail = async () => {
    try {
      setLoading(true);
      const response = await api.get(`/payment-in/${id}`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      setPayment(response.data);
    } catch (error) {
      logger.error("Error fetching payment:", error);
      toast.error("Failed to fetch payment details");
    } finally {
      setLoading(false);
    }
  };

  const handlePrint = () => {
    window.print();
  };

  if (loading || !payment) {
    return (
      <Layout>
        <div className="flex flex-col items-center justify-center py-20">
          <div className="animate-spin rounded-full h-10 w-10 border-b-2 border-emerald-600 mb-4"></div>
          <p className="text-slate-500 font-medium">Loading receipt...</p>
        </div>
      </Layout>
    );
  }

  return (
    <Layout>
      <div className="max-w-5xl mx-auto animate-fade-in pb-10">
        {/* Header - Hidden on print */}
        <div className="mb-8 print:hidden">
          <button
            onClick={() => navigate("/sales/payment-in-list")}
            className="flex items-center text-slate-600 hover:text-indigo-600 mb-4 transition-colors font-medium gap-2"
          >
            <ArrowLeft className="w-4 h-4" />
            Back to Payment List
          </button>
          <div className="flex justify-between items-start">
            <div>
              <h1 className="text-2xl font-bold text-slate-800 tracking-tight flex items-center gap-2">
                <Receipt className="w-6 h-6 text-emerald-600" />
                Payment Receipt
              </h1>
              <p className="text-sm text-slate-500 mt-1">
                View and print payment receipt
              </p>
            </div>
            <button
              className="flex items-center gap-2 px-4 py-2 bg-emerald-600 text-white rounded-lg hover:bg-emerald-700 transition-colors shadow-sm font-medium"
              onClick={handlePrint}
            >
              <Printer className="w-4 h-4" />
              Print Receipt
            </button>
          </div>
        </div>

        {/* Receipt Container - Optimized for Print */}
        <div className="bg-white border border-slate-200 rounded-2xl shadow-sm overflow-hidden print:shadow-none print:p-0 print:rounded-none print:bg-white print:border-0">
          {/* Receipt Header Section */}
          <div className="px-8 py-6 border-b-2 border-slate-200 print:px-6 print:py-4 print:border-gray-300">
            <div className="flex justify-between items-start gap-4">
              <div className="flex-1">
                <h2 className="text-3xl font-bold text-emerald-600 mb-1 print:text-green-700 tracking-tight">
                  PAYMENT RECEIPT
                </h2>
                <div className="text-base font-mono font-bold text-slate-800 print:text-black">
                  Receipt #: {payment.receiptNumber}
                </div>
              </div>
              <div className="text-right flex-shrink-0">
                <div className="text-xs font-bold text-slate-500 print:text-gray-900 uppercase mb-1 tracking-wider">
                  Receipt Date & Time
                </div>
                <div className="font-bold text-base text-slate-800 print:text-black">
                  {new Date(payment.paymentDate).toLocaleDateString("en-IN", {
                    day: "2-digit",
                    month: "short",
                    year: "numeric",
                  })}
                </div>
                <div className="text-xs text-slate-500 print:text-gray-700">
                  {new Date(payment.paymentDate).toLocaleTimeString("en-IN", {
                    hour: "2-digit",
                    minute: "2-digit",
                  })}
                </div>
              </div>
            </div>
          </div>

          {/* Customer and Payment Summary Section */}
          <div className="grid grid-cols-2 gap-6 px-8 py-6 print:grid-cols-2 print:gap-4 print:px-6 print:py-4">
            {/* Customer Info */}
            <div>
              <h3 className="text-xs font-bold text-slate-500 print:text-gray-900 uppercase mb-3 pb-2 border-b border-slate-200 print:border-gray-300 tracking-wider">
                Received From
              </h3>
              <div className="space-y-2">
                <div className="font-bold text-lg text-slate-800 print:text-black">
                  {payment.customer.name}
                </div>
                <div className="text-sm text-slate-600 print:text-gray-900 flex items-center gap-2">
                  <Phone className="w-4 h-4 text-slate-400 print:hidden" />
                  {payment.customer.phone}
                </div>
                {payment.customer.email && (
                  <div className="text-sm text-slate-600 print:text-gray-900 flex items-center gap-2">
                    <Mail className="w-4 h-4 text-slate-400 print:hidden" />
                    {payment.customer.email}
                  </div>
                )}
              </div>
            </div>

            {/* Payment Summary */}
            <div className="text-right">
              <h3 className="text-xs font-bold text-slate-500 print:text-gray-900 uppercase mb-3 pb-2 border-b border-slate-200 print:border-gray-300 tracking-wider">
                Payment Summary
              </h3>
              <div className="space-y-2">
                <div>
                  <div className="text-xs text-slate-500 print:text-gray-900 mb-1">
                    Amount Received
                  </div>
                  <div className="font-bold text-2xl text-emerald-600 print:text-green-700">
                    ₹{payment.totalAmount.toFixed(2)}
                  </div>
                </div>
                {payment.creditApplied > 0 && (
                  <div className="mt-3 pt-3 border-t border-slate-200 print:border-gray-300">
                    <div className="text-xs text-slate-500 print:text-gray-700 mb-1">
                      + Credit Applied
                    </div>
                    <div className="font-bold text-lg text-orange-600 print:text-orange-700">
                      ₹{payment.creditApplied.toFixed(2)}
                    </div>
                  </div>
                )}
              </div>
            </div>
          </div>

          {/* Payment Methods Section */}
          <div className="px-8 py-6 border-t border-default print:px-6 print:py-4 print:border-gray-300">
            <h3 className="text-xs font-bold text-secondary print:text-gray-700 uppercase mb-4 flex items-center">
              <svg
                className="w-4 h-4 mr-2"
                fill="none"
                stroke="currentColor"
                viewBox="0 0 24 24"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2}
                  d="M17 9V7a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2m2 4h10a2 2 0 002-2v-6a2 2 0 00-2-2H9a2 2 0 00-2 2v6a2 2 0 002 2zm7-5a2 2 0 11-4 0 2 2 0 014 0z"
                />
              </svg>
              Payment Method(s)
            </h3>
            <div className="space-y-2">
              {payment.paymentMethods.map((pm: { method: string; reference?: string; amount: number; chequeNumber?: string; chequeDate?: string; chequeBank?: string; cardType?: string }, idx: number) => (
                <div
                  key={idx}
                  className="flex justify-between items-start py-3 px-4 bg-surface print:bg-white print:border print:border-gray-300 rounded border border-default"
                >
                  <div className="flex items-start flex-1">
                    <div className="w-8 h-8 bg-card print:bg-white rounded-full flex items-center justify-center mr-3 flex-shrink-0 mt-0.5">
                      <svg
                        className="w-4 h-4 text-blue-600 dark:text-blue-400 print:text-blue-700"
                        fill="none"
                        stroke="currentColor"
                        viewBox="0 0 24 24"
                      >
                        {pm.method === "cash" && (
                          <path
                            strokeLinecap="round"
                            strokeLinejoin="round"
                            strokeWidth={2}
                            d="M17 9V7a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2m2 4h10a2 2 0 002-2v-6a2 2 0 00-2-2H9a2 2 0 00-2 2v6a2 2 0 002 2zm7-5a2 2 0 11-4 0 2 2 0 014 0z"
                          />
                        )}
                        {pm.method === "card" && (
                          <path
                            strokeLinecap="round"
                            strokeLinejoin="round"
                            strokeWidth={2}
                            d="M3 10h18M7 15h1m4 0h1m-7 4h12a3 3 0 003-3V8a3 3 0 00-3-3H6a3 3 0 00-3 3v8a3 3 0 003 3z"
                          />
                        )}
                        {pm.method === "upi" && (
                          <path
                            strokeLinecap="round"
                            strokeLinejoin="round"
                            strokeWidth={2}
                            d="M12 18h.01M8 21h8a2 2 0 002-2V5a2 2 0 00-2-2H8a2 2 0 00-2 2v14a2 2 0 002 2z"
                          />
                        )}
                        {pm.method === "cheque" && (
                          <path
                            strokeLinecap="round"
                            strokeLinejoin="round"
                            strokeWidth={2}
                            d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"
                          />
                        )}
                        {!["cash", "card", "upi", "cheque"].includes(
                          pm.method
                        ) && (
                            <path
                              strokeLinecap="round"
                              strokeLinejoin="round"
                              strokeWidth={2}
                              d="M17 9V7a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2m2 4h10a2 2 0 002-2v-6a2 2 0 00-2-2H9a2 2 0 00-2 2v6a2 2 0 002 2zm7-5a2 2 0 11-4 0 2 2 0 014 0z"
                            />
                          )}
                      </svg>
                    </div>
                    <div>
                      <div className="font-bold text-main print:text-black capitalize">
                        {pm.method}
                      </div>
                      {pm.reference && (
                        <div className="text-xs text-secondary print:text-gray-700 mt-0.5">
                          Ref: {pm.reference}
                        </div>
                      )}
                      {pm.chequeNumber && (
                        <div className="text-xs text-secondary print:text-gray-700 mt-1 space-y-0.5">
                          <div>Cheque #{pm.chequeNumber}</div>
                          {pm.chequeDate && (
                            <div>
                              Date:{" "}
                              {new Date(pm.chequeDate).toLocaleDateString(
                                "en-IN"
                              )}
                            </div>
                          )}
                          {pm.chequeBank && <div>Bank: {pm.chequeBank}</div>}
                        </div>
                      )}
                      {pm.cardType && (
                        <div className="text-xs text-secondary print:text-gray-700 mt-0.5">
                          {pm.cardType}
                        </div>
                      )}
                    </div>
                  </div>
                  <div className="font-bold text-blue-600 dark:text-blue-400 print:text-blue-700 text-base ml-4 flex-shrink-0">
                    ₹{pm.amount.toFixed(2)}
                  </div>
                </div>
              ))}
            </div>
          </div>

          {/* Allocated Invoices */}
          {payment.allocatedInvoices &&
            payment.allocatedInvoices.length > 0 && (
              <div className="px-8 py-6 border-t border-default print:px-6 print:py-4 print:border-gray-300">
                <h3 className="text-xs font-bold text-secondary print:text-gray-700 uppercase mb-4">
                  Payment Allocated To
                </h3>
                <div className="overflow-x-auto">
                  <table className="w-full text-sm">
                    <thead>
                      <tr className="border-b-2 border-default print:border-gray-300">
                        <th className="text-left py-2 px-2 font-bold text-main print:text-black">
                          #
                        </th>
                        <th className="text-left py-2 px-2 font-bold text-main print:text-black">
                          Invoice No
                        </th>
                        <th className="text-right py-2 px-2 font-bold text-main print:text-black">
                          Invoice Total
                        </th>
                        <th className="text-right py-2 px-2 font-bold text-main print:text-black">
                          Amount Paid
                        </th>
                      </tr>
                    </thead>
                    <tbody>
                      {payment.allocatedInvoices.map((allocation: { invoice?: { invoiceNo: string; totalAmount: number }; allocatedAmount: number }, index: number) => (
                        <tr
                          key={index}
                          className="border-b border-default print:border-gray-300"
                        >
                          <td className="py-2 px-2 text-main print:text-gray-900">
                            {index + 1}
                          </td>
                          <td className="py-2 px-2 text-main print:text-black font-medium">
                            {allocation.invoice?.invoiceNo || "N/A"}
                          </td>
                          <td className="py-2 px-2 text-right text-main print:text-black">
                            ₹
                            {allocation.invoice?.totalAmount?.toFixed(2) ||
                              "0.00"}
                          </td>
                          <td className="py-2 px-2 text-right font-bold text-green-600 dark:text-green-400 print:text-green-700">
                            ₹{allocation.allocatedAmount.toFixed(2)}
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            )}

          {/* Summary and Status Section */}
          <div className="px-8 py-6 border-t border-default bg-card print:px-6 print:py-4 print:bg-white print:border-gray-300">
            <div className="flex justify-center">
              <div className="w-full md:w-144">
                <div className="space-y-6 bg-surface print:bg-white p-8 rounded-lg shadow-sm border border-default print:border print:border-gray-300 text-xl">
                  <div className="flex justify-between py-3 text-base">
                    <span className="text-main print:text-black">
                      Total Payment Received:
                    </span>
                    <span className="font-bold text-main print:text-black">
                      ₹{payment.totalAmount.toFixed(2)}
                    </span>
                  </div>

                  {/* <div className="flex justify-between py-2 text-sm">
                                        <span className="text-gray-900 dark:text-gray-900 print:text-black">Allocated to Invoices:</span>
                                        <span className="font-bold text-gray-900 dark:text-gray-200 print:text-black">
                                            ₹{(payment.allocatedInvoices?.reduce((sum, inv) => sum + inv.allocatedAmount, 0) || 0).toFixed(2)}
                                        </span>
                                    </div> */}

                  {payment.creditApplied > 0 && (
                    <div className="flex justify-between py-2 text-sm border-b border-default print:border-gray-200">
                      <span className="text-main print:text-black">
                        Customer Credit Applied:
                      </span>
                      <span className="font-bold text-main print:text-black">
                        ₹{payment.creditApplied.toFixed(2)}
                      </span>
                    </div>
                  )}

                  <div className="flex justify-between py-0 text-sm border-t-1 border-default print:border-gray-200 pt-2">
                    <span className="text-main print:text-black">
                      Effective Payment:
                    </span>
                    <span className="font-bold text-main print:text-black">
                      ₹
                      {(payment.totalAmount + payment.creditApplied).toFixed(2)}
                    </span>
                  </div>

                  <div className="flex justify-between -mt-1 text-sm">
                    <span className="text-main print:text-black">
                      Allocated to Invoices:
                    </span>
                    <span className="font-bold text-main print:text-black">
                      ₹
                      {payment.allocatedInvoices
                        .reduce((sum: number, inv: { allocatedAmount: number }) => sum + inv.allocatedAmount, 0)
                        .toFixed(2)}
                    </span>
                  </div>

                  {/* Status Box */}
                  {(() => {
                    const currentDues = payment.customerCurrentDues || 0;
                    const effectivePayment =
                      payment.totalAmount + payment.creditApplied;
                    const duesBeforePayment = currentDues + effectivePayment;

                    if (
                      effectivePayment > duesBeforePayment &&
                      duesBeforePayment > 0
                    ) {
                      const excessAmount = effectivePayment - duesBeforePayment;
                      return (
                        <div className="mt-4 p-3 bg-emerald-50 dark:bg-emerald-900/20 border border-emerald-200 dark:border-emerald-700 print:border-emerald-600 print:bg-white rounded-lg">
                          <div className="flex items-start gap-2">
                            <svg
                              className="w-5 h-5 text-emerald-600 dark:text-emerald-400 print:text-emerald-700 flex-shrink-0 mt-0.5"
                              fill="currentColor"
                              viewBox="0 0 20 20"
                            >
                              <path
                                fillRule="evenodd"
                                d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z"
                              />
                            </svg>
                            <div className="flex-1">
                              <div className="font-semibold text-emerald-900 dark:text-emerald-300 print:text-emerald-900 text-sm mb-1">
                                Excess Amount Credited
                              </div>
                              <p className="text-xs text-emerald-700 dark:text-emerald-400 print:text-emerald-800 leading-relaxed">
                                ₹{excessAmount.toFixed(2)} added to customer
                                credit
                              </p>
                            </div>
                          </div>
                        </div>
                      );
                    }

                    if (
                      Math.abs(effectivePayment - duesBeforePayment) < 0.01 &&
                      duesBeforePayment > 0
                    ) {
                      return (
                        <div className="mt-4 p-3 bg-teal-50 dark:bg-teal-900/20 border border-teal-200 dark:border-teal-700 print:border-teal-600 print:bg-white rounded-lg">
                          <div className="flex items-start gap-2">
                            <svg
                              className="w-5 h-5 text-teal-600 dark:text-teal-400 print:text-teal-700 flex-shrink-0 mt-0.5"
                              fill="currentColor"
                              viewBox="0 0 20 20"
                            >
                              <path
                                fillRule="evenodd"
                                d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z"
                              />
                            </svg>
                            <div className="flex-1">
                              <div className="font-semibold text-teal-900 dark:text-teal-300 print:text-teal-900 text-sm mb-1">
                                Dues Fully Repaid
                              </div>
                              <p className="text-xs text-teal-700 dark:text-teal-400 print:text-teal-800 leading-relaxed">
                                All pending dues have been cleared
                              </p>
                            </div>
                          </div>
                        </div>
                      );
                    }

                    if (
                      effectivePayment < duesBeforePayment &&
                      duesBeforePayment > 0
                    ) {
                      const remainingDues =
                        duesBeforePayment - effectivePayment;
                      return (
                        <div className="mt-4 p-3 bg-amber-50 dark:bg-amber-900/20 border border-amber-200 dark:border-amber-700 print:border-amber-600 print:bg-white rounded-lg">
                          <div className="flex items-start gap-2">
                            <svg
                              className="w-5 h-5 text-amber-600 dark:text-amber-400 print:text-amber-700 flex-shrink-0 mt-0.5"
                              fill="currentColor"
                              viewBox="0 0 20 20"
                            >
                              <path
                                fillRule="evenodd"
                                d="M8.257 3.099c.765-1.36 2.722-1.36 3.486 0l5.58 9.92c.75 1.334-.213 2.98-1.742 2.98H4.42c-1.53 0-2.493-1.646-1.743-2.98l5.58-9.92zM11 13a1 1 0 11-2 0 1 1 0 012 0zm-1-8a1 1 0 00-1 1v3a1 1 0 002 0V6a1 1 0 00-1-1z"
                              />
                            </svg>
                            <div className="flex-1">
                              <div className="font-semibold text-amber-900 dark:text-amber-300 print:text-amber-900 text-sm mb-1">
                                Partial Payment
                              </div>
                              <p className="text-xs text-amber-700 dark:text-amber-400 print:text-amber-800 leading-relaxed">
                                Remaining balance: ₹{remainingDues.toFixed(2)}
                              </p>
                            </div>
                          </div>
                        </div>
                      );
                    }

                    if (duesBeforePayment <= 0) {
                      return (
                        <div className="mt-4 p-3 bg-indigo-50 dark:bg-indigo-900/20 border border-indigo-200 dark:border-indigo-700 print:border-indigo-600 print:bg-white rounded-lg">
                          <div className="flex items-start gap-2">
                            <svg
                              className="w-5 h-5 text-indigo-600 dark:text-indigo-400 print:text-indigo-700 flex-shrink-0 mt-0.5"
                              fill="currentColor"
                              viewBox="0 0 20 20"
                            >
                              <path
                                fillRule="evenodd"
                                d="M6.267 3.455a3.066 3.066 0 001.745-.723 3.066 3.066 0 013.976 0 3.066 3.066 0 001.745.723 3.066 3.066 0 012.812 3.062v6.018a1 1 0 01-.999 1H3.455a1 1 0 01-.999-1V6.517a3.066 3.066 0 012.812-3.062p"
                              />
                            </svg>
                            <div className="flex-1">
                              <div className="font-semibold text-indigo-900 dark:text-indigo-300 print:text-indigo-900 text-sm mb-1">
                                Advance Payment
                              </div>
                              <p className="text-xs text-indigo-700 dark:text-indigo-400 print:text-indigo-800 leading-relaxed">
                                ₹
                                {(
                                  payment.totalAmount + payment.creditApplied
                                ).toFixed(2)}{" "}
                                credited for future invoices
                              </p>
                            </div>
                          </div>
                        </div>
                      );
                    }
                    return null;
                  })()}
                </div>
              </div>
            </div>
          </div>

          {/* Notes Section */}
          {payment.notes && (
            <div className="px-8 py-6 border-t border-default print:px-6 print:py-4 print:border-gray-300">
              <h3 className="text-xs font-bold text-secondary print:text-gray-700 uppercase mb-3 pb-2 border-b border-default print:border-gray-300">
                Notes
              </h3>
              <p className="text-sm text-secondary print:text-gray-800 leading-relaxed">
                {payment.notes}
              </p>
            </div>
          )}

          {/* Footer */}
          <div className="px-8 py-6 border-t border-default print:px-6 print:py-4 print:border-gray-300 text-center">
            <p className="text-sm text-main print:text-gray-900 font-medium">
              Thank you for your payment!
            </p>
            <p className="text-xs text-muted print:text-gray-700 mt-2">
              This is a computer-generated receipt.
            </p>
            {payment.createdAt && (
              <p className="text-xs text-muted print:text-gray-700 mt-2">
                Created on {new Date(payment.createdAt).toLocaleString("en-IN")}
              </p>
            )}
          </div>
        </div>

        {/* Additional Info - Hidden on print */}
        <div className="mt-6 bg-card border border-default rounded-lg p-4 print:hidden">
          <div className="flex items-start gap-3">
            <svg
              className="w-5 h-5 text-secondary mt-0.5 flex-shrink-0"
              fill="none"
              stroke="currentColor"
              viewBox="0 0 24 24"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
                d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"
              />
            </svg>
            <div className="flex-1">
              <h4 className="text-sm font-semibold text-main mb-1">
                Receipt Information
              </h4>
              <p className="text-sm text-secondary">
                Deposited to:{" "}
                {payment.depositAccount === "cash"
                  ? "Cash in Hand"
                  : "Bank Account"}
              </p>
            </div>
          </div>
        </div>
      </div>

      {/* Print Styles */}
      <style>{`
                @media print {
                    * {
                        -webkit-print-color-adjust: exact !important;
                        color-adjust: exact !important;
                        print-color-adjust: exact !important;
                    }
                    
                    body {
                        background: white !important;
                        margin: 0 !important;
                        padding: 0 !important;
                    }
                    
                    nav, aside, .print\\:hidden, button:not(.print\\:block) {
                        display: none !important;
                    }
                    
                    .max-w-5xl {
                        max-width: 100% !important;
                    }
                    
                    .bg-white {
                        background: white !important;
                        box-shadow: none !important;
                    }
                    
                    .border-gray-300 {
                        border-color: #d1d5db !important;
                    }
                    
                    .text-green-600,
                    .text-green-700,
                    .dark\\:text-green-500 {
                        color: #16a34a !important;
                    }
                    
                    .text-gray-800,
                    .text-gray-900,
                    .dark\\:text-gray-200,
                    .dark\\:text-gray-300 {
                        color: #000 !important;
                    }
                    
                    .text-gray-600,
                    .text-gray-700 {
                        color: #374151 !important;
                    }
                    
                    table {
                        width: 100% !important;
                    }
                    
                    th, td {
                        border-color: #d1d5db !important;
                    }
                }
            `}</style>
    </Layout>
  );
};

export default PaymentReceiptDetail;

import { logger } from '@/shared/lib/logger';
import { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import api from "@/shared/api/api";
import { toast } from "react-toastify";
import Layout from "@/shared/ui/Layout/Layout";
import {
  RotateCcw,
  FileText,
  User,
  Phone,
  Mail,
  CreditCard,
  Banknote,
  Building2,
  X,
  Save,
  Trash2,
  ChevronRight,
  AlertCircle,
  CheckCircle
} from 'lucide-react';

const Return = () => {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(false);
  const [showInvoiceModal, setShowInvoiceModal] = useState(false);
  const [invoices, setInvoices] = useState<any[]>([]);
  const [searchInvoice, setSearchInvoice] = useState("");

  // Load draft from localStorage on mount
  const [formData, setFormData] = useState<any>(() => {
    const savedDraft = localStorage.getItem("returnDraft");
    if (savedDraft) {
      try {
        return JSON.parse(savedDraft);
      } catch (error: any) {
        logger.error("Error loading return draft:", error);
      }
    }
    return {
      selectedInvoice: null,
      customer: null,
      items: [],
      refundMethod: "",
      originalPaymentInfo: null, // NEW: Store original payment details
      notes: "",
    };
  });

  // Get token from user object in localStorage
  const user = JSON.parse(localStorage.getItem("user") || '{}');
  const token = user?.token;


  // Debug: Check if token exists
  if (!token) {
    logger.warn("⚠️ Auth token missing. User object:", user);
  }

  // Save draft to localStorage whenever formData changes
  useEffect(() => {
    if (formData.selectedInvoice || formData.items.length > 0) {
      localStorage.setItem("returnDraft", JSON.stringify(formData));
    }
  }, [formData]);

  // Fetch invoices when modal opens
  useEffect(() => {
    if (showInvoiceModal) {
      fetchInvoices();
    }
  }, [showInvoiceModal]);

  const fetchInvoices = async () => {
    if (!token) {
      toast.error("Authentication error: Token missing. Please log in again.");
      logger.error("Token is missing:", { user, token });
      return;
    }
    try {
      const response = await api.get(`/pos/invoices`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      setInvoices(response.data);
      toast.success("Invoices loaded successfully");
    } catch (error: any) {
      logger.error("Error fetching invoices:", error);
      if (error.response?.status === 401) {
        toast.error("Session expired. Please log in again.");
        localStorage.removeItem("user");
      } else {
        toast.error(error.response?.data?.message || "Failed to fetch invoices");
      }
    }
  };

  const handleInvoiceSelect = async (invoice: any) => {
    try {
      // Fetch full invoice details with populated items
      const response = await api.get(
        `/pos/invoice/${invoice._id}`,
        {
          headers: { Authorization: `Bearer ${token}` },
        }
      );
      const fullInvoice = response.data || {};
      if (!fullInvoice.items || !Array.isArray(fullInvoice.items)) {
        throw new Error("Invalid invoice data: items missing");
      }

      // Fetch existing returns for this invoice
      let existingReturns: any[] = [];
      try {
        const returnsResponse = await api.get(`/returns`, {
          headers: { Authorization: `Bearer ${token}` },
        });
        existingReturns = returnsResponse.data.filter(
          (ret: any) => ret.invoice._id === invoice._id
        );
      } catch (error: any) {
        logger.error("Error fetching existing returns:", error);
      }

      // Calculate already returned quantities per product
      const returnedQuantities: any = {};
      existingReturns.forEach((returnRecord) => {
        (returnRecord.items || []).forEach((item: any) => {
          const productId =
            typeof item.product === "object" && item.product?._id
              ? item.product._id
              : item.product;
          if (!productId) return;
          if (!returnedQuantities[productId]) {
            returnedQuantities[productId] = 0;
          }
          returnedQuantities[productId] += Number(item.returnedQty) || 0;
        });
      });

      // Populate items with return fields and remaining quantities
      const returnItems = fullInvoice.items
        .map((item: any) => {
          // Handle both populated and non-populated item references
          const itemData = item.item;
          const itemName =
            typeof itemData === "object" ? itemData.name : "Item";
          const itemId = typeof itemData === "object" ? itemData._id : itemData;

          const alreadyReturned = Number(returnedQuantities[itemId]) || 0;
          const remainingQty = Number(item.quantity || 0) - alreadyReturned;

          return {
            productId: itemId,
            productName: itemName,
            originalQty: item.quantity,
            alreadyReturned: alreadyReturned,
            remainingQty: remainingQty,
            returnedQty: Math.min(Math.max(remainingQty, 0), Number(item.quantity || 0)), // Default to remaining quantity, clamped
            rate: item.price,
            taxPercent: 0,
            condition: "not_damaged",
            reason: "",
          };
        })
        .filter((item: any) => item.remainingQty > 0); // Only show items that can still be returned

      if (returnItems.length === 0) {
        toast.warning("All items from this invoice have already been returned.");
        return;
      }

      // NEW: Capture original payment information
      const originalPaymentInfo = {
        method: fullInvoice.paymentMethod,
        paidVia: fullInvoice.paidViaMethod,
        creditApplied: fullInvoice.creditApplied || 0,
        paidAmount: fullInvoice.paidAmount || 0,
        bankAccount: fullInvoice.bankAccount,
        splitDetails: fullInvoice.splitPaymentDetails || [],
      };

      setFormData({
        selectedInvoice: fullInvoice,
        customer: fullInvoice.customer,
        items: returnItems,
        refundMethod: "", // User must select
        originalPaymentInfo, // Store detected info
        notes: "",
      });

      setShowInvoiceModal(false);
      toast.success("Invoice selected successfully");
    } catch (error: any) {
      logger.error("Error fetching invoice details:", error);
      const msg =
        (error.response?.data?.message || error.message || "Failed to fetch invoice details");
      toast.error(msg);
    }
  };

  const updateItem = (index: number, field: string, value: any) => {
    const newItems = [...formData.items];
    newItems[index][field] = value;
    setFormData({ ...formData, items: newItems });
  };

  const calculateSubtotal = () => {
    return formData.items.reduce((sum: number, item: any) => {
      return sum + item.returnedQty * item.rate;
    }, 0);
  };

  const calculateTax = () => {
    return formData.items.reduce((sum: number, item: any) => {
      const lineSubtotal = item.returnedQty * item.rate;
      return sum + (lineSubtotal * item.taxPercent) / 100;
    }, 0);
  };

  const calculateTotal = () => {
    return calculateSubtotal() + calculateTax();
  };

  const validateForm = () => {
    if (!formData.selectedInvoice) {
      toast.warning("Please select an invoice");
      return false;
    }

    const itemsWithQty = formData.items.filter((item: any) => item.returnedQty > 0);
    if (itemsWithQty.length === 0) {
      toast.warning("Please add at least one item with quantity greater than 0");
      return false;
    }

    for (const item of itemsWithQty) {
      if (item.returnedQty > item.remainingQty) {
        toast.error(
          `Return quantity for ${item.productName
          } cannot exceed remaining quantity (${item.remainingQty
          }). Already returned: ${item.alreadyReturned || 0}`
        );
        return false;
      }

      if (!item.condition) {
        toast.warning(`Please select condition for ${item.productName}`);
        return false;
      }

      if (!item.reason) {
        toast.warning(`Please select reason for ${item.productName}`);
        return false;
      }
    }

    // Validate refund method is selected
    if (!formData.refundMethod) {
      toast.warning("Please select a refund method before completing the return");
      return false;
    }

    // Validate original_payment has detected info
    if (formData.refundMethod === 'original_payment' && !formData.originalPaymentInfo) {
      toast.error("Cannot detect original payment method from invoice. Please select a refund method manually.");
      return false;
    }

    return true;
  };

  const handleSubmit = async () => {
    if (!validateForm()) return;

    setLoading(true);

    try {
      const itemsToReturn = formData.items.filter(
        (item: any) => item.returnedQty > 0
      );

      const returnData = {
        invoiceId: formData.selectedInvoice._id,
        items: itemsToReturn,
        refundMethod: formData.refundMethod,
        discountAmount: 0,
        notes: formData.notes,
      };

      const response = await api.post(`/returns`, returnData, {
        headers: { Authorization: `Bearer ${token}` },
      });

      // Clear draft from localStorage on successful completion
      localStorage.removeItem("returnDraft");

      toast.success("Items returned successfully!");
      setTimeout(() => {
        navigate("/sales/returned-items");
      }, 1500);
    } catch (error: any) {
      logger.error("Error creating return:", error);
      toast.error(error.response?.data?.message || "Failed to create return");
    } finally {
      setLoading(false);
    }
  };

  // Function to clear draft
  const clearDraft = () => {
    if (confirm("Are you sure you want to clear this return draft?")) {
      localStorage.removeItem("returnDraft");
      setFormData({
        selectedInvoice: null,
        customer: null,
        items: [],
        refundMethod: "",
        originalPaymentInfo: null,
        notes: "",
      });
      toast.info("Return draft cleared");
    }
  };

  // Separate reasons based on condition
  const damagedReasons = [
    "Damaged Product",
    "Quality Issue",
    "Expired Product",
    "Defective Item",
    "Other",
  ];

  const notDamagedReasons = [
    "Wrong Item",
    "Customer Changed Mind",
    "Duplicate Order",
    "No Longer Needed",
    "Other",
  ];

  // Get appropriate reasons based on condition
  const getReasonsForCondition = (condition: string) => {
    return condition === "damaged" ? damagedReasons : notDamagedReasons;
  };

  const filteredInvoices = invoices.filter(
    (inv) =>
      inv.invoiceNo.toLowerCase().includes(searchInvoice.toLowerCase()) ||
      (inv.customer?.name || "")
        .toLowerCase()
        .includes(searchInvoice.toLowerCase())
  );

  return (
    <Layout>
      <div className="space-y-6 animate-fade-in pb-10">
        {/* Header Section */}
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div>
            <h1 className="text-2xl font-bold text-slate-800 tracking-tight flex items-center gap-2">
              <RotateCcw className="w-6 h-6 text-indigo-600" />
              Process Return
            </h1>
            <p className="text-sm text-slate-500 mt-1">Create a new customer return and issue credits</p>
          </div>
          <div className="flex gap-3">
            {formData.selectedInvoice && (
              <button
                onClick={clearDraft}
                className="flex items-center gap-2 px-4 py-2 border border-slate-300 text-slate-700 rounded-lg hover:bg-slate-50 transition-all font-medium"
              >
                <Trash2 className="w-4 h-4" /> Clear Draft
              </button>
            )}
            <button
              onClick={handleSubmit}
              disabled={loading}
              className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 shadow-sm transition-all font-medium disabled:opacity-50"
            >
              <Save className="w-4 h-4" /> {loading ? "Processing..." : "Save Return"}
            </button>
          </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          <div className="lg:col-span-2 space-y-6">
            {/* Invoice Selection */}
            <div className="bg-white border border-slate-200 rounded-2xl shadow-sm overflow-hidden">
              <div className="bg-slate-50 px-6 py-3 border-b border-slate-100">
                <h2 className="text-xs font-bold text-slate-500 uppercase tracking-wider flex items-center gap-2">
                  <FileText className="w-4 h-4" /> Select Invoice
                </h2>
              </div>
              <div className="p-6">
                {formData.selectedInvoice ? (
                  <div className="p-4 bg-indigo-50 border border-indigo-200 rounded-xl">
                    <div className="flex items-center justify-between">
                      <div>
                        <p className="font-bold text-indigo-800">
                          {formData.selectedInvoice.invoiceNo}
                        </p>
                        <p className="text-sm text-slate-600 mt-1">
                          {new Date(formData.selectedInvoice.createdAt).toLocaleDateString('en-IN')} • ₹{formData.selectedInvoice.totalAmount?.toFixed(2) || '0.00'}
                        </p>
                      </div>
                      <button
                        onClick={() => setFormData({
                          selectedInvoice: null, customer: null, items: [],
                          refundMethod: "credit", originalPaymentInfo: null, notes: "",
                        })}
                        className="text-red-600 hover:text-red-700 text-sm font-bold"
                      >
                        Change
                      </button>
                    </div>
                  </div>
                ) : (
                  <button
                    onClick={() => setShowInvoiceModal(true)}
                    className="w-full px-4 py-4 border-2 border-dashed border-slate-300 rounded-xl text-slate-500 hover:border-indigo-500 hover:text-indigo-600 transition-colors flex items-center justify-center gap-2"
                  >
                    <FileText className="w-5 h-5" /> Click to select invoice
                  </button>
                )}
              </div>
            </div>

            {/* Customer Info */}
            {formData.customer && (
              <div className="bg-white border border-slate-200 rounded-2xl shadow-sm overflow-hidden">
                <div className="bg-slate-50 px-6 py-3 border-b border-slate-100">
                  <h2 className="text-xs font-bold text-slate-500 uppercase tracking-wider flex items-center gap-2">
                    <User className="w-4 h-4" /> Customer
                  </h2>
                </div>
                <div className="p-6">
                  <div className="flex items-start gap-4">
                    <div className="w-12 h-12 rounded-xl bg-gradient-to-br from-indigo-500 to-violet-600 flex items-center justify-center text-white text-lg font-black shadow-lg">
                      {formData.customer.name?.charAt(0).toUpperCase() || '?'}
                    </div>
                    <div className="flex-1">
                      <p className="text-lg font-bold text-slate-800">{formData.customer.name}</p>
                      <div className="flex flex-wrap gap-4 mt-2 text-sm text-slate-600">
                        {formData.customer.phone && (
                          <span className="flex items-center gap-1.5"><Phone className="w-4 h-4 text-slate-400" /> {formData.customer.phone}</span>
                        )}
                        {formData.customer.email && (
                          <span className="flex items-center gap-1.5"><Mail className="w-4 h-4 text-slate-400" /> {formData.customer.email}</span>
                        )}
                      </div>
                    </div>
                  </div>
                  {/* Credit Balance Display */}
                  {formData.customer?.dues < 0 && (
                    <div className="mt-4 p-3 bg-emerald-50 border border-emerald-200 rounded-xl flex items-center justify-between">
                      <span className="text-sm font-medium text-emerald-700 flex items-center gap-2">
                        <CheckCircle className="w-4 h-4" /> Available Credit
                      </span>
                      <span className="text-lg font-bold text-emerald-600">₹{Math.abs(formData.customer.dues).toFixed(2)}</span>
                    </div>
                  )}
                  {/* Pending Dues Display */}
                  {formData.customer?.dues > 0 && (
                    <div className="mt-4 p-3 bg-red-50 border border-red-200 rounded-xl flex items-center justify-between">
                      <span className="text-sm font-medium text-red-700 flex items-center gap-2">
                        <AlertCircle className="w-4 h-4" /> Pending Dues
                      </span>
                      <span className="text-lg font-bold text-red-600">₹{formData.customer.dues?.toFixed(2) || '0.00'}</span>
                    </div>
                  )}
                </div>
              </div>
            )}

            {/* Return Items */}
            {formData.items.length > 0 && (
              <div className="bg-white border border-slate-200 rounded-2xl shadow-sm overflow-hidden">
                <div className="bg-slate-50 px-6 py-3 border-b border-slate-100">
                  <h2 className="text-xs font-bold text-slate-500 uppercase tracking-wider">Return Items</h2>
                </div>
                <div className="overflow-x-auto">
                  <table className="w-full text-left">
                    <thead className="bg-slate-50 border-b border-slate-200">
                      <tr className="text-xs font-bold text-slate-500 uppercase tracking-wider">
                        <th className="px-4 py-3">Item</th>
                        <th className="px-4 py-3 text-right">Original</th>
                        <th className="px-4 py-3 text-right">Returned</th>
                        <th className="px-4 py-3 text-right">Remaining</th>
                        <th className="px-4 py-3 text-center">Return Qty</th>
                        <th className="px-4 py-3 text-right">Rate</th>
                        <th className="px-4 py-3">Condition</th>
                        <th className="px-4 py-3">Reason</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y">
                      {formData.items.map((item: any, index: number) => (
                        <tr key={index}>
                          <td className="px-4 py-3 text-main">
                            {item.productName}
                          </td>
                          <td className="px-4 py-3 text-secondary">
                            {item.originalQty}
                          </td>
                          <td className="px-4 py-3 text-orange-600 dark:text-orange-400 font-medium">
                            {item.alreadyReturned || 0}
                          </td>
                          <td className="px-4 py-3 text-green-600 dark:text-green-400 font-medium">
                            {item.remainingQty}
                          </td>
                          <td className="px-4 py-3">
                            <input
                              type="number"
                              value={item.returnedQty}
                              onChange={(e) =>
                                updateItem(
                                  index,
                                  "returnedQty",
                                  Math.min(
                                    parseFloat(e.target.value) || 0,
                                    item.remainingQty
                                  )
                                )
                              }
                              className="w-20 px-2 py-1 border border-default rounded bg-card text-main focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500"
                              min="0"
                              max={item.remainingQty}
                            />
                          </td>
                          <td className="px-4 py-3 text-main">
                            ₹{item.rate.toFixed(2)}
                          </td>
                          <td className="px-4 py-3">
                            <select
                              value={item.condition}
                              onChange={(e) => {
                                const newCondition = e.target.value;
                                updateItem(index, "condition", newCondition);
                                // Clear reason when condition changes to prevent invalid combinations
                                updateItem(index, "reason", "");
                              }}
                              className="w-32 px-2 py-1 border border-default rounded bg-card text-main focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500"
                            >
                              <option value="not_damaged">Not Damaged</option>
                              <option value="damaged">Damaged</option>
                            </select>
                          </td>
                          <td className="px-4 py-3">
                            <select
                              value={item.reason}
                              onChange={(e) =>
                                updateItem(index, "reason", e.target.value)
                              }
                              className="w-40 px-2 py-1 border border-default rounded bg-card text-main focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500"
                            >
                              <option value="">Select reason</option>
                              {getReasonsForCondition(item.condition).map(
                                (reason) => (
                                  <option key={reason} value={reason}>
                                    {reason}
                                  </option>
                                )
                              )}
                            </select>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            )}

            {/* Refund Details */}
            {formData.items.length > 0 && (
              <div className="bg-card rounded-xl shadow-sm p-6">
                <h2 className="text-lg font-bold text-main mb-4">
                  Refund Details
                </h2>
                <div className="space-y-4">
                  <div>
                    <label className="block text-sm font-medium text-secondary mb-2">
                      Refund Method <span className="text-red-600">*</span>
                    </label>
                    <div className="grid grid-cols-2 gap-3">
                      {["cash", "original_payment"].map(
                        (method) => (
                          <button
                            key={method}
                            onClick={() =>
                              setFormData({ ...formData, refundMethod: method })
                            }
                            className={`p-3 border-2 rounded-lg transition ${formData.refundMethod === method
                              ? "border-indigo-600 bg-indigo-50 dark:bg-indigo-900/40"
                              : "border-default hover:border-indigo-300"
                              }`}
                          >
                            <div className="text-sm font-medium text-main capitalize">
                              {method.replace("_", " ")}
                            </div>
                          </button>
                        )
                      )}
                    </div>

                    {/* Display Original Payment Info if 'original_payment' selected */}
                    {formData.refundMethod === 'original_payment' && formData.originalPaymentInfo && (
                      <div className="mt-4 p-4 bg-blue-50 dark:bg-blue-900/20 border border-blue-200 dark:border-blue-800/50 rounded-lg">
                        <h4 className="font-medium text-blue-900 dark:text-blue-100 mb-3 flex items-center space-x-2">
                          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                          </svg>
                          <span>Detected Original Payment Method</span>
                        </h4>
                        <div className="space-y-2 text-sm">
                          <div className="flex justify-between items-center">
                            <span className="text-blue-700 dark:text-blue-300">Payment Method:</span>
                            <span className="font-semibold text-blue-900 dark:text-blue-100 capitalize">
                              {formData.originalPaymentInfo.method.replace('_', ' ')}
                            </span>
                          </div>

                          {formData.originalPaymentInfo.method === 'split' && (
                            <div className="mt-2 p-2 bg-amber-50 dark:bg-amber-900/20 border border-amber-200 dark:border-amber-800/50 rounded">
                              <p className="text-xs text-amber-800 dark:text-amber-200">
                                ⚠️ Split payment detected. Refund will be processed as customer credit.
                              </p>
                            </div>
                          )}

                          {formData.originalPaymentInfo.method === 'bank_transfer' && (
                            <div className="mt-2 p-2 bg-green-50 dark:bg-green-900/20 border border-green-200 dark:border-green-800/50 rounded">
                              <p className="text-xs text-green-800 dark:text-green-200">
                                ✓ Bank refund will be processed to the same account used for payment.
                              </p>
                            </div>
                          )}

                          {(formData.originalPaymentInfo.method === 'upi' || formData.originalPaymentInfo.method === 'card') && (
                            <div className="mt-2 p-2 bg-amber-50 dark:bg-amber-900/20 border border-amber-200 dark:border-amber-800/50 rounded">
                              <p className="text-xs text-amber-800 dark:text-amber-200">
                                ℹ️ {formData.originalPaymentInfo.method.toUpperCase()} payments cannot be directly refunded.
                                Refund will be processed as customer credit.
                              </p>
                            </div>
                          )}

                          {formData.originalPaymentInfo.method === 'cash' && (
                            <div className="mt-2 p-2 bg-green-50 dark:bg-green-900/20 border border-green-200 dark:border-green-800/50 rounded">
                              <p className="text-xs text-green-800 dark:text-green-200">
                                ✓ Cash refund will be processed.
                              </p>
                            </div>
                          )}
                        </div>
                      </div>
                    )}

                    {/* Validation message if original_payment selected without info */}
                    {formData.refundMethod === 'original_payment' && !formData.originalPaymentInfo && (
                      <div className="mt-4 p-4 bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800/50 rounded-lg">
                        <p className="text-sm text-red-800 dark:text-red-200">
                          ⚠️ Cannot detect original payment method. Please select an invoice first.
                        </p>
                      </div>
                    )}
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-secondary mb-2">
                      Notes
                    </label>
                    <textarea
                      value={formData.notes}
                      onChange={(e) =>
                        setFormData({ ...formData, notes: e.target.value })
                      }
                      rows={3}
                      className="w-full px-4 py-2 border border-default rounded-lg bg-card text-main focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500"
                      placeholder="Add notes about the return..."
                    />
                  </div>
                </div>
              </div>
            )}
          </div>

          {/* Summary Sidebar */}
          <div className="lg:col-span-1">
            <div className="bg-white border border-indigo-100 rounded-2xl shadow-sm overflow-hidden sticky top-4">
              <div className="bg-indigo-50/50 px-6 py-3 border-b border-indigo-100">
                <h2 className="text-xs font-bold text-indigo-800 uppercase tracking-wider">Return Summary</h2>
              </div>
              <div className="p-6 space-y-4">
                <div className="flex justify-between text-sm">
                  <span className="text-slate-500 font-medium">Subtotal</span>
                  <span className="font-bold text-slate-800">₹{calculateSubtotal().toFixed(2)}</span>
                </div>
                <div className="flex justify-between text-sm">
                  <span className="text-slate-500 font-medium">Tax</span>
                  <span className="font-bold text-slate-800">₹{calculateTax().toFixed(2)}</span>
                </div>
              </div>
              <div className="px-6 py-5 bg-rose-600 text-white">
                <div className="flex justify-between items-center">
                  <span className="text-lg font-bold tracking-tight">Refund Amount</span>
                  <span className="text-2xl font-bold tracking-tight">₹{calculateTotal().toFixed(2)}</span>
                </div>
              </div>
              <div className="p-6 space-y-3">
                <div className="p-3 bg-amber-50 border border-amber-200 rounded-xl text-sm text-amber-800">
                  <strong>Note:</strong> This amount will be credited or refunded via the selected method.
                </div>
                <button
                  onClick={handleSubmit}
                  disabled={loading}
                  className="w-full py-3 bg-indigo-600 text-white rounded-xl hover:bg-indigo-700 font-bold disabled:opacity-50 flex items-center justify-center gap-2 transition-all"
                >
                  <Save className="w-4 h-4" /> {loading ? "Processing..." : "Save Return"}
                </button>
                <button
                  onClick={() => navigate("/sales/returned-items")}
                  className="w-full py-3 border border-slate-300 text-slate-700 rounded-xl hover:bg-slate-50 font-medium transition-all"
                >
                  View Returned Items
                </button>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Invoice Selection Modal */}
      {showInvoiceModal && (
        <div className="fixed inset-0 bg-black/75 backdrop-blur-sm flex items-center justify-center z-50 p-4">
          <div className="bg-card rounded-xl shadow-xl max-w-4xl w-full max-h-[80vh] overflow-hidden">
            <div className="p-6 border-b">
              <div className="flex items-center justify-between mb-4">
                <h3 className="text-xl font-bold text-main">Select Invoice</h3>
                <button
                  onClick={() => setShowInvoiceModal(false)}
                  className="text-muted hover:text-secondary"
                >
                  <svg
                    className="w-6 h-6"
                    fill="none"
                    stroke="currentColor"
                    viewBox="0 0 24 24"
                  >
                    <path
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      strokeWidth={2}
                      d="M6 18L18 6M6 6l12 12"
                    />
                  </svg>
                </button>
              </div>
              <input
                type="text"
                placeholder="Search by invoice number or customer name..."
                value={searchInvoice}
                onChange={(e) => setSearchInvoice(e.target.value)}
                className="w-full px-4 py-2 border border-default rounded-lg bg-card text-main placeholder:text-muted focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500"
              />
            </div>
            <div className="overflow-y-auto max-h-96 p-6">
              {filteredInvoices.length === 0 ? (
                <p className="text-center text-muted py-8">No invoices found</p>
              ) : (
                <div className="space-y-3">
                  {filteredInvoices.map((invoice) => (
                    <div
                      key={invoice._id}
                      onClick={() => handleInvoiceSelect(invoice)}
                      className="p-4 border border-default rounded-lg hover:bg-surface hover:border-indigo-500 cursor-pointer transition"
                    >
                      <div className="flex items-center justify-between">
                        <div>
                          <p className="font-medium text-main">
                            {invoice.invoiceNo}
                          </p>
                          <p className="text-sm text-secondary">
                            {invoice.customer?.name || "Walk-in Customer"}
                          </p>
                          <p className="text-sm text-muted">
                            {new Date(invoice.createdAt).toLocaleDateString(
                              "en-IN"
                            )}
                          </p>
                        </div>
                        <div className="text-right">
                          <p className="font-bold text-main">
                            ₹{invoice.totalAmount.toFixed(2)}
                          </p>
                          <span
                            className={`inline-block px-2 py-1 rounded text-xs font-medium ${invoice.paymentStatus === "paid"
                              ? "bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-400"
                              : invoice.paymentStatus === "partial"
                                ? "bg-yellow-100 text-yellow-800 dark:bg-yellow-900/30 dark:text-yellow-400"
                                : "bg-red-100 text-red-800 dark:bg-red-900/30 dark:text-red-400"
                              }`}
                          >
                            {invoice.paymentStatus}
                          </span>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>
        </div>
      )}
    </Layout>
  );
};

export default Return;

import { logger } from '@/shared/lib/logger';
import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import api from "@/shared/api/api";
import Layout from "@/shared/ui/Layout/Layout";
import {
    RotateCcw,
    Plus,
    Search,
    ChevronRight,
    Trash2,
    Package,
    AlertCircle,
    CheckCircle,
    Clock,
    CreditCard,
    Banknote,
    Building2
} from 'lucide-react';

const ReturnedItems = () => {
    const navigate = useNavigate();
    const [returns, setReturns] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);
    const [searchTerm, setSearchTerm] = useState('');
    const [statusFilter, setStatusFilter] = useState('all');
    const [refundMethodFilter, setRefundMethodFilter] = useState('all');
    const [expandedRows, setExpandedRows] = useState(new Set());
    const [currentPage, setCurrentPage] = useState(1);
    const [deleteConfirm, setDeleteConfirm] = useState<string | null>(null);
    const itemsPerPage = 20;

    const user = JSON.parse(localStorage.getItem('user') || '{}');
    const token = user?.token;


    useEffect(() => {
        fetchReturns();
    }, []);

    useEffect(() => {
        setCurrentPage(1);
    }, [searchTerm, statusFilter, refundMethodFilter]);

    const fetchReturns = async () => {
        try {
            setLoading(true);
            const response = await api.get(`/returns`, {
                headers: { Authorization: `Bearer ${token}` }
            });
            setReturns(response.data || []);
        } catch (error) {
            logger.error('Error fetching returns:', error);
        } finally {
            setLoading(false);
        }
    };

    const handleDelete = async (returnId: string) => {
        try {
            await api.delete(`/returns/${returnId}`, {
                headers: { Authorization: `Bearer ${token}` }
            });
            setDeleteConfirm(null);
            fetchReturns();
        } catch (error) {
            logger.error('Error deleting return:', error);
        }
    };

    const toggleRowExpansion = (returnId: any) => {
        const newExpanded = new Set(expandedRows);
        if (newExpanded.has(returnId)) {
            newExpanded.delete(returnId);
        } else {
            newExpanded.add(returnId);
        }
        setExpandedRows(newExpanded);
    };

    const getStatusConfig = (status: string) => {
        const configs: any = {
            'processed': { color: 'bg-emerald-100 text-emerald-800 border-emerald-200', icon: CheckCircle },
            'pending': { color: 'bg-amber-100 text-amber-800 border-amber-200', icon: Clock },
            'refunded': { color: 'bg-blue-100 text-blue-800 border-blue-200', icon: CreditCard }
        };
        return configs[status] || { color: 'bg-slate-100 text-slate-800 border-slate-200', icon: Package };
    };

    const filteredReturns = returns.filter(ret => {
        const matchesSearch =
            ret.returnId?.toLowerCase().includes(searchTerm.toLowerCase()) ||
            (ret.invoice?.invoiceNo || '').toLowerCase().includes(searchTerm.toLowerCase()) ||
            ret.customerName?.toLowerCase().includes(searchTerm.toLowerCase());
        const matchesStatus = statusFilter === 'all' || ret.status === statusFilter;
        const matchesRefundMethod = refundMethodFilter === 'all' || ret.refundMethod === refundMethodFilter;
        return matchesSearch && matchesStatus && matchesRefundMethod;
    });

    const totalPages = Math.ceil(filteredReturns.length / itemsPerPage);
    const startIndex = (currentPage - 1) * itemsPerPage;
    const endIndex = startIndex + itemsPerPage;
    const paginatedReturns = filteredReturns.slice(startIndex, endIndex);

    // Calculate metrics
    const totalAmount = filteredReturns.reduce((sum, ret) => sum + (ret.totalReturnAmount || 0), 0);
    const fullReturns = filteredReturns.filter(ret => ret.returnType === 'full').length;
    const partialReturns = filteredReturns.filter(ret => ret.returnType === 'partial').length;

    if (loading) {
        return (
            <Layout>
                <div className="flex flex-col items-center justify-center py-20">
                    <div className="animate-spin rounded-full h-10 w-10 border-b-2 border-indigo-600 mb-4"></div>
                    <p className="text-slate-500 font-medium">Loading returns...</p>
                </div>
            </Layout>
        );
    }

    return (
        <Layout>
            <div className="space-y-6 animate-fade-in pb-10">
                {/* Header Section */}
                <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                    <div>
                        <h1 className="text-2xl font-bold text-slate-800 tracking-tight">Returns & Refunds</h1>
                        <p className="text-sm text-slate-500 mt-1">Track and manage customer returns</p>
                    </div>
                    <button
                        onClick={() => navigate('/sales/return')}
                        className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 shadow-sm transition-all font-medium"
                    >
                        <Plus className="w-5 h-5" />
                        <span>New Return</span>
                    </button>
                </div>

                {/* KPI Grid */}
                <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                    <div className="bg-white p-5 rounded-xl shadow-sm border border-slate-100 flex flex-col justify-between hover:shadow-md transition-all group">
                        <div className="flex justify-between items-start">
                            <div>
                                <p className="text-xs font-bold text-slate-400 uppercase tracking-wider">Total Returns</p>
                                <h3 className="text-2xl font-bold text-slate-800 mt-1 group-hover:text-indigo-600 transition-colors">{filteredReturns.length}</h3>
                            </div>
                            <div className="p-2 bg-indigo-50 rounded-lg text-indigo-600 group-hover:bg-indigo-100 transition-colors">
                                <RotateCcw className="w-6 h-6" />
                            </div>
                        </div>
                        <div className="mt-4 h-1 w-full bg-slate-50 rounded-full overflow-hidden">
                            <div className="h-full bg-indigo-500 rounded-full w-full"></div>
                        </div>
                    </div>

                    <div className="bg-white p-5 rounded-xl shadow-sm border border-slate-100 flex flex-col justify-between hover:shadow-md transition-all group">
                        <div className="flex justify-between items-start">
                            <div>
                                <p className="text-xs font-bold text-slate-400 uppercase tracking-wider">Total Amount</p>
                                <h3 className="text-2xl font-bold text-slate-800 mt-1 group-hover:text-rose-600 transition-colors">₹{totalAmount.toFixed(0)}</h3>
                            </div>
                            <div className="p-2 bg-rose-50 rounded-lg text-rose-600 group-hover:bg-rose-100 transition-colors">
                                <Banknote className="w-6 h-6" />
                            </div>
                        </div>
                        <div className="mt-4 text-xs text-rose-600 font-medium bg-rose-50 inline-block px-2 py-1 rounded">
                            Value returned
                        </div>
                    </div>

                    <div className="bg-white p-5 rounded-xl shadow-sm border border-slate-100 flex flex-col justify-between hover:shadow-md transition-all group">
                        <div className="flex justify-between items-start">
                            <div>
                                <p className="text-xs font-bold text-slate-400 uppercase tracking-wider">Full Returns</p>
                                <h3 className="text-2xl font-bold text-slate-800 mt-1 group-hover:text-purple-600 transition-colors">{fullReturns}</h3>
                            </div>
                            <div className="p-2 bg-purple-50 rounded-lg text-purple-600 group-hover:bg-purple-100 transition-colors">
                                <Package className="w-6 h-6" />
                            </div>
                        </div>
                        <div className="mt-4 text-xs text-slate-500">
                            <strong>{filteredReturns.length > 0 ? ((fullReturns / filteredReturns.length) * 100).toFixed(0) : 0}%</strong> of returns
                        </div>
                    </div>

                    <div className="bg-white p-5 rounded-xl shadow-sm border border-slate-100 flex flex-col justify-between hover:shadow-md transition-all group">
                        <div className="flex justify-between items-start">
                            <div>
                                <p className="text-xs font-bold text-slate-400 uppercase tracking-wider">Partial Returns</p>
                                <h3 className="text-2xl font-bold text-slate-800 mt-1 group-hover:text-blue-600 transition-colors">{partialReturns}</h3>
                            </div>
                            <div className="p-2 bg-blue-50 rounded-lg text-blue-600 group-hover:bg-blue-100 transition-colors">
                                <AlertCircle className="w-6 h-6" />
                            </div>
                        </div>
                        <div className="mt-4 text-xs text-slate-500">
                            <strong>{filteredReturns.length > 0 ? ((partialReturns / filteredReturns.length) * 100).toFixed(0) : 0}%</strong> of returns
                        </div>
                    </div>
                </div>

                {/* Filter Island */}
                <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-5">
                    <div className="flex flex-col lg:flex-row gap-4 items-center justify-between">
                        <div className="relative w-full lg:max-w-md group">
                            <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                                <Search className="h-5 w-5 text-slate-400 group-focus-within:text-indigo-500 transition-colors" />
                            </div>
                            <input
                                type="text"
                                placeholder="Search return ID, invoice, customer..."
                                value={searchTerm}
                                onChange={(e) => setSearchTerm(e.target.value)}
                                className="block w-full pl-10 pr-3 py-2.5 border border-slate-300 rounded-lg leading-5 bg-white placeholder-slate-400 focus:outline-none focus:placeholder-slate-300 focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500 sm:text-sm transition-shadow shadow-sm"
                            />
                        </div>
                        <div className="flex flex-wrap items-center gap-3 w-full lg:w-auto">
                            <select
                                value={statusFilter}
                                onChange={(e) => setStatusFilter(e.target.value)}
                                className="px-4 py-2.5 border border-slate-300 bg-white text-slate-700 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 shadow-sm text-sm"
                            >
                                <option value="all">All Status</option>
                                <option value="processed">Processed</option>
                                <option value="pending">Pending</option>
                                <option value="refunded">Refunded</option>
                            </select>
                            <select
                                value={refundMethodFilter}
                                onChange={(e) => setRefundMethodFilter(e.target.value)}
                                className="px-4 py-2.5 border border-slate-300 bg-white text-slate-700 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 shadow-sm text-sm"
                            >
                                <option value="all">All Methods</option>
                                <option value="credit">Credit</option>
                                <option value="cash">Cash</option>
                                <option value="bank">Bank</option>
                                <option value="original_payment">Original Payment</option>
                            </select>
                            {(searchTerm || statusFilter !== 'all' || refundMethodFilter !== 'all') && (
                                <button
                                    onClick={() => { setSearchTerm(''); setStatusFilter('all'); setRefundMethodFilter('all'); }}
                                    className="text-sm text-slate-500 hover:text-indigo-600 font-medium px-2 transition-colors"
                                >
                                    Clear
                                </button>
                            )}
                        </div>
                    </div>
                </div>

                {/* Data Table */}
                <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
                    {filteredReturns.length === 0 ? (
                        <div className="flex flex-col items-center justify-center py-20 px-4 text-center">
                            <div className="bg-slate-100 p-4 rounded-full mb-4">
                                <RotateCcw className="w-8 h-8 text-slate-400" />
                            </div>
                            <h3 className="text-lg font-bold text-slate-800">No returns found</h3>
                            <p className="text-slate-500 mt-1 max-w-sm">No returns match your current filters or get started by creating a new return.</p>
                            <button
                                onClick={() => navigate('/sales/return')}
                                className="mt-6 px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 font-medium shadow-sm"
                            >
                                Create First Return
                            </button>
                        </div>
                    ) : (
                        <>
                            <div className="overflow-x-auto">
                                <table className="w-full text-left border-collapse">
                                    <thead>
                                        <tr className="bg-slate-50/50 border-b border-slate-200">
                                            <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase tracking-wider">Return ID</th>
                                            <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase tracking-wider">Date</th>
                                            <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase tracking-wider">Invoice</th>
                                            <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase tracking-wider">Customer</th>
                                            <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase tracking-wider">Type</th>
                                            <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase tracking-wider text-right">Amount</th>
                                            <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase tracking-wider text-center">Status</th>
                                            <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase tracking-wider text-right">Actions</th>
                                        </tr>
                                    </thead>
                                    <tbody className="divide-y divide-slate-100">
                                        {paginatedReturns.map((returnItem) => {
                                            const statusConfig = getStatusConfig(returnItem.status);
                                            const isExpanded = expandedRows.has(returnItem._id);
                                            return (
                                                <>
                                                    <tr key={returnItem._id} className="hover:bg-slate-50 transition-colors group">
                                                        <td className="px-6 py-4">
                                                            <button
                                                                onClick={() => toggleRowExpansion(returnItem._id)}
                                                                className="flex items-center gap-2 font-bold text-indigo-600 hover:text-indigo-800"
                                                            >
                                                                <ChevronRight className={`w-4 h-4 transition-transform ${isExpanded ? 'rotate-90' : ''}`} />
                                                                {returnItem.returnId}
                                                            </button>
                                                        </td>
                                                        <td className="px-6 py-4 text-sm text-slate-600">
                                                            {new Date(returnItem.returnDate).toLocaleDateString()}
                                                        </td>
                                                        <td className="px-6 py-4">
                                                            <button
                                                                onClick={() => navigate(`/pos/invoice/${returnItem.invoice?._id}`)}
                                                                className="text-sm text-indigo-600 hover:underline"
                                                            >
                                                                {returnItem.invoice?.invoiceNo || 'N/A'}
                                                            </button>
                                                        </td>
                                                        <td className="px-6 py-4 text-sm font-medium text-slate-800">{returnItem.customerName}</td>
                                                        <td className="px-6 py-4">
                                                            <span className={`px-2.5 py-0.5 rounded-full text-xs font-bold uppercase ${returnItem.returnType === 'full' ? 'bg-purple-100 text-purple-800' : 'bg-blue-100 text-blue-800'
                                                                }`}>
                                                                {returnItem.returnType}
                                                            </span>
                                                        </td>
                                                        <td className="px-6 py-4 text-right font-bold text-slate-800">
                                                            ₹{returnItem.totalReturnAmount?.toFixed(2) || '0.00'}
                                                        </td>
                                                        <td className="px-6 py-4 text-center">
                                                            <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-bold uppercase border ${statusConfig.color}`}>
                                                                {returnItem.status}
                                                            </span>
                                                        </td>
                                                        <td className="px-6 py-4 text-right">
                                                            <button
                                                                onClick={() => setDeleteConfirm(returnItem._id)}
                                                                className="p-1.5 text-red-600 hover:bg-red-50 rounded-lg transition-colors opacity-0 group-hover:opacity-100"
                                                                title="Delete"
                                                            >
                                                                <Trash2 className="w-4 h-4" />
                                                            </button>
                                                        </td>
                                                    </tr>
                                                    {isExpanded && (
                                                        <tr>
                                                            <td colSpan={8} className="px-6 py-4 bg-slate-50/50">
                                                                <div className="space-y-4">
                                                                    <h4 className="text-xs font-bold text-slate-500 uppercase tracking-wider">Returned Items</h4>
                                                                    <div className="bg-white rounded-lg border border-slate-200 overflow-hidden">
                                                                        <table className="w-full">
                                                                            <thead className="bg-slate-50 border-b border-slate-200">
                                                                                <tr className="text-xs font-bold text-slate-500 uppercase tracking-wider">
                                                                                    <th className="px-4 py-2 text-left">Product</th>
                                                                                    <th className="px-4 py-2 text-right">Qty</th>
                                                                                    <th className="px-4 py-2 text-right">Rate</th>
                                                                                    <th className="px-4 py-2 text-center">Condition</th>
                                                                                    <th className="px-4 py-2 text-left">Reason</th>
                                                                                    <th className="px-4 py-2 text-right">Total</th>
                                                                                </tr>
                                                                            </thead>
                                                                            <tbody className="divide-y divide-slate-100">
                                                                                {returnItem.items?.map((item: any, idx: number) => (
                                                                                    <tr key={idx}>
                                                                                        <td className="px-4 py-2 text-sm font-medium text-slate-800">{item.productName}</td>
                                                                                        <td className="px-4 py-2 text-sm text-right">{item.returnedQty}</td>
                                                                                        <td className="px-4 py-2 text-sm text-right">₹{item.rate?.toFixed(2)}</td>
                                                                                        <td className="px-4 py-2 text-center">
                                                                                            <span className={`px-2 py-0.5 text-xs rounded-full ${item.condition === 'damaged' ? 'bg-red-100 text-red-800' : 'bg-green-100 text-green-800'
                                                                                                }`}>
                                                                                                {item.condition?.replace('_', ' ')}
                                                                                            </span>
                                                                                        </td>
                                                                                        <td className="px-4 py-2 text-sm text-slate-600">{item.reason || '-'}</td>
                                                                                        <td className="px-4 py-2 text-sm text-right font-bold">₹{item.lineTotal?.toFixed(2)}</td>
                                                                                    </tr>
                                                                                ))}
                                                                            </tbody>
                                                                        </table>
                                                                    </div>
                                                                    {returnItem.notes && (
                                                                        <div className="mt-3 p-3 bg-amber-50 rounded-lg text-sm text-amber-800">
                                                                            <strong>Notes:</strong> {returnItem.notes}
                                                                        </div>
                                                                    )}
                                                                </div>
                                                            </td>
                                                        </tr>
                                                    )}
                                                </>
                                            );
                                        })}
                                    </tbody>
                                </table>
                            </div>

                            {/* Pagination */}
                            {totalPages > 1 && (
                                <div className="px-6 py-4 border-t border-slate-200 bg-slate-50/50 flex items-center justify-between">
                                    <div className="text-sm text-slate-500">
                                        Showing <span className="font-medium text-slate-700">{startIndex + 1}</span> to <span className="font-medium text-slate-700">{Math.min(endIndex, filteredReturns.length)}</span> of <span className="font-medium text-slate-700">{filteredReturns.length}</span>
                                    </div>
                                    <div className="flex items-center gap-2">
                                        <button
                                            onClick={() => setCurrentPage((prev) => Math.max(1, prev - 1))}
                                            disabled={currentPage === 1}
                                            className="px-3 py-1 bg-white border border-slate-300 rounded-lg text-sm font-medium text-slate-600 hover:bg-slate-50 disabled:opacity-50 disabled:cursor-not-allowed transition-colors shadow-sm"
                                        >
                                            Previous
                                        </button>
                                        <button
                                            onClick={() => setCurrentPage((prev) => Math.min(totalPages, prev + 1))}
                                            disabled={currentPage === totalPages}
                                            className="px-3 py-1 bg-white border border-slate-300 rounded-lg text-sm font-medium text-slate-600 hover:bg-slate-50 disabled:opacity-50 disabled:cursor-not-allowed transition-colors shadow-sm"
                                        >
                                            Next
                                        </button>
                                    </div>
                                </div>
                            )}
                        </>
                    )}
                </div>
            </div>

            {/* Delete Confirmation Modal */}
            {deleteConfirm && (
                <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-50 flex items-center justify-center p-4 animate-fade-in">
                    <div className="bg-white rounded-xl shadow-2xl max-w-sm w-full p-6 border border-slate-100 animate-scale-in">
                        <div className="w-12 h-12 bg-red-100 rounded-full flex items-center justify-center mb-4 mx-auto">
                            <Trash2 className="w-6 h-6 text-red-600" />
                        </div>
                        <h3 className="text-lg font-bold text-slate-800 text-center mb-2">Delete Return?</h3>
                        <p className="text-sm text-slate-500 text-center mb-6">
                            This will reverse all inventory and customer ledger changes. This action cannot be undone.
                        </p>
                        <div className="flex gap-3">
                            <button
                                onClick={() => setDeleteConfirm(null)}
                                className="flex-1 px-4 py-2 border border-slate-300 rounded-lg text-slate-700 font-medium hover:bg-slate-50 transition-colors"
                            >
                                Cancel
                            </button>
                            <button
                                onClick={() => deleteConfirm && handleDelete(deleteConfirm)}
                                className="flex-1 px-4 py-2 bg-red-600 text-white rounded-lg font-bold hover:bg-red-700 shadow-sm transition-colors"
                            >
                                Delete
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </Layout>
    );
};

export default ReturnedItems;

