import { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { useDispatch, useSelector } from "react-redux";
import {
  getAllSalesInvoices,
  getSalesInvoiceSummary,
  deleteSalesInvoice,
  reset,
} from "@/entities/sales/model/salesInvoiceSlice";
import Layout from "@/shared/ui/Layout/Layout";
import PageHeader from "@/shared/ui/Layout/PageHeader";
import MetricCard from "@/shared/ui/Feedback/MetricCard";
import FormInput from "@/shared/ui/Form/Input";
import CustomerSelectionModal from "@/shared/ui/Modals/CustomerSelectionModal";
import { AppDispatch, RootState } from "@/app/store/store";
import { Customer, Invoice } from '@repo/shared';
import {
  FileText,
  Plus,
  Search,
  Filter,
  Trash2,
  Eye,
  MoreVertical,
  CheckCircle,
  Clock,
  AlertCircle,
  XCircle,
  DollarSign,
  TrendingUp,
  AlertTriangle
} from "lucide-react";

const SalesInvoice = () => {
  const navigate = useNavigate();
  const dispatch = useDispatch<AppDispatch>();
  const {
    invoices = [],
    summary = null,
    isLoading,
    isError,
    message,
  } = useSelector((state: RootState) => state.salesInvoice);



  const [searchTerm, setSearchTerm] = useState("");
  const [statusFilter, setStatusFilter] = useState("all");
  const [deleteConfirm, setDeleteConfirm] = useState<string | null>(null);
  const [showCustomerModal, setShowCustomerModal] = useState(false);
  const [selectedCustomer, setSelectedCustomer] = useState<any>(null);
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 10;

  useEffect(() => {
    dispatch(getAllSalesInvoices());
    dispatch(getSalesInvoiceSummary());
    return () => {
      dispatch(reset());
    };
  }, [dispatch]);

  useEffect(() => {
    setCurrentPage(1);
  }, [searchTerm, statusFilter, selectedCustomer]);

  const handleDelete = async (id: string) => {
    await dispatch(deleteSalesInvoice(id));
    setDeleteConfirm(null);
    dispatch(getAllSalesInvoices());
  };

  const isCustomer = (cust: any): cust is Customer => {
    return cust && typeof cust === 'object' && 'name' in cust;
  };

  const filteredInvoices = Array.isArray(invoices)
    ? (invoices as Invoice[]).filter((invoice) => {
      const customer = invoice.customer;
      const customerName = isCustomer(customer) ? customer.name : '';
      const matchesSearch =
        invoice.invoiceNo.toLowerCase().includes(searchTerm.toLowerCase()) ||
        customerName.toLowerCase().includes(searchTerm.toLowerCase());
      const matchesStatus =
        statusFilter === "all" || invoice.paymentStatus === statusFilter;
      const matchesCustomer =
        !selectedCustomer || (isCustomer(customer) && customer._id === selectedCustomer._id);
      return matchesSearch && matchesStatus && matchesCustomer;
    })
    : [];

  // Pagination calculations
  const totalPages = Math.ceil(filteredInvoices.length / itemsPerPage);
  const startIndex = (currentPage - 1) * itemsPerPage;
  const endIndex = startIndex + itemsPerPage;
  const paginatedInvoices = filteredInvoices.slice(startIndex, endIndex);

  const getStatusColor = (status: string) => {
    switch (status) {
      case "paid":
        return "bg-emerald-100 text-emerald-800 dark:bg-emerald-900/30 dark:text-emerald-400 border-emerald-200 dark:border-emerald-800";
      case "partial":
        return "bg-amber-100 text-amber-800 dark:bg-amber-900/30 dark:text-amber-400 border-amber-200 dark:border-amber-800";
      case "unpaid":
        return "bg-rose-100 text-rose-800 dark:bg-rose-900/30 dark:text-rose-400 border-rose-200 dark:border-rose-800";
      default:
        return "bg-neutral-100 text-neutral-800 dark:bg-neutral-800 dark:text-neutral-400 border-neutral-200 dark:border-neutral-700";
    }
  };

  // Get metrics from backend summary (source of truth)
  const totalInvoices = summary?.totalInvoices || 0;
  const totalPaid = summary?.totalPaid || 0;
  const totalDue = summary?.outstandingDues || 0;

  return (
    <Layout>
      <div className="max-w-7xl mx-auto animate-fade-in pb-12 bg-app min-h-screen">
        <PageHeader
          title="Sales Invoices"
          description="Manage and track your customer invoicing"
          actions={
            <button
              onClick={() => navigate('/sales/new')}
              className="flex items-center gap-2 px-6 py-2.5 bg-primary text-white rounded-xl hover:bg-primary-hover shadow-lg shadow-primary/20 transition-all font-black uppercase tracking-widest text-xs btn-interactive"
            >
              <Plus className="w-4 h-4" />
              <span>Create Invoice</span>
            </button>
          }
        />

        {/* Error Feedback */}
        {isError && (
          <div className="mb-6 p-4 bg-rose-50 dark:bg-rose-900/10 border border-rose-200 dark:border-rose-900/20 rounded-xl flex items-center gap-3 animate-slide-down">
            <AlertTriangle className="w-5 h-5 text-rose-600" />
            <p className="text-rose-700 dark:text-rose-400 text-sm font-bold italic">{message}</p>
          </div>
        )}

        {/* KPI Grid */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
          <MetricCard
            title="Total Invoices"
            value={totalInvoices}
            icon={FileText}
            color="primary"
            variant="default"
          />
          <MetricCard
            title="Amount Collected"
            value={`₹${totalPaid.toLocaleString()}`}
            icon={CheckCircle}
            color="emerald"
            variant="default"
            progress={totalInvoices > 0 ? (totalPaid / (totalPaid + totalDue)) * 100 : 0}
          />
          <MetricCard
            title="Outstanding Dues"
            value={`₹${totalDue.toLocaleString()}`}
            icon={AlertCircle}
            color="rose"
            variant="default"
            subtext="Action Required"
            trend="down"
          />
        </div>

        {/* Advanced Filters */}
        <div className="bg-white dark:bg-neutral-800 p-4 rounded-xl border border-neutral-200 dark:border-neutral-700 flex flex-col gap-4 mb-8">
          <div className="flex flex-wrap gap-4 items-end">
            {/* Search */}
            <div className="flex-1 min-w-[200px]">
              <label className="text-xs font-bold text-neutral-500 uppercase mb-1 block">Search</label>
              <div className="relative">
                <Search className="w-4 h-4 absolute left-3 top-2.5 text-neutral-400" />
                <input
                  type="text"
                  placeholder="Search invoice number, customer..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  className="w-full pl-9 pr-4 py-2 bg-neutral-100 dark:bg-neutral-900 border border-neutral-200 dark:border-neutral-700 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-primary/50"
                />
              </div>
            </div>

            {/* Status Filter */}
            <div className="w-48">
              <label className="text-xs font-bold text-neutral-500 uppercase mb-1 block">Status</label>
              <select
                value={statusFilter}
                onChange={(e) => setStatusFilter(e.target.value)}
                className="w-full px-3 py-2 bg-neutral-100 dark:bg-neutral-900 border border-neutral-200 dark:border-neutral-700 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-primary/50"
              >
                <option value="all">All Status</option>
                <option value="paid">Paid</option>
                <option value="partial">Partial</option>
                <option value="unpaid">Unpaid</option>
              </select>
            </div>

            {/* Customer Filter */}
            <div className="w-auto">
              <label className="text-xs font-bold text-neutral-500 uppercase mb-1 block">Customer</label>
              {selectedCustomer ? (
                <div className="flex items-center gap-2 bg-primary/10 border border-primary/20 text-primary px-3 py-2 rounded-lg text-sm font-medium animate-fade-in h-[38px]">
                  <span className="truncate max-w-[150px]">{selectedCustomer.name}</span>
                  <button onClick={() => setSelectedCustomer(null)} className="hover:text-primary-hover transition-colors">
                    <XCircle className="w-4 h-4" />
                  </button>
                </div>
              ) : (
                <button
                  onClick={() => setShowCustomerModal(true)}
                  className="px-4 py-2 bg-neutral-100 dark:bg-neutral-900 border border-neutral-200 dark:border-neutral-700 text-neutral-600 dark:text-neutral-300 rounded-lg hover:bg-neutral-200 dark:hover:bg-neutral-800 transition-all text-sm font-medium flex items-center gap-2 h-[38px]"
                >
                  <Filter className="w-4 h-4" />
                  Filter Customer
                </button>
              )}
            </div>
          </div>
        </div>

        {/* Data Table */}
        <div className="bg-white dark:bg-neutral-800 rounded-xl border border-neutral-200 dark:border-neutral-700 overflow-hidden flex flex-col shadow-sm">
          {isLoading ? (
            <div className="flex flex-col items-center justify-center py-32">
              <div className="animate-spin rounded-full h-10 w-10 border-b-2 border-primary mb-4"></div>
              <p className="text-neutral-500 text-sm font-medium">Loading invoices...</p>
            </div>
          ) : filteredInvoices.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-32 px-4 text-center">
              <div className="bg-neutral-100 dark:bg-neutral-800 p-4 rounded-full mb-4">
                <Search className="w-8 h-8 text-neutral-400" />
              </div>
              <h3 className="text-lg font-bold text-neutral-900 dark:text-neutral-100">No Invoices Found</h3>
              <p className="text-neutral-500 mt-1 max-w-sm text-sm">No sales invoices match your current search or filter criteria.</p>
              <button
                onClick={() => { setSearchTerm(''); setStatusFilter('all'); setSelectedCustomer(null); }}
                className="mt-6 px-4 py-2 bg-white dark:bg-neutral-800 border border-neutral-200 dark:border-neutral-700 text-neutral-700 dark:text-neutral-300 text-sm font-medium rounded-lg hover:bg-neutral-50 dark:hover:bg-neutral-700 transition-all shadow-sm"
              >
                Clear Filters
              </button>
            </div>
          ) : (
            <>
              {/* Desktop Table */}
              <div className="hidden md:block overflow-x-auto">
                <table className="w-full text-left text-sm">
                  <thead className="bg-neutral-50 dark:bg-neutral-900 border-b border-neutral-200 dark:border-neutral-700">
                    <tr>
                      <th className="px-6 py-4 text-xs font-semibold text-neutral-500 uppercase tracking-wider">Invoice #</th>
                      <th className="px-6 py-4 text-xs font-semibold text-neutral-500 uppercase tracking-wider">Date</th>
                      <th className="px-6 py-4 text-xs font-semibold text-neutral-500 uppercase tracking-wider">Customer</th>
                      <th className="px-6 py-4 text-xs font-semibold text-neutral-500 uppercase tracking-wider text-right">Amount</th>
                      <th className="px-6 py-4 text-xs font-semibold text-neutral-500 uppercase tracking-wider text-right">Paid</th>
                      <th className="px-6 py-4 text-xs font-semibold text-neutral-500 uppercase tracking-wider text-center">Status</th>
                      <th className="px-6 py-4 text-xs font-semibold text-neutral-500 uppercase tracking-wider text-right">Actions</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-neutral-200 dark:divide-neutral-700">
                    {paginatedInvoices.map((invoice) => (
                      <tr key={invoice._id} className="hover:bg-neutral-50 dark:hover:bg-neutral-700/50 transition-colors">
                        <td className="px-6 py-4 font-mono text-primary font-bold cursor-pointer hover:underline" onClick={() => navigate(`/sales/invoice/${invoice._id}`)}>
                          {invoice.invoiceNo}
                        </td>
                        <td className="px-6 py-4 text-neutral-600 dark:text-neutral-400">
                          <div>{new Date(invoice.createdAt).toLocaleDateString("en-IN")}</div>
                          <div className="text-xs text-neutral-400 mt-0.5">{new Date(invoice.createdAt).toLocaleTimeString()}</div>
                        </td>
                        <td className="px-6 py-4">
                          <div className="font-medium text-neutral-900 dark:text-neutral-100">
                            {isCustomer(invoice.customer) ? invoice.customer.name : "Walk-in Customer"}
                          </div>
                          {(isCustomer(invoice.customer) && invoice.customer.phone) && (
                            <div className="text-xs text-neutral-500 mt-0.5">{invoice.customer.phone}</div>
                          )}
                        </td>
                        <td className="px-6 py-4 text-right font-medium text-neutral-900 dark:text-neutral-100">
                          ₹{invoice.totalAmount.toLocaleString()}
                        </td>
                        <td className="px-6 py-4 text-right font-medium text-emerald-600">
                          ₹{invoice.paidAmount.toLocaleString()}
                        </td>
                        <td className="px-6 py-4 text-center">
                          <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium border
                                ${getStatusColor(invoice.paymentStatus)}`}>
                            {invoice.paymentStatus}
                          </span>
                        </td>
                        <td className="px-6 py-4 text-right">
                          <div className="flex justify-end gap-2">
                            <button
                              onClick={() => navigate(`/sales/invoice/${invoice._id}`)}
                              className="p-2 text-neutral-500 hover:text-primary hover:bg-neutral-100 dark:hover:bg-neutral-700 rounded-lg transition-all"
                              title="View Invoice"
                            >
                              <Eye className="w-4 h-4" />
                            </button>
                            <button
                              onClick={() => setDeleteConfirm(invoice._id || null)}
                              className="p-2 text-neutral-500 hover:text-rose-600 hover:bg-neutral-100 dark:hover:bg-neutral-700 rounded-lg transition-all"
                              title="Delete Invoice"
                            >
                              <Trash2 className="w-4 h-4" />
                            </button>
                          </div>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>

              {/* Mobile Card Stack */}
              <div className="md:hidden divide-y divide-neutral-200 dark:divide-neutral-700">
                {paginatedInvoices.map((invoice) => (
                  <div key={invoice._id} className="p-4 active:bg-neutral-50 dark:active:bg-neutral-800 transition-all" onClick={() => navigate(`/sales/invoice/${invoice._id}`)}>
                    <div className="flex justify-between items-start mb-2">
                      <div>
                        <div className="font-bold text-neutral-900 dark:text-neutral-100">{invoice.invoiceNo}</div>
                        <div className="text-sm text-neutral-500 mt-0.5">
                          {isCustomer(invoice.customer) ? invoice.customer.name : "Walk-in Customer"}
                        </div>
                      </div>
                      <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium border
                                ${getStatusColor(invoice.paymentStatus)}`}>
                        {invoice.paymentStatus}
                      </span>
                    </div>
                    <div className="flex justify-between items-center mt-3 text-xs text-neutral-500">
                      <span>{new Date(invoice.createdAt).toLocaleDateString()}</span>
                      <div className="text-sm font-bold text-neutral-900 dark:text-neutral-100">
                        ₹{invoice.totalAmount.toLocaleString()}
                      </div>
                    </div>
                  </div>
                ))}
              </div>

              {/* Pagination */}
              {totalPages > 1 && (
                <div className="px-6 py-4 border-t border-neutral-200 dark:border-neutral-700 flex items-center justify-between bg-neutral-50 dark:bg-neutral-900">
                  <div className="text-xs text-neutral-500">
                    Showing <span className="font-medium">{startIndex + 1}</span> to <span className="font-medium">{Math.min(endIndex, filteredInvoices.length)}</span> of <span className="font-medium">{filteredInvoices.length}</span> results
                  </div>
                  <div className="flex items-center gap-2">
                    <button
                      onClick={() => setCurrentPage((prev) => Math.max(1, prev - 1))}
                      disabled={currentPage === 1}
                      className="px-3 py-1.5 border border-neutral-300 dark:border-neutral-600 rounded-lg text-xs font-medium text-neutral-600 dark:text-neutral-300 hover:bg-white dark:hover:bg-neutral-800 disabled:opacity-50 disabled:cursor-not-allowed transition-all"
                    >
                      Previous
                    </button>
                    <div className="flex gap-1">
                      {Array.from({ length: totalPages }, (_, i) => i + 1).map((page) => {
                        if (page === 1 || page === totalPages || (page >= currentPage - 1 && page <= currentPage + 1)) {
                          return (
                            <button
                              key={page}
                              onClick={() => setCurrentPage(page)}
                              className={`w-8 h-8 flex items-center justify-center rounded-lg text-xs font-medium transition-all ${currentPage === page
                                ? "bg-primary text-white"
                                : "text-neutral-600 hover:bg-neutral-100 dark:hover:bg-neutral-800"
                                }`}
                            >
                              {page}
                            </button>
                          );
                        } else if (page === currentPage - 2 || page === currentPage + 2) {
                          return <span key={page} className="px-1 text-neutral-400">...</span>;
                        }
                        return null;
                      })}
                    </div>
                    <button
                      onClick={() => setCurrentPage((prev) => Math.min(totalPages, prev + 1))}
                      disabled={currentPage === totalPages}
                      className="px-3 py-1.5 border border-neutral-300 dark:border-neutral-600 rounded-lg text-xs font-medium text-neutral-600 dark:text-neutral-300 hover:bg-white dark:hover:bg-neutral-800 disabled:opacity-50 disabled:cursor-not-allowed transition-all"
                    >
                      Next
                    </button>
                  </div>
                </div>
              )}
            </>
          )}
        </div>

        {/* Delete Modal */}
        {deleteConfirm && (
          <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-[100] flex items-center justify-center p-4 animate-fade-in duration-300">
            <div className="bg-white dark:bg-neutral-800 rounded-2xl shadow-2xl max-w-sm w-full p-6 border border-neutral-200 dark:border-neutral-700 animate-scale-in">
              <div className="w-12 h-12 bg-rose-100 dark:bg-rose-900/30 rounded-full flex items-center justify-center mb-4 mx-auto">
                <AlertTriangle className="w-6 h-6 text-rose-600 dark:text-rose-400" />
              </div>
              <h3 className="text-lg font-bold text-neutral-900 dark:text-neutral-100 text-center mb-2">Delete Invoice?</h3>
              <p className="text-sm text-neutral-500 text-center mb-6">
                Are you sure you want to delete this invoice? This action cannot be undone.
              </p>
              <div className="flex gap-3">
                <button
                  onClick={() => setDeleteConfirm(null)}
                  className="flex-1 px-4 py-2 bg-white dark:bg-neutral-800 border border-neutral-200 dark:border-neutral-700 rounded-lg text-neutral-700 dark:text-neutral-300 font-medium hover:bg-neutral-50 dark:hover:bg-neutral-700 transition-all"
                >
                  Cancel
                </button>
                <button
                  onClick={() => handleDelete(deleteConfirm)}
                  className="flex-1 px-4 py-2 bg-rose-600 text-white rounded-lg font-medium hover:bg-rose-700 transition-all shadow-md shadow-rose-600/20"
                >
                  Delete
                </button>
              </div>
            </div>
          </div>
        )}
      </div>

      <CustomerSelectionModal
        isOpen={showCustomerModal}
        onClose={() => setShowCustomerModal(false)}
        onSelect={(customer: any) => {
          setSelectedCustomer(customer);
          setShowCustomerModal(false);
        }}
      />
    </Layout>
  );
};

export default SalesInvoice;

import { useEffect, useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { useNavigate, useParams } from 'react-router-dom';
import { getSalesInvoiceById, reset, clearSalesInvoice, markSalesInvoiceAsPaid } from "@/entities/sales/model/salesInvoiceSlice";
import Layout from "@/shared/ui/Layout/Layout";
import PaymentModal from "@/shared/ui/Modals/PaymentModal";
import { AppDispatch, RootState } from "@/app/store/store";
import { Customer, PopulatedInvoice } from '@repo/shared';
import {
    FileText,
    CheckCircle,
    Clock,
    AlertCircle,
    ArrowLeft,
    Printer,
    CreditCard,
    User,
    Phone,
    Mail,
    MapPin,
    Receipt,
    BadgeCheck
} from 'lucide-react';

const SalesInvoiceDetail = () => {
    const { id } = useParams();
    const navigate = useNavigate();
    const dispatch = useDispatch<AppDispatch>();
    const { invoice, isLoading, isError, message } = useSelector((state: RootState) => state.salesInvoice);
    const [showPaymentModal, setShowPaymentModal] = useState(false);

    useEffect(() => {
        if (id) {
            dispatch(getSalesInvoiceById(id));
        }
        return () => {
            dispatch(reset());
        };
    }, [dispatch, id]);

    const handlePrint = () => {
        window.print();
    };

    const handlePayment = async (paymentData: any) => {
        if (!invoice) return;
        const result = await dispatch(markSalesInvoiceAsPaid({
            id: (invoice._id || invoice.id) as string,
            amount: paymentData.paidAmount,
            bankAccount: paymentData.bankAccount,
            paymentMethod: paymentData.paymentMethod
        }));

        if (result.meta.requestStatus === 'fulfilled') {
            setShowPaymentModal(false);
            if (id) dispatch(getSalesInvoiceById(id));
        }
    };

    const getStatusConfig = (status: string) => {
        const configs: Record<string, any> = {
            'paid': { color: 'from-emerald-500 to-emerald-600', icon: CheckCircle, text: 'Paid in Full', badge: 'bg-emerald-100 text-emerald-800' },
            'partial': { color: 'from-amber-500 to-amber-600', icon: Clock, text: 'Partially Paid', badge: 'bg-amber-100 text-amber-800' },
            'unpaid': { color: 'from-red-500 to-red-600', icon: AlertCircle, text: 'Payment Due', badge: 'bg-red-100 text-red-800' }
        };
        return configs[status] || configs['unpaid'];
    };

    const isCustomer = (cust: any): cust is Customer => {
        return cust && typeof cust === 'object' && 'name' in cust;
    };

    if (isLoading || !invoice) {
        return (
            <Layout>
                <div className="flex flex-col items-center justify-center py-20">
                    <div className="animate-spin rounded-full h-10 w-10 border-b-2 border-indigo-600 mb-4"></div>
                    <p className="text-slate-500 font-medium">Loading invoice...</p>
                </div>
            </Layout>
        );
    }

    if (isError) {
        return (
            <Layout>
                <div className="max-w-4xl mx-auto">
                    <div className="p-4 bg-red-50 border border-red-200 rounded-lg flex items-center gap-3">
                        <AlertCircle className="w-5 h-5 text-red-500" />
                        <p className="text-red-700">{message}</p>
                    </div>
                    <button
                        onClick={() => navigate('/sales/invoice')}
                        className="mt-4 text-indigo-600 hover:text-indigo-700 font-medium flex items-center gap-2"
                    >
                        <ArrowLeft className="w-4 h-4" /> Back to Sales Invoices
                    </button>
                </div>
            </Layout>
        );
    }

    const populatedInvoice = invoice as unknown as PopulatedInvoice;
    const statusConfig = getStatusConfig(invoice.paymentStatus);
    const StatusIcon = statusConfig.icon;
    const balanceDue = (invoice.totalAmount || 0) - (invoice.paidAmount || 0);

    return (
        <Layout>
            <div className="space-y-6 animate-fade-in pb-10">
                {/* Immersive Status Banner */}
                <div className={`bg-gradient-to-r ${statusConfig.color} rounded-[2rem] p-8 text-white shadow-xl relative overflow-hidden print:hidden`}>
                    <div className="absolute top-0 right-0 p-8 opacity-10 pointer-events-none">
                        <Receipt className="w-48 h-48" />
                    </div>
                    <div className="relative z-10">
                        <button
                            onClick={() => navigate('/sales')}
                            className="flex items-center gap-2 text-white/80 hover:text-white text-sm font-medium mb-6 transition-colors"
                        >
                            <ArrowLeft className="w-4 h-4" /> Back to Invoices
                        </button>
                        <div className="flex flex-col lg:flex-row lg:items-center lg:justify-between gap-6">
                            <div>
                                <div className="flex items-center gap-3 mb-2">
                                    <StatusIcon className="w-6 h-6" />
                                    <span className="text-white/80 text-sm font-bold uppercase tracking-widest">{statusConfig.text}</span>
                                </div>
                                <h1 className="text-4xl font-black tracking-tight mb-2">{invoice.invoiceNo}</h1>
                                <p className="text-white/80 font-medium">
                                    {populatedInvoice.customer?.name || 'Walk-in Customer'} • {new Date(invoice.createdAt).toLocaleDateString('en-IN', { day: '2-digit', month: 'short', year: 'numeric' })}
                                </p>
                                {balanceDue > 0 && (
                                    <div className="mt-3 inline-flex items-center gap-2 px-3 py-1.5 bg-white/20 rounded-xl text-sm font-bold">
                                        <AlertCircle className="w-4 h-4" /> ₹{balanceDue.toFixed(2)} Balance Due
                                    </div>
                                )}
                            </div>
                            <div className="flex flex-wrap gap-3">
                                <button
                                    onClick={handlePrint}
                                    className="px-4 py-2.5 bg-white/10 backdrop-blur-md border border-white/20 text-white rounded-xl text-sm font-bold hover:bg-white/20 transition-all flex items-center gap-2"
                                >
                                    <Printer className="w-4 h-4" /> Print
                                </button>
                                {invoice.paymentStatus !== 'paid' && (
                                    <button
                                        onClick={() => setShowPaymentModal(true)}
                                        className="px-4 py-2.5 bg-white text-emerald-700 rounded-xl text-sm font-bold shadow-lg hover:bg-emerald-50 transition-all flex items-center gap-2"
                                    >
                                        <CreditCard className="w-4 h-4" /> Record Payment
                                    </button>
                                )}
                            </div>
                        </div>
                    </div>
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                    <div className="lg:col-span-2 space-y-6">
                        {/* Customer Card */}
                        {invoice.customer && (
                            <div className="bg-white border border-slate-200 rounded-2xl shadow-sm overflow-hidden print:shadow-none print:border">
                                <div className="bg-slate-50 px-6 py-3 border-b border-slate-100">
                                    <h2 className="text-xs font-bold text-slate-500 uppercase tracking-wider">Bill To</h2>
                                </div>
                                <div className="p-6 flex items-start gap-4">
                                    <div className="w-14 h-14 rounded-2xl bg-gradient-to-br from-indigo-500 to-violet-600 flex items-center justify-center text-white text-xl font-black shadow-lg">
                                        {isCustomer(invoice.customer) ? (invoice.customer.name.charAt(0).toUpperCase()) : '?'}
                                    </div>
                                    <div className="flex-1">
                                        <p className="text-lg font-bold text-slate-800">
                                            {populatedInvoice.customer?.name || 'Customer'}
                                        </p>
                                        <div className="flex flex-wrap gap-4 mt-2 text-sm text-slate-600">
                                            {populatedInvoice.customer?.phone && (
                                                <span className="flex items-center gap-1.5">
                                                    <Phone className="w-4 h-4 text-slate-400" /> {populatedInvoice.customer.phone}
                                                </span>
                                            )}
                                            {populatedInvoice.customer?.email && (
                                                <span className="flex items-center gap-1.5">
                                                    <Mail className="w-4 h-4 text-slate-400" /> {populatedInvoice.customer.email}
                                                </span>
                                            )}
                                        </div>
                                        {populatedInvoice.customer?.address && (
                                            <p className="mt-2 text-sm text-slate-500 flex items-start gap-1.5">
                                                <MapPin className="w-4 h-4 text-slate-400 mt-0.5" /> {populatedInvoice.customer.address}
                                            </p>
                                        )}
                                    </div>
                                </div>
                            </div>
                        )}

                        {/* Invoice Items */}
                        <div className="bg-white border border-slate-200 rounded-2xl shadow-sm overflow-hidden print:shadow-none print:border">
                            <div className="bg-slate-50 px-6 py-3 border-b border-slate-100 flex justify-between items-center">
                                <h2 className="text-xs font-bold text-slate-500 uppercase tracking-wider">Invoice Items</h2>
                                <span className={`px-2.5 py-0.5 rounded-full text-xs font-bold uppercase ${statusConfig.badge}`}>
                                    {invoice.paymentStatus}
                                </span>
                            </div>
                            <div className="overflow-x-auto">
                                <table className="w-full text-left">
                                    <thead className="bg-slate-50 border-b border-slate-200">
                                        <tr className="text-xs font-bold text-slate-500 uppercase tracking-wider">
                                            <th className="px-4 py-3 text-center w-12">#</th>
                                            <th className="px-4 py-3">Item</th>
                                            <th className="px-4 py-3 text-right">Qty</th>
                                            <th className="px-4 py-3 text-right">Price</th>
                                            <th className="px-4 py-3 text-right">Total</th>
                                        </tr>
                                    </thead>
                                    <tbody className="divide-y divide-slate-100">
                                        {invoice.items?.map((item: any, index: number) => (
                                            <tr key={index} className="hover:bg-slate-50/80 transition-colors">
                                                <td className="px-4 py-3 text-center text-xs text-slate-400 font-bold">{index + 1}</td>
                                                <td className="px-4 py-3 font-medium text-slate-800">{item.name || 'Item'}</td>
                                                <td className="px-4 py-3 text-right font-medium">{item.quantity}</td>
                                                <td className="px-4 py-3 text-right text-slate-600">₹{item.price?.toFixed(2) || '0.00'}</td>
                                                <td className="px-4 py-3 text-right font-bold text-slate-800">₹{item.total?.toFixed(2) || '0.00'}</td>
                                            </tr>
                                        ))}
                                    </tbody>
                                </table>
                            </div>
                        </div>

                        {/* Invoice Info */}
                        <div className="bg-white border border-slate-200 rounded-2xl shadow-sm overflow-hidden print:shadow-none print:border">
                            <div className="bg-slate-50 px-6 py-3 border-b border-slate-100">
                                <h2 className="text-xs font-bold text-slate-500 uppercase tracking-wider">Invoice Details</h2>
                            </div>
                            <div className="p-6 grid grid-cols-2 md:grid-cols-4 gap-6">
                                <div>
                                    <p className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1">Invoice No</p>
                                    <p className="text-sm font-bold text-slate-800">{invoice.invoiceNo}</p>
                                </div>
                                <div>
                                    <p className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1">Invoice Date</p>
                                    <p className="text-sm font-medium text-slate-800">
                                        {new Date(invoice.createdAt).toLocaleDateString('en-IN', { day: '2-digit', month: 'short', year: 'numeric' })}
                                    </p>
                                </div>
                                <div>
                                    <p className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1">Payment Method</p>
                                    <p className="text-sm font-medium text-slate-800 capitalize">{invoice.paymentMethod || 'N/A'}</p>
                                </div>
                                <div>
                                    <p className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1">Time</p>
                                    <p className="text-sm font-medium text-slate-800">
                                        {new Date(invoice.createdAt).toLocaleTimeString('en-IN', { hour: '2-digit', minute: '2-digit' })}
                                    </p>
                                </div>
                            </div>
                        </div>
                    </div>

                    {/* Sidebar */}
                    <div className="lg:col-span-1 space-y-6">
                        {/* Payment Summary */}
                        <div className="bg-white border border-indigo-100 rounded-2xl shadow-sm overflow-hidden sticky top-4 print:shadow-none print:border">
                            <div className="bg-indigo-50/50 px-6 py-3 border-b border-indigo-100">
                                <h2 className="text-xs font-bold text-indigo-800 uppercase tracking-wider">Payment Summary</h2>
                            </div>
                            <div className="p-6 space-y-4">
                                <div className="flex justify-between text-sm">
                                    <span className="text-slate-500 font-medium">Subtotal</span>
                                    <span className="font-bold text-slate-800">₹{invoice.subtotal?.toFixed(2) || '0.00'}</span>
                                </div>
                                {(invoice.tax || 0) > 0 && (
                                    <div className="flex justify-between text-sm">
                                        <span className="text-slate-500 font-medium">Tax</span>
                                        <span className="font-bold text-slate-800">+₹{invoice.tax?.toFixed(2) || '0.00'}</span>
                                    </div>
                                )}
                                {(invoice.discount || 0) > 0 && (
                                    <div className="flex justify-between text-sm">
                                        <span className="text-slate-500 font-medium">Discount</span>
                                        <span className="font-bold text-rose-600">-₹{invoice.discount?.toFixed(2) || '0.00'}</span>
                                    </div>
                                )}
                                <div className="border-t pt-4">
                                    <div className="flex justify-between text-sm">
                                        <span className="text-slate-500 font-medium">Total Amount</span>
                                        <span className="font-bold text-slate-800">₹{invoice.totalAmount?.toFixed(2) || '0.00'}</span>
                                    </div>
                                </div>
                                <div className="flex justify-between text-sm">
                                    <span className="text-slate-500 font-medium">Paid Amount</span>
                                    <span className="font-bold text-emerald-600">₹{invoice.paidAmount?.toFixed(2) || '0.00'}</span>
                                </div>
                            </div>
                            <div className={`px-6 py-5 flex justify-between items-center text-white ${balanceDue > 0 ? 'bg-red-600' : 'bg-emerald-600'
                                }`}>
                                <span className="text-lg font-bold tracking-tight">
                                    {balanceDue > 0 ? 'Balance Due' : 'Fully Paid'}
                                </span>
                                <span className="text-2xl font-bold tracking-tight">
                                    {balanceDue > 0 ? `₹${balanceDue.toFixed(2)}` : <BadgeCheck className="w-8 h-8" />}
                                </span>
                            </div>
                        </div>

                        {/* Quick Actions */}
                        <div className="bg-white border border-slate-200 rounded-2xl shadow-sm overflow-hidden print:hidden">
                            <div className="bg-slate-50 px-6 py-3 border-b border-slate-100">
                                <h2 className="text-xs font-bold text-slate-500 uppercase tracking-wider">Quick Actions</h2>
                            </div>
                            <div className="p-4 space-y-2">
                                {invoice.paymentStatus !== 'paid' && (
                                    <button
                                        onClick={() => setShowPaymentModal(true)}
                                        className="w-full py-3 bg-emerald-600 text-white rounded-xl font-bold hover:bg-emerald-700 transition-all flex items-center justify-center gap-2"
                                    >
                                        <CreditCard className="w-4 h-4" /> Record Payment
                                    </button>
                                )}
                                <button
                                    onClick={handlePrint}
                                    className="w-full py-3 border border-slate-300 text-slate-700 rounded-xl font-medium hover:bg-slate-50 transition-all flex items-center justify-center gap-2"
                                >
                                    <Printer className="w-4 h-4" /> Print Invoice
                                </button>
                                <button
                                    onClick={() => {
                                        dispatch(clearSalesInvoice());
                                        dispatch(reset());
                                        navigate('/sales/invoice');
                                    }}
                                    className="w-full py-3 border border-slate-300 text-slate-700 rounded-xl font-medium hover:bg-slate-50 transition-all flex items-center justify-center gap-2"
                                >
                                    <ArrowLeft className="w-4 h-4" /> Back to List
                                </button>
                            </div>
                        </div>
                    </div>
                </div>

                {/* Print Footer */}
                <div className="hidden print:block mt-12 pt-6 border-t text-center text-slate-500 text-sm">
                    <p>Thank you for your business!</p>
                    <p className="mt-1">This is a computer-generated invoice.</p>
                </div>
            </div>

            {/* Print Styles */}
            <style>{`
                @media print {
                    .print\\:hidden { display: none !important; }
                    .print\\:shadow-none { box-shadow: none !important; }
                    .print\\:border { border: 1px solid #e2e8f0 !important; }
                    .print\\:block { display: block !important; }
                }
            `}</style>

            {/* Payment Modal */}
            {showPaymentModal && (
                <PaymentModal
                    isOpen={showPaymentModal}
                    onClose={() => setShowPaymentModal(false)}
                    onSubmit={handlePayment}
                    documentType="Sales Invoice"
                    totalAmount={invoice.totalAmount}
                    paidAmount={invoice.paidAmount}
                />
            )}
        </Layout>
    );
};

export default SalesInvoiceDetail;

import { useState, useEffect } from "react";
import { useNavigate, Link } from "react-router-dom";
import { useDispatch, useSelector } from "react-redux";
import { createSalesInvoice, reset } from "@/entities/sales/model/salesInvoiceSlice";
import Layout from "@/shared/ui/Layout/Layout";
import PageHeader from "@/shared/ui/Layout/PageHeader";
import FormInput from "@/shared/ui/Form/Input";
import CustomerSelectionModal from "@/shared/ui/Modals/CustomerSelectionModal";
import { AppDispatch, RootState } from "@/app/store/store";
import { Plus, Trash2, Save, User, Calendar, Receipt, Percent, Truck, FileText, ArrowLeft } from "lucide-react";
import { toast } from "react-toastify";

// Types (Adjust based on your actual types/sales.ts)
interface InvoiceItem {
    name: string;
    quantity: number;
    rate: number;
    tax: number; // Percentage
    amount: number;
}

const SalesInvoiceForm = () => {
    const navigate = useNavigate();
    const dispatch = useDispatch<AppDispatch>();
    const { isLoading, isSuccess, isError, message } = useSelector(
        (state: RootState) => state.salesInvoice
    );

    // Form State
    const [formData, setFormData] = useState({
        invoiceNo: `INV-${Date.now()}`, // Temporary ID generation
        invoiceDate: new Date().toISOString().split("T")[0],
        dueDate: "",
        customer: null as any,
        items: [] as InvoiceItem[],
        discount: 0,
        shippingCharges: 0,
        notes: "",
        termsAndConditions: "",
    });

    const [showCustomerModal, setShowCustomerModal] = useState(false);

    // Initialize with one empty item
    useEffect(() => {
        if (formData.items.length === 0) {
            setFormData(prev => ({
                ...prev,
                items: [{ name: "", quantity: 1, rate: 0, tax: 0, amount: 0 }]
            }));
        }
    }, []);

    useEffect(() => {
        if (isSuccess) {
            toast.success("Invoice created successfully!");
            dispatch(reset());
            navigate("/sales"); // Go back to list
        }
        if (isError) {
            toast.error(message || "Failed to create invoice");
        }
        return () => {
            dispatch(reset());
        };
    }, [isSuccess, isError, message, dispatch, navigate]);

    // Calculations
    const calculateItemAmount = (item: InvoiceItem) => {
        const baseAmount = item.quantity * item.rate;
        const taxAmount = (baseAmount * item.tax) / 100;
        return baseAmount + taxAmount;
    };

    const updateItem = (index: number, field: keyof InvoiceItem, value: any) => {
        const newItems = [...formData.items];
        newItems[index] = { ...newItems[index], [field]: value };
        newItems[index].amount = calculateItemAmount(newItems[index]);
        setFormData({ ...formData, items: newItems });
    };

    const addItem = () => {
        setFormData({
            ...formData,
            items: [...formData.items, { name: "", quantity: 1, rate: 0, tax: 0, amount: 0 }],
        });
    };

    const removeItem = (index: number) => {
        if (formData.items.length > 1) {
            const newItems = formData.items.filter((_, i) => i !== index);
            setFormData({ ...formData, items: newItems });
        }
    };

    const calculateSubtotal = () => {
        return formData.items.reduce((sum, item) => sum + (item.quantity * item.rate), 0);
    };

    const calculateTotalTax = () => {
        return formData.items.reduce((sum, item) => sum + ((item.quantity * item.rate * item.tax) / 100), 0);
    };

    const calculateTotal = () => {
        const subtotal = calculateSubtotal();
        const totalTax = calculateTotalTax();
        return subtotal + totalTax + Number(formData.shippingCharges) - Number(formData.discount);
    };

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (!formData.customer) {
            toast.error("Please select a customer");
            return;
        }
        if (formData.items.some(item => !item.name || item.quantity <= 0 || item.rate <= 0)) {
            toast.error("Please ensure all items have valid details");
            return;
        }

        // Adapt payload to your API requirements
        const payload = {
            ...formData,
            customer: formData.customer._id, // Assuming customer object has _id
            totalAmount: calculateTotal(),
            subtotal: calculateSubtotal(),
            tax: calculateTotalTax(),
            status: "unpaid", // Default status
            // validUntil: formData.dueDate // Check API field name
        };

        dispatch(createSalesInvoice(payload));
    };

    return (
        <Layout>
            <div className="max-w-5xl mx-auto pb-20 animate-fade-in">
                <PageHeader
                    title="Create New Invoice"
                    description="Draft and issue a new sales invoice"
                    backButton={
                        <Link
                            to="/sales"
                            className="inline-flex items-center gap-2 text-sm font-bold text-neutral-500 hover:text-primary transition-colors"
                        >
                            <ArrowLeft className="w-4 h-4" /> Back to Sales
                        </Link>
                    }
                />

                <form onSubmit={handleSubmit} className="space-y-6 mt-6">
                    {/* Section 1: Invoice Details */}
                    <div className="bg-white dark:bg-neutral-800 rounded-xl border border-neutral-200 dark:border-neutral-700 p-6 shadow-sm">
                        <h3 className="text-lg font-bold text-neutral-800 dark:text-neutral-100 mb-4 flex items-center gap-2">
                            <FileText className="w-5 h-5 text-primary" /> Invoice Details
                        </h3>
                        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                            <FormInput
                                label="Invoice Number"
                                name="invoiceNo"
                                value={formData.invoiceNo}
                                onChange={(e: React.ChangeEvent<HTMLInputElement>) => setFormData({ ...formData, invoiceNo: e.target.value })}
                                icon={<Receipt className="w-4 h-4" />}
                                required
                                disabled // Auto-generated usually
                            />
                            <FormInput
                                label="Invoice Date"
                                type="date"
                                name="invoiceDate"
                                value={formData.invoiceDate}
                                onChange={(e: React.ChangeEvent<HTMLInputElement>) => setFormData({ ...formData, invoiceDate: e.target.value })}
                                icon={<Calendar className="w-4 h-4" />}
                                required
                            />
                            <FormInput
                                label="Due Date"
                                type="date"
                                name="dueDate"
                                value={formData.dueDate}
                                onChange={(e: React.ChangeEvent<HTMLInputElement>) => setFormData({ ...formData, dueDate: e.target.value })}
                                icon={<Calendar className="w-4 h-4" />}
                            />
                        </div>
                    </div>

                    {/* Section 2: Customer Selection */}
                    <div className="bg-white dark:bg-neutral-800 rounded-xl border border-neutral-200 dark:border-neutral-700 p-6 shadow-sm">
                        <div className="flex justify-between items-center mb-4">
                            <h3 className="text-lg font-bold text-neutral-800 dark:text-neutral-100 flex items-center gap-2">
                                <User className="w-5 h-5 text-primary" /> Customer
                            </h3>
                            {!formData.customer && (
                                <button
                                    type="button"
                                    onClick={() => setShowCustomerModal(true)}
                                    className="text-sm font-medium text-primary hover:underline"
                                >
                                    Select Customer
                                </button>
                            )}
                        </div>

                        {formData.customer ? (
                            <div className="flex items-center justify-between p-4 bg-neutral-50 dark:bg-neutral-900 rounded-lg border border-neutral-200 dark:border-neutral-700">
                                <div>
                                    <p className="font-bold text-neutral-900 dark:text-neutral-100">{formData.customer.name}</p>
                                    <p className="text-sm text-neutral-500">{formData.customer.phone || formData.customer.email}</p>
                                </div>
                                <button
                                    type="button"
                                    onClick={() => setFormData({ ...formData, customer: null })}
                                    className="p-2 hover:bg-neutral-200 dark:hover:bg-neutral-800 rounded-md text-neutral-500"
                                >
                                    Change
                                </button>
                            </div>
                        ) : (
                            <div
                                onClick={() => setShowCustomerModal(true)}
                                className="border-2 border-dashed border-neutral-300 dark:border-neutral-700 rounded-lg p-8 flex flex-col items-center justify-center text-neutral-400 cursor-pointer hover:border-primary hover:text-primary transition-colors"
                            >
                                <User className="w-8 h-8 mb-2" />
                                <span className="font-medium">Click to select a customer</span>
                            </div>
                        )}
                    </div>

                    {/* Section 3: Items */}
                    <div className="bg-white dark:bg-neutral-800 rounded-xl border border-neutral-200 dark:border-neutral-700 p-6 shadow-sm overflow-hidden">
                        <h3 className="text-lg font-bold text-neutral-800 dark:text-neutral-100 mb-4">Items</h3>
                        <div className="overflow-x-auto">
                            <table className="w-full text-left">
                                <thead>
                                    <tr className="border-b border-neutral-200 dark:border-neutral-700 text-xs font-semibold text-neutral-500 uppercase">
                                        <th className="px-4 py-3 min-w-[200px]">Item Name</th>
                                        <th className="px-4 py-3 w-24 text-right">Qty</th>
                                        <th className="px-4 py-3 w-32 text-right">Rate</th>
                                        <th className="px-4 py-3 w-24 text-right">Tax (%)</th>
                                        <th className="px-4 py-3 w-32 text-right">Amount</th>
                                        <th className="px-4 py-3 w-16"></th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-neutral-200 dark:divide-neutral-700">
                                    {formData.items.map((item, index) => (
                                        <tr key={index}>
                                            <td className="px-4 py-3">
                                                <input
                                                    type="text"
                                                    placeholder="Item name/description"
                                                    value={item.name}
                                                    onChange={(e) => updateItem(index, 'name', e.target.value)}
                                                    className="w-full bg-transparent border-none focus:ring-0 p-0 text-sm font-medium placeholder:text-neutral-400"
                                                />
                                            </td>
                                            <td className="px-4 py-3">
                                                <input
                                                    type="number"
                                                    min="1"
                                                    value={item.quantity}
                                                    onChange={(e) => updateItem(index, 'quantity', Number(e.target.value))}
                                                    className="w-full bg-transparent border-none focus:ring-0 p-0 text-sm text-right"
                                                />
                                            </td>
                                            <td className="px-4 py-3">
                                                <input
                                                    type="number"
                                                    min="0"
                                                    value={item.rate}
                                                    onChange={(e) => updateItem(index, 'rate', Number(e.target.value))}
                                                    className="w-full bg-transparent border-none focus:ring-0 p-0 text-sm text-right"
                                                />
                                            </td>
                                            <td className="px-4 py-3">
                                                <input
                                                    type="number"
                                                    min="0"
                                                    max="100"
                                                    value={item.tax}
                                                    onChange={(e) => updateItem(index, 'tax', Number(e.target.value))}
                                                    className="w-full bg-transparent border-none focus:ring-0 p-0 text-sm text-right text-neutral-500"
                                                />
                                            </td>
                                            <td className="px-4 py-3 text-right font-medium text-neutral-900 dark:text-neutral-100">
                                                ₹{item.amount.toFixed(2)}
                                            </td>
                                            <td className="px-4 py-3 text-center">
                                                <button
                                                    type="button"
                                                    onClick={() => removeItem(index)}
                                                    className="text-neutral-400 hover:text-rose-500 transition-colors p-1"
                                                >
                                                    <Trash2 className="w-4 h-4" />
                                                </button>
                                            </td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                        <button
                            type="button"
                            onClick={addItem}
                            className="mt-4 flex items-center gap-2 text-sm font-bold text-primary hover:text-primary-hover transition-colors px-4" // Added px-4 for alignment if needed
                        >
                            <Plus className="w-4 h-4" /> Add Item
                        </button>
                    </div>

                    {/* Section 4: Summary & Totals */}
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <div className="space-y-4">
                            <div className="bg-white dark:bg-neutral-800 rounded-xl border border-neutral-200 dark:border-neutral-700 p-6 shadow-sm h-full">
                                <h3 className="text-sm font-bold text-neutral-500 uppercase mb-4">Notes & Terms</h3>
                                <textarea
                                    placeholder="Add notes for the customer..."
                                    value={formData.notes}
                                    onChange={(e) => setFormData({ ...formData, notes: e.target.value })}
                                    className="w-full p-3 bg-neutral-50 dark:bg-neutral-900 border border-neutral-200 dark:border-neutral-700 rounded-lg text-sm mb-4 focus:ring-2 focus:ring-primary/20 focus:border-primary outline-none resize-none h-24"
                                />
                                <textarea
                                    placeholder="Terms and conditions..."
                                    value={formData.termsAndConditions}
                                    onChange={(e) => setFormData({ ...formData, termsAndConditions: e.target.value })}
                                    className="w-full p-3 bg-neutral-50 dark:bg-neutral-900 border border-neutral-200 dark:border-neutral-700 rounded-lg text-sm focus:ring-2 focus:ring-primary/20 focus:border-primary outline-none resize-none h-24"
                                />
                            </div>
                        </div>

                        <div className="space-y-4">
                            <div className="bg-white dark:bg-neutral-800 rounded-xl border border-neutral-200 dark:border-neutral-700 p-6 shadow-sm">
                                <h3 className="text-sm font-bold text-neutral-500 uppercase mb-4">Payment Summary</h3>

                                <div className="space-y-3 text-sm">
                                    <div className="flex justify-between text-neutral-600 dark:text-neutral-400">
                                        <span>Subtotal</span>
                                        <span>₹{calculateSubtotal().toFixed(2)}</span>
                                    </div>
                                    <div className="flex justify-between text-neutral-600 dark:text-neutral-400">
                                        <span>Tax (Total)</span>
                                        <span>+ ₹{calculateTotalTax().toFixed(2)}</span>
                                    </div>
                                    <div className="flex justify-between items-center text-neutral-600 dark:text-neutral-400">
                                        <span className="flex items-center gap-1"><Truck className="w-3 h-3" /> Shipping</span>
                                        <input
                                            type="number"
                                            value={formData.shippingCharges}
                                            onChange={(e) => setFormData({ ...formData, shippingCharges: Number(e.target.value) })}
                                            className="w-24 text-right bg-transparent border-b border-neutral-300 dark:border-neutral-700 focus:border-primary outline-none p-1"
                                        />
                                    </div>
                                    <div className="flex justify-between items-center text-neutral-600 dark:text-neutral-400">
                                        <span className="flex items-center gap-1"><Percent className="w-3 h-3" /> Discount</span>
                                        <input
                                            type="number"
                                            value={formData.discount}
                                            onChange={(e) => setFormData({ ...formData, discount: Number(e.target.value) })}
                                            className="w-24 text-right bg-transparent border-b border-neutral-300 dark:border-neutral-700 focus:border-primary outline-none p-1 text-rose-500"
                                        />
                                    </div>
                                    <div className="border-t border-neutral-200 dark:border-neutral-700 pt-3 flex justify-between items-center font-bold text-lg text-neutral-900 dark:text-neutral-100">
                                        <span>Total Amount</span>
                                        <span>₹{calculateTotal().toFixed(2)}</span>
                                    </div>
                                </div>
                            </div>

                            <button
                                type="submit"
                                disabled={isLoading}
                                className="w-full py-4 bg-primary text-white rounded-xl font-bold text-lg shadow-lg hover:bg-primary-hover hover:shadow-primary/30 transition-all disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2"
                            >
                                {isLoading ? (
                                    <>Processing...</>
                                ) : (
                                    <><Save className="w-5 h-5" /> Save & Create Invoice</>
                                )}
                            </button>
                        </div>
                    </div>
                </form>
            </div>

            <CustomerSelectionModal
                isOpen={showCustomerModal}
                onClose={() => setShowCustomerModal(false)}
                onSelect={(customer: any) => {
                    setFormData({ ...formData, customer });
                    setShowCustomerModal(false);
                }}
            />
        </Layout>
    );
};

export default SalesInvoiceForm;

import { logger } from '@/shared/lib/logger';
import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import api from "@/shared/api/api";
import { toast } from 'react-toastify';
import Layout from "@/shared/ui/Layout/Layout";
import PageHeader from "@/shared/ui/Layout/PageHeader";
import FormInput from "@/shared/ui/Form/Input";
import CustomerSelectionModal from "@/shared/ui/Modals/CustomerSelectionModal";
import ItemSelectionModal from "@/shared/ui/Modals/ItemSelectionModal";
import type { SalesOrder, SalesOrderItem, Customer } from '@repo/shared';

const SalesOrderPage = () => {
    const navigate = useNavigate();
    const [showCustomerModal, setShowCustomerModal] = useState(false);
    const [showItemModal, setShowItemModal] = useState(false);
    const [loading, setLoading] = useState(false);

    // Using a shape compatible with SalesOrder but allowing for form state
    interface SalesOrderFormData {
        orderDate: string;
        expectedDeliveryDate: string;
        customer: Customer | null;
        items: SalesOrderItem[];
        discount: number;
        notes: string;
    }

    const [formData, setFormData] = useState<SalesOrderFormData>({
        orderDate: new Date().toISOString().split('T')[0],
        expectedDeliveryDate: '',
        customer: null,
        items: [],
        discount: 0,
        notes: ''
    });

    const addItemFromModal = (item: any) => {
        const existingIndex = formData.items.findIndex((i) => i.item === item._id);

        if (existingIndex >= 0) {
            // Update quantity if item already exists
            const newItems = [...formData.items];
            newItems[existingIndex].quantity += item.quantity || 1;
            setFormData({ ...formData, items: newItems });
        } else {
            // Add new item
            const newItem: SalesOrderItem = {
                item: item._id,
                name: item.name,
                quantity: item.quantity || 1,
                rate: item.sellingPrice || 0,
                tax: 18,
                discount: 0,
                availableStock: item.stockQty - (item.reservedStock || 0)
            };

            setFormData({
                ...formData,
                items: [...formData.items, newItem]
            });
        }
    };

    const updateItem = (index: number, field: keyof SalesOrderItem, value: number) => {
        const newItems = [...formData.items];
        // @ts-ignore - Dynamic key assignment
        newItems[index][field] = value;
        setFormData({ ...formData, items: newItems });
    };

    const removeItem = (index: number) => {
        const newItems = formData.items.filter((_, i) => i !== index);
        setFormData({ ...formData, items: newItems });
    };

    const calculateItemTotal = (item: SalesOrderItem) => {
        const subtotal = item.quantity * item.rate;
        const taxAmount = (subtotal * item.tax) / 100;
        return subtotal + taxAmount - item.discount;
    };

    const calculateSubtotal = () => {
        return formData.items.reduce((sum, item) => sum + (item.quantity * item.rate), 0);
    };

    const calculateTax = () => {
        return formData.items.reduce((sum, item) => {
            const subtotal = item.quantity * item.rate;
            return sum + (subtotal * item.tax / 100);
        }, 0);
    };

    const calculateItemDiscount = () => {
        return formData.items.reduce((sum, item) => sum + (item.discount || 0), 0);
    };

    const calculateTotal = () => {
        return calculateSubtotal() + calculateTax() - calculateItemDiscount() - formData.discount;
    };

    const validateForm = () => {
        if (!formData.customer) {
            toast.error('Please select a customer');
            return false;
        }

        if (formData.items.length === 0) {
            toast.error('Please add at least one item');
            return false;
        }

        if (!formData.expectedDeliveryDate) {
            toast.error('Please select expected delivery date');
            return false;
        }

        // Validate stock availability
        for (const item of formData.items) {
            if (item.availableStock !== undefined && item.quantity > item.availableStock) {
                toast.error(`Insufficient available stock for ${item.name}. Available: ${item.availableStock}`);
                return false;
            }
        }

        return true;
    };

    const handleSaveDraft = async () => {
        if (!validateForm()) return;

        setLoading(true);
        try {
            const user = JSON.parse(localStorage.getItem('user') || '{}');
            const token = user?.token;
            // Ensure customer is not null (validated in validateForm)
            if (!formData.customer) return;

            const payload = {
                customerId: formData.customer.id || formData.customer._id,
                orderDate: formData.orderDate,
                expectedDeliveryDate: formData.expectedDeliveryDate,
                items: formData.items.map((item) => ({
                    item: item.item,
                    quantity: item.quantity,
                    rate: item.rate,
                    tax: item.tax,
                    discount: item.discount
                })),
                discount: formData.discount,
                notes: formData.notes
            };

            const response = await api.post(
                `/api/sales-orders`,
                payload,
                { headers: { Authorization: `Bearer ${token}` } }
            );

            toast.success('Sales Order saved as draft successfully!');
            navigate('/sales/sales-order-list');
        } catch (error: any) {
            logger.error('Error saving sales order:', error);
            toast.error(error.response?.data?.message || 'Failed to save sales order');
        } finally {
            setLoading(false);
        }
    };

    const handleConfirmOrder = async () => {
        if (!validateForm()) return;

        setLoading(true);
        try {
            const user = JSON.parse(localStorage.getItem('user') || '{}');
            const token = user?.token;

            if (!formData.customer) return;

            // First create the order
            const payload = {
                customerId: formData.customer.id || formData.customer._id,
                orderDate: formData.orderDate,
                expectedDeliveryDate: formData.expectedDeliveryDate,
                items: formData.items.map((item) => ({
                    item: item.item,
                    quantity: item.quantity,
                    rate: item.rate,
                    tax: item.tax,
                    discount: item.discount
                })),
                discount: formData.discount,
                notes: formData.notes
            };

            const createResponse = await api.post(
                `/api/sales-orders`,
                payload,
                { headers: { Authorization: `Bearer ${token}` } }
            );

            const orderId = createResponse.data.salesOrder._id;

            // Then confirm it
            await api.post(
                `/api/sales-orders/${orderId}/confirm`,
                {},
                { headers: { Authorization: `Bearer ${token}` } }
            );

            toast.success('Sales Order confirmed successfully! Stock reserved.');
            navigate('/sales/sales-order-list');
        } catch (error: any) {
            logger.error('Error confirming sales order:', error);
            toast.error(error.response?.data?.message || 'Failed to confirm sales order');
        } finally {
            setLoading(false);
        }
    };

    const statusOptions = [
        { value: 'Draft', label: 'Draft', color: 'bg-gray-100 text-gray-800' },
        { value: 'Confirmed', label: 'Confirmed', color: 'bg-blue-100 text-blue-800' },
        { value: 'Partially Delivered', label: 'Partially Delivered', color: 'bg-purple-100 text-purple-800' },
        { value: 'Delivered', label: 'Delivered', color: 'bg-indigo-100 text-indigo-800' },
        { value: 'Partially Invoiced', label: 'Partially Invoiced', color: 'bg-yellow-100 text-yellow-800' },
        { value: 'Invoiced', label: 'Invoiced', color: 'bg-green-100 text-green-800' },
        { value: 'Cancelled', label: 'Cancelled', color: 'bg-red-100 text-red-800' }
    ];

    // Helper to calculate total tax amount for display
    const totalTaxAmount = calculateTax();
    const subTotalAmount = calculateSubtotal();
    const totalDiscountAmount = calculateItemDiscount();
    const finalTotalAmount = calculateTotal();

    return (
        <Layout>
            <div className="flex flex-col h-[calc(100vh-theme(spacing.16))] bg-slate-50 animate-fade-in">
                {/* ERP Header Action Bar */}
                <div className="bg-white border-b border-slate-200 px-6 py-4 flex items-center justify-between shadow-sm shrink-0 z-10">
                    <div>
                        <h1 className="text-2xl font-bold text-slate-800 tracking-tight">Sales Order</h1>
                        <p className="text-sm text-slate-500 mt-0.5">Manage customer orders and reservations</p>
                    </div>
                    <div className="flex items-center gap-3">
                        <button
                            onClick={() => navigate('/sales/sales-order-list')}
                            className="px-4 py-2 text-sm font-medium text-slate-700 bg-white border border-slate-300 rounded-lg hover:bg-slate-50 transition-colors shadow-sm"
                        >
                            Cancel
                        </button>
                        <button
                            onClick={handleSaveDraft}
                            disabled={loading}
                            className="px-4 py-2 text-sm font-medium text-indigo-700 bg-indigo-50 border border-indigo-200 rounded-lg hover:bg-indigo-100 disabled:opacity-50 transition-colors shadow-sm"
                        >
                            {loading ? 'Saving...' : 'Save Draft'}
                        </button>
                        <button
                            onClick={handleConfirmOrder}
                            disabled={loading}
                            className="px-6 py-2 text-sm font-medium text-white bg-emerald-600 border border-transparent rounded-lg shadow-sm hover:bg-emerald-700 focus:ring-2 focus:ring-offset-2 focus:ring-emerald-500 disabled:opacity-50 flex items-center gap-2 transition-all"
                        >
                            {loading ? (
                                <svg className="animate-spin h-4 w-4 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                                    <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                                    <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                                </svg>
                            ) : (
                                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
                                </svg>
                            )}
                            {loading ? 'Processing...' : 'Confirm Order'}
                        </button>
                    </div>
                </div>

                {/* Main Content Scrollable Area */}
                <div className="flex-1 overflow-auto p-6">
                    <div className="max-w-7xl mx-auto space-y-6 pb-10">
                        {/* Top Section: Order Info & Customer */}
                        <div className="bg-white border border-slate-200 rounded-xl shadow-sm overflow-hidden">
                            <div className="bg-slate-50/50 px-6 py-3 border-b border-slate-100 flex justify-between items-center">
                                <h2 className="text-xs font-bold text-slate-500 uppercase tracking-wider">Order Information</h2>
                                <div className="text-xs font-bold text-slate-500 bg-white px-2.5 py-1 rounded-md border border-slate-200 shadow-sm">
                                    DRAFT MODE
                                </div>
                            </div>
                            <div className="p-6 grid grid-cols-1 md:grid-cols-4 gap-8">
                                {/* Column 1: Dates */}
                                <div className="space-y-5">
                                    <div>
                                        <label className="block text-xs font-bold text-slate-500 mb-1.5 uppercase">Order Date <span className="text-red-500">*</span></label>
                                        <input
                                            type="date"
                                            value={formData.orderDate}
                                            onChange={(e) => setFormData({ ...formData, orderDate: e.target.value })}
                                            className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 shadow-sm"
                                        />
                                    </div>
                                    <div>
                                        <label className="block text-xs font-bold text-slate-500 mb-1.5 uppercase">Expected Delivery <span className="text-red-500">*</span></label>
                                        <input
                                            type="date"
                                            value={formData.expectedDeliveryDate}
                                            onChange={(e) => setFormData({ ...formData, expectedDeliveryDate: e.target.value })}
                                            className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 shadow-sm"
                                        />
                                    </div>
                                </div>

                                {/* Column 2: Empty Spacer or Additional Meta */}
                                <div className="hidden md:block"></div>

                                {/* Column 3 & 4: Customer Panel */}
                                <div className="md:col-span-2 border border-slate-200 rounded-xl bg-slate-50/50 p-4 relative group hover:border-indigo-300 transition-colors">
                                    <label className="block text-xs font-bold text-indigo-600 mb-3 uppercase tracking-wider">Customer Details</label>
                                    {formData.customer ? (
                                        <div className="flex justify-between items-start">
                                            <div>
                                                <p className="font-bold text-slate-800 text-base">{formData.customer.name}</p>
                                                {/* @ts-ignore - address might be string or object */}
                                                <p className="text-sm text-slate-600 mt-1">{formData.customer.address?.line1 || typeof formData.customer.address === 'string' ? formData.customer.address : ''}, {formData.customer.address?.city}</p>
                                                <div className="flex gap-4 mt-3 text-xs font-medium text-slate-500">
                                                    <span className="flex items-center gap-1">
                                                        <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 5a2 2 0 012-2h3.28a1 1 0 01.948.684l1.498 4.493a1 1 0 01-.502 1.21l-2.257 1.13a11.042 11.042 0 005.516 5.516l1.13-2.257a1 1 0 011.21-.502l4.493 1.498a1 1 0 01.684.949V19a2 2 0 01-2 2h-1C9.716 21 3 14.284 3 6V5z" /></svg>
                                                        {formData.customer.phone}
                                                    </span>
                                                    {formData.customer.email && (
                                                        <span className="flex items-center gap-1">
                                                            <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 8l7.89 5.26a2 2 0 002.22 0L21 8M5 19h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z" /></svg>
                                                            {formData.customer.email}
                                                        </span>
                                                    )}
                                                </div>
                                            </div>
                                            <button
                                                onClick={() => setFormData({ ...formData, customer: null })}
                                                className="text-red-600 hover:text-red-700 text-xs font-medium border border-red-200 bg-white px-3 py-1.5 rounded-lg hover:bg-red-50 transition-colors shadow-sm"
                                            >
                                                Change
                                            </button>
                                        </div>
                                    ) : (
                                        <div className="h-full flex flex-col items-center justify-center gap-3 py-4">
                                            <div className="p-3 bg-white rounded-full shadow-sm">
                                                <svg className="w-6 h-6 text-slate-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z" /></svg>
                                            </div>
                                            <p className="text-sm font-medium text-slate-500">No customer selected</p>
                                            <button
                                                onClick={() => setShowCustomerModal(true)}
                                                className="px-4 py-2 bg-indigo-600 text-white text-xs font-bold uppercase tracking-wider rounded-lg hover:bg-indigo-700 shadow-sm flex items-center gap-2 transition-all"
                                            >
                                                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
                                                Find Customer
                                            </button>
                                        </div>
                                    )}
                                </div>
                            </div>
                        </div>

                        {/* Items Section - Dense Table with Calculations */}
                        <div className="bg-white border border-slate-200 rounded-xl shadow-sm overflow-hidden flex flex-col min-h-[300px]">
                            <div className="px-6 py-3 border-b border-slate-100 bg-slate-50/50 flex justify-between items-center">
                                <h2 className="text-xs font-bold text-slate-500 uppercase tracking-wider">Line Items</h2>
                                <button
                                    onClick={() => setShowItemModal(true)}
                                    className="px-4 py-2 bg-emerald-600 text-white text-xs font-bold uppercase tracking-wider rounded-lg hover:bg-emerald-700 flex items-center gap-2 shadow-sm transition-all"
                                >
                                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 6v6m0 0v6m0-6h6m-6 0H6" /></svg>
                                    Add Product
                                </button>
                            </div>

                            <div className="flex-1 overflow-x-auto">
                                <table className="w-full text-left border-collapse">
                                    <thead>
                                        <tr className="bg-slate-50 border-b border-slate-200 text-xs font-bold text-slate-500 uppercase tracking-wider">
                                            <th className="px-4 py-3 border-r border-slate-200 w-12 text-center">#</th>
                                            <th className="px-4 py-3 border-r border-slate-200">Product</th>
                                            <th className="px-4 py-3 border-r border-slate-200 w-28 text-right">Qty</th>
                                            <th className="px-4 py-3 border-r border-slate-200 w-32 text-right">Rate</th>
                                            <th className="px-4 py-3 border-r border-slate-200 w-24 text-right">Tax %</th>
                                            <th className="px-4 py-3 border-r border-slate-200 w-28 text-right">Disc</th>
                                            <th className="px-4 py-3 border-r border-slate-200 w-32 text-right">Total</th>
                                            <th className="px-4 py-3 w-12 text-center"></th>
                                        </tr>
                                    </thead>
                                    <tbody className="divide-y divide-slate-100">
                                        {formData.items.length === 0 ? (
                                            <tr>
                                                <td colSpan={8} className="px-4 py-16 text-center text-slate-400">
                                                    <div className="flex flex-col items-center gap-2">
                                                        <svg className="w-8 h-8 text-slate-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M20 7l-8-4-8 4m16 0l-8 4m8-4v10l-8 4m0-10L4 7m8 4v10M4 7v10l8 4" /></svg>
                                                        <p className="text-sm font-medium">No items added yet</p>
                                                        <p className="text-xs">Select products to build your order</p>
                                                    </div>
                                                </td>
                                            </tr>
                                        ) : (
                                            formData.items.map((item, index) => (
                                                <tr key={index} className="hover:bg-slate-50/80 group transition-colors">
                                                    <td className="px-4 py-2 text-xs text-slate-500 text-center border-r border-slate-100 bg-slate-50/30">
                                                        {index + 1}
                                                    </td>
                                                    <td className="px-4 py-2 border-r border-slate-100 max-w-xs">
                                                        <p className="text-sm font-semibold text-slate-800 truncate">{item.name}</p>
                                                        <p className="text-[10px] uppercase font-bold text-slate-400 mt-0.5">Stock: {item.availableStock}</p>
                                                    </td>
                                                    <td className="px-4 py-2 border-r border-slate-100 text-right p-1.5">
                                                        <input
                                                            type="number"
                                                            min="1"
                                                            max={item.availableStock}
                                                            value={item.quantity}
                                                            onChange={(e) => updateItem(index, 'quantity', parseFloat(e.target.value) || 0)}
                                                            className="w-full text-right px-2 py-1.5 text-sm border border-slate-200 rounded-md focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 transition-all font-medium"
                                                        />
                                                    </td>
                                                    <td className="px-4 py-2 border-r border-slate-100 text-right p-1.5">
                                                        <input
                                                            type="number"
                                                            value={item.rate}
                                                            onChange={(e) => updateItem(index, 'rate', parseFloat(e.target.value) || 0)}
                                                            className="w-full text-right px-2 py-1.5 text-sm border border-slate-200 rounded-md focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 transition-all font-medium"
                                                        />
                                                    </td>
                                                    <td className="px-4 py-2 border-r border-slate-100 text-right p-1.5">
                                                        <select
                                                            value={item.tax}
                                                            onChange={(e) => updateItem(index, 'tax', parseFloat(e.target.value))}
                                                            className="w-full text-right px-1 py-1.5 text-sm border border-slate-200 rounded-md focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 transition-all bg-white"
                                                        >
                                                            <option value="0">0%</option>
                                                            <option value="5">5%</option>
                                                            <option value="12">12%</option>
                                                            <option value="18">18%</option>
                                                            <option value="28">28%</option>
                                                        </select>
                                                    </td>
                                                    <td className="px-4 py-2 border-r border-slate-100 text-right p-1.5">
                                                        <input
                                                            type="number"
                                                            value={item.discount}
                                                            onChange={(e) => updateItem(index, 'discount', parseFloat(e.target.value) || 0)}
                                                            className="w-full text-right px-2 py-1.5 text-sm border border-slate-200 rounded-md focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 transition-all"
                                                        />
                                                    </td>
                                                    <td className="px-4 py-2 border-r border-slate-100 text-right font-bold text-slate-700">
                                                        ₹{calculateItemTotal(item).toFixed(2)}
                                                    </td>
                                                    <td className="px-4 py-2 text-center">
                                                        <button
                                                            onClick={() => removeItem(index)}
                                                            className="text-slate-400 hover:text-red-600 transition-colors p-1.5 hover:bg-red-50 rounded-lg"
                                                            title="Remove Item"
                                                        >
                                                            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
                                                            </svg>
                                                        </button>
                                                    </td>
                                                </tr>
                                            ))
                                        )}
                                    </tbody>
                                    {formData.items.length > 0 && (
                                        <tfoot className="bg-slate-50/50 border-t border-slate-200">
                                            <tr>
                                                <td colSpan={6} className="px-4 py-3 text-xs text-right text-slate-500 uppercase font-bold border-r border-slate-200">Subtotal</td>
                                                <td className="px-4 py-3 text-sm text-right font-bold text-slate-700 border-r border-slate-200">₹{subTotalAmount.toFixed(2)}</td>
                                                <td></td>
                                            </tr>
                                            <tr>
                                                <td colSpan={6} className="px-4 py-3 text-xs text-right text-slate-500 uppercase font-bold border-r border-slate-200">Total Tax</td>
                                                <td className="px-4 py-3 text-sm text-right font-bold text-slate-700 border-r border-slate-200">₹{totalTaxAmount.toFixed(2)}</td>
                                                <td></td>
                                            </tr>
                                        </tfoot>
                                    )}
                                </table>
                            </div>
                        </div>

                        {/* Bottom Section: Notes & Final Totals */}
                        <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
                            {/* Notes Panel */}
                            <div className="md:col-span-2 bg-white border border-slate-200 rounded-xl shadow-sm overflow-hidden flex flex-col">
                                <div className="bg-slate-50/50 px-6 py-3 border-b border-slate-100">
                                    <h2 className="text-xs font-bold text-slate-500 uppercase tracking-wider">Terms & Notes</h2>
                                </div>
                                <div className="p-4 flex-1">
                                    <textarea
                                        value={formData.notes}
                                        onChange={(e) => setFormData({ ...formData, notes: e.target.value })}
                                        rows={4}
                                        className="w-full h-full px-4 py-3 border border-slate-300 rounded-lg text-sm focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 resize-none placeholder:text-slate-400"
                                        placeholder="Add payment terms, delivery instructions, or general remarks..."
                                    />
                                </div>
                            </div>

                            {/* Final Calculations Panel */}
                            <div className="bg-white border border-indigo-100 rounded-xl shadow-sm overflow-hidden flex flex-col">
                                <div className="bg-indigo-50/50 px-6 py-3 border-b border-indigo-100">
                                    <h2 className="text-xs font-bold text-indigo-800 uppercase tracking-wider">Order Summary</h2>
                                </div>
                                <div className="p-6 space-y-4 flex-1">
                                    <div className="flex justify-between text-sm">
                                        <span className="text-slate-500 font-medium">Subtotal</span>
                                        <span className="font-bold text-slate-800">₹{subTotalAmount.toFixed(2)}</span>
                                    </div>
                                    <div className="flex justify-between text-sm">
                                        <span className="text-slate-500 font-medium">Item Discounts</span>
                                        <span className="font-bold text-rose-600">-₹{totalDiscountAmount.toFixed(2)}</span>
                                    </div>
                                    <div className="flex justify-between text-sm">
                                        <span className="text-slate-500 font-medium">Tax</span>
                                        <span className="font-bold text-slate-800">₹{totalTaxAmount.toFixed(2)}</span>
                                    </div>
                                    <div className="border-t border-slate-100 pt-4 mt-2">
                                        <div className="flex justify-between items-center mb-2">
                                            <span className="text-sm font-bold text-slate-600">Additional Discount</span>
                                            <input
                                                type="number"
                                                value={formData.discount}
                                                onChange={(e) => setFormData({ ...formData, discount: parseFloat(e.target.value) || 0 })}
                                                className="w-24 text-right px-3 py-1.5 text-sm border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 font-medium"
                                            />
                                        </div>
                                    </div>
                                </div>
                                <div className="bg-slate-800 px-6 py-5 flex justify-between items-center text-white">
                                    <span className="text-lg font-bold tracking-tight">Net Total</span>
                                    <span className="text-2xl font-bold tracking-tight">₹{finalTotalAmount.toFixed(2)}</span>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>

                <CustomerSelectionModal
                    isOpen={showCustomerModal}
                    onClose={() => setShowCustomerModal(false)}
                    onSelect={(customer: any) => {
                        setFormData({ ...formData, customer });
                        setShowCustomerModal(false);
                    }}
                />

                <ItemSelectionModal
                    isOpen={showItemModal}
                    onClose={() => setShowItemModal(false)}
                    onSelect={addItemFromModal}
                />
            </div>
        </Layout>
    );
};

export default SalesOrderPage;

import { logger } from '@/shared/lib/logger';
import { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import api from "@/shared/api/api";
import { toast } from 'react-toastify';
import Layout from "@/shared/ui/Layout/Layout";
import {
    Package,
    Truck,
    FileText,
    CheckCircle,
    XCircle,
    Clock,
    ArrowLeft,
    Printer,
    AlertTriangle,
    Phone,
    Mail,
    ClipboardList,
    BadgeCheck,
    Receipt,
    LucideIcon
} from 'lucide-react';
import { SalesOrder, SalesOrderItem } from '@repo/shared';

interface StatusConfig {
    color: string;
    icon: LucideIcon;
    text: string;
}

const SalesOrderDetail = () => {
    const { id } = useParams();
    const navigate = useNavigate();
    const [order, setOrder] = useState<SalesOrder | null>(null);
    const [loading, setLoading] = useState(true);
    const [actionLoading, setActionLoading] = useState(false);

    useEffect(() => {
        fetchOrderDetails();
    }, [id]);

    const fetchOrderDetails = async () => {
        setLoading(true);
        try {
            const user = JSON.parse(localStorage.getItem('user') || '{}');
            const token = user?.token;
            const response = await api.get(
                `/api/sales-orders/${id}`,
                { headers: { Authorization: `Bearer ${token}` } }
            );
            setOrder(response.data);
        } catch (error: any) {
            logger.error('Error fetching order details:', error);
            toast.error('Failed to fetch order details');
            navigate('/sales/sales-order-list');
        } finally {
            setLoading(false);
        }
    };

    const handleCancelOrder = async () => {
        if (!confirm('Are you sure you want to cancel this order? Reserved stock will be released.')) {
            return;
        }

        setActionLoading(true);
        try {
            const user = JSON.parse(localStorage.getItem('user') || '{}');
            const token = user?.token;
            await api.post(
                `/api/sales-orders/${id}/cancel`,
                {},
                { headers: { Authorization: `Bearer ${token}` } }
            );
            toast.success('Sales Order cancelled successfully');
            fetchOrderDetails();
        } catch (error: any) {
            logger.error('Error cancelling order:', error);
            toast.error(error.response?.data?.message || 'Failed to cancel order');
        } finally {
            setActionLoading(false);
        }
    };

    const getStatusConfig = (status: string | undefined): StatusConfig => {
        const configs: Record<string, StatusConfig> = {
            'Draft': { color: 'from-slate-500 to-slate-600', icon: ClipboardList, text: 'Draft Order' },
            'Confirmed': { color: 'from-blue-500 to-blue-600', icon: BadgeCheck, text: 'Order Confirmed' },
            'Partially Delivered': { color: 'from-purple-500 to-purple-600', icon: Truck, text: 'Partially Delivered' },
            'Delivered': { color: 'from-indigo-500 to-indigo-600', icon: Package, text: 'Fully Delivered' },
            'Partially Invoiced': { color: 'from-amber-500 to-amber-600', icon: Receipt, text: 'Partially Invoiced' },
            'Invoiced': { color: 'from-emerald-500 to-emerald-600', icon: CheckCircle, text: 'Invoiced & Complete' },
            'Cancelled': { color: 'from-red-500 to-red-600', icon: XCircle, text: 'Order Cancelled' }
        };
        return (status && configs[status]) || configs['Draft'];
    };

    const getLifecycleStages = () => {
        const stages = ['Draft', 'Confirmed', 'Delivered', 'Invoiced'];
        const currentStatus = order?.status?.replace('Partially ', '') || 'Draft';
        const currentIndex = stages.indexOf(currentStatus);

        return stages.map((stage, index) => ({
            name: stage,
            completed: index < currentIndex,
            current: index === currentIndex,
            upcoming: index > currentIndex
        }));
    };

    if (loading) {
        return (
            <Layout>
                <div className="flex flex-col items-center justify-center py-20">
                    <div className="animate-spin rounded-full h-10 w-10 border-b-2 border-indigo-600 mb-4"></div>
                    <p className="text-slate-500 font-medium">Loading order details...</p>
                </div>
            </Layout>
        );
    }

    if (!order) {
        return (
            <Layout>
                <div className="flex flex-col items-center justify-center py-20">
                    <AlertTriangle className="w-12 h-12 text-amber-500 mb-4" />
                    <p className="text-slate-700 font-bold text-lg">Order not found</p>
                    <button onClick={() => navigate('/sales/sales-order-list')} className="mt-4 text-indigo-600 font-medium hover:underline">
                        Back to Orders
                    </button>
                </div>
            </Layout>
        );
    }

    const statusConfig = getStatusConfig(order.status);
    const StatusIcon = statusConfig.icon;
    const hasItemsToDeliver = order.items.some((item: SalesOrderItem) => ((item.reservedQty || 0) - (item.deliveredQty || 0)) > 0);
    const canConvertToDC = hasItemsToDeliver && (order.status === 'Confirmed' || order.status === 'Partially Delivered');
    const canCancel = order.status !== 'Cancelled' && order.status !== 'Invoiced';

    return (
        <Layout>
            <div className="space-y-6 animate-fade-in pb-10">
                {/* Immersive Status Banner */}
                <div className={`bg-gradient-to-r ${statusConfig.color} rounded-[2rem] p-8 text-white shadow-xl relative overflow-hidden`}>
                    <div className="absolute top-0 right-0 p-8 opacity-10 pointer-events-none">
                        <StatusIcon className="w-48 h-48" />
                    </div>
                    <div className="relative z-10">
                        <button
                            onClick={() => navigate('/sales/sales-order-list')}
                            className="flex items-center gap-2 text-white/80 hover:text-white text-sm font-medium mb-6 transition-colors"
                        >
                            <ArrowLeft className="w-4 h-4" /> Back to Orders
                        </button>
                        <div className="flex flex-col lg:flex-row lg:items-center lg:justify-between gap-6">
                            <div>
                                <div className="flex items-center gap-3 mb-2">
                                    <StatusIcon className="w-6 h-6" />
                                    <span className="text-white/80 text-sm font-bold uppercase tracking-widest">{statusConfig.text}</span>
                                </div>
                                <h1 className="text-4xl font-black tracking-tight mb-2">{order.orderNumber}</h1>
                                <p className="text-white/80 font-medium">
                                    {order.customer?.name} • Created {new Date(order.orderDate).toLocaleDateString()}
                                </p>
                                {order.isOverdue && (
                                    <div className="mt-3 inline-flex items-center gap-2 px-3 py-1.5 bg-white/20 rounded-xl text-sm font-bold">
                                        <Clock className="w-4 h-4" /> Delivery Overdue
                                    </div>
                                )}
                            </div>
                            <div className="flex flex-wrap gap-3">
                                <button
                                    onClick={() => window.print()}
                                    className="px-4 py-2.5 bg-white/10 backdrop-blur-md border border-white/20 text-white rounded-xl text-sm font-bold hover:bg-white/20 transition-all flex items-center gap-2"
                                >
                                    <Printer className="w-4 h-4" /> Print
                                </button>
                                {canConvertToDC && (
                                    <button
                                        onClick={() => navigate(`/sales/delivery-challan?salesOrderId=${order._id}`)}
                                        className="px-4 py-2.5 bg-white text-purple-700 rounded-xl text-sm font-bold shadow-lg hover:bg-purple-50 transition-all flex items-center gap-2"
                                    >
                                        <Truck className="w-4 h-4" /> Create Delivery Challan
                                    </button>
                                )}
                                {canCancel && (
                                    <button
                                        onClick={handleCancelOrder}
                                        disabled={actionLoading}
                                        className="px-4 py-2.5 bg-red-500/20 border border-red-300/30 text-white rounded-xl text-sm font-bold hover:bg-red-500/30 transition-all flex items-center gap-2 disabled:opacity-50"
                                    >
                                        <XCircle className="w-4 h-4" /> Cancel Order
                                    </button>
                                )}
                            </div>
                        </div>
                    </div>
                </div>

                {/* Order Lifecycle Timeline */}
                <div className="bg-white border border-slate-200 rounded-2xl shadow-sm p-6">
                    <h3 className="text-xs font-bold text-slate-500 uppercase tracking-wider mb-4">Order Lifecycle</h3>
                    <div className="flex items-center justify-between">
                        {getLifecycleStages().map((stage, index) => (
                            <div key={stage.name} className="flex items-center flex-1">
                                <div className="flex flex-col items-center">
                                    <div className={`w-10 h-10 rounded-full flex items-center justify-center text-sm font-bold transition-all ${stage.completed ? 'bg-emerald-500 text-white' :
                                        stage.current ? 'bg-indigo-600 text-white ring-4 ring-indigo-100' :
                                            'bg-slate-100 text-slate-400'
                                        }`}>
                                        {stage.completed ? <CheckCircle className="w-5 h-5" /> : index + 1}
                                    </div>
                                    <p className={`mt-2 text-xs font-bold ${stage.current ? 'text-indigo-600' : 'text-slate-500'}`}>
                                        {stage.name}
                                    </p>
                                </div>
                                {index < 3 && (
                                    <div className={`flex-1 h-1 mx-2 rounded-full ${stage.completed ? 'bg-emerald-500' : 'bg-slate-200'}`} />
                                )}
                            </div>
                        ))}
                    </div>
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                    <div className="lg:col-span-2 space-y-6">
                        {/* Order Info */}
                        <div className="bg-white border border-slate-200 rounded-2xl shadow-sm overflow-hidden">
                            <div className="bg-slate-50 px-6 py-3 border-b border-slate-100">
                                <h2 className="text-xs font-bold text-slate-500 uppercase tracking-wider">Order Information</h2>
                            </div>
                            <div className="p-6 grid grid-cols-2 md:grid-cols-4 gap-6">
                                <div>
                                    <p className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1">Order Number</p>
                                    <p className="text-sm font-bold text-slate-800">{order.orderNumber}</p>
                                </div>
                                <div>
                                    <p className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1">Order Date</p>
                                    <p className="text-sm font-medium text-slate-800">{new Date(order.orderDate).toLocaleDateString()}</p>
                                </div>
                                <div>
                                    <p className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1">Expected Delivery</p>
                                    <p className="text-sm font-medium text-slate-800">
                                        {new Date(order.expectedDeliveryDate).toLocaleDateString()}
                                    </p>
                                </div>
                                <div>
                                    <p className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1">Created By</p>
                                    <p className="text-sm font-medium text-slate-800">{order.createdBy?.name || 'N/A'}</p>
                                </div>
                            </div>
                        </div>

                        {/* Customer Info */}
                        <div className="bg-white border border-slate-200 rounded-2xl shadow-sm overflow-hidden">
                            <div className="bg-slate-50 px-6 py-3 border-b border-slate-100">
                                <h2 className="text-xs font-bold text-slate-500 uppercase tracking-wider">Customer Details</h2>
                            </div>
                            <div className="p-6 flex items-start gap-4">
                                <div className="w-14 h-14 rounded-2xl bg-gradient-to-br from-indigo-500 to-violet-600 flex items-center justify-center text-white text-xl font-black shadow-lg">
                                    {order.customer?.name?.charAt(0).toUpperCase() || '?'}
                                </div>
                                <div className="flex-1">
                                    <p className="text-lg font-bold text-slate-800">{order.customer?.name}</p>
                                    <div className="flex flex-wrap gap-4 mt-2 text-sm text-slate-600">
                                        {order.customer?.phone && (
                                            <span className="flex items-center gap-1.5">
                                                <Phone className="w-4 h-4 text-slate-400" /> {order.customer.phone}
                                            </span>
                                        )}
                                        {order.customer?.email && (
                                            <span className="flex items-center gap-1.5">
                                                <Mail className="w-4 h-4 text-slate-400" /> {order.customer.email}
                                            </span>
                                        )}
                                    </div>
                                </div>
                            </div>
                        </div>

                        {/* Items Table */}
                        <div className="bg-white border border-slate-200 rounded-2xl shadow-sm overflow-hidden">
                            <div className="bg-slate-50 px-6 py-3 border-b border-slate-100">
                                <h2 className="text-xs font-bold text-slate-500 uppercase tracking-wider">Order Items</h2>
                            </div>
                            <div className="overflow-x-auto">
                                <table className="w-full text-left">
                                    <thead className="bg-slate-50 border-b border-slate-200">
                                        <tr className="text-xs font-bold text-slate-500 uppercase tracking-wider">
                                            <th className="px-4 py-3 text-center w-12">#</th>
                                            <th className="px-4 py-3">Product</th>
                                            <th className="px-4 py-3 text-right">Qty</th>
                                            <th className="px-4 py-3 text-right">Rate</th>
                                            <th className="px-4 py-3 text-right">Tax</th>
                                            <th className="px-4 py-3 text-center">Fulfillment</th>
                                            <th className="px-4 py-3 text-right">Total</th>
                                        </tr>
                                    </thead>
                                    <tbody className="divide-y divide-slate-100">
                                        {order.items.map((item: SalesOrderItem, index: number) => {
                                            const deliveryProgress = item.quantity > 0 ? ((item.deliveredQty || 0) / item.quantity) * 100 : 0;
                                            return (
                                                <tr key={index} className="hover:bg-slate-50/80 transition-colors">
                                                    <td className="px-4 py-3 text-center text-xs text-slate-400 font-bold">{index + 1}</td>
                                                    <td className="px-4 py-3">
                                                        <p className="font-semibold text-slate-800">{item.item?.name || item.name}</p>
                                                    </td>
                                                    <td className="px-4 py-3 text-right font-medium">{item.quantity}</td>
                                                    <td className="px-4 py-3 text-right font-medium">₹{item.rate}</td>
                                                    <td className="px-4 py-3 text-right text-slate-600">{item.tax}%</td>
                                                    <td className="px-4 py-3">
                                                        <div className="flex flex-col items-center gap-1">
                                                            <div className="w-24 h-2 bg-slate-100 rounded-full overflow-hidden">
                                                                <div
                                                                    className="h-full bg-emerald-500 rounded-full transition-all"
                                                                    style={{ width: `${deliveryProgress}%` }}
                                                                />
                                                            </div>
                                                            <span className="text-[10px] font-bold text-slate-500">
                                                                {item.deliveredQty || 0}/{item.quantity} delivered
                                                            </span>
                                                        </div>
                                                    </td>
                                                    <td className="px-4 py-3 text-right font-bold text-slate-800">₹{item.total?.toFixed(2) || '0.00'}</td>
                                                </tr>
                                            );
                                        })}
                                    </tbody>
                                </table>
                            </div>
                        </div>

                        {/* Notes */}
                        {order.notes && (
                            <div className="bg-white border border-slate-200 rounded-2xl shadow-sm overflow-hidden">
                                <div className="bg-slate-50 px-6 py-3 border-b border-slate-100">
                                    <h2 className="text-xs font-bold text-slate-500 uppercase tracking-wider">Notes</h2>
                                </div>
                                <div className="p-6">
                                    <p className="text-sm text-slate-600">{order.notes}</p>
                                </div>
                            </div>
                        )}
                    </div>

                    {/* Sidebar */}
                    <div className="lg:col-span-1 space-y-6">
                        {/* Order Summary */}
                        <div className="bg-white border border-indigo-100 rounded-2xl shadow-sm overflow-hidden sticky top-4">
                            <div className="bg-indigo-50/50 px-6 py-3 border-b border-indigo-100">
                                <h2 className="text-xs font-bold text-indigo-800 uppercase tracking-wider">Order Summary</h2>
                            </div>
                            <div className="p-6 space-y-4">
                                <div className="flex justify-between text-sm">
                                    <span className="text-slate-500 font-medium">Subtotal</span>
                                    <span className="font-bold text-slate-800">₹{order.subtotal?.toFixed(2) || '0.00'}</span>
                                </div>
                                <div className="flex justify-between text-sm">
                                    <span className="text-slate-500 font-medium">Tax</span>
                                    <span className="font-bold text-slate-800">₹{order.taxTotal?.toFixed(2) || '0.00'}</span>
                                </div>
                                <div className="flex justify-between text-sm">
                                    <span className="text-slate-500 font-medium">Discount</span>
                                    <span className="font-bold text-rose-600">-₹{order.discountTotal?.toFixed(2) || '0.00'}</span>
                                </div>
                            </div>
                            <div className="bg-slate-800 px-6 py-5 flex justify-between items-center text-white">
                                <span className="text-lg font-bold tracking-tight">Net Total</span>
                                <span className="text-2xl font-bold tracking-tight">₹{order.totalAmount?.toFixed(2) || '0.00'}</span>
                            </div>
                        </div>

                        {/* Conversion History */}
                        {((order.deliveryChallans && order.deliveryChallans.length > 0) || (order.invoices && order.invoices.length > 0)) && (
                            <div className="bg-white border border-slate-200 rounded-2xl shadow-sm overflow-hidden">
                                <div className="bg-slate-50 px-6 py-3 border-b border-slate-100">
                                    <h2 className="text-xs font-bold text-slate-500 uppercase tracking-wider">Linked Documents</h2>
                                </div>
                                <div className="p-6 space-y-4">
                                    {order.deliveryChallans && order.deliveryChallans.length > 0 && (
                                        <div>
                                            <p className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-2">Delivery Challans</p>
                                            <div className="space-y-2">
                                                {order.deliveryChallans.map((dc: any, index: number) => (
                                                    <div key={index} className="flex items-center gap-2 p-2 bg-purple-50 rounded-lg">
                                                        <Truck className="w-4 h-4 text-purple-600" />
                                                        <span className="text-sm font-medium text-purple-800">{dc.challanNumber || `DC #${index + 1}`}</span>
                                                    </div>
                                                ))}
                                            </div>
                                        </div>
                                    )}
                                    {order.invoices && order.invoices.length > 0 && (
                                        <div>
                                            <p className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-2">Invoices</p>
                                            <div className="space-y-2">
                                                {order.invoices.map((inv: any, index: number) => (
                                                    <div key={index} className="flex items-center gap-2 p-2 bg-emerald-50 rounded-lg">
                                                        <FileText className="w-4 h-4 text-emerald-600" />
                                                        <span className="text-sm font-medium text-emerald-800">{inv.invoiceNo || `Invoice #${index + 1}`}</span>
                                                    </div>
                                                ))}
                                            </div>
                                        </div>
                                    )}
                                </div>
                            </div>
                        )}
                    </div>
                </div>
            </div>
        </Layout>
    );
};

export default SalesOrderDetail;

import { logger } from '@/shared/lib/logger';
import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import api from '@/shared/api/api';
import { toast } from 'react-toastify';
import Layout from '@/shared/ui/Layout/Layout';
import { SalesOrder } from '@repo/shared';

const SalesOrderList = () => {
    const navigate = useNavigate();
    const [orders, setOrders] = useState<SalesOrder[]>([]);
    const [loading, setLoading] = useState(true);
    const [filters, setFilters] = useState({
        status: '',
        search: '',
        overdue: false
    });

    const isOverdue = (order: SalesOrder) => {
        if (!order.expectedDeliveryDate) return false;
        return new Date(order.expectedDeliveryDate) < new Date() && order.status !== 'Delivered' && order.status !== 'Invoiced' && order.status !== 'Cancelled';
    };

    useEffect(() => {
        fetchOrders();
    }, [filters]);

    const fetchOrders = async () => {
        setLoading(true);
        try {
            const user = JSON.parse(localStorage.getItem('user') || '{}');
            const token = user?.token;
            const params = new URLSearchParams();
            if (filters.status) params.append('status', filters.status);
            if (filters.overdue) params.append('overdue', 'true');

            const response = await api.get(
                `/api/sales-orders?${params.toString()}`,
                { headers: { Authorization: `Bearer ${token}` } }
            );

            let fetchedOrders = response.data;

            // Apply search filter on frontend
            if (filters.search) {
                const searchLower = filters.search.toLowerCase();
                fetchedOrders = fetchedOrders.filter((order: SalesOrder) =>
                    order.orderNumber.toLowerCase().includes(searchLower) ||
                    order.customer?.name.toLowerCase().includes(searchLower)
                );
            }

            setOrders(fetchedOrders);
        } catch (error: any) {
            logger.error('Error fetching orders:', error);
            toast.error('Failed to fetch sales orders');
        } finally {
            setLoading(false);
        }
    };

    const getStatusColor = (status: string) => {
        switch (status) {
            case 'Delivered':
            case 'Invoiced':
                return 'bg-emerald-100 text-emerald-800 border border-emerald-200';
            case 'Confirmed':
                return 'bg-blue-100 text-blue-800 border border-blue-200';
            case 'Partially Delivered':
            case 'Partially Invoiced':
                return 'bg-amber-100 text-amber-800 border border-amber-200';
            case 'Cancelled':
                return 'bg-red-100 text-red-800 border border-red-200';
            default: // Draft
                return 'bg-slate-100 text-slate-800 border border-slate-200';
        }
    };

    // Calculate Dashboard Metrics
    const totalOrders = orders.length;
    const totalRevenue = orders.reduce((sum, o) => sum + (o.totalAmount || 0), 0);
    const confirmedOrders = orders.filter((o) => ['Confirmed', 'Partially Delivered', 'Delivered'].includes(o.status)).length;
    const overdueOrders = orders.filter((o) => isOverdue(o)).length;

    return (
        <Layout>
            <div className="space-y-6 animate-fade-in pb-10">
                {/* Header Section */}
                <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                    <div>
                        <h1 className="text-2xl font-bold text-slate-800 tracking-tight">Sales Orders</h1>
                        <p className="text-sm text-slate-500 mt-1">Manage, track, and fulfill customer orders</p>
                    </div>
                    <div className="flex gap-3">
                        <button
                            onClick={() => window.print()}
                            className="p-2 bg-white border border-slate-300 rounded-lg text-slate-600 hover:bg-slate-50 shadow-sm transition-all"
                            title="Print List"
                        >
                            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z" />
                            </svg>
                        </button>
                        <button
                            onClick={() => navigate('/sales/sales-order')}
                            className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 shadow-sm transition-all font-medium"
                        >
                            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" />
                            </svg>
                            <span>Create Order</span>
                        </button>
                    </div>
                </div>

                {/* Dashboard / Metrics Grid */}
                <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                    <div className="bg-white p-5 rounded-xl shadow-sm border border-slate-100 flex flex-col justify-between hover:shadow-md transition-shadow">
                        <div className="flex justify-between items-start">
                            <div>
                                <p className="text-xs font-bold text-slate-400 uppercase tracking-wider">Total Revenue</p>
                                <h3 className="text-2xl font-bold text-slate-800 mt-1">₹{totalRevenue.toLocaleString()}</h3>
                            </div>
                            <div className="p-2 bg-emerald-50 rounded-lg text-emerald-600">
                                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                                </svg>
                            </div>
                        </div>
                        <div className="mt-4 flex items-center text-xs text-emerald-600 font-medium">
                            <span className="flex items-center">
                                <svg className="w-3 h-3 mr-1" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 7h8m0 0v8m0-8l-8 8-4-4-6 6" /></svg>
                                +12% from last month
                            </span>
                        </div>
                    </div>

                    <div className="bg-white p-5 rounded-xl shadow-sm border border-slate-100 flex flex-col justify-between hover:shadow-md transition-shadow">
                        <div className="flex justify-between items-start">
                            <div>
                                <p className="text-xs font-bold text-slate-400 uppercase tracking-wider">Total Orders</p>
                                <h3 className="text-2xl font-bold text-slate-800 mt-1">{totalOrders}</h3>
                            </div>
                            <div className="p-2 bg-indigo-50 rounded-lg text-indigo-600">
                                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
