import React, { useState, useEffect } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { useNavigate } from 'react-router-dom';
import { updateProfile, resetAuthState } from "@/entities/session/model/authSlice";
import Layout from "@/shared/ui/Layout/Layout";
import { toast } from 'react-toastify';
import { RootState, AppDispatch } from "@/app/store/store";

interface FormData {
    name: string;
    email: string;
    phone: string;
    shopName: string;
    gstNumber: string;
    shopAddress: string;
}

interface FormErrors {
    name?: string;
    email?: string;
    phone?: string;
}

const ProfileSettings: React.FC = () => {
    const navigate = useNavigate();
    const dispatch = useDispatch<AppDispatch>();
    const { user, isLoading, isSuccess, isError, message } = useSelector(
        (state: RootState) => state.auth
    );

    const [formData, setFormData] = useState<FormData>({
        name: '',
        email: '',
        phone: '',
        shopName: '',
        gstNumber: '',
        shopAddress: '',
    });

    const [errors, setErrors] = useState<FormErrors>({});
    const [showSuccess, setShowSuccess] = useState(false);

    const { name, email, phone, shopName, gstNumber, shopAddress } = formData;

    // Initialize form with user data
    useEffect(() => {
        if (user) {
            setFormData({
                name: user.name || '',
                email: user.email || '',
                phone: user.phone || '',
                shopName: user.shopName || '',
                gstNumber: user.gstNumber || '',
                shopAddress: user.shopAddress || '',
            });
        }
    }, [user]);

    // Handle success and error states
    useEffect(() => {
        if (isSuccess) {
            setShowSuccess(true);
            toast.success('Profile updated successfully!');
            const timer = setTimeout(() => {
                setShowSuccess(false);
                dispatch(resetAuthState());
            }, 3000);
            return () => clearTimeout(timer);
        }
    }, [isSuccess, dispatch]);

    useEffect(() => {
        if (isError && message) {
            toast.error(message);
            dispatch(resetAuthState());
        }
    }, [isError, message, dispatch]);

    // Validate form
    const validateForm = () => {
        const newErrors: FormErrors = {};

        if (!name || name.trim().length === 0) {
            newErrors.name = 'Name is required';
        } else if (name.trim().length < 2) {
            newErrors.name = 'Name must be at least 2 characters';
        }

        if (!email || email.trim().length === 0) {
            newErrors.email = 'Email is required';
        } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
            newErrors.email = 'Invalid email format';
        }

        if (phone && phone.length < 10) {
            newErrors.phone = 'Phone number must be at least 10 digits';
        }

        setErrors(newErrors);
        return Object.keys(newErrors).length === 0;
    };

    const onChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
        const { name, value } = e.target;
        setFormData((prevState) => ({
            ...prevState,
            [name]: value,
        }));
        // Clear error for this field when user starts typing
        if (errors[name as keyof FormErrors]) {
            setErrors((prevErrors) => ({
                ...prevErrors,
                [name]: '',
            }));
        }
    };

    const onSubmit = async (e: React.FormEvent) => {
        e.preventDefault();

        if (!validateForm()) {
            return;
        }

        await dispatch(updateProfile(formData));
    };

    if (!user) {
        return (
            <Layout>
                <div className="flex justify-center items-center h-64">
                    <div className="text-center">
                        <p className="text-secondary">Loading profile...</p>
                    </div>
                </div>
            </Layout>
        );
    }

    return (
        <Layout>
            <div className="max-w-3xl mx-auto">
                {/* Header */}
                <div className="mb-8">
                    <button
                        onClick={() => navigate('/dashboard')}
                        className="flex items-center text-secondary hover:text-main mb-4"
                    >
                        <svg
                            className="w-5 h-5 mr-2"
                            fill="none"
                            stroke="currentColor"
                            viewBox="0 0 24 24"
                        >
                            <path
                                strokeLinecap="round"
                                strokeLinejoin="round"
                                strokeWidth={2}
                                d="M15 19l-7-7 7-7"
                            />
                        </svg>
                        Back to Dashboard
                    </button>
                    <h1 className="text-3xl font-bold text-main mb-2">Profile Settings</h1>
                    <p className="text-secondary">Update your personal and business information</p>
                </div>

                {/* Success Message */}
                {showSuccess && (
                    <div className="mb-6 p-4 bg-green-50 border border-green-200 rounded-lg">
                        <div className="flex items-center">
                            <svg
                                className="w-5 h-5 text-green-600 mr-3"
                                fill="none"
                                stroke="currentColor"
                                viewBox="0 0 24 24"
                            >
                                <path
                                    strokeLinecap="round"
                                    strokeLinejoin="round"
                                    strokeWidth={2}
                                    d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z"
                                />
                            </svg>
                            <p className="text-green-600 font-medium">Profile updated successfully!</p>
                        </div>
                    </div>
                )}

                {/* Form Card */}
                <div className="bg-card rounded-xl shadow-sm p-8">
                    <form onSubmit={onSubmit} className="space-y-6">
                        {/* Full Name Input */}
                        <div>
                            <label
                                htmlFor="name"
                                className="block text-sm font-medium text-secondary mb-2"
                            >
                                Full Name <span className="text-red-500">*</span>
                            </label>
                            <input
                                type="text"
                                id="name"
                                name="name"
                                value={name}
                                onChange={onChange}
                                className={`w-full px-4 py-3 border rounded-lg focus:ring-2 focus:ring-primaryfocus:border-transparent transition ${errors.name
                                    ? 'border-red-500 bg-red-50'
                                    : ' border-default'
                                    }`}
                                placeholder="Enter your full name"
                            />
                            {errors.name && (
                                <p className="mt-1 text-sm text-red-600">{errors.name}</p>
                            )}
                        </div>

                        {/* Email Input */}
                        <div>
                            <label
                                htmlFor="email"
                                className="block text-sm font-medium text-secondary mb-2"
                            >
                                Email Address <span className="text-red-500">*</span>
                            </label>
                            <input
                                type="email"
                                id="email"
                                name="email"
                                value={email}
                                onChange={onChange}
                                className={`w-full px-4 py-3 border rounded-lg focus:ring-2 focus:ring-primaryfocus:border-transparent transition ${errors.email
                                    ? 'border-red-500 bg-red-50'
                                    : ' border-default'
                                    }`}
                                placeholder="Enter your email address"
                            />
                            {errors.email && (
                                <p className="mt-1 text-sm text-red-600">{errors.email}</p>
                            )}
                        </div>

                        {/* Phone Input */}
                        <div>
                            <label
                                htmlFor="phone"
                                className="block text-sm font-medium text-secondary mb-2"
                            >
                                Phone Number
                            </label>
                            <input
                                type="tel"
                                id="phone"
                                name="phone"
                                value={phone}
                                onChange={onChange}
                                className={`w-full px-4 py-3 border rounded-lg focus:ring-2 focus:ring-primaryfocus:border-transparent transition ${errors.phone
                                    ? 'border-red-500 bg-red-50'
                                    : ' border-default'
                                    }`}
                                placeholder="Enter your phone number"
                            />
                            {errors.phone && (
                                <p className="mt-1 text-sm text-red-600">{errors.phone}</p>
                            )}
                        </div>

                        {/* Shop Name Input */}
                        <div>
                            <label
                                htmlFor="shopName"
                                className="block text-sm font-medium text-secondary mb-2"
                            >
                                Shop Name
                            </label>
                            <input
                                type="text"
                                id="shopName"
                                name="shopName"
                                value={shopName}
                                onChange={onChange}
                                className="w-full px-4 py-3 border  border-default rounded-lg focus:ring-2 focus:ring-primaryfocus:border-transparent transition"
                                placeholder="Enter your shop/business name"
                            />
                        </div>

                        {/* GST Number Input */}
                        <div>
                            <label
                                htmlFor="gstNumber"
                                className="block text-sm font-medium text-secondary mb-2"
                            >
                                GST Number (GSTIN)
                            </label>
                            <input
                                type="text"
                                id="gstNumber"
                                name="gstNumber"
                                value={gstNumber}
                                onChange={onChange}
                                className="w-full px-4 py-3 border border-default rounded-lg focus:ring-2 focus:ring-primaryfocus:border-transparent transition"
                                placeholder="e.g., 27AABCU9603R1ZM"
                            />
                        </div>

                        {/* Shop Address Input */}
                        <div>
                            <label
                                htmlFor="shopAddress"
                                className="block text-sm font-medium text-secondary mb-2"
                            >
                                Shop Address
                            </label>
                            <textarea
                                id="shopAddress"
                                name="shopAddress"
                                value={shopAddress}
                                onChange={onChange}
                                rows={3}
                                className="w-full px-4 py-3 border border-default rounded-lg focus:ring-2 focus:ring-primaryfocus:border-transparent transition resize-none"
                                placeholder="Enter complete shop address (Street, City, State, PIN Code)"
                            />
                        </div>

                        {/* Additional Info Section */}
                        <div className="pt-4 border-t  border-default">
                            <h3 className="text-sm font-medium text-main mb-4">Account Information</h3>
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                <div className=" bg-surface p-4 rounded-lg">
                                    <p className="text-xs font-medium text-muted mb-1">User ID</p>
                                    <p className="text-sm text-main break-all">{user._id}</p>
                                </div>
                                <div className=" bg-surface p-4 rounded-lg">
                                    <p className="text-xs font-medium text-muted mb-1">Role</p>
                                    <p className="text-sm text-main capitalize">{user.role || 'Owner'}</p>
                                </div>
                            </div>
                        </div>

                        {/* Form Actions */}
                        <div className="flex space-x-4 pt-4">
                            <button
                                type="button"
                                onClick={() => {
                                    setFormData({
                                        name: user.name || '',
                                        email: user.email || '',
                                        phone: user.phone || '',
                                        shopName: user.shopName || '',
                                        gstNumber: user.gstNumber || '',
                                        shopAddress: user.shopAddress || '',
                                    });
                                    setErrors({});
                                }}
                                className="flex-1 px-6 py-3 border  border-default text-secondary rounded-lg hover: bg-surface font-medium transition"
                            >
                                Reset
                            </button>
                            <button
                                type="submit"
                                disabled={isLoading}
                                className="flex-1 px-6 py-3 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 font-medium transition disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center"
                            >
                                {isLoading ? (
                                    <>
                                        <svg
                                            className="animate-spin h-5 w-5 mr-2"
                                            viewBox="0 0 24 24"
                                        >
                                            <circle
                                                className="opacity-25"
                                                cx="12"
                                                cy="12"
                                                r="10"
                                                stroke="currentColor"
                                                strokeWidth="4"
                                                fill="none"
                                            />
                                            <path
                                                className="opacity-75"
                                                fill="currentColor"
                                                d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"
                                            />
                                        </svg>
                                        Saving Changes...
                                    </>
                                ) : (
                                    'Save Changes'
                                )}
                            </button>
                        </div>
                    </form>
                </div>

                {/* Help Section */}
                <div className="mt-8 bg-blue-50 border border-blue-200 rounded-xl p-6">
                    <div className="flex">
                        <div className="flex-shrink-0">
                            <svg
                                className="h-5 w-5 text-blue-600"
                                fill="none"
                                stroke="currentColor"
                                viewBox="0 0 24 24"
                            >
                                <path
                                    strokeLinecap="round"
                                    strokeLinejoin="round"
                                    strokeWidth={2}
                                    d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"
                                />
                            </svg>
                        </div>
                        <div className="ml-3">
                            <p className="text-sm text-blue-700">
                                Keep your profile information up to date to ensure accurate records and effective communication.
                            </p>
                        </div>
                    </div>
                </div>
            </div>
        </Layout>
    );
};

export default ProfileSettings;

import { logger } from '@/shared/lib/logger';
import React, { useMemo, useState, useTransition, useCallback, useActionState } from 'react';
import { Shield, Lock, CheckCircle, Loader2, AlertTriangle, Key, Users, ChevronRight, Zap, Activity, ShieldCheck, ShieldAlert } from 'lucide-react';
import { useSelector, useDispatch } from 'react-redux';
import { updateEmployee } from "@/entities/people/model/laborSlice";
import { SecurityTabProps } from './types';
import { RootState, AppDispatch } from "@/app/store/store";
import { Role } from "@/entities/session/model/core";
import { AppView, SystemRole } from "@repo/shared";
import ChangePasswordModal from '@/shared/ui/Auth/ChangePasswordModal';

const isSecuredIdeally = () => true;
const securePassword = (p: string) => p;

const PERMISSION_VIEWS: { id: AppView; label: string; category: string }[] = [
    { id: 'DASHBOARD', label: 'Main Dashboard', category: 'General' },
    { id: 'PROFIT_PULSE', label: 'Profit Pulse AI', category: 'Intelligence' },
    { id: 'POS', label: 'Point of Sale', category: 'Sales' },
    { id: 'INVENTORY', label: 'Live Inventory', category: 'Assets' },
    { id: 'PURCHASE', label: 'Purchases', category: 'Assets' },
    { id: 'FINANCE', label: 'Finance & P&L', category: 'Finance' },
    { id: 'SALES', label: 'Sales History', category: 'Sales' },
    { id: 'LABOR', label: 'Labor Mgmt', category: 'General' },
    { id: 'SETTINGS', label: 'System Settings', category: 'System' },
    { id: 'VENDORS', label: 'Suppliers Mgmt', category: 'Vendors' },
];

/* ─── Animated Security Gauge ──────────────────────────────── */
const SecurityGauge: React.FC<{ score: number }> = ({ score }) => {
    const circumference = 2 * Math.PI * 56; // radius = 56
    const offset = circumference - (score / 100) * circumference;
    const color = score > 70 ? '#10b981' : score > 40 ? '#f59e0b' : '#ef4444';
    const bgColor = score > 70 ? 'from-emerald-500/10 to-emerald-500/5' : score > 40 ? 'from-amber-500/10 to-amber-500/5' : 'from-red-500/10 to-red-500/5';

    return (
        <div className={`relative w-40 h-40 mx-auto bg-gradient-to-b ${bgColor} rounded-full p-2`}>
            <svg className="w-full h-full -rotate-90" viewBox="0 0 120 120">
                {/* Background ring */}
                <circle cx="60" cy="60" r="56" fill="none" stroke="currentColor" strokeWidth="6" className="text-slate-100 dark:text-slate-800" />
                {/* Animated progress ring */}
                <circle
                    cx="60" cy="60" r="56" fill="none"
                    stroke={color} strokeWidth="6" strokeLinecap="round"
                    strokeDasharray={circumference} strokeDashoffset={offset}
                    className="transition-all duration-1000 ease-out"
                    style={{ filter: `drop-shadow(0 0 6px ${color}40)` }}
                />
            </svg>
            <div className="absolute inset-0 flex flex-col items-center justify-center">
                <span className="text-3xl font-black" style={{ color }}>{score}</span>
                <span className="text-[9px] font-black uppercase tracking-widest text-slate-400 mt-0.5">/ 100</span>
            </div>
            {/* Pulse */}
            <div
                className="absolute inset-0 rounded-full animate-ping opacity-10"
                style={{ backgroundColor: color, animationDuration: '3s' }}
            />
        </div>
    );
};

/* ─── Security Metric Card ─────────────────────────────────── */
const SecurityMetric: React.FC<{
    icon: React.ElementType; label: string; value: string; status: 'good' | 'warn' | 'danger'; detail: string;
}> = ({ icon: Icon, label, value, status, detail }) => {
    const colors = {
        good: { bg: 'bg-emerald-50 dark:bg-emerald-900/10', border: 'border-emerald-200 dark:border-emerald-800', text: 'text-emerald-600 dark:text-emerald-400', iconBg: 'bg-emerald-100 dark:bg-emerald-900/30' },
        warn: { bg: 'bg-amber-50 dark:bg-amber-900/10', border: 'border-amber-200 dark:border-amber-800', text: 'text-amber-600 dark:text-amber-400', iconBg: 'bg-amber-100 dark:bg-amber-900/30' },
        danger: { bg: 'bg-red-50 dark:bg-red-900/10', border: 'border-red-200 dark:border-red-800', text: 'text-red-600 dark:text-red-400', iconBg: 'bg-red-100 dark:bg-red-900/30' },
    };
    const c = colors[status];

    return (
        <div className={`${c.bg} ${c.border} border rounded-3xl p-6 transition-all hover:shadow-md`}>
            <div className="flex items-start justify-between mb-4">
                <div className={`w-12 h-12 ${c.iconBg} rounded-2xl flex items-center justify-center`}>
                    <Icon className={`w-6 h-6 ${c.text}`} />
                </div>
                <span className={`text-[10px] font-black px-3 py-1.5 ${c.bg} ${c.text} rounded-lg uppercase tracking-widest border ${c.border}`}>
                    {status.toUpperCase()}
                </span>
            </div>
            <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">{label}</h4>
            <p className="text-xl font-black text-slate-800 dark:text-white mb-2">{value}</p>
            <p className="text-[10px] text-slate-500 font-medium leading-relaxed">{detail}</p>
        </div>
    );
};

const SecurityTab: React.FC<SecurityTabProps> = ({ roles = [], permissions = {}, handlePermissionToggle }) => {
    const dispatch = useDispatch<AppDispatch>();
    const { employees } = useSelector((state: RootState) => state.labor || { employees: [] });
    const { user } = useSelector((state: RootState) => state.auth);
    const [isPasswordModalOpen, setIsPasswordModalOpen] = useState(false);

    const securityScore = useMemo(() => {
        if (!user) return 0;
        let score = 0;
        score += 30; // Base score for being authenticated
        if (user.is2faEnabled) score += 40;
        score += 24; // Placeholder for additional checks (password strength, etc.)
        return Math.min(score, 100);
    }, [user]);

    const staffStatus = useMemo(() => {
        const total = employees?.length || 0;
        const secured = employees?.filter((e: any) => e.is2faEnabled).length || 0;
        return { total, secured, percent: total > 0 ? Math.round((secured / total) * 100) : 100 };
    }, [employees]);

    const insecureUsers = useMemo(() => {
        return (employees || []).filter((e: any) => e.pin && !isSecuredIdeally());
    }, [employees]);

    /* ─── React 19 useActionState for Migration ───────────────── */
    const [migrationState, migrationAction, isMigrating] = useActionState(
        async (prev: { done: number; total: number; success: boolean }, formData: FormData) => {
            const toMigrate = insecureUsers;
            let successCount = 0;
            for (const usr of toMigrate) {
                try {
                    const secured = await securePassword(usr.pin || "");
                    await dispatch(updateEmployee({
                        id: usr.id || usr._id || "",
                        data: {
                            pin: secured,
                            tenantId: usr.tenantId
                        }
                    })).unwrap();
                    successCount++;
                } catch (err) { logger.error(err); }
            }
            return { done: successCount, total: toMigrate.length, success: true };
        },
        { done: 0, total: 0, success: false }
    );

    return (
        <div className="p-6 space-y-10 animate-in fade-in slide-in-from-bottom-4 duration-500">
            {/* Security Dashboard Header */}
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                {/* Gauge */}
                <div className="bg-white dark:bg-slate-900 p-8 rounded-3xl border border-slate-200 dark:border-slate-800 shadow-sm flex flex-col items-center justify-center">
                    <SecurityGauge score={securityScore} />
                    <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mt-4 mb-1">Enterprise Security Score</h3>
                    <p className="text-lg font-black text-slate-800 dark:text-white">
                        {securityScore > 70 ? 'Industry Standard' : 'Enhancement Recommended'}
                    </p>
                </div>

                {/* Quick Metrics */}
                <div className="lg:col-span-2 grid grid-cols-1 md:grid-cols-2 gap-4">
                    <SecurityMetric
                        icon={ShieldCheck}
                        label="Authentication Level"
                        value={user?.is2faEnabled ? '2FA Active' : 'Password Only'}
                        status={user?.is2faEnabled ? 'good' : 'warn'}
                        detail={user?.is2faEnabled ? 'Multi-factor authentication is enabled for your account.' : 'Enable 2FA for enhanced account protection.'}
                    />
                    <SecurityMetric
                        icon={Users}
                        label="Staff Access Security"
                        value={`${staffStatus.secured} / ${staffStatus.total} Protected`}
                        status={staffStatus.percent === 100 ? 'good' : staffStatus.percent > 50 ? 'warn' : 'danger'}
                        detail={`${staffStatus.percent}% of staff accounts have 2FA enrollment.`}
                    />
                    <SecurityMetric
                        icon={Key}
                        label="Encryption Standard"
                        value={insecureUsers.length === 0 ? 'BCRYPT-256' : 'Mixed'}
                        status={insecureUsers.length === 0 ? 'good' : 'danger'}
                        detail={insecureUsers.length === 0 ? 'All credentials use modern hashing.' : `${insecureUsers.length} legacy credentials detected.`}
                    />
                    <SecurityMetric
                        icon={Activity}
                        label="Session Policy"
                        value="Active"
                        status="good"
                        detail="Idle sessions auto-terminate after 30 minutes."
                    />
                </div>
            </div>

            {/* Account Safeguards */}
            <div className="bg-white dark:bg-slate-900 rounded-[2.5rem] border border-slate-200 dark:border-slate-800 overflow-hidden shadow-sm">
                <div className="p-8 border-b border-slate-100 dark:border-slate-800 bg-slate-50/50 dark:bg-slate-900/50 flex flex-col md:flex-row md:justify-between md:items-center gap-4">
                    <div className="flex items-center gap-4">
                        <div className="w-12 h-12 bg-white dark:bg-slate-800 rounded-2xl shadow-sm border border-slate-100 dark:border-slate-700 flex items-center justify-center">
                            <Lock className="w-6 h-6 text-slate-400" />
                        </div>
                        <div>
                            <h3 className="text-lg font-black text-slate-800 dark:text-white">Account Safeguards</h3>
                            <p className="text-xs text-slate-500 font-bold mt-1">Manage your personal security credentials</p>
                        </div>
                    </div>
                    <button
                        onClick={() => setIsPasswordModalOpen(true)}
                        className="px-8 py-4 bg-slate-900 dark:bg-white text-white dark:text-slate-900 border border-transparent dark:border-slate-200 text-xs font-black uppercase tracking-widest rounded-2xl hover:opacity-90 transition-all active:scale-95 shadow-xl shadow-slate-200 dark:shadow-none"
                    >
                        Change Access Key
                    </button>
                </div>
            </div>

            {/* Password Security Section */}
            <section>
                <div className="flex items-center gap-3 mb-8">
                    <div className="w-10 h-10 rounded-xl bg-amber-50 dark:bg-amber-900/20 flex items-center justify-center">
                        <Key className="w-5 h-5 text-amber-600 dark:text-amber-400" />
                    </div>
                    <div>
                        <h3 className="text-lg font-bold text-slate-800 dark:text-white leading-none">Password Governance</h3>
                        <p className="text-xs text-slate-500 font-medium mt-1">Manage encryption and data security protocols</p>
                    </div>
                </div>

                {insecureUsers.length === 0 ? (
                    <div className="p-8 bg-emerald-50/30 dark:bg-emerald-900/10 border border-emerald-100 dark:border-emerald-800 rounded-3xl flex flex-col md:flex-row items-center gap-8">
                        <div className="w-20 h-20 rounded-2xl bg-emerald-500 text-white flex items-center justify-center shadow-xl shadow-emerald-200 dark:shadow-none shrink-0">
                            <CheckCircle className="w-10 h-10" />
                        </div>
                        <div className="text-center md:text-left">
                            <h4 className="text-xl font-black text-slate-800 dark:text-white leading-none mb-2">Maximum Security Active</h4>
                            <p className="text-sm text-slate-500 font-medium leading-relaxed max-w-xl">
                                All identified enterprise user credentials are currently using high-level hashing algorithms (BCRYPT-256). No manual intervention is required at this stage.
                            </p>
                        </div>
                        <div className="px-6 py-2 bg-white dark:bg-slate-800 rounded-2xl border border-slate-100 dark:border-slate-700 text-[10px] font-black tracking-widest text-emerald-600 uppercase">
                            ENCRYPTED
                        </div>
                    </div>
                ) : (
                    <div className="p-8 bg-amber-50/50 dark:bg-amber-900/10 border border-amber-200 dark:border-amber-800 rounded-3xl flex flex-col md:flex-row items-center gap-8 shadow-sm">
                        <div className="w-20 h-20 rounded-2xl bg-amber-500 text-white flex items-center justify-center shadow-xl shadow-amber-200 dark:shadow-none shrink-0 border-4 border-white dark:border-slate-800">
                            <AlertTriangle className="w-10 h-10" />
                        </div>
                        <div className="flex-1 text-center md:text-left">
                            <p className="text-[10px] font-black text-amber-600 uppercase tracking-widest mb-1">IMMEDIATE ACTION REQUIRED</p>
                            <h4 className="text-xl font-black text-slate-800 dark:text-white leading-none mb-2">Legacy Credentials Detected</h4>
                            <p className="text-sm text-slate-500 font-medium leading-relaxed max-w-xl">
                                Found {insecureUsers.length} active sessions using legacy plaintext or weak hashing. Migrating them will enforce modern security standards without affecting user login flows.
                            </p>
                            {migrationState.success && (
                                <p className="text-sm font-bold text-emerald-600 mt-2">
                                    ✓ Migration complete — {migrationState.done}/{migrationState.total} secured.
                                </p>
                            )}
                        </div>
                        <form action={migrationAction}>
                            <button
                                type="submit"
                                disabled={isMigrating}
                                className="bg-slate-900 dark:bg-indigo-600 hover:scale-105 text-white px-8 py-4 rounded-2xl text-xs font-black tracking-widest transition-all shadow-xl active:scale-95 disabled:opacity-50 flex items-center gap-3"
                            >
                                {isMigrating ? <Loader2 className="w-4 h-4 animate-spin" /> : <Lock className="w-4 h-4" />}
                                {isMigrating ? 'SECURING...' : 'MIGRATE ALL SECURELY'}
                            </button>
                        </form>
                    </div>
                )}
            </section>

            {/* Role Permissions Section */}
            <section>
                <div className="flex items-center justify-between mb-8">
                    <div className="flex items-center gap-3">
                        <div className="w-10 h-10 rounded-xl bg-blue-50 dark:bg-blue-900/20 flex items-center justify-center">
                            <Users className="w-5 h-5 text-blue-600 dark:text-blue-400" />
                        </div>
                        <div>
                            <h3 className="text-lg font-bold text-slate-800 dark:text-white leading-none">Enterprise Roles & ACL</h3>
                            <p className="text-xs text-slate-500 font-medium mt-1">Configure access control levels for each staff role</p>
                        </div>
                    </div>
                    <button className="text-[10px] font-black text-indigo-600 dark:text-indigo-400 flex items-center gap-1 hover:gap-2 transition-all">
                        ADVANCED ACL MAP <ChevronRight className="w-3 h-3" />
                    </button>
                </div>

                <div className="space-y-6">
                    {roles.filter((r: any) => r.code !== SystemRole.OWNER).map((role: any) => (
                        <div key={role.id} className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-3xl p-6 shadow-sm">
                            <div className="flex items-center gap-4 mb-8">
                                <div className="w-12 h-12 rounded-2xl bg-slate-50 dark:bg-slate-800 flex items-center justify-center border border-slate-100 dark:border-slate-700">
                                    <Users className="w-6 h-6 text-slate-400" />
                                </div>
                                <div>
                                    <h4 className="text-base font-black text-slate-800 dark:text-white leading-none uppercase tracking-wider">{role.description || role.code}</h4>
                                    <p className="text-[10px] text-slate-400 font-bold mt-1">ACCESS LEVEL: {role.code === 'admin' ? 'FULL' : 'GRADED'}</p>
                                </div>
                            </div>

                            <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-5 gap-3">
                                {PERMISSION_VIEWS.map(view => {
                                    const isAllowed = (permissions[role.code] || []).includes(view.id);
                                    return (
                                        <button
                                            key={view.id}
                                            onClick={() => handlePermissionToggle(role.code, view.id)}
                                            className={`p-4 rounded-2xl text-[10px] font-black transition-all border flex flex-col justify-between h-24 text-left ${isAllowed
                                                ? 'bg-indigo-600 border-indigo-600 text-white shadow-lg shadow-indigo-200 dark:shadow-none'
                                                : 'bg-slate-50 dark:bg-slate-800/20 border-slate-100 dark:border-slate-700 text-slate-400 hover:border-indigo-300'
                                                }`}
                                        >
                                            <span className={`opacity-60 text-[8px] uppercase tracking-tighter ${isAllowed ? 'text-white' : ''}`}>{view.category}</span>
                                            <span>{view.label}</span>
                                        </button>
                                    );
                                })}
                            </div>
                        </div>
                    ))}

                    {roles.length === 0 && (
                        <div className="p-20 text-center space-y-4 opacity-30 grayscale">
                            <Users className="w-16 h-16 mx-auto mb-2 text-slate-400" />
                            <p className="text-sm font-black uppercase tracking-[0.2em]">No Operational Roles Defined</p>
                            <p className="text-xs font-medium">Add staff roles to configure granular permissions.</p>
                        </div>
                    )}
                </div>
            </section>

            {/* Change Password Modal */}
            <ChangePasswordModal
                isOpen={isPasswordModalOpen}
                onClose={() => setIsPasswordModalOpen(false)}
            />
        </div>
    );
};

export default SecurityTab;

import { logger } from '@/shared/lib/logger';
import React, { useState, useEffect } from 'react';
import { useParams, useSearchParams } from 'react-router-dom';
import Layout from "@/shared/ui/Layout/Layout";
import PageHeader from "@/shared/ui/Layout/PageHeader";
import { useSelector, useDispatch } from 'react-redux';
import { toast } from 'react-toastify';
import { RootState, AppDispatch } from "@/app/store/store";
import { updateSettings, resetSettings } from "@/app/store/slices/settingsSlice";
import { updateTenantDetails } from "@/entities/session/model/tenantSlice";
import { updateProfile } from "@/entities/session/model/authSlice";
import { SettingsState } from "@/entities/session/model/settings";
import { Tenant } from "@/entities/session/model/core";
import { TaxMode, AppView } from "@repo/shared";
import { setStoredTheme } from "@/shared/lib/utils/theme";
import {
    Settings as SettingsIcon,
    Building,
    Palette,
    CreditCard,
    Puzzle,
    ShieldCheck,
    Share2,
    Lock,
    User,
    Star,
    Loader2,
    RotateCcw,
    Save,
    CheckCircle
} from 'lucide-react';

// Import Tabs
import GeneralTab from './GeneralTab';
import BranchSettingsTab from './BranchSettingsTab';
import BrandingTab from './BrandingTab';
import FinanceTab from './FinanceTab';
import IntegrationsTab from './IntegrationsTab';
import MISControlsTab from './MISControlsTab';
import ModulesTab from './ModulesTab';
import PersonalizationTab from './PersonalizationTab';
import SecurityTab from './SecurityTab';
import SubscriptionTab from './SubscriptionTab';
import { GeneralSettings, MISConfig, ModulesConfig, TenantTheme } from './types';

const Settings: React.FC = () => {
    const [isLoading, setIsLoading] = useState(false);
    const [isSaving, setIsSaving] = useState(false);

    const tabs = [
        { id: 'general', label: 'General', icon: Building, desc: 'Company profile & contact' },
        { id: 'branches', label: 'Branches', icon: Building, desc: 'Manage locations & counters' },
        { id: 'branding', label: 'Branding', icon: Palette, desc: 'Themes & visual identity' },
        { id: 'finance', label: 'Finance', icon: CreditCard, desc: 'Taxes, billing & banking' },
        { id: 'modules', label: 'Modules', icon: Puzzle, desc: 'Enable/disable ERP features' },
        { id: 'mis', label: 'MIS Controls', icon: ShieldCheck, desc: 'Management & audit logs' },
        { id: 'integrations', label: 'Integrations', icon: Share2, desc: 'WhatsApp & external APIs' },
        { id: 'security', label: 'Security', icon: Lock, desc: 'Roles & access control' },
        { id: 'personalization', label: 'Personalization', icon: User, desc: 'User-specific preferences' },
        { id: 'subscription', label: 'Subscription', icon: Star, desc: 'Your current plan & billing' }
    ];

    const { tab } = useParams<{ tab: string }>();
    const activeTab = tabs.find(t => t.id === tab) ? tab : 'general';

    const dispatch = useDispatch<AppDispatch>();
    const { tenants } = useSelector((state: RootState) => state.tenant);
    const { user, role } = useSelector((state: RootState) => state.auth);
    const settings = useSelector((state: RootState) => state.settings);

    const activeTenant = tenants.find((t: any) => t.id === user?.tenantId);

    // -- Local State Initialized from Redux --

    // General
    const [appName, setAppName] = useState(activeTenant?.name || settings.appName);
    const [businessType, setBusinessType] = useState(activeTenant?.businessType || 'Retail');
    const [addressLine1, setAddressLine1] = useState(activeTenant?.companyDetails?.addressLine1 || '');
    const [city, setCity] = useState(activeTenant?.companyDetails?.city || '');
    const [state, setState] = useState(activeTenant?.companyDetails?.state || '');
    const [pincode, setPincode] = useState(activeTenant?.companyDetails?.pincode || '');
    const [phone, setPhone] = useState(activeTenant?.companyDetails?.phone || '');
    const [email, setEmail] = useState(activeTenant?.companyDetails?.email || '');
    const [website, setWebsite] = useState(activeTenant?.companyDetails?.website || '');

    // Branding & Personalization
    const [primaryColor, setPrimaryColor] = useState<string>(activeTenant?.primaryColor || settings.primaryColor || '#4f46e5');
    const [tenantTheme, setTenantTheme] = useState<TenantTheme>(activeTenant?.theme as TenantTheme || 'light');
    const [logoUrl, setLogoUrl] = useState<string | null>(activeTenant?.loginLogoUrl || settings.logoUrl || null);

    const [userTheme, setUserTheme] = useState<'light' | 'dark' | 'system'>(user?.theme || 'system');
    const [userColor, setUserColor] = useState(user?.primaryColor || '');
    const [userLogo, setUserLogo] = useState(user?.loginLogoUrl || '');

    // Finance & Tax
    const [taxMode, setTaxMode] = useState<string>((activeTenant?.systemConfig?.pricingMode) || settings.defaultTaxMode || 'EXCLUSIVE');
    const [gstin, setGstin] = useState(activeTenant?.taxDetails?.gstin || '');
    const [pan, setPan] = useState(activeTenant?.taxDetails?.pan || '');
    const [bankName, setBankName] = useState(activeTenant?.bankingDetails?.bankName || '');
    const [accNo, setAccNo] = useState(activeTenant?.bankingDetails?.accountNumber || '');
    const [ifsc, setIfsc] = useState(activeTenant?.bankingDetails?.ifsc || '');
    const [accountHolderName, setAccountHolderName] = useState(activeTenant?.bankingDetails?.accountHolderName || '');

    // Modules & Config
    const [modules, setModules] = useState<ModulesConfig>(settings.enabledModules as any || { pos: true, inventory: true, finance: true });
    const [misConfig, setMisConfig] = useState<MISConfig>((settings as any) || {});
    const [isSaved, setIsSaved] = useState(false);

    // Save Settings Handler (Redux)
    const handleSave = async () => {
        setIsSaving(true);
        try {
            // 1. Settings Slice Update
            const settingsPayload: Partial<SettingsState> = {
                appName,
                logoUrl: logoUrl || undefined,
                primaryColor,
                enabledModules: modules,
                defaultTaxMode: taxMode as TaxMode,
                // rolePermissions: ... // handled in SecurityTab if needed, or separate
            };

            // 2. Tenant Details Update
            const tenantUpdates: Partial<Tenant> = {
                name: appName,
                primaryColor,
                loginLogoUrl: logoUrl || undefined,
                theme: tenantTheme,
                businessType,
                companyDetails: {
                    addressLine1, city, state, pincode, phone, email, website,
                    country: activeTenant?.companyDetails?.country || 'India',
                    stateCode: activeTenant?.companyDetails?.stateCode || '29'
                },
                taxDetails: {
                    gstin, pan,
                    taxSystem: activeTenant?.taxDetails?.taxSystem || 'GST',
                    isGstEnabled: activeTenant?.taxDetails?.isGstEnabled ?? true
                },
                bankingDetails: { bankName, accountNumber: accNo, ifsc, accountHolderName },
            };

            if (user?.tenantId) {
                dispatch(updateTenantDetails({
                    id: user.tenantId,
                    updates: tenantUpdates
                }));
            }

            dispatch(updateSettings(settingsPayload));

            // 3. User Profile Update
            if (user?.id) {
                dispatch(updateProfile({
                    theme: userTheme,
                    primaryColor: userColor,
                    loginLogoUrl: userLogo || undefined
                }));
                if (userTheme !== 'system') {
                    setStoredTheme(userTheme);
                }
            }

            setIsSaved(true);
            setTimeout(() => setIsSaved(false), 3000);
            toast.success("All settings saved successfully!");
        } catch (error: any) {
            logger.error("Save error", error);
            toast.error(error.message || "Failed to save settings");
        } finally {
            setIsSaving(false);
        }
    };

    const handleReset = () => {
        if (confirm('Reset all settings to defaults? This will reload the application.')) {
            dispatch(resetSettings());
            window.location.reload();
        }
    };

    const [permissions, setPermissions] = useState(settings.rolePermissions);

    const renderTabContent = () => {
        const componentProps = {
            general: {
                appName, setAppName,
                businessType, setBusinessType,
                addressLine1, setAddressLine1,
                city, setCity,
                state, setState,
                pincode, setPincode,
                phone, setPhone,
                email, setEmail,
                website, setWebsite
            },
            branding: {
                tenantTheme, setTenantTheme, primaryColor, setPrimaryColor,
                logoUrl, handleLogoUpload: (e: React.ChangeEvent<HTMLInputElement>) => { if (e.target.files && e.target.files[0]) setLogoUrl(URL.createObjectURL(e.target.files[0])); }
            },
            finance: {
                taxMode, setTaxMode,
                gstin, setGstin, pan, setPan,
                bankName, setBankName, accNo, setAccNo, ifsc, setIfsc, accountHolderName, setAccountHolderName
            },
            modules: { modules, handleModuleToggle: (id: string) => setModules(prev => ({ ...prev, [id]: !prev[id] })) },
            mis: {
                misConfig: { ...misConfig, ...settings } as unknown as MISConfig,
                handleMisToggle: (k: string) => dispatch(updateSettings({ [k]: !((settings as any)[k]) })),
                setMaxDiscountPercent: (v: number) => dispatch(updateSettings({ sales: { ...settings.sales, defaultDiscount: v } }))
            },
            security: {
                roles: [], permissions,
                handlePermissionToggle: (roleCode: string, view: string | AppView) => {
                    const viewId = view as AppView;
                    const current = permissions[roleCode] || [];
                    const updated = current.includes(viewId) ? current.filter((v: any) => v !== viewId) : [...current, viewId];
                    setPermissions({ ...permissions, [roleCode]: updated });
                }
            },
            personalization: {
                userTheme, setUserTheme, userColor, setUserColor,
                userLogo, handleUserLogoUpload: (e: React.ChangeEvent<HTMLInputElement>) => { if (e.target.files && e.target.files[0]) setUserLogo(URL.createObjectURL(e.target.files[0])); }
            }
        };

        if (isLoading && activeTab === 'general') {
            return (
                <div className="flex flex-col items-center justify-center h-64 text-slate-400">
                    <Loader2 className="w-8 h-8 animate-spin mb-2" />
                    <p className="text-sm font-medium">Loading settings...</p>
                </div>
            );
        }

        switch (activeTab) {
            case 'general': return <GeneralTab {...componentProps.general} />;
            case 'branches': return <BranchSettingsTab />;
            case 'branding': return <BrandingTab {...componentProps.branding} />;
            case 'finance': return <FinanceTab {...componentProps.finance} />;
            case 'modules': return <ModulesTab {...componentProps.modules} />;
            case 'mis': return <MISControlsTab {...componentProps.mis} />;
            case 'integrations': return <IntegrationsTab />;
            case 'security': return <SecurityTab {...componentProps.security} />;
            case 'personalization': return <PersonalizationTab {...componentProps.personalization} />;
            case 'subscription': return <SubscriptionTab />;
            default: return <GeneralTab {...componentProps.general} />;
        }
    };

    return (
        <Layout>
            <PageHeader
                title="System Settings"
                description="Configure your enterprise environment, manage users, and customize your experience."
            />

            <div className="flex flex-col gap-6">
                {/* Horizontal Navigation Bar Removed */}

                {/* Main Content Area */}
                <div className="w-full min-h-[calc(100vh-250px)] bg-white dark:bg-slate-900 rounded-3xl shadow-2xl shadow-slate-200/50 dark:shadow-none border border-slate-200 dark:border-slate-800 overflow-hidden animate-in fade-in slide-in-from-bottom-4 duration-500 flex flex-col">
                    <div className="border-b border-slate-100 dark:border-slate-800 px-8 py-6 flex items-center justify-between bg-slate-50/50 dark:bg-slate-800/20 backdrop-blur-sm">
                        <div className="flex items-center gap-4">
                            <div className="w-12 h-12 rounded-2xl bg-indigo-100 dark:bg-indigo-900/30 flex items-center justify-center">
                                {(() => {
                                    const Icon = tabs.find(t => t.id === activeTab)?.icon || SettingsIcon;
                                    return <Icon className="w-6 h-6 text-indigo-600 dark:text-indigo-400" />;
                                })()}
                            </div>
                            <div>
                                <h2 className="text-xl font-extrabold text-slate-800 dark:text-white leading-none">
                                    {tabs.find(t => t.id === activeTab)?.label} Settings
                                </h2>
                                <p className="text-xs text-slate-500 font-medium mt-1 uppercase tracking-wider">
                                    System / Configuration / {activeTab}
                                </p>
                            </div>
                        </div>
                        <div className="flex items-center gap-3">
                            <button
                                onClick={handleReset}
                                className="px-4 py-2 text-slate-500 hover:text-red-500 dark:text-slate-400 font-bold flex items-center gap-2"
                            >
                                <RotateCcw className="w-4 h-4" /> Reset
                            </button>
                            <button
                                onClick={handleSave}
                                disabled={isSaving}
                                className={`px-6 py-2.5 bg-slate-900 dark:bg-indigo-600 text-white rounded-xl text-sm font-bold shadow-lg hover:shadow-indigo-500/20 active:scale-95 transition-all disabled:opacity-70 disabled:cursor-not-allowed flex items-center gap-2 ${isSaved ? 'bg-emerald-600 dark:bg-emerald-600' : ''}`}
                            >
                                {isSaving && <Loader2 className="w-4 h-4 animate-spin" />}
                                {isSaved ? <CheckCircle className="w-4 h-4" /> : !isSaving && <Save className="w-4 h-4" />}
                                {isSaved ? 'Saved!' : isSaving ? 'Saving...' : 'Save Changes'}
                            </button>
                        </div>
                    </div>

                    <div className="relative overflow-y-auto flex-1">
                        {renderTabContent()}
                    </div>
                </div>
            </div>
        </Layout>
    );
};

export default Settings;

import { logger } from '@/shared/lib/logger';
import React, { useTransition } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import {
    Check, Zap, Shield, Crown, Building, Activity,
    CreditCard, Sparkles,
    Database, Users as UsersIcon, Smartphone
} from 'lucide-react';
import api from "@/shared/api/api";
import { toast } from 'react-toastify';
import { RootState } from "@/app/store/store";

interface Plan {
    code: string;
    name: string;
    price: string;
    desc: string;
    icon: any;
    color: string;
    features: string[];
    popular?: boolean;
}

const SubscriptionTab: React.FC = () => {
    const dispatch = useDispatch();
    const [isPending, startTransition] = useTransition();
    const { user } = useSelector((state: RootState) => state.auth);
    const { tenants } = useSelector((state: RootState) => state.tenant || { tenants: [] });

    const currentTenant = (tenants || []).find((t: any) => (t.id || t._id) === user?.tenantId);
    const currentPlanCode = currentTenant?.planCode || 'FREE';

    const handleSwitchPlan = (planCode: string) => {
        startTransition(async () => {
            try {
                const response = await api.put('/shop/settings', {
                    plan: planCode,
                });
                if (response.data.success) {
                    dispatch({
                        type: 'tenant/updateTenantDetails',
                        payload: { id: user?.tenantId, updates: response.data.data }
                    });
                    toast.success(`Switched to ${planCode} plan successfully!`);
                }
            } catch (error: any) {
                logger.error('Error switching plan:', error);
                toast.error(error.response?.data?.message || 'Failed to switch plan');
            }
        });
    };

    const PLANS: Plan[] = [
        {
            code: 'FREE',
            name: 'Standard Base',
            price: '₹0',
            desc: 'Essential tools for single-terminal operations.',
            icon: Building,
            color: 'slate',
            features: ['Up to 50 items', 'Basic reporting', 'Single user']
        },
        {
            code: 'STARTER',
            name: 'Growth Engine',
            price: '₹29',
            desc: 'Expanded capacity for emerging enterprises.',
            icon: Sparkles,
            color: 'indigo',
            features: ['Up to 500 items', 'Standard reporting', 'Multi-user', 'E-commerce enabled']
        },
        {
            code: 'PRO',
            name: 'Professional',
            price: '₹99',
            desc: 'Full-spectrum suite for high-volume trade.',
            icon: Crown,
            color: 'emerald',
            popular: true,
            features: ['Unlimited items', 'Advanced analytics', 'Custom domain', 'Priority support']
        },
        {
            code: 'ENTERPRISE',
            name: 'Apex Tier',
            price: '₹499',
            desc: 'Bespoke infrastructure for global scale.',
            icon: Zap,
            color: 'blue',
            features: ['Dedicated account manager', 'Custom integrations', 'SLA guaranteed', 'On-premise option']
        }
    ];

    // Simulated usage data
    const usage = [
        { label: 'Storage Payload', value: 45, total: 50, unit: 'Items', icon: Database },
        { label: 'Agent Seats', value: 3, total: 5, unit: 'Users', icon: UsersIcon },
        { label: 'Terminal Nodes', value: 2, total: 10, unit: 'Devices', icon: Smartphone }
    ];

    return (
        <div className="p-8 space-y-12 animate-in fade-in slide-in-from-bottom-4 duration-700">
            {/* Active Subscription Summary */}
            <section className="bg-slate-900 rounded-[3rem] p-10 flex flex-col md:flex-row items-center gap-10 border border-slate-800 shadow-2xl relative overflow-hidden group">
                <div className="absolute top-0 right-0 p-10 opacity-5 pointer-events-none group-hover:opacity-10 transition-opacity">
                    <Shield className="w-64 h-64 text-emerald-500" />
                </div>

                <div className="relative z-10 w-24 h-24 rounded-[2.5rem] bg-emerald-600 flex items-center justify-center shadow-2xl shadow-emerald-500/30 group-hover:scale-105 transition-transform">
                    <Activity className="w-12 h-12 text-white animate-pulse" />
                </div>

                <div className="relative z-10 flex-1 text-center md:text-left">
                    <div className="flex items-center justify-center md:justify-start gap-3 mb-4">
                        <span className="px-4 py-1.5 bg-emerald-500/10 text-emerald-400 rounded-full text-[10px] font-black tracking-[0.2em] border border-emerald-500/20">VALID SESSION ACTIVE</span>
                        <div className="flex h-2 w-2 relative">
                            <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-emerald-400 opacity-75"></span>
                            <span className="relative inline-flex rounded-full h-2 w-2 bg-emerald-500"></span>
                        </div>
                    </div>
                    <h3 className="text-4xl font-black text-white italic tracking-tighter uppercase mb-2">
                        {PLANS.find(p => p.code === currentPlanCode)?.name || 'Apex Tier'}
                    </h3>
                    <p className="text-slate-500 font-medium text-lg max-w-lg">
                        Your enterprise ecosystem is currently operating under the <span className="text-emerald-400 font-black italic">{currentPlanCode} Protocol</span>.
                    </p>
                </div>

                <div className="relative z-10 grid grid-cols-2 gap-4 shrink-0">
                    <button className="px-8 py-4 bg-white hover:bg-slate-50 text-slate-900 rounded-2xl text-[11px] font-black tracking-widest shadow-xl active:scale-95 transition-all">
                        BILLING HUB
                    </button>
                    <button className="px-8 py-4 bg-slate-800 hover:bg-slate-700 text-slate-300 rounded-2xl text-[11px] font-black tracking-widest border border-slate-700 active:scale-95 transition-all">
                        DOCS
                    </button>
                </div>
            </section>

            {/* Usage HUD */}
            <div className="grid md:grid-cols-3 gap-8">
                {usage.map((item, idx) => (
                    <div key={idx} className="bg-white dark:bg-slate-950 p-8 rounded-[2.5rem] border border-slate-100 dark:border-slate-800 shadow-sm group hover:shadow-xl transition-all duration-500">
                        <div className="flex items-center justify-between mb-6">
                            <div className="w-12 h-12 rounded-2xl bg-slate-50 dark:bg-slate-900 flex items-center justify-center group-hover:scale-110 transition-transform">
