                                    <div className="absolute top-0 left-1/2 -translate-x-1/2 -translate-y-1/2 px-6 py-2 bg-white text-indigo-600 rounded-full text-[10px] font-black tracking-[0.2em] shadow-xl border border-indigo-100">
