                                </button>
                                <button className="px-4 py-2 border border-defalut text-secondary rounded-lg hover:bg-surface text-sm font-medium">
                                    Download
                                </button>
                            </div>
                        </div>
                    ))}
                </div>
            </div>
        </Layout>
    );
};

