/* ─── Node Topology Visualizer ────────────────────────────── */
const NodeTopology: React.FC<{ devices: DeviceRegistryEntry[] }> = ({ devices }) => {
    const onlineDevices = useMemo(() => devices.filter(d => d.isOnline), [devices]);
    
