import React, { useState, useTransition } from 'react';
import { Link } from 'react-router-dom';
import { User, Mail, Store, Phone, ArrowRight, ArrowLeft, ShieldCheck, Loader2, ChevronRight } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import SecurePasswordInput from './SecurePasswordInput';
import AuthLayout from '@/views/Views/ui/AuthLayout';
import AuthAlert from '@/views/Views/ui/AuthAlert';
import AuthInput from '@/features/auth-by-email/ui/AuthInput';
import PasswordStrengthMeter from '@/features/auth-by-email/ui/PasswordStrengthMeter';
import { useRegisterForm } from '@/features/auth-by-email/lib/useRegisterForm';

const STEPS = [
    { id: 1, label: 'Identity', fields: ['name', 'email'] as const },
    { id: 2, label: 'Business', fields: ['shopName', 'phone'] as const },
    { id: 3, label: 'Security', fields: ['password', 'confirmPassword', 'terms'] as const },
];

const Register: React.FC = () => {
    const { form, onSubmit, isLoading } = useRegisterForm();
    const { register, formState: { errors }, trigger, watch } = form;
    const { isError, message, validationError } = form as any;
    const [step, setStep] = useState(1);
    const [direction, setDirection] = useState(1);
    const [isPending, startTransition] = useTransition();

    const passwordValue = watch('password') || '';

    const nextStep = async () => {
        const currentFields = STEPS[step - 1].fields;
        const isValid = await trigger(currentFields as any);
        if (isValid && step < 3) {
            setDirection(1);
            startTransition(() => setStep(step + 1));
        }
    };

    const prevStep = () => {
        if (step > 1) {
            setDirection(-1);
            startTransition(() => setStep(step - 1));
        }
    };

    const handleFinalSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        const isValid = await trigger();
        if (isValid) {
            startTransition(() => {
                onSubmit(e);
            });
        }
    };

    const loading = isLoading || isPending;

    const slideVariants = {
        enter: (dir: number) => ({ x: dir > 0 ? 60 : -60, opacity: 0 }),
        center: { x: 0, opacity: 1 },
        exit: (dir: number) => ({ x: dir > 0 ? -60 : 60, opacity: 0 }),
    };

    return (
        <AuthLayout
            title="Enterprise Registration"
            subtitle="Create your workspace"
            secondarySubtitle="Start your 14-day free trial"
            description="Join thousands of retailers using our platform to scale their business. Professional tools for professional growth."
        >
            <motion.div
                initial={{ opacity: 0, y: 12 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ duration: 0.5, ease: [0.22, 1, 0.36, 1] }}
            >
                {/* Error Alert */}
                {(isError || validationError) && (
                    <div className="mb-6">
                        <AuthAlert
                            type="error"
                            title="Registration Error"
                            message={validationError || message}
                        />
                    </div>
                )}

                {/* Step Indicator */}
                <div className="flex items-center gap-2 mb-8">
                    {STEPS.map((s, i) => (
                        <React.Fragment key={s.id}>
                            <div className="flex items-center gap-2">
                                <div
                                    className={`w-7 h-7 rounded-lg flex items-center justify-center text-[10px] font-bold transition-all duration-500 ${step > s.id
                                        ? 'bg-emerald-500/15 text-emerald-400 border border-emerald-500/20'
                                        : step === s.id
                                            ? 'bg-indigo-500/15 text-indigo-400 border border-indigo-500/25'
                                            : 'bg-white/[0.03] text-white/15 border border-white/[0.05]'
                                        }`}
                                >
                                    {step > s.id ? '✓' : s.id}
                                </div>
                                <span className={`text-[10px] font-bold uppercase tracking-[0.15em] transition-colors duration-300 hidden sm:block ${step >= s.id ? 'text-white/40' : 'text-white/10'
                                    }`}>
                                    {s.label}
                                </span>
                            </div>
                            {i < STEPS.length - 1 && (
                                <div className={`flex-1 h-px transition-colors duration-500 ${step > s.id ? 'bg-emerald-500/20' : 'bg-white/[0.04]'
                                    }`} />
                            )}
                        </React.Fragment>
                    ))}
                </div>

                <form onSubmit={handleFinalSubmit}>
                    <AnimatePresence mode="wait" custom={direction}>
                        {/* STEP 1: Identity */}
                        {step === 1 && (
                            <motion.div
                                key="step1"
                                custom={direction}
                                variants={slideVariants}
                                initial="enter"
                                animate="center"
                                exit="exit"
                                transition={{ duration: 0.35, ease: [0.22, 1, 0.36, 1] }}
                                className="space-y-5"
                            >
                                <AuthInput
                                    id="register-name"
                                    label="Full Name"
                                    placeholder="John Doe"
                                    icon={User}
                                    registration={register('name')}
                                    error={errors.name?.message}
                                />
                                <AuthInput
                                    id="register-email"
                                    label="Email Address"
                                    type="email"
                                    placeholder="name@company.com"
                                    icon={Mail}
                                    registration={register('email')}
                                    error={errors.email?.message}
                                />
                            </motion.div>
                        )}

                        {/* STEP 2: Business Profile */}
                        {step === 2 && (
                            <motion.div
                                key="step2"
                                custom={direction}
                                variants={slideVariants}
                                initial="enter"
                                animate="center"
                                exit="exit"
                                transition={{ duration: 0.35, ease: [0.22, 1, 0.36, 1] }}
                                className="space-y-5"
                            >
                                <AuthInput
                                    id="register-shopName"
                                    label="Business Name"
                                    placeholder="Acme Corporation"
                                    icon={Store}
                                    registration={register('shopName')}
                                    error={errors.shopName?.message}
                                />
                                <AuthInput
                                    id="register-phone"
                                    label="Contact Number"
                                    type="tel"
                                    placeholder="9876543210"
                                    leftElement={
                                        <span className="h-full rounded-l-xl border-r border-white/[0.06] bg-white/[0.03] px-3 flex items-center text-white/25 text-[10px] font-bold tracking-[0.15em] transition-colors group-focus-within:text-indigo-400/60">
                                            +91
                                        </span>
                                    }
                                    registration={register('phone')}
                                    error={errors.phone?.message}
                                />
                            </motion.div>
                        )}

                        {/* STEP 3: Security */}
                        {step === 3 && (
                            <motion.div
                                key="step3"
                                custom={direction}
                                variants={slideVariants}
                                initial="enter"
                                animate="center"
                                exit="exit"
                                transition={{ duration: 0.35, ease: [0.22, 1, 0.36, 1] }}
                                className="space-y-5"
                            >
                                <SecurePasswordInput
                                    id="register-password"
                                    label="Create Password"
                                    placeholder="Min 8 characters"
                                    registration={register('password')}
                                    error={errors.password?.message}
                                />

                                <PasswordStrengthMeter password={passwordValue} />

                                <SecurePasswordInput
                                    id="register-confirmPassword"
                                    label="Confirm Password"
                                    placeholder="Re-enter password"
                                    registration={register('confirmPassword')}
                                    error={errors.confirmPassword?.message}
                                />

                                {/* Terms */}
                                <div className="flex items-start gap-3 pt-1 group cursor-pointer">
                                    <div className="relative flex items-center mt-0.5">
                                        <input
                                            id="register-terms"
                                            type="checkbox"
                                            {...register('terms')}
                                            className="peer h-4 w-4 rounded-md border-white/10 bg-white/[0.04] text-indigo-500 focus:ring-indigo-500/30 transition-all cursor-pointer appearance-none border checked:bg-indigo-600 checked:border-indigo-600"
                                        />
                                        <ShieldCheck className="absolute pointer-events-none opacity-0 peer-checked:opacity-100 w-3 h-3 text-white left-0.5" />
                                    </div>
                                    <label htmlFor="register-terms" className="text-[10px] font-medium text-white/25 leading-relaxed cursor-pointer group-hover:text-white/35 transition-colors">
                                        I agree to the <a href="#" className="text-indigo-400/70 hover:text-indigo-400 underline underline-offset-2">Terms of Service</a> and <a href="#" className="text-indigo-400/70 hover:text-indigo-400 underline underline-offset-2">Privacy Policy</a>
                                    </label>
                                </div>
                                {errors.terms && (
                                    <p className="text-[11px] text-red-400/90 font-medium flex items-center gap-1.5">
                                        <span className="w-1 h-1 rounded-full bg-red-400 shrink-0" />
                                        {errors.terms?.message}
                                    </p>
                                )}
                            </motion.div>
                        )}
                    </AnimatePresence>

                    {/* Navigation Buttons */}
                    <div className="flex items-center gap-3 mt-8">
                        {step > 1 && (
                            <button
                                type="button"
                                onClick={prevStep}
                                className="h-12 px-5 bg-white/[0.04] border border-white/[0.06] text-white/50 hover:text-white/80 hover:bg-white/[0.06] rounded-xl font-bold text-sm flex items-center gap-2 transition-all"
                            >
                                <ArrowLeft className="w-3.5 h-3.5" />
                                Back
                            </button>
                        )}

                        {step < 3 ? (
                            <button
                                type="button"
                                onClick={nextStep}
                                className="flex-1 h-12 bg-gradient-to-r from-indigo-600 to-violet-600 hover:from-indigo-500 hover:to-violet-500 text-white rounded-xl font-bold text-sm flex items-center justify-center gap-2 active:scale-[0.98] transition-all shadow-lg shadow-indigo-600/20"
                            >
                                Continue <ChevronRight className="w-4 h-4" />
                            </button>
                        ) : (
                            <button
                                type="submit"
                                disabled={loading}
                                className="flex-1 h-12 bg-gradient-to-r from-indigo-600 to-violet-600 hover:from-indigo-500 hover:to-violet-500 text-white rounded-xl font-bold text-sm flex items-center justify-center gap-2 active:scale-[0.98] transition-all disabled:opacity-40 disabled:scale-100 shadow-lg shadow-indigo-600/20"
                            >
                                {loading ? (
                                    <Loader2 className="w-4 h-4 animate-spin" />
                                ) : (
                                    <>Initialize Enterprise <ArrowRight className="w-3.5 h-3.5" /></>
                                )}
                            </button>
                        )}
                    </div>
                </form>

                {/* Footer */}
                <div className="mt-8 pt-7 border-t border-white/[0.05] text-center">
                    <p className="text-[10px] font-bold text-white/15 uppercase tracking-[0.2em] mb-3">
                        Already have access?
                    </p>
                    <Link
                        to="/login"
                        className="inline-flex items-center gap-2 text-sm font-bold text-indigo-400/80 hover:text-indigo-300 transition-colors"
                    >
                        Sign In to Workspace <ArrowRight className="w-3.5 h-3.5" />
                    </Link>
                </div>
            </motion.div>
        </AuthLayout>
    );
};

export default Register;

import React, { useEffect, useTransition } from 'react';
import { useLocation, useNavigate, Link } from 'react-router-dom';
import { ArrowRight, ShieldAlert, Loader2 } from 'lucide-react';
import { motion } from 'framer-motion';
import SecurePasswordInput from './SecurePasswordInput';
import PasswordStrengthMeter from '@/features/auth-by-email/ui/PasswordStrengthMeter';
import AuthLayout from '@/views/Views/ui/AuthLayout';
import AuthAlert from '@/views/Views/ui/AuthAlert';
import { useResetPasswordForm } from '@/features/auth-by-email/lib/useResetPasswordForm';

const ResetPassword: React.FC = () => {
    const location = useLocation();
    const navigate = useNavigate();
    const [isPending, startTransition] = useTransition();

    const params = new URLSearchParams(location.search);
    const email = params.get('email') || '';
    const token = params.get('token') || '';

    const { form, onSubmit, isLoading } = useResetPasswordForm(email, token);
    const { register, formState: { errors }, watch } = form;
    const { isError, isSuccess, message, validationError } = form as any;

    const passwordValue = watch('password') || '';
    const loading = isLoading || isPending;

    useEffect(() => {
        if (isSuccess) {
            const t = setTimeout(() => navigate('/login'), 2500);
            return () => clearTimeout(t);
        }
    }, [isSuccess, navigate]);

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        startTransition(() => {
            onSubmit(e);
        });
    };

    // Invalid / expired link
    if (!token || !email) {
        return (
            <AuthLayout
                title="Access Denied"
                subtitle="Invalid Reset Link"
                secondarySubtitle="This request could not be verified"
                description="This reset link is either invalid or has expired. Please request a new one for security."
            >
                <motion.div
                    initial={{ opacity: 0, scale: 0.95 }}
                    animate={{ opacity: 1, scale: 1 }}
                    transition={{ duration: 0.5 }}
                    className="space-y-6"
                >
                    <div className="bg-red-500/[0.06] border border-red-500/10 p-6 rounded-xl flex flex-col items-center gap-4 text-center">
                        <ShieldAlert className="w-10 h-10 text-red-400/80" />
                        <p className="text-[10px] font-bold text-red-400/60 uppercase tracking-[0.2em]">Security Link Invalid</p>
                        <Link
                            to="/forgot-password"
                            className="w-full h-12 bg-gradient-to-r from-indigo-600 to-violet-600 hover:from-indigo-500 hover:to-violet-500 text-white rounded-xl font-bold text-sm flex items-center justify-center gap-2 transition-all shadow-lg shadow-indigo-600/20"
                        >
                            Request New Link <ArrowRight className="w-3.5 h-3.5" />
                        </Link>
                    </div>
                </motion.div>
            </AuthLayout>
        );
    }

    return (
        <AuthLayout
            title="System Security"
            subtitle="Reset your Password"
            secondarySubtitle={`Updating credentials for ${email}`}
            description="Create a strong, unique password to protect your enterprise workspace and data."
        >
            <motion.div
                initial={{ opacity: 0, y: 12 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ duration: 0.5, ease: [0.22, 1, 0.36, 1] }}
            >
                {/* Success state */}
                {isSuccess ? (
                    <motion.div
                        initial={{ opacity: 0, scale: 0.95 }}
                        animate={{ opacity: 1, scale: 1 }}
                        className="text-center space-y-6"
                    >
                        <div className="w-16 h-16 bg-emerald-500/10 border border-emerald-500/15 rounded-2xl flex items-center justify-center mx-auto">
                            <svg className="w-8 h-8 text-emerald-400" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                                <polyline points="20 6 9 17 4 12" />
                            </svg>
                        </div>
                        <div className="space-y-2">
                            <h3 className="text-lg font-bold text-white">Password Updated</h3>
                            <p className="text-white/30 text-sm">
                                Your credentials have been updated. Redirecting to login...
                            </p>
                        </div>
                        {/* Progress indicator */}
                        <div className="w-full bg-white/[0.04] h-1 rounded-full overflow-hidden">
                            <div
                                className="h-full bg-gradient-to-r from-emerald-500 to-emerald-400 rounded-full"
                                style={{
                                    animation: 'progressBar 2.5s ease-in-out forwards',
                                    width: '0%'
                                }}
                            />
                        </div>
                        <style>{`
                            @keyframes progressBar {
                                from { width: 0%; }
                                to { width: 100%; }
                            }
                        `}</style>
                    </motion.div>
                ) : (
                    <>
                        {/* Alerts */}
                        {(validationError || isError) && (
                            <div className="mb-6">
                                <AuthAlert
                                    type="error"
                                    title="Reset Error"
                                    message={validationError || message}
                                />
                            </div>
                        )}

                        <form className="space-y-5" onSubmit={handleSubmit}>
                            <SecurePasswordInput
                                id="reset-password"
                                label="New Password"
                                placeholder="Min 8+ characters"
                                registration={register('password')}
                                error={errors.password?.message}
                            />

                            <PasswordStrengthMeter password={passwordValue} />

                            <SecurePasswordInput
                                id="reset-confirmPassword"
                                label="Confirm New Password"
                                placeholder="Re-enter your password"
                                registration={register('confirmPassword')}
                                error={errors.confirmPassword?.message}
                            />

                            <button
                                type="submit"
                                disabled={loading}
                                className="w-full h-12 bg-gradient-to-r from-indigo-600 to-violet-600 hover:from-indigo-500 hover:to-violet-500 text-white rounded-xl font-bold text-sm flex items-center justify-center gap-2.5 active:scale-[0.98] transition-all duration-200 disabled:opacity-40 disabled:scale-100 shadow-lg shadow-indigo-600/20"
                            >
                                {loading ? (
                                    <Loader2 className="w-4 h-4 animate-spin" />
                                ) : (
                                    <>Update Password <ArrowRight className="w-3.5 h-3.5" /></>
                                )}
                            </button>
                        </form>

                        {/* Back to login */}
                        <div className="mt-8 pt-7 border-t border-white/[0.05] text-center">
                            <Link
                                to="/login"
                                className="text-[10px] font-bold text-white/20 hover:text-white/40 uppercase tracking-[0.2em] transition-colors flex items-center justify-center gap-2"
                            >
                                <ArrowRight className="w-3 h-3 rotate-180" /> Abort & Return to Login
                            </Link>
                        </div>
                    </>
                )}
            </motion.div>
        </AuthLayout>
    );
};

export default ResetPassword;

import React, { useState, useEffect, useTransition } from 'react';
import { useNavigate } from 'react-router-dom';
import { useDispatch, useSelector } from 'react-redux';
import { RootState, AppDispatch } from "@/app/store/store";
import { logout, setAuthError, setAuthSuccess } from "@/entities/session/model/authSlice";
import api from "@/shared/api/api";
import { clearSession } from "@/shared/lib/utils/session";
import { Lock, ArrowRight, AlertCircle, CheckCircle2, Loader2, Eye, EyeOff, ShieldCheck } from 'lucide-react';
import { motion } from 'framer-motion';
import PasswordStrengthMeter from '../../components/Auth/PasswordStrengthMeter';

const ResetPassword = () => {
    const navigate = useNavigate();
    const dispatch = useDispatch<AppDispatch>();
    const { isLoading, isSuccess, isError } = useSelector((state: RootState) => state.auth);
    const [isPending, startTransition] = useTransition();

    const [password, setPassword] = useState('');
    const [confirmPassword, setConfirmPassword] = useState('');
    const [showPassword, setShowPassword] = useState(false);
    const [sessionChecked, setSessionChecked] = useState(false);
    const [localError, setLocalError] = useState('');

    const [validation, setValidation] = useState({
        length: false, upper: false, lower: false, number: false, special: false
    });

    useEffect(() => {
        const checkSession = async () => {
            try {
                setSessionChecked(true);
            } catch (e) {
                dispatch(setAuthError("Session invalid or link expired. Please request a new link."));
                setSessionChecked(true);
            }
        };
        checkSession();
        return () => {
            dispatch(setAuthSuccess(false));
            dispatch(setAuthError(null));
        };
    }, [dispatch]);

    useEffect(() => {
        setValidation({
            length: password.length >= 8,
            upper: /[A-Z]/.test(password),
            lower: /[a-z]/.test(password),
            number: /[0-9]/.test(password),
            special: /[^A-Za-z0-9]/.test(password)
        });
    }, [password]);

    const strengthScore = Object.values(validation).filter(Boolean).length;
    const isPasswordStrong = validation.length && strengthScore >= 4;

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setLocalError('');
        dispatch(setAuthError(null));

        if (password !== confirmPassword) {
            setLocalError("Passwords do not match.");
            return;
        }
        if (!isPasswordStrong) {
            setLocalError("Password does not meet security requirements.");
            return;
        }

        try {
            await api.post('/auth/reset-password', { password });
            dispatch(setAuthSuccess(true));
        } catch (err: any) {
            dispatch(setAuthError(err.message));
        }
    };

    useEffect(() => {
        if (isSuccess) {
            startTransition(() => {
                dispatch(logout());
                clearSession();
            });
            const timer = setTimeout(() => navigate('/'), 2500);
            return () => clearTimeout(timer);
        }
    }, [isSuccess, navigate, dispatch, startTransition]);

    const loading = isLoading || isPending;

    if (!sessionChecked) {
        return (
            <div className="h-screen bg-[#06080F] flex items-center justify-center">
                <Loader2 className="w-8 h-8 animate-spin text-indigo-500" />
            </div>
        );
    }

    return (
        <div className="min-h-screen relative flex items-center justify-center p-4 sm:p-6 overflow-hidden bg-[#06080F]">
            {/* Ambient Background */}
            <div className="absolute inset-0 pointer-events-none overflow-hidden">
                <div className="absolute -top-[25%] -left-[10%] w-[55%] h-[55%] bg-indigo-600/[0.06] blur-[150px] rounded-full animate-pulse" style={{ animationDuration: '8s' }} />
                <div className="absolute -bottom-[25%] -right-[10%] w-[50%] h-[50%] bg-violet-600/[0.05] blur-[130px] rounded-full animate-pulse" style={{ animationDuration: '12s' }} />
                <div className="absolute inset-0 opacity-[0.012]" style={{
                    backgroundImage: 'linear-gradient(rgba(255,255,255,0.1) 1px, transparent 1px), linear-gradient(90deg, rgba(255,255,255,0.1) 1px, transparent 1px)',
                    backgroundSize: '64px 64px'
                }} />
            </div>

            <motion.div
                className="relative z-10 w-full max-w-[460px]"
                initial={{ opacity: 0, y: 20, scale: 0.98 }}
                animate={{ opacity: 1, y: 0, scale: 1 }}
                transition={{ duration: 0.7, ease: [0.22, 1, 0.36, 1] }}
            >
                {/* Glass Card */}
                <div className="bg-white/[0.025] backdrop-blur-2xl border border-white/[0.06] rounded-3xl shadow-2xl shadow-black/20 p-7 sm:p-9 max-h-[90dvh] overflow-y-auto" style={{ scrollbarWidth: 'none' }}>
                    {/* Header */}
                    <div className="mb-7">
                        <div className="flex justify-between items-start mb-5">
                            <div className="w-10 h-10 bg-gradient-to-br from-indigo-500 to-violet-600 rounded-xl flex items-center justify-center shadow-lg shadow-indigo-500/20">
                                <ShieldCheck className="w-5 h-5 text-white" />
                            </div>
                            <div className="flex items-center gap-2 px-3 py-1.5 bg-white/[0.03] border border-white/[0.06] rounded-full">
                                <span className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse" />
                                <span className="text-[9px] uppercase font-bold tracking-[0.2em] text-white/25">Secure</span>
                            </div>
                        </div>
                        <h1 className="text-2xl sm:text-3xl font-black text-white tracking-tight mb-1.5">Set New Password</h1>
                        <p className="text-white/25 text-sm font-medium">Reset access for your Enterprise Account</p>
                    </div>

                    {isSuccess ? (
                        /* Success State */
                        <motion.div
                            className="text-center py-4"
                            initial={{ opacity: 0, scale: 0.95 }}
                            animate={{ opacity: 1, scale: 1 }}
                        >
                            <div className="w-16 h-16 bg-emerald-500/10 text-emerald-400 rounded-2xl flex items-center justify-center mx-auto mb-6 border border-emerald-500/15">
                                <CheckCircle2 className="w-8 h-8" />
                            </div>
                            <h2 className="text-xl font-bold text-white mb-2">Password Updated</h2>
                            <p className="text-white/30 mb-6 text-sm">
                                Credentials synchronized. Redirecting...
                            </p>
                            <div className="w-full bg-white/[0.04] h-1 rounded-full overflow-hidden">
                                <div
                                    className="h-full bg-gradient-to-r from-emerald-500 to-emerald-400 rounded-full"
                                    style={{ animation: 'progressBar 2.5s ease-in-out forwards', width: '0%' }}
                                />
                            </div>
                        </motion.div>
                    ) : (
                        <form onSubmit={handleSubmit} className="space-y-6">
                            {/* New Password */}
                            <div className="group">
                                <label className="block text-[10px] font-bold text-white/30 uppercase tracking-[0.2em] mb-2.5 ml-0.5 transition-colors group-focus-within:text-indigo-400">
                                    New Password
                                </label>
                                <div className="relative">
                                    <Lock className="w-[18px] h-[18px] text-white/20 absolute left-4 top-1/2 -translate-y-1/2 group-focus-within:text-indigo-400 transition-colors duration-300" />
                                    <input
                                        type={showPassword ? "text" : "password"}
                                        value={password}
                                        onChange={(e) => setPassword(e.target.value)}
                                        placeholder="Min 8 characters"
                                        className="w-full h-13 pl-11 pr-11 bg-white/[0.04] border border-white/[0.07] rounded-xl outline-none focus:ring-2 focus:ring-indigo-500/30 focus:border-indigo-500/40 text-white/90 font-mono text-sm tracking-wider transition-all duration-300 placeholder:text-white/15 hover:border-white/[0.12]"
                                        disabled={loading}
                                    />
                                    <button
                                        type="button"
                                        onClick={() => setShowPassword(!showPassword)}
                                        className="absolute right-3.5 top-1/2 -translate-y-1/2 text-white/20 hover:text-white/50 transition-colors"
                                    >
                                        {showPassword ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
                                    </button>
                                    <div className="absolute inset-0 rounded-xl opacity-0 group-focus-within:opacity-100 transition-opacity duration-500 pointer-events-none bg-gradient-to-r from-indigo-500/[0.03] to-violet-500/[0.03]" />
                                </div>
                            </div>

                            {/* Confirm Password */}
                            <div className="group">
                                <label className="block text-[10px] font-bold text-white/30 uppercase tracking-[0.2em] mb-2.5 ml-0.5 transition-colors group-focus-within:text-indigo-400">
                                    Confirm Password
                                </label>
                                <div className="relative">
                                    <Lock className="w-[18px] h-[18px] text-white/20 absolute left-4 top-1/2 -translate-y-1/2 group-focus-within:text-indigo-400 transition-colors duration-300" />
                                    <input
                                        type={showPassword ? "text" : "password"}
                                        value={confirmPassword}
                                        onChange={(e) => setConfirmPassword(e.target.value)}
                                        placeholder="Repeat password"
                                        className="w-full h-13 pl-11 pr-4 bg-white/[0.04] border border-white/[0.07] rounded-xl outline-none focus:ring-2 focus:ring-indigo-500/30 focus:border-indigo-500/40 text-white/90 font-mono text-sm tracking-wider transition-all duration-300 placeholder:text-white/15 hover:border-white/[0.12]"
                                        disabled={loading}
                                    />
                                    <div className="absolute inset-0 rounded-xl opacity-0 group-focus-within:opacity-100 transition-opacity duration-500 pointer-events-none bg-gradient-to-r from-indigo-500/[0.03] to-violet-500/[0.03]" />
                                </div>
                            </div>

                            {/* Strength Meter */}
                            <PasswordStrengthMeter password={password} />

                            {/* Error */}
                            {(isError || localError) && (
                                <div
                                    className="flex items-center gap-3 text-[11px] font-medium p-3.5 bg-red-500/[0.06] border border-red-500/15 text-red-400/80 rounded-xl"
                                    style={{ animation: 'alertIn 0.3s ease-out' }}
                                >
                                    <AlertCircle className="w-4 h-4 shrink-0 text-red-400" />
                                    <span>{localError || (typeof isError === 'string' ? isError : 'An error occurred')}</span>
                                </div>
                            )}

                            {/* Submit */}
                            <button
                                type="submit"
                                disabled={loading || !isPasswordStrong}
                                className="w-full h-13 bg-gradient-to-r from-indigo-600 to-violet-600 hover:from-indigo-500 hover:to-violet-500 text-white rounded-xl font-bold text-sm flex items-center justify-center gap-2.5 active:scale-[0.98] transition-all duration-200 disabled:opacity-30 disabled:cursor-not-allowed shadow-lg shadow-indigo-600/20 group"
                            >
                                {loading ? (
                                    <Loader2 className="w-4 h-4 animate-spin" />
                                ) : (
                                    <>Set New Password <ArrowRight className="w-3.5 h-3.5 group-hover:translate-x-0.5 transition-transform" /></>
                                )}
                            </button>

                            {/* Footer */}
                            <div className="pt-5 border-t border-white/[0.04] flex items-center justify-center gap-3">
                                <div className="flex -space-x-1">
                                    {[1,2,3].map(i => (
                                        <div key={i} className="w-4 h-4 rounded-full bg-white/[0.04] border border-white/[0.06]" />
                                    ))}
                                </div>
                                <span className="text-[9px] font-bold uppercase tracking-[0.25em] text-white/12">Enterprise Encryption</span>
                            </div>
                        </form>
                    )}
                </div>

                <p className="mt-6 text-center text-white/10 font-bold text-[10px] uppercase tracking-[0.3em] flex items-center justify-center gap-2">
                    <ShieldCheck className="w-3.5 h-3.5" /> Secure Transmission
                </p>
            </motion.div>

            <style>{`
                @keyframes progressBar {
                    from { width: 0%; }
                    to { width: 100%; }
                }
                @keyframes alertIn {
                    from { opacity: 0; transform: translateY(-6px) scale(0.97); }
                    to { opacity: 1; transform: translateY(0) scale(1); }
                }
            `}</style>
        </div>
    );
};

