import { createSlice, createAsyncThunk, PayloadAction } from '@reduxjs/toolkit';
import api from "@/shared/api/api";

const API_URL = "/reports";

// Get token from state
const getConfig = (token: string) => ({
  headers: {
    Authorization: `Bearer ${token}`,
  },
});

interface ReportsState {
  salesReport: any | null; // Define specific Report types if/when available
  stockReport: any | null;
  customerReport: any | null;
  dashboardStats: any | null;
  isLoading: boolean;
  isSuccess: boolean;
  isError: boolean;
  message: string | any;
}

const initialState: ReportsState = {
  salesReport: null,
  stockReport: null,
  customerReport: null,
  dashboardStats: null,
  isLoading: false,
  isSuccess: false,
  isError: false,
  message: '',
};

// Get sales report
export const getSalesReport = createAsyncThunk(
  'reports/getSales',
  async (_, thunkAPI) => {
    try {
      const state = thunkAPI.getState() as any;
      const token = state.auth.user?.token;
      if (!token) return thunkAPI.rejectWithValue("Not authenticated");
      const response = await api.get(`${API_URL}/sales`, getConfig(token));
      return response.data;
    } catch (error: any) {
      const message =
        (error.response && error.response.data && error.response.data.message) ||
        error.message ||
        error.toString();
      return thunkAPI.rejectWithValue(message);
    }
  }
);

