export const reportsSlice = createSlice({
  name: 'reports',
  initialState,
  reducers: {
    reset: (state) => {
      state.isLoading = false;
      state.isSuccess = false;
      state.isError = false;
      state.message = '';
    },
  },
  extraReducers: (builder) => {
    builder
      // Get sales report
      .addCase(getSalesReport.pending, (state) => {
        state.isLoading = true;
      })
      .addCase(getSalesReport.fulfilled, (state, action: PayloadAction<any>) => {
        state.isLoading = false;
        state.isSuccess = true;
        state.salesReport = action.payload;
      })
      .addCase(getSalesReport.rejected, (state, action) => {
        state.isLoading = false;
        state.isError = true;
        state.message = action.payload;
      })
      // Get stock report
      .addCase(getStockReport.pending, (state) => {
        state.isLoading = true;
      })
      .addCase(getStockReport.fulfilled, (state, action: PayloadAction<any>) => {
        state.isLoading = false;
        state.isSuccess = true;
        state.stockReport = action.payload;
      })
      .addCase(getStockReport.rejected, (state, action) => {
        state.isLoading = false;
        state.isError = true;
        state.message = action.payload;
      })
      // Get customer report
      .addCase(getCustomerReport.pending, (state) => {
        state.isLoading = true;
      })
      .addCase(getCustomerReport.fulfilled, (state, action: PayloadAction<any>) => {
        state.isLoading = false;
        state.isSuccess = true;
        state.customerReport = action.payload;
      })
      .addCase(getCustomerReport.rejected, (state, action) => {
        state.isLoading = false;
        state.isError = true;
        state.message = action.payload;
      })
      // Get dashboard stats
      .addCase(getDashboardStats.pending, (state) => {
        state.isLoading = true;
      })
      .addCase(getDashboardStats.fulfilled, (state, action: PayloadAction<any>) => {
        state.isLoading = false;
        state.isSuccess = true;
        state.dashboardStats = action.payload;
      })
      .addCase(getDashboardStats.rejected, (state, action) => {
        state.isLoading = false;
        state.isError = true;
        state.message = action.payload;
      });
  },
});

export const { reset } = reportsSlice.actions;
export default reportsSlice.reducer;

import { logger } from '@/shared/lib/logger';
import { db } from '@/shared/lib/db';
import api from '@/shared/api/api';
import { store } from "@/app/store/store";
import { setDailyRecordSynced } from "@/entities/finance/model/financeSlice";
import { SyncIntelligenceService } from '@/features/ai-intelligence/lib/SyncIntelligenceService';

export class SyncManager {
    private static isSyncingSelection = false;
    private static isSyncing = false;
    private static isSyncingDF = false;

    static async syncOfflineSales() {
        if (this.isSyncing || !navigator.onLine) return;
        this.isSyncing = true;

        try {
            const pendingSales = await db.offlineSales
                .where('synced')
                .equals(0) // false
                .toArray();

            for (const sale of pendingSales) {
                try {
                    // Optimized: Sync the entire sale and its inventory impact in one atomic transaction
                    // Replaced Supabase RPC with API call
                    const { data } = await api.post('/sales-invoice/sync', {
                        sale_json: sale
                    });

                    // Assuming API returns success
                    await db.offlineSales.update(sale.localId!, { synced: true });
                    logger.info(`Synced sale: ${sale.id}`);

                    // Log to Sync Intelligence Ledger
                    await SyncIntelligenceService.logEvent({
                        deviceId: 'LOCAL_POS', // In real system, get actual device ID
                        branchId: sale.branchId || 'UNKNOWN',
                        eventType: 'SALE',
                        entityId: sale.id!,
                        entityType: 'Invoice',
                        status: 'SYNCED',
                        payload: { total: sale.total, itemsCount: sale.items?.length }
                    });

                } catch (err) {
                    logger.error(`Failed to sync sale ${sale.id}:`, err);
                    // Update retry count if needed
                }
            }
        } finally {
            this.isSyncing = false;
        }
    }

    static async cacheProducts(products: any[]) {
        try {
            await db.products.bulkPut(products);
            await db.syncMetadata.put({ key: 'products_last_sync', lastSynced: new Date().toISOString() });
        } catch (err) {
            logger.error('Failed to cache products:', err);
        }
    }

    static async cacheCustomers(customers: any[]) {
        try {
            await db.customers.bulkPut(customers);
            await db.syncMetadata.put({ key: 'customers_last_sync', lastSynced: new Date().toISOString() });
        } catch (err) {
            logger.error('Failed to cache customers:', err);
        }
    }

    static async getOfflineProducts(tenantId: string) {
        if (!tenantId) return [];
        return await db.products
            .where('tenantId')
            .equals(tenantId)
            .toArray();
    }

    static async getOfflineCustomers(tenantId: string) {
        if (!tenantId) return [];
        return await db.customers
            .where('tenantId')
            .equals(tenantId)
            .toArray();
    }

    static async syncDailyFinanceEntries() {
        if (this.isSyncingDF || !navigator.onLine) return;
        this.isSyncingDF = true;

        try {
            const pending = await db.dailyFinanceQueue
                .where('synced')
                .equals(0)
                .toArray();

            for (const item of pending) {
                try {
                    const { recordId, operation, data } = item;

                    // Use API instead of Supabase
                    // Assuming generic sync endpoint or mapped endpoints
                    const endpoint = '/finance/sync'; // Placeholder
                    await api.post(endpoint, {
                        recordId,
                        operation,
                        data,
                        tenant_id: data.tenant_id
                    });

                    await db.dailyFinanceQueue.update(item.localId!, { synced: true });
                    logger.info(`Synced ${operation} for ${recordId}`);

                    // Update Redux state
                    if (operation !== 'DELETE') {
                        store.dispatch(setDailyRecordSynced({ id: recordId, synced: true }));
                    }

                    // Log to Sync Intelligence Ledger
                    await SyncIntelligenceService.logEvent({
                        deviceId: 'LOCAL_POS',
                        branchId: data.branch_id || 'UNKNOWN',
                        eventType: operation === 'INSERT' ? 'PAYMENT' : 'STOCK_ADJUST',
                        entityId: recordId,
                        entityType: 'DailyFinance',
                        status: 'SYNCED',
                        payload: { operation }
                    });

                } catch (err: any) {
                    logger.error(`Unexpected sync error for item ${item.recordId}:`, err);
                    await db.dailyFinanceQueue.update(item.localId!, {
                        error: err.message,
                        retryCount: (item.retryCount || 0) + 1
                    });
                }
            }
        } finally {
            this.isSyncingDF = false;
        }
    }
}

import { useState } from 'react';
import { useSelector } from 'react-redux';
import { RootState } from '@/app/store/store';
import { useTenantData } from '@/features/tenant-onboarding/lib/useTenantData';
import { useProductSync } from './useProductSync';
import { useFinanceSync } from './useFinanceSync';
import { useSalesSync } from './useSalesSync';
import { usePurchaseSync } from './usePurchaseSync';
// import { useHRData } from './useHRData'; // File is missing in whole codebase
import { useVisualPreferences } from '@/features/tenant-onboarding/lib/useVisualPreferences';

/**
 * Orchestrator Hook for MongoDB/REST data synchronization.
 * Splits logic into domain-specific hooks for better maintainability and performance.
 */
export const useDBDataSync = () => {
    const { user } = useSelector((state: RootState) => state.auth);
    // Ensure tenantId is a string, even if user object has full tenant populated
    const tenantId = user?.tenantId && typeof user.tenantId === 'object'
        ? (user.tenantId as any)._id
        : user?.tenantId;

    const [loading] = useState(false);
    const [error] = useState<string | null>(null);

    // 1. Fetch Tenant & Branch Master Data (Requires user ID for session repair)
    useTenantData(user);

    // 2. Domain-specific sync hooks (Only run when tenantId is available)
    useProductSync(tenantId);
    useSalesSync(tenantId);
    useFinanceSync(tenantId);
    // useHRData(tenantId);
    usePurchaseSync(tenantId);
    useVisualPreferences(tenantId, user?.id);

    return { loading, error };
};

import { useEffect } from 'react';
import { useDispatch } from 'react-redux';
import { useQuery } from '@tanstack/react-query';
import { setTransactions, setCheques, setDailyRecords } from '@/entities/finance/model/financeSlice';
import { Transaction, Cheque } from "@repo/shared"; // Check shared-kernel for finance types
import { SyncManager } from "./SyncManager";
import { fetchTransactionsRaw, fetchChequesRaw, fetchDailyFinanceRaw } from './financeQueries';

export const useFinanceSync = (tenantId: string | undefined) => {
    const dispatch = useDispatch();

    // 1. Transactions Query
    const { data: rawTx } = useQuery({
        queryKey: ['transactions', tenantId],
        queryFn: () => fetchTransactionsRaw(tenantId!),
        enabled: !!tenantId,
        refetchInterval: 30000 // Polling every 30s
    });

    // 2. Cheques Query
    const { data: rawCheques } = useQuery({
        queryKey: ['cheques', tenantId],
        queryFn: () => fetchChequesRaw(tenantId!),
        enabled: !!tenantId,
        refetchInterval: 30000
    });

    // 3. Daily Finance Query
    const { data: rawDF } = useQuery({
        queryKey: ['daily_finance', tenantId],
        queryFn: () => fetchDailyFinanceRaw(tenantId!),
        enabled: !!tenantId,
        refetchInterval: 30000
    });

    // 4. Sync to Redux (Bridge)
    useEffect(() => {
        if (!rawTx) return;
        const mappedTx = rawTx.map((t: any) => ({
            id: t.id,
            type: t.type,
            category: t.category,
            amount: t.amount,
            date: t.date,
            description: t.description,
            sector: t.sector,
            branchId: t.branch_id,
            tenantId: t.tenant_id
        })) as Transaction[];
        dispatch(setTransactions(mappedTx));
    }, [rawTx, dispatch]);

    useEffect(() => {
        if (!rawCheques) return;
        const mappedCheques = rawCheques.map((c: any) => ({
            id: c.id,
            number: c.number,
            bankName: c.bank_name,
            payee: c.payee,
            amount: c.amount,
            date: c.date,
            status: c.status,
            type: c.type,
            sector: c.sector,
            tenantId: c.tenant_id
        })) as Cheque[];
        dispatch(setCheques(mappedCheques));
    }, [rawCheques, dispatch]);

    useEffect(() => {
        if (!rawDF) return;
        const mappedDF = rawDF.map((df: any) => ({
            id: df.id,
            date: df.date,
            cashSales: df.cash_sales,
            onlineSales: df.online_sales,
            totalSales: df.total_sales,
            expenses: df.expenses,
            cashInDrawer: df.cash_in_drawer,
            notes: df.notes,
            timestamp: df.timestamp,
            tenantId: df.tenant_id
        }));
        dispatch(setDailyRecords(mappedDF));
    }, [rawDF, dispatch]);

    // 5. Background Sync Manager Trigger
    useEffect(() => {
        if (!tenantId) return;
        const syncInterval = setInterval(() => {
            if (navigator.onLine) {
                SyncManager.syncDailyFinanceEntries();
            }
        }, 60000); // Background sync every minute
        return () => clearInterval(syncInterval);
    }, [tenantId]);
};

import { logger } from '@/shared/lib/logger';
import { useEffect } from 'react';
import { useDispatch } from 'react-redux';
// import { supabase } from '../lib/supabase'; // Removed
import { setProducts, setCategories, setHydrating } from '@/entities/inventory/model/inventorySlice';
import { Product } from "@repo/shared"; 
import { SyncManager } from "./SyncManager";
import { getTable } from "@/shared/api/dataSource";
import { useUiStore } from '@/shared/lib/store/uiStore';

export const useProductSync = (tenantId: string | undefined) => {
    const dispatch = useDispatch();

    useEffect(() => {
        if (!tenantId) return;

        const fetchProducts = async () => {
            const setSyncStatus = useUiStore.getState().setSyncing;
        setSyncStatus(true);
            try {
                // 1. Immediate Hydration (SWR) - only if DB mode
                const cached = await SyncManager.getOfflineProducts(tenantId);
                if (cached && cached.length > 0) {
                    dispatch(setProducts(cached));
                }

                // 2. Parallelized Background Fetch (Switches between DEMO/DB)
                const [prodData, catData] = await Promise.all([
                    getTable('products', { filters: { tenant_id: tenantId } }),
                    getTable('cloth_product_master', { filters: { tenant_id: tenantId } })
                ]);

                // 3. Process Products
                if (prodData) {
                    const mappedProducts = prodData.map((p: any) => ({
                        id: p.id,
                        sku: p.sku,
                        name: p.name,
                        nameTamil: p.nameTamil || p.pNameTamil || p.name_tamil,
                        category: p.category || 'General',
                        subCategory: p.subCategory || p.sub_category,
                        sellingPrice: p.sellingPrice ?? p.price ?? p.selling_price ?? 0,
                        mrp: p.mrp,
                        costPrice: p.costPrice ?? p.cost ?? 0,
                        stockQty: p.stockQty ?? p.stock ?? 0,
                        sector: p.sector,
                        branchId: p.branchId || p.branch_id,
                        productType: p.productType || p.product_type || 'General',
                        barcode: p.barcode,
                        brand: p.brand,
                        hsnCode: p.hsnCode || p.hsn_code,
                        gstPercentage: p.gstPercentage || p.gst_percentage || p.gst_rate || 18,
                        unit: p.unit || 'Piece',
                        tenantId: p.tenantId || p.tenant_id,
                        image: p.image,
                        description: p.description,
                        discount: p.discount || 0
                    })) as Product[];
                    dispatch(setProducts(mappedProducts));
                    SyncManager.cacheProducts(mappedProducts);
                }

                // 4. Process Categories
                if (catData) {
                    const uniqueCategories = Array.from(new Set(catData.map((c: any) => c.product_name || c.category).filter(Boolean)));
                    dispatch(setCategories(uniqueCategories as string[]));
                }
            } catch (err) {
                logger.error("Failed to sync products:", err);
            } finally {
                dispatch(setHydrating(false));
                const setSyncStatus = useUiStore.getState().setSyncing;
            setSyncStatus(false);
            }
        };

        fetchProducts();

        return () => {
            // Cleanup
        };
    }, [dispatch, tenantId]);
};

